window.SEMIPRIME_SOURCES={"RiemannGaussian.SemiprimeCachedSourceScheduledExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeCachedSourcePublicExecution\nimport RiemannGaussian.SemiprimeScheduledFactorExecution\n\n/-!\n# Natural-input materialized factoring execution\n\nThe only runtime input is N. The original computed schedule and literal decidable\nguard select the new materialized public count/search; the same complete finite\ntrial fallback handles the complementary branch. No source array, design,\ncoefficient, local table, count answer or externally chosen parameter is supplied.\nThis is a semantic execution join, not a new whole primitive-bit clock theorem.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeCachedSourceScheduledExecution\nopen scoped BigOperators\nopen Filter SemiprimePublicAcquiredExecution\nopen SemiprimeScheduledFactorExecution\n\n/-- Entire deterministic N-only algorithm, with the new materialized counter on\nits automatically chosen fast branch and the old finite complete fallback. -/\ndef run (N : ℕ) : Option ℕ :=\n  if hN : 0<N then\n    if hr : 0<groups N then\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      if fastGuard N then\n        SemiprimeCachedSourcePublicExecution.factor N hN (groups N) (points N)\n          (epsilon N) (degree N) (precision N)\n      else trialFactor N\n    else trialFactor N\n  else none\n\n/-- Exact output equivalence on EVERY natural input, not only promised semiprimes.\nThe two algorithms can have different operation traces and work reports. -/\ntheorem run_eq_old (N : ℕ) : run N=SemiprimeScheduledFactorExecution.run N := by\n  by_cases hN : 0<N\n  · by_cases hr : 0<groups N\n    · let _ : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      by_cases hg : fastGuard N\n      · have hQ : 1≤points N := Nat.le_trans (by decide : 1≤2) hg.2.2.2.1\n        have hAQ := guard_interval N hg\n        have hp := precision_valid N hN (guard_points_pos N hg)\n        have he := SemiprimeCachedSourcePublicExecution.factor_eq_old N hN (groups N) (points N)\n          (epsilon N) (degree N) (precision N) hQ hAQ hp.1 hp.2\n        simpa only [run,SemiprimeScheduledFactorExecution.run,dite_eq_left hN,\n          dite_eq_left hr,ite_eq_left hg] using he\n      · simp only [run,SemiprimeScheduledFactorExecution.run,dite_eq_left hN,\n          dite_eq_left hr,ite_eq_right hg]\n    · simp only [run,SemiprimeScheduledFactorExecution.run,dite_eq_left hN,dite_eq_right hr]\n  · simp only [run,SemiprimeScheduledFactorExecution.run,dite_eq_right hN]\n\n/-- Every actual returned integer is a proper divisor of the original input. -/\ntheorem run_sound (N p : ℕ) (h : run N=some p) : 2≤p ∧ p<N ∧ p∣N :=\n  SemiprimeScheduledFactorExecution.run_sound N p ((run_eq_old N).symm.trans h)\n\n/-- Complete failure characterization for all naturals, including zero, one,\nprimes, and perfect squares. -/\ntheorem run_none_iff (N : ℕ) :\n    run N=none ↔ ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [run_eq_old]\n  exact SemiprimeScheduledFactorExecution.run_none_iff N\n\n/-- The literal guard eventually passes, so the runtime actually uses the new\npaid cached-source counter rather than the finite fallback. -/\ntheorem eventually_run_materialized : ∀ᶠ N : ℕ in atTop,\n    ∃ hN : 0<N, ∃ hg : fastGuard N,\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt (guard_groups_pos N hg)⟩\n      run N=SemiprimeCachedSourcePublicExecution.factor N hN (groups N) (points N)\n        (epsilon N) (degree N) (precision N) := by\n  filter_upwards [eventually_fastGuard,eventually_gt_atTop 0] with N hg hN\n  exact ⟨hN,hg,by simp only [run,dite_eq_left hN,dite_eq_left (guard_groups_pos N hg),ite_eq_left hg]⟩\n\nend RiemannGaussian.SemiprimeCachedSourceScheduledExecution\n","RiemannGaussian.SemiprimeD1AffineCoefficientBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1AffineCoefficient\n\n/-! # Original-data work bound for requested affine-product coefficients\nGeneric ring operations and native tuple/list work are counted separately by\nthe producer; their sum is bounded without an advised coefficient/clock oracle.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1AffineCoefficientBounds\nopen SemiprimeD1AffineCoefficient\n\n/-- Every cached scalar read scans at most the original list once. -/\ntheorem read_work {R : Type*} (default : R) (vs : List R) (i : ℕ) :\n    (read default vs i).2 ≤ 3*vs.length+1 := by\n  induction vs generalizing i with\n  | nil => simp [SemiprimeD1AffineCoefficient.read]\n  | cons v vs ih =>\n    cases i with\n    | zero => simp only [SemiprimeD1AffineCoefficient.read,List.length_cons];omega\n    | succ i => have h:=ih i;simp only [SemiprimeD1AffineCoefficient.read,List.length_cons];omega\n\n/-- Full acquired tuple copies have literal linear work. -/\ntheorem copyTuple_work (beta : List ℕ) : (copyTuple beta).2=3*beta.length+1 := by\n  induction beta with\n  | nil => rfl\n  | cons b bs ih => simp only [copyTuple,List.length_cons,ih];omega\n\n/-- Every actual tuple-decrement path and copied suffix is paid. -/\ntheorem decrement_work (beta : List ℕ) (i : ℕ) : (decrement beta i).2 ≤ 3*beta.length+2 := by\n  induction beta generalizing i with\n  | nil => simp [decrement]\n  | cons b bs ih =>\n    cases i with\n    | zero => simp only [decrement,copyTuple_work,List.length_cons];omega\n    | succ i => have h:=ih i;simp only [decrement,List.length_cons];omega\n\n/-- Terminal all-zero check pays each original tuple cell exactly once. -/\ntheorem zeroTest_work (beta : List ℕ) : (zeroTest beta).2=3*beta.length+1 := by\n  induction beta with\n  | nil => rfl\n  | cons b bs ih => simp only [zeroTest,List.length_cons,ih];omega\n\n/-- Actual branch accumulation retains each acquired report and one ring addition. -/\ntheorem sumRuns_work {R : Type*} [AddMonoid R] (rs : List (Run R)) :\n    (sumRuns rs).work=(rs.map Run.work).sum+4*rs.length+1 := by\n  induction rs with\n  | nil => rfl\n  | cons r rs ih =>\n    change r.ringOps+(sumRuns rs).ringOps+1+(r.control+(sumRuns rs).control+3)=_\n    have he : r.ringOps+(sumRuns rs).ringOps+1+(r.control+(sumRuns rs).control+3)=\n        r.work+(sumRuns rs).work+4 := by unfold Run.work;ring\n    rw [he,ih]\n    simp only [List.map_cons,List.sum_cons,List.length_cons]\n    omega\n\n/-- Literal bounded sum of cached branch reports. -/\ntheorem map_work_le {R : Type*} (indices : List ℕ) (f : ℕ→Run R) (B : ℕ)\n    (h : ∀i∈indices,(f i).work ≤ B) :\n    (indices.map (fun i => (f i).work)).sum ≤ indices.length*B := by\n  induction indices with\n  | nil => simp\n  | cons i indices ih =>\n    have hh:=h i List.mem_cons_self\n    have ht:=ih (fun j hj => h j (List.mem_cons_of_mem i hj))\n    simp only [List.map_cons,List.sum_cons,List.length_cons]\n    nlinarith\n\n/-- Fixed polynomial overhead before branching, from actual source dimensions. -/\ndef stageConstant (K tupleLength rowWidth : ℕ) : ℕ :=\n  (K+1)*(6*tupleLength+3*rowWidth+24)+11\n\n/-- One actual row's recursive branches cost at mostK+1 acquired subcalls plus\na fixed original-dimension overhead. The final theorem discharges all subcalls. -/\ntheorem evaluate_step_le {R : Type*} [CommRing R] (K : ℕ) (row : Row R)\n    (rows : List (Row R)) (beta : List ℕ) (A B : ℕ)\n    (hrow : row.coefficients.length ≤ A)\n    (hchild : ∀target : List ℕ,target.length=beta.length→(evaluate K rows target).work ≤ B) :\n    (evaluate K (row::rows) beta).work ≤ (K+1)*B+stageConstant K beta.length A := by\n  let branch (i : ℕ) : Run R :=\n    let exponent:=read 0 beta i\n    if exponent.1=0 then ⟨0,0,exponent.2+3⟩\n    else\n      let target:=decrement beta i\n      let child:=evaluate K rows target.1\n      let coeff:=read 0 row.coefficients i\n      ⟨coeff.1*child.value,child.ringOps+1,\n        exponent.2+target.2+child.control+coeff.2+5⟩\n  have hbranch (i : ℕ) : (branch i).work ≤ B+6*beta.length+3*A+10 := by\n    have he:=read_work 0 beta i\n    have ht:=decrement_work beta i\n    have hc:=read_work (0:R) row.coefficients i\n    have hh:=hchild (decrement beta i).1 (decrement_length beta i)\n    unfold Run.work at hh\n    unfold branch Run.work\n    dsimp only\n    split_ifs <;> dsimp only <;> omega\n  have hs:=map_work_le (List.range K) branch (B+6*beta.length+3*A+10) (fun i _=>hbranch i)\n  simp only [List.length_range] at hs\n  have hsum := sumRuns_work ((List.range K).map branch)\n  simp only [List.map_map,Function.comp_def,List.length_map,List.length_range] at hsum\n  have hbase:=hchild beta rfl\n  have heq : (evaluate K (row::rows) beta).work=\n      (evaluate K rows beta).work+(sumRuns ((List.range K).map branch)).work+10*K+10 := by\n    change ((evaluate K rows beta).ringOps+(sumRuns ((List.range K).map branch)).ringOps+2)+\n      ((evaluate K rows beta).control+(sumRuns ((List.range K).map branch)).control+10*K+8)=_\n    unfold Run.work\n    ring\n  rw [heq]\n  unfold stageConstant\n  rw [hsum]\n  nlinarith\n\n/-- Exact closed original-data upper bound, with no output/fit/work advice. -/\ndef budget (K L tupleLength rowWidth : ℕ) : ℕ :=\n  (L+1)*stageConstant K tupleLength rowWidth*(K+1)^L\n\n/-- Pure scalar recursion balance, independent of all executable projections. -/\ntheorem recursion_budget (K L C : ℕ) :\n    (K+1)*((L+1)*C*(K+1)^L)+C ≤ (L+2)*C*(K+1)^(L+1) := by\n  have hp : 1 ≤ (K+1)^(L+1) := Nat.one_le_pow _ _ (by omega)\n  have hc:=Nat.mul_le_mul_left C hp\n  calc\n    _ ≤ (K+1)*((L+1)*C*(K+1)^L)+C*(K+1)^(L+1) := by omega\n    _ = _ := by rw [pow_succ];ring\n\n/-- Actual requested-coefficient acquisition is bounded bypoly(K,L)*(K+1)^L.\nAll recursive tuple shapes and every branch callback are discharged internally. -/\ntheorem evaluate_work {R : Type*} [CommRing R] (K : ℕ) (rows : List (Row R))\n    (beta : List ℕ) (A : ℕ) (hrows : ∀row∈rows,row.coefficients.length ≤ A) :\n    (evaluate K rows beta).work ≤ budget K rows.length beta.length A := by\n  induction rows generalizing beta with\n  | nil =>\n    have hz:=zeroTest_work beta\n    change 0+((zeroTest beta).2+2) ≤ _\n    simp only [Nat.zero_add]\n    unfold budget stageConstant\n    simp only [List.length_nil,Nat.zero_add,pow_zero,Nat.mul_one,Nat.one_mul]\n    have hm : 6*beta.length+3*A+24 ≤ (K+1)*(6*beta.length+3*A+24) :=\n      Nat.le_mul_of_pos_left _ (Nat.succ_pos K)\n    omega\n  | cons row rows ih =>\n    have hrow:=hrows row List.mem_cons_self\n    have htail : ∀r∈rows,r.coefficients.length ≤ A := fun r hr=>hrows r (List.mem_cons_of_mem row hr)\n    have hstep:=evaluate_step_le K row rows beta A (budget K rows.length beta.length A) hrow (by\n      intro target hlen\n      have h:=ih target htail\n      simpa only [hlen] using h)\n    have hrec:=recursion_budget K rows.length (stageConstant K beta.length A)\n    unfold budget at hstep ⊢\n    simp only [List.length_cons]\n    exact hstep.trans hrec\n\n/-- Original finite-mode data and acquired tuple shape specialize the bound to\npoly(K,L)*(K+1)^L, with no coefficient value or subcall-work premise. -/\ntheorem evaluate_work_modes {R : Type*} [CommRing R] (K : ℕ) (rows : List (Row R))\n    (beta : List ℕ) (hbeta : beta.length=K)\n    (hrows : ∀row∈rows,row.coefficients.length ≤ K) :\n    (evaluate K rows beta).work ≤\n      (rows.length+1)*stageConstant K K K*(K+1)^rows.length := by\n  simpa only [budget,hbeta] using evaluate_work K rows beta K hrows\n\nend RiemannGaussian.SemiprimeD1AffineCoefficientBounds\n","RiemannGaussian.SemiprimeD1BoundaryNetworkDegree":"import RiemannGaussian.SemiprimeD1BoundaryLeafLoad\nimport RiemannGaussian.SemiprimeD1BoundaryPartitionRate\nimport RiemannGaussian.SemiprimeD1TensorNetworkRecursion\n\n/-! Literal stored-port degree bounds control the acquired endpoint graph. -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryNetworkDegree\nopen SemiprimeD1BoundaryPlan\nopen SemiprimeD1BoundaryLeafPorts\nopen SemiprimeD1BoundaryRefinement\n\ntheorem degree_le_ports (net : SemiprimeD1TensorNetwork.Network)\n    (hw : SemiprimeD1TensorNetwork.WellFormed net) (v : Nat)\n    (hv : v < (SemiprimeD1TensorNetwork.vertices net).length) :\n    degree (graph net) v ≤ ((SemiprimeD1TensorNetwork.vertices net)[v]).ports.length := by\n  let selected := selectedIndices (graph net).edges (fun x => x.1.1 == v || x.1.2 == v)\n  have hlen : selected.length = degree (graph net) v :=\n    SemiprimeD1BoundaryLeafLoad.selected_length (graph net).edges\n      (fun e => e.1 == v || e.2 == v)\n  rw [←hlen]\n  apply (selectedIndices_nodup _ _).length_le_of_subset\n  intro p hp\n  have hpb := selectedIndices_lt _ _ p hp\n  have hbound : p < SemiprimeD1TensorNetwork.edgeCount net := by\n    simpa only [graph_edges_length] using hpb\n  let e : Fin (SemiprimeD1TensorNetwork.edgeCount net) := ⟨p,hbound⟩\n  have hpred := (selectedIndices_mem (graph net).edges _ p hpb).mp hp\n  have he : (graph net).edges[p]'hpb = ((networkGraph net).left e,(networkGraph net).right e) :=\n    networkEndpoints_get net e\n  rw [he] at hpred\n  apply (edge_mem_vertex_ports net hw v hv e).mpr\n  simpa only [Bool.or_eq_true,beq_iff_eq] using hpred\n\n/-- The actual acquired maximum degree inherits the original stored-port cap. -/\ntheorem maxDegree_le (net : SemiprimeD1TensorNetwork.Network)\n    (hw : SemiprimeD1TensorNetwork.WellFormed net) (d : Nat)\n    (hd : SemiprimeD1TensorNetworkRecursion.DegreeBound net d) : maxDegree (graph net) ≤ d := by\n  apply SemiprimeD1BoundaryPartitionRate.foldl_max_le _ 0 d (Nat.zero_le _)\n  intro x hx\n  obtain ⟨v,hv,rfl⟩ := List.mem_map.mp hx\n  have hvi : v < (SemiprimeD1TensorNetwork.vertices net).length := List.mem_range.mp hv\n  exact (degree_le_ports net hw v hvi).trans (hd _ (List.getElem_mem hvi))\n\nend RiemannGaussian.SemiprimeD1BoundaryNetworkDegree\n","RiemannGaussian.SemiprimeD1ChildPortPullback":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildActivationOriginal\n\n/-! # Executed cached original-port pullback for physical group children\nThe original edge-ID bank is acquired from retained original typed ports and\nactual placements. Every child endpoint performs a literal physical ID lookup.\nNo desired permutation, Word getter, or tensor truth callback is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2600000\nnamespace RiemannGaussian.SemiprimeD1ChildPortPullback\nopen SemiprimeMaterializedWords SemiprimeD1ChildGraph SemiprimeD1PacketInventory\n\n/-- Acquire the original occurrence-ID bank by physically copying each actual ID. -/\ndef bank {I : Type*} : List (I×Placement)→Run (List (List Bool×I))\n  | [] => ⟨[],2⟩\n  | (i,p)::ps =>\n    let id := SemiprimeSourceCompactBits.copy p.edge\n    let tail := bank ps\n    ⟨(id.bits,i)::tail.value,id.clock+tail.work+6⟩\n\n/-- Literal bank content from original acquired occurrences, without an ID oracle. -/\ntheorem bank_value {I : Type*} (ps : List (I×Placement)) :\n    (bank ps).value=ps.map (fun p => (p.2.edge,p.1)) := by\n  induction ps with\n  | nil => rfl\n  | cons p ps ih => simp only [bank,ih,SemiprimeSourceCompactBits.copy_bits,List.map_cons]\n\n/-- Linear physical lookup; arbitrary padding aliases are not conflated. -/\ndef findPort {I : Type*} (target : List Bool) : List (List Bool×I)→Run (Option I)\n  | [] => ⟨none,2⟩\n  | (id,i)::rest =>\n    let same := equalBytes id target\n    if same.value then ⟨some i,same.work+4⟩\n    else\n      let tail := findPort target rest\n      ⟨tail.value,same.work+tail.work+6⟩\n\n/-- Acquire one original-port/side link for every actual child incidence. -/\ndef pull {I : Type*} {V : ℕ} (ids : List (List Bool×I)) :\n    List (Endpoint V)→Run (List (Option (I×Bool)))\n  | [] => ⟨[],2⟩\n  | e::es =>\n    let here := findPort e.edge ids\n    let tail := pull ids es\n    ⟨(here.value.map (fun i => (i,e.side)))::tail.value,here.work+tail.work+5⟩\n\n/-- Exact child factor-major pullback scan; all searches are actually executed. -/\ntheorem pull_value {I : Type*} {V : ℕ} (ids : List (List Bool×I)) (es : List (Endpoint V)) :\n    (pull ids es).value=es.map (fun e => (findPort e.edge ids).value.map (fun i => (i,e.side))) := by\n  induction es with\n  | nil => rfl\n  | cons e es ih => simp only [pull,ih,List.map_cons]\n\n/-- Whole prepared group data, retaining source, graph, activation and computed links. -/\nstructure Acquired (n F a : ℕ) (inputArity : Fin F→ℕ) where\n  /-- Once-produced parent source, also needed for isolated old-vertex activation. -/\n  source : SemiprimeD1PacketReplayOriginal.Acquired n F a inputArity\n  /-- Actual cached group child graph. -/\n  graph : Graph (n+F)\n  /-- Actual activation bits for every old vertex. -/\n  activation : SemiprimeSourceCompactBits.Report\n  /-- Actual physically copied original ID/native-port bank. -/\n  ids : List (List Bool×((e : Fin F)×Fin (inputArity e)))\n  /-- Actually computed original-port/side links in child factor-major order. -/\n  links : List (Option (((e : Fin F)×Fin (inputArity e))×Bool))\n  /-- Shared source once, actual graph/mask locals, bank and lookup reports. -/\n  work : ℕ\n\n/-- Conservative native list/zip/flatten metadata traversal allowance.\nThis is not a binary-address machine clock. -/\ndef metadataAllowance {n F a : ℕ} {inputArity : Fin F→ℕ}\n    (source : SemiprimeD1PacketReplayOriginal.Acquired n F a inputArity) (graph : Graph (n+F)) : ℕ :=\n  10*(source.padding.source.selection.cache.data.metadata.incidences.length+\n    source.placements.length+graph.factors.length+graph.endpoints.length+1)\n\n/-- Reuse original source once; independently execute each physical producer once. -/\ndef fromReplay {n F a r : ℕ} {inputArity : Fin F→ℕ}\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (source : SemiprimeD1PacketReplayOriginal.Acquired n F a inputArity) (q : Fin a) (g : Fin r) :\n    Acquired n F a inputArity :=\n  let graph := SemiprimeD1ChildGraph.fromReplay inputOwner source q g\n  let activation := SemiprimeD1ChildActivation.fromReplay source q g\n  let ids := bank (source.padding.source.selection.cache.data.metadata.incidences.zip source.placements)\n  let links := pull ids.value graph.factors.flatten\n  ⟨source,graph,activation,ids.value,links.value,\n    graph.work+(activation.clock-source.state.clock)+ids.work+links.work+metadataAllowance source graph+20⟩\n\n/-- Original-input prepared child, with no activation or port-permutation advice. -/\ndef acquire (n F r a : ℕ) (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r) :\n    Acquired n F a inputArity :=\n  fromReplay inputOwner (SemiprimeD1PacketReplayOriginal.acquire n F r a inputArity inputOwner) q g\n\n/-- The shared original source report is counted once, not executed twice by a wrapper. -/\ntheorem work_decomposition {n F a r : ℕ} {inputArity : Fin F→ℕ}\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (source : SemiprimeD1PacketReplayOriginal.Acquired n F a inputArity) (q : Fin a) (g : Fin r) :\n    (fromReplay inputOwner source q g).work=\n      source.state.clock+\n      ((SemiprimeD1ChildGraph.fromReplay inputOwner source q g).work-source.state.clock)+\n      ((SemiprimeD1ChildActivation.fromReplay source q g).clock-source.state.clock)+\n      (bank (source.padding.source.selection.cache.data.metadata.incidences.zip source.placements)).work+\n      (pull (fromReplay inputOwner source q g).ids (fromReplay inputOwner source q g).graph.factors.flatten).work+\n      metadataAllowance source (fromReplay inputOwner source q g).graph+20 := by\n  have hg := SemiprimeD1ChildGraph.fromReplay_retains inputOwner source q g\n  unfold fromReplay\n  dsimp only\n  omega\n\nend RiemannGaussian.SemiprimeD1ChildPortPullback\n","RiemannGaussian.SemiprimeD1GridResidue":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1GridValuation\n\n/-! # Exact valuation and finite translation on the original complete residue grid -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1GridResidue\nopen scoped BigOperators\nopen SemiprimeD1GridValuation SemiprimeD1WireKernelFactors\n\n/-- Canonical residue-grid order; zero is always explicitly excluded in applications. -/\ndef order (k : ℕ) (x : ZMod (2^k)) : ℕ := padicValNat 2 x.val\n\n/-- A nonzero canonical residue has nonzero original integer representative. -/\ntheorem val_ne_zero (k : ℕ) (x : ZMod (2^k)) (hx : x≠0) : (x.val:ℤ)≠0 := by\n  have h : x.val≠0 := by intro h;apply hx;exact (ZMod.val_eq_zero x).mp h\n  exact_mod_cast h\n\n/-- Original integer representatives have exactly the stored residue valuation. -/\ntheorem order_val (k : ℕ) (x : ZMod (2^k)) : padicValInt 2 (x.val:ℤ)=order k x := by\n  simp only [padicValInt.of_nat,order]\n\n/-- Every nonzero residue order is below the grid exponent. -/\ntheorem order_lt (k : ℕ) (x : ZMod (2^k)) (hx : x≠0) : order k x<k := by\n  have hn : x.val≠0 := by intro h;apply hx;exact (ZMod.val_eq_zero x).mp h\n  have hp : 2^padicValNat 2 x.val≤x.val := Nat.le_of_dvd (Nat.pos_of_ne_zero hn) pow_padicValNat_dvd\n  exact (Nat.pow_lt_pow_iff_right (by decide : 1<(2:ℕ))).mp (hp.trans_lt x.val_lt)\n\n/-- Distinct residues give a genuine bounded integer difference. -/\ntheorem difference_ne_zero (k : ℕ) (x y : ZMod (2^k)) (hxy : x≠y) :\n    (x.val:ℤ)-(y.val:ℤ)≠0 := by\n  intro h\n  apply hxy\n  apply ZMod.val_injective\n  omega\n\n/-- Original bounded integer difference and canonical residue subtraction have SAME order. -/\ntheorem order_sub (k : ℕ) (x y : ZMod (2^k)) (hxy : x≠y) :\n    order k (x-y)=padicValInt 2 ((x.val:ℤ)-(y.val:ℤ)) := by\n  have hn := difference_ne_zero k x y hxy\n  have hb : ((x.val:ℤ)-(y.val:ℤ)).natAbs<2^k :=\n    difference_abs_lt (2^k) x.val y.val x.val_lt y.val_lt\n  have hmod : (2:ℤ)^k∣((x.val:ℤ)-(y.val:ℤ))-((x-y).val:ℤ) := by\n    have h : ((2^k:ℕ):ℤ)∣((x.val:ℤ)-(y.val:ℤ))-((x-y).val:ℤ) := by\n      apply (ZMod.intCast_zmod_eq_zero_iff_dvd _ (2^k)).mp\n      simp only [Int.cast_sub,Int.cast_natCast,ZMod.natCast_zmod_val,sub_self]\n    simpa only [Nat.cast_pow,Nat.cast_ofNat] using h\n  simpa only [order_val] using (valuation_congruent k _ _ hn (valuation_lt k _ hn hb) hmod).2\n\n/-- Exact nonarchimedean equality for distinct original integer orders. -/\ntheorem int_sub_order_of_lt (x y : ℤ) (hx : x≠0)\n    (h : padicValInt 2 x<padicValInt 2 y) :\n    x-y≠0 ∧ padicValInt 2 (x-y)=padicValInt 2 x := by\n  apply valuation_congruent (padicValInt 2 x+1) x (x-y) hx (by omega)\n  have hd : (2:ℤ)^(padicValInt 2 x+1)∣y :=\n    (padicValInt_dvd_iff (p:=2) _ _).mpr (Or.inr (by omega))\n  convert hd using 1;ring\n\n/-- Residue subtraction orders are the minimum when the original orders differ. -/\ntheorem order_sub_of_ne (k : ℕ) (x y : ZMod (2^k)) (hx : x≠0) (hy : y≠0)\n    (h : order k x≠order k y) : order k (x-y)=min (order k x) (order k y) := by\n  have hxy : x≠y := by intro he;subst y;exact h rfl\n  rw [order_sub k x y hxy]\n  rcases lt_or_gt_of_ne h with hlt|hgt\n  · have h := (int_sub_order_of_lt (x.val:ℤ) (y.val:ℤ) (val_ne_zero k x hx)\n      (by simpa only [order_val] using hlt)).2\n    simpa only [order_val,Nat.min_eq_left hlt.le] using h\n  · have h := (int_sub_order_of_lt (y.val:ℤ) (x.val:ℤ) (val_ne_zero k y hy)\n      (by simpa only [order_val] using hgt)).2\n    have he : (y.val:ℤ)-(x.val:ℤ)=-((x.val:ℤ)-(y.val:ℤ)) := by ring\n    rw [he] at h\n    simp only [padicValInt,Int.natAbs_neg] at h\n    change padicValInt 2 ((x.val:ℤ)-(y.val:ℤ))=padicValInt 2 (y.val:ℤ) at h\n    simpa only [order_val,Nat.min_eq_right hgt.le] using h\n\n/-- The minimum-order lower bound also covers equal orders, without assuming a domain. -/\ntheorem order_sub_lower (k : ℕ) (x y : ZMod (2^k))\n    (hxy : x≠y) : min (order k x) (order k y)≤order k (x-y) := by\n  rw [order_sub k x y hxy]\n  have hdx : (2:ℤ)^min (order k x) (order k y)∣(x.val:ℤ) := by\n    apply (padicValInt_dvd_iff (p:=2) _ _).mpr\n    exact Or.inr (by rw [order_val];exact Nat.min_le_left _ _)\n  have hdy : (2:ℤ)^min (order k x) (order k y)∣(y.val:ℤ) := by\n    apply (padicValInt_dvd_iff (p:=2) _ _).mpr\n    exact Or.inr (by rw [order_val];exact Nat.min_le_right _ _)\n  exact ((padicValInt_dvd_iff (p:=2) _ _).mp (dvd_sub hdx hdy)).resolve_left\n    (difference_ne_zero k x y hxy)\n\n/-- Literal modular translation q↦t-q, with no lookup or cardinality advice. -/\ndef reflect (k : ℕ) (t : ZMod (2^k)) : Equiv.Perm (ZMod (2^k)) := Equiv.subLeft t\n\n/-- Original exclusion of the zero and own node is preserved by reflection. -/\ntheorem reflect_membership (k : ℕ) (t x : ZMod (2^k)) :\n    (x≠0 ∧ x≠t) ↔ (t-x≠0 ∧ t-x≠t) := by\n  constructor\n  · rintro ⟨h0,ht⟩\n    constructor\n    · exact sub_ne_zero.mpr (Ne.symm ht)\n    · intro h;apply h0;linear_combination -h\n  · rintro ⟨h0,ht⟩\n    constructor\n    · intro h;apply ht;rw [h,sub_zero]\n    · intro h;apply h0;rw [h,sub_self]\n\nend RiemannGaussian.SemiprimeD1GridResidue\n","RiemannGaussian.SemiprimeD1HybridCallTree":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1HybridCallBranch\n\n/-! # Whole actual recursion-call envelope at the requested main exponent\nEvery literal grid point, acquired mode and64 child groups is included. The\nfinite inventory is bounded uniformly in fuel; this counts calls, not the\nprimitive work of those calls or their leaf table contractions.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1HybridCallTree\nopen scoped BigOperators\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimeD1RecursiveCallTree SemiprimeD1RecursiveCallInventory\nopen SemiprimeD1HybridCallEnvelope SemiprimeD1HybridCallBranch SemiprimeD1Schedule\n\n/-- Grid and group factors contribute only a fixed quadratic logarithmic exponent. -/\ntheorem grid_power_le (s : ℕ) :\n    (gridFactor s)^(SemiprimeD1PackingReady.logarithm s+1) ≤\n      Real.exp (((4*SemiprimeD1PackingReady.logarithm s+7)*\n        (SemiprimeD1PackingReady.logarithm s+1):ℕ):ℝ) := by\n  have htwo : (2:ℝ) ≤ Real.exp 1 := by linarith [Real.add_one_le_exp (1:ℝ)]\n  have h := pow_le_pow_left₀ (by positivity : (0:ℝ) ≤ 2) htwo\n    ((4*SemiprimeD1PackingReady.logarithm s+7)*(SemiprimeD1PackingReady.logarithm s+1))\n  dsimp only [gridFactor]\n  rw [←pow_mul]\n  convert h using 1\n  rw [←Real.exp_nat_mul]\n  simp only [mul_one]\n\n/-- The exact floor in the original root taper costs only the fixed512 factor. -/\ntheorem mode_total_le (s : ℕ)\n    (hl : epsilonDenominator ≤ SemiprimeD1PackingReady.logarithm s) :\n    (8/7:ℝ)*modeFactor s ≤ (393216/7:ℝ)*(s:ℝ)/Real.sqrt (SemiprimeD1PackingReady.logarithm s:ℕ) := by\n  have hroot := SemiprimeD1PathRate.sqrt_root_bound (SemiprimeD1PackingReady.logarithm s) hl\n  have hb : 0 < SemiprimeD1PackingReady.logarithm s/epsilonDenominator :=\n    Nat.div_pos hl (by norm_num [epsilonDenominator])\n  have hlpos : 0 < SemiprimeD1PackingReady.logarithm s := by\n    have hh : 0 < epsilonDenominator := by norm_num [epsilonDenominator]\n    omega\n  have hs1 : 0 < Real.sqrt (SemiprimeD1PackingReady.logarithm s/epsilonDenominator:ℕ) :=\n    Real.sqrt_pos.mpr (by exact_mod_cast hb)\n  have hs2 : 0 < Real.sqrt (SemiprimeD1PackingReady.logarithm s:ℕ) :=\n    Real.sqrt_pos.mpr (by exact_mod_cast hlpos)\n  dsimp only [modeFactor]\n  rw [←mul_div_assoc]\n  apply (div_le_div_iff₀ hs1 hs2).mpr\n  calc\n    _ = (((8/7:ℝ)*96)*(s:ℝ))*Real.sqrt (SemiprimeD1PackingReady.logarithm s:ℕ) := by ring\n    _ ≤ (((8/7:ℝ)*96)*(s:ℝ))*(512*Real.sqrt (SemiprimeD1PackingReady.logarithm s/epsilonDenominator:ℕ)) :=\n      mul_le_mul_of_nonneg_left hroot (by positivity)\n    _ = _ := by ring\n\n/-- Explicit whole-tree envelope for the ACTUAL closed controller inventory,\nuniformly over all supplied fuels and every original root in the input caps.\nNo branching count, child solution, inherited precision or packing oracle occurs. -/\ntheorem eventually_count_le : ∀ᶠ s : ℕ in Filter.atTop,\n    ∀ (root : Call) (fuel : ℕ), root.depth=0 → edgeCount root.net ≤ s → root.ctx.precision ≤ s →\n      root.ctx.Positive → WellFormed root.net → Good root.ctx root.net →\n      SemiprimeD1TensorNetworkRecursion.DegreeBound root.net (SemiprimeD1PackingReady.degreeCap s) →\n      (count s fuel root:ℝ) ≤ (SemiprimeD1PackingReady.logarithm s+2:ℕ)*\n        Real.exp ((393216/7:ℝ)*(s:ℝ)/Real.sqrt (SemiprimeD1PackingReady.logarithm s:ℕ)+\n          (((4*SemiprimeD1PackingReady.logarithm s+7)*\n            (SemiprimeD1PackingReady.logarithm s+1):ℕ):ℝ)) := by\n  have hlim : Filter.Tendsto SemiprimeD1PackingReady.logarithm Filter.atTop Filter.atTop :=\n    SemiprimeCounterRate.tendsto_clog_two_atTop.comp (Filter.tendsto_add_atTop_nat 2)\n  filter_upwards [eventually_reach_branch,hlim.eventually (Filter.eventually_ge_atTop epsilonDenominator)] with s hbranch hl\n  intro root fuel hdepth hM hp hpos hw hg hd\n  let lam := SemiprimeD1PackingReady.logarithm s\n  let k := min fuel (lam+1)\n  have hk : k ≤ lam+1 := Nat.min_le_right _ _\n  have hG : 1 ≤ gridFactor s := by dsimp only [gridFactor];exact one_le_pow₀ (by norm_num)\n  have hA : 0 ≤ modeFactor s := by dsimp only [modeFactor];positivity\n  have h := count_le s root (gridFactor s) (modeFactor s) hG hA\n    (fun call hr => hbranch root call hdepth hM hp hpos hw hg hd hr) k root Reach.root\n  rw [hdepth] at h\n  have htail : modeFactor s*tail 0 k ≤ (8/7:ℝ)*modeFactor s := by\n    have hh := mul_le_mul_of_nonneg_left (tail_le 0 k) hA\n    norm_num only [pow_zero,mul_one] at hh\n    exact hh.trans (le_of_eq (mul_comm _ _))\n  have hcoef : (k:ℝ)+1 ≤ (lam+2:ℕ) := by exact_mod_cast (by omega : k+1 ≤ lam+2)\n  have hgrid : (gridFactor s)^k ≤ Real.exp (((4*lam+7)*(lam+1):ℕ):ℝ) :=\n    (pow_le_pow_right₀ hG hk).trans (grid_power_le s)\n  have hmode := mode_total_le s hl\n  rw [count_fuel_cap s fuel root]\n  calc\n    _ ≤ _ := h\n    _ ≤ (lam+2:ℕ)*\n        (Real.exp (((4*lam+7)*(lam+1):ℕ):ℝ)*\n          Real.exp ((393216/7:ℝ)*(s:ℝ)/Real.sqrt (lam:ℕ))) := by\n      have h1 := mul_le_mul hcoef hgrid (by positivity) (by positivity)\n      have h2 := mul_le_mul h1 (Real.exp_le_exp.mpr (htail.trans hmode))\n        (Real.exp_pos _).le (by positivity)\n      convert h2 using 1\n      ring\n    _ = _ := by rw [←Real.exp_add];congr 2;ring\n\nend RiemannGaussian.SemiprimeD1HybridCallTree\n","RiemannGaussian.SemiprimeD1JetWordPacketTables":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetWordPacketEntryBits\nimport RiemannGaussian.SemiprimeD1PacketTensorTables\nimport RiemannGaussian.SemiprimeD1TensorTapeLeaf\n\n/-! # Eager actual packet tables from original word producers\nThe unchanged actual prepared header and node are retained once. Every entry\nexecutes the new physical word backend, and all distinct reports remain paid.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 700000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1JetWordPacketTables\nopen SemiprimeD1JetAxes SemiprimeD1TensorTables\nopen SemiprimeD1PacketTensorTables (Header prepare)\n\n/-- Materialize every entry with the new actual word backend. -/\ndef acquire {V : ℕ} (header : Header V) (ctx : Context)\n    (z : SemiprimeD1JetAffineCoefficient.JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ) : Acquired header.endpoints.length :=\n  let out:=build header.endpoints.length\n    (SemiprimeD1JetWordPacketEntryBits.evaluate ctx (SemiprimeD1PacketEntryBits.borrow z) a i t\n      header.masks header.endpoints beta)\n  ⟨out.table,header.clock+z.clock+out.clock+beta.length+12⟩\n\n/-- Original eager-table bytes are preserved; their different clocks are not equated. -/\ntheorem acquire_table {V : ℕ} (header : Header V) (ctx : Context) (hpos:ctx.Positive)\n    (z : SemiprimeD1JetAffineCoefficient.JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ) :\n    (acquire header ctx z a i t beta).table=\n      (SemiprimeD1PacketTensorTables.acquire header ctx z a i t beta).table := by\n  apply SemiprimeD1TensorTapeLeaf.build_table_congr\n  intro bits\n  exact SemiprimeD1JetWordPacketEntryBits.evaluate_words ctx hpos _ _ _ _ _ _ _ _\n\n/-- Every acquired table entry is canonical by the actual final physical multiply. -/\ntheorem acquire_good {V : ℕ} (header : Header V) (ctx : Context)\n    (z : SemiprimeD1JetAffineCoefficient.JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ) :\n    Good ctx (acquire header ctx z a i t beta).table := by\n  apply build_good\n  intro bits _\n  exact SemiprimeD1JetWordPacketEntryBits.evaluate_canonical ctx _ _ _ _ _ _ _ _\n\n/-- Original source/graph/mask acquisition is executed through the actual header. -/\ndef acquireOriginal {n F r a : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (source : SemiprimeD1OriginalModeAcquisition.Acquired n F a arity)\n    (packet : Fin source.packets.state.packets.length) (i : Fin a) (g : Fin r)\n    (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ) :=\n  acquire (prepare owner source packet i g) ctx z a i t beta\n\n/-- The actual original source and node reports remain in every eager table. -/\ntheorem acquire_retains {V : ℕ} (header : Header V) (ctx : Context)\n    (z : SemiprimeD1JetAffineCoefficient.JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ) :\n    header.clock+z.clock≤(acquire header ctx z a i t beta).clock := by\n  dsimp only [acquire]\n  omega\nend RiemannGaussian.SemiprimeD1JetWordPacketTables\n","RiemannGaussian.SemiprimeD1NetworkRecoveryLicence":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetCoordinateLinear\nimport RiemannGaussian.SemiprimeD1NetworkIntegralDeformation\nimport RiemannGaussian.SemiprimeD1IntegerRecoveryAcquisition\n\n/-! # D.5 recovery for products of INDIVIDUAL current table integer lifts\nThe source product is formed intrinsically in the integral old-jet ring BEFORE\nmapping to either rational or modular coefficients. No mod-parent aggregate word\nis lifted. Concrete network wrappers below consume literal Vertex/table data.\n-/\n\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1NetworkRecoveryLicence\nopen scoped BigOperators\nopen Polynomial SemiprimeD1JetAlgebra SemiprimeD1JetScalarMap SemiprimeD1JetBoxIndex\n  SemiprimeD1JetLiteralLift SemiprimeD1DyadicInteger SemiprimeD1IntegralDeformation\n  SemiprimeD1OriginalDeformation SemiprimeD1CurrentTableDeformation\n  SemiprimeD1JetCoordinateLinear SemiprimeD1DyadicBounds\n  SemiprimeD1NetworkIntegralDeformation SemiprimeD1LeafCounter\nnoncomputable section\n\n/-- Internal scalar reference for intrinsic integral old-jet source products. -/\ndef reference (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→Integral axes)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) : Polynomial ℚ :=\n  polynomial (coordinate (dims axes) e he)\n    (SemiprimeD1Deformation.polynomial _ (fun x => scalarMap (dims axes) integers.subtype (A x)) (fun x => scalarMap (dims axes) integers.subtype (B x))\n      (wire (constants (dims axes)) n F r a arity owner))\n\n/-- The reference has the ORIGINAL D.8 degree budget, with no degree oracle. -/\ntheorem reference_degree (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→Integral axes)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    (reference axes n F r a arity owner A B e he).natDegree≤\n      (Placements n F r a arity owner).length*(2*(2^a)-1) :=\n  (polynomial_degree _ _).trans (original_degree _ n F r a arity owner _ _)\n\n/-- Old-coordinate linear extraction commutes with the EXACT original local substitution. -/\ntheorem reference_local (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→Integral axes)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    (reference axes n F r a arity owner A B e he).comp (SemiprimeD1WireKernelPaper.affine a t.val)=\n      polynomial (coordinate (dims axes) e he)\n        ((integralPolynomial axes n F r a arity owner t A B).map (scalarMap (dims axes) integers.subtype)) := by\n  have hsub := SemiprimeD1JetCoordinateLinear.polynomial_comp (coordinate (dims axes) e he)\n    (SemiprimeD1Deformation.polynomial _ (fun x => scalarMap (dims axes) integers.subtype (A x)) (fun x => scalarMap (dims axes) integers.subtype (B x))\n      (wire (constants (dims axes)) n F r a arity owner)) (SemiprimeD1WireKernelPaper.affine a t.val)\n  have hc : algebraMap ℚ (Algebra (dims axes) ℚ)=constants (dims axes) := Subsingleton.elim _ _\n  rw [hc] at hsub\n  rw [reference,← hsub,← integral_inclusion]\n\n/-- The two original scalar affine-coordinate definitions are exactly the same polynomial. -/\ntheorem original_affine (a t : ℕ) : SemiprimeD1WireKernelPaper.affine a t=\n    SemiprimeD1ScaledHermite.affine (SemiprimeD1HermiteOriginal.alpha a) (SemiprimeD1HermiteNodes.node a t) := by\n  simp only [SemiprimeD1WireKernelPaper.affine,SemiprimeD1ScaledHermite.affine,\n    SemiprimeD1HermiteOriginal.alpha,SemiprimeD1HermiteNodes.node,Int.cast_ofNat]\n\n/-- ACTUAL child old-coordinate residue equality DERIVES the original retained D.5 error. -/\ntheorem child_error (axes : List ℕ) (n F r a p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→Integral axes)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) (j : ℕ) (bs : List Bool)\n    (hchild : coefficient (dims axes) e he\n      (scalarMap (dims axes) (reduction p) ((integralPolynomial axes n F r a arity owner t A B).coeff j))=\n        (SemiprimeBitArithmetic.bitValue bs:ZMod (2^p))) :\n    AtLeast (p:ℤ) ((SemiprimeBitArithmetic.bitValue bs:ℚ)-\n      (((reference axes n F r a arity owner A B e he).comp\n        (SemiprimeD1ScaledHermite.affine (SemiprimeD1HermiteOriginal.alpha a)\n          (SemiprimeD1HermiteNodes.node a t.val))).coeff j)) := by\n  rw [← original_affine,reference_local,polynomial_coefficient,Polynomial.coeff_map]\n  exact old_coordinate_word_error (dims axes) e he p\n    ((integralPolynomial axes n F r a arity owner t A B).coeff j) bs hchild\n\n/-- The reference's original value at zero is integral from the literal source contraction. -/\ntheorem reference_zero_integral (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→Integral axes)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    AtLeast 0 ((reference axes n F r a arity owner A B e he).eval 0) := by\n  rw [reference,polynomial_eval,map_zero,original_at_zero]\n  have hs : (∑bits,scalarMap (dims axes) integers.subtype (A bits)*scalarMap (dims axes) integers.subtype (B bits))=\n      scalarMap (dims axes) integers.subtype (∑bits,A bits*B bits) := by\n    simp only [map_sum,map_mul]\n  change AtLeast 0 (coefficient (dims axes) e he _)\n  rw [hs,coefficient_scalarMap]\n  exact (coefficient (dims axes) e he (∑bits,A bits*B bits)).property\n\n/-- Internal intrinsic-ring D.5 bridge. Concrete network inputs are instantiated\nbelow by products of individually lifted actual table entries. -/\ntheorem integral_word_recovery (axes : List ℕ) (n F r a u p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→Integral axes)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e)\n    (hu : 0<u) (huM : u≤(Placements n F r a arity owner).length)\n    (children : ℕ → Array (List Bool))\n    (hchild : ∀t : Fin (SemiprimeD1WireKernelOriginal.size a),\n      t.val∈SemiprimeD1HermiteNodes.active a (SemiprimeD1TaperedLoss.height\n        (Placements n F r a arity owner).length u) u →\n      ∀j<SemiprimeD1JetRecoveryGrid.nodeMultiplicity a (SemiprimeD1TaperedLoss.height\n        (Placements n F r a arity owner).length u) u t.val,\n      coefficient (dims axes) e he\n        (scalarMap (dims axes) (reduction (SemiprimeD1WeightPrecision.precision a\n          (Placements n F r a arity owner).length u p t.val))\n          ((integralPolynomial axes n F r a arity owner t A B).coeff j))=\n        (SemiprimeBitArithmetic.bitValue ((children t.val)[j]?.getD []):ZMod\n          (2^SemiprimeD1WeightPrecision.precision a (Placements n F r a arity owner).length u p t.val))) :\n    SemiprimeD1IntegerRecoveryResidue.finish p\n      (SemiprimeD1IntegerRecoveryAcquisition.run a (Placements n F r a arity owner).length u children).result=\n      SemiprimeD1RecoveryResidue.reduce p ((reference axes n F r a arity owner A B e he).eval 0) := by\n  rw [SemiprimeD1IntegerRecoveryAcquisition.run_result]\n  apply SemiprimeD1IntegerRecoveryResidue.original_run_modulo a _ u p hu huM\n    (reference axes n F r a arity owner A B e he)\n    (reference_degree axes n F r a arity owner A B e he) children\n    (reference_zero_integral axes n F r a arity owner A B e he)\n  intro t ht j hj\n  have htN : t<SemiprimeD1WireKernelOriginal.size a :=\n    Finset.mem_range.mp (Finset.mem_filter.mp ht).1\n  rw [SemiprimeD1IntegerRecovery.decodedPackets_coefficient]\n  have h := child_error axes n F r a _ arity owner ⟨t,htN⟩ A B e he j\n    ((children t)[j]?.getD []) (hchild ⟨t,htN⟩ ht j hj)\n  simpa only [SemiprimeD1IntegerRecovery.decode_eq] using h\n\n/-- Concrete scalar reference of the ACTUAL network's individual integer-entry products. -/\ndef networkReference (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (left right : List Vertex)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) : Polynomial ℚ :=\n  reference axes n F r a arity owner (networkValue axes left) (networkValue axes right) e he\n\n/-- Actual individual network entry products preserve the ORIGINAL reference degree cap. -/\ntheorem network_reference_degree (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (left right : List Vertex)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    (networkReference axes n F r a arity owner left right e he).natDegree≤\n      (Placements n F r a arity owner).length*(2*(2^a)-1) :=\n  reference_degree axes n F r a arity owner _ _ e he\n\n/-- The actual network source, including every carry, gives integral parent coordinate values. -/\ntheorem network_reference_zero_integral (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (left right : List Vertex)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    AtLeast 0 ((networkReference axes n F r a arity owner left right e he).eval 0) :=\n  reference_zero_integral axes n F r a arity owner _ _ e he\n\n\n/-- The reference's parent residue is EXACTLY the original individual-table\nnetwork contraction at parent precision, with all integer carries preserved. -/\ntheorem network_reference_zero_residue (axes : List ℕ) (n F r a p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (left right : List Vertex)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    SemiprimeD1RecoveryResidue.reduce p\n      ((networkReference axes n F r a arity owner left right e he).eval 0)=\n      coefficient (dims axes) e he\n        (∑bits : Fin (Placements n F r a arity owner).length→Bool,\n          (left.map (fun v => SemiprimeD1JetInterpretation.interpret ⟨axes,p⟩\n            (SemiprimeD1TensorTables.valueAt v.table (localAssignment bits v)))).prod*\n          (right.map (fun v => SemiprimeD1JetInterpretation.interpret ⟨axes,p⟩\n            (SemiprimeD1TensorTables.valueAt v.table (localAssignment bits v)))).prod) := by\n  let total : Integral axes := ∑bits : Fin (Placements n F r a arity owner).length→Bool,\n    networkValue axes left bits*networkValue axes right bits\n  have href : (networkReference axes n F r a arity owner left right e he).eval 0=\n      coefficient (dims axes) e he (scalarMap (dims axes) integers.subtype total) := by\n    rw [networkReference,reference,polynomial_eval,map_zero,original_at_zero]\n    change coefficient (dims axes) e he\n      (∑bits,scalarMap (dims axes) integers.subtype (networkValue axes left bits)*\n        scalarMap (dims axes) integers.subtype (networkValue axes right bits))=_\n    simp only [total,map_sum,map_mul]\n  have hmod : scalarMap (dims axes) (reduction p) total=\n      ∑bits : Fin (Placements n F r a arity owner).length→Bool,\n        (left.map (fun v => SemiprimeD1JetInterpretation.interpret ⟨axes,p⟩\n          (SemiprimeD1TensorTables.valueAt v.table (localAssignment bits v)))).prod*\n        (right.map (fun v => SemiprimeD1JetInterpretation.interpret ⟨axes,p⟩\n          (SemiprimeD1TensorTables.valueAt v.table (localAssignment bits v)))).prod := by\n    simp only [total,map_sum,map_mul,networkValue_modular]\n  rw [href,coefficient_scalarMap]\n  change reduction p (coefficient (dims axes) e he total)=_\n  rw [← coefficient_scalarMap (dims axes) (reduction p) total e he,hmod]\n\n/-- ACTUAL network-data D.5 recovery, with INDIVIDUAL current entries lifted BEFORE\nproducts. No aggregate-mod-parent table, unknown A/B value, degree, integrality,\nweight, or scalar-error oracle is an input. Only child modular postconditions remain. -/\ntheorem network_word_recovery (axes : List ℕ) (n F r a u p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (left right : List Vertex)\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e)\n    (hu : 0<u) (huM : u≤(Placements n F r a arity owner).length)\n    (children : ℕ → Array (List Bool))\n    (hchild : ∀t : Fin (SemiprimeD1WireKernelOriginal.size a),\n      t.val∈SemiprimeD1HermiteNodes.active a (SemiprimeD1TaperedLoss.height\n        (Placements n F r a arity owner).length u) u →\n      ∀j<SemiprimeD1JetRecoveryGrid.nodeMultiplicity a (SemiprimeD1TaperedLoss.height\n        (Placements n F r a arity owner).length u) u t.val,\n      coefficient (dims axes) e he\n        (scalarMap (dims axes) (reduction (SemiprimeD1WeightPrecision.precision a\n          (Placements n F r a arity owner).length u p t.val))\n          ((networkPolynomial axes n F r a arity owner t left right).coeff j))=\n        (SemiprimeBitArithmetic.bitValue ((children t.val)[j]?.getD []):ZMod\n          (2^SemiprimeD1WeightPrecision.precision a (Placements n F r a arity owner).length u p t.val))) :\n    SemiprimeD1IntegerRecoveryResidue.finish p\n      (SemiprimeD1IntegerRecoveryAcquisition.run a (Placements n F r a arity owner).length u children).result=\n      SemiprimeD1RecoveryResidue.reduce p ((networkReference axes n F r a arity owner left right e he).eval 0) :=\n  integral_word_recovery axes n F r a u p arity owner _ _ e he hu huM children hchild\n\nend\nend RiemannGaussian.SemiprimeD1NetworkRecoveryLicence\n","RiemannGaussian.SemiprimeD1OwnerPrefixBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RootOwnerTables\nimport RiemannGaussian.SemiprimeD1TensorTapeCodec\n\n/-! # Physical owner-prefix records and exact duplicate/conflict semantics\nKeys are binary original WIRE values, not factor-major occurrence ordinals.\nThese definitions specify a literal parser/equality source; they are never an\ninstruction evaluating a list, prefix compatibility or an allowed-value answer.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1OwnerPrefixBits\nopen SemiprimeSourceHistogramKeyBits (frame frame_length)\nopen SemiprimeBitArithmetic\n\n/-- A framed binary wire key followed by ONE actual value bit per record.\nThe final false tag is consumed; bytes beyond it are retained exactly. -/\ndef records : List (List Bool×Bool)→List Bool→List Bool\n  | [],tail=>false::tail\n  | (key,value)::rest,tail=>true::frame key (value::records rest tail)\n/-- Actual initialized compatibility flags, updated by every original record. -/\ndef scan (query : List Bool) : List (List Bool×Bool)→Bool→Bool→Bool×Bool\n  | [],low,high=>(low,high)\n  | (key,value)::rest,low,high=>\n      let same:=decide (bitValue key=bitValue query)\n      scan query rest (low && !(same && value)) (high && !(same && !value))\n/-- All physical framing, including every value and record/end tag, is retained. -/\ntheorem records_length (rows : List (List Bool×Bool)) (tail : List Bool) :\n    (records rows tail).length=3*rows.length+2*(rows.map (fun x=>x.1.length)).sum+1+tail.length := by\n  induction rows with\n  | nil=>simp [records,Nat.add_comm]\n  | cons row rows ih=>\n    rcases row with ⟨key,value⟩\n    simp only [records,List.length_cons,frame_length,List.map_cons,List.sum_cons,ih]\n    omega\n/-- Every row rules out exactly its opposite value when its original key matches. -/\ntheorem scan_all (query : List Bool) (rows : List (List Bool×Bool)) (low high : Bool) :\n    scan query rows low high=\n      (low && rows.all (fun x=>decide (bitValue x.1≠bitValue query ∨ x.2=false)),\n       high && rows.all (fun x=>decide (bitValue x.1≠bitValue query ∨ x.2=true))) := by\n  induction rows generalizing low high with\n  | nil=>simp only [scan,List.all_nil,Bool.and_true]\n  | cons row rows ih=>\n    rcases row with ⟨key,value⟩\n    rw [scan,ih]\n    by_cases h:bitValue key=bitValue query <;> cases value <;>\n      simp [h,List.all_cons]\n/-- Original finite-wire keys and ALL original prefix records are the only\nsemantic premise; duplicates and inconsistent repeated assignments remain. -/\ntheorem scan_original {n : ℕ} (wire : Fin n) (fixed : List (Fin n×Bool))\n    (encode : Fin n→List Bool) (he : ∀i,bitValue (encode i)=i.val) :\n    scan (encode wire) (fixed.map (fun x=>(encode x.1,x.2))) true true=\n      (SemiprimeD1RootOwnerTables.allowed fixed wire false,\n       SemiprimeD1RootOwnerTables.allowed fixed wire true) := by\n  rw [scan_all]\n  simp only [Bool.true_and,List.all_map,Function.comp_def,SemiprimeD1RootOwnerTables.allowed]\n  congr 2 <;> funext x <;> by_cases hx:x.1=wire\n  · simp [he,hx]\n  · have hv:x.1.val≠wire.val:=fun h=>hx (Fin.ext h)\n    simp [he,hx,hv]\n  · simp [he,hx]\n  · have hv:x.1.val≠wire.val:=fun h=>hx (Fin.ext h)\n    simp [he,hx,hv]\nend RiemannGaussian.SemiprimeD1OwnerPrefixBits\n","RiemannGaussian.SemiprimeD1PacketEntryPolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketSourceProductValues\nimport RiemannGaussian.SemiprimeD1PacketRowProducts\n\n/-! # Executed packet entries are the acquired polynomial coefficient times source product\nBorrowing affects only reports, never acquired coefficient data. The theorem\nuses the actual physical row recipes and mask restriction; no row polynomial,\nsource-value family or coefficient answer is a caller input.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 120000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1PacketEntryPolynomial\nopen SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nopen SemiprimeD1PacketEntryInputs SemiprimeD1PacketEntryBits\n\n/-- Physical local base terms ignore only the borrowed producer report. -/\ntheorem baseTerm_borrow (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row column : Wire a) :\n    baseTerm ctx (borrow z) a t row column=baseTerm ctx z a t row column := rfl\n\n/-- Physical signed mode coefficients use the identical borrowed current word vector. -/\ntheorem coefficient_borrow (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) :\n    coefficient ctx (borrow z) a i t row item=coefficient ctx z a i t row item := rfl\n\n/-- Acquired constant row data is unchanged by producer-report borrowing. -/\ntheorem rowBase_borrow (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a)) :\n    rowBase ctx (borrow z) a t row columns=rowBase ctx z a t row columns := rfl\n\n/-- The actual entire cached coefficient list is unchanged. -/\ntheorem coefficients_borrow (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (items : List SemiprimeD1PacketModeMask.Item) :\n    (coefficients ctx (borrow z) a i t row items).value=(coefficients ctx z a i t row items).value := by\n  rw [SemiprimeD1PacketEntryValue.coefficients_value,SemiprimeD1PacketEntryValue.coefficients_value]\n  simp only [coefficient_borrow]\n\n/-- The literal acquired affine row, not just its interpretation, is unchanged. -/\ntheorem recipe_borrow (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (columns : List (Wire a)) (items : List SemiprimeD1PacketModeMask.Item) :\n    (recipe ctx (borrow z) a i t row columns items).value=(recipe ctx z a i t row columns items).value := by\n  dsimp only [recipe]\n  rw [rowBase_borrow,coefficients_borrow]\n\n/-- The entire literal row inventory is unchanged, with order and multiplicity retained. -/\ntheorem recipes_borrow (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (columns rows : List (Wire a)) (items : List SemiprimeD1PacketModeMask.Item) :\n    (recipes ctx (borrow z) a i t columns items rows).value=\n      (recipes ctx z a i t columns items rows).value := by\n  rw [SemiprimeD1PacketEntryValue.recipes_value,SemiprimeD1PacketEntryValue.recipes_value]\n  simp only [recipe_borrow]\n\n/-- Borrowing leaves the actual packet polynomial unchanged, coefficient by coefficient. -/\ntheorem polynomial_borrow (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (columns rows : List (Wire a)) (cache : SemiprimeD1PacketModeMask.Cache) :\n    SemiprimeD1PacketPolynomialAcquired.polynomial ctx (borrow z) a i t columns rows cache=\n      SemiprimeD1PacketPolynomialAcquired.polynomial ctx z a i t columns rows cache := by\n  unfold SemiprimeD1PacketPolynomialAcquired.polynomial\n  rw [recipes_borrow]\n\n/-- Executed coefficient acquisition uses exactly the acquired packet polynomial\nand ORIGINAL global beta source exponents, over the concrete current quotient. -/\ntheorem evaluate_polynomial {V : ℕ} (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (cache : SemiprimeD1PacketModeMask.Cache) (endpoints : List (SemiprimeD1ChildGraph.Endpoint V))\n    (beta : List ℕ) (bits : List Bool) (hpos : ctx.Positive) :\n    let input:=gather a endpoints bits\n    interpret ctx (evaluate ctx z a i t cache endpoints beta bits).words=\n      (SemiprimeD1PacketPolynomialAcquired.polynomial ctx z a i t input.columns input.rows cache).coeff\n        (SemiprimeD1SeparatedCoefficient.restrict (SemiprimeD1PacketModeProjection.targetSet cache) beta.toFinsupp)*\n      interpret ctx (sourceProduct ctx a i input.columns beta cache.items 0).words := by\n  dsimp only\n  rw [SemiprimeD1PacketEntryValue.evaluate_value ctx z a i t cache endpoints beta bits hpos,\n    recipes_borrow,SemiprimeD1PacketModeProjection.restrict_toFinsupp,\n    ← SemiprimeD1PacketEntryValue.sourceProduct_value ctx a i _ beta cache.items 0 hpos]\n  rfl\n/-- Borrowed producer reports do not change interpreted executed entries;\nthis is a value theorem only and does not identify or discard either report. -/\ntheorem evaluate_borrow {V : ℕ} (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (cache : SemiprimeD1PacketModeMask.Cache) (endpoints : List (SemiprimeD1ChildGraph.Endpoint V))\n    (beta : List ℕ) (bits : List Bool) (hpos : ctx.Positive) :\n    interpret ctx (evaluate ctx (borrow z) a i t cache endpoints beta bits).words=\n      interpret ctx (evaluate ctx z a i t cache endpoints beta bits).words := by\n  rw [evaluate_polynomial ctx (borrow z) a i t cache endpoints beta bits hpos,\n    evaluate_polynomial ctx z a i t cache endpoints beta bits hpos,polynomial_borrow]\nend RiemannGaussian.SemiprimeD1PacketEntryPolynomial\n","RiemannGaussian.SemiprimeD1PacketSourceValues":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketCoefficientAlignment\n\n/-! # Original source forms at computed route owners\nEvery source form below is reconstructed from the actual child column list.\nFinite source-group sums collapse using original routing and empty-tile zeros,\nwithout an advised source owner or source-linear-form answer.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 4000000\nnamespace RiemannGaussian.SemiprimeD1PacketSourceValues\nopen scoped BigOperators\nopen SemiprimeD1PacketEntryInputs SemiprimeD1PacketGlobalRowForm\nopen SemiprimeD1PacketRowExpansion SemiprimeD1PacketSourceAlignment\nopen SemiprimeD1ChildGraph SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nnoncomputable section\nattribute [local instance] Classical.propDecidable\n\n/-- Source group read from the actual physical routing bytes, with its original\npalette bound proved from the retained sparse replay. -/\ndef sourceGroup (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (tile : Fin (2^(i.val+1))) : Fin r :=\n  ⟨SemiprimeBitArithmetic.bitValue (SemiprimeD1ModeRoutingBits.fromReplay\n    (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner) packet i tile).source,\n    (SemiprimeD1ModeRoutingOriginal.route_palette n F r a arity owner packet i tile).2.1⟩\n\n/-- Computed source group equality is exactly the executed compact-byte equality. -/\ntheorem sourceGroup_bytes (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (tile : Fin (2^(i.val+1))) (g : Fin r) :\n    sourceGroup n F r a arity owner packet i tile=g ↔\n      (SemiprimeD1ModeRoutingBits.acquire\n        (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets[packet.val] a i tile).source=\n          (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits := by\n  have hc := (SemiprimeD1ModeRoutingOriginal.route_palette n F r a arity owner packet i tile).1\n  have hd := (SemiprimeD1ModeRoutingBits.fromReplay_data\n    (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner) packet i tile).1\n  constructor\n  · intro h\n    rw [←hd]\n    apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ hc\n      (SemiprimeSourceHistogramPortKeys.encodeKey_compact g.val)\n    rw [SemiprimeSourceHistogramPortKeys.encodeKey_value]\n    exact congrArg Fin.val h\n  · intro h\n    apply Fin.ext\n    change SemiprimeBitArithmetic.bitValue _=g.val\n    rw [hd,h,SemiprimeSourceHistogramPortKeys.encodeKey_value]\n\n/-- Original source form at that computed owner. This is derived from the actual\nacquired column list, not an external L-value function. -/\ndef sourceForm (ctx : Context) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (assignment : Endpoint (n+F)→Bool) (tile : Fin (2^(i.val+1))) (b : ℕ) : Carrier ctx :=\n  tilePower ctx a i (columnsOf n F r a arity owner i packet assignment\n    (sourceGroup n F r a arity owner packet i tile)) tile.val b\n\n/-- The actual source group sum has exactly one possible nonzero source form.\nA local source=target mode contributes zero; empty forms remain literal zero. -/\ntheorem source_sum (ctx : Context) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g : Fin r) (assignment : Endpoint (n+F)→Bool)\n    (tile : Fin (2^(i.val+1))) (b : ℕ) (c : Carrier ctx) :\n    (∑h : Fin r,if h=g then 0 else\n      c*tilePower ctx a i (columnsOf n F r a arity owner i packet assignment h) tile.val b)=\n      if sourceGroup n F r a arity owner packet i tile=g then 0\n      else c*sourceForm ctx n F r a arity owner packet i assignment tile b := by\n  rw [Finset.sum_eq_single (sourceGroup n F r a arity owner packet i tile)]\n  · rfl\n  · intro h _ hn\n    by_cases hg : h=g\n    · simp only [hg,ite_true]\n    · have hs : (SemiprimeD1ModeRoutingBits.acquire\n          (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets[packet.val] a i tile).source≠\n          (SemiprimeSourceHistogramPortKeys.encodeKey h.val).bits := by\n        intro hb\n        exact hn ((sourceGroup_bytes n F r a arity owner packet i tile h).mpr hb).symm\n      simp only [hg,ite_false]\n      rw [original_tilePower_zero ctx n F r a arity owner packet i h assignment tile b hs,mul_zero]\n  · simp only [Finset.mem_univ,not_true_eq_false,false_implies]\n\n/-- The full original row uses exactly one reconstructed source form per tile.\nThis eliminates the source-group sum using the actual routing palette. -/\ntheorem full_row_source (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g : Fin r) (rowEndpoint : Endpoint (n+F))\n    (hr : rowEndpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hrs : rowEndpoint.side=true) (rowBit : Bool) (assignment : Endpoint (n+F)→Bool)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (hpos : ctx.Positive) (hp : 0<ctx.precision)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val≠0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val)=i.val) :\n    let row := (wire a rowEndpoint rowBit).1\n    ((SemiprimeD1PacketColumnPartition.originalSideWires n F r a arity owner false packet assignment).map\n      (fun c => interpret ctx (SemiprimeD1PacketEntryBits.baseTerm ctx z a t row c).words)).sum=\n      ((columnsOf n F r a arity owner i packet assignment g).map\n        (fun c => interpret ctx (SemiprimeD1PacketEntryBits.baseTerm ctx z a t row c).words)).sum+\n      ∑tile : Fin (2^(i.val+1)),∑b∈Finset.range (ctx.precision-1),\n        if sourceGroup n F r a arity owner packet i tile=g then 0 else\n        modeValue ctx z a i t row tile b*sourceForm ctx n F r a arity owner packet i assignment tile b := by\n  dsimp only\n  rw [full_row_D12 ctx z n F r a arity owner packet i g rowEndpoint hr hrs rowBit assignment t hpos hp ht hi]\n  let row := (wire a rowEndpoint rowBit).1\n  let localSum := ((columnsOf n F r a arity owner i packet assignment g).map\n    (fun c => interpret ctx (SemiprimeD1PacketEntryBits.baseTerm ctx z a t row c).words)).sum\n  let expansion := fun h : Fin r => ∑tile : Fin (2^(i.val+1)),∑b∈Finset.range (ctx.precision-1),\n    modeValue ctx z a i t row tile b*tilePower ctx a i (columnsOf n F r a arity owner i packet assignment h) tile.val b\n  have hsplit : (∑h : Fin r,if h=g then localSum else expansion h)=\n      localSum+∑h : Fin r,if h=g then 0 else expansion h := by\n    have he (h : Fin r) : (if h=g then localSum else expansion h)=\n        (if h=g then localSum else 0)+(if h=g then 0 else expansion h) := by\n      by_cases hh : h=g <;> simp only [hh,ite_true,ite_false,add_zero,zero_add]\n    simp_rw [he]\n    rw [Finset.sum_add_distrib]\n    simp only [Finset.sum_ite_eq',Finset.mem_univ,ite_true]\n  change (∑h : Fin r,if h=g then _ else expansion h)=_\n  have hleft : (∑h : Fin r,if h=g then\n      ((columnsOf n F r a arity owner i packet assignment h).map\n        (fun c => interpret ctx (SemiprimeD1PacketEntryBits.baseTerm ctx z a t row c).words)).sum else expansion h)=\n      ∑h : Fin r,if h=g then localSum else expansion h := by\n    apply Finset.sum_congr rfl\n    intro h _\n    by_cases hh : h=g <;> simp only [hh,ite_true,ite_false,localSum]\n  rw [hleft,hsplit]\n  congr 1\n  have hterm (h : Fin r) : (if h=g then 0 else expansion h)=\n      ∑tile : Fin (2^(i.val+1)),∑b∈Finset.range (ctx.precision-1),\n        if h=g then 0 else modeValue ctx z a i t row tile b*\n          tilePower ctx a i (columnsOf n F r a arity owner i packet assignment h) tile.val b := by\n    by_cases hh : h=g <;> simp only [hh,ite_true,ite_false,expansion,Finset.sum_const_zero]\n  simp_rw [hterm]\n  rw [Finset.sum_comm]\n  apply Finset.sum_congr rfl\n  intro tile _\n  rw [Finset.sum_comm]\n  apply Finset.sum_congr rfl\n  intro b _\n  exact source_sum ctx n F r a arity owner packet i g assignment tile b (modeValue ctx z a i t row tile b)\n\nend\nend RiemannGaussian.SemiprimeD1PacketSourceValues\n","RiemannGaussian.SemiprimeD1PackingReady":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1LeafReady\n\n/-! # Uniform original-input packing guards for every permitted D.1 depth\nLiteral integer floors and ceilings are retained. No packing acceptance or\nasymptotic comparison is supplied as a premise.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1PackingReady\nopen Filter SemiprimeD1Schedule\nopen scoped Topology\n\n/-- Actual original binary ceiling logarithm. -/\ndef logarithm (s : ℕ) : ℕ := Nat.clog 2 (s+2)\n\n/-- One fixed degree cap shared by every recursive call. -/\ndef degreeCap (s : ℕ) : ℕ := 2^((9*logarithm s+9)/10)\n\n/-- Maximum actual packet exponent, before choosing any recursive depth. -/\ndef maximumExponent (s : ℕ) : ℕ := 4*(logarithm s/131072)\n\n/-- An elementary exponential bound, proved from a literal starting index. -/\ntheorem linear_le_pow (m : ℕ) (hm : 16 ≤ m) : 100*(m+1) ≤ 2^m := by\n  induction m,hm using Nat.le_induction with\n  | base => norm_num\n  | succ m hm ih =>\n    rw [pow_succ]\n    have hp : 100 ≤ 100*(m+1) := by omega\n    nlinarith\n\n/-- A twentieth of the literal logarithm pays the full integer square-root factor. -/\ntheorem logarithm_factor (lam : ℕ) (hlam : 1000 ≤ lam) :\n    Nat.sqrt lam+1 ≤ 2^(lam/20) := by\n  have hm : 16 ≤ lam/20 := by omega\n  have h := linear_le_pow (lam/20) hm\n  have hs := Nat.sqrt_le_self lam\n  have hd := Nat.mod_lt lam (by decide : 0 < 20)\n  have he := Nat.mod_add_div lam 20\n  omega\n\n/-- All literal exponents fit below the original root-size exponent. -/\ntheorem exponent_margin (lam : ℕ) (hlam : 1000 ≤ lam) :\n    1+24*(4*(lam/131072))+(9*lam+9)/10+lam/20 ≤ lam-2 ∧\n    4*(lam/131072)+1 ≤ (9*lam+9)/10 := by\n  omega\n\n/-- Actual ceiling-logarithm inversion, with the additive input offset paid. -/\ntheorem root_power (s : ℕ) (hs : 2 ≤ s) (hl : 2 ≤ logarithm s) :\n    2^(logarithm s-2) ≤ s := by\n  have hp := Nat.pow_pred_clog_lt_self (by decide : 1 < 2) (show 1 < s+2 by omega)\n  have he : logarithm s-1=(logarithm s-2)+1 := by omega\n  change 2^(logarithm s-1) < s+2 at hp\n  rw [he,pow_succ] at hp\n  omega\n\n/-- Concrete original-input guards, before selecting a recursion depth. -/\ntheorem packing_numeric (s : ℕ) (hs : 2 ≤ s) (hlam : 1000 ≤ logarithm s) :\n    2*(64^(2*maximumExponent s))^2*degreeCap s ≤ leafSize s (logarithm s) ∧\n    64^(2*maximumExponent s)*2^maximumExponent s ≤ leafSize s (logarithm s) ∧\n    2*2^maximumExponent s ≤ degreeCap s := by\n  let lam := logarithm s\n  let a := maximumExponent s\n  let c := (9*lam+9)/10\n  have hm := exponent_margin lam hlam\n  have hf := logarithm_factor lam hlam\n  have hp := root_power s hs (by omega)\n  have hfirst : (2*(64^(2*a))^2*2^c)*(Nat.sqrt lam+1) ≤ s := by\n    calc\n      _ ≤ (2*(64^(2*a))^2*2^c)*2^(lam/20) := Nat.mul_le_mul_left _ hf\n      _ = 2^(1+24*a+c+lam/20) := by\n        have hh : (64^(2*a))^2=(2:ℕ)^(24*a) := by\n          rw [show (64:ℕ)=2^6 by norm_num,← pow_mul,← pow_mul]\n          congr 1\n          ring\n        rw [hh]\n        change (2^1*2^(24*a)*2^c)*2^(lam/20)=_\n        simp only [← pow_add]\n      _ ≤ 2^(lam-2) := Nat.pow_le_pow_right (by decide : 0 < (2:ℕ)) hm.1\n      _ ≤ s := hp\n  have hsmall : 64^(2*a)*2^a ≤ 2*(64^(2*a))^2*2^c := by\n    have ha : a ≤ c := by dsimp [a,maximumExponent,c,lam] at *;omega\n    have hpow := Nat.pow_le_pow_right (by decide : 0 < (2:ℕ)) ha\n    have hbase : 1 ≤ 64^(2*a) := Nat.one_le_pow _ _ (by decide)\n    have hfactor : 64^(2*a) ≤ 2*(64^(2*a))^2 := by nlinarith\n    exact Nat.mul_le_mul hfactor hpow\n  have hleaf : 2*(64^(2*a))^2*2^c ≤ leafSize s lam := by\n    have hd := (Nat.le_div_iff_mul_le (show 0 < Nat.sqrt lam+1 by omega)).mpr hfirst\n    exact hd.trans (Nat.le_succ _)\n  refine ⟨hleaf,hsmall.trans hleaf,?_⟩\n  change 2*2^a ≤ 2^c\n  rw [← pow_succ']\n  exact Nat.pow_le_pow_right (by decide : 0 < (2:ℕ)) hm.2\n\n/-- Uniform original-input acceptance, proved eventually rather than assumed. -/\ntheorem eventually_packing : ∀ᶠ s : ℕ in atTop,\n    2*(64^(2*maximumExponent s))^2*degreeCap s ≤ leafSize s (logarithm s) ∧\n    64^(2*maximumExponent s)*2^maximumExponent s ≤ leafSize s (logarithm s) ∧\n    2*2^maximumExponent s ≤ degreeCap s := by\n  have ht : Tendsto logarithm atTop atTop :=\n    SemiprimeCounterRate.tendsto_clog_two_atTop.comp (tendsto_add_atTop_nat 2)\n  filter_upwards [eventually_ge_atTop (2:ℕ),ht.eventually (eventually_ge_atTop (1000:ℕ))] with s hs hl\n  exact packing_numeric s hs hl\n\n/-- Every actual recursive exponent obeys the same original-input cap. -/\ntheorem actual_exponent_le (s depth : ℕ) :\n    exponent (logarithm s) depth ≤ maximumExponent s := by\n  simpa only [maximumExponent,epsilonDenominator] using exponent_le (logarithm s) depth\n\n/-- Original-input packing guards hold uniformly at EVERY active depth and\nfor EVERY inherited degree below the one global cap. -/\ntheorem eventually_all_depths : ∀ᶠ s : ℕ in atTop,∀depth M degree : ℕ,\n    Active s (logarithm s) depth M → degree ≤ degreeCap s →\n    2*(64^(2*exponent (logarithm s) depth))^2*degree < M ∧\n    64^(2*exponent (logarithm s) depth)*2^exponent (logarithm s) depth < M ∧\n    max degree (2*2^exponent (logarithm s) depth) ≤ degreeCap s := by\n  filter_upwards [eventually_packing] with s hs\n  intro depth M degree hactive hdegree\n  have ha := actual_exponent_le s depth\n  have hleaf : leafSize s (logarithm s) < M := hactive.1\n  have hpow : 64^(2*exponent (logarithm s) depth) ≤ 64^(2*maximumExponent s) :=\n    Nat.pow_le_pow_right (by decide : 0<(64:ℕ)) (Nat.mul_le_mul_left _ ha)\n  have htwo : 2^exponent (logarithm s) depth ≤ 2^maximumExponent s :=\n    Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) ha\n  refine ⟨lt_of_le_of_lt ((Nat.mul_le_mul\n    (Nat.mul_le_mul_left 2 (Nat.pow_le_pow_left hpow 2)) hdegree).trans hs.1) hleaf,\n    lt_of_le_of_lt ((Nat.mul_le_mul hpow htwo).trans hs.2.1) hleaf,?_⟩\n  exact max_le hdegree ((Nat.mul_le_mul_left 2 htwo).trans hs.2.2)\n\nend RiemannGaussian.SemiprimeD1PackingReady\n","RiemannGaussian.SemiprimeD1PhysicalSourcePolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PhysicalSourceBudget\nimport RiemannGaussian.SemiprimeSourceHistogramResources\n\n/-! # Fixed polynomial overhead of the actual original sparse source supplier\nThe actual output menu factor remains explicit; no once-per-parent sharing of\nrepeated child/header source reports is asserted.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1PhysicalSourcePolynomial\nopen SemiprimeSourceHistogramResources\nopen SemiprimeSourceHistogramScalesBounds (clog_cap)\nopen SemiprimeReportPolynomialGrowth\n\n/-- Pure polynomial overhead beyond the already proved original selector envelope. -/\ndef replayTail (S : ℕ) : ℕ :=\n  prefixPolynomial S+featurePolynomial S+2*S+10+\n  S*(3*(2*S+1)+2)*(88*(S+2)+7)+1+40*(S+(S+1)+3)+6+2+\n  S*SemiprimeD1PacketReplayBudget.stepBudget S (3*(2*S+1)+1)\n    (S*(2*(S+1)+1)) (S+2)\n\n/-- Full sparse selector/padding/replay fixed polynomial envelope. -/\ndef replayEnvelope (S : ℕ) : ℕ := envelope S+replayTail S\n\n/-- Actual source-key widths derive from original graph/alphabet dimensions. -/\ntheorem feature_width (n F L S : ℕ) (hn : n ≤ S) (hF : F ≤ S) (hL : L ≤ S) :\n    SemiprimeSourceHistogramFeatureBitsBounds.width (n+F) L ≤ 2*S+1 := by\n  have hN:=clog_cap (n+F) (2*S) (by omega)\n  have hLlog:=clog_cap L S hL\n  exact max_le hN (hLlog.trans (by omega))\n\n/-- All original sparse source replay/padding/index reports have a fixed\npolynomial bound in actual input dimension caps, not a supplied report answer. -/\ntheorem replay_budget (n F r a M S : ℕ) (hr0 : 0 < r)\n    (hn : n ≤ S) (hF : F ≤ S) (hr : r ≤ S) (ha : a ≤ S)\n    (hM : M ≤ S) (hL : r^a ≤ S) :\n    SemiprimeD1PacketReplayBudget.budget n F r a M ≤ replayEnvelope S := by\n  have hs:=budget_polynomial n F r a 0 M S hr0 hn hF hr ha (by omega) hM hL\n  have hp:=prefixBudget_polynomial (r^a) (n+F) S hL (by omega)\n  have hf:=featureBudget_polynomial n F M (r^a) S hn hF hM hL\n  have hw:=feature_width n F (r^a) S hn hF hL\n  have hc:=clog_cap M S hM\n  have hclock:=clog_cap (M+1) (S+1) (by omega)\n  have hstep:=SemiprimeD1PacketReplayBudget.stepBudget_mono ha\n    (show 3*SemiprimeSourceHistogramFeatureBitsBounds.width (n+F) (r^a)+1 ≤ 3*(2*S+1)+1 by omega)\n    (show a*(2*(r+1)+1) ≤ S*(2*(S+1)+1) by gcongr)\n    (show SemiprimeSourceHistogramTrieBounds.clockWidth M ≤ S+2 from hclock)\n  have hm:=Nat.mul_le_mul hM hstep\n  have hpad : M*(3*SemiprimeSourceHistogramFeatureBitsBounds.width (n+F) (r^a)+2)*\n      (88*(Nat.clog 2 (M+1)+1)+7) ≤ S*(3*(2*S+1)+2)*(88*(S+2)+7) := by\n    exact Nat.mul_le_mul (Nat.mul_le_mul hM (by omega)) (by omega)\n  have htail : 40*(a+Nat.clog 2 (M+1)+3) ≤ 40*(S+(S+1)+3) := by gcongr\n  unfold SemiprimeD1PacketReplayBudget.budget SemiprimeD1PacketPadding.budget\n    SemiprimeD1IncidenceAcquisitionBounds.budget replayEnvelope replayTail\n  omega\n\n/-- Original replay polynomial has fixed monomial witnesses before all resources. -/\ntheorem replayEnvelope_monomial : Bound replayEnvelope := by\n  apply add_bound (show Bound envelope from envelope_monomial)\n  unfold replayTail prefixPolynomial featurePolynomial squaresPolynomial\n    SemiprimeD1PacketReplayBudget.stepBudget SemiprimeD1PacketReplayBudget.packetLength\n  dsimp only\n  boundArithmetic\n\n/-- Fixed source supplier factor; the actual mode count is kept outside. -/\ndef sourceFactor (S : ℕ) : ℕ :=\n  replayEnvelope S+SemiprimeD1WeightedCardinality.modeFactor (S*S) S+\n    SemiprimeD1WeightedCardinality.modeOverhead (S*S) S+8*S+20\n\n/-- Nonnegative actual supplier dimensions give polynomial cost per ACTUAL mode,\nincluding the original source producer each time a caller retains it. -/\ntheorem source_budget (n F r a M u i p packets P modes S : ℕ)\n    (hr0 : 0 < r) (hn : n ≤ S) (hF : F ≤ S) (hr : r ≤ S) (ha : a ≤ S)\n    (hM : M ≤ S) (hu : u ≤ S) (hi : i ≤ S) (hp : p ≤ S)\n    (hL : r^a ≤ S) (hpackets : packets ≤ S) (hP : P ≤ S) (htiles : 2^(i+1) ≤ S) :\n    SemiprimeD1PhysicalSourceBudget.budget n F r a M u i p packets P modes ≤\n      sourceFactor S*(modes+1) := by\n  have hb:=replay_budget n F r a M S hr0 hn hF hr ha hM hL\n  have hslots:=Nat.mul_le_mul hpackets htiles\n  have hfactor : SemiprimeD1WeightedCardinality.modeFactor (packets*2^(i+1)) P ≤\n      SemiprimeD1WeightedCardinality.modeFactor (S*S) S := by\n    unfold SemiprimeD1WeightedCardinality.modeFactor\n    gcongr\n  have hover : SemiprimeD1WeightedCardinality.modeOverhead (packets*2^(i+1)) P ≤\n      SemiprimeD1WeightedCardinality.modeOverhead (S*S) S := by\n    unfold SemiprimeD1WeightedCardinality.modeOverhead\n    gcongr\n  have hmode:=Nat.mul_le_mul_right modes hfactor\n  unfold SemiprimeD1PhysicalSourceBudget.budget sourceFactor\n  nlinarith only [hb,hmode,hover,hM,hpackets,ha,hi,hu,hp]\n\n/-- Fixed monomial growth of the actual source factor, no cost-growth premise. -/\ntheorem sourceFactor_monomial : Bound sourceFactor := by\n  unfold sourceFactor\n  apply add_bound\n  · apply add_bound\n    · apply add_bound\n      · apply add_bound replayEnvelope_monomial\n        unfold SemiprimeD1WeightedCardinality.modeFactor\n        boundArithmetic\n      · unfold SemiprimeD1WeightedCardinality.modeOverhead\n        boundArithmetic\n    · boundArithmetic\n  · boundArithmetic\n\nend RiemannGaussian.SemiprimeD1PhysicalSourcePolynomial\n","RiemannGaussian.SemiprimeD1PublicPackingReady":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PackingReady\nimport RiemannGaussian.SemiprimeMacroParameters\n\n/-! # Actual public macro dimensions fit the one global D.1 degree cap\nInteger powers retain the original scope constant and the literal public scale.\nThis is a dimension/packing theorem, not a completed recursive bit clock.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1PublicPackingReady\nopen SemiprimeD1PackingReady\n\n/-- Fixed public root-size scale, before all inputs. -/\ndef scale (ell : ℕ) : ℕ := 2^20*ell\n\n/-- The literal rounded degree cap has its original eighteenth-power size. -/\ntheorem degreeCap_power (s : ℕ) : s^18 ≤ (degreeCap s)^20 := by\n  have hs : s ≤ 2^logarithm s :=\n    (show s ≤ s+2 by omega).trans (Nat.le_pow_clog (by decide : 1<2) _)\n  have he : 18*logarithm s ≤ ((9*logarithm s+9)/10)*20 := by omega\n  calc\n    _ ≤ (2^logarithm s)^18 := Nat.pow_le_pow_left hs _\n    _ = 2^(18*logarithm s) := by rw [← pow_mul];congr 1;omega\n    _ ≤ 2^(((9*logarithm s+9)/10)*20) := Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) he\n    _ = _ := by rw [degreeCap,← pow_mul]\n\n/-- Every original fourth-power scope estimate fits the literal global cap. -/\ntheorem scope_of_fourth (ell degree : ℕ) (hell : 0<ell)\n    (hd : degree^4 ≤ 512^4*ell^3) : degree ≤ degreeCap (scale ell) := by\n  have hp := Nat.pow_le_pow_left hd 5\n  have htwenty : degree^20 ≤ 512^20*ell^15 := by\n    simpa only [mul_pow,← pow_mul] using hp\n  have hel : ell^15 ≤ ell^18 := Nat.pow_le_pow_right hell (by decide)\n  have hc : (512:ℕ)^20 ≤ (2^20)^18 := by norm_num\n  have hcap := degreeCap_power (scale ell)\n  have hfinal : degree^20 ≤ degreeCap (scale ell)^20 :=\n    htwenty.trans ((Nat.mul_le_mul hc hel).trans (by simpa only [scale,mul_pow] using hcap))\n  exact (Nat.pow_le_pow_iff_left (by decide : (20:ℕ)≠0)).mp hfinal\n\n/-- Actual equality-subdivided public macro scopes fit at every positive input width. -/\ntheorem actual_scope (ell : ℕ) (hell : 0<ell) :\n    SemiprimeMacroParameters.scopeBound ell ≤ degreeCap (scale ell) :=\n  scope_of_fourth ell _ hell (SemiprimeMacroParameters.scopeBound_fourth_le hell)\n\n/-- Actual public equality-graph variable count fits the same fixed root size. -/\ntheorem actual_size (ell : ℕ) (hell : 0<ell) :\n    SemiprimeMacroParameters.variableCount ell ≤ scale ell := by\n  exact (SemiprimeMacroParameters.variableCount_le hell).trans\n    (Nat.mul_le_mul_right ell (by norm_num : 6400≤2^20))\n\nend RiemannGaussian.SemiprimeD1PublicPackingReady\n","RiemannGaussian.SemiprimeD1RecoveryRowsBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryNodeBitsBounds\nimport RiemannGaussian.SemiprimeD1RecoveryRowsRun\n\n/-! # Actual original-grid physical canonical-row cache\nEvery node is acquired by the physical constructor, including inactive nodes\nbefore filtering. Only native node/index labels are metadata; canonical signed\nnumerator and positive-denominator payloads are actual copied Boolean words.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1RecoveryRowsBits\nopen SemiprimeRationalBits SemiprimeBitArithmetic SemiprimeSourceMemoryBits\nopen SemiprimeD1RecoveryScalarRun SemiprimeD1RecoveryWeightRun\nopen SemiprimeD1WireKernelOriginal SemiprimeD1TaperedLoss SemiprimeD1JetRecoveryGrid\n\n/-- One physical canonical row with typed original indexing metadata. -/\nstructure Row where\n  /-- Original grid node label, native metadata. -/\n  node : ℕ\n  /-- Original retained coefficient index, native metadata. -/\n  index : ℕ\n  /-- Actual physical canonical weight payload. -/\n  word : RationalWord\n\n/-- Actual physical canonical rows and distinctly retained reports. -/\nstructure Report where\n  /-- Original node-major/index-major physical rows. -/\n  rows : List Row\n  /-- Actual rational arithmetic and physical payload copies. -/\n  clock : ℕ\n  /-- Typed indexing/valuation/width/control stages. -/\n  metadataWork : ℕ\n\n/-- Copy every actual canonical payload once while assigning original local indices. -/\ndef pack (node : ℕ) : ℕ → List RationalWord → Report\n  | _,[] => ⟨[],1,1⟩\n  | index,x::xs =>\n    let current:=copyWord x\n    let tail:=pack node (index+1) xs\n    ⟨⟨node,index,current.word⟩::tail.rows,current.clock+tail.clock+3,tail.metadataWork+3⟩\n\n/-- Acquire every original physical node before the original active-row filter. -/\ndef gather (a M u : ℕ) : List (Fin (size a)) → Report\n  | [] => ⟨[],1,1⟩\n  | t::ts =>\n    let current:=SemiprimeD1RecoveryNodeBits.acquire a M u t\n    let tail:=gather a M u ts\n    if t.val=center a ∨ current.retained=0 then\n      ⟨tail.rows,current.clock+tail.clock+3,current.metadataWork+tail.metadataWork+4⟩\n    else\n      let rows:=pack t.val 0 current.words\n      ⟨rows.rows++tail.rows,current.clock+tail.clock+rows.clock+3,\n        current.metadataWork+tail.metadataWork+rows.metadataWork+2*rows.rows.length+6⟩\n\n/-- ORIGINAL-input full physical canonical row acquisition; no row/word/count supplier. -/\ndef acquire (a M u : ℕ) : Report :=\n  let nodes:=SemiprimeD1RecoveryRowsRun.nodeIndices a\n  let rows:=gather a M u nodes.value\n  ⟨rows.rows,rows.clock+3,nodes.work+rows.metadataWork+3⟩\n\n/-- Proof-only scalar view; the runtime constructor never calls this decoder. -/\ndef view (rows : List Row) : List (ℕ×ℕ×ℤ×ℕ) :=\n  rows.map fun r => (r.node,r.index,r.word.numerator.value,bitValue r.word.denominator)\n\n/-- Original labels applied to canonical component pairs, for proof comparison. -/\ndef tag (node : ℕ) : ℕ → List (ℤ×ℕ) → List (ℕ×ℕ×ℤ×ℕ)\n  | _,[] => []\n  | index,(n,d)::xs => (node,index,n,d)::tag node (index+1) xs\n\n/-- Canonical views preserve actual concatenation order. -/\ntheorem view_append (xs ys : List Row) : view (xs++ys)=view xs++view ys := by\n  simp only [view,List.map_append]\n\n/-- Actual deep payload copying preserves exact canonical components and order. -/\ntheorem pack_view (node index : ℕ) (words : List RationalWord) :\n    view (pack node index words).rows=\n      tag node index (words.map (fun x => (x.numerator.value,bitValue x.denominator))) := by\n  induction words generalizing index with\n  | nil => rfl\n  | cons x xs ih =>\n    simp only [view] at ih\n    simp only [pack,view,List.map_cons,copyWord_word,tag,ih]\n\n/-- Native original canonical records have the same precise index traversal. -/\ntheorem tag_native (node index : ℕ) (rows : List CanonicalRow) :\n    tag node index (rows.map (fun r => (r.numerator,r.denominator)))=\n      (List.range rows.length).map fun j =>\n        let r:=(rows[j]?).getD ⟨0,1⟩\n        (node,index+j,r.numerator,r.denominator) := by\n  induction rows generalizing index with\n  | nil => rfl\n  | cons r rows ih =>\n    simp only [List.map_cons,tag,List.length_cons,List.range_succ_eq_map,List.map_cons,\n      List.getElem?_cons_zero,Option.getD_some,Nat.add_zero,List.map_map,Function.comp_def,\n      List.getElem?_cons_succ,ih,Nat.add_left_comm,Nat.add_comm]\n\n/-- The original acquired retained count is computed, not supplied as row advice. -/\ntheorem native_retained (a M u : ℕ) (t : Fin (size a)) :\n    (SemiprimeD1RecoveryWeightRun.acquire a M u t).data.retained=nodeMultiplicity a (height M u) u t.val := by\n  rw [SemiprimeD1RecoveryWeightRun.acquire_data]\n  rfl\n\n/-- Full actual physical row-cache traversal refines the EXACT frozen native\nrow constructor, including original active-node and local-index order. -/\ntheorem gather_view (a M u : ℕ) (ts : List (Fin (size a))) (hM : u ≤ M) :\n    view (gather a M u ts).rows=\n      (SemiprimeD1RecoveryRowsRun.gather a M u ts).rows.map\n        (fun r => (r.node,r.index,r.numerator,r.denominator)) := by\n  induction ts with\n  | nil => rfl\n  | cons t ts ih =>\n    have he:=SemiprimeD1RecoveryNodeBitsCorrectness.acquire_canonical a M u t hM\n    have hr:=SemiprimeD1RecoveryNodeBits.acquire_retained a M u t\n    have hn:=native_retained a M u t\n    simp only [gather,SemiprimeD1RecoveryRowsRun.gather,hr,hn]\n    split_ifs\n    · exact ih\n    · rw [view_append,pack_view,he,tag_native,ih]\n      simp only [indices_value,List.map_append,List.map_map,Function.comp_def,Nat.zero_add]\n\n\n/-- ORIGINAL-input actual physical rows equal the original acquired canonical\ninteger records. No native canonical-field extraction executes in this path. -/\ntheorem acquire_view (a M u : ℕ) (hM : u ≤ M) :\n    view (acquire a M u).rows=(SemiprimeD1RecoveryRowsRun.acquire a M u).rows.map\n      (fun r => (r.node,r.index,r.numerator,r.denominator)) := by\n  exact gather_view a M u (SemiprimeD1RecoveryRowsRun.nodeIndices a).value hM\n\n/-- Actual copied payload widths and denominator legality are inherited physically. -/\ntheorem pack_good (node index : ℕ) (words : List RationalWord) (W : ℕ)\n    (hv : ∀x∈words,x.Valid) (hw : ∀x∈words,Width x W) :\n    (∀r∈(pack node index words).rows,r.word.Valid) ∧\n      (∀r∈(pack node index words).rows,Width r.word W) := by\n  induction words generalizing index with\n  | nil => exact ⟨by simp [pack],by simp [pack]⟩\n  | cons x xs ih =>\n    have old:=ih (index+1) (fun y hy => hv y (List.mem_cons_of_mem _ hy))\n      (fun y hy => hw y (List.mem_cons_of_mem _ hy))\n    constructor <;> intro r hr <;> simp only [pack,List.mem_cons,copyWord_word] at hr\n    · rcases hr with rfl|hr\n      · exact hv x List.mem_cons_self\n      · exact old.1 r hr\n    · rcases hr with rfl|hr\n      · exact hw x List.mem_cons_self\n      · exact old.2 r hr\n\n/-- Every actual full-grid physical row has the original internally derived width. -/\ntheorem gather_good (a M u : ℕ) (ts : List (Fin (size a))) (hM : u ≤ M) :\n    (∀r∈(gather a M u ts).rows,r.word.Valid) ∧\n      (∀r∈(gather a M u ts).rows,Width r.word (SemiprimeD1RecoveryNodeBits.width a M)) := by\n  induction ts with\n  | nil => exact ⟨by simp [gather],by simp [gather]⟩\n  | cons t ts ih =>\n    have cur:=SemiprimeD1RecoveryNodeBitsCorrectness.acquire_correct a M u t hM\n    have current:=pack_good t.val 0 (SemiprimeD1RecoveryNodeBits.acquire a M u t).words\n      (SemiprimeD1RecoveryNodeBits.width a M) cur.2.1 cur.2.2.1\n    simp only [gather]\n    split_ifs\n    · exact ih\n    · constructor <;> intro r hr <;> rcases List.mem_append.mp hr with hh|hh\n      · exact current.1 r hh\n      · exact ih.1 r hh\n      · exact current.2 r hh\n      · exact ih.2 r hh\n\n/-- ORIGINAL full physical canonical cache legality/width, with no Fits advice. -/\ntheorem acquire_good (a M u : ℕ) (hM : u ≤ M) :\n    (∀r∈(acquire a M u).rows,r.word.Valid) ∧\n      (∀r∈(acquire a M u).rows,Width r.word (SemiprimeD1RecoveryNodeBits.width a M)) :=\n  gather_good a M u (SemiprimeD1RecoveryRowsRun.nodeIndices a).value hM\n\n/-- Actual canonical payload packing stores one row per computed weight. -/\ntheorem pack_length (node index : ℕ) (words : List RationalWord) :\n    (pack node index words).rows.length=words.length := by\n  induction words generalizing index with\n  | nil => rfl\n  | cons x xs ih => simp only [pack,List.length_cons,ih]\n\n/-- Every actual repeated payload bit copy is charged from the source width. -/\ntheorem pack_clock (node index : ℕ) (words : List RationalWord) (W : ℕ)\n    (hw : ∀x∈words,Width x W) : (pack node index words).clock ≤ words.length*(8*W+9)+1 := by\n  induction words generalizing index with\n  | nil => simp [pack]\n  | cons x xs ih =>\n    have hc:=copyWord_clock x W (hw x List.mem_cons_self)\n    have ht:=ih (index+1) (fun y hy => hw y (List.mem_cons_of_mem _ hy))\n    simp only [pack,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Exact native row-label counter stages are retained distinctly. -/\ntheorem pack_metadataWork (node index : ℕ) (words : List RationalWord) :\n    (pack node index words).metadataWork=3*words.length+1 := by\n  induction words generalizing index with\n  | nil => rfl\n  | cons x xs ih => simp only [pack,List.length_cons,ih]; omega\n\n/-- The original physical node stores exactly its original retained multiplicity. -/\ntheorem node_length (a M u : ℕ) (t : Fin (size a)) (hM : u ≤ M) :\n    (SemiprimeD1RecoveryNodeBits.acquire a M u t).words.length=nodeMultiplicity a (height M u) u t.val := by\n  have h:=congrArg List.length (SemiprimeD1RecoveryNodeBitsCorrectness.acquire_correct a M u t hM).1\n  simpa only [List.length_map,Array.length_toList,SemiprimeD1JetRecoveryWeights.acquire_weights_size] using h\n\n/-- Literal actual physical per-node row-cache report envelope. -/\ndef nodeBudget (a M : ℕ) : ℕ :=\n  SemiprimeD1RecoveryNodeBitsBounds.budget a M (SemiprimeD1RecoveryNodeBits.width a M)+\n    SemiprimeD1RecoveryNodeBits.m M*(8*SemiprimeD1RecoveryNodeBits.width a M+9)+4\n\n/-- Every actual original node producer and copied canonical payload is retained. -/\ntheorem gather_clock (a M u : ℕ) (ts : List (Fin (size a))) (hM : u ≤ M) :\n    (gather a M u ts).clock ≤ ts.length*nodeBudget a M+1 := by\n  induction ts with\n  | nil => simp [gather]\n  | cons t ts ih =>\n    have cc:=SemiprimeD1RecoveryNodeBitsBounds.acquire_clock a M u t hM\n    have cur:=SemiprimeD1RecoveryNodeBitsCorrectness.acquire_correct a M u t hM\n    have cp:=pack_clock t.val 0 (SemiprimeD1RecoveryNodeBits.acquire a M u t).words\n      (SemiprimeD1RecoveryNodeBits.width a M) cur.2.2.1\n    have hl : (SemiprimeD1RecoveryNodeBits.acquire a M u t).words.length ≤ SemiprimeD1RecoveryNodeBits.m M :=\n      (node_length a M u t hM).le.trans (SemiprimeD1WeightPrecision.nodeMultiplicity_le a M u t.val hM)\n    have hp:=Nat.mul_le_mul_right (8*SemiprimeD1RecoveryNodeBits.width a M+9) hl\n    simp only [gather]\n    split_ifs <;> dsimp only\n    · simp only [List.length_cons,Nat.add_mul,Nat.one_mul,nodeBudget]\n      simp only [nodeBudget] at ih\n      omega\n    · simp only [List.length_cons,Nat.add_mul,Nat.one_mul,nodeBudget]\n      simp only [nodeBudget] at ih\n      omega\n\n/-- Complete physical original canonical-row cache arithmetic budget. -/\ndef budget (a M : ℕ) : ℕ := size a*nodeBudget a M+4\n\n/-- The ORIGINAL full physical row acquisition has a closed arithmetic/copy\nreport with no source coefficient, height, Fits or callback-cost advice. -/\ntheorem acquire_clock (a M u : ℕ) (hM : u ≤ M) : (acquire a M u).clock ≤ budget a M := by\n  have h:=gather_clock a M u (SemiprimeD1RecoveryRowsRun.nodeIndices a).value hM\n  have hn : (SemiprimeD1RecoveryRowsRun.nodeIndices a).value.length=size a := by\n    have hh:=congrArg List.length (SemiprimeD1RecoveryRowsRun.nodeIndices_values a)\n    simpa only [List.length_map,List.length_range] using hh\n  simp only [acquire,budget]\n  rw [hn] at h\n  omega\n\n/-- Actual full physical cache length is bounded from original multiplicities. -/\ntheorem acquire_length (a M u : ℕ) (hM : u ≤ M) :\n    (acquire a M u).rows.length ≤ size a*(4*M) := by\n  have he:=congrArg List.length (acquire_view a M u hM)\n  simp only [view,List.length_map] at he\n  have hl:=SemiprimeD1RecoveryRowsRun.acquire_length a M u\n  have hm:=Nat.mul_le_mul_left (size a) (SemiprimeD1WeightPrecision.height_mul_le M u hM)\n  omega\n\nend RiemannGaussian.SemiprimeD1RecoveryRowsBits\n","RiemannGaussian.SemiprimeD1StackAllDescriptorRecordPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackAllDescriptorRecordWiring\nimport RiemannGaussian.SemiprimeD1StackAllDescriptorRecordInventory\n/-! # Paid tag copy and literal eighteen-state physical constructor decoder -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 1000000\nnamespace RiemannGaussian.SemiprimeD1StackAllDescriptorRecordPrimitives\nopen SemiprimeD1StackAllDescriptorRecord SemiprimeD1StackAllDescriptorRecordWiring\nopen SemiprimeD1StackProcedureTrace\n/-- Consecutive fragments execute the same fixed physical source and retain outer returns. -/\ntheorem compose {m n : Nat} {pc mid next : Label} {before middle after : Stack→List Bool}\n    (h : Runs program m pc before mid middle) (g : Runs program n mid middle next after) :\n    Runs program (m+n) pc before next after :=runs_trans program _ _ _ _ _ _ _ _ h g\n/-- Actual preserving tag copy reads the original field and fills only the private reader. -/\ntheorem copy_tag (d : Stack→List Bool) (hr : d tagReader=[]) (hs : d copyScratch=[]) :\n    Runs program (5*(d (source 1)).length+4) (.inl .start) d (.inl (.decode 0))\n      (Function.update d tagReader (d (source 1))) :=by\n  apply included_call program copyStack (fun pc=>.inr (.inl pc)) copyStack_injective\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (.inl .start) (.inl (.decode 0)) rfl (5*(d (source 1)).length+3)\n    (SemiprimeD1StackCopy.state 0 none (d (source 1)) [] [])\n    (SemiprimeD1StackCopy.done (d (source 1)) (d (source 1)++[]))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words (d (source 1)) [] none\n  · constructor\n    · intro k;fin_cases k <;> simp [copyStack,SemiprimeD1StackCopy.state,SemiprimeD1StackCopy.payload,hr,hs]\n    · intro k _;rfl\n  · constructor\n    · intro k\n      fin_cases k\n      · change Function.update d tagReader (d (source 1)) (source 1)=d (source 1)\n        exact Function.update_of_ne (by decide) _ _\n      · change Function.update d tagReader (d (source 1)) tagReader=d (source 1)++[]\n        simp only [Function.update_same,List.append_nil]\n      · change Function.update d tagReader (d (source 1)) copyScratch=[]\n        rw [Function.update_of_ne (by decide : copyScratch≠tagReader)]\n        exact hs\n    · intro k hk\n      have hne:tagReader≠k:=hk 1\n      exact Function.update_of_ne (Ne.symm hne) _ _\n/-- Each copied true marker is physically consumed by one actual transition. -/\ntheorem tag_prefix (n i : Nat) (hi:i+n<18) (d : Stack→List Bool) (tail : List Bool) :\n    Runs program n (.inl (.decode ⟨i,by omega⟩))\n      (Function.update d tagReader (List.replicate n true++tail))\n      (.inl (.decode ⟨i+n,hi⟩)) (Function.update d tagReader tail) :=by\n  induction n generalizing i with\n  | zero=>simpa only [List.replicate_zero,List.nil_append,Nat.add_zero] using\n      runs_refl program (.inl (.decode ⟨i,hi⟩)) (Function.update d tagReader tail)\n  | succ n ih=>\n    have hit:i<17:=by omega\n    have hc:program (.inl (.decode ⟨i,by omega⟩))=.base (.pop tagReader (dispatch ⟨i,by omega⟩)\n      (.inl .abort) (.inl (.decode ⟨i+1,by omega⟩))):=by simp only [program,nextDecode,dite_eq_left hit]\n    have h0:Runs program 1 (.inl (.decode ⟨i,by omega⟩))\n        (Function.update d tagReader (List.replicate (n+1) true++tail))\n        (.inl (.decode ⟨i+1,by omega⟩)) (Function.update d tagReader (List.replicate n true++tail)):=by\n      apply one_base program _ _ _ _ _ hc\n      · rfl\n      · change Function.update (Function.update d tagReader (List.replicate (n+1) true++tail)) tagReader\n          (List.replicate (n+1) true++tail).tail=_\n        simp only [List.replicate_succ,List.cons_append,List.tail_cons,Function.update_idem]\n    have h1:=ih (i+1) (by omega)\n    have he:(⟨i+1+n,by omega⟩:Fin 18)=⟨i+(n+1),hi⟩:=by apply Fin.ext;change i+1+n=i+(n+1);omega\n    rw [he] at h1\n    simpa only [show 1+n=n+1 by omega] using compose h0 h1\n/-- Physical EOF dispatch occurs only after the complete copied original tag is consumed. -/\ntheorem tag_decode (code : Fin 18) (d : Stack→List Bool) :\n    Runs program (code.val+1) (.inl (.decode 0)) (Function.update d tagReader (List.replicate code.val true))\n      (dispatch code) (Function.update d tagReader []) :=by\n  have h0:=tag_prefix code.val 0 (by omega) d []\n  simp only [List.append_nil,Nat.zero_add] at h0\n  have h1:Runs program 1 (.inl (.decode code)) (Function.update d tagReader [])\n      (dispatch code) (Function.update d tagReader []):=by\n    apply one_base program _ _ (.pop tagReader (dispatch code) (.inl .abort) (nextDecode code)) _ _ rfl\n    · rfl\n    · change Function.update (Function.update d tagReader []) tagReader []=_\n      simp only [Function.update_idem]\n  exact compose h0 h1\n/-- Real acquisition-free frontend trace: copy actual raw tag, consume every marker,\nthen select exactly one literal family entry, preserving all original fields. -/\ntheorem dispatch_run (raw : Fin 6→List Bool) (bank hist out : List Bool) (code : Fin 18)\n    (htag:raw 1=List.replicate code.val true) :\n    Runs program (6*code.val+5) (.inl .start) (cleanData raw bank hist out)\n      (dispatch code) (cleanData raw bank hist out) :=by\n  have h0:=copy_tag (cleanData raw bank hist out) rfl rfl\n  change Runs program (5*(raw 1).length+4) _ _ _ (Function.update (cleanData raw bank hist out) tagReader (raw 1)) at h0\n  rw [htag,List.length_replicate] at h0\n  have h1:=tag_decode code (cleanData raw bank hist out)\n  have he:Function.update (cleanData raw bank hist out) tagReader []=cleanData raw bank hist out:=by\n    funext k\n    by_cases hk:k=tagReader\n    · subst k;rfl\n    · exact Function.update_of_ne hk _ _\n  rw [he] at h1\n  convert compose h0 h1 using 1;omega\nend RiemannGaussian.SemiprimeD1StackAllDescriptorRecordPrimitives\n","RiemannGaussian.SemiprimeD1StackAssignmentLoopExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackAssignmentLoop\n\n/-! # Literal body and increment calls inside the enumeration loop -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackAssignmentLoopExecution\nopen SemiprimeD1StackAssignmentLoop\nlocal notation \"ctl\" => SemiprimeD1StackAssignmentLoop.control\nnamespace M\nexport SemiprimeD1StackMultiplierLink (Rel DataRel PcRel instruction run_rel data_initial)\nend M\nnamespace B\nexport SemiprimeD1StackBytecode (State run)\nend B\n\n/-- A physical write changes precisely one literal data stack. -/\n@[simp] theorem update_data (word scratch next history output xs : List Bool) (k : Stack) :\n    Function.update (data word scratch next history output) k xs=\n      data (if k=.word then xs else word) (if k=.scratch then xs else scratch)\n        (if k=.next then xs else next) (if k=.history then xs else history)\n        (if k=.output then xs else output) := by\n  funext j\n  cases k <;> cases j <;> simp [data]\n\n/-- A real call pushes its literal continuation before executing included code. -/\ntheorem component_call {K L : Type} [DecidableEq K]\n    (stack : K → Stack) (label : L → Label) (hinj : Function.Injective stack)\n    (component : L → SemiprimeD1StackBytecode.Instruction K L)\n    (hcode : ∀l,code (label l)=M.instruction stack label (component l))\n    (start resumeTo : Control) (entry : L)\n    (hstart : code (ctl start)=(.call (label entry) (ctl resumeTo)))\n    (input : Stack → List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) (m : ℕ) (result : B.State K L)\n    (hr : B.run component m ⟨some entry,none,fun k => input (stack k)⟩=some result) :\n    ∃resultState,C.run code (m+1) ⟨some (ctl start),flag,returned,input,frames⟩=some resultState ∧\n      M.Rel stack label input (ctl resumeTo) frames result resultState := by\n  let entered : C.State Stack Label := ⟨some (label entry),none,none,input,ctl resumeTo::frames⟩\n  have hs : C.run code 1 ⟨some (ctl start),flag,returned,input,frames⟩=some entered := by\n    simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,\n      SemiprimeD1StackCalls.execute,hstart,entered]\n  have hrel : M.Rel stack label input (ctl resumeTo) frames\n      ⟨some entry,none,fun k => input (stack k)⟩ entered :=\n    ⟨M.data_initial stack input,rfl,rfl⟩\n  obtain ⟨resultState,hf,hd⟩ := M.run_rel stack label hinj code component hcode input\n    (ctl resumeTo) frames m _ result entered hrel hr\n  refine ⟨resultState,?_,hd⟩\n  rw [show m+1=1+m by omega,SemiprimeD1StackReturnLink.run_add,hs,Option.bind_some,hf]\n\n/-- Reconstruct only finite flags around a proved literal data/PC/frame result. -/\ntheorem state_eq (c : C.State Stack Label) (pc : Label)\n    (word scratch next history output : List Bool) (frames : List Label)\n    (hp : c.pc=some pc) (hd : c.data=data word scratch next history output) (hf : c.frames=frames) :\n    c=state pc c.flag c.returned word scratch next history output frames := by\n  rcases c with ⟨l,flag,returned,store,fs⟩\n  dsimp at hp hd hf\n  cases hp\n  cases hd\n  cases hf\n  rfl\n\n/-- Actual included body logs one assignment and returns with the argument restored. -/\ntheorem body_call (word history output : List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) :\n    ∃m≤6*(2*word.length+3)+1,∃f r,C.run code m\n      (state (ctl .bodyCall) flag returned word [] [] history output frames)=\n      some (state (ctl .incCall) f r word [] []\n        ((true::SemiprimeSourceHistogramKeyBits.frame word []).reverse++history) output frames) := by\n  obtain ⟨m,hm,hbody⟩ := SemiprimeD1StackAssignmentBody.body_run word history\n  have hprojection : (fun k => data word [] [] history output (bodyStack k))=\n      SemiprimeD1StackAssignmentBody.contents word [] history := by\n    funext k\n    cases k <;> rfl\n  rw [←hprojection] at hbody\n  obtain ⟨resultState,hr,hrel⟩ := component_call bodyStack body bodyStack_injective A.code body_code\n    .bodyCall .incCall A.entry rfl (data word [] [] history output) flag returned frames m _ hbody\n  have hd : resultState.data=data word [] []\n      ((true::SemiprimeSourceHistogramKeyBits.frame word []).reverse++history) output := by\n    funext k\n    cases k with\n    | word => exact hrel.1.1 .word\n    | scratch => exact hrel.1.1 .scratch\n    | next => exact hrel.1.2 .next (by intro k; cases k <;> simp [bodyStack])\n    | history => exact hrel.1.1 .history\n    | output => exact hrel.1.2 .output (by intro k; cases k <;> simp [bodyStack])\n  have hp : resultState.pc=some (ctl .incCall) ∧ resultState.frames=frames := hrel.2\n  refine ⟨m+1,by omega,resultState.flag,resultState.returned,?_⟩\n  exact hr.trans (congrArg some (state_eq resultState _ _ _ _ _ _ _ hp.1 hd hp.2))\n\n/-- Actual included incrementer returns physical overflow/wrapped bytes, not an answer. -/\ntheorem increment_call (word history output : List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) :\n    ∃m≤5*(2*word.length+3)+1,∃f r,C.run code m\n      (state (ctl .incCall) flag returned word [] [] history output frames)=\n      some (state (ctl .afterInc) f r [] []\n        (SemiprimeD1StackIncrement.overflow word::SemiprimeD1StackIncrement.wrapped word)\n        history output frames) := by\n  obtain ⟨m,hm,hinc⟩ := SemiprimeD1StackIncrementBytecode.increment_run word []\n  have hprojection : (fun k => data word [] [] history output (incStack k))=\n      SemiprimeD1TensorTapeFieldMachine.contents word [] [] := by\n    funext k\n    cases k <;> rfl\n  rw [←hprojection] at hinc\n  obtain ⟨resultState,hr,hrel⟩ := component_call incStack increment incStack_injective I.code increment_code\n    .incCall .afterInc I.entry rfl (data word [] [] history output) flag returned frames m _ hinc\n  have hd : resultState.data=data [] []\n      (SemiprimeD1StackIncrement.overflow word::SemiprimeD1StackIncrement.wrapped word) history output := by\n    funext k\n    cases k with\n    | word => exact hrel.1.1 .input\n    | scratch => exact hrel.1.1 .scratch\n    | next => simpa [incStack,data,SemiprimeD1TensorTapeFieldMachine.contents] using hrel.1.1 .output\n    | history => exact hrel.1.2 .history (by intro k; cases k <;> simp [incStack])\n    | output => exact hrel.1.2 .output (by intro k; cases k <;> simp [incStack])\n  have hp : resultState.pc=some (ctl .afterInc) ∧ resultState.frames=frames := hrel.2\n  refine ⟨m+1,by omega,resultState.flag,resultState.returned,?_⟩\n  exact hr.trans (congrArg some (state_eq resultState _ _ _ _ _ _ _ hp.1 hd hp.2))\n\n/-- Actual interpreter paths compose with every transition retained. -/\ntheorem run_trans {m n : ℕ} {a b c : C.State Stack Label}\n    (h : C.run code m a=some b) (g : C.run code n b=some c) :\n    C.run code (m+n) a=some c := by\n  rw [SemiprimeD1StackReturnLink.run_add,h,Option.bind_some,g]\n\n/-- Physically move the wrapped word out of the incrementer result stack. -/\ntheorem move_drain (xs rev history output : List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) :\n    C.run code (2*xs.length+1) (state (ctl .moveDrain) flag returned [] rev xs history output frames)=\n      some (state (ctl .restore) none returned [] (xs.reverse++rev) [] history output frames) := by\n  induction xs generalizing rev flag with\n  | nil =>\n    simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,\n      SemiprimeD1StackCalls.execute,SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data]\n  | cons b bs ih =>\n    have hs : C.run code 2 (state (ctl .moveDrain) flag returned [] rev (b::bs) history output frames)=\n        some (state (ctl .moveDrain) (some b) returned [] (b::rev) bs history output frames) := by\n      cases b <;> simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,\n        SemiprimeD1StackCalls.execute,SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data,\n        Function.iterate_succ_apply]\n    rw [show 2*(b::bs).length+1=2+(2*bs.length+1) by simp; omega,\n      SemiprimeD1StackReturnLink.run_add,hs,Option.bind_some]\n    simpa [List.reverse_cons,List.append_assoc] using ih (b::rev) (some b)\n\n/-- Restore every wrapped digit to the next actual body call. -/\ntheorem move_restore (xs word history output : List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) :\n    C.run code (2*xs.length+1) (state (ctl .restore) flag returned word xs [] history output frames)=\n      some (state (ctl .bodyCall) none returned (xs.reverse++word) [] [] history output frames) := by\n  induction xs generalizing word flag with\n  | nil =>\n    simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,\n      SemiprimeD1StackCalls.execute,SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data]\n  | cons b bs ih =>\n    have hs : C.run code 2 (state (ctl .restore) flag returned word (b::bs) [] history output frames)=\n        some (state (ctl .restore) (some b) returned (b::word) bs [] history output frames) := by\n      cases b <;> simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,\n        SemiprimeD1StackCalls.execute,SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data,\n        Function.iterate_succ_apply]\n    rw [show 2*(b::bs).length+1=2+(2*bs.length+1) by simp; omega,\n      SemiprimeD1StackReturnLink.run_add,hs,Option.bind_some]\n    simpa [List.reverse_cons,List.append_assoc] using ih (b::word) (some b)\n\n/-- Real final log reversal, including the final halt and return-frame preservation. -/\ntheorem reverse_history (xs output next : List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) :\n    C.run code (2*xs.length+2) (state (ctl .reverse) flag returned [] [] next xs output frames)=\n      some ⟨none,none,none,data [] [] next [] (xs.reverse++output),frames⟩ := by\n  induction xs generalizing flag output with\n  | nil =>\n    simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,\n      SemiprimeD1StackCalls.execute,SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data,Function.iterate_succ_apply]\n  | cons b bs ih =>\n    have hs : C.run code 2 (state (ctl .reverse) flag returned [] [] next (b::bs) output frames)=\n        some (state (ctl .reverse) (some b) returned [] [] next bs (b::output) frames) := by\n      cases b <;> simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,\n        SemiprimeD1StackCalls.execute,SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data,\n        Function.iterate_succ_apply]\n    rw [show 2*(b::bs).length+2=2+(2*bs.length+2) by simp; omega,\n      SemiprimeD1StackReturnLink.run_add,hs,Option.bind_some]\n    simpa [List.reverse_cons,List.append_assoc] using ih (b::output) (some b)\n\n\n/-- The final wrapped word is physically cleared after overflow. -/\ntheorem clear_next (xs history output : List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) :\n    C.run code (xs.length+1) (state (ctl .clearNext) flag returned [] [] xs history output frames)=\n      some (state (ctl .finish) none returned [] [] [] history output frames) := by\n  induction xs generalizing flag with\n  | nil =>\n    simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,SemiprimeD1StackCalls.execute,\n      SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data]\n  | cons b bs ih =>\n    have hs : C.run code 1 (state (ctl .clearNext) flag returned [] [] (b::bs) history output frames)=\n        some (state (ctl .clearNext) (some b) returned [] [] bs history output frames) := by\n      cases b <;> simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,\n        SemiprimeD1StackCalls.execute,SemiprimeD1StackBytecode.choose,code,state,\n        SemiprimeD1StackAssignmentLoop.control,data]\n    convert run_trans hs (ih (some b)) using 1\n    simp\n    all_goals (congr 1; omega)\n\n/-- A false physical overflow bit returns the wrapped word to the next body call. -/\ntheorem continue_run (xs history output : List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) :\n    C.run code (4*xs.length+3)\n      (state (ctl .afterInc) flag returned [] [] (false::xs) history output frames)=\n      some (state (ctl .bodyCall) none returned xs [] [] history output frames) := by\n  have hs : C.run code 1 (state (ctl .afterInc) flag returned [] [] (false::xs) history output frames)=\n      some (state (ctl .moveDrain) (some false) returned [] [] xs history output frames) := by\n    simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,SemiprimeD1StackCalls.execute,\n      SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data]\n  have hd := move_drain xs [] history output (some false) returned frames\n  have hr := move_restore (xs.reverse++[]) [] history output none returned frames\n  have h := run_trans hs (run_trans hd hr)\n  convert h using 1 <;> simp\n  all_goals (congr 1; omega)\n\n/-- True physical overflow clears leftovers and emits the entire framed log. -/\ntheorem finish_run (xs history output : List Bool) (flag : Option Bool) (returned : Option Label)\n    (frames : List Label) :\n    C.run code (xs.length+2*history.length+7)\n      (state (ctl .afterInc) flag returned [] [] (true::xs) history output frames)=\n      some ⟨none,none,none,data [] [] [] [] (history.reverse++false::output),frames⟩ := by\n  have hs : C.run code 1 (state (ctl .afterInc) flag returned [] [] (true::xs) history output frames)=\n      some (state (ctl .clearNext) (some true) returned [] [] xs history output frames) := by\n    simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,SemiprimeD1StackCalls.execute,\n      SemiprimeD1StackBytecode.choose,code,state,SemiprimeD1StackAssignmentLoop.control,data]\n  have hc := clear_next xs history output (some true) returned frames\n  have hf : C.run code 1 (state (ctl .finish) none returned [] [] [] history output frames)=\n      some (state (ctl .reverse) none returned [] [] [] (false::history) output frames) := by\n    simp [SemiprimeD1StackCalls.run,SemiprimeD1StackCalls.step,SemiprimeD1StackCalls.execute,\n      code,state,SemiprimeD1StackAssignmentLoop.control,data]\n  have hr := reverse_history (false::history) output [] none returned frames\n  have h := run_trans hs (run_trans hc (run_trans hf hr))\n  convert h using 1 <;> simp [List.reverse_cons,List.append_assoc]\n  all_goals (congr 1; omega)\n\nend RiemannGaussian.SemiprimeD1StackAssignmentLoopExecution\n","RiemannGaussian.SemiprimeD1StackAssignmentOrder":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackIncrement\nimport Mathlib.Data.List.Nodup\n\n/-! # Exact before-overflow assignment order\nAll natural/list expressions here are proof specifications. The finite loop\nexecutes physical overflow tests and never evaluates these counters or catalogues.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackAssignmentOrder\nopen SemiprimeD1StackIncrement (wrapped overflow)\nopen SemiprimeBitArithmetic (bitValue bitNat)\n\n/-- Number of assignments from this word through the last pre-overflow word. -/\ndef remaining (xs : List Bool) : ℕ := 2^xs.length-bitValue xs\n\n/-- Proof-only chronological specification of repeated wrapped increments. -/\ndef assignments : ℕ → List Bool → List (List Bool)\n  | 0,_ => []\n  | n+1,xs => xs::assignments n (wrapped xs)\n\n/-- No valid fixed-width word has zero assignments left before overflow. -/\ntheorem remaining_pos (xs : List Bool) : 0<remaining xs := by\n  have h := SemiprimeBitArithmetic.bitValue_lt_width xs\n  unfold remaining\n  omega\n\n/-- The overflow iteration is exactly the final remaining assignment. -/\ntheorem overflow_remaining (xs : List Bool) (h : overflow xs=true) : remaining xs=1 := by\n  have hv := SemiprimeD1StackIncrement.value_balance xs\n  have hb := SemiprimeBitArithmetic.bitValue_lt_width xs\n  simp only [h,bitNat,ite_true,Nat.mul_one] at hv\n  unfold remaining\n  omega\n\n/-- Before overflow the actual wrapped value increases by exactly one. -/\ntheorem wrapped_value_step (xs : List Bool) (h : overflow xs=false) :\n    bitValue (wrapped xs)=bitValue xs+1 := by\n  have hv := SemiprimeD1StackIncrement.value_balance xs\n  simpa [h,bitNat] using hv\n\n/-- The next actual word has exactly one fewer iteration left. -/\ntheorem remaining_step (xs : List Bool) (h : overflow xs=false) :\n    remaining (wrapped xs)+1=remaining xs := by\n  have hv := wrapped_value_step xs h\n  have hb := SemiprimeBitArithmetic.bitValue_lt_width xs\n  simp only [remaining,SemiprimeD1StackIncrement.wrapped_length,hv]\n  omega\n\n/-- Every prefix specification has its exact literal iteration length. -/\ntheorem assignments_length (n : ℕ) (xs : List Bool) : (assignments n xs).length=n := by\n  induction n generalizing xs with\n  | zero => rfl\n  | succ n ih => simp [assignments,ih]\n\n/-- All actual generated words retain the original fixed width. -/\ntheorem assignments_width (n : ℕ) (xs ys : List Bool) (h : ys∈assignments n xs) :\n    ys.length=xs.length := by\n  induction n generalizing xs with\n  | zero => simp [assignments] at h\n  | succ n ih =>\n    simp only [assignments,List.mem_cons] at h\n    rcases h with rfl|h\n    · rfl\n    · exact (ih (wrapped xs) h).trans (SemiprimeD1StackIncrement.wrapped_length xs)\n\n/-- Every nonwrapping chronological prefix enumerates consecutive natural values. -/\ntheorem assignments_values (n : ℕ) (xs : List Bool) (hn : n≤remaining xs) :\n    (assignments n xs).map bitValue=List.range' (bitValue xs) n := by\n  induction n generalizing xs with\n  | zero => simp [assignments]\n  | succ n ih =>\n    by_cases hz : n=0\n    · subst n; simp [assignments,List.range'_succ]\n    · have ho : overflow xs=false := by\n        cases h : overflow xs with\n        | false => rfl\n        | true => have hr := overflow_remaining xs h; omega\n      have hr := remaining_step xs ho\n      have ht : n≤remaining (wrapped xs) := by omega\n      simp only [assignments,List.map_cons,List.range'_succ]\n      rw [ih (wrapped xs) ht,wrapped_value_step xs ho]\n\n/-- Fixed-width binary values uniquely identify the literal padded word. -/\ntheorem word_value_injective (xs ys : List Bool) (hlen : xs.length=ys.length)\n    (hval : bitValue xs=bitValue ys) : xs=ys := by\n  induction xs generalizing ys with\n  | nil => cases ys <;> simp_all\n  | cons b bs ih =>\n    cases ys with\n    | nil => simp at hlen\n    | cons c cs =>\n      have hl : bs.length=cs.length := by simpa using hlen\n      cases b <;> cases c <;> simp [bitValue,bitNat] at hval ⊢\n      all_goals first | omega | exact ih cs hl (by omega)\n\n/-- The acquired zero word has its exact original width and value. -/\ntheorem zero_remaining (width : ℕ) : remaining (List.replicate width false)=2^width := by\n  have hv : bitValue (List.replicate width false)=0 := by\n    induction width with\n    | zero => rfl\n    | succ n ih => simp [List.replicate_succ,bitValue,bitNat,ih]\n  simp [remaining,hv]\n\n/-- Exactly 2^width distinct assignments occur before the first overflow. -/\ntheorem zero_nodup (width : ℕ) :\n    (assignments (2^width) (List.replicate width false)).Nodup := by\n  apply List.Nodup.of_map bitValue\n  rw [assignments_values _ _ (by rw [zero_remaining])]\n  exact List.nodup_range'\n\n/-- Every fixed-width original assignment appears, including width zero. -/\ntheorem zero_complete (width : ℕ) (ys : List Bool) :\n    ys∈assignments (2^width) (List.replicate width false) ↔ ys.length=width := by\n  constructor\n  · intro h\n    simpa using assignments_width (2^width) (List.replicate width false) ys h\n  · intro hlen\n    have hy : bitValue ys<2^width := by\n      simpa [hlen] using SemiprimeBitArithmetic.bitValue_lt_width ys\n    have hv := assignments_values (2^width) (List.replicate width false) (by rw [zero_remaining])\n    have hzero : bitValue (List.replicate width false)=0 := by\n      have hr := zero_remaining width\n      have hb := SemiprimeBitArithmetic.bitValue_lt_width (List.replicate width false)\n      simp only [remaining,List.length_replicate] at hr hb\n      omega\n    rw [hzero] at hv\n    have hm : bitValue ys∈(assignments (2^width) (List.replicate width false)).map bitValue := by\n      rw [hv]\n      simpa using hy\n    obtain ⟨word,hw,he⟩ := List.mem_map.mp hm\n    have hl : word.length=ys.length := by\n      have hh := assignments_width (2^width) (List.replicate width false) word hw\n      simpa [hlen] using hh\n    have heq := word_value_injective word ys hl he\n    simpa [heq] using hw\n\nend RiemannGaussian.SemiprimeD1StackAssignmentOrder\n","RiemannGaussian.SemiprimeD1StackBinarySquareRootArithmetic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib.Data.Nat.Sqrt\nimport RiemannGaussian.SemiprimeD1StackWordLessExecution\nimport RiemannGaussian.SemiprimeD1StackPackedRootMetadataEncoding\nimport RiemannGaussian.SemiprimeD1StackReduceExecution\n\n/-! # Binary greedy square root: arithmetic and actual raw-word specification\nThe recurrence tests exactly one descending power of two per input cell, plus\nthe leading power. It never materializes the value of the binary input in unary.\nThese are proof-side specifications; the finite machine is defined separately.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackBinarySquareRootArithmetic\nopen SemiprimeBitArithmetic\nopen SemiprimeD1StackPackedRootMetadataEncoding (baseWord base_value base_length)\n/-- One arithmetic candidate bit; no answer is a runtime operand. -/\ndef nextRoot (d n r : ℕ) : ℕ := if (r+2^n)^2 ≤ d then r+2^n else r\n/-- The n+1 descending candidate-bit tests, including the units bit. -/\ndef greedy (d : ℕ) : ℕ→ℕ→ℕ\n  | 0,r => nextRoot d 0 r\n  | n+1,r => greedy d n (nextRoot d (n+1) r)\n/-- A single test halves the remaining interval for the integer square root. -/\ntheorem nextRoot_bounds (d n r : ℕ) (hl : r^2 ≤ d)\n    (hu : d < (r+2^(n+1))^2) :\n    (nextRoot d n r)^2 ≤ d ∧ d < (nextRoot d n r+2^n)^2 := by\n  unfold nextRoot\n  split_ifs with h\n  · refine ⟨h,?_⟩\n    have he : r+2^n+2^n=r+2^(n+1) := by rw [pow_succ]; omega\n    rw [he]\n    exact hu\n  · exact ⟨hl,by omega⟩\n/-- Every candidate-bit test preserves a certified interval, without trial division. -/\ntheorem greedy_bounds (d n r : ℕ) (hl : r^2 ≤ d)\n    (hu : d < (r+2^(n+1))^2) :\n    (greedy d n r)^2 ≤ d ∧ d < (greedy d n r+1)^2 := by\n  induction n generalizing r with\n  | zero => simpa only [greedy,pow_zero] using nextRoot_bounds d 0 r hl hu\n  | succ n ih =>\n    have h:=nextRoot_bounds d (n+1) r hl hu\n    exact ih (nextRoot d (n+1) r) h.1 h.2\n/-- The interval invariant identifies the result with the ordinary integer sqrt. -/\ntheorem greedy_eq_sqrt (d n : ℕ) (hd : d < 2^n) : greedy d n 0=Nat.sqrt d := by\n  apply Nat.eq_sqrt'.2\n  apply greedy_bounds d n 0 (by simp)\n  have hp : 0 < 2^(n+1) := by positivity\n  have he : 2^n ≤ 2^(n+1) := by rw [pow_succ]; omega\n  have hq : 2^(n+1) ≤ (2^(n+1))^2 := by nlinarith\n  simpa only [zero_add] using hd.trans_le (he.trans hq)\n/-- The actual real-adder trial word, including raw padding. -/\ndef trial (r p : List Bool) : List Bool := (addBits r p false).bits\n/-- The actual multiplier word used by the physical comparison. -/\ndef square (r p : List Bool) : List Bool := (mulBits (trial r p) (trial r p)).bits\n/-- Exact actual comparison outcome: TRUE means reject the candidate. -/\ndef rejects (d r p : List Bool) : Bool := SemiprimeD1StackWordLessExecution.answer d (square r p)\n/-- The physical branch retains either the old raw root or the real-adder word. -/\ndef nextWord (d r p : List Bool) : List Bool := if rejects d r p then r else trial r p\n/-- Proof-side raw-word trace of exactly n+1 candidate-bit iterations. -/\ndef wordLoop (d : List Bool) : ℕ→List Bool→List Bool\n  | 0,r => nextWord d r (baseWord 0)\n  | n+1,r => wordLoop d n (nextWord d r (baseWord (n+1)))\n/-- The final physical reverse and high-zero trim produce a compact word. -/\ndef output (d : List Bool) : List Bool :=\n  SemiprimeD1StackReduceExecution.trimReverse (wordLoop d d.length []).reverse\n/-- The adder trial has the exact expected integer value. -/\ntheorem trial_value (r p : List Bool) : bitValue (trial r p)=bitValue r+bitValue p := by\n  simpa [trial,bitNat] using addBits_correct r p false\n/-- The actual square is computed from both real trial copies. -/\ntheorem square_value (r p : List Bool) : bitValue (square r p)=(bitValue r+bitValue p)^2 := by\n  rw [square,mulBits_correct,trial_value,pow_two]\n/-- Exact branch semantics follows from the physical subtractor borrow. -/\ntheorem rejects_true (d r p : List Bool) :\n    rejects d r p=true ↔ bitValue d < (bitValue r+bitValue p)^2 := by\n  rw [rejects,SemiprimeD1StackWordLessExecution.answer_true,square_value]\n/-- Both physical branches implement the arithmetic candidate-bit test. -/\ntheorem nextWord_value (d r : List Bool) (n : ℕ) :\n    bitValue (nextWord d r (baseWord n))=nextRoot (bitValue d) n (bitValue r) := by\n  unfold nextWord nextRoot\n  by_cases h : rejects d r (baseWord n)=true\n  · have hb:= (rejects_true d r (baseWord n)).1 h\n    rw [base_value] at hb\n    simp only [h,ite_true,show ¬(bitValue r+2^n)^2 ≤ bitValue d by omega,ite_false]\n  · have hb : (bitValue r+2^n)^2 ≤ bitValue d := by\n      have ht:=rejects_true d r (baseWord n)\n      rw [base_value] at ht\n      exact Nat.le_of_not_lt (fun hx => h (ht.2 hx))\n    simp only [h,Bool.false_eq_true,ite_false,hb,ite_true,trial_value,base_value]\n/-- Raw-word execution and the descending arithmetic recurrence agree universally. -/\ntheorem wordLoop_value (d r : List Bool) (n : ℕ) :\n    bitValue (wordLoop d n r)=greedy (bitValue d) n (bitValue r) := by\n  induction n generalizing r with\n  | zero => exact nextWord_value d r 0\n  | succ n ih => rw [wordLoop,ih,nextWord_value,greedy]\n/-- The final raw-word specification is the square root for EVERY binary input. -/\ntheorem output_value (d : List Bool) : bitValue (output d)=Nat.sqrt (bitValue d) := by\n  rw [output,SemiprimeD1StackReduceExecution.trimReverse_value,List.reverse_reverse,wordLoop_value]\n  exact greedy_eq_sqrt (bitValue d) d.length (bitValue_lt_width d)\n/-- Real final trimming gives the compact byte ABI, including zero and padded inputs. -/\ntheorem output_compact (d : List Bool) : SemiprimeSourceCompactBits.Compact (output d) :=\n  SemiprimeD1StackReduceExecution.trimReverse_compact _\n/-- Actual raw-adder padding grows by at most one cell beyond the longer operand. -/\ntheorem trial_length (r p : List Bool) : (trial r p).length ≤ max r.length p.length+1 := by\n  have h:=(addBits_counts r p false).2.2.2.2\n  exact h\n/-- The existing raw multiplication width theorem applies to the actual square. -/\ntheorem square_length (r p : List Bool) : (square r p).length ≤ 3*(trial r p).length := by\n  have h:=mulBits_length (trial r p) (trial r p)\n  change (square r p).length ≤ 2*(trial r p).length+(trial r p).length at h\n  omega\n/-- Branch selection cannot exceed the same adder width envelope. -/\ntheorem nextWord_length (d r p : List Bool) :\n    (nextWord d r p).length ≤ max r.length p.length+1 := by\n  unfold nextWord\n  split_ifs\n  · exact (le_max_left r.length p.length).trans (Nat.le_add_right _ 1)\n  · exact trial_length r p\n/-- n+1 actual tests add only n+1 raw padding cells beyond the largest input word. -/\ntheorem wordLoop_length (d r : List Bool) (n : ℕ) :\n    (wordLoop d n r).length ≤ max r.length (n+1)+(n+1) := by\n  induction n generalizing r with\n  | zero => simpa only [wordLoop,base_length] using nextWord_length d r (baseWord 0)\n  | succ n ih =>\n    have h0:=nextWord_length d r (baseWord (n+1))\n    rw [base_length] at h0\n    have h1:=ih (nextWord d r (baseWord (n+1)))\n    have hm : max (nextWord d r (baseWord (n+1))).length (n+1) ≤ max r.length (n+2)+1 :=\n      max_le (by omega) (by omega)\n    change (wordLoop d n (nextWord d r (baseWord (n+1)))).length ≤ _\n    omega\n/-- With an empty original root, every completed raw root has linear bit length. -/\ntheorem original_word_length (d : List Bool) :\n    (wordLoop d d.length []).length ≤ 2*(d.length+1) := by\n  have h:=wordLoop_length d [] d.length\n  simpa only [List.length_nil,max_eq_right (Nat.zero_le _),two_mul] using h\nend RiemannGaussian.SemiprimeD1StackBinarySquareRootArithmetic\n","RiemannGaussian.SemiprimeD1StackBinarySquareRootCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBinarySquareRootPrimitives\n/-! # Exact real copy/adapt stages of one greedy binary square-root test -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackBinarySquareRootCalls\nopen SemiprimeD1StackBinarySquareRoot SemiprimeD1StackBinarySquareRootEncoding\nopen SemiprimeD1StackBinarySquareRootPrimitives SemiprimeD1StackProcedureTrace\n/-- Actual clean adder-source preparation copies the old root and actual power. -/\ntheorem operands_call (bits p r : List Bool) :\n    Runs program ((5*r.length+4)+(5*p.length+4)) (ctl .rootCopy) (idle bits p r) (ctl .add)\n      (bank (retained bits p) (A.store r p [] []) (fun _ => []) (fun _ => []) (words r [])) := by\n  have h0:=copy_call .root (ctl .rootCopy) (ctl .powerCopy) rfl (idle bits p r) r [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update (idle bits p r) (adder .left) (r++[])) at h0\n  have e0 : Function.update (fun _ : A.Stack => []) .left r=A.store r [] [] [] := by\n    funext k;cases k <;> rfl\n  dsimp only [idle] at h0\n  rw [List.append_nil,bank_adder,e0] at h0\n  have h1:=copy_call .power (ctl .powerCopy) (ctl .add) rfl\n    (bank (retained bits p) (A.store r [] [] []) (fun _ => []) (fun _ => []) (words r [])) p [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (adder .right) (p++[])) at h1\n  rw [List.append_nil,bank_adder,SemiprimeD1StackAdder.store_right] at h1\n  exact join h0 h1\n/-- Real trial copies prepare BOTH multiplier operands; the adder result is retained. -/\ntheorem square_operands_call (bits p r : List Bool) :\n    Runs program ((5*(E.trial r p).length+4)+(5*(E.trial r p).length+4))\n      (ctl .trialInputCopy)\n      (bank (retained bits p) (A.store [] [] [] (E.trial r p)) (fun _ => []) (fun _ => []) (words r []))\n      (ctl .square)\n      (bank (retained bits p) (A.store [] [] [] (E.trial r p))\n        (X.payload (E.trial r p) (E.trial r p) [] [] [] [] [] [] []) (fun _ => []) (words r [])) := by\n  let t:=E.trial r p\n  let m:=retained bits p\n  let a:=A.store [] [] [] t\n  have h0:=copy_call .trialInput (ctl .trialInputCopy) (ctl .trialFactorCopy) rfl\n    (bank m a (fun _ => []) (fun _ => []) (words r [])) t [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (multiply X.input) (t++[])) at h0\n  have e0 : Function.update (fun _ : X.Stack => []) X.input t=X.payload t [] [] [] [] [] [] [] [] := by\n    funext k\n    rcases k with k|k|k\n    · cases k <;> rfl\n    · fin_cases k <;> rfl\n    · cases k <;> rfl\n  rw [List.append_nil,bank_multiply,e0] at h0\n  have h1:=copy_call .trialFactor (ctl .trialFactorCopy) (ctl .square) rfl\n    (bank m a (X.payload t [] [] [] [] [] [] [] []) (fun _ => []) (words r [])) t [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (multiply X.factor) (t++[])) at h1\n  rw [List.append_nil,bank_multiply,SemiprimeD1StackMultiplierExecution.payload_ys] at h1\n  exact join h0 h1\n/-- Real original-D and actual-square copies prepare the numeric comparison. -/\ntheorem compare_operands_call (bits p r : List Bool) :\n    Runs program ((5*bits.length+4)+(5*(E.square r p).length+4))\n      (ctl .discriminantCopy)\n      (bank (retained bits p) (A.store [] [] [] (E.trial r p))\n        (X.payload [] [] [] [] (E.square r p) [] [] [] []) (fun _ => []) (words r []))\n      (ctl .compare)\n      (bank (retained bits p) (A.store [] [] [] (E.trial r p))\n        (X.payload [] [] [] [] (E.square r p) [] [] [] [])\n        (W.store bits (E.square r p) [] [] []) (words r [])) := by\n  let m:=retained bits p\n  let a:=A.store [] [] [] (E.trial r p)\n  let x:=X.payload [] [] [] [] (E.square r p) [] [] [] []\n  have h0:=copy_call .discriminant (ctl .discriminantCopy) (ctl .squareCopy) rfl\n    (bank m a x (fun _ => []) (words r [])) bits [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (SemiprimeD1StackBinarySquareRoot.compare (.inl .left)) (bits++[])) at h0\n  have e0 : Function.update (fun _ : W.Stack => []) (.inl .left) bits=W.store bits [] [] [] [] := by\n    funext k\n    rcases k with k|k\n    · cases k <;> rfl\n    · cases k;rfl\n  rw [List.append_nil,bank_compare,e0] at h0\n  have h1:=copy_call .square (ctl .squareCopy) (ctl .compare) rfl\n    (bank m a x (W.store bits [] [] [] []) (words r [])) (E.square r p) [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (SemiprimeD1StackBinarySquareRoot.compare (.inl .right)) (_++[])) at h1\n  have e1 : Function.update (W.store bits [] [] [] []) (.inl .right) (E.square r p)=W.store bits (E.square r p) [] [] [] := by\n    funext k\n    rcases k with k|k\n    · cases k <;> rfl\n    · cases k;rfl\n  rw [List.append_nil,bank_compare,e1] at h1\n  exact join h0 h1\n/-- Exact own clock for all arithmetic and copy calls before the decision. -/\ndef testTime (bits p r : List Bool) : ℕ :=\n  ((5*r.length+4)+(5*p.length+4))+addTime r p+\n  ((5*(E.trial r p).length+4)+(5*(E.trial r p).length+4))+\n  multiplyTime (E.trial r p) (E.trial r p)+\n  ((5*bits.length+4)+(5*(E.square r p).length+4))+compareTime bits (E.square r p)\n/-- Complete real trial preparation, square and comparison from a clean boundary. -/\ntheorem test_call (bits p r : List Bool) :\n    Runs program (testTime bits p r) (ctl .rootCopy) (idle bits p r) (ctl .decide) (tested bits p r) := by\n  have h0:=operands_call bits p r\n  have h1:=add_call (retained bits p) (fun _ => []) (fun _ => []) (words r []) r p\n  have h2:=square_operands_call bits p r\n  have h3:=multiply_call (retained bits p) (A.store [] [] [] (E.trial r p)) (fun _ => []) (words r []) r p\n  have h4:=compare_operands_call bits p r\n  have h5:=compare_call (retained bits p) (A.store [] [] [] (E.trial r p))\n    (X.payload [] [] [] [] (E.square r p) [] [] [] []) (words r []) bits (E.square r p)\n  exact join (join (join (join (join h0 h1) h2) h3) h4) h5\nend RiemannGaussian.SemiprimeD1StackBinarySquareRootCalls\n","RiemannGaussian.SemiprimeD1StackBitGather":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBitIndex\nimport RiemannGaussian.SemiprimeD1TensorTapeVectorMachine\nimport RiemannGaussian.SemiprimeD1TensorTapeCodec\nimport RiemannGaussian.SemiprimeD1LeafCounter\n\n/-! # Physical ordered gather from framed unary indices\nEvery index receives a fresh physical copy of the assignment. Both that copy and\nits unused suffix are consumed. The assignment is restored literally. The final\nresult is reversed physically into original port order. No indexed-read callback\nor native index register occurs in the program.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackBitGather\nopen Turing Turing.TM2 Turing.TM2.Stmt\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n\n/-- Fixed Boolean data stacks. -/\ninductive Stack | input | assignment | reader | scratch | accumulator | output\n  deriving DecidableEq,Inhabited,Repr\ninstance : Fintype Stack where\n  elems := {.input,.assignment,.reader,.scratch,.accumulator,.output}\n  complete := by intro k; cases k <;> simp\n\n/-- Fixed control labels, independent of every scope/index length. -/\ninductive PC | marker | drain | restore | tag | drop | get | clear | reverse\n  deriving DecidableEq,Inhabited,Repr\ninstance : Fintype PC where\n  elems := {.marker,.drain,.restore,.tag,.drop,.get,.clear,.reverse}\n  complete := by intro k; cases k <;> simp\n\n/-- Every stack contains individual Boolean symbols. -/\nabbrev Alphabet (_ : Stack) := Bool\n/-- The sole finite register is an optional popped bit. -/\nabbrev Registers := Option Bool\n\n/-- Actual finite stack instructions, including all assignment copying/clearing. -/\ndef program : PC → Stmt Alphabet PC Registers\n  | .marker => .pop .input (fun _ b => b)\n      (.branch (fun b => b==some true) (.goto (fun _ => .drain)) (.goto (fun _ => .reverse)))\n  | .drain => .pop .assignment (fun _ b => b)\n      (.branch (fun b => b.isSome)\n        (.push .scratch (fun b => b.getD false) (.goto (fun _ => .drain)))\n        (.goto (fun _ => .restore)))\n  | .restore => .pop .scratch (fun _ b => b)\n      (.branch (fun b => b.isSome)\n        (.push .assignment (fun b => b.getD false)\n          (.push .reader (fun b => b.getD false) (.goto (fun _ => .restore))))\n        (.goto (fun _ => .tag)))\n  | .tag => .pop .input (fun _ b => b)\n      (.branch (fun b => b==some true) (.goto (fun _ => .drop)) (.goto (fun _ => .get)))\n  | .drop => .pop .input (fun _ b => b)\n      (.pop .reader (fun _ b => b) (.goto (fun _ => .tag)))\n  | .get => .pop .reader (fun _ b => b)\n      (.push .accumulator (fun b => b.getD false) (.goto (fun _ => .clear)))\n  | .clear => .pop .reader (fun _ b => b)\n      (.branch (fun b => b.isSome) (.goto (fun _ => .clear)) (.goto (fun _ => .marker)))\n  | .reverse => .pop .accumulator (fun _ b => b)\n      (.branch (fun b => b.isSome)\n        (.push .output (fun b => b.getD false) (.goto (fun _ => .reverse))) .halt)\n\n/-- Genuine fixed finite-alphabet machine. -/\ndef machine : FinTM2 where\n  K := Stack\n  k₀ := .input\n  k₁ := .output\n  Γ := Alphabet\n  Λ := PC\n  main := .marker\n  σ := Registers\n  initialState := none\n  m := program\n\n/-- Explicit actual stack payloads. -/\ndef contents (input assignment reader scratch accumulator output : List Bool) :\n    (k : Stack) → List (Alphabet k)\n  | .input => input\n  | .assignment => assignment\n  | .reader => reader\n  | .scratch => scratch\n  | .accumulator => accumulator\n  | .output => output\n\n/-- Actual configurations; all unbounded data live only in stacks. -/\ndef cfg (pc : Option PC) (flag : Registers)\n    (input assignment reader scratch accumulator output : List Bool) :\n    Cfg Alphabet PC Registers := ⟨pc,flag,contents input assignment reader scratch accumulator output⟩\n\n/-- Actual primitive transition function. -/\ndef step := TM2.step program\n\n/-- Every physical update is a literal single-stack update. -/\n@[simp] theorem update_contents (input assignment reader scratch accumulator output xs : List Bool)\n    (k : Stack) : Function.update (contents input assignment reader scratch accumulator output) k xs=\n      contents (if k=.input then xs else input) (if k=.assignment then xs else assignment)\n        (if k=.reader then xs else reader) (if k=.scratch then xs else scratch)\n        (if k=.accumulator then xs else accumulator) (if k=.output then xs else output) := by\n  funext j\n  cases k <;> cases j <;> simp [contents]\n\n/-- Exact actual transition paths, with proof-only lengths. -/\ninductive Executes : ℕ → Cfg Alphabet PC Registers → Cfg Alphabet PC Registers → Prop\n  | refl (c) : Executes 0 c c\n  | next {n c d e} : step c=some d → Executes n d e → Executes (n+1) c e\n\n/-- Actual execution paths compose. -/\ntheorem Executes.trans {n m : ℕ} {a b c : Cfg Alphabet PC Registers}\n    (h : Executes n a b) (g : Executes m b c) : Executes (n+m) a c := by\n  induction h with\n  | refl => simpa using g\n  | @next n a d b hs ht ih =>\n    simpa only [Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using Executes.next hs (ih g)\n\n/-- Actual iterate equation needed by Mathlib time certificates. -/\ntheorem Executes.iterates {n : ℕ} {a b : Cfg Alphabet PC Registers} (h : Executes n a b) :\n    ((fun x : Option (Cfg Alphabet PC Registers) => x.bind step)^[n]) (some a)=some b := by\n  induction h with\n  | refl => rfl\n  | @next n a d b hs ht ih =>\n    rw [Function.iterate_succ_apply]\n    simpa only [Option.bind_some,hs] using ih\n\n/-- The first copy pass physically drains every assignment cell. -/\ntheorem drain_exec (flag : Registers) (input assignment reader scratch acc out : List Bool) :\n    Executes (assignment.length+1) (cfg (some .drain) flag input assignment reader scratch acc out)\n      (cfg (some .restore) none input [] reader (assignment.reverse++scratch) acc out) := by\n  induction assignment generalizing flag scratch with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    have hs : step (cfg (some .drain) flag input (b::bs) reader scratch acc out)=\n        some (cfg (some .drain) (some b) input bs reader (b::scratch) acc out) := by\n      simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n    simpa [List.reverse_cons,List.append_assoc] using Executes.next hs (ih (some b) (b::scratch))\n\n/-- The second copy pass restores the assignment AND creates the disposable reader. -/\ntheorem restore_exec (flag : Registers) (input assignment reader scratch acc out : List Bool) :\n    Executes (scratch.length+1) (cfg (some .restore) flag input assignment reader scratch acc out)\n      (cfg (some .tag) none input (scratch.reverse++assignment) (scratch.reverse++reader) [] acc out) := by\n  induction scratch generalizing flag assignment reader with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    have hs : step (cfg (some .restore) flag input assignment reader (b::bs) acc out)=\n        some (cfg (some .restore) (some b) input (b::assignment) (b::reader) bs acc out) := by\n      simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n    simpa [List.reverse_cons,List.append_assoc] using\n      Executes.next hs (ih (some b) (b::assignment) (b::reader))\n\n/-- Actual two-pass assignment copy, including both EOF tests. -/\ntheorem copy_exec (flag : Registers) (input assignment acc out : List Bool) :\n    Executes (2*assignment.length+2) (cfg (some .drain) flag input assignment [] [] acc out)\n      (cfg (some .tag) none input assignment assignment [] acc out) := by\n  have h := (drain_exec flag input assignment [] [] acc out).trans\n    (restore_exec none input [] [] (assignment.reverse++[]) acc out)\n  simp only [List.append_nil,List.length_reverse,List.reverse_reverse] at h\n  convert h using 1\n  omega\n\n/-- Scan a framed unary index and physically discard that many reader cells. -/\ntheorem field_exec (flag : Registers) (index input assignment reader acc out : List Bool) :\n    Executes (2*index.length+1)\n      (cfg (some .tag) flag (frame index input) assignment reader [] acc out)\n      (cfg (some .get) (some false) input assignment (reader.drop index.length) [] acc out) := by\n  induction index generalizing flag reader with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackBitGather.step,program,cfg,contents,frame,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    have hs : step (cfg (some .tag) flag (frame (b::bs) input) assignment reader [] acc out)=\n        some (cfg (some .drop) (some true) (b::frame bs input) assignment reader [] acc out) := by\n      simp [SemiprimeD1StackBitGather.step,program,cfg,contents,frame,TM2.step,TM2.stepAux]\n    have hd : step (cfg (some .drop) (some true) (b::frame bs input) assignment reader [] acc out)=\n        some (cfg (some .tag) reader.head? (frame bs input) assignment reader.tail [] acc out) := by\n      simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n    have h := Executes.next hs (Executes.next hd (ih reader.head? reader.tail))\n    convert h using 1\n    simp\n\n/-- Clear every unused reader suffix physically before processing the next port. -/\ntheorem clear_exec (flag : Registers) (input assignment reader acc out : List Bool) :\n    Executes (reader.length+1) (cfg (some .clear) flag input assignment reader [] acc out)\n      (cfg (some .marker) none input assignment [] [] acc out) := by\n  induction reader generalizing flag with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    apply Executes.next ?_ (ih (some b))\n    simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n\n/-- Reverse the gathered accumulator into original port order. -/\ntheorem reverse_exec (flag : Registers) (input assignment acc out : List Bool) :\n    Executes (acc.length+1) (cfg (some .reverse) flag input assignment [] [] acc out)\n      (cfg none none input assignment [] [] [] (acc.reverse++out)) := by\n  induction acc generalizing flag out with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    have hs : step (cfg (some .reverse) flag input assignment [] [] (b::bs) out)=\n        some (cfg (some .reverse) (some b) input assignment [] [] bs (b::out)) := by\n      simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n    simpa [List.reverse_cons,List.append_assoc] using Executes.next hs (ih (some b) (b::out))\n\n/-- Finish the indexed read and physically clear its entire unused reader suffix. -/\ntheorem get_clear_exec (flag : Registers) (input assignment reader acc out : List Bool) :\n    Executes (reader.tail.length+2) (cfg (some .get) flag input assignment reader [] acc out)\n      (cfg (some .marker) none input assignment [] [] (reader.head?.getD false::acc) out) := by\n  have hs : step (cfg (some .get) flag input assignment reader [] acc out)=\n      some (cfg (some .clear) reader.head? input assignment reader.tail []\n        (reader.head?.getD false::acc) out) := by\n    simp [SemiprimeD1StackBitGather.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  simpa using Executes.next hs (clear_exec reader.head? input assignment reader.tail\n    (reader.head?.getD false::acc) out)\n\n/-- Actual per-port scan cost, including restored assignment and disposed suffix. -/\ndef portSteps (assignment index : List Bool) : ℕ :=\n  2*assignment.length+2*index.length+(assignment.drop (index.length+1)).length+6\n\n/-- Actual full scan cost before final output reversal. -/\ndef scanSteps (assignment : List Bool) : List (List Bool) → ℕ\n  | [] => 1\n  | i::is => portSteps assignment i+scanSteps assignment is\n\n/-- Physical indexing values, specified without any runtime getter callback. -/\ndef values (assignment : List Bool) (indices : List (List Bool)) : List Bool :=\n  indices.map (fun i => (assignment[i.length]?).getD false)\n\n/-- Complete chronological gather scan, preserving the original assignment. -/\ntheorem gather_scan (flag : Registers) (assignment : List Bool) (indices : List (List Bool))\n    (tail acc out : List Bool) :\n    Executes (scanSteps assignment indices)\n      (cfg (some .marker) flag (vectorBits indices++tail) assignment [] [] acc out)\n      (cfg (some .reverse) (some false) tail assignment [] []\n        ((values assignment indices).reverse++acc) out) := by\n  induction indices generalizing flag acc with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackBitGather.step,program,cfg,contents,vectorBits,values,\n      TM2.step,TM2.stepAux]\n  | cons i is ih =>\n    have hs : step (cfg (some .marker) flag (vectorBits (i::is)++tail) assignment [] [] acc out)=\n        some (cfg (some .drain) (some true) (frame i (vectorBits is++tail)) assignment [] [] acc out) := by\n      simp [SemiprimeD1StackBitGather.step,program,cfg,contents,vectorBits,\n        SemiprimeD1TensorTapeVectorMachine.frame_append,TM2.step,TM2.stepAux]\n    have hc := copy_exec (some true) (frame i (vectorBits is++tail)) assignment acc out\n    have hf := field_exec none i (vectorBits is++tail) assignment assignment acc out\n    have hg := get_clear_exec (some false) (vectorBits is++tail) assignment\n      (assignment.drop i.length) acc out\n    have hi := ih none ((assignment.drop i.length).head?.getD false::acc)\n    have h := Executes.next hs (hc.trans (hf.trans (hg.trans hi)))\n    convert h using 1 <;> simp [scanSteps,portSteps,values,List.reverse_cons,List.append_assoc,\n      List.head?_eq_getElem?,List.getElem?_drop,Nat.add_assoc]\n    all_goals omega\n\n/-- Complete actual machine execution with one physical output bit per port. -/\ntheorem gather_exec (assignment : List Bool) (indices : List (List Bool)) (tail out : List Bool) :\n    Executes (scanSteps assignment indices+indices.length+1)\n      (cfg (some .marker) none (vectorBits indices++tail) assignment [] [] [] out)\n      (cfg none none tail assignment [] [] [] (values assignment indices++out)) := by\n  have hs := gather_scan none assignment indices tail [] out\n  have hr := reverse_exec (some false) tail assignment ((values assignment indices).reverse++[]) out\n  have h := hs.trans hr\n  simpa [values,Nat.add_assoc] using h\n\n/-- Literal frozen ordered gather from original unary port indices, no producer oracle. -/\ntheorem original_gather_exec (assignment : List Bool) (ports : List ℕ) (tail out : List Bool) :\n    Executes (scanSteps assignment (ports.map (fun i => List.replicate i true))+ports.length+1)\n      (cfg (some .marker) none (vectorBits (ports.map (fun i => List.replicate i true))++tail)\n        assignment [] [] [] out)\n      (cfg none none tail assignment [] [] []\n        ((SemiprimeD1LeafCounter.gather assignment ports).bits++out)) := by\n  simpa [values,List.map_map,Function.comp_def,SemiprimeD1LeafCounter.gather_value] using\n    gather_exec assignment (ports.map (fun i => List.replicate i true)) tail out\n\nend RiemannGaussian.SemiprimeD1StackBitGather\n","RiemannGaussian.SemiprimeD1StackBitGatherBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBitGather\n\n/-! # Actual primitive time/storage of physical gather\nRepeated whole-assignment copies and discarded suffix scans are included. Input\nindex framing/unary acquisition and preparation of the assignment stack remain\ncaller operations. No native producer clock is assumed.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackBitGatherBounds\nopen Turing Turing.TM2\nopen SemiprimeD1StackBitGather\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n\n/-- Actual encoded-vector length dominates the number of requested ports. -/\ntheorem count_le_tape (indices : List (List Bool)) : indices.length≤(vectorBits indices).length := by\n  induction indices with\n  | nil => simp [vectorBits]\n  | cons i is ih =>\n    simp only [vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n    omega\n\n/-- Complete scan cost, including every repeated assignment copy and suffix clear. -/\ntheorem scanSteps_le (assignment : List Bool) (indices : List (List Bool)) :\n    scanSteps assignment indices≤(3*assignment.length+6)*(vectorBits indices).length := by\n  induction indices with\n  | nil => simp [scanSteps,vectorBits]\n  | cons i is ih =>\n    have hd : (assignment.drop (i.length+1)).length≤assignment.length := by\n      simp only [List.length_drop]\n      omega\n    simp only [scanSteps,portSteps,vectorBits,List.length_cons,\n      SemiprimeSourceHistogramKeyBits.frame_length]\n    nlinarith\n\n/-- Fixed polynomial bound in the actual assignment and index-tape lengths. -/\ndef budget (assignmentLength indexTapeLength : ℕ) : ℕ :=\n  (3*assignmentLength+8)*(indexTapeLength+1)\n\n/-- All literal actual transition counts fit the displayed polynomial. -/\ntheorem gather_steps_le (assignment : List Bool) (indices : List (List Bool)) :\n    scanSteps assignment indices+indices.length+1≤budget assignment.length (vectorBits indices).length := by\n  have hs := scanSteps_le assignment indices\n  have hc := count_le_tape indices\n  unfold budget\n  nlinarith\n\n/-- Genuine TM2 time certificate; no bit getter or lookup callback is supplied. -/\ndef gatherInTime (assignment : List Bool) (indices : List (List Bool)) (tail out : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (cfg (some .marker) none (vectorBits indices++tail) assignment [] [] [] out)\n      (some (cfg none none tail assignment [] [] [] (values assignment indices++out)))\n      (budget assignment.length (vectorBits indices).length) := by\n  refine ⟨⟨_,(gather_exec assignment indices tail out).iterates⟩,?_⟩\n  change scanSteps assignment indices+indices.length+1≤_\n  exact gather_steps_le assignment indices\n\n/-- Closed original ordered-port endpoint, with only physical unary indices as input. -/\ndef originalGatherInTime (assignment : List Bool) (ports : List ℕ) (tail out : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (cfg (some .marker) none (vectorBits (ports.map (fun i => List.replicate i true))++tail)\n        assignment [] [] [] out)\n      (some (cfg none none tail assignment [] [] []\n        ((SemiprimeD1LeafCounter.gather assignment ports).bits++out)))\n      (budget assignment.length (vectorBits (ports.map (fun i => List.replicate i true))).length) := by\n  simpa [values,List.map_map,Function.comp_def,SemiprimeD1LeafCounter.gather_value] using\n    gatherInTime assignment (ports.map (fun i => List.replicate i true)) tail out\n\n/-- Every alphabet is the same finite two-symbol set. -/\ntheorem alphabet_card (k : Stack) : Fintype.card (Alphabet k)=2 := by\n  change Fintype.card Bool=2\n  decide\n\n/-- No unbounded register data are hidden in this program. -/\ntheorem registers_card : Fintype.card Registers=3 := by decide\n\n/-- Every elementary stack/control syntax node is included in the static depth. -/\ndef instructionDepth : Stmt Alphabet PC Registers → ℕ\n  | .push _ _ q => 1+instructionDepth q\n  | .peek _ _ q => 1+instructionDepth q\n  | .pop _ _ q => 1+instructionDepth q\n  | .load _ q => 1+instructionDepth q\n  | .branch _ q r => 1+max (instructionDepth q) (instructionDepth r)\n  | .goto _ => 1\n  | .halt => 1\n\n/-- At most five elementary instructions occur in one TM2 transition. -/\ntheorem program_depth (pc : PC) : instructionDepth (program pc)≤5 := by\n  cases pc <;> decide\n\n/-- All actual jumps stay within the same fixed eight-label program. -/\ntheorem program_supports : TM2.Supports program Finset.univ := by\n  constructor\n  · simp\n  · intro pc hpc\n    cases pc <;> simp [program,TM2.SupportsStmt]\n\n/-- All six unbounded data stacks, including restoration and result scratch. -/\ndef cells (c : Cfg Alphabet PC Registers) : ℕ :=\n  (c.stk Stack.input).length+(c.stk Stack.assignment).length+(c.stk Stack.reader).length+\n    (c.stk Stack.scratch).length+(c.stk Stack.accumulator).length+(c.stk Stack.output).length\n\n/-- One actual instruction label creates at most two Boolean symbols. -/\ntheorem step_cells (c d : Cfg Alphabet PC Registers) (h : step c=some d) :\n    cells d≤cells c+2 := by\n  rcases c with ⟨pc,flag,store⟩\n  cases pc with\n  | none => simp [SemiprimeD1StackBitGather.step,TM2.step] at h\n  | some pc =>\n    cases pc <;>\n      simp [SemiprimeD1StackBitGather.step,TM2.step,program,TM2.stepAux,\n        Bool.cond_eq_ite,Function.update] at h <;>\n      (try split_ifs at h) <;> cases h <;> simp [cells,Function.update] <;> omega\n\n/-- All reached states, including copy/restore/clear frames, have derived storage. -/\ntheorem path_cells {n : ℕ} {c d : Cfg Alphabet PC Registers} (h : Executes n c d) :\n    cells d≤cells c+2*n := by\n  induction h with\n  | refl => omega\n  | @next n c e d hs ht ih =>\n    have hh := step_cells c e hs\n    omega\n\n/-- Uniform quadratic all-prefix Boolean storage in actual encoded input sizes. -/\ntheorem gather_cells (assignment : List Bool) (indices : List (List Bool)) (tail out : List Bool)\n    (n : ℕ) (c : Cfg Alphabet PC Registers)\n    (h : Executes n (cfg (some .marker) none (vectorBits indices++tail) assignment [] [] [] out) c)\n    (hn : n≤budget assignment.length (vectorBits indices).length) :\n    cells c≤(vectorBits indices).length+tail.length+assignment.length+out.length+\n      2*budget assignment.length (vectorBits indices).length := by\n  have hh := path_cells h\n  simp only [cells,cfg,contents,List.length_append,List.length_nil,Nat.add_zero] at hh\n  unfold cells\n  omega\n\nend RiemannGaussian.SemiprimeD1StackBitGatherBounds\n","RiemannGaussian.SemiprimeD1StackBooleanDescriptorRecordExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBooleanDescriptorRecordPrimitives\n/-! # Complete actual descriptor parsing, dispatch and Boolean-row acquisition -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackBooleanDescriptorRecordExecution\nopen SemiprimeD1StackBooleanDescriptorRecord SemiprimeD1StackBooleanDescriptorRecordEncoding\nopen SemiprimeD1StackBooleanDescriptorRecordView SemiprimeD1StackBooleanDescriptorRecordPrimitives\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\n/-- One actual field read plus its actual successful-validity pop. -/\ntheorem field_run (part : Fin 5) (base : R.Stack→List Bool) (w : Record) (tail : List Bool) :\n    Runs program (8*(w part).length+8) (.local (.field part))\n      (clean base (parsed part.val w) (suffix w part.val tail)) (nextField part)\n      (clean base (parsed (part.val+1) w) (suffix w (part.val+1) tail)) := by\n  have h0:=field_call part (clean base (parsed part.val w) (suffix w part.val tail))\n    (w part) (suffix w (part.val+1) tail) (suffix_step w part tail)\n    (by change (if part.val<part.val then w part else [])=[];simp) rfl rfl\n  unfold clean at h0\n  rw [update_reader,update_cache,parsed_step,update_valid] at h0\n  have h1 : Runs program 1 (.local (.valid part))\n      (data base (parsed (part.val+1) w) (suffix w (part.val+1) tail) [true] []) (nextField part)\n      (clean base (parsed (part.val+1) w) (suffix w (part.val+1) tail)) := by\n    apply one_base program (.local (.valid part)) (nextField part)\n      (.pop (aux .valid) (.local .abort) (.local .abort) (nextField part)) _ _ rfl\n    · rfl\n    · exact update_valid _ _ _ _ _ _\n  have h:=h0.trans h1\n  simpa only [clean,Nat.add_assoc,show 7+1=8 from rfl] using h\n/-- All five actual descriptor fields are acquired, including arbitrary caller suffixes. -/\ntheorem all_fields (base : R.Stack→List Bool) (w : Record) (tail : List Bool) :\n    Runs program (8*mass w+40) (.local (.field 0))\n      (clean base (fun _=>[]) (record w tail)) (.local .copyTag) (clean base w tail) := by\n  have h0:=field_run 0 base w tail\n  have h1:=field_run 1 base w tail\n  have h2:=field_run 2 base w tail\n  have h3:=field_run 3 base w tail\n  have h4:=field_run 4 base w tail\n  have h:=h0.trans (h1.trans (h2.trans (h3.trans h4)))\n  have hm:mass w=(w 0).length+((w 1).length+((w 2).length+((w 3).length+((w 4).length+0)))):=rfl\n  have ht:(8*(w 0).length+8)+((8*(w 1).length+8)+((8*(w 2).length+8)+\n      ((8*(w 3).length+8)+(8*(w 4).length+8))))=8*mass w+40 := by omega\n  rw [ht] at h\n  change Runs program (8*mass w+40) (.local (.field 0))\n    (clean base (parsed 0 w) (record w tail)) (.local .copyTag) (clean base (parsed 5 w) tail) at h\n  have hz:parsed 0 w=fun _=>[]:=by funext k;simp [parsed]\n  rw [parsed_end,hz] at h\n  exact h\n/-- Every unary constructor marker executes one real pop; EOF selects a literal finite branch. -/\ntheorem decode_run (n i : Nat) (hi:i+n<18) (base : R.Stack→List Bool) (w : Record) (tail : List Bool) :\n    Runs program (n+1) (.local (.decode ⟨i,by omega⟩))\n      (data base w tail [] (List.replicate n true)) (dispatch ⟨i+n,hi⟩) (clean base w tail) := by\n  induction n generalizing i with\n  | zero=>\n    apply one_base program _ _ (.pop (aux .tagReader) (dispatch ⟨i,by omega⟩)\n      (nextDecode ⟨i,by omega⟩) (nextDecode ⟨i,by omega⟩)) _ _ rfl\n    · rfl\n    · exact update_tagReader _ _ _ _ _ _\n  | succ n ih=>\n    have hit:i<17:=by omega\n    have hc:program (.local (.decode ⟨i,by omega⟩))=.base (.pop (aux .tagReader) (dispatch ⟨i,by omega⟩)\n      (.local (.decode ⟨i+1,by omega⟩)) (.local (.decode ⟨i+1,by omega⟩))):=by\n        simp [program,nextDecode,hit]\n    have h0:Runs program 1 (.local (.decode ⟨i,by omega⟩))\n        (data base w tail [] (List.replicate (n+1) true)) (.local (.decode ⟨i+1,by omega⟩))\n        (data base w tail [] (List.replicate n true)) := by\n      apply one_base program _ _ (.pop (aux .tagReader) (dispatch ⟨i,by omega⟩)\n        (.local (.decode ⟨i+1,by omega⟩)) (.local (.decode ⟨i+1,by omega⟩))) _ _ hc\n      · rfl\n      · change Function.update (data base w tail [] (List.replicate (n+1) true))\n          (aux .tagReader) (List.replicate (n+1) true).tail=_\n        simp only [List.replicate_succ,List.tail_cons]\n        exact update_tagReader _ _ _ _ _ _\n    have h1:=ih (i+1) (by omega)\n    have he:(⟨i+1+n,by omega⟩:Fin 18)=⟨i+(n+1),hi⟩:=by\n      apply Fin.ext\n      change i+1+n=i+(n+1)\n      omega\n    rw [he] at h1\n    simpa only [show 1+(n+1)=n+1+1 by omega] using h0.trans h1\n/-- Exact clean halt, retaining all parsed fields, the unread descriptor suffix and scope bank. -/\ndef done (mode : SemiprimeD1StackBooleanEntry.Mode) (w : Record) (tail : List Bool)\n    (scope : List (List Bool)) (hist out : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,clean (R.done mode scope hist out).data w tail,[]⟩\n/-- Complete own source allowance: every parse, tag-copy/pop, nested row call and halt. -/\ndef timeBound (code : Fin 18) (w : Record) (mode : SemiprimeD1StackBooleanEntry.Mode)\n    (scope : List (List Bool)) : Nat :=\n  SemiprimeD1StackBooleanRecordExecution.timeBound mode scope+8*mass w+6*code.val+47\n/-- The same fixed program physically reads the actual descriptor before selecting\nthe Boolean row. The hypotheses describe source bytes; no mode is passed to control. -/\ntheorem source_run (code : Fin 18) (w : Record) (tail : List Bool)\n    (mode : SemiprimeD1StackBooleanEntry.Mode) (htag:w 0=List.replicate code.val true)\n    (hm:dispatch code=.local (.record mode)) (scope : List (List Bool)) (hist out : List Bool) :\n    ∃t ≤ timeBound code w mode scope,\n      C.run program t (initial (record w tail) (SemiprimeD1TensorTapeCodec.vectorBits scope) hist out)=\n        some (done mode w tail scope hist out) := by\n  let base:=recordInput (SemiprimeD1TensorTapeCodec.vectorBits scope) hist out\n  have h0:=all_fields base w tail\n  have h1:=copy_tag base w tail\n  rw [htag,List.length_replicate] at h1\n  have h2:=decode_run code.val 0 (by omega) base w tail\n  have he:(⟨0+code.val,by omega⟩:Fin 18)=code:=by\n    apply Fin.ext\n    change 0+code.val=code.val\n    omega\n  rw [he,hm] at h2\n  obtain ⟨t,ht,h3⟩:=record_call mode scope hist out tail w\n  have h:=h0.trans (h1.trans (h2.trans h3))\n  obtain ⟨finish,hr,ho⟩:=h []\n    (initial (record w tail) (SemiprimeD1TensorTapeCodec.vectorBits scope) hist out) ⟨rfl,rfl,rfl⟩\n  refine ⟨(8*mass w+40)+((5*code.val+4)+((code.val+1)+(t+1)))+1,?_,?_⟩\n  · unfold timeBound;omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n    rcases ho with ⟨hp,hd,hf⟩\n    change C.step program finish=some (done mode w tail scope hist out)\n    simp only [C.step,SemiprimeD1StackCalls.step,hp,Option.map_some,program,C.execute,hd,hf,done]\n/-- Genuine finite-machine execution, with the actual descriptor as its source\nand the acquired binary scope supplied by the explicit caller. -/\nnoncomputable def descriptorRecordInTime (code : Fin 18) (w : Record) (tail : List Bool)\n    (mode : SemiprimeD1StackBooleanEntry.Mode) (htag:w 0=List.replicate code.val true)\n    (hm:dispatch code=.local (.record mode)) (scope : List (List Bool)) (hist out : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration\n        (initial (record w tail) (SemiprimeD1TensorTapeCodec.vectorBits scope) hist out))\n      (some (SemiprimeD1StackCalls.configuration (done mode w tail scope hist out))) (timeBound code w mode scope) := by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .reader) (.inl R.history) (.local (.field 0)) program\n  have h:=source_run code w tail mode htag hm scope hist out\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackBooleanDescriptorRecordExecution\n","RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueExecution\nimport RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueHistory\n/-! # Uniform polynomial clock for the same binary-N-only Boolean factor acquirer -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueBounds\nopen SemiprimeD1StackBooleanFactorCatalogue SemiprimeD1StackBooleanFactorCatalogueSource\nopen SemiprimeD1StackBooleanFactorCatalogueLoop SemiprimeD1StackBooleanFactorCatalogueExecution\nopen SemiprimeD1StackBooleanFactorCataloguePrimitives\nopen SemiprimeD1BooleanFactorCatalogueIndices (key scopeWords indices vertex)\nopen SemiprimeD1BooleanFactorCatalogueIndicesBounds (occurrences)\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimePublicAcquiredExecution (factorCount)\n/-- Shared actual-width envelope, derived from the acquired source in proofs only. -/\ndef resource (bits : List Bool) : Nat :=\n  112*(occurrences (bitValue bits)+1)^2+8*(bits.length+10000000000000*(bits.length+1)^5)+300\n/-- One fixed per-factor polynomial, including repeated catalogue scans. -/\ndef cap (bits : List Bool) : Nat :=10^150*(bits.length+1)^35\n/-- Complete actual original-N clock; constants are fixed before the whole family. -/\ndef runBound (bits : List Bool) : Nat :=10^170*(bits.length+1)^40\nattribute [local irreducible] cap resource afterRows indices\n/-- The actual original occurrence domain is linear in binary input width. -/\ntheorem occurrences_linear (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    occurrences (bitValue bits) ≤ 12800*bits.length := by\n  have h:=SemiprimeD1RootTensorTables.actual_incidence_bound (bitValue bits) hN\n  rw [←SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc] at h\n  exact h\n/-- Actual scope width and descriptor acquisition imply the fixed per-row polynomial. -/\ntheorem resource_le_cap (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    resource bits ≤ cap bits := by\n  let I:=bits.length+1\n  have hI:1 ≤ I:=by dsimp [I];omega\n  have hM:=occurrences_linear bits hc hN\n  have hM1:occurrences (bitValue bits)+1 ≤ 12801*I:=by dsimp [I];omega\n  have hM2:=Nat.pow_le_pow_left hM1 2\n  rw [mul_pow] at hM2\n  have h2:I^2 ≤ I^35:=Nat.pow_le_pow_right hI (by decide : 2 ≤ 35)\n  have hM35:=hM2.trans (Nat.mul_le_mul_left ((12801:Nat)^2) h2)\n  have h5:I^5 ≤ I^35:=Nat.pow_le_pow_right hI (by decide : 5 ≤ 35)\n  have h1:I ≤ I^35:=by simpa only [pow_one] using Nat.pow_le_pow_right hI (by decide : 1 ≤ 35)\n  have hlen:bits.length ≤ I^35:=(by dsimp [I];omega : bits.length ≤ I).trans h1\n  have hP:1 ≤ I^35:=Nat.succ_le_of_lt (Nat.pow_pos (by dsimp [I];omega))\n  unfold resource cap\n  change 112*(occurrences (bitValue bits)+1)^2+8*(bits.length+10000000000000*I^5)+300 ≤ 10^150*I^35\n  nlinarith only [hM35,h5,hlen,hP]\n/-- One actual row, all cleanup and the subsequent EOF read fit the shared width envelope. -/\ntheorem rowBudget_le_resource (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f : Fin (factorCount (bitValue bits))) :\n    rowBudget bits (occurrences (bitValue bits)) f.val f+1 ≤ resource bits := by\n  let M:=occurrences (bitValue bits)\n  let v:=vertex (bitValue bits) f\n  have hs:=SemiprimeD1BooleanFactorCatalogueIndicesBounds.scope_count_le bits hc hN f\n  have hb:=SemiprimeD1StackPortOrdinalStreamBounds.bank_length (scopeWords bits f.val) M\n    (SemiprimeD1BooleanFactorCatalogueIndicesBounds.scope_word_length_le bits hc hN f)\n  have hd:=SemiprimeD1BooleanFactorCatalogueIndicesBounds.descriptor_length_le bits hc hN f\n  have hm:=SemiprimeD1StackBooleanDescriptorRecordEncoding.record_length (E.vertex v) []\n  rw [SemiprimeD1StackBooleanDescriptorRecordEncoding.record_vertex] at hm\n  have hA:=Nat.mul_le_mul_right (M+1) (Nat.add_le_add_right hs 1)\n  have hB:=Nat.mul_le_mul_right (2*M+2) hs\n  unfold rowBudget SemiprimeD1StackBooleanDescriptorRecordAll.rowBound resource\n  change 110*((scopeWords bits f.val).length+1)*(M+1)+\n      7*(SemiprimeD1StackBooleanDescriptorRecordEncoding.record (E.vertex v) []).length+222+\n      SemiprimeD1StackBooleanDescriptorRecordEncoding.mass (E.vertex v)+\n      (SemiprimeD1TensorTapeCodec.vectorBits (scopeWords bits f.val)).length+9+1 ≤\n    112*(M+1)^2+8*(bits.length+10000000000000*(bits.length+1)^5)+300\n  rw [SemiprimeD1StackBooleanDescriptorRecordEncoding.record_vertex]\n  simp only [List.length_nil,Nat.add_zero] at hm\n  change (SemiprimeD1VertexCatalogueEncoding.vertex v []).length ≤ _ at hd\n  nlinarith\n/-- Each original row plus its real next-EOF test has an own fixed polynomial cost. -/\ntheorem rowBudget_le_cap (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f : Fin (factorCount (bitValue bits))) :\n    rowBudget bits (occurrences (bitValue bits)) f.val f+1 ≤ cap bits :=\n  (rowBudget_le_resource bits hc hN f).trans (resource_le_cap bits hc hN)\n/-- Every retained-source query is paid from its actual copy/filter execution clock. -/\ntheorem query_le_cap (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f : Fin (factorCount (bitValue bits))) :\n    SemiprimeD1StackFactorScopeFibreExecution.preparedTime bits (key f.val)+2 ≤ cap bits := by\n  have hb:bits≠[]:=by intro h;rw [h] at hN;exact Nat.lt_irrefl _ hN\n  have h0:SemiprimeD1StackFactorScopeFibreExecution.preparedTime bits (key f.val)+2 ≤\n      SemiprimeD1StackFactorScopeFibreExecution.timeBound bits (key f.val):=by\n    unfold SemiprimeD1StackFactorScopeFibreExecution.timeBound;omega\n  have h1:=SemiprimeD1StackFactorScopeFibreBounds.timeBound_le bits (key f.val) hb\n  have h2:=SemiprimeD1StackFactorScopeFibreBounds.original_timeBound bits hc hN f\n  have hcst:(10:Nat)^140 ≤ 10^150:=by norm_num\n  unfold cap\n  exact h0.trans (h1.trans (h2.trans (Nat.mul_le_mul_right _ hcst)))\n/-- Actual history grows by at most one shared polynomial allowance per original descriptor. -/\ntheorem history_le_cap (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f : Fin (factorCount (bitValue bits))) (hist : List Bool) :\n    (DA.afterHistory (vertex (bitValue bits) f) (scopeWords bits f.val) hist).length ≤ hist.length+cap bits := by\n  have hr:=resource_le_cap bits hc hN\n  have hs:=SemiprimeD1BooleanFactorCatalogueIndicesBounds.scope_count_le bits hc hN f\n  have hp:=SemiprimeD1StackBooleanRecordBounds.ports_length (scopeWords bits f.val) (occurrences (bitValue bits))\n    (SemiprimeD1BooleanFactorCatalogueIndicesBounds.scope_word_value_le bits hc hN f)\n  have hB:=Nat.mul_le_mul_right (2*occurrences (bitValue bits)+2) hs\n  unfold SemiprimeD1StackBooleanDescriptorRecordAll.afterHistory\n  cases hm:SemiprimeD1StackBooleanDescriptorRecordOriginal.originalMode (vertex (bitValue bits) f) with\n  | none=>exact Nat.le_add_right _ _\n  | some mode=>\n    have ht:=SemiprimeD1StackBooleanRecordBounds.table_length mode\n    simp only [List.length_append,List.length_reverse]\n    have hl:(SemiprimeD1StackBooleanRecord.R.row (SemiprimeD1StackBooleanRecord.S.result (scopeWords bits f.val))\n        (SemiprimeD1StackBooleanRecord.table mode)).length=\n      2*(SemiprimeD1StackBooleanRecord.S.result (scopeWords bits f.val)).length+\n        2*(SemiprimeD1StackBooleanRecord.table mode).length+3 := by\n      simp only [SemiprimeD1StackVertexRecordStream.row,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,\n        List.length_nil]\n      omega\n    rw [hl]\n    have hp2:(SemiprimeD1StackBooleanRecord.S.result (scopeWords bits f.val)).length ≤\n        occurrences (bitValue bits)*(2*occurrences (bitValue bits)+2)+1:=by omega\n    have hr2:112*(occurrences (bitValue bits)+1)^2+300 ≤ cap bits:=by\n      unfold resource at hr\n      omega\n    have hx:2*(SemiprimeD1StackBooleanRecord.S.result (scopeWords bits f.val)).length+\n        2*(SemiprimeD1StackBooleanRecord.table mode).length+3 ≤\n        112*(occurrences (bitValue bits)+1)^2+300 := by nlinarith only [hp2,ht]\n    omega\n/-- Actual repeated copy/filter work is linear in the number of physically\nprocessed descriptors, with a fixed original-width polynomial per descriptor. -/\ntheorem loopBudget_le (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (n : Nat) (fs : List (Fin (factorCount (bitValue bits))))\n    (hseq:fs.map Fin.val=List.range' n fs.length) :\n    loopBudget bits (occurrences (bitValue bits)) n fs ≤ 2*cap bits*fs.length := by\n  induction fs generalizing n with\n  | nil=>rfl\n  | cons f fs ih=>\n    have horder:=SemiprimeD1BooleanFactorCatalogueIndicesBounds.cons_values (bitValue bits) n f fs hseq\n    have hr:=rowBudget_le_cap bits hc hN f\n    rw [horder.1] at hr\n    cases fs with\n    | nil=>\n      change rowBudget bits (occurrences (bitValue bits)) n f+1+0 ≤ 2*cap bits*1\n      omega\n    | cons g gs=>\n      have hg:=SemiprimeD1BooleanFactorCatalogueIndicesBounds.cons_values (bitValue bits) (n+1) g gs horder.2\n      have hq:=query_le_cap bits hc hN g\n      rw [hg.1] at hq\n      have hi:=ih (n+1) horder.2\n      change rowBudget bits (occurrences (bitValue bits)) n f+1+\n          (SemiprimeD1StackFactorScopeFibreExecution.preparedTime bits (key (n+1))+2+\n            loopBudget bits (occurrences (bitValue bits)) (n+1) (g::gs)) ≤\n        2*cap bits*((g::gs).length+1)\n      nlinarith only [hr,hq,hi]\n/-- The actual accumulated history has a fixed polynomial width per emitted row. -/\ntheorem history_bound (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (n : Nat) (fs : List (Fin (factorCount (bitValue bits))))\n    (hseq:fs.map Fin.val=List.range' n fs.length) (hist : List Bool) :\n    (afterRows bits n fs hist).length ≤ hist.length+cap bits*fs.length := by\n  rw [SemiprimeD1StackBooleanFactorCatalogueHistory.afterRows_fold bits n fs hseq]\n  exact SemiprimeD1StackBooleanFactorCatalogueHistory.fold_length\n    (fun f=>DA.afterHistory (vertex (bitValue bits) f) (scopeWords bits f.val))\n    (cap bits) (history_le_cap bits hc hN) fs hist\n/-- The same whole actual setup has a fixed polynomial allowance from original N. -/\ntheorem setup_le_cap (bits : List Bool) : setupBound bits ≤ cap bits := by\n  have hI:1 ≤ bits.length+1:=by omega\n  have h30:=Nat.pow_le_pow_right hI (by decide : 30 ≤ 35)\n  have h5:=Nat.pow_le_pow_right hI (by decide : 5 ≤ 35)\n  have h1:(bits.length+1) ≤ (bits.length+1)^35:=by\n    simpa only [pow_one] using Nat.pow_le_pow_right hI (by decide : 1 ≤ 35)\n  have hp:1 ≤ (bits.length+1)^35:=Nat.succ_le_of_lt (Nat.pow_pos (by omega))\n  unfold setupBound SemiprimeD1StackFactorScopeFibreBounds.runBound cap\n  simp only [List.length_nil,Nat.zero_add,Nat.mul_one]\n  nlinarith only [h30,h5,h1,hp]\n/-- Complete WHOLE N-only Boolean factor-record acquisition clock, including\nsource acquisition, every query/cleanup, output reversal and literal halt. -/\ntheorem timeBound_le_runBound (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    timeBound bits ≤ runBound bits := by\n  have hs:=setup_le_cap bits\n  have hl:=loopBudget_le bits hc hN 0 (indices (bitValue bits)) (indices_sequence (bitValue bits))\n  have hh0:=history_bound bits hc hN 0 (indices (bitValue bits)) (indices_sequence (bitValue bits)) []\n  have hh:(afterRows bits 0 (indices (bitValue bits)) []).length ≤ cap bits*(indices (bitValue bits)).length:=\n    hh0.trans (Nat.zero_add _).le\n  have hC:1 ≤ cap bits:=Nat.succ_le_of_lt (by unfold cap;positivity)\n  have hm:timeBound bits ≤ cap bits*(4*(indices (bitValue bits)).length+5):=by\n    unfold timeBound\n    nlinarith only [hs,hl,hh,hC]\n  have hF:=SemiprimeD1StackFactorScopeFibreBounds.factor_count_le bits hc hN\n  have hp:1 ≤ (bits.length+1)^5:=Nat.succ_le_of_lt (Nat.pow_pos (by omega))\n  have hFC:4*(indices (bitValue bits)).length+5 ≤ 10000000000000000*(bits.length+1)^5:=by\n    rw [indices_length]\n    nlinarith only [hF,hp]\n  calc\n    _ ≤ cap bits*(4*(indices (bitValue bits)).length+5):=hm\n    _ ≤ cap bits*(10000000000000000*(bits.length+1)^5):=Nat.mul_le_mul_left _ hFC\n    _ = (10^150*10000000000000000)*((bits.length+1)^35*(bits.length+1)^5):=by unfold cap;ring\n    _ = 10^166*((bits.length+1)^35*(bits.length+1)^5):=by\n      rw [show (10000000000000000:Nat)=10^16 by norm_num,←pow_add]\n    _ ≤ 10^170*((bits.length+1)^35*(bits.length+1)^5):=\n      Nat.mul_le_mul_right _ (Nat.pow_le_pow_right (by decide : 1 ≤ (10:Nat)) (by decide : 166 ≤ 170))\n    _ = runBound bits:=by unfold runBound;rw [←pow_add]\n/-- Actual original-N source trace with the fixed polynomial, not a retained report clock. -/\ntheorem source_run_polynomial (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t ≤ runBound bits,C.run program t (initial bits)=some (done bits) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits hc hN\n  exact ⟨t,ht.trans (timeBound_le_runBound bits hc hN),hr⟩\n/-- Same actual finite-control machine, from canonical binary N alone, with its\nentire own polynomial clock and no acquired-data or branch supplier. -/\nnoncomputable def machineBounded (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (runBound bits) := by\n  have h:=machineCatalogue bits hc hN\n  exact ⟨h.toEvalsTo,h.steps_le_m.trans (timeBound_le_runBound bits hc hN)⟩\n/-- Entire actual218-role source and all real return cells, at every reached prefix. -/\ntheorem polynomial_prefix_cells (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel : Nat) (finish : C.State Stack Label) (hr:C.run program fuel (initial bits)=some finish) :\n    (∑k:Stack,(finish.data k).length)+finish.frames.length ≤ 219*(bits.length+runBound bits) :=\n  (prefix_cells bits hc hN fuel finish hr).trans\n    (Nat.mul_le_mul_left 219 (Nat.add_le_add_left (timeBound_le_runBound bits hc hN) bits.length))\n/-- Same complete inventory in the actual compiled binary-N machine. -/\ntheorem polynomial_machine_prefix_cells (bits : List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 219*(bits.length+runBound bits) :=\n  (machine_prefix_cells bits hc hN fuel cfg hr).trans\n    (Nat.mul_le_mul_left 219 (Nat.add_le_add_left (timeBound_le_runBound bits hc hN) bits.length))\nend RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueBounds\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankClearEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankState\n/-! # Exact partial physical cleanup views and whole236-role cost\nOnly heap/counter persist. Every other actual component/shadow role belongs to\nthe finite sweep; mathematical prefixes/costs are not runtime operands.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankClearEncoding\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankState\nprivate instance:BEq P.Stack:=⟨fun a b=>decide (a=b)⟩\nprivate instance:LawfulBEq P.Stack where\n  eq_of_beq:=by intro a b h;exact of_decide_eq_true h\n  rfl:=by intro a;exact decide_eq_true rfl\n/-- Mathematical view after exactly n fixed physical ports have been visited. -/\ndef through (bank:P.Stack→List Bool) (n:Nat):P.Stack→List Bool:=fun k=>\n  if persistent k then bank k else if k∈I.roles.take n then [] else bank k\n/-- Exact fully swept bank; only the two actual immutable input roles remain. -/\ndef cleared (bank:P.Stack→List Bool):P.Stack→List Bool:=fun k=>if persistent k then bank k else []\n/-- No word changes before the first real sweep instruction. -/\ntheorem through_zero (bank:P.Stack→List Bool):through bank 0=bank:=by funext k;simp [through]\n/-- Complete sweep covers every real role, including every unused shadow allocation. -/\ntheorem through_all (bank:P.Stack→List Bool):through bank 238=cleared bank:=by\n  have ht:I.roles.take 238=I.roles:=by rw [←I.roles_length,List.take_length]\n  funext k\n  simp only [through,cleared,ht,I.roles_complete,ite_true]\n/-- The finite next port is really appended to the processed-prefix inventory. -/\ntheorem take_step (i:Fin 238):I.roles.take (i.val+1)=I.roles.take i.val++[I.role i]:=\n  List.take_succ_eq_append_getElem (by rw [I.roles_length];exact i.isLt)\n/-- Distinct cleanup labels have not previously modified the current real word. -/\ntheorem current_not_seen (i:Fin 238):I.role i∉I.roles.take i.val:=by\n  intro h\n  obtain ⟨j,hj,he⟩:=List.mem_take_iff_getElem.mp h\n  have hi:j < i.val:=lt_of_lt_of_le hj (Nat.min_le_left _ _)\n  have heq:j=i.val:=I.roles_nodup.getElem_inj.mp he\n  omega\n/-- The next actual word length is its ORIGINAL stopped-callee payload length. -/\ntheorem through_current (bank:P.Stack→List Bool) (i:Fin 238):through bank i.val (I.role i)=bank (I.role i):=by\n  simp only [through,current_not_seen,ite_false,ite_self]\n/-- A retained heap/counter port is skipped by an actual jump and has no mathematical change. -/\ntheorem through_skip (bank:P.Stack→List Bool) (i:Fin 238) (hp:persistent (I.role i)=true):\n    through bank (i.val+1)=through bank i.val:=by\n  funext k\n  by_cases hk:k=I.role i\n  · subst k;simp only [through,hp,ite_true]\n  · simp only [through,take_step,List.mem_append,List.mem_singleton,hk,or_false]\n/-- Every other real port advances ONLY by its actual physical drain. -/\ntheorem through_clear (bank:P.Stack→List Bool) (i:Fin 238) (hp:persistent (I.role i)=false):\n    through bank (i.val+1)=Function.update (through bank i.val) (I.role i) []:=by\n  funext k\n  by_cases hk:k=I.role i\n  · subst k;simp only [through,hp,Bool.false_eq_true,ite_false,Function.update_self,take_step,List.mem_append,List.mem_singleton,or_true,ite_true]\n  · simp only [Function.update_of_ne hk,through,take_step,List.mem_append,List.mem_singleton,hk,or_false]\n/-- Each physical sweep port costs one EOF pop/jump, plus precisely its nonpersistent payload bits. -/\ndef portTime (bank:P.Stack→List Bool) (k:P.Stack):Nat:=if persistent k then 1 else (bank k).length+1\n/-- Sum of the SAME actual future physical drain/jump costs. -/\ndef sweepTime (bank:P.Stack→List Bool) (n:Nat):Nat:=((I.roles.drop n).map (portTime bank)).sum\n/-- Exact remaining-time recurrence for the next finite source port. -/\ntheorem sweepTime_step (bank:P.Stack→List Bool) (i:Fin 238):\n    sweepTime bank i.val=portTime bank (I.role i)+sweepTime bank (i.val+1):=by\n  have hd:I.roles.drop i.val=I.role i::I.roles.drop (i.val+1):=\n    List.drop_eq_getElem_cons (by rw [I.roles_length];exact i.isLt)\n  simp only [sweepTime,hd,List.map_cons,List.sum_cons]\n/-- No hidden cleanup occurs after the last actual physical port. -/\ntheorem sweepTime_all (bank:P.Stack→List Bool):sweepTime bank 238=0:=by\n  unfold sweepTime\n  rw [←I.roles_length,List.drop_length]\n  rfl\n/-- Exactly236 actual callee allocations are drained; exactly heap/counter are skipped. -/\ntheorem clear_count:(I.roles.filter (fun k=>!persistent k)).length=236:=by decide\n/-- All actual sweep work has a linear cap in the actual full stopped-bank word bound. -/\ntheorem sweepTime_le (bank:P.Stack→List Bool) (L:Nat) (h:∀k,(bank k).length ≤L):\n    sweepTime bank 0 ≤238*(L+1):=by\n  have hbound:∀ks:List P.Stack,(ks.map (portTime bank)).sum ≤ks.length*(L+1):=by\n    intro ks\n    induction ks with\n    | nil=>simp only [List.map_nil,List.sum_nil,List.length_nil,Nat.zero_mul,Nat.le_refl]\n    | cons k ks ih=>\n      have hk:portTime bank k ≤L+1:=by\n        unfold portTime\n        split_ifs <;> have h0:=h k <;> omega\n      simp only [List.map_cons,List.sum_cons,List.length_cons,Nat.add_mul,Nat.one_mul]\n      omega\n  simpa only [sweepTime,List.drop_zero,I.roles_length] using hbound I.roles\n/-- The actually cleared copy scratch is safe to borrow before the next real parser/copy/callee call. -/\ntheorem cleared_scratch (bank:P.Stack→List Bool):cleared bank P.copyScratch=[]:=by\n  simp only [cleared,scratch_not_persistent,Bool.false_eq_true,ite_false]\n/-- Every skipped physical heap/counter word remains literally unchanged through the full sweep. -/\ntheorem cleared_retained (bank:P.Stack→List Bool) (k:P.Stack) (hp:persistent k=true):cleared bank k=bank k:=by\n  simp only [cleared,hp,ite_true]\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankClearEncoding\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankCalls\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankBinding\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinateEncoding\n/-! # Four actual input words and exact original-order phase-bank output ABI\nRequests describe literal issued-reference and child-field pairs in proofs.\nNo request object, bank answer, phase, function or mode list inhabits runtime.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankEncoding\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankState\nopen SemiprimeD1StackJetFoldWords (Modes modeTape)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace O\nexport SemiprimeD1StackCachePhaseRootOriginal (rootSource rootDone rootSize)\nend O\nnamespace R\nexport SemiprimeD1StackRootPhaseFreshRecords (heap aux)\nexport SemiprimeD1StackRootPhaseFreshRecordsEncoding (result)\nend R\nnamespace A\nexport SemiprimeD1StackFreshBankRestoreOriginal (reference)\nend A\n/-- Actual issued-phase ordinal paired with actual per-phase nested recursive-child bytes, proof notation ONLY. -/\nabbrev Request (bits:List Bool):=Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length×Modes\n/-- Actual framed stream of acquired allocator-issued reference WORDS; no ordinal is encoded during runtime. -/\ndef references (bits:List Bool) (requests:List (Request bits)):List Bool:=vectorBits (requests.map (fun r=>A.reference bits r.1))\n/-- Actual framed stream of the corresponding physically retained per-phase child tapes. -/\ndef children {bits:List Bool} (requests:List (Request bits)):List Bool:=vectorBits (requests.map (fun r=>modeTape r.2))\n/-- Actual byte payload acquired by ONE real238-role source; this is a proof-side projection, never an operand. -/\ndef payload (bits:List Bool) (r:Request bits):List Bool:=\n  (O.rootDone bits r.1 r.2).data (SemiprimeD1StackCachePhase.blockStack (SemiprimeD1StackCachePhase.Blocks.aux .output))\n/-- Exact output vector in original physical reference/child-pair order, including repeats/rejections. -/\ndef result (bits:List Bool) (requests:List (Request bits)):List Bool:=vectorBits (requests.map (payload bits))\n/-- Physical four-word prepared source; original-N acquisition/recursive child production are separate upstream tasks. -/\ndef source (bits:List Bool) (requests:List (Request bits)):C.State Stack Label:=\n  initial (R.result bits R.heap) (R.result bits (R.aux .counter)) (references bits requests) (children requests)\n/-- Literal stopped bank from its immutable physical heap/counter only; all other238-role words are empty. -/\ndef base (bits:List Bool):P.Stack→List Bool:=P.input (R.result bits R.heap) (R.result bits (R.aux .counter)) [] []\n/-- Exact full246-role successful halt, with final true status physically written only after scratch's last use. -/\ndef done (bits:List Bool) (requests:List (Request bits)):C.State Stack Label:=\n  ⟨none,none,none,Function.update (data (base bits)\n    (words {references:=references bits requests,children:=children requests,output:=result bits requests})) status [true],[]⟩\n/-- Literal tagged payload chunk, before the final outer false sentinel. -/\ndef chunk (word:List Bool):List Bool:=SemiprimeD1StackRecoveryCoordinateEncoding.chunk word\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankEncoding\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankLoop\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankPrepare\n/-! # Whole four-input actual phase-bank acquisition\nThe sole fixed program copies both actual vectors, parses each real pair,\nexecutes one real phase source, logs its actual output, cleans all236 roles,\nchecks both EOFs, reverses once and writes true status before the actual halt.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankExecution\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankState\nopen SemiprimeD1StackCachePhaseBankEncoding SemiprimeD1StackCachePhaseBankLoop\nopen SemiprimeD1StackCachePhaseBankPrepare SemiprimeD1StackCachePhaseBankPrimitives\nopen SemiprimeD1StackProcedureTrace\nattribute [local irreducible] SemiprimeD1StackRootPhaseFreshRecordsEncoding.result\n  SemiprimeD1StackRootPhaseParametersEncoding.phases\n  SemiprimeD1StackRootPhaseParametersEncoding.exponentValue\n  SemiprimeD1StackRootPhaseParametersEncoding.levelsValue\n  SemiprimeD1StackRootPhaseParametersEncoding.edgeValue\n/-- Whole physical source cap: actual reader preparation, same-source replay caps and genuine final halt. -/\ndef timeBound (bits:List Bool) (requests:List (Request bits)):Nat:=\n  prepareTime (references bits requests) (children requests)+replayBound bits requests []+1\n/-- Complete SAMEprogram source trace, before the actual final halt. -/\ntheorem source_trace (bits:List Bool) (requests:List (Request bits)):\n    ∃t,t+1 ≤timeBound bits requests ∧Runs program t (.local .start) (source bits requests).data\n      (.local .done) (done bits requests).data:=by\n  have h0:=prepare_run (R.result bits R.heap) (R.result bits (R.aux .counter)) (references bits requests) (children requests)\n  obtain ⟨t,ht,h1⟩:=replay_run bits requests (references bits requests) (children requests) [] [false]\n  simp only [List.reverse_nil,List.nil_append,chunks_vector] at h1\n  have h:=join h0 h1\n  exact ⟨_,by unfold timeBound;omega,h⟩\n/-- Actual whole source from ONLY real heap/counter/reference-vector/child-vector words, with clear real return frames. -/\ntheorem source_run (bits:List Bool) (requests:List (Request bits)):\n    ∃t ≤timeBound bits requests,SemiprimeD1StackCalls.run program t (source bits requests)=some (done bits requests):=by\n  obtain ⟨t,ht,h⟩:=source_trace bits requests\n  obtain ⟨out,hr,ha⟩:=h [] (source bits requests) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (.local .done) rfl (done bits requests).data [] out ha\n  refine ⟨t+1,ht,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n  exact hh\n/-- True status is a real singleton written AFTER the scratch's final use, not an input validity flag. -/\ntheorem status_true (bits:List Bool) (requests:List (Request bits)):(done bits requests).data status=[true]:=by\n  simp only [done,Function.update_self]\n/-- The acquired phase-bank vector contains every actual per-reference output in chronological source order. -/\ntheorem output_tape (bits:List Bool) (requests:List (Request bits)):(done bits requests).data output=result bits requests:=rfl\n/-- Entire original reference/child vector words remain literally unchanged. -/\ntheorem inputs_retained (bits:List Bool) (requests:List (Request bits)):\n    (done bits requests).data (aux .references)=references bits requests ∧\n      (done bits requests).data (aux .children)=children requests:=⟨rfl,rfl⟩\n/-- Generic final projection precedes substitution of any original-N heap/context. -/\ntheorem final_heap_counter (hp cn:List Bool) (w:Aux→List Bool) (flag:List Bool):\n    (Function.update (data (P.input hp cn [] []) w) status flag) heap=hp ∧\n      (Function.update (data (P.input hp cn [] []) w) status flag) counter=cn:=⟨rfl,rfl⟩\n/-- Original physical heap/counter remain literally unchanged after every source and cleanup. -/\ntheorem heap_counter_retained (bits:List Bool) (requests:List (Request bits)):\n    (done bits requests).data heap=R.result bits R.heap ∧\n      (done bits requests).data counter=R.result bits (R.aux .counter):=by\n  have h:=final_heap_counter (R.result bits R.heap) (R.result bits (R.aux .counter))\n    (words {references:=references bits requests,children:=children requests,output:=result bits requests}) [true]\n  exact h\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankExecution\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankResources\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankOriginalRows\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankSemanticCaps\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinateOriginal\n/-! # Complete actual issued-phase bank and exact original coordinate-consumer bytes\nThe source consumes ONLY four actual words. Root345's actual chronological\nreference vector determines every call; functions below name already supplied\nchild bytes in proofs, and are not runtime operands. Recursive child production\nand a literal N-only producer/iterator join remain upstream OPEN.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankOriginal\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankEncoding\nopen SemiprimeD1StackCachePhaseBankOriginalRows SemiprimeD1StackCachePhaseBankBounds\nopen SemiprimeD1StackCachePhaseBankInputBounds\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackJetFoldWords (Modes modeTape)\nnamespace F\nexport SemiprimeD1StackFreshBankRestoreOriginal (output_references producer_lineage banks reference root_issued)\nend F\nnamespace Root\nexport SemiprimeD1StackRootPhaseFreshRecords (output program initial)\nexport SemiprimeD1StackRootPhaseFreshRecordsEncoding (done)\nexport SemiprimeD1StackRootPhaseFreshRecordsExecution (runBound)\nend Root\nattribute [local irreducible] SemiprimeD1StackRootPhaseFreshRecordsEncoding.result\n  SemiprimeD1StackRootPhaseParametersEncoding.phases\n/-- Every original chronological phase is visited exactly once, including rejected/empty phases.\nRows denote actual nested child words in proofs only; runtime sees their encoded vector. -/\ndef chronological (bits:List Bool)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):List (Request bits):=\n  List.ofFn (fun i=>(i,rows i))\n/-- The loop input is the ENTIRE physically produced issued-reference output, not an advised permutation. -/\ntheorem references_original (bits:List Bool)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):\n    references bits (chronological bits rows)=R.result bits Root.output:=by\n  rw [F.output_references]\n  simp only [references,chronological,List.map_ofFn]\n  rfl\n/-- Actual per-phase recursive answer byte input, without a supplied cache answer. -/\ndef childInput (bits:List Bool)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):List Bool:=\n  vectorBits (List.ofFn (fun i=>modeTape (rows i)))\n/-- Exact chronological children encoding, keeping rejected phase occurrences as well. -/\ntheorem children_original (bits:List Bool)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):\n    children (chronological bits rows)=childInput bits rows:=by\n  simp only [children,chronological,childInput,List.map_ofFn]\n  rfl\n/-- The actual full iterator starts from the reached heap/counter/output-ref words and actual child bytes ONLY. -/\ndef prepared (bits:List Bool)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):C.State Stack Label:=\n  initial (R.result bits R.heap) (R.result bits (R.aux .counter)) (R.result bits Root.output) (childInput bits rows)\n/-- Four literal word equalities establish the complete initial state before original arithmetic is instantiated. -/\ntheorem source_actual (bits:List Bool)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):\n    source bits (chronological bits rows)=prepared bits rows:=by\n  unfold source prepared\n  rw [references_original,children_original]\n/-- Actual original phase count; no phase-count operand or termination oracle enters the program. -/\ntheorem chronological_count (bits:List Bool)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):\n    (chronological bits rows).length=(SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length:=\n  List.length_ofFn\n/-- Whole actual iterator produces exact native ascending block bytes for EVERY original issued phase. -/\ntheorem source_original (bits:List Bool)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):\n    ∃t ≤runBound bits (chronological bits rows),\n      SemiprimeD1StackCalls.run program t (prepared bits rows)=some (done bits (chronological bits rows)) ∧\n      (done bits (chronological bits rows)).data output=Col.originalTape (phases bits (chronological bits rows)):=by\n  obtain ⟨t,ht,hr⟩:=source_run_bounded bits (chronological bits rows)\n  rw [source_actual] at hr\n  exact ⟨t,ht,hr,original_tape bits (chronological bits rows)⟩\n/-- Genuine original allocator lineage and SAME actual source clocks, without calling a pair of sources one machine. -/\ntheorem producer_and_bank (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<SemiprimeBitArithmetic.bitValue bits)\n    (rows:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length→Modes):\n    ∃p ≤Root.runBound bits,∃t ≤runBound bits (chronological bits rows),\n      SemiprimeD1StackCalls.run Root.program p (Root.initial bits)=some (Root.done bits) ∧\n      SemiprimeD1StackHeapReadBounds.History\n        (SemiprimeD1StackFreshBankRestoreExecution.records (F.banks bits))\n        (R.result bits R.heap) (R.result bits (R.aux .counter)) ∧\n      (∀i:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length,\n        SemiprimeD1StackHeapReadBounds.Issued\n          (SemiprimeD1StackFreshBankRestoreExecution.records (F.banks bits)) (F.reference bits i)) ∧\n      SemiprimeD1StackCalls.run program t (prepared bits rows)=some (done bits (chronological bits rows)) ∧\n      (done bits (chronological bits rows)).data output=Col.originalTape (phases bits (chronological bits rows)):=by\n  obtain ⟨p,hp,hr,hh,_href,hi⟩:=F.producer_lineage bits hc hN\n  obtain ⟨t,ht,he,ho⟩:=source_original bits rows\n  exact ⟨p,hp,t,ht,hr,hh,hi,he,ho⟩\n/-- Exact old coordinate-cache bytes of the acquired ACTUAL phase blocks, including rejected rows and EOF defaults. -/\ntheorem coordinate_identity (bits:List Bool) (requests:List (Request bits)) (key:List Bool):\n    SemiprimeD1StackRecoveryCoordinateEncoding.result (requests.map (blocks bits)) key=\n      SemiprimeD1StackRecoveryEntriesEncoding.childTape\n        (SemiprimeD1PhysicalRecursiveCounter.coordinateCache\n          (SemiprimeD1RecursiveCounter.coordinate (phases bits requests) (SemiprimeBitArithmetic.bitValue key))):=by\n  have h:=SemiprimeD1StackRecoveryCoordinateOriginalRows.result_original (phases bits requests) key\n  have hv:SemiprimeD1StackRecoveryCoordinateOriginalRows.originalPhases (phases bits requests)=requests.map (blocks bits):=by\n    unfold SemiprimeD1StackRecoveryCoordinateOriginalRows.originalPhases phases\n    simp only [List.map_map,Function.comp_def]\n    rfl\n  rw [hv] at h\n  exact h\n/-- Uniform fixed coefficient/degree precede all prepared four-word source instances. -/\ntheorem uniform_source:∃coef degree:Nat,∀(bits:List Bool) (requests:List (Request bits)),\n    ∃t ≤coef*(resource bits requests+2)^degree,\n      SemiprimeD1StackCalls.run program t (source bits requests)=some (done bits requests):=by\n  exact ⟨10^100,18,source_run_bounded⟩\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankOriginal\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankOriginalRows":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankEncoding\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinateOriginalRows\n/-! # Actual restored guard, exact native block words and Coordinate21 ABI\nThe blocks below are derived from the actual stopped phase source. Rejected\nphases remain present with an empty block vector. OLD precision remains two;\nNEW working precision is read from the distinct originally acquired cache.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankOriginalRows\nopen SemiprimeD1StackCachePhaseBankEncoding\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace X\nexport SemiprimeD1StackCachePhaseRootOriginal (good dimension newPrecision)\nend X\nnamespace Col\nexport SemiprimeD1StackRecoveryCoordinateEncoding (tape)\nexport SemiprimeD1StackRecoveryCoordinateOriginalRows (originalTape originalPhases phaseWords)\nend Col\nattribute [local irreducible] SemiprimeD1StackFreshBankRestoreOriginal.banks\n  SemiprimeD1StackRootPhaseParametersEncoding.phases\n  SemiprimeD1StackRootPhaseParametersEncoding.exponentValue\n  SemiprimeD1StackRootPhaseParametersEncoding.levelsValue\n  SemiprimeD1StackRootPhaseParametersEncoding.edgeValue\n  SemiprimeD1StackCachePhaseRootOriginal.good\n  SemiprimeD1StackCachePhaseRootOriginal.dimension\n  SemiprimeD1StackCachePhaseRootOriginal.newPrecision\n/-- Actual native ascending OLD-coordinate blocks of the literal NEW-precision right fold. -/\ndef blocks (bits:List Bool) (r:Request bits):List (List (List Bool)):=\n  if X.good bits r.1 then\n    (List.range (X.dimension bits r.1)).map (fun j=>\n      (SemiprimeD1JetBlockBits.extract (⟨[],2⟩:SemiprimeD1JetAxes.Context) j\n        (SemiprimeD1StackCachePhaseExecution.coefficients [] (X.dimension bits r.1)\n          (X.newPrecision bits r.1) r.2)).words)\n  else []\n/-- The actual complete238-role output equals that native block codec, without a branch flag input. -/\ntheorem payload_native (bits:List Bool) (r:Request bits):\n    payload bits r=vectorBits ((blocks bits r).map vectorBits):=by\n  cases hg:X.good bits r.1 with\n  | false=>\n    unfold payload O.rootDone blocks\n    simp only [hg,Bool.false_eq_true,ite_false,List.map_nil]\n    rfl\n  | true=>\n    unfold payload O.rootDone blocks\n    simp only [hg,ite_true]\n    have h:=SemiprimeD1StackCachePhaseOriginal.output_native\n      (SemiprimeD1StackFreshBankRestoreOriginal.banks bits) (SemiprimeD1StackFreshBankRestoreOriginal.ordinal bits r.1)\n      [] [false,true] (X.dimension bits r.1) (X.newPrecision bits r.1) r.2\n    have hp:SemiprimeBitArithmetic.bitValue [false,true]=2:=by decide\n    rw [hp] at h\n    simpa only [SemiprimeD1StackCachePhaseExecution.done,List.map_map,Function.comp_def] using h\n/-- Exact Coordinate21 phase-bank bytes preserve chronological duplicates and every rejected row. -/\ntheorem result_codec (bits:List Bool) (requests:List (Request bits)):\n    result bits requests=Col.tape (requests.map (blocks bits)):=by\n  unfold result Col.tape\n  simp only [List.map_map,Function.comp_def]\n  congr 1\n  apply List.map_congr_left\n  intro r _\n  exact payload_native bits r\n/-- A rejected issued phase produces the literal empty-vector payload, rather than being omitted. -/\ntheorem rejected_payload (bits:List Bool) (r:Request bits) (hg:X.good bits r.1=false):\n    payload bits r=[false]:=by\n  rw [payload_native]\n  simp only [blocks,hg,Bool.false_eq_true,ite_false,List.map_nil]\n  rfl\n/-- Proof-side old PhaseRun representation of these ACTUAL block bytes; no report clock is transported. -/\ndef phase (bits:List Bool) (r:Request bits):SemiprimeD1RecursiveCounter.PhaseRun:=\n  ⟨(blocks bits r).toArray,if X.good bits r.1 then SemiprimeBitArithmetic.bitValue (X.newPrecision bits r.1) else 0,0⟩\n/-- The ordered PhaseRun view contains no supplied cache answers: all blocks were acquired by the real source. -/\ndef phases (bits:List Bool) (requests:List (Request bits)):Array SemiprimeD1RecursiveCounter.PhaseRun:=\n  (requests.map (phase bits)).toArray\n/-- Exact original PhaseRun/block encoder, independent of native report clocks. -/\ntheorem original_tape (bits:List Bool) (requests:List (Request bits)):\n    result bits requests=Col.originalTape (phases bits requests):=by\n  rw [result_codec]\n  unfold Col.originalTape Col.originalPhases phases\n  simp only [List.map_map,Function.comp_def]\n  rfl\n/-- The actual logged phase count includes all rejected and repeated issued references. -/\ntheorem phase_count (bits:List Bool) (requests:List (Request bits)):(phases bits requests).size=requests.length:=by\n  simp only [phases,List.size_toArray,List.length_map]\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankOriginalRows\n","RiemannGaussian.SemiprimeD1StackCachePhasePrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseView\n/-! # Actual cache-handoff copies with their own physical calls and returns -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhasePrimitives\nopen SemiprimeD1StackCachePhase SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Actual fragments concatenate with all external real return frames retained. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Every cache/input handoff is a real preserving copy, not a semantic operand assignment. -/\ntheorem copy_call (site:Copy) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copySource site)=xs) (hy:before (copyTarget site)=ys) (hs:before copyScratch=[]) :\n    Runs program (5*xs.length+4) (ctl (.copy site)) before (copyNext site)\n      (Function.update before (copyTarget site) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack site) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack site) (copy_injective site) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack site) (Label.copy site) (copy_injective site) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl (.copy site)) (copyNext site) rfl (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- A real local push is used for the rejected phase's empty vector terminal. -/\ntheorem reject_run (before:Stack→List Bool) :\n    Runs program 1 (ctl .reject) before (ctl .done)\n      (Function.update before (blockStack (Blocks.aux .output)) (false::before (blockStack (Blocks.aux .output)))) :=\n  one_base program _ _ _ _ _ rfl rfl rfl\nend RiemannGaussian.SemiprimeD1StackCachePhasePrimitives\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationResults":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLoop\n/-! # Exact all-vertex activation log and generated-key invariants -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationResults\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryActivationView\nopen SemiprimeD1StackChildGroupFactoryActivationLoop\n/-- Exactly one actual Boolean log cell per real vertex, in reverse accumulation order. -/\ntheorem finish_history (i:Inputs) (coordinate:Nat) (rows:List Row) (key hist map:List Bool):\n    (finish i coordinate key hist map rows).history=\n      (rows.map (fun row=>active i coordinate row.colours)).reverse++hist:=by\n  induction rows generalizing key hist map with\n  | nil=>rfl\n  | cons row rows ih=>\n    simpa only [finish,List.map_cons,List.reverse_cons,List.append_assoc,List.singleton_append]\n      using ih (advance key) (active i coordinate row.colours::hist)\n        (true::SemiprimeSourceHistogramKeyBits.frame key\n          (SemiprimeSourceHistogramKeyBits.frame [active i coordinate row.colours] map))\n/-- Every original numeric vertex key is generated once, even when there are no occurrences. -/\ntheorem finish_key_value (i:Inputs) (coordinate:Nat) (rows:List Row) (key hist map:List Bool):\n    SemiprimeBitArithmetic.bitValue (finish i coordinate key hist map rows).key=\n      SemiprimeBitArithmetic.bitValue key+rows.length:=by\n  induction rows generalizing key hist map with\n  | nil=>simp only [finish,List.length_nil,Nat.add_zero]\n  | cons row rows ih=>\n    have h:=ih (advance key) (active i coordinate row.colours::hist)\n      (true::SemiprimeSourceHistogramKeyBits.frame key\n        (SemiprimeSourceHistogramKeyBits.frame [active i coordinate row.colours] map))\n    simpa only [finish,advance_value,List.length_cons,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using h\n/-- Only generated bounded metadata grows; neither original numeric N nor a coefficient becomes unary. -/\ntheorem finish_key_length (i:Inputs) (coordinate:Nat) (rows:List Row) (key hist map:List Bool):\n    (finish i coordinate key hist map rows).key.length≤key.length+2*rows.length:=by\n  induction rows generalizing key hist map with\n  | nil=>simp only [finish,List.length_nil,Nat.mul_zero,Nat.add_zero,le_refl]\n  | cons row rows ih=>\n    have h:=ih (advance key) (active i coordinate row.colours::hist)\n      (true::SemiprimeSourceHistogramKeyBits.frame key\n        (SemiprimeSourceHistogramKeyBits.frame [active i coordinate row.colours] map))\n    have hk:=advance_length key\n    change (finish i coordinate (advance key) (active i coordinate row.colours::hist)\n      (true::SemiprimeSourceHistogramKeyBits.frame key\n        (SemiprimeSourceHistogramKeyBits.frame [active i coordinate row.colours] map)) rows).key.length≤_\n    simp only [List.length_cons]\n    omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationResults\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketConvert":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryCalls\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketRecord\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketReuse\n/-! # Real ordinal conversion, whole-bucket logging and complete reuse\nOnly the actually generated binary port vector is copied to the real twelve-role\nconverter. Its value-sensitive trace and every callee cleanup byte are paid.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketConvert\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryCalls SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace Ordinal\nexport SemiprimeD1StackPortOrdinalStream (initial result)\nexport SemiprimeD1StackPortOrdinalStreamExecution (done timeBound)\nend Ordinal\nnamespace Record\nexport SemiprimeD1StackChildGroupFactoryBucketRecord (row timeBound source_trace)\nend Record\nnamespace Reuse\nexport SemiprimeD1StackChildGroupFactoryBucketReuse (result timeBound source_trace)\nend Reuse\n/-- Actual converter operand is the paid copy of the actual fresh-ID bank. -/\ndef copied (before:Stack→List Bool) (words:List (List Bool)):Stack→List Bool:=\n  Function.update before (ordinal .bank) (vectorBits words)\n/-- Complete retained115-word bank after the actual ordinal source. -/\ndef converted (before:Stack→List Bool) (words:List (List Bool)):Stack→List Bool:=\n  withOrdinal (copied before words) (Ordinal.done words).data\n/-- Actual entire bucket log in the real factor history, including empty buckets. -/\ndef logged (before:Stack→List Bool) (packet children:List Bool) (words:List (List Bool)):Stack→List Bool:=\n  Function.update (converted before words) (aux .factorHistory)\n    ((Record.row packet children (Ordinal.result words)).reverse++converted before words (aux .factorHistory))\n/-- Complete physical reuse boundary before the next observed packet. -/\ndef result (before:Stack→List Bool) (packet children:List Bool) (words:List (List Bool)):Stack→List Bool:=\n  Reuse.result (logged before packet children words)\n/-- Same actual converter clock, preserving copy, bucket logger and fifteen physical drains. -/\ndef timeBound (before:Stack→List Bool) (packet children:List Bool) (words:List (List Bool)):Nat:=\n  (5*(vectorBits words).length+4)+(Ordinal.timeBound words+1)+\n    Record.timeBound packet children (Ordinal.result words)+Reuse.timeBound (logged before packet children words)\n/-- No supplied unary answer: the real ordinal converter consumes the generated binary vector. -/\ntheorem source_trace (before:Stack→List Bool) (packet children:List Bool) (words:List (List Bool))\n    (hp:before (aux .packetKey)=packet) (hj:before (aux .jointKey)=children)\n    (hw:before (aux .portBank)=vectorBits words) (hz:∀k,before (ordinal k)=[])\n    (hr:before (aux .rowBuffer)=[]) (hb:before (aux .frameBuffer)=[]) (hc:before (aux .copyScratch)=[]):\n    ∃t≤timeBound before packet children words,\n      Runs program t (.local 8 8) before (.local 6 18) (result before packet children words):=by\n  have h0:=copy_call 25 (.local 8 8) (.local 8 9) rfl before (vectorBits words) []\n    hw (hz .bank) hc\n  simp only [List.append_nil] at h0\n  change Runs program _ _ before _ (copied before words) at h0\n  have hf:∀k,copied before words (ordinal k)=(Ordinal.initial (vectorBits words)).data k:=by\n    intro k\n    cases k <;> simp [copied,ordinal,Ordinal.initial]\n    all_goals exact hz _\n  obtain ⟨t,ht,h1⟩:=ordinal_call (.local 8 9) (.local 8 10) rfl (copied before words) words hf\n  change Runs program t _ _ _ (converted before words) at h1\n  have hp':converted before words (aux .packetKey)=packet:=by\n    simpa [converted,copied,withOrdinal,ordinal,aux] using hp\n  have hj':converted before words (aux .jointKey)=children:=by\n    simpa [converted,copied,withOrdinal,ordinal,aux] using hj\n  have hr':converted before words (aux .rowBuffer)=[]:=by\n    simpa [converted,copied,withOrdinal,ordinal,aux] using hr\n  have hb':converted before words (aux .frameBuffer)=[]:=by\n    simpa [converted,copied,withOrdinal,ordinal,aux] using hb\n  have hc':converted before words (aux .copyScratch)=[]:=by\n    simpa [converted,copied,withOrdinal,ordinal,aux] using hc\n  have h2:=Record.source_trace (converted before words) packet children (Ordinal.result words) hp' hj' rfl hr' hb' hc'\n  change Runs program _ _ _ _ (logged before packet children words) at h2\n  have h3:=Reuse.source_trace (logged before packet children words)\n  refine ⟨(5*(vectorBits words).length+4)+t+Record.timeBound packet children (Ordinal.result words)+\n      Reuse.timeBound (logged before packet children words),?_,?_⟩\n  · dsimp only [timeBound]\n    omega\n  · have hwhole:=join h0 (join h1 (join h2 h3))\n    simpa only [result,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketConvert\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketHeader":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryFields\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketRecord\n/-! # Actual nested-bucket header scan at both literal port/order source sites\nAll three actual header fields are physically parsed. The packet and actual\nunary right-port tape are physically drained before scanning child endpoints.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketHeader\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryFields SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackChildGroupFactoryBucketRecord (payload)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Two literal location families, with no runtime classification or mode input. -/\ndef pc (search:Bool) (slot:Fin 14):Label:=if search then match slot.val with\n  | 0=>(.local 11 28)\n  | 1=>(.local 11 29)\n  | 2=>(.local 11 30)\n  | 3=>(.local 11 31)\n  | 4=>(.local 12 0)\n  | 5=>(.local 12 1)\n  | 6=>(.local 12 2)\n  | 7=>(.local 12 3)\n  | 8=>(.local 12 4)\n  | 9=>(.local 12 5)\n  | 10=>(.local 12 6)\n  | 11=>(.local 12 7)\n  | 12=>(.local 12 8)\n  | 13=>(.local 12 9)\n  | _=>(.local 12 9)\nelse match slot.val with\n  | 0=>(.local 9 7)\n  | 1=>(.local 9 8)\n  | 2=>(.local 9 9)\n  | 3=>(.local 9 10)\n  | 4=>(.local 9 11)\n  | 5=>(.local 9 12)\n  | 6=>(.local 9 13)\n  | 7=>(.local 9 14)\n  | 8=>(.local 9 15)\n  | 9=>(.local 9 16)\n  | 10=>(.local 9 17)\n  | 11=>(.local 9 18)\n  | 12=>(.local 9 19)\n  | 13=>(.local 9 20)\n  | _=>(.local 9 20)\n/-- All actual header outputs and both actual Field private roles are physically empty. -/\ndef cleanRoles:List Stack:=[aux .childReader,aux .packetKey,aux .endpointReader,aux .paddingKey,\n  field (.inl .scratch),field (.inr ())]\n/-- Exact retained outer suffix and acquired actual nested endpoint vector. -/\ndef result (before:Stack→List Bool) (children tail:List Bool):Stack→List Bool:=\n  Function.update (Function.update before (aux .outerReader) tail) (aux .endpointReader) children\n/-- Four actual Field calls with validity pops, tag/EOF, and both real header drains. -/\ndef timeBound (packet children ports:List Bool):Nat:=\n  8*((payload packet children ports).length+packet.length+children.length+ports.length)+packet.length+ports.length+36\n/-- Exact actual header acquisition and paid disposal at either real caller site. -/\ntheorem source_trace (search:Bool) (before:Stack→List Bool) (packet children ports tail:List Bool)\n    (hi:before (aux .outerReader)=true::frame (payload packet children ports) tail)\n    (hz:∀k∈cleanRoles,before k=[]):\n    Runs program (timeBound packet children ports) (pc search 0) before (pc search 13) (result before children tail):=by\n  have hz0:before (aux .childReader)=[]:=hz _ (by simp [cleanRoles])\n  have hz1:before (aux .packetKey)=[]:=hz _ (by simp [cleanRoles])\n  have hz2:before (aux .endpointReader)=[]:=hz _ (by simp [cleanRoles])\n  have hz3:before (aux .paddingKey)=[]:=hz _ (by simp [cleanRoles])\n  have hz4:before (field (.inl .scratch))=[]:=hz _ (by simp [cleanRoles])\n  have hz5:before (field (.inr ()))=[]:=hz _ (by simp [cleanRoles])\n  simp only [aux,field,payload] at hi hz0 hz1 hz2 hz3 hz4 hz5\n  let b0:=before\n  let b1:Stack→List Bool:=Function.update b0 (aux .outerReader) (frame (payload packet children ports) tail)\n  have h0a:=pop_run (pc search 0) abort (pc search 1) (pc search 2) (aux .outerReader) b0\n      (true::frame (payload packet children ports) tail) (by cases search <;> rfl) (by simp [b0,aux,payload,hi])\n  have h0:Runs program 1 (pc search 0) b0 (pc search 2) b1:=by\n    simpa only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] using h0a\n  let b2:Stack→List Bool:=Function.update (Function.update b1 (aux .outerReader) tail) (aux .childReader) (payload packet children ports)\n  have h1:Runs program (8*((payload packet children ports)).length+8) (pc search 2) b1 (pc search 4) b2:=\n    field_read 17 (pc search 2) (pc search 3) (pc search 4) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b1 (payload packet children ports) tail (by simp [b0,b1,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,aux,fieldStack,fieldPorts,payload,hz0]) (by simp [b0,b1,aux,field,payload,hz4]) (by simp [b0,b1,aux,field,payload,hz5])\n  let b3:Stack→List Bool:=Function.update (Function.update b2 (aux .childReader) (frame children (frame ports []))) (aux .packetKey) packet\n  have h2:Runs program (8*(packet).length+8) (pc search 4) b2 (pc search 6) b3:=\n    field_read 6 (pc search 4) (pc search 5) (pc search 6) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b2 packet (frame children (frame ports [])) (by simp [b0,b1,b2,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,aux,fieldStack,fieldPorts,payload,hz1]) (by simp [b0,b1,b2,aux,field,payload,hz4]) (by simp [b0,b1,b2,aux,field,payload,hz5])\n  let b4:Stack→List Bool:=Function.update (Function.update b3 (aux .childReader) (frame ports [])) (aux .endpointReader) children\n  have h3:Runs program (8*(children).length+8) (pc search 6) b3 (pc search 8) b4:=\n    field_read 18 (pc search 6) (pc search 7) (pc search 8) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b3 children (frame ports []) (by simp [b0,b1,b2,b3,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,b3,aux,fieldStack,fieldPorts,payload,hz2]) (by simp [b0,b1,b2,b3,aux,field,payload,hz4]) (by simp [b0,b1,b2,b3,aux,field,payload,hz5])\n  let b5:Stack→List Bool:=Function.update (Function.update b4 (aux .childReader) []) (aux .paddingKey) ports\n  have h4:Runs program (8*(ports).length+8) (pc search 8) b4 (pc search 10) b5:=\n    field_read 5 (pc search 8) (pc search 9) (pc search 10) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b4 ports [] (by simp [b0,b1,b2,b3,b4,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,b3,b4,aux,fieldStack,fieldPorts,payload,hz3]) (by simp [b0,b1,b2,b3,b4,aux,field,payload,hz4]) (by simp [b0,b1,b2,b3,b4,aux,field,payload,hz5])\n  have h5a:=peek_run (pc search 10) (pc search 11) abort abort (aux .childReader) b5 []\n      (by cases search <;> rfl) (by simp [b0,b1,b2,b3,b4,b5,aux,payload])\n  have h5:Runs program 1 (pc search 10) b5 (pc search 11) b5:=by\n    simpa only [List.head?_nil,SemiprimeD1StackBytecode.choose] using h5a\n  let b6:Stack→List Bool:=Function.update b5 (aux .packetKey) []\n  have h6:Runs program (packet.length+1) (pc search 11) b5 (pc search 12) b6:=\n    drain_loop (pc search 11) (pc search 12) (aux .packetKey) (by cases search <;> rfl) b5 packet (by simp [b0,b1,b2,b3,b4,b5,aux,payload])\n  let b7:Stack→List Bool:=Function.update b6 (aux .paddingKey) []\n  have h7:Runs program (ports.length+1) (pc search 12) b6 (pc search 13) b7:=\n    drain_loop (pc search 12) (pc search 13) (aux .paddingKey) (by cases search <;> rfl) b6 ports (by simp [b0,b1,b2,b3,b4,b5,b6,aux,payload])\n  have hout:b7=result before children tail:=by\n    funext k\n    rcases k with k|k|k|k|k|k\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,payload,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,payload,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,payload,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,payload,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,payload,result]\n    · cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,payload,hz0,hz1,hz3,result]\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 (join h6 (h7)))))))\n  rw [hout] at hwhole\n  have ht:(1)+((8*((payload packet children ports)).length+8))+((8*(packet).length+8))+((8*(children).length+8))+((8*(ports).length+8))+(1)+((packet.length+1))+((ports.length+1))=timeBound packet children ports:=by dsimp only [timeBound];omega\n  simpa only [←ht,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketHeader\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryColour":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryFields\n/-! # Actual unary-coordinate scan of acquired colour-vector bytes\nThis fragment consumes an actual unary colour coordinate and real framed row.\nEOF yields the empty binary zero word. The NEW jet axis is never read here.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryColour\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryFields SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Only the three words actually touched by the colour reader. -/\ndef view (before:Stack→List Bool) (cursor reader word:List Bool):Stack→List Bool:=\n  Function.update (Function.update (Function.update before (aux .colourCursor) cursor)\n    (aux .colourReader) reader) (aux .colourWord) word\n/-- Exact acquired word and unread row suffix, for proof statements only. -/\ndef result : Nat→List (List Bool)→List Bool×List Bool\n  | _,[]=>([],[])\n  | 0,w::ws=>(w,vectorBits ws)\n  | n+1,_::ws=>result n ws\n/-- Own elapsed physical clock, including EOF and all failed-coordinate erasure. -/\ndef time : Nat→List (List Bool)→Nat\n  | 0,[]=>4\n  | n+1,[]=>n+4\n  | 0,w::_=>8*w.length+10\n  | n+1,w::ws=>9*w.length+11+time n ws\n/-- Reader writes keep the abstract surrounding115-word bank untouched. -/\ntheorem view_write_cursor (b:Stack→List Bool) (c r w v:List Bool):\n    Function.update (view b c r w) (aux .colourCursor) v=view b v r w:=by\n  funext k\n  by_cases h0:k=aux .colourWord\n  · subst k;simp [view,aux]\n  by_cases h1:k=aux .colourReader\n  · subst k;simp [view,aux]\n  by_cases h2:k=aux .colourCursor\n  · subst k;simp [view,aux]\n  simp [view,h0,h1,h2]\ntheorem view_write_reader (b:Stack→List Bool) (c r w v:List Bool):\n    Function.update (view b c r w) (aux .colourReader) v=view b c v w:=by\n  funext k\n  by_cases h0:k=aux .colourWord\n  · subst k;simp [view,aux]\n  by_cases h1:k=aux .colourReader\n  · subst k;simp [view,aux]\n  simp [view,h0,h1]\ntheorem view_write_word (b:Stack→List Bool) (c r w v:List Bool):\n    Function.update (view b c r w) (aux .colourWord) v=view b c r v:=by\n  exact Function.update_idem _ _ _\n/-- Actual parser call and actual TRUE-pop, before either skipping or selecting. -/\ntheorem parsed (take:Bool) (before:Stack→List Bool) (cursor word:List Bool)\n    (rows:List (List Bool))\n    (hs:before (field (.inl .scratch))=[]) (hv:before (field (.inr ()))=[]):\n    Runs program (8*word.length+8) (if take then .local 1 2 else .local 0 30)\n      (view before cursor (frame word (vectorBits rows)) [])\n      (if take then .local 1 6 else .local 1 0)\n      (view before cursor (vectorBits rows) word):=by\n  have h:=field_read 0 (if take then .local 1 2 else .local 0 30)\n    (if take then .local 1 3 else .local 0 31)\n    (if take then .local 1 6 else .local 1 0) abort abort\n    (by cases take <;> rfl) (by cases take <;> rfl)\n    (view before cursor (frame word (vectorBits rows)) []) word (vectorBits rows)\n    (by simp [fieldStack,fieldPorts,view,aux])\n    (by simp [fieldStack,fieldPorts,view,aux])\n    (by simpa [view,field,aux] using hs)\n    (by simpa [view,field,aux] using hv)\n  change Runs program _ _ _ _\n    (Function.update (Function.update (view before cursor (frame word (vectorBits rows)) [])\n      (aux .colourReader) (vectorBits rows)) (aux .colourWord) word) at h\n  rw [view_write_reader,view_write_word] at h\n  exact h\n/-- Once EOF is real, all remaining unary metadata and reader bytes are physically drained. -/\ntheorem default (before:Stack→List Bool) (cursor reader:List Bool):\n    Runs program (cursor.length+reader.length+2) (.local 1 4) (view before cursor reader [])\n      (.local 1 6) (view before [] [] []):=by\n  have h0:=drain_loop (.local 1 4) (.local 1 5) (aux .colourCursor) rfl\n    (view before cursor reader []) cursor (by simp [view,aux])\n  rw [view_write_cursor] at h0\n  have h1:=drain_loop (.local 1 5) (.local 1 6) (aux .colourReader) rfl\n    (view before [] reader []) reader (by simp [view,aux])\n  rw [view_write_reader] at h1\n  have h:=join h0 h1\n  simpa only [Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using h\n/-- Complete real colour-coordinate loop: no host row getter or decoded colour is an instruction. -/\ntheorem source_trace (before:Stack→List Bool) (n:Nat) (rows:List (List Bool))\n    (hs:before (field (.inl .scratch))=[]) (hv:before (field (.inr ()))=[]):\n    Runs program (time n rows) (.local 0 28) (view before (List.replicate n true) (vectorBits rows) [])\n      (.local 1 6) (view before [] (result n rows).2 (result n rows).1):=by\n  induction n generalizing rows with\n  | zero=>\n    have h0:=pop_run (.local 0 28) (.local 1 1) (.local 0 29) (.local 0 29)\n      (aux .colourCursor) (view before [] (vectorBits rows) []) [] rfl\n      (by simp [view,aux])\n    simp only [List.head?_nil,List.tail_nil,SemiprimeD1StackBytecode.choose] at h0\n    rw [view_write_cursor] at h0\n    cases rows with\n    | nil=>\n      have h1:=pop_run (.local 1 1) (.local 1 4) (.local 1 4) (.local 1 2)\n        (aux .colourReader) (view before [] [false] []) [false] rfl\n        (by simp [view,aux])\n      simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h1\n      rw [view_write_reader] at h1\n      exact join h0 (join h1 (default before [] []))\n    | cons w ws=>\n      have h1:=pop_run (.local 1 1) (.local 1 4) (.local 1 4) (.local 1 2)\n        (aux .colourReader) (view before [] (vectorBits (w::ws)) []) (vectorBits (w::ws)) rfl\n        (by simp [view,aux])\n      simp only [vectorBits,List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h1\n      rw [view_write_reader] at h1\n      have h:=join h0 (join h1 (parsed true before [] w ws hs hv))\n      have ht:1+(1+(8*w.length+8))=8*w.length+10:=by omega\n      rw [ht] at h\n      simpa [time,result] using h\n  | succ n ih=>\n    have h0:=pop_run (.local 0 28) (.local 1 1) (.local 0 29) (.local 0 29)\n      (aux .colourCursor) (view before (true::List.replicate n true) (vectorBits rows) [])\n      (true::List.replicate n true) rfl (by simp [view,aux])\n    simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n    rw [view_write_cursor] at h0\n    cases rows with\n    | nil=>\n      have h1:=pop_run (.local 0 29) (.local 1 4) (.local 1 4) (.local 0 30)\n        (aux .colourReader) (view before (List.replicate n true) [false] []) [false] rfl\n        (by simp [view,aux])\n      simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h1\n      rw [view_write_reader] at h1\n      have h:=join h0 (join h1 (default before (List.replicate n true) []))\n      simpa only [time,result,List.length_replicate,List.length_nil,Nat.add_zero,\n        Nat.add_assoc,Nat.add_comm,Nat.add_left_comm,List.replicate_succ] using h\n    | cons w ws=>\n      have h1:=pop_run (.local 0 29) (.local 1 4) (.local 1 4) (.local 0 30)\n        (aux .colourReader) (view before (List.replicate n true) (vectorBits (w::ws)) [])\n        (vectorBits (w::ws)) rfl (by simp [view,aux])\n      simp only [vectorBits,List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h1\n      rw [view_write_reader] at h1\n      have h2:=parsed false before (List.replicate n true) w ws hs hv\n      have h3:=drain_loop (.local 1 0) (.local 0 28) (aux .colourWord) rfl\n        (view before (List.replicate n true) (vectorBits ws) w) w\n        (by simp [view,aux])\n      rw [view_write_word] at h3\n      have h:=join h0 (join h1 (join h2 (join h3 (ih ws))))\n      have ht:1+(1+((8*w.length+8)+((w.length+1)+time n ws)))=9*w.length+11+time n ws:=by omega\n      rw [ht] at h\n      simpa only [time,result,List.replicate_succ,Bool.false_eq_true,ite_false] using h\n/-- Semantic interpretation of the computed field, including every out-of-range default. -/\ntheorem result_word (n:Nat) (rows:List (List Bool)):(result n rows).1=rows.getD n []:=by\n  induction n generalizing rows with\n  | zero=>cases rows <;> simp [result]\n  | succ n ih=>cases rows <;> simp [result,ih]\n/-- The actual scan is linear in the physically supplied unary coordinate and row bytes. -/\ntheorem time_le (n:Nat) (rows:List (List Bool)):\n    time n rows≤12*(n+(vectorBits rows).length+1):=by\n  induction n generalizing rows with\n  | zero=>\n    cases rows with\n    | nil=>simp [time,vectorBits]\n    | cons w ws=>\n      simp only [time,vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\n  | succ n ih=>\n    cases rows with\n    | nil=>simp only [time,vectorBits,List.length_cons,List.length_nil];omega\n    | cons w ws=>\n      have h:=ih ws\n      simp only [time,vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length] at h ⊢\n      omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryColour\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointCleanup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointParse\n/-! # Complete paid per-incidence raw-field erasure\nEvery parsed field is physically drained through its actual EOF instruction.\nThe seven finite positions are already literal source labels, not input counts.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointCleanup\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryEndpointParse (Fields)\nopen SemiprimeD1StackProcedureTrace\n/-- The exact seven actual raw-field roles. -/\ndef role:Fin 7→Stack\n  | 0=>aux .ownerKey\n  | 1=>aux .factorKey\n  | 2=>aux .sourceKey\n  | 3=>aux .paddingKey\n  | 4=>aux .packetKey\n  | 5=>aux .slotWord\n  | 6=>aux .edgeWord\n/-- Exact words acquired by the real preceding parser. -/\ndef word (f:Fields):Fin 7→List Bool\n  | 0=>f.owner\n  | 1=>f.factor\n  | 2=>f.source\n  | 3=>f.padding\n  | 4=>f.packet\n  | 5=>f.slot\n  | 6=>f.edge\n/-- The actual fixed cleanup positions and their loop continuation. -/\ndef pc:Fin 8→Label\n  | 0=>(.local 6 6)\n  | 1=>(.local 6 7)\n  | 2=>(.local 6 8)\n  | 3=>(.local 6 9)\n  | 4=>(.local 6 10)\n  | 5=>(.local 6 11)\n  | 6=>(.local 6 12)\n  | 7=>(.local 2 20)\n/-- Complete physical effect; every other115-role word is retained. -/\ndef result (before:Stack→List Bool):Stack→List Bool:=\n  Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (before) (aux .ownerKey) []) (aux .factorKey) []) (aux .sourceKey) []) (aux .paddingKey) []) (aux .packetKey) []) (aux .slotWord) []) (aux .edgeWord) []\n/-- Own sum of all actual payload pops and all seven actual EOF pops. -/\ndef timeBound (f:Fields):Nat:=f.owner.length+f.factor.length+f.source.length+f.padding.length+\n  f.packet.length+f.slot.length+f.edge.length+7\n/-- Whole real per-incidence cleanup, with no implicit discarded raw fields. -/\ntheorem source_trace (before:Stack→List Bool) (f:Fields)\n    (hread:∀i,before (role i)=word f i):\n    Runs program (timeBound f) (pc 0) before (pc 7) (result before):=by\n  have hx0:before (aux .ownerKey)=f.owner:=hread 0\n  have hx1:before (aux .factorKey)=f.factor:=hread 1\n  have hx2:before (aux .sourceKey)=f.source:=hread 2\n  have hx3:before (aux .paddingKey)=f.padding:=hread 3\n  have hx4:before (aux .packetKey)=f.packet:=hread 4\n  have hx5:before (aux .slotWord)=f.slot:=hread 5\n  have hx6:before (aux .edgeWord)=f.edge:=hread 6\n  simp only [aux] at hx0 hx1 hx2 hx3 hx4 hx5 hx6\n  let b0:=before\n  let b1:Stack→List Bool:=Function.update b0 (aux .ownerKey) []\n  have h0:Runs program (f.owner.length+1) (pc 0) b0 (pc 1) b1:=\n    drain_loop (pc 0) (pc 1) (aux .ownerKey) rfl b0 f.owner (by simp [b0,aux,hx0])\n  let b2:Stack→List Bool:=Function.update b1 (aux .factorKey) []\n  have h1:Runs program (f.factor.length+1) (pc 1) b1 (pc 2) b2:=\n    drain_loop (pc 1) (pc 2) (aux .factorKey) rfl b1 f.factor (by simp [b0,b1,aux,hx1])\n  let b3:Stack→List Bool:=Function.update b2 (aux .sourceKey) []\n  have h2:Runs program (f.source.length+1) (pc 2) b2 (pc 3) b3:=\n    drain_loop (pc 2) (pc 3) (aux .sourceKey) rfl b2 f.source (by simp [b0,b1,b2,aux,hx2])\n  let b4:Stack→List Bool:=Function.update b3 (aux .paddingKey) []\n  have h3:Runs program (f.padding.length+1) (pc 3) b3 (pc 4) b4:=\n    drain_loop (pc 3) (pc 4) (aux .paddingKey) rfl b3 f.padding (by simp [b0,b1,b2,b3,aux,hx3])\n  let b5:Stack→List Bool:=Function.update b4 (aux .packetKey) []\n  have h4:Runs program (f.packet.length+1) (pc 4) b4 (pc 5) b5:=\n    drain_loop (pc 4) (pc 5) (aux .packetKey) rfl b4 f.packet (by simp [b0,b1,b2,b3,b4,aux,hx4])\n  let b6:Stack→List Bool:=Function.update b5 (aux .slotWord) []\n  have h5:Runs program (f.slot.length+1) (pc 5) b5 (pc 6) b6:=\n    drain_loop (pc 5) (pc 6) (aux .slotWord) rfl b5 f.slot (by simp [b0,b1,b2,b3,b4,b5,aux,hx5])\n  let b7:Stack→List Bool:=Function.update b6 (aux .edgeWord) []\n  have h6:Runs program (f.edge.length+1) (pc 6) b6 (pc 7) b7:=\n    drain_loop (pc 6) (pc 7) (aux .edgeWord) rfl b6 f.edge (by simp [b0,b1,b2,b3,b4,b5,b6,aux,hx6])\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 (h6))))))\n  have ht:((f.owner.length+1))+((f.factor.length+1))+((f.source.length+1))+((f.padding.length+1))+((f.packet.length+1))+((f.slot.length+1))+((f.edge.length+1))=timeBound f:=by dsimp only [timeBound];omega\n  simpa only [←ht,Nat.add_assoc,result,b0,b1,b2,b3,b4,b5,b6,b7] using hwhole\n/-- Every one of the seven actual fields is empty at the next real row boundary. -/\ntheorem result_role (before:Stack→List Bool) (i:Fin 7):result before (role i)=[]:=by\n  fin_cases i <;> rfl\n/-- The actual cleanup retains every physical role outside its fixed seven-word image. -/\ntheorem result_other (before:Stack→List Bool) (k:Stack) (h:∀i,role i≠k):result before k=before k:=by\n  have h0:=Ne.symm (h 0)\n  have h1:=Ne.symm (h 1)\n  have h2:=Ne.symm (h 2)\n  have h3:=Ne.symm (h 3)\n  have h4:=Ne.symm (h 4)\n  have h5:=Ne.symm (h 5)\n  have h6:=Ne.symm (h 6)\n  simp only [role] at h0 h1 h2 h3 h4 h5 h6\n  simp only [result,Function.update_of_ne h6,Function.update_of_ne h5,\n    Function.update_of_ne h4,Function.update_of_ne h3,Function.update_of_ne h2,\n    Function.update_of_ne h1,Function.update_of_ne h0]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointCleanup\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryPrimitives\n/-! # Actual framed-field source calls at all21 fixed factory sites -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryFields\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryWiringFacts\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Each real Field call preserves every other115-role word and pays its own physical call/return. -/\ntheorem field_call (site:Fin 21) (pc next:Label)\n    (hc:program pc=.call (.field site (F.active .tagPop (none,false))) next) (before:Stack→List Bool) (word tail:List Bool)\n    (hi:before (fieldStack site (.inl .input))=frame word tail)\n    (ho:before (fieldStack site (.inl .output))=[]) (hs:before (field (.inl .scratch))=[]) (hv:before (field (.inr ()))=[]):\n    Runs program (8*word.length+7) pc before next\n      (Function.update (Function.update (Function.update before (fieldStack site (.inl .input)) tail)\n        (fieldStack site (.inl .output)) word) (field (.inr ())) [true]):=by\n  let start:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let stop:SemiprimeD1StackBytecode.State F.Stack F.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel (fieldStack site) before start.store before:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k with\n        | input=>exact hi\n        | scratch=>exact hs\n        | output=>exact ho\n      · cases k;exact hv\n    · intro k _;rfl\n  have h0:=Link.data_update (fieldStack site) (field_injective site) before start.store before hin (.inl .input) tail\n  have h1:=Link.data_update (fieldStack site) (field_injective site) before _ _ h0 (.inl .output) word\n  have h2:=Link.data_update (fieldStack site) (field_injective site) before _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update start.store (.inl .input) tail) (.inl .output) word) (.inr ()) [true]=stop.store:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  exact included_call program (fieldStack site) (Label.field site) (field_injective site) F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) pc next\n    hc (8*word.length+6) start stop _ _ rfl rfl\n    (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin h2\n/-- The caller physically consumes the real parser flag before using the field. -/\ntheorem field_read (site:Fin 21) (pc parsed next empty low:Label)\n    (hc:program pc=.call (.field site (F.active .tagPop (none,false))) parsed)\n    (hp:program parsed=.base (.pop (field (.inr ())) empty low next))\n    (before:Stack→List Bool) (word tail:List Bool)\n    (hi:before (fieldStack site (.inl .input))=frame word tail)\n    (ho:before (fieldStack site (.inl .output))=[])\n    (hs:before (field (.inl .scratch))=[]) (hv:before (field (.inr ()))=[]):\n    Runs program (8*word.length+8) pc before next\n      (Function.update (Function.update before (fieldStack site (.inl .input)) tail)\n        (fieldStack site (.inl .output)) word):=by\n  have h0:=field_call site pc parsed hc before word tail hi ho hs hv\n  let v:=Function.update (Function.update (Function.update before (fieldStack site (.inl .input)) tail)\n    (fieldStack site (.inl .output)) word) (field (.inr ())) [true]\n  have h1:=pop_run parsed empty low next (field (.inr ())) v [true] hp (Function.update_self _ _ _)\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h1\n  have he:Function.update v (field (.inr ())) []=\n      Function.update (Function.update before (fieldStack site (.inl .input)) tail)\n        (fieldStack site (.inl .output)) word:=by\n    dsimp [v]\n    have hoNe:fieldStack site (.inl .output)≠field (.inr ()) := (field_disjoint site).2.2.2.2\n    have hiNe:fieldStack site (.inl .input)≠field (.inr ()) := (field_disjoint site).2.2.2.1\n    rw [Function.update_idem,Function.update_comm hoNe,Function.update_comm hiNe]\n    have hz:Function.update before (field (.inr ())) []=before:=by\n      rw [←hv];exact Function.update_eq_self _ _\n    rw [hz]\n  rw [he] at h1\n  have h:=join h0 h1\n  simpa only [Nat.add_assoc] using h\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryFields\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationCapacities\n/-! # Whole actual activation/forward-endpoint prefix has one fixed quartic clock\nAll classification and map bytes come from the physical acquired ID dictionary;\nsource fields/counts are charged to the same thirteen actual input words.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBounds\nopen SemiprimeD1StackChildGroupFactory\nnamespace F\nexport SemiprimeD1StackChildGroupFactoryForwardSource (activation rows timeBound)\nend F\nnamespace Raw\nexport SemiprimeD1StackChildGroupFactoryAcquisitionByteBounds (fieldBytes field_le_tapes fields_count)\nend Raw\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryEndpointParse (Fields)\nend P\nnamespace Size\nexport SemiprimeD1StackChildGroupFactoryTraceBounds (inputBytes)\nexport SemiprimeD1StackChildGroupFactoryActivationCapacities (capacity inputSize source_timeBound_le)\nend Size\nnamespace K\nexport SemiprimeD1StackChildGroupFactoryEndpointKeys (pairs placements row pairs_rows placements_rows rows_valid)\nend K\n/-- A fixed paid common count/byte allowance, never a runtime operand. -/\ndef capacity (i:Inputs):Nat:=8*(Size.inputBytes i+1)\n/-- Entire same-program prefix clock is quartic in the actual thirteen physical input bytes. -/\ntheorem timeBound_le (i:Inputs) (a coordinate:Nat) (ids:List (List Bool)) (fields:List P.Fields)\n    (hids:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids)\n    (he:i.environment=SemiprimeD1StackSourceEnvironmentEncoding.dictionary ids)\n    (hc:i.catalogue=SemiprimeD1StackPacketRowsOriginal.catalogue a)\n    (hi:i.colourIndex=List.replicate coordinate true)\n    (hlen:ids.length=i.owners.length+i.factors.length)\n    (hpairs:i.occurrences=K.pairs fields) (hplacements:i.placements=K.placements fields)\n    (hdom:∀f∈fields,SemiprimeBitArithmetic.bitValue f.owner < ids.length ∧\n      SemiprimeBitArithmetic.bitValue f.factor < ids.length):\n    F.timeBound i a coordinate ids fields≤1000000000*(capacity i+1)^4:=by\n  let S:=capacity i\n  have hs:Size.inputBytes i≤S:=by dsimp only [S,capacity];omega\n  have hid:ids.length≤S:=by rw [hlen];dsimp only [S,capacity,Size.inputBytes];omega\n  have hp:(K.pairs fields).length+(K.placements fields).length≤S:=by\n    rw [←hpairs,←hplacements]\n    dsimp only [S,capacity,Size.inputBytes];omega\n  have hfields:∀f∈fields,Raw.fieldBytes f≤S:=fun f hf=>(Raw.field_le_tapes fields f hf).trans hp\n  have hn:fields.length≤S:=(Raw.fields_count fields).trans (by omega)\n  let ar:=F.activation a ids\n  let er:=F.rows i a coordinate ids fields\n  let entries:=SemiprimeD1StackChildGroupFactoryActivationMap.entries i coordinate [] ar\n  have hal:ar.length=ids.length:=by\n    simp only [ar,F.activation,SemiprimeD1StackChildGroupFactoryActivationMeaning.plan_length,List.length_reverse]\n  have hem:i.environment=SemiprimeD1StackOwnerLookup.records (SemiprimeD1StackSourceEnvironmentEncoding.prefixRows ids) []:=he\n  have hcm:i.catalogue=SemiprimeD1StackOwnerLookup.records\n      (SemiprimeD1StackPacketRowsMeaning.originalEntries 64 a) []:=\n    hc.trans (SemiprimeD1StackPacketRowsMeaning.catalogue_original a).symm\n  have hv:=SemiprimeD1StackChildGroupFactoryActivationMeaning.plan_valid_all a ids hids\n  have hat:=Size.source_timeBound_le i coordinate (SemiprimeD1StackSourceEnvironmentEncoding.prefixRows ids)\n    (SemiprimeD1StackPacketRowsMeaning.originalEntries 64 a) ar hem hcm hi\n    (by simpa only [hal] using hlen) hv\n  have hcapacity:Size.capacity i≤S:=by dsimp only [Size.capacity,Size.inputSize,S,capacity,Size.inputBytes];omega\n  have ham:SemiprimeD1StackChildGroupFactoryActivationSource.timeBound i coordinate\n      (SemiprimeD1StackSourceEnvironmentEncoding.prefixRows ids)\n      (SemiprimeD1StackPacketRowsMeaning.originalEntries 64 a) ar≤200000000*S^3:=\n    hat.trans (Nat.mul_le_mul_left _ (Nat.pow_le_pow_left hcapacity 3))\n  have hmap:(SemiprimeD1StackOwnerLookup.records entries []).length≤10*(S+1)^2:=by\n    have h:=SemiprimeD1StackChildGroupFactoryActivationMapBounds.zero_records_length i coordinate ar\n    change (SemiprimeD1StackOwnerLookup.records entries []).length≤_ at h\n    rw [hal] at h\n    exact h.trans (Nat.mul_le_mul_left _ (Nat.pow_le_pow_left (by omega:ids.length+1≤S+1) 2))\n  have her:∀r∈er,Raw.fieldBytes r.fields≤S:=by\n    intro r hr\n    obtain ⟨f,hf,rfl⟩:=List.mem_map.mp hr\n    exact hfields f hf\n  have hvalid:SemiprimeD1StackChildGroupFactoryEndpointLoop.Valid entries er:=by\n    apply K.rows_valid\n    intro f hf\n    simpa only [hal] using hdom f hf\n  have hep:(SemiprimeD1StackChildGroupFactoryEndpointLoop.pairs er).length+\n      (SemiprimeD1StackChildGroupFactoryEndpointLoop.placements er).length≤S:=by\n    simpa only [er,F.rows,K.pairs_rows,K.placements_rows] using hp\n  have hen:er.length≤S:=by simpa only [er,F.rows,List.length_map] using hn\n  have het:=SemiprimeD1StackChildGroupFactoryEndpointBounds.source_time entries er S her hvalid hen hep hmap\n  change SemiprimeD1StackChildGroupFactoryActivationSource.timeBound i coordinate\n      (SemiprimeD1StackSourceEnvironmentEncoding.prefixRows ids)\n      (SemiprimeD1StackPacketRowsMeaning.originalEntries 64 a) ar+\n    SemiprimeD1StackChildGroupFactoryEndpointSource.timeBound entries er≤1000000000*(S+1)^4\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBucketsSource":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardSource\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointSourceView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsSource\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryCatalogueCodecs\n/-! # Actual thirteen-input entry through complete chronological child buckets\nGenerated forward endpoint bytes feed the actual packet scan directly. All\nactivation flags and fresh child IDs are computed by the same literal program;\nno endpoint list or bucket answer is supplied as an additional runtime input.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBucketsSource\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace Forward\nexport SemiprimeD1StackChildGroupFactoryForwardSource (activation rows result timeBound source_trace)\nend Forward\nnamespace A\nexport SemiprimeD1StackChildGroupFactoryActivationSource (result)\nend A\nnamespace EV\nexport SemiprimeD1StackChildGroupFactoryEndpointSourceView (Protected result_other result_clean result_endpoints)\nend EV\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryEndpointParse (Fields)\nend Parse\nnamespace Bucket\nexport SemiprimeD1StackChildGroupFactoryBucketsSource (result timeBound source_trace)\nend Bucket\nnamespace BP\nexport SemiprimeD1StackChildGroupFactoryBucketParse (cleanRoles)\nend BP\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (selected selected_records)\nend Code\n/-- Actual generated endpoint interpretation; never an extra runtime tape. -/\ndef endpoints (i:Inputs) (a coordinate:Nat) (ids:List (List Bool)) (fields:List Parse.Fields):=\n  Code.selected (Forward.rows i a coordinate ids fields)\n/-- Complete physical bank after actual forward endpoint and bucket acquisition. -/\ndef result (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List Parse.Fields):Stack→List Bool:=\n  Bucket.result (Forward.result i a coordinate ids fields) packets (endpoints i a coordinate ids fields) []\n/-- Composed own clock on the actually generated forward endpoint tape. -/\ndef timeBound (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List Parse.Fields):Nat:=\n  Forward.timeBound i a coordinate ids fields+\n    Bucket.timeBound (Forward.result i a coordinate ids fields) packets (endpoints i a coordinate ids fields) []\n/-- All physical words outside the actual endpoint source's fixed work image retain their activation boundary bytes. -/\ntheorem forward_other (i:Inputs) (a coordinate:Nat) (ids:List (List Bool)) (fields:List Parse.Fields)\n    (k:Stack) (hk:EV.Protected k):\n    Forward.result i a coordinate ids fields k=A.result i coordinate (Forward.activation a ids) k:=\n  EV.result_other _ _ k hk\n/-- Every actual bucket parser destination is fresh after forward endpoint acquisition. -/\ntheorem forward_clean (i:Inputs) (a coordinate:Nat) (ids:List (List Bool)) (fields:List Parse.Fields):\n    ∀k∈BP.cleanRoles,Forward.result i a coordinate ids fields k=[]:=by\n  have hraw:=EV.result_clean (A.result i coordinate (Forward.activation a ids)) (Forward.rows i a coordinate ids fields)\n    (by simp [A.result,SemiprimeD1StackChildGroupFactoryActivation.data,input,\n      SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles,aux,field])\n  intro k hk\n  simp only [BP.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n  · exact hraw _ (by simp [SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles])\n  · exact hraw _ (by simp [SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles])\n  · exact hraw _ (by simp [SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles])\n  · exact hraw _ (by simp [SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles])\n  · rw [forward_other _ _ _ _ _ _ (by\n      constructor\n      all_goals first | (intro j;fin_cases j <;> decide) | decide)]\n    rfl\n  · rw [forward_other _ _ _ _ _ _ (by\n      constructor\n      all_goals first | (intro j;fin_cases j <;> decide) | decide)]\n    rfl\n  · exact hraw _ (by simp [SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles])\n  · exact hraw _ (by simp [SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles])\n/-- Whole actual entry through ALL real observed packet buckets, including empty and duplicate keys. -/\ntheorem source_trace (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List Parse.Fields)\n    (hids:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids)\n    (he:i.environment=SemiprimeD1StackSourceEnvironmentEncoding.dictionary ids)\n    (hc:i.catalogue=SemiprimeD1StackPacketRowsOriginal.catalogue a)\n    (hi:i.colourIndex=List.replicate coordinate true)\n    (hlen:ids.length=i.owners.length+i.factors.length)\n    (hpairs:i.occurrences=SemiprimeD1StackChildGroupFactoryEndpointKeys.pairs fields)\n    (hplacements:i.placements=SemiprimeD1StackChildGroupFactoryEndpointKeys.placements fields)\n    (hdom:∀f∈fields,SemiprimeBitArithmetic.bitValue f.owner < ids.length ∧\n      SemiprimeBitArithmetic.bitValue f.factor < ids.length)\n    (hpackets:i.packets=SemiprimeD1TensorTapeCodec.vectorBits packets):\n    ∃t≤timeBound i a coordinate ids packets fields,\n      Runs program t entry (input i) (.local 9 2) (result i a coordinate ids packets fields):=by\n  obtain ⟨x,hx,h0⟩:=Forward.source_trace i a coordinate ids fields hids he hc hi hlen hpairs hplacements hdom\n  have fresh (k:Stack) (hk:EV.Protected k)\n      (hz:A.result i coordinate (Forward.activation a ids) k=[]):Forward.result i a coordinate ids fields k=[]:=\n    (forward_other _ _ _ _ _ _ hk).trans hz\n  have hparse:=forward_clean i a coordinate ids fields\n  have ht:Forward.result i a coordinate ids fields (aux .packets)=SemiprimeD1TensorTapeCodec.vectorBits packets:=by\n    rw [forward_other _ _ _ _ _ _ (by\n      constructor\n      all_goals first | (intro j;fin_cases j <;> decide) | decide)]\n    exact hpackets\n  have hep:Forward.result i a coordinate ids fields (aux .endpoints)=\n      SemiprimeD1StackChildGroupFactoryBucketParse.records (endpoints i a coordinate ids fields):=by\n    rw [show Forward.result i a coordinate ids fields (aux .endpoints)=\n      SemiprimeD1StackChildGroupFactoryEndpointLoopView.selectedRecords (Forward.rows i a coordinate ids fields)++[false] from rfl]\n    exact (Code.selected_records _).symm\n  obtain ⟨y,hy,h1⟩:=Bucket.source_trace (Forward.result i a coordinate ids fields) packets\n    (endpoints i a coordinate ids fields) [] ht\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    hep (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl) hparse\n    (by exact EV.result_clean _ _ (by simp [A.result,SemiprimeD1StackChildGroupFactoryActivation.data,input,\n      SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles,aux,field]) _ (by simp [SemiprimeD1StackChildGroupFactoryEndpointParse.cleanRoles]))\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    (by intro k;apply fresh _ ?_ rfl;constructor;all_goals first | (intro j;fin_cases j <;> cases k <;> decide) | (cases k <;> decide))\n    (by intro k;apply fresh _ ?_ rfl;constructor;all_goals first | (intro j;fin_cases j <;> cases k <;> decide) | (cases k <;> decide))\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n    (fresh _ (by constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) rfl)\n  refine ⟨x+y,?_,join h0 h1⟩\n  dsimp only [timeBound];omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBucketsSource\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoopView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoop\n/-! # Exact actual left-port order and complete nested scan reuse boundary -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoopView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryLeftPortsLoop\nnamespace Log\nexport SemiprimeD1StackChildGroupFactoryWordLog (row)\nend Log\n/-- The actual one-bucket scan prepends exactly its selected global-ID word records. -/\ntheorem step_portHistory (before:Stack→List Bool) (b:Bucket) (tail target:List Bool):\n    step before b tail target (aux .portHistory)=\n      ((Inner.portWords b.children target).flatMap Log.row).reverse++before (aux .portHistory):=by\n  rw [step,Inner.result_portHistory]\n  rfl\n/-- Exact actual filtered port word order across every observed bucket. -/\ntheorem result_portHistory (buckets:List Bucket) (before:Stack→List Bool) (target:List Bool):\n    result buckets before target (aux .portHistory)=\n      ((portWords buckets target).flatMap Log.row).reverse++before (aux .portHistory):=by\n  induction buckets generalizing before with\n  | nil=>simp only [result,atEOF,portWords,List.flatMap_nil,List.reverse_nil,List.nil_append];rfl\n  | cons b bs ih=>\n    rw [result,ih,step_portHistory]\n    simp only [portWords,List.flatMap_append,List.reverse_append,List.append_assoc]\n/-- Every physical cache word outside the actual six child roles, two readers and port log is retained. -/\ntheorem result_other (buckets:List Bucket) (before:Stack→List Bool) (target:List Bool) (k:Stack)\n    (hf:∀j,Cleanup.role j≠k) (he:k≠aux .endpointReader) (ho:k≠aux .outerReader) (hp:k≠aux .portHistory):\n    result buckets before target k=before k:=by\n  induction buckets generalizing before with\n  | nil=>simp only [result,atEOF,Function.update_of_ne ho]\n  | cons b bs ih=>rw [result,ih];exact step_other _ _ _ _ k hf he ho hp\n/-- Actual entire outer reader is empty after its real EOF pair. -/\ntheorem result_outerReader (buckets:List Bucket) (before:Stack→List Bool) (target:List Bool):\n    result buckets before target (aux .outerReader)=[]:=by\n  induction buckets generalizing before with\n  | nil=>rfl\n  | cons b bs ih=>exact ih _\n/-- Actual endpoint reader is empty even when there were no observed packets. -/\ntheorem result_endpointReader (buckets:List Bucket) (before:Stack→List Bool) (target:List Bool)\n    (he:before (aux .endpointReader)=[]):result buckets before target (aux .endpointReader)=[]:=by\n  induction buckets generalizing before with\n  | nil=>simpa [result,atEOF,aux] using he\n  | cons b bs ih=>exact ih _ (step_endpointReader _ _ _ _)\n/-- Whole nested scan preserves actual child-parser freshness. -/\ntheorem result_clean (buckets:List Bucket) (before:Stack→List Bool) (target:List Bool)\n    (hz:∀k∈Parse.cleanRoles,before k=[]):∀k∈Parse.cleanRoles,result buckets before target k=[]:=by\n  induction buckets generalizing before with\n  | nil=>\n    intro k hk\n    have hn:k≠aux .outerReader:=by intro he;subst k;simp [Parse.cleanRoles,aux,field] at hk\n    simpa only [result,atEOF,Function.update_of_ne hn] using hz k hk\n  | cons b bs ih=>exact ih _ (step_clean _ _ _ _ hz)\n/-- Whole nested scan preserves actual header-parser freshness. -/\ntheorem result_headerClean (buckets:List Bucket) (before:Stack→List Bool) (target:List Bool)\n    (hh:∀k∈Header.cleanRoles,before k=[]):∀k∈Header.cleanRoles,result buckets before target k=[]:=by\n  induction buckets generalizing before with\n  | nil=>\n    intro k hk\n    have hn:k≠aux .outerReader:=by intro he;subst k;simp [Header.cleanRoles,aux,field] at hk\n    simpa only [result,atEOF,Function.update_of_ne hn] using hh k hk\n  | cons b bs ih=>exact ih _ (step_headerClean _ _ _ _ hh)\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoopView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeTags":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativePairs\nimport RiemannGaussian.SemiprimeD1ChildAssignmentEndpoint\n/-! # Exact injective raw old-tag codec derived from the original acquired ID bank\nThese erased specifications identify actual edge/side bytes already copied by\nthe source. No tag lookup, inverse, getter or permutation is a runtime operand.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeTags\nnamespace Pair\nexport SemiprimeD1StackChildGroupFactoryNativePairs (paired)\nend Pair\nnamespace Fld\nexport SemiprimeD1StackChildGroupFactoryNativeFields (source)\nend Fld\nnamespace Native\nexport SemiprimeD1ChildPortBijection (original_ports_nodup original_ports_complete)\nexport SemiprimeD1ChildPortPullbackCorrectness (ids_value ids_nodup findPort_member)\nend Native\n/-- Actual unique-key zip lookup, independent of any original graph normalization. -/\ntheorem lookup_zip {A B:Type} [BEq A] [LawfulBEq A] (xs:List A) (ys:List B) (word:B→List Bool)\n    (hn:xs.Nodup) (p:A×B) (hp:p∈xs.zip ys):\n    (ys.map word).getD (xs.idxOf p.1) []=word p.2:=by\n  induction xs generalizing ys with\n  | nil=>simp only [List.zip_nil_left,List.not_mem_nil] at hp\n  | cons x xs ih=>\n    cases ys with\n    | nil=>simp only [List.zip_nil_right,List.not_mem_nil] at hp\n    | cons y ys=>\n      have hnd:=List.nodup_cons.mp hn\n      simp only [List.zip_cons_cons,List.mem_cons] at hp\n      rcases hp with rfl|hp\n      · simp only [List.map_cons,List.idxOf_cons_self,List.getD_cons_zero]\n      · have hne:x≠p.1:=by\n          intro he\n          exact hnd.1 (he ▸ (List.of_mem_zip hp).1)\n        simp only [List.map_cons,List.idxOf_cons_ne _ hne,List.getD_cons_succ]\n        exact ih ys hnd.2 hp\n/-- Every actual original key has a paired physical placement when acquired lengths agree. -/\ntheorem exists_zip_right {A B:Type} (xs:List A) (ys:List B) (hl:xs.length=ys.length)\n    (x:A) (hx:x∈xs):∃y,(x,y)∈xs.zip ys:=by\n  induction xs generalizing ys with\n  | nil=>simp only [List.not_mem_nil] at hx\n  | cons a xs ih=>\n    cases ys with\n    | nil=>simp only [List.length_cons,List.length_nil] at hl;omega\n    | cons b ys=>\n      have ht:xs.length=ys.length:=by simp only [List.length_cons] at hl;omega\n      rcases List.mem_cons.mp hx with rfl|hx\n      · exact ⟨b,List.mem_cons_self⟩\n      · obtain ⟨y,hy⟩:=ih ys ht hx\n        exact ⟨y,List.mem_cons_of_mem _ hy⟩\n/-- The original edge word is read from its SAME acquired original-position placement. Proof notation only. -/\ndef edgeFor (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n)\n    (port:(e:Fin F)×Fin (arity e)):List Bool:=\n  ((Fld.source n F a arity owner).placements.map SemiprimeD1PacketInventory.Placement.edge).getD\n    ((SemiprimeD1CollisionOriginal.ports n F a arity).idxOf port) []\n/-- The raw edge code is precisely the actual acquired byte field at each real typed pair. -/\ntheorem edgeFor_pair (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n)\n    (p:((e:Fin F)×Fin (arity e))×SemiprimeD1PacketInventory.Placement)\n    (hp:p∈Pair.paired n F a arity owner):edgeFor n F a arity owner p.1=p.2.edge:=\n  lookup_zip _ _ _ (Native.original_ports_nodup n F a arity) p hp\n/-- Every original typed port has its actual physical pair; no choice enters the runtime source. -/\ntheorem pair_for (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n)\n    (port:(e:Fin F)×Fin (arity e)):\n    ∃out,(port,out)∈Pair.paired n F a arity owner:=by\n  have hl:=congrArg List.length (SemiprimeD1PacketReplayOriginal.sources n F 64 a arity owner)\n  rw [List.length_map,SemiprimeD1IncidenceAcquisition.keys_original,List.length_map] at hl\n  exact exists_zip_right _ _ hl.symm port (Native.original_ports_complete n F a arity port)\n/-- Actual edge-ID acquisition gives an injective original port codec, proved using its real first-match bank. -/\ntheorem edgeFor_injective (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n)\n    (q:Fin a) (g:Fin 64):Function.Injective (edgeFor n F a arity owner):=by\n  intro left right he\n  obtain ⟨lo,hlo⟩:=pair_for n F a arity owner left\n  obtain ⟨ro,hro⟩:=pair_for n F a arity owner right\n  have hl:=edgeFor_pair n F a arity owner (left,lo) hlo\n  have hr:=edgeFor_pair n F a arity owner (right,ro) hro\n  have heq:lo.edge=ro.edge:=hl.symm.trans (he.trans hr)\n  let data:=SemiprimeD1ChildPortPullback.acquire n F 64 a arity owner q g\n  have hmleft:(lo.edge,left)∈data.ids:=by\n    rw [Native.ids_value]\n    exact List.mem_map.mpr ⟨(left,lo),hlo,rfl⟩\n  have hmright:(ro.edge,right)∈data.ids:=by\n    rw [Native.ids_value]\n    exact List.mem_map.mpr ⟨(right,ro),hro,rfl⟩\n  have hfindleft:=Native.findPort_member data.ids (Native.ids_nodup n F 64 a arity owner q g) lo.edge left hmleft\n  have hfindright:=Native.findPort_member data.ids (Native.ids_nodup n F 64 a arity owner q g) ro.edge right hmright\n  rw [heq,hfindright] at hfindleft\n  exact Option.some.inj hfindleft.symm\n/-- Exact edge-plus-side field key, before the source's later physical TRUE sentinel. -/\ndef rawTag (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n)\n    (tag:((e:Fin F)×Fin (arity e))×Bool):List Bool:=\n  SemiprimeSourceHistogramKeyBits.frame (edgeFor n F a arity owner tag.1) [tag.2]\n/-- Sentinel-protected raw equality is injective on ALL original typed ports and sides. -/\ntheorem rawTag_injective (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n)\n    (q:Fin a) (g:Fin 64):Function.Injective (rawTag n F a arity owner):=by\n  intro left right h\n  have hs:=SemiprimeSourceHistogramKeyBits.frame_injective _ _ _ _ h\n  exact Prod.ext (edgeFor_injective n F a arity owner q g hs.1) (List.cons.inj hs.2).1\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeTags\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortOneView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortOne\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagSourceView\n/-! # Complete actual original-port iteration restoration and ordered index meaning -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortOneView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryOldPortOne\nopen SemiprimeBitArithmetic (bitValue)\nnamespace QV\nexport SemiprimeD1StackChildGroupFactoryTagSourceView (result_other result_answer result_local result_tag result_work result_orderHistory)\nend QV\nnamespace Early\nexport SemiprimeD1StackChildGroupFactoryTagEarlyClear (role)\nend Early\nnamespace PV\nexport SemiprimeD1StackChildGroupFactoryOldPortPickView\n  (result_oldReader result_role result_clean result_skipped_tag)\nend PV\nnamespace Position\nexport SemiprimeD1StackChildGroupFactoryTagLoopView (finalPosition)\nend Position\nnamespace Log\nexport SemiprimeD1StackChildGroupFactoryWordLog (row)\nend Log\n/-- Full actual cache retention outside the original reader, query work and ordered answer log. -/\ntheorem result_other (before:Stack→List Bool) (buckets:List Buckets.Bucket) (p:Parse.Point) (tail target:List Bool) (k:Stack)\n    (hf:∀j,Early.role j≠k) (ho:k≠aux .oldReader) (ha:k≠aux .answerPosition)\n    (hp:k≠aux .localPosition) (ht:k≠aux .tagWord) (hh:k≠aux .orderHistory):\n    result before buckets p tail target k=before k:=by\n  have hraw:∀j,Cleanup.role j≠k:=by\n    intro j\n    fin_cases j\n    · exact hf 4\n    · exact hf 7\n    · exact hf 8\n  by_cases h:bitValue p.vertex=bitValue target\n  · simp only [result,h,ite_true]\n    rw [QV.result_other _ _ _ _ _ k hf ha hp ht hh]\n    exact PV.result_other _ _ _ _ k hraw ho ht\n  · simp only [result,h,ite_false]\n    exact PV.result_other _ _ _ _ k hraw ho ht\n/-- Actual original reader advances exactly one record, even when the query short-circuits early. -/\ntheorem result_oldReader (before:Stack→List Bool) (buckets:List Buckets.Bucket) (p:Parse.Point) (tail target:List Bool):\n    result before buckets p tail target (aux .oldReader)=tail:=by\n  by_cases h:bitValue p.vertex=bitValue target\n  · simp only [result,h,ite_true]\n    rw [QV.result_other _ _ _ _ _ _ (by intro j;fin_cases j <;> decide)\n      (by decide) (by decide) (by decide) (by decide)]\n    exact PV.result_oldReader _ _ _ _\n  · simp only [result,h,ite_false]\n    exact PV.result_oldReader _ _ _ _\n/-- All eleven actual nested-reader/current-field/candidate roles are physically ready for the next old port. -/\ntheorem result_work (before:Stack→List Bool) (buckets:List Buckets.Bucket) (p:Parse.Point) (tail target:List Bool)\n    (hh:∀k∈Header.cleanRoles,before k=[]) (hch:∀k∈Child.cleanRoles,before k=[])\n    (ho:before (aux .outerReader)=[]) (hcan:before (aux .candidateTag)=[]) (j:Fin 11):\n    result before buckets p tail target (Early.role j)=[]:=by\n  have hh':∀k∈Header.cleanRoles,picked before p tail target k=[]:=PV.result_headerClean _ _ _ _ hh\n  have hch':∀k∈Child.cleanRoles,picked before p tail target k=[]:=PV.result_childClean _ _ _ _ hch\n  have ho':picked before p tail target (aux .outerReader)=[]:=\n    (PV.result_other _ _ _ _ _ (by intro i;fin_cases i <;> decide) (by decide) (by decide)).trans ho\n  have hc':picked before p tail target (aux .candidateTag)=[]:=\n    (PV.result_other _ _ _ _ _ (by intro i;fin_cases i <;> decide) (by decide) (by decide)).trans hcan\n  by_cases h:bitValue p.vertex=bitValue target\n  · simp only [result,h,ite_true]\n    exact QV.result_work _ _ _ _ _ hh' hch' hc' j\n  · simp only [result,h,ite_false]\n    fin_cases j\n    · exact ho'\n    · exact hh' (aux .childReader) (by simp [Header.cleanRoles])\n    · exact hh' (aux .endpointReader) (by simp [Header.cleanRoles])\n    · exact hch' (aux .rowBuffer) (by simp [Child.cleanRoles])\n    · exact hch' (aux .ownerKey) (by simp [Child.cleanRoles])\n    · exact hch' (aux .sourceKey) (by simp [Child.cleanRoles])\n    · exact hch' (aux .slotWord) (by simp [Child.cleanRoles])\n    · exact hch' (aux .edgeWord) (by simp [Child.cleanRoles])\n    · exact hch' (aux .sideWord) (by simp [Child.cleanRoles])\n    · exact hch' (aux .globalPosition) (by simp [Child.cleanRoles])\n    · exact hc'\n/-- Actual answer operand is physically fresh for the next old port. -/\ntheorem result_answer (before:Stack→List Bool) (buckets:List Buckets.Bucket) (p:Parse.Point) (tail target:List Bool)\n    (ha:before (aux .answerPosition)=[]):result before buckets p tail target (aux .answerPosition)=[]:=by\n  by_cases h:bitValue p.vertex=bitValue target\n  · simp only [result,h,ite_true];exact QV.result_answer _ _ _ _ _\n  · simp only [result,h,ite_false]\n    exact (PV.result_other _ _ _ _ _ (by intro i;fin_cases i <;> decide) (by decide) (by decide)).trans ha\n/-- Actual local counter is physically fresh for the next old port. -/\ntheorem result_local (before:Stack→List Bool) (buckets:List Buckets.Bucket) (p:Parse.Point) (tail target:List Bool)\n    (hp:before (aux .localPosition)=[]):result before buckets p tail target (aux .localPosition)=[]:=by\n  by_cases h:bitValue p.vertex=bitValue target\n  · simp only [result,h,ite_true];exact QV.result_local _ _ _ _ _\n  · simp only [result,h,ite_false]\n    exact (PV.result_other _ _ _ _ _ (by intro i;fin_cases i <;> decide) (by decide) (by decide)).trans hp\n/-- Actual target tag is physically fresh before acquiring the next original tag. -/\ntheorem result_tag (before:Stack→List Bool) (buckets:List Buckets.Bucket) (p:Parse.Point) (tail target:List Bool)\n    (ht:before (aux .tagWord)=[]):result before buckets p tail target (aux .tagWord)=[]:=by\n  by_cases h:bitValue p.vertex=bitValue target\n  · simp only [result,h,ite_true];exact QV.result_tag _ _ _ _ _\n  · simp only [result,h,ite_false]\n    exact (PV.result_skipped_tag _ _ _ _ h).trans ht\n/-- Physical binary answer word generated by this actual whole first-index query. -/\ndef answerWord (buckets:List Buckets.Bucket) (p:Parse.Point) (target:List Bool):List Bool:=\n  Position.finalPosition buckets target (Build.rawTag p.edge p.side) []\n/-- Exactly matching numeric old vertices emit one computed first-index word, in original old-port order. -/\ntheorem result_orderHistory (before:Stack→List Bool) (buckets:List Buckets.Bucket) (p:Parse.Point) (tail target:List Bool):\n    result before buckets p tail target (aux .orderHistory)=\n      (if bitValue p.vertex=bitValue target then (Log.row (answerWord buckets p target)).reverse else [])++before (aux .orderHistory):=by\n  by_cases h:bitValue p.vertex=bitValue target\n  · simp only [result,h,ite_true]\n    rw [QV.result_orderHistory]\n    rw [picked,PV.result_other _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide)]\n    rfl\n  · simp only [result,h,ite_false]\n    rw [picked,PV.result_other _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide)]\n    rfl\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortOneView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagInner":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagVisitView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsInner\n/-! # Actual first-match child-vector search with a physical binary local counter\nThe actual source stops at its first whole-tag match. At physical child EOF it\nreturns to the outer bucket scan. Predicates/results below are specifications\nof actual bytes and source branches, never runtime verdict/counter suppliers.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagInner\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace Visit\nexport SemiprimeD1StackChildGroupFactoryTagVisit (next candidate result timeBound source_trace)\nend Visit\nnamespace View\nexport SemiprimeD1StackChildGroupFactoryTagVisitView\n  (hit advance result_reader result_clean result_other result_position result_candidate)\nend View\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryChildParse (cleanRoles)\nend Parse\nnamespace Encoding\nexport SemiprimeD1StackChildGroupFactoryLeftPortsInner (Child records)\nend Encoding\nnamespace Cleanup\nexport SemiprimeD1StackChildGroupFactoryChildCleanup (role)\nend Cleanup\nopen SemiprimeBitArithmetic (bitValue)\n/-- Constructive decidability of the actual numeric-vertex/literal-tag test. -/\ninstance hitDecidable (e:SemiprimeD1StackChildGroupFactoryBucketParse.Endpoint) (target tag:List Bool):\n    Decidable (View.hit e target tag):=\n  inferInstanceAs (Decidable (bitValue e.vertex=bitValue target ∧ tag=Visit.candidate e))\n/-- Whether actual numeric-vertex/literal-tag source tests find a match before physical EOF. -/\ndef found:List Encoding.Child→List Bool→List Bool→Bool\n  | [],_,_=>false\n  | p::ps,target,tag=>if View.hit p.1 target tag then true else found ps target tag\n/-- Actual real found or exhausted-child continuation, chosen by actual source tests. -/\ndef next (children:List Encoding.Child) (target tag:List Bool):Label:=\n  if found children target tag=true then .local 13 19 else .local 11 28\n/-- The actual child EOF pop/peek leaves its reader empty. -/\ndef atEOF (before:Stack→List Bool):Stack→List Bool:=Function.update before (aux .endpointReader) []\n/-- Full physical bank at the actual first-hit or exhausted-child boundary. -/\ndef result:List Encoding.Child→(Stack→List Bool)→List Bool→List Bool→List Bool→Stack→List Bool\n  | [],before,_,_,_=>atEOF before\n  | p::ps,before,target,tag,position=>if View.hit p.1 target tag then\n      Visit.result before p.1 p.2 (Encoding.records ps) target tag position\n    else result ps (Visit.result before p.1 p.2 (Encoding.records ps) target tag position)\n      target tag (View.advance p.1 target position)\n/-- Only the actual executed prefix is paid; no later child is visited after a real hit. -/\ndef timeBound:List Encoding.Child→List Bool→List Bool→List Bool→Nat\n  | [],_,_,_=>2\n  | p::ps,target,tag,position=>Visit.timeBound p.1 p.2 target tag position+\n      if View.hit p.1 target tag then 0 else timeBound ps target tag (View.advance p.1 target position)\n/-- Exact real child-EOF instructions before the next outer bucket. -/\ntheorem eof_trace (before:Stack→List Bool) (hr:before (aux .endpointReader)=[false]):\n    Runs program 2 (.local 12 9) before (.local 11 28) (atEOF before):=by\n  have h0:=pop_run (.local 12 9) abort (.local 12 10) (.local 12 11) (aux .endpointReader) before [false] rfl hr\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n  have h1:=peek_run (.local 12 10) (.local 11 28) abort abort (aux .endpointReader) (atEOF before) [] rfl\n    (Function.update_self _ _ _)\n  simp only [List.head?_nil,SemiprimeD1StackBytecode.choose] at h1\n  exact join h0 h1\n/-- Entire actual first-match child scan, preserving every real outer return frame. -/\ntheorem source_trace (children:List Encoding.Child) (before:Stack→List Bool) (target tag position:List Bool)\n    (hi:before (aux .endpointReader)=Encoding.records children)\n    (hz:∀k∈Parse.cleanRoles,before k=[])\n    (ht:before (aux .vertexKey)=target) (htag:before (aux .tagWord)=tag)\n    (hp:before (aux .localPosition)=position) (hcan:before (aux .candidateTag)=[])\n    (hc:before (aux .copyScratch)=[]) (ha:∀k,before (arithmetic k)=[]):\n    Runs program (timeBound children target tag position) (.local 12 9) before (next children target tag)\n      (result children before target tag position):=by\n  induction children generalizing before position with\n  | nil=>simpa only [timeBound,next,found,Bool.false_eq_true,ite_false,result] using eof_trace before hi\n  | cons p ps ih=>\n    have h0:=Visit.source_trace before p.1 p.2 (Encoding.records ps) target tag position hi hz ht htag hp hcan hc ha\n    by_cases h:View.hit p.1 target tag\n    · have hh:bitValue p.1.vertex=bitValue target ∧ tag=Visit.candidate p.1:=h\n      have h0':Runs program (Visit.timeBound p.1 p.2 target tag position) (.local 12 9) before (.local 13 19)\n          (Visit.result before p.1 p.2 (Encoding.records ps) target tag position):=by\n        simpa [Visit.next,hh] using h0\n      simpa [timeBound,result,found,h,next] using h0'\n    · have hh:¬(bitValue p.1.vertex=bitValue target ∧ tag=Visit.candidate p.1):=h\n      have h0':Runs program (Visit.timeBound p.1 p.2 target tag position) (.local 12 9) before (.local 12 9)\n          (Visit.result before p.1 p.2 (Encoding.records ps) target tag position):=by\n        simpa only [Visit.next,hh,ite_false] using h0\n      let after:=Visit.result before p.1 p.2 (Encoding.records ps) target tag position\n      have hi':after (aux .endpointReader)=Encoding.records ps:=View.result_reader _ _ _ _ _ _ _ h\n      have hz':∀k∈Parse.cleanRoles,after k=[]:=View.result_clean _ _ _ _ _ _ _ hz h\n      have ht':after (aux .vertexKey)=target:=\n        (View.result_other _ _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans ht\n      have htag':after (aux .tagWord)=tag:=\n        (View.result_other _ _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans htag\n      have hp':after (aux .localPosition)=View.advance p.1 target position:=View.result_position _ _ _ _ _ _ _ hp h\n      have hcan':after (aux .candidateTag)=[]:=View.result_candidate _ _ _ _ _ _ _ hcan h\n      have hc':after (aux .copyScratch)=[]:=\n        (View.result_other _ _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans hc\n      have ha':∀k,after (arithmetic k)=[]:=by\n        intro k\n        exact (View.result_other _ _ _ _ _ _ _ _ (by intro j;fin_cases j <;> simp [Cleanup.role,arithmetic,aux])\n          (by simp [arithmetic,aux]) (by simp [arithmetic,aux]) (by simp [arithmetic,aux])).trans (ha k)\n      have h1:=ih after (View.advance p.1 target position) hi' hz' ht' htag' hp' hcan' hc' ha'\n      have hwhole:=join h0' h1\n      simpa only [timeBound,result,found,h,ite_false,next] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagInner\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryVerticesLoopView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryVerticesLoop\n/-! # Exact complete all-vertex ordered logs and retained physical bank\nThese are projections of the actual marker-loop result, including empty and\nisolated vertices. Actual binary add-one outputs determine every query key.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryVerticesLoopView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryVerticesLoop\nnamespace View\nexport SemiprimeD1StackChildGroupFactoryVertexBodyView\n  (result_vertexHistory result_factorHistory)\nend View\nnamespace Log\nexport SemiprimeD1StackChildGroupFactoryWordLog (row)\nend Log\nnamespace Unary\nexport SemiprimeD1StackPortOrdinalStream (result)\nend Unary\nnamespace Left\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (portWords)\nend Left\nnamespace Old\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (orderWords)\nend Old\n/-- Literal forward rows whose reversals are logged by the real scope source. -/\ndef scopeRows : List Bool → List Buckets.Bucket → List Bool → List Bool\n  | [],_,_=>[]\n  | _::todo,buckets,key=>Log.row (Unary.result (Left.portWords buckets key)) ++\n      scopeRows todo buckets (Inc.successor key)\n/-- Literal forward rows whose reversals are logged by the real order source. -/\ndef orderRows : List Bool → List Points.Point → List Buckets.Bucket → List Bool → List Bool\n  | [],_,_,_=>[]\n  | _::todo,points,buckets,key=>Log.row (Unary.result (Old.orderWords buckets points key)) ++\n      orderRows todo points buckets (Inc.successor key)\n/-- Final actual binary counter word after all physical marker iterations. -/\ndef finalKey : List Bool → List Bool → List Bool\n  | [],key=>key\n  | _::todo,key=>finalKey todo (Inc.successor key)\n/-- Every protected source/cache word survives all marker iterations. -/\ntheorem result_other (todo:List Bool) (before:Stack→List Bool) (points:List Points.Point)\n    (buckets:List Buckets.Bucket) (key:List Bool) (k:Stack)\n    (hk:BV.Protected k) (ht:k≠aux .vertexTodo):\n    result todo before points buckets key k=before k:=by\n  induction todo generalizing before key with\n  | nil=>simp only [result,atEOF,Function.update_of_ne ht]\n  | cons b todo ih=>\n    rw [result,ih,BV.result_other _ _ _ _ _ hk]\n    exact Function.update_of_ne ht _ _\n/-- The marker tape is genuinely exhausted at the stopped loop boundary. -/\ntheorem result_todo (todo:List Bool) (before:Stack→List Bool) (points:List Points.Point)\n    (buckets:List Buckets.Bucket) (key:List Bool):\n    result todo before points buckets key (aux .vertexTodo)=[]:=by\n  induction todo generalizing before key with\n  | nil=>change Function.update before (aux .vertexTodo) [] (aux .vertexTodo)=[]\n         exact Function.update_self _ _ _\n  | cons b todo ih=>exact ih _ _\n/-- All physical query/ordinal/arithmetic readiness is preserved by the complete loop. -/\ntheorem result_ready (todo:List Bool) (before:Stack→List Bool) (points:List Points.Point)\n    (buckets:List Buckets.Bucket) (key:List Bool) (hr:Body.Ready before):\n    Body.Ready (result todo before points buckets key):=by\n  induction todo generalizing before key with\n  | nil=>exact popped_ready before [] hr\n  | cons b todo ih=>exact ih _ _ (BV.result_ready _ _ _ _ (popped_ready _ _ hr))\n/-- Exact complete reversed scope log, before the paid final reversal. -/\ntheorem result_vertexHistory (todo:List Bool) (before:Stack→List Bool) (points:List Points.Point)\n    (buckets:List Buckets.Bucket) (key:List Bool):\n    result todo before points buckets key (aux .vertexHistory)=\n      (scopeRows todo buckets key).reverse++before (aux .vertexHistory):=by\n  induction todo generalizing before key with\n  | nil=>simp only [result,atEOF,Function.update_of_ne (by decide : aux .vertexHistory≠aux .vertexTodo),scopeRows,List.reverse_nil,List.nil_append]\n  | cons b todo ih=>\n    rw [result,ih,View.result_vertexHistory]\n    simp only [popped,Function.update_of_ne (by decide : aux .vertexHistory≠aux .vertexTodo),scopeRows,List.reverse_append,List.append_assoc]\n/-- Exact complete reversed original-port-order log, before the paid final reversal. -/\ntheorem result_factorHistory (todo:List Bool) (before:Stack→List Bool) (points:List Points.Point)\n    (buckets:List Buckets.Bucket) (key:List Bool):\n    result todo before points buckets key (aux .factorHistory)=\n      (orderRows todo points buckets key).reverse++before (aux .factorHistory):=by\n  induction todo generalizing before key with\n  | nil=>simp only [result,atEOF,Function.update_of_ne (by decide : aux .factorHistory≠aux .vertexTodo),orderRows,List.reverse_nil,List.nil_append]\n  | cons b todo ih=>\n    rw [result,ih,View.result_factorHistory]\n    simp only [popped,Function.update_of_ne (by decide : aux .factorHistory≠aux .vertexTodo),orderRows,List.reverse_append,List.append_assoc]\n/-- Exact generated counter after the last real add-one call. -/\ntheorem result_key (todo:List Bool) (before:Stack→List Bool) (points:List Points.Point)\n    (buckets:List Buckets.Bucket) (key:List Bool) (hk:before (aux .vertexKey)=key):\n    result todo before points buckets key (aux .vertexKey)=finalKey todo key:=by\n  induction todo generalizing before key with\n  | nil=>simpa only [result,atEOF,Function.update_of_ne (by decide : aux .vertexKey≠aux .vertexTodo),finalKey] using hk\n  | cons b todo ih=>exact ih _ _ (BV.result_key _ _ _ _)\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryVerticesLoopView\n","RiemannGaussian.SemiprimeD1StackChildUnitVertexStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildUnitVertexBounds\n/-! # All32 actual data roles, displaced cache shadows and real return cells -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildUnitVertexStorage\nopen SemiprimeD1StackChildUnitVertex SemiprimeD1StackChildUnitVertexOriginal\nopen SemiprimeD1StackChildUnitVertexBounds\n/-- Only the two context-header tapes are present before all acquired counters/unit/record bits. -/\ntheorem initial_length (axes : List ℕ) (precision : List Bool) (k : Stack) :\n    ((originalInitial axes precision).data k).length≤resource axes precision := by\n  rcases k with k|k\n  · exact SemiprimeD1StackJetContextBounds.initial_length axes precision k\n  · rcases k with k|k\n    · change (if k=U.widthCache ∨ k=U.rankCache then [] else ([] : List Bool)).length≤_\n      split <;> exact Nat.zero_le _\n    · cases k <;> exact Nat.zero_le _\n/-- No actual successful source prefix extends beyond this same source's whole proved halt. -/\ntheorem prefix_fuel (axes : List ℕ) (hp : ∀q∈axes,0<q) (precision : List Bool)\n    (fuel : ℕ) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (originalInitial axes precision)=some out) :\n    fuel≤polynomial axes precision := by\n  obtain ⟨t,ht,hs⟩:=source_run_bounded axes hp precision\n  have hf : fuel≤t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hs,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hh : SemiprimeD1StackCalls.run program 1 (done axes precision)=none := rfl\n    rw [hh,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- An abstract inventory bound, without concrete register-enumeration reduction. -/\ntheorem finite_sum_bound {K : Type} [Fintype K] (data : K→List Bool) (cap : ℕ)\n    (h : ∀k,(data k).length≤cap) : (∑k : K,(data k).length)≤Fintype.card K*cap := by\n  calc\n    _≤∑_k : K,cap:=Finset.sum_le_sum (fun k _=>h k)\n    _=_:=by simp only [Finset.sum_const,Finset.card_univ,smul_eq_mul]\n/-- Fixed coefficient/degree before every actual header and context. -/\ndef cellsPolynomial (axes : List ℕ) (precision : List Bool) : ℕ:=10^11*(resource axes precision+1)^2\n/-- Every SAME-source prefix includes ALL32 source/shadow/frame words and actual saved return cells. -/\ntheorem prefix_cells (axes : List ℕ) (hp : ∀q∈axes,0<q) (precision : List Bool)\n    (fuel : ℕ) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (originalInitial axes precision)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤cellsPolynomial axes precision := by\n  have hf:=prefix_fuel axes hp precision fuel out hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (resource axes precision)\n    _ out (initial_length axes precision) hr\n  have hm:=finite_sum_bound out.data (resource axes precision+fuel) hd\n  rw [stack_card] at hm\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel (originalInitial axes precision) out hr\n  change out.frames.length≤0+fuel at hframes\n  have hr' : resource axes precision≤(resource axes precision+1)^2:=by nlinarith [sq_nonneg (resource axes precision)]\n  unfold cellsPolynomial polynomial at *\n  omega\n/-- The actual finite32-role compiled machine counts its real none-label return tape at every reached prefix. -/\ntheorem machine_prefix_cells (axes : List ℕ) (hp : ∀q∈axes,0<q) (precision : List Bool)\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (originalInitial axes precision)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤cellsPolynomial axes precision := by\n  have heq:=SemiprimeD1StackCalls.run_correct (context J.axesCache) (aux .record) (.local .start) program fuel\n    (originalInitial axes precision)\n  have hh:=heq.trans hr\n  cases hout : SemiprimeD1StackCalls.run program fuel (originalInitial axes precision) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg : cfg=SemiprimeD1StackCalls.configuration out:=(Option.some.inj hh).symm\n    subst cfg\n    exact prefix_cells axes hp precision fuel out hout\nend RiemannGaussian.SemiprimeD1StackChildUnitVertexStorage\n","RiemannGaussian.SemiprimeD1StackChildVertexChoiceBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildVertexChoiceSource\n/-! # One fixed whole clock for both actual constructor branches\nThe resource pays actual header bytes and rank/precision VALUES. No recursively\nenlarged elapsed child runtime becomes a rational/table operand width.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildVertexChoiceBounds\nopen SemiprimeD1StackChildVertexChoice SemiprimeD1StackChildVertexChoiceSpec\nopen SemiprimeD1StackChildVertexChoiceSource\nvariable {d : ℕ}\n/-- Uniform fixed coefficient and degree, chosen before all original vertices and activity bits. -/\ndef polynomial (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order ports : List ℕ) : ℕ:=\n  10^26*(resource old extra oldp newp parent order ports)^2*2^ports.length\n/-- Both whole constructor clocks, actual activity consumption, call and halt fit the SAME quadratic envelope. -/\ntheorem timeBound_le (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order ports : List ℕ) (bit : Bool) :\n    timeBound old extra oldp newp parent order ports bit≤polynomial old extra oldp newp parent order ports := by\n  let r:=resource old extra oldp newp parent order ports\n  let e:=2^ports.length\n  have hb:=resource_bounds old extra oldp newp parent order ports\n  have hr : 1≤r:=hb.1\n  have he : 1≤e:=Nat.one_le_pow _ _ (by decide : 1≤(2:ℕ))\n  have h1 : 1≤r^2*e:=Nat.mul_le_mul (Nat.one_le_pow _ _ hr) he\n  have hs : r^2≤r^2*e:=by simpa only [Nat.mul_one] using Nat.mul_le_mul_left (r^2) he\n  have ha : (AB.resource old extra oldp newp parent order ports)^2*e≤r^2*e:=\n    Nat.mul_le_mul_right e (Nat.pow_le_pow_left hb.2.1 2)\n  have hu : (UB.resource (extra++old.axes) newp+1)^2≤r^2*e:=\n    (Nat.pow_le_pow_left hb.2.2 2).trans hs\n  unfold polynomial\n  rw [Nat.mul_assoc]\n  change timeBound old extra oldp newp parent order ports bit≤10^26*(r^2*e)\n  cases bit\n  · change 10^8*(UB.resource (extra++old.axes) newp+1)^2+3≤10^26*(r^2*e)\n    omega\n  · change 10^24*(AB.resource old extra oldp newp parent order ports)^2*e+3≤10^26*(r^2*e)\n    rw [Nat.mul_assoc]\n    omega\n/-- Actual whole eight-word source reaches its exact complete stopped169 bank within the fixed cap. -/\ntheorem source_run_bounded (old : SemiprimeD1JetAxes.Context) (ho : old.Positive)\n    (extra : List ℕ) (he : 0<extra.prod) (oldp newp : List Bool)\n    (hp : SemiprimeBitArithmetic.bitValue oldp=old.precision)\n    (parent : SemiprimeD1TensorTables.Table d) (hg : SemiprimeD1TensorTables.Good old parent)\n    (order ports : List ℕ) (bit : Bool) :\n    ∃t≤polynomial old extra oldp newp parent order ports,\n      SemiprimeD1StackCalls.run program t (originalInitial old extra oldp newp parent order ports bit)=\n        some (done old extra oldp newp parent order ports bit) := by\n  obtain ⟨t,ht,hr⟩:=source_run old ho extra he oldp newp hp parent hg order ports bit\n  exact ⟨t,ht.trans (timeBound_le old extra oldp newp parent order ports bit),hr⟩\n/-- Genuine compiled finite169-role source with the SAME whole source clock. -/\nnoncomputable def machineSource (old : SemiprimeD1JetAxes.Context) (ho : old.Positive)\n    (extra : List ℕ) (he : 0<extra.prod) (oldp newp : List Bool)\n    (hp : SemiprimeBitArithmetic.bitValue oldp=old.precision)\n    (parent : SemiprimeD1TensorTables.Table d) (hg : SemiprimeD1TensorTables.Good old parent)\n    (order ports : List ℕ) (bit : Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (originalInitial old extra oldp newp parent order ports bit))\n      (some (SemiprimeD1StackCalls.configuration (done old extra oldp newp parent order ports bit)))\n      (polynomial old extra oldp newp parent order ports) := by\n  apply SemiprimeD1StackCalls.evalsCorrect activity output (.local .start) program\n  let h:=source_run_bounded old ho extra he oldp newp hp parent hg order ports bit\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackChildVertexChoiceBounds\n","RiemannGaussian.SemiprimeD1StackChildVertexChoiceExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildVertexChoiceView\n/-! # Actual activity pop, whole source call/return and enclosing true halt -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildVertexChoiceExecution\nopen SemiprimeD1StackChildVertexChoice SemiprimeD1StackChildVertexChoiceView\nopen SemiprimeD1StackProcedureTrace\n/-- The actual bit chooses the literal call site; no native activation predicate executes. -/\ndef branch (bit : Bool) : Control:=if bit then .active else .inactive\n/-- Entire stopped169-word bank, with real flags and returns empty. -/\ndef stopped (data : Stack→List Bool) : C.State Stack Label:=⟨none,none,none,data,[]⟩\n/-- Literal singleton activity consumption, valid for arbitrary transient flags/outer frames. -/\ntheorem pop_run (a : A.Stack→List Bool) (bit : Bool) :\n    Runs program 1 (.local .start) (bank a (fun _=>[]) [bit])\n      (.local (branch bit)) (activeResult a) := by\n  apply one_base program (.local .start) (.local (branch bit))\n    (.pop activity (.local .abort) (.local .inactive) (.local .active)) _ _ rfl\n  · cases bit <;> rfl\n  · exact pop_activity a bit\n/-- Every nested active call and real return is retained, including arbitrary enclosing returns. -/\ntheorem active_call (time : ℕ) (source out : C.State A.Stack A.Label)\n    (hentry : source.pc=some (.local .start)) (hstart : source.frames=[])\n    (hstop : out.pc=none) (hframes : out.frames=[])\n    (hr : SemiprimeD1StackCalls.run A.program time source=some out) :\n    Runs program (time+1) (.local .active) (activeResult source.data)\n      (.local .done) (activeResult out.data) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program active Label.active active_injective\n    A.program (.local .start) (fun _=>rfl) (.local .active) (.local .done) rfl\n    time source out _ _ hentry hstart hstop hframes hr\n  · exact active_rel source.data source.data\n  · exact active_rel source.data out.data\n/-- The inactive whole call changes exactly its32-role image; all other active words and shadows survive. -/\ntheorem inactive_call (a : A.Stack→List Bool) (time : ℕ) (source out : C.State U.Stack U.Label)\n    (hin : ∀k,activeResult a (inactive k)=source.data k)\n    (hentry : source.pc=some (.local .start)) (hstart : source.frames=[])\n    (hstop : out.pc=none) (hframes : out.frames=[])\n    (hr : SemiprimeD1StackCalls.run U.program time source=some out) :\n    Runs program (time+1) (.local .inactive) (activeResult a)\n      (.local .done) (inactiveResult a out.data) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program inactive Label.inactive inactive_injective\n    U.program (.local .start) (fun _=>rfl) (.local .inactive) (.local .done) rfl\n    time source out _ _ hentry hstart hstop hframes hr\n  · exact ⟨hin,fun _ _=>rfl⟩\n  · exact inactive_rel a out.data\n/-- A complete caller run pays its literal pop, actual call, source trace and true halt. -/\ntheorem finish_run (a : A.Stack→List Bool) (bit : Bool) (time : ℕ) (data : Stack→List Bool)\n    (h : Runs program (time+1) (.local (branch bit)) (activeResult a) (.local .done) data) :\n    SemiprimeD1StackCalls.run program (time+3)\n      (⟨some (.local .start),none,none,bank a (fun _=>[]) [bit],[]⟩ : C.State Stack Label)=\n      some (stopped data) := by\n  have ht:=runs_trans program _ _ _ _ _ _ _ _ (pop_run a bit) h\n  obtain ⟨out,hr,ha⟩:=ht [] ⟨some (.local .start),none,none,bank a (fun _=>[]) [bit],[]⟩ ⟨rfl,rfl,rfl⟩\n  have he : time+3=(1+(time+1))+1:=by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n  exact halt_run program (.local .done) rfl data [] out ha\n/-- Whole eight-word active entry through its actual enclosing halt. -/\ntheorem active_run (parent order oldAxes oldp axes precision scope : List Bool)\n    (time : ℕ) (out : C.State A.Stack A.Label) (hstop : out.pc=none) (hframes : out.frames=[])\n    (hr : SemiprimeD1StackCalls.run A.program time\n      (A.initial parent order oldAxes oldp axes precision scope)=some out) :\n    SemiprimeD1StackCalls.run program (time+3)\n      (initial parent order oldAxes oldp axes precision scope [true])=\n      some (stopped (activeResult out.data)) :=\n  finish_run _ true time _ (active_call time _ out rfl rfl hstop hframes hr)\n/-- Whole eight-word inactive entry; only new headers feed the actual unit constructor. -/\ntheorem inactive_run (parent order oldAxes oldp axes precision scope : List Bool)\n    (time : ℕ) (out : C.State U.Stack U.Label) (hstop : out.pc=none) (hframes : out.frames=[])\n    (hr : SemiprimeD1StackCalls.run U.program time\n      (SemiprimeD1StackChildUnitVertex.initial axes precision)=some out) :\n    SemiprimeD1StackCalls.run program (time+3)\n      (initial parent order oldAxes oldp axes precision scope [false])=\n      some (stopped (inactiveResult (A.initial parent order oldAxes oldp axes precision scope).data out.data)) :=\n  finish_run _ false time _ (inactive_call _ time _ out\n    (inactive_initial parent order oldAxes oldp axes precision scope) rfl rfl hstop hframes hr)\nend RiemannGaussian.SemiprimeD1StackChildVertexChoiceExecution\n","RiemannGaussian.SemiprimeD1StackDigitBlock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1StackCopy\nimport RiemannGaussian.SemiprimeD1StackReduceExecution\n\n/-! # Physical streaming digit block\nThis program acquires one canonical low block while RETAINING the high input\ntail. A real Copy supplies the disposable width markers. A real included trim\nprocedure canonicalizes the collected bits; the retained input and cached width\nare unmapped auxiliary payload and cannot be silently cleared by that call.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 500000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackDigitBlock\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run)\nend B\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\n\n/-- Fixed data stacks; the two dummy stacks isolate the trim-only procedure entry. -/\ninductive Stack where\n  | input | width | counter | scratch | temporary | dummyLeft | dummyRight | output\n  deriving DecidableEq,Repr\n\n/-- Explicit finite stack catalogue, fixed before all inputs. -/\ninstance : Fintype Stack := Fintype.ofList\n  [.input,.width,.counter,.scratch,.temporary,.dummyLeft,.dummyRight,.output]\n  (by intro k;cases k <;> simp)\n\n/-- Actual local control and literal Copy/trim procedure labels. -/\ninductive Label where\n  | start | take | read | save (bit : Bool) | clearCounter | trimCall | done\n  | copy (label : Fin 9)\n  | trim (label : SemiprimeD1StackReduce.Label)\n  deriving DecidableEq,Fintype,Repr\n\n/-- Real persistent-width copying. -/\ndef copyStack : Fin 3→Stack := fun k=>if k=0 then .width else if k=1 then .counter else .temporary\n\n/-- The included trim call cannot touch the retained high input or cached width. -/\ndef trimStack : SemiprimeD1StackAdder.Stack→Stack\n  | .left => .dummyLeft\n  | .right => .dummyRight\n  | .scratch => .scratch\n  | .output => .output\n\n/-- The complete fixed table, with no natural-value or arbitrary-function opcode. -/\ndef program : Label→C.Instruction Stack Label\n  | .start => .call (.copy 0) .take\n  | .take => .base (.pop .counter .trimCall .read .read)\n  | .read => .base (.pop .input .clearCounter (.save false) (.save true))\n  | .save b => .base (.push .scratch b .take)\n  | .clearCounter => .base (.pop .counter .trimCall .clearCounter .clearCounter)\n  | .trimCall => .call (.trim .trim) .done\n  | .done => .base .halt\n  | .copy l => SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code l)\n  | .trim l => SemiprimeD1StackMultiplierLink.instruction trimStack Label.trim (SemiprimeD1StackReduce.code l)\n\n/-- Literal physical payload, including retained input and cached precision width. -/\ndef store (input width counter scratch temporary dummyLeft dummyRight output : List Bool) : Stack→List Bool\n  | .input => input\n  | .width => width\n  | .counter => counter\n  | .scratch => scratch\n  | .temporary => temporary\n  | .dummyLeft => dummyLeft\n  | .dummyRight => dummyRight\n  | .output => output\n\n/-- Copy has no alias among its source/restoration/output stacks. -/\ntheorem copyStack_injective : Function.Injective copyStack := by\n  intro i j h\n  fin_cases i <;> fin_cases j <;> simp_all [copyStack]\n\n/-- The trim source is included without any aliased data stacks. -/\ntheorem trimStack_injective : Function.Injective trimStack := by\n  intro i j h\n  cases i <;> cases j <;> simp_all [trimStack]\n\n/-- Fixed actual finite procedure machine. Width is an explicit physical caller input. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine Stack.input Stack.output .start program\n\n/-- Every physical alphabet, including return continuations, is finite. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite Stack.input Stack.output Label.start program\n\n/-- All internal control is finite; raw input/counters are physical stack data. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite Stack.input Stack.output Label.start program\n\nend RiemannGaussian.SemiprimeD1StackDigitBlock\n","RiemannGaussian.SemiprimeD1StackEdgeCatalogueEmit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEdgeCatalogueParse\n\n/-! # Actual edge field framing and reversal, with every bit operation retained -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 8192\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackEdgeCatalogueEmit\nopen SemiprimeD1StackEdgeCatalogue SemiprimeD1StackEdgeCatalogueComponents\nopen SemiprimeD1StackEdgeCatalogueView SemiprimeD1StackEdgeCatalogueParse\nopen SemiprimeD1StackProcedureFragments (Runs)\nopen SemiprimeD1EdgeCatalogueEncoding (Record record half sideWord)\nopen SemiprimeSourceHistogramKeyBits (frame frame_length)\n\n/-- Literal next label after one actual framed-field reversal. -/\ndef nextField (side:Bool) (part:Fin 6) : Label :=\n  if h:part.val<5 then .inl (.emitFrame side ⟨part.val+1,by omega⟩)\n  else if side then .inl .clearSide else .inl .pushSide\n/-- Actual source word at each of six static field positions. -/\ndef sourceField (words:Record) (side:List Bool) (part:Fin 6) : List Bool :=\n  if h:part.val=0 then side else words ⟨part.val-1,by omega⟩\n/-- Framing reads the actual cached field or physically acquired side marker. -/\ntheorem source_clean (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (raw side:List Bool) (part:Fin 6) :\n    clean base tape words raw side (frameSource part)=sourceField words side part := by fin_cases part <;> rfl\n/-- A physical raw-output update retains every other source/cache role. -/\ntheorem clean_raw (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (raw side next:List Bool) :\n    Function.update (clean base tape words raw side) (aux .reversed) next=clean base tape words next side := by\n  unfold clean\n  rw [update_aux]\n  congr 1\n  funext k\n  cases k <;> simp [cleanWork,Function.update]\n/-- A physical side-marker update retains all actual parsed fields. -/\ntheorem clean_side (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (raw side next:List Bool) :\n    Function.update (clean base tape words raw side) (aux .side) next=clean base tape words raw next := by\n  unfold clean\n  rw [update_aux]\n  congr 1\n  funext k\n  cases k <;> simp [cleanWork,Function.update]\n/-- One real Frame call and one real Reverse call emit the actual cached field. -/\ntheorem field_run (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (raw sideWord:List Bool)\n    (side:Bool) (part:Fin 6) :\n    Runs program (10*(sourceField words sideWord part).length+10) (.inl (.emitFrame side part))\n      (clean base tape words raw sideWord) (nextField side part)\n      (clean base tape words ((frame (sourceField words sideWord part) []).reverse++raw) sideWord) := by\n  let before:=clean base tape words raw sideWord\n  let word:=sourceField words sideWord part\n  have hf:=frame_call part side before rfl rfl\n  have hsource:before (frameSource part)=word:=source_clean base tape words raw sideWord part\n  rw [hsource] at hf\n  have hr:=reverse_call false (Function.update before (aux .frameBuffer) (frame word []))\n    (.inl (.emitReverse side part)) (nextField side part) rfl\n  have hi:(Function.update before (aux .frameBuffer) (frame word [])) (reverseInput false)=frame word []:=\n    Function.update_self _ _ _\n  have ho:(Function.update before (aux .frameBuffer) (frame word [])) (reverseOutput false)=raw:=by\n    simp [reverseOutput,before,clean,store,cleanWork,aux,Function.update]\n  rw [hi,ho] at hr\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (Function.update before (aux .frameBuffer) (frame word [])) (aux .frameBuffer) [])\n      (aux .reversed) ((frame word []).reverse++raw)) at hr\n  rw [Function.update_idem] at hr\n  have he:Function.update before (aux .frameBuffer) []=before:=by\n    have hh:before (aux .frameBuffer)=[]:=rfl\n    rw [←hh]\n    exact Function.update_eq_self _ _\n  rw [he,clean_raw] at hr\n  have h:=hf.trans hr\n  rw [frame_length,List.length_nil] at h\n  simpa only [show (6*word.length+5)+(2*(2*word.length+0+1)+3)=10*word.length+10 by omega] using h\n\n/-- Framing retains the exact acquired tail. -/\ntheorem frame_append (xs ys:List Bool) : frame xs ys=frame xs []++ys := by\n  induction xs with\n  | nil => rfl\n  | cons b xs ih => simpa only [frame,List.cons_append] using congrArg (fun rest=>true::b::rest) ih\n/-- Literal reverse of one side-plus-descriptor record. -/\ntheorem reverse_record (words:Record) (side raw:List Bool) :\n    (frame (words 4) []).reverse++((frame (words 3) []).reverse++((frame (words 2) []).reverse++\n      ((frame (words 1) []).reverse++((frame (words 0) []).reverse++((frame side []).reverse++raw)))))=\n      (frame side (record words [])).reverse++raw := by\n  symm\n  unfold record\n  rw [frame_append side,frame_append (words 0),frame_append (words 1),frame_append (words 2),frame_append (words 3)]\n  simp only [List.reverse_append,List.append_assoc]\n\n/-- Both output continuations are static finite labels. -/\ndef afterRecord (side:Bool) : Label := if side then .inl .clearSide else .inl .pushSide\n/-- All six actual fields are emitted without catalogue/count/record callbacks. -/\ntheorem record_run (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (raw sideWord:List Bool) (side:Bool) :\n    Runs program (10*(sideWord.length+wordMass words)+60) (.inl (.emitFrame side 0))\n      (clean base tape words raw sideWord) (afterRecord side)\n      (clean base tape words ((frame sideWord (record words [])).reverse++raw) sideWord) := by\n  let r1:=(frame sideWord []).reverse++raw\n  let r2:=(frame (words 0) []).reverse++r1\n  let r3:=(frame (words 1) []).reverse++r2\n  let r4:=(frame (words 2) []).reverse++r3\n  let r5:=(frame (words 3) []).reverse++r4\n  have h0:=field_run base tape words raw sideWord side 0\n  have h1:=field_run base tape words r1 sideWord side 1\n  have h2:=field_run base tape words r2 sideWord side 2\n  have h3:=field_run base tape words r3 sideWord side 3\n  have h4:=field_run base tape words r4 sideWord side 4\n  have h5:=field_run base tape words r5 sideWord side 5\n  have h:=h0.trans (h1.trans (h2.trans (h3.trans (h4.trans h5))))\n  change Runs program _ _ _ (afterRecord side) (clean base tape words\n    ((frame (words 4) []).reverse++((frame (words 3) []).reverse++((frame (words 2) []).reverse++\n      ((frame (words 1) []).reverse++((frame (words 0) []).reverse++((frame sideWord []).reverse++raw)))))) sideWord) at h\n  rw [reverse_record] at h\n  have ht:(10*sideWord.length+10+(10*(words 0).length+10+(10*(words 1).length+10+\n      (10*(words 2).length+10+(10*(words 3).length+10+(10*(words 4).length+10))))))=\n      10*(sideWord.length+wordMass words)+60:=by unfold wordMass;omega\n  change Runs program (10*sideWord.length+10+(10*(words 0).length+10+(10*(words 1).length+10+\n    (10*(words 2).length+10+(10*(words 3).length+10+(10*(words 4).length+10)))))) _ _ _ _ at h\n  rw [ht] at h\n  exact h\n\n/-- Framing preserves an actual appended tail byte for byte. -/\ntheorem frame_tail (xs ys zs:List Bool) : frame xs (ys++zs)=frame xs ys++zs := by\n  induction xs with\n  | nil => rfl\n  | cons b xs ih => simpa only [frame,List.cons_append] using congrArg (fun rest=>true::b::rest) ih\n/-- Five-field descriptor framing preserves its actual tail. -/\ntheorem record_append (words:Record) (tail:List Bool) : record words tail=record words []++tail := by\n  unfold record\n  rw [frame_append (words 4) tail,frame_tail (words 3),frame_tail (words 2),frame_tail (words 1),frame_tail (words 0)]\n/-- The actual side field and descriptor preserve their acquired tape suffix. -/\ntheorem half_append (side:Bool) (words:Record) (tail:List Bool) : half side words tail=half side words []++tail := by\n  unfold half\n  rw [record_append,frame_tail]\n/-- Reverse accumulation retains the exact original false-before-true order. -/\ntheorem reverse_pair (words:Record) (raw:List Bool) :\n    (half true words []).reverse++((half false words []).reverse++raw)=\n      (half false words (half true words [])).reverse++raw := by\n  rw [half_append false words (half true words [])]\n  simp only [List.reverse_append,List.append_assoc]\n/-- Both literal edge-side records are physically emitted, with actual side acquisition/cleanup. -/\ntheorem pair_run (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (raw:List Bool) :\n    Runs program (20*wordMass words+132) (.inl (.emitFrame false 0))\n      (clean base tape words raw []) (.inl (.clearCache 0))\n      (clean base tape words ((half false words (half true words [])).reverse++raw) []) := by\n  let r1:=(half false words []).reverse++raw\n  let r2:=(half true words []).reverse++r1\n  have h0:=record_run base tape words raw [] false\n  change Runs program _ _ _ (.inl .pushSide) (clean base tape words r1 []) at h0\n  have h1:=push_run (.inl .pushSide) (.inl (.emitFrame true 0)) (aux .side) true (clean base tape words r1 []) rfl\n  change Runs program _ _ _ _ (Function.update (clean base tape words r1 []) (aux .side) [true]) at h1\n  rw [clean_side] at h1\n  have h2:=record_run base tape words r1 [true] true\n  change Runs program _ _ _ (.inl .clearSide) (clean base tape words r2 [true]) at h2\n  have h3:=pop_run (.inl .clearSide) (.inl (.clearCache 0)) (aux .side) (clean base tape words r2 [true]) rfl\n  change Runs program _ _ _ _ (Function.update (clean base tape words r2 [true]) (aux .side) []) at h3\n  rw [clean_side] at h3\n  have h:=h0.trans (h1.trans (h2.trans h3))\n  change Runs program _ _ _ _ (clean base tape words\n    ((half true words []).reverse++((half false words []).reverse++raw)) []) at h\n  rw [reverse_pair] at h\n  have ht:(10*(0+wordMass words)+60)+(1+((10*(1+wordMass words)+60)+1))=20*wordMass words+132:=by omega\n  change Runs program ((10*(0+wordMass words)+60)+(1+((10*(1+wordMass words)+60)+1))) _ _ _ _ at h\n  rw [ht] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackEdgeCatalogueEmit\n\n","RiemannGaussian.SemiprimeD1StackEdgeCountFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEdgeCount\n/-! # Actual six physical field reads, validity pops and payload drains -/\nset_option autoImplicit false\nset_option maxHeartbeats 1500000\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackEdgeCountFields\nopen SemiprimeD1StackEdgeCount\nopen SemiprimeD1StackProcedureFragments (Runs one_base included_call)\nopen SemiprimeSourceHistogramKeyBits (frame)\n\n/-- Actual preserving whole-edge-tape Copy, not a read-only byte-size formula. -/\ntheorem copy_call (bank : List Bool) :\n    Runs program (5*bank.length+4) (.inl .start) (data bank [] [] [] [] [] []) (.inl .peekRecord)\n      (data bank bank [] [] [] [] []) := by\n  apply included_call program copyStack copyLabel SemiprimeD1StackDigitCount.copyStack_injective\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (.inl .start) (.inl .peekRecord) rfl (5*bank.length+3)\n    (SemiprimeD1StackCopy.state 0 none bank [] []) (SemiprimeD1StackCopy.done bank bank)\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words bank [] none\n  · exact SemiprimeD1StackDigitCountComponents.copy_input bank\n  · exact SemiprimeD1StackDigitCountComponents.copy_output bank\n\n/-- Every field, including the empty side field, is actually parsed and copied. -/\ntheorem field_call (part : Fin 6) (bank word tail count wire : List Bool) :\n    Runs program (8*word.length+7) (.inl (.read part)) (data bank (frame word tail) count [] [] [] wire)\n      (.inl (.valid part)) (data bank tail count word [] [true] wire) := by\n  apply included_call program fieldStack fieldLabel SemiprimeD1StackDigitCount.fieldStack_injective\n    Field.code (Field.active .tagPop (none,false)) (fun _=>rfl) (.inl (.read part)) (.inl (.valid part)) rfl\n    (8*word.length+6) (SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) [])\n    (⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩:\n      B.State Field.Stack Field.Label)\n  · rfl\n  · rfl\n  · exact SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  · constructor\n    · intro k\n      cases k with\n      | inl k => cases k <;> rfl\n      | inr k => cases k; rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k\n      cases k with\n      | inl k => cases k <;> rfl\n      | inr k => cases k; rfl\n    · intro k hk\n      cases k with\n      | bank => rfl\n      | count => rfl\n      | copyScratch => rfl\n      | reader => exact False.elim (hk (.inl .input) rfl)\n      | word => exact False.elim (hk (.inl .output) rfl)\n      | fieldScratch => exact False.elim (hk (.inl .scratch) rfl)\n      | valid => exact False.elim (hk (.inr ()) rfl)\n\n/-- Acquired field-validity is physically consumed before any next-field control. -/\ntheorem pop_valid (part : Fin 6) (bank reader count word wire : List Bool) :\n    Runs program 1 (.inl (.valid part)) (data bank reader count word [] [true] wire)\n      (.inl (.clear part)) (data bank reader count word [] [] wire) := by\n  apply one_base program _ _ (.pop .valid (.inl .abort) (.inl .abort) (.inl (.clear part))) _ _ rfl\n  · rfl\n  · funext k; cases k <;> simp [B.execute,SemiprimeD1StackDigitCount.data,Function.update]\n\n/-- Every parsed payload is physically cleared before the next of SIX fields. -/\ntheorem clear_word (part : Fin 6) (word bank reader count wire : List Bool) :\n    Runs program (word.length+1) (.inl (.clear part)) (data bank reader count word [] [] wire)\n      (afterClear part) (data bank reader count [] [] [] wire) := by\n  induction word with\n  | nil =>\n    apply one_base program _ _ (.pop .word (afterClear part) (.inl (.clear part)) (.inl (.clear part))) _ _ rfl\n    · rfl\n    · funext k; cases k <;> simp [B.execute,SemiprimeD1StackDigitCount.data,Function.update]\n  | cons bit word ih =>\n    have h : Runs program 1 (.inl (.clear part)) (data bank reader count (bit::word) [] [] wire)\n        (.inl (.clear part)) (data bank reader count word [] [] wire) := by\n      apply one_base program _ _ (.pop .word (afterClear part) (.inl (.clear part)) (.inl (.clear part))) _ _ rfl\n      · cases bit <;> rfl\n      · cases bit <;> funext k <;> cases k <;> simp [B.execute,SemiprimeD1StackDigitCount.data,Function.update]\n    simpa only [List.length_cons,show 1+(word.length+1)=word.length+1+1 by omega] using h.trans ih\n\n/-- Closed actual one-field round: parser, real validity pop and complete drain. -/\ntheorem field_run (part : Fin 6) (bank word tail count wire : List Bool) :\n    Runs program (9*word.length+9) (.inl (.read part)) (data bank (frame word tail) count [] [] [] wire)\n      (afterClear part) (data bank tail count [] [] [] wire) := by\n  have h:=(field_call part bank word tail count wire).trans\n    ((pop_valid part bank tail count word wire).trans (clear_word part word bank tail count wire))\n  simpa only [show (8*word.length+7)+(1+(word.length+1))=9*word.length+9 by omega] using h\n\n/-- Exact sum of the SIX physical field-round transition counts. -/\ndef fieldsTime (words : Record) : ℕ :=\n  (9*(words 0).length+9)+(9*(words 1).length+9)+(9*(words 2).length+9)+\n    (9*(words 3).length+9)+(9*(words 4).length+9)+(9*(words 5).length+9)\n\n/-- All six original fields execute before the count marker can be pushed. -/\ntheorem fields_run (words : Record) (bank tail count wire : List Bool) :\n    Runs program (fieldsTime words) (.inl (.read 0)) (data bank (record words tail) count [] [] [] wire)\n      (.inl .pushCount) (data bank tail count [] [] [] wire) := by\n  have h0:=field_run 0 bank (words 0)\n    (frame (words 1) (frame (words 2) (frame (words 3) (frame (words 4) (frame (words 5) tail))))) count wire\n  have h1:=field_run 1 bank (words 1) (frame (words 2) (frame (words 3) (frame (words 4) (frame (words 5) tail)))) count wire\n  have h2:=field_run 2 bank (words 2) (frame (words 3) (frame (words 4) (frame (words 5) tail))) count wire\n  have h3:=field_run 3 bank (words 3) (frame (words 4) (frame (words 5) tail)) count wire\n  have h4:=field_run 4 bank (words 4) (frame (words 5) tail) count wire\n  have h5:=field_run 5 bank (words 5) tail count wire\n  simp only [afterClear] at h0 h1 h2 h3 h4 h5\n  norm_num at h0 h1 h2 h3 h4 h5\n  exact (((((h0.trans h1).trans h2).trans h3).trans h4).trans h5)\n\nend RiemannGaussian.SemiprimeD1StackEdgeCountFields\n","RiemannGaussian.SemiprimeD1StackExprLiteralExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprLiteral\n\n/-! # Actual encoded literal evaluation and reusable physical base case\nBoth parser and fitter are literally included. Their outputs and validity bit\nare consequences of their executed traces, never premises supplied by a caller.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackExprLiteralExecution\nopen SemiprimeD1StackExprLiteral SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n\n/-- Actual pre-parser data, still containing the framed literal payload. -/\ndef beforeField (word tail cached : List Bool) : Stack→List Bool := input (frame word tail) cached\n/-- Reached data after the physical parser has computed its true validity bit. -/\ndef parsed (word tail cached : List Bool) : Stack→List Bool :=\n  store tail (Fit.store word cached [] [] []) [true]\n/-- Actual parser flag has been consumed before the fitter call. -/\ndef beforeFit (word tail cached : List Bool) : Stack→List Bool :=\n  store tail (Fit.store word cached [] [] []) []\n/-- Exact final physical syntax suffix, template cache and literal output. -/\ndef finalData (word tail cached : List Bool) : Stack→List Bool :=\n  store tail (Fit.store [] cached [] [] (SemiprimeD1StackWordFitExecution.result word cached)) []\n/-- Clean terminal source state, retaining the real code suffix and cache. -/\ndef done (word tail cached : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,finalData word tail cached,[]⟩\n\n/-- Both literal constructor tags are actually read, not inferred from a supplied AST. -/\ntheorem tags_run (word tail cached : List Bool) :\n    Runs program 2 (ctl .start)\n      (input (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached)\n      (ctl .fieldCall) (beforeField word tail cached) := by\n  have h0 : Runs program 1 (ctl .start)\n      (input (false::false::frame word tail) cached) (ctl .secondTag)\n      (input (false::frame word tail) cached) := by\n    apply one_base program (ctl .start) (ctl .secondTag)\n      (.pop inputCode (ctl .bad) (ctl .secondTag) (ctl .bad)) _ _ rfl\n    · rfl\n    · funext k\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k <;> cases k <;> rfl\n  have h1 : Runs program 1 (ctl .secondTag) (input (false::frame word tail) cached)\n      (ctl .fieldCall) (beforeField word tail cached) := by\n    apply one_base program (ctl .secondTag) (ctl .fieldCall)\n      (.pop inputCode (ctl .bad) (ctl .fieldCall) (ctl .bad)) _ _ rfl\n    · rfl\n    · funext k\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k <;> cases k <;> rfl\n  exact runs_trans program 1 1 _ _ _ _ _ _ h0 h1\n\n/-- The actual field call acquires the payload and flag while preserving the\nphysical template and entire code suffix. No supplied split or verdict is used. -/\ntheorem field_call (word tail cached : List Bool) :\n    Runs program (8*word.length+7) (ctl .fieldCall) (beforeField word tail cached)\n      (ctl .checkValid) (parsed word tail cached) := by\n  apply included_call program fieldStack fieldLabel fieldStack_injective Field.code\n    (Field.active .tagPop (none,false)) (fun _=>rfl) (ctl .fieldCall) (ctl .checkValid) rfl\n    (8*word.length+6) (Field.initial (frame word tail) [])\n    (⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word)\n      (fun _=>[true])⟩:SemiprimeD1StackBytecode.State Field.Stack Field.Label)\n    (beforeField word tail cached) (parsed word tail cached)\n  · rfl\n  · rfl\n  · exact SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> rfl\n      · cases k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> rfl\n      · cases k;rfl\n    · intro k hk\n      rcases k with k|k\n      · fin_cases k <;> first | rfl | exact False.elim (hk (.inl .output) rfl)\n      · rcases k with k|k\n        · cases k;exact False.elim (hk (.inl .input) rfl)\n        · cases k;exact False.elim (hk (.inr ()) rfl)\n\n/-- The parser's actual true flag is popped before entering arithmetic. -/\ntheorem check_flag (word tail cached : List Bool) :\n    Runs program 1 (ctl .checkValid) (parsed word tail cached)\n      (ctl .fitCall) (beforeFit word tail cached) := by\n  apply one_base program (ctl .checkValid) (ctl .fitCall)\n    (.pop valid (ctl .bad) (ctl .bad) (ctl .fitCall)) _ _ rfl\n  · rfl\n  · funext k\n    rcases k with k|k\n    · rfl\n    · rcases k with k|k <;> cases k <;> rfl\n\n/-- The real nested fitter consumes the acquired payload and preserves every\nunmapped suffix/flag cell. Its template is the ACTUAL cached physical word. -/\ntheorem fit_call (word tail cached : List Bool) :\n    Runs program (SemiprimeD1StackWordFitExecution.totalTime word cached+1)\n      (ctl .fitCall) (beforeFit word tail cached) (ctl .done) (finalData word tail cached) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program Sum.inl fitLabel Sum.inl_injective\n    Fit.program .start (fun _=>rfl) (ctl .fitCall) (ctl .done) rfl\n    (SemiprimeD1StackWordFitExecution.totalTime word cached) (Fit.initial word cached)\n    (SemiprimeD1StackWordFitExecution.done word cached) (beforeFit word tail cached) (finalData word tail cached)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackWordFitExecution.source_run word cached\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · exact False.elim (hk k rfl)\n      · rfl\n\n/-- Reusable literal-body count, with the real final halt included. -/\ndef readyTime (word cached : List Bool) : ℕ :=\n  (8*word.length+7)+1+(SemiprimeD1StackWordFitExecution.totalTime word cached+1)+1\n/-- Whole literal count also pays the two original constructor-tag reads. -/\ndef totalTime (word cached : List Bool) : ℕ := 2+readyTime word cached\n\n/-- Reusable completed literal body for a larger fixed recursive evaluator. -/\ntheorem ready (word tail cached : List Bool) :\n    Runs program ((8*word.length+7)+1+(SemiprimeD1StackWordFitExecution.totalTime word cached+1))\n      (ctl .fieldCall) (beforeField word tail cached) (ctl .done) (finalData word tail cached) :=\n  runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _ (field_call word tail cached) (check_flag word tail cached))\n    (fit_call word tail cached)\n\n/-- Actual balanced source trace from an already-dispatched literal field. This\nentry lets the whole evaluator share the original tag-dispatch instructions. -/\ntheorem ready_run (word tail cached : List Bool) :\n    C.run program (readyTime word cached)\n      (⟨some (ctl .fieldCall),none,none,beforeField word tail cached,[]⟩:C.State Stack Label)=\n      some (done word tail cached) := by\n  obtain ⟨finish,hf,ho⟩:=ready word tail cached []\n    (⟨some (ctl .fieldCall),none,none,beforeField word tail cached,[]⟩:C.State Stack Label) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (finalData word tail cached) [] finish ho\n  rw [readyTime,SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some,hh]\n  rfl\n\n/-- The encoded input is physically read to acquire and evaluate its literal.\nThe AST appears only in the proof-side specification of those supplied bytes. -/\ntheorem source_run (word tail cached : List Bool) :\n    C.run program (totalTime word cached)\n      (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached)=some (done word tail cached) := by\n  have h:=runs_trans program _ _ _ _ _ _ _ _ (tags_run word tail cached) (ready word tail cached)\n  obtain ⟨finish,hf,ho⟩:=h []\n    (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (finalData word tail cached) [] finish ho\n  rw [totalTime,readyTime,show 2+((8*word.length+7)+1+\n      (SemiprimeD1StackWordFitExecution.totalTime word cached+1)+1)=\n      (2+((8*word.length+7)+1+(SemiprimeD1StackWordFitExecution.totalTime word cached+1)))+1 by omega,\n    SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some,hh]\n  rfl\n\nend RiemannGaussian.SemiprimeD1StackExprLiteralExecution\n","RiemannGaussian.SemiprimeD1StackFactorScopeFibre":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1FactorScopePairOriginal\n/-! # Actual binary N plus physical factor key to ordered scope-ID vector\nThe complete entry acquires the N-only pair source once. The prepared copy\nentry requires that same source already physically acquired, and preserves it\nfor repeated factors. Query-key acquisition remains a caller operation.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackFactorScopeFibre\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace P\nexport SemiprimeD1StackFactorScopePairs (Stack Label program input initial originalInput aux)\nexport SemiprimeD1StackFactorScopePairExecution (rows result done)\nend P\nnamespace F\nexport SemiprimeD1StackOwnerFibre (Stack Label program initial done records values)\nend F\n/-- All137 actual Boolean roles, including the complete122-role source. -/\nabbrev Stack :=P.Stack⊕(F.Stack⊕Unit)\n/-- Direct inclusion of the complete original-N pair source. -/\ndef sourceStack : P.Stack→Stack :=Sum.inl\n/-- Direct inclusion of the generic physical numeric-key filter. -/\ndef fibreStack (k : F.Stack) : Stack :=.inr (.inl k)\n/-- Literal preserving-copy scratch, independent of both actual sources. -/\ndef scratch : Stack :=.inr (.inr ())\n/-- Original binary N input role. -/\ndef originalInput : Stack :=sourceStack P.originalInput\n/-- Retained actual factor-key/scope-ID pair catalogue. -/\ndef pairsOutput : Stack :=sourceStack (P.aux .output)\n/-- Physical current factor key; its encoding/acquisition is the caller's work. -/\ndef query : Stack :=fibreStack (.inr .query)\n/-- Actual selected scope-ID vector, in original ascending local-port order. -/\ndef output : Stack :=fibreStack (.inr .output)\n/-- Source-preserving copy from retained pairs to the actual generic filter reader. -/\ndef copyStack (k : Fin 3) : Stack :=\n  if k=0 then pairsOutput else if k=1 then fibreStack (.inr .reader) else scratch\n/-- Fixed complete and prepared entries, with no original count/ordinal in control. -/\ninductive Label where\n  | main | copy | filter | done\n  | source (pc : P.Label) | fibre (pc : F.Label) | copyCode (pc : Fin 9)\n  deriving Fintype\n/-- Actual source call, preserving reader copy, generic filter call and halt. -/\ndef program : Label→C.Instruction Stack Label\n  | .main=>.call (.source (.local .main)) .copy\n  | .copy=>.call (.copyCode 0) .filter\n  | .filter=>.call (.fibre .loop) .done\n  | .done=>.base .halt\n  | .source pc=>SemiprimeD1StackValidationLink.instruction sourceStack Label.source (P.program pc)\n  | .fibre pc=>SemiprimeD1StackValidationLink.instruction fibreStack Label.fibre (F.program pc)\n  | .copyCode pc=>SemiprimeD1StackMultiplierLink.instruction copyStack Label.copyCode (SemiprimeD1StackCopy.code pc)\n/-- Complete two-component physical store, with the actual extra scratch empty. -/\ndef data (source : P.Stack→List Bool) (fibre : F.Stack→List Bool) : Stack→List Bool :=\n  Sum.elim source (Sum.elim fibre (fun _=>[]))\n/-- Only binary N and an actually acquired physical factor-key word enter. -/\ndef initial (bits key : List Bool) : C.State Stack Label :=\n  ⟨some .main,none,none,data (P.input bits) (F.initial key []).data,[]⟩\n/-- Genuine prepared entry AFTER the entire actual N-only pair acquisition. -/\ndef afterSource (bits key : List Bool) : Stack→List Bool :=data (P.result bits) (F.initial key []).data\n/-- Mathematical exact retained pair bytes, not a runtime catalogue supplier. -/\ndef pairTape (bits : List Bool) : List Bool :=F.records ((P.rows bits).map SemiprimeD1FactorScopePairEncoding.pair) []\n/-- The preserving copy has physically acquired the generic filter's reader. -/\ndef afterCopy (bits key : List Bool) : Stack→List Bool :=data (P.result bits) (F.initial key (pairTape bits)).data\n/-- Every original source/cache byte and the physical query survive filtering. -/\ndef result (bits key : List Bool) : Stack→List Bool :=\n  data (P.result bits) (F.done key ((P.rows bits).map SemiprimeD1FactorScopePairEncoding.pair) []).data\n/-- Actual final flags and real return frames are cleared. -/\ndef done (bits key : List Bool) : C.State Stack Label :=⟨none,none,none,result bits key,[]⟩\n/-- One fixed finite machine before every original input and factor key. -/\ndef machine : Turing.FinTM2 :=SemiprimeD1StackCalls.machine originalInput output .main program\n/-- Every source, filter and scratch role is included. -/\ntheorem stack_card : Fintype.card Stack=137 :=by decide\n/-- The literal copy uses three disjoint actual physical roles. -/\ntheorem copy_injective : Function.Injective copyStack :=by decide\nend RiemannGaussian.SemiprimeD1StackFactorScopeFibre\n","RiemannGaussian.SemiprimeD1StackFermatConstants":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackTransformBounds\nimport RiemannGaussian.SemiprimeD1StackValidationLink\nimport RiemannGaussian.SemiprimeD1StackFermatWords\n\n/-! # Original-input physical Fermat constant production\nActual metadata R/E counters are acquired by the real nested-call transform\nprogram. Literal copy/pop/push loops write modulus and normalizer bit patterns;\nno native power, negation, modulo or encoded constant answer is executed.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackFermatConstants\nnamespace Meta\nexport SemiprimeD1StackTransform (Stack Label program input initial)\nend Meta\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run)\nend B\nnamespace LinkB\nexport SemiprimeD1StackMultiplierLink (instruction DataRel data_unique Rel run_rel)\nend LinkB\nnamespace LinkC\nexport SemiprimeD1StackValidationLink (instruction Rel run_rel)\nend LinkC\n\n/-- Original metadata stacks plus two actual constant-word outputs. -/\nabbrev Stack := Meta.Stack⊕Bool\n\n/-- Fixed finite local constant-producing control. -/\ninductive Local where\n  | start | modStart | modDrop | modHigh | modLoop | modZero | modLow\n  | normStart | normDrop | normCopyE | normLoop | normOne | normSubR\n  | normZeros | normZero | normLow | halt | bad\n  deriving DecidableEq,Repr\n/-- Literal finite local-label catalogue. -/\ninstance : Fintype Local where\n  elems:={.start,.modStart,.modDrop,.modHigh,.modLoop,.modZero,.modLow,.normStart,.normDrop,\n    .normCopyE,.normLoop,.normOne,.normSubR,.normZeros,.normZero,.normLow,.halt,.bad}\n  complete:=by intro k;cases k <;> simp\n\n/-- Fixed local, actual metadata and actual Copy instruction labels. -/\nabbrev Label := Local⊕(Meta.Label⊕(Bool×Fin 9))\n\n/-- Actual metadata label inclusion retains all nested source calls. -/\ndef metaLabel (pc:Meta.Label) : Label := .inr (.inl pc)\n/-- Literal source operand of the two included Copy procedures. -/\ndef copyInput (mode:Bool) : Stack := .inl (if mode then .exponent else .radius)\n/-- Literal destination work stack for R or E. -/\ndef copyOutput (mode:Bool) : Stack := .inl (if mode then .thresholdWork else .squareWork)\n/-- Actual Copy operands, using the retained metadata's empty temporary. -/\ndef copyStack (mode:Bool) (k:Fin 3) : Stack :=\n  if k=0 then copyInput mode else if k=1 then copyOutput mode else .inl .temporary\n/-- Literal included Copy control labels. -/\ndef copyLabel (mode:Bool) (pc:Fin 9) : Label := .inr (.inr (mode,pc))\n\n/-- Complete fixed original-input program, including metadata itself and real constant-word loops. -/\ndef program : Label→C.Instruction Stack Label\n  | .inr (.inl pc) => LinkC.instruction Sum.inl metaLabel (Meta.program pc)\n  | .inr (.inr (mode,pc)) => LinkB.instruction (copyStack mode) (copyLabel mode) (SemiprimeD1StackCopy.code pc)\n  | .inl .start => .call (metaLabel (.inl .start)) (.inl .modStart)\n  | .inl .modStart => .call (copyLabel false 0) (.inl .modDrop)\n  | .inl .modDrop => .base (.pop (.inl .squareWork) (.inl .bad) (.inl .modHigh) (.inl .modHigh))\n  | .inl .modHigh => .base (.push (.inr false) true (.inl .modLoop))\n  | .inl .modLoop => .base (.pop (.inl .squareWork) (.inl .modLow) (.inl .modZero) (.inl .modZero))\n  | .inl .modZero => .base (.push (.inr false) false (.inl .modLoop))\n  | .inl .modLow => .base (.push (.inr false) true (.inl .normStart))\n  | .inl .normStart => .call (copyLabel false 0) (.inl .normDrop)\n  | .inl .normDrop => .base (.pop (.inl .squareWork) (.inl .bad) (.inl .normCopyE) (.inl .normCopyE))\n  | .inl .normCopyE => .call (copyLabel true 0) (.inl .normLoop)\n  | .inl .normLoop => .base (.pop (.inl .thresholdWork) (.inl .normZeros) (.inl .normOne) (.inl .normOne))\n  | .inl .normOne => .base (.push (.inr true) true (.inl .normSubR))\n  | .inl .normSubR => .base (.pop (.inl .squareWork) (.inl .bad) (.inl .normLoop) (.inl .normLoop))\n  | .inl .normZeros => .base (.pop (.inl .squareWork) (.inl .normLow) (.inl .normZero) (.inl .normZero))\n  | .inl .normZero => .base (.push (.inr true) false (.inl .normZeros))\n  | .inl .normLow => .base (.push (.inr true) true (.inl .halt))\n  | .inl .halt => .base .halt\n  | .inl .bad => .base .halt\n\n/-- One fixed original-input finite machine, before every binary N. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (.inl .input) (.inr true) (.inl .start) program\n\n/-- Only the original binary input is initialized; no metadata/constant word is preloaded. -/\ndef input (bits:List Bool) : Stack→List Bool := Sum.elim (Meta.input bits) (fun _=>[])\n/-- Actual no-continuation original-input start. -/\ndef initial (bits:List Bool) : C.State Stack Label := ⟨some (.inl .start),none,none,input bits,[]⟩\n\n/-- Both Copy inclusions use distinct actual operands. -/\ntheorem copyStack_injective (mode:Bool) : Function.Injective (copyStack mode) := by\n  cases mode <;> decide\n/-- All original metadata and output data stacks are fixed before input. -/\ntheorem stack_card : Fintype.card Stack=13 := by decide\n/-- All metadata/local/copy labels total135 before every input. -/\ntheorem label_card : Fintype.card Label=135 := by decide\n/-- Every stack alphabet is finite, including the fixed real return-tag alphabet. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (.inl .input) (.inr true) (.inl .start) program\nend RiemannGaussian.SemiprimeD1StackFermatConstants\n","RiemannGaussian.SemiprimeD1StackFermatLocal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFermatComponents\n\n/-! # Actual constant-word bit loops\nAll emitted bits are literal pushes. The retained metadata are untouched; work\ncounters are consumed one physical cell at a time, including every EOF test.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackFermatLocal\nopen SemiprimeD1StackFermatConstants SemiprimeD1StackFermatComponents\nopen SemiprimeD1StackProcedureFragments (At Runs one_base)\n\n/-- Two real instructions consume one radius marker and write one modulus zero. -/\ntheorem mod_zero_bit (base:Meta.Stack→List Bool) (rw ew tmp modulus normalizer:List Bool) :\n    Runs program 2 (.inl .modLoop) (data base (true::rw) ew tmp modulus normalizer)\n      (.inl .modLoop) (data base rw ew tmp (false::modulus) normalizer) := by\n  have h0:Runs program 1 (.inl .modLoop) (data base (true::rw) ew tmp modulus normalizer)\n      (.inl .modZero) (data base rw ew tmp modulus normalizer):=by\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl .modLow) (.inl .modZero) (.inl .modZero)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .modZero) (data base rw ew tmp modulus normalizer)\n      (.inl .modLoop) (data base rw ew tmp (false::modulus) normalizer):=by\n    apply one_base program _ _ (.push (.inr false) false (.inl .modLoop)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  exact h0.trans (h1)\n\n/-- Two real instructions consume one residual radius marker and write one inverse zero. -/\ntheorem norm_zero_bit (base:Meta.Stack→List Bool) (rw ew tmp modulus normalizer:List Bool) :\n    Runs program 2 (.inl .normZeros) (data base (true::rw) ew tmp modulus normalizer)\n      (.inl .normZeros) (data base rw ew tmp modulus (false::normalizer)) := by\n  have h0:Runs program 1 (.inl .normZeros) (data base (true::rw) ew tmp modulus normalizer)\n      (.inl .normZero) (data base rw ew tmp modulus normalizer):=by\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl .normLow) (.inl .normZero) (.inl .normZero)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .normZero) (data base rw ew tmp modulus normalizer)\n      (.inl .normZeros) (data base rw ew tmp modulus (false::normalizer)):=by\n    apply one_base program _ _ (.push (.inr true) false (.inl .normZeros)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  exact h0.trans (h1)\n\n/-- Three real instructions consume E/R markers and write one high inverse bit. -/\ntheorem norm_pair (base:Meta.Stack→List Bool) (rw ew tmp modulus normalizer:List Bool) :\n    Runs program 3 (.inl .normLoop) (data base (true::rw) (true::ew) tmp modulus normalizer)\n      (.inl .normLoop) (data base rw ew tmp modulus (true::normalizer)) := by\n  have h0:Runs program 1 (.inl .normLoop) (data base (true::rw) (true::ew) tmp modulus normalizer)\n      (.inl .normOne) (data base (true::rw) ew tmp modulus normalizer):=by\n    apply one_base program _ _ (.pop (.inl .thresholdWork) (.inl .normZeros) (.inl .normOne) (.inl .normOne)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .normOne) (data base (true::rw) ew tmp modulus normalizer)\n      (.inl .normSubR) (data base (true::rw) ew tmp modulus (true::normalizer)):=by\n    apply one_base program _ _ (.push (.inr true) true (.inl .normSubR)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  have h2:Runs program 1 (.inl .normSubR) (data base (true::rw) ew tmp modulus (true::normalizer))\n      (.inl .normLoop) (data base rw ew tmp modulus (true::normalizer)):=by\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl .bad) (.inl .normLoop) (.inl .normLoop)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  exact h0.trans (h1.trans (h2))\n\n/-- All modulus gap zeros are physically emitted, including the terminal EOF test. -/\ntheorem mod_zeros (n:ℕ) (base:Meta.Stack→List Bool) (ew tmp modulus normalizer:List Bool) :\n    Runs program (2*n+1) (.inl .modLoop) (data base (List.replicate n true) ew tmp modulus normalizer)\n      (.inl .modLow) (data base [] ew tmp (List.replicate n false++modulus) normalizer) := by\n  induction n generalizing modulus with\n  | zero =>\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl .modLow) (.inl .modZero) (.inl .modZero)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  | succ n ih =>\n    have h:=(mod_zero_bit base (List.replicate n true) ew tmp modulus normalizer).trans (ih (false::modulus))\n    have hd:List.replicate n false++false::modulus=List.replicate (n+1) false++modulus:=by\n      rw [List.replicate_succ',List.append_assoc,List.singleton_append]\n    rw [hd] at h\n    simpa only [List.replicate_succ,show 2+(2*n+1)=2*(n+1)+1 by omega] using h\n\n/-- All normalizer low gap zeros are physically emitted after the actual high-one loop. -/\ntheorem norm_zeros (n:ℕ) (base:Meta.Stack→List Bool) (ew tmp modulus normalizer:List Bool) :\n    Runs program (2*n+1) (.inl .normZeros) (data base (List.replicate n true) ew tmp modulus normalizer)\n      (.inl .normLow) (data base [] ew tmp modulus (List.replicate n false++normalizer)) := by\n  induction n generalizing normalizer with\n  | zero =>\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl .normLow) (.inl .normZero) (.inl .normZero)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  | succ n ih =>\n    have h:=(norm_zero_bit base (List.replicate n true) ew tmp modulus normalizer).trans (ih (false::normalizer))\n    have hd:List.replicate n false++false::normalizer=List.replicate (n+1) false++normalizer:=by\n      rw [List.replicate_succ',List.append_assoc,List.singleton_append]\n    rw [hd] at h\n    simpa only [List.replicate_succ,show 2+(2*n+1)=2*(n+1)+1 by omega] using h\n\n/-- E high bits and the residual gap are acquired by the actual two-counter cancellation loop. -/\ntheorem norm_pairs (E gap:ℕ) (base:Meta.Stack→List Bool) (tmp modulus normalizer:List Bool) :\n    Runs program (3*E+1) (.inl .normLoop)\n      (data base (List.replicate (E+gap) true) (List.replicate E true) tmp modulus normalizer)\n      (.inl .normZeros) (data base (List.replicate gap true) [] tmp modulus (List.replicate E true++normalizer)) := by\n  induction E generalizing normalizer with\n  | zero =>\n    apply one_base program _ _ (.pop (.inl .thresholdWork) (.inl .normZeros) (.inl .normOne) (.inl .normOne)) _ _ rfl\n    · rfl\n    · funext k;cases k with\n      | inl k => cases k <;> simp [B.execute,data,Function.update]\n      | inr bit => cases bit <;> simp [B.execute,data,Function.update]\n  | succ E ih =>\n    have h:=(norm_pair base (List.replicate (E+gap) true) (List.replicate E true) tmp modulus normalizer).trans\n      (ih (true::normalizer))\n    have hd:List.replicate E true++true::normalizer=List.replicate (E+1) true++normalizer:=by\n      rw [List.replicate_succ',List.append_assoc,List.singleton_append]\n    rw [hd] at h\n    simpa only [Nat.succ_add,List.replicate_succ,show 3+(3*E+1)=3*(E+1)+1 by omega] using h\nend RiemannGaussian.SemiprimeD1StackFermatLocal\n","RiemannGaussian.SemiprimeD1StackFreshBankRestoreBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFreshBankRestoreExecution\n\n/-! # Linear actual Fresh-cache access, including all ninety-five roles and real returns\nThe actual stored heap, counter and issued reference pay for the whole read and\nall eighty-five field parses. No decoded-bank, selected-record-size or address\noracle is a runtime operand or a resource premise.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackFreshBankRestoreBounds\nopen SemiprimeD1StackFreshBankRestore SemiprimeD1StackFreshBankRestoreFields\nopen SemiprimeD1StackFreshBankRestoreExecution\nopen SemiprimeD1StackCalls (run configuration)\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- Total physical input bytes plus one, including the actual issued-reference word. -/\ndef resource (heap counter reference:List Bool) :Nat :=heap.length+counter.length+reference.length+1\n/-- Actual prepared-source input size, not a price assigned to a semantic bank lookup. -/\ndef inputSize (banks:List (F.Stack→List Bool)) (i:Fin banks.length) :Nat :=\n  resource (SemiprimeD1StackHeapAllocate.heapBytes (records banks))\n    (List.replicate banks.length true) (List.replicate i.val true)\n/-- One fixed linear whole-consumer clock from the actual physical input bytes. -/\ndef linearBound (banks:List (F.Stack→List Bool)) (i:Fin banks.length) :Nat :=1000*inputSize banks i\n/-- Generic consecutive field framing has its literal data and delimiter byte count. -/\ntheorem frames_length (ks:List F.Stack) (bank:F.Stack→List Bool) :\n    (ks.foldr (fun k tail=>SemiprimeSourceHistogramKeyBits.frame (bank k) tail) []).length=\n      2*(ks.map (fun k=>(bank k).length)).sum+ks.length :=by\n  induction ks with\n  | nil=>rfl\n  | cons k ks ih=>\n    simp only [List.foldr_cons,SemiprimeSourceHistogramKeyBits.frame_length,ih,\n      List.map_cons,List.sum_cons,List.length_cons]\n    omega\n/-- The complete phase record contains every actual restored word, not just the useful operands. -/\ntheorem record_length (bank:F.Stack→List Bool) :\n    (record bank).length=2*mass bank 0+85 :=by\n  have h:=frames_length I.roles bank\n  simpa only [record,mass,List.drop_zero,I.roles_length] using h\n/-- Any actual stored record's payload is bounded by the complete original allocation history. -/\ntheorem member_mass (rows:List (List Bool)) (word:List Bool) (hw:word∈rows) :\n    word.length ≤ SemiprimeD1StackHeapReadBounds.wordMass rows :=by\n  induction rows with\n  | nil=>simp only [List.not_mem_nil] at hw\n  | cons row rows ih=>\n    rcases List.mem_cons.mp hw with h|h\n    · subst word\n      simp only [SemiprimeD1StackHeapReadBounds.wordMass,List.map_cons,List.sum_cons]\n      omega\n    · have ht:=ih h\n      simp only [SemiprimeD1StackHeapReadBounds.wordMass,List.map_cons,List.sum_cons]\n      unfold SemiprimeD1StackHeapReadBounds.wordMass at ht\n      omega\n/-- Complete selected word mass is paid by the actual physical heap; no selected-size cap is supplied. -/\ntheorem selected_mass_le (banks:List (F.Stack→List Bool)) (i:Fin banks.length) :\n    mass banks[i.val] 0 ≤ (SemiprimeD1StackHeapAllocate.heapBytes (records banks)).length :=by\n  have hm:record banks[i.val]∈records banks:=List.mem_map.mpr ⟨banks[i.val],List.getElem_mem i.isLt,rfl⟩\n  have h:=member_mass (records banks) (record banks[i.val]) hm\n  rw [record_length] at h\n  rw [SemiprimeD1StackHeapReadBounds.heap_length]\n  omega\n/-- The SAME actual dereference/restore trace fits one fixed linear input-byte clock. -/\ntheorem runBound_le (banks:List (F.Stack→List Bool)) (i:Fin banks.length) :\n    runBound banks i ≤ linearBound banks i :=by\n  have hr:=SemiprimeD1StackHeapReadBounds.readTimeAt_le (records banks) (index banks i)\n  have hm:=selected_mass_le banks i\n  have hl:(records banks).length=banks.length:=by simp only [records,List.length_map]\n  have hv:(index banks i).val=i.val:=rfl\n  unfold runBound linearBound inputSize resource\n  simp only [List.length_replicate]\n  omega\n/-- Real whole source execution with its physical-input linear cap. -/\ntheorem source_run_linear (banks:List (F.Stack→List Bool)) (i:Fin banks.length) :\n    ∃q ≤ linearBound banks i,run program q (source banks i)=some (target banks i) :=\n  ⟨runBound banks i,runBound_le banks i,run_exact banks i⟩\n/-- Each initialized word contains only one of the actual three physical input tapes. -/\ntheorem initial_length (heap counter reference:List Bool) (k:Stack) :\n    ((initial heap counter reference).data k).length ≤ resource heap counter reference :=by\n  rcases k with k|k\n  · exact Nat.zero_le _\n  · cases k <;> simp only [initial,data,SemiprimeD1StackHeapRead.input,\n      Sum.elim_inr,List.length_nil,resource] <;> omega\n/-- Successful prefixes cannot pass the SAME program's actual bounded final halt. -/\ntheorem prefix_fuel (banks:List (F.Stack→List Bool)) (i:Fin banks.length)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (source banks i)=some out) :\n    fuel ≤ linearBound banks i :=by\n  have he:=run_exact banks i\n  have hh:run program 1 (target banks i)=none:=rfl\n  have hf:fuel ≤ runBound banks i:=by\n    by_contra hn\n    have h:fuel=runBound banks i+(1+(fuel-(runBound banks i+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hh,Option.bind_none] at hr\n    cases hr\n  exact hf.trans (runBound_le banks i)\n/-- Abstract finite-bank summation avoids reducing any concrete source or cache during elaboration. -/\ntheorem word_sum_le {K:Type} [Fintype K] (words:K→List Bool) (B:Nat)\n    (h:∀k,(words k).length ≤ B) :(∑k:K,(words k).length) ≤ Fintype.card K*B :=by\n  calc\n    _ ≤ ∑_k:K,B:=Finset.sum_le_sum (fun k _=>h k)\n    _= _:=by simp only [Finset.sum_const,Finset.card_univ,smul_eq_mul]\n/-- All ninety-five Boolean data words and every actual return cell are counted at every prefix. -/\ntheorem prefix_cells (banks:List (F.Stack→List Bool)) (i:Fin banks.length)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (source banks i)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤100000*inputSize banks i :=by\n  have hi:∀k,((source banks i).data k).length ≤ inputSize banks i:=\n    initial_length (SemiprimeD1StackHeapAllocate.heapBytes (records banks))\n      (List.replicate banks.length true) (List.replicate i.val true)\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (inputSize banks i) (source banks i) out hi hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel (source banks i) out hr\n  change out.frames.length ≤ 0+fuel at hf\n  have hs:=word_sum_le out.data (inputSize banks i+fuel) hd\n  rw [stack_card] at hs\n  have ht:=prefix_fuel banks i fuel out hr\n  unfold linearBound at ht\n  omega\n/-- Actual compiled finite-machine certificate uses the same physical linear clock. -/\nnoncomputable def restoreBoundedInTime (banks:List (F.Stack→List Bool)) (i:Fin banks.length) :\n    StateTransition.EvalsToInTime machine.step (configuration (source banks i))\n      (some (configuration (target banks i))) (linearBound banks i) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output (ctl .start) program\n  exact ⟨⟨runBound banks i,run_exact banks i⟩,runBound_le banks i⟩\n/-- Every reached compiled configuration counts the complete restored bank and actual return stack. -/\ntheorem machine_prefix_cells (banks:List (F.Stack→List Bool)) (i:Fin banks.length)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (configuration (source banks i)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤100000*inputSize banks i :=by\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output (ctl .start) program fuel (source banks i)\n  have hh:=he.trans hr\n  cases hout:run program fuel (source banks i) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells banks i fuel out hout\n/-- Every actual transition expands into at most four fundamental machine commands. -/\ntheorem compile_depth (pc:Label) :SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤4 :=\n  SemiprimeD1StackCalls.compile_depth (ctl .start) (program pc)\nend RiemannGaussian.SemiprimeD1StackFreshBankRestoreBounds\n","RiemannGaussian.SemiprimeD1StackJetBlocksFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetBlocksView\n/-! # Real coefficient framing and sequential actual/default field reads\nThe real source never changes a coefficient's binary padding or value. EOF is\npeeked and retained while physical rank markers still require default zeros.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackJetBlocksFields\nopen SemiprimeD1StackJetBlocks SemiprimeD1StackJetBlocksPrimitives\nopen SemiprimeD1StackJetBlocksView SemiprimeD1StackJetBlocksEncoding\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => Label.local\n/-- Exact actual single-field emission; all old context/source/loop words are retained. -/\ndef emitAfter (before:Stack→List Bool) (word hist:List Bool) :Stack→List Bool :=\n  Function.update (Function.update before (aux .word) []) (aux .rowHistory) ((Codec.chunk word).reverse++hist)\n/-- One real preserving Frame, true tag, real reverse and physical word cleanup emit exactly one coefficient field. -/\ntheorem emit_field (before:Stack→List Bool) (word hist:List Bool)\n    (hw:before (aux .word)=word) (hh:before (aux .rowHistory)=hist)\n    (hb:before (aux .frameBuffer)=[]) (hs:before (aux .frameScratch)=[]) :\n    Runs program (11*word.length+14) (ctl .frame) before (ctl .inner) (emitAfter before word hist) :=by\n  let b1:=Function.update before (aux .frameBuffer) (frame word [])\n  let b2:=Function.update b1 (aux .frameBuffer) (Codec.chunk word)\n  let b3:=Function.update (Function.update b2 (aux .frameBuffer) []) (aux .rowHistory) ((Codec.chunk word).reverse++hist)\n  have h0:=frame_call before word [] hw hb hs\n  have h1:=push_run .fieldTag (ctl .fieldReverse) (aux .frameBuffer) true b1 rfl\n  have he1:Function.update b1 (aux .frameBuffer) (true::b1 (aux .frameBuffer))=b2:=by\n    simp only [b2,b1,Codec.chunk,Function.update_self,Function.update_idem]\n  rw [he1] at h1\n  have h2:=reverse_call .field .fieldReverse .clearWord rfl b2 (Codec.chunk word) hist\n    (by simp [b2,reverseStack]) (by simpa [b2,b1,reverseStack,aux,Function.update] using hh)\n  have h3:=drain_loop .clearWord (ctl .inner) (aux .word) rfl b3 word\n    (by simpa [b3,b2,b1,aux,Function.update] using hw)\n  have h:=join (join (join h0 h1) h2) h3\n  have he:Function.update b3 (aux .word) []=emitAfter before word hist:=by\n    dsimp only [aux] at hb\n    funext k;rcases k with k|k\n    · rfl\n    · cases k <;> simp [b3,b2,b1,emitAfter,aux,Function.update,hb]\n  rw [he] at h\n  have hl:=Codec.chunk_length word\n  convert h using 1; omega\n/-- Actual non-EOF coefficient read consumes one rank marker, one vector tag and one complete real field. -/\ntheorem real_slot (context:X.Stack→List Bool) (coefficients blocks todo hist history word:List Bool) (words:List (List Bool)) (r:Nat) :\n    Runs program (19*word.length+25) (ctl .inner)\n      (data context coefficients blocks todo (vectorBits (word::words)) (List.replicate (r+1) true) [] hist [] history)\n      (ctl .inner) (data context coefficients blocks todo (vectorBits words) (List.replicate r true) []\n        ((Codec.chunk word).reverse++hist) [] history) :=by\n  let source:=data context coefficients blocks todo (vectorBits (word::words)) (List.replicate (r+1) true) [] hist [] history\n  let b1:=data context coefficients blocks todo (vectorBits (word::words)) (List.replicate r true) [] hist [] history\n  let b2:=data context coefficients blocks todo (frame word (vectorBits words)) (List.replicate r true) [] hist [] history\n  let parsed:=data context coefficients blocks todo (vectorBits words) (List.replicate r true) word hist [] history\n  have h0:Runs program 1 (ctl .inner) source (ctl .peek) b1:=by\n    apply one_base program (ctl .inner) (ctl .peek)\n      (.pop (aux .rankTodo) (ctl .rowSeed) (ctl .abort) (ctl .peek)) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  have h1:Runs program 1 (ctl .peek) b1 (ctl .tag) b1:=by\n    apply one_base program (ctl .peek) (ctl .tag)\n      (.peek (aux .reader) (ctl .frame) (ctl .frame) (ctl .tag)) _ _ rfl\n    · rfl\n    · rfl\n  have h2:Runs program 1 (ctl .tag) b1 (ctl .field) b2:=by\n    apply one_base program (ctl .tag) (ctl .field)\n      (.pop (aux .reader) (ctl .abort) (ctl .abort) (ctl .field)) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  have h3:=field_call .field .valid rfl b2 word (vectorBits words) rfl rfl rfl rfl\n  have he3:Function.update (Function.update (Function.update b2 fieldInput (vectorBits words)) fieldOutput word) (aux .valid) [true]=\n      Function.update parsed (aux .valid) [true]:=by\n    funext k;rcases k with k|k\n    · rfl\n    · cases k <;> simp [b2,parsed,fieldInput,fieldOutput,fieldStack,data,aux,Function.update]\n  rw [he3] at h3\n  have h4:Runs program 1 (ctl .valid) (Function.update parsed (aux .valid) [true]) (ctl .frame) parsed:=by\n    apply one_base program (ctl .valid) (ctl .frame)\n      (.pop (aux .valid) (ctl .abort) (ctl .abort) (ctl .frame)) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  have h5:=emit_field parsed word hist rfl rfl rfl rfl\n  have he5:emitAfter parsed word hist=data context coefficients blocks todo (vectorBits words) (List.replicate r true) []\n      ((Codec.chunk word).reverse++hist) [] history:=by\n    dsimp only [emitAfter,parsed]\n    rw [data_word,data_rowHistory]\n  rw [he5] at h5\n  have h:=join (join (join (join (join h0 h1) h2) h3) h4) h5\n  convert h using 1; omega\n/-- Actual source EOF is peeked rather than consumed; one empty coefficient field still emits for each actual rank marker. -/\ntheorem empty_slot (context:X.Stack→List Bool) (coefficients blocks todo hist history:List Bool) (r:Nat) :\n    Runs program 16 (ctl .inner)\n      (data context coefficients blocks todo (vectorBits []) (List.replicate (r+1) true) [] hist [] history)\n      (ctl .inner) (data context coefficients blocks todo (vectorBits []) (List.replicate r true) []\n        ((Codec.chunk []).reverse++hist) [] history) :=by\n  let source:=data context coefficients blocks todo (vectorBits []) (List.replicate (r+1) true) [] hist [] history\n  let b1:=data context coefficients blocks todo (vectorBits []) (List.replicate r true) [] hist [] history\n  have h0:Runs program 1 (ctl .inner) source (ctl .peek) b1:=by\n    apply one_base program (ctl .inner) (ctl .peek)\n      (.pop (aux .rankTodo) (ctl .rowSeed) (ctl .abort) (ctl .peek)) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  have h1:Runs program 1 (ctl .peek) b1 (ctl .frame) b1:=by\n    apply one_base program (ctl .peek) (ctl .frame)\n      (.peek (aux .reader) (ctl .frame) (ctl .frame) (ctl .tag)) _ _ rfl\n    · rfl\n    · rfl\n  have h2:=emit_field b1 [] hist rfl rfl rfl rfl\n  have he2:emitAfter b1 [] hist=data context coefficients blocks todo (vectorBits []) (List.replicate r true) []\n      ((Codec.chunk []).reverse++hist) [] history:=by\n    dsimp only [emitAfter,b1]\n    rw [data_word,data_rowHistory]\n  rw [he2] at h2\n  exact join (join h0 h1) h2\nend RiemannGaussian.SemiprimeD1StackJetBlocksFields\n","RiemannGaussian.SemiprimeD1StackJetFoldProjection":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetFoldState\n/-! # Literal real-operator bank projections of the111-role fold store -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackJetFoldProjection\nopen SemiprimeD1StackJetFold SemiprimeD1StackJetFoldState\n/-- The actual multiplier operands/caches; no target or coefficient answer is present. -/\ndef cache (v:Values):SemiprimeD1StackJetPointExecution.Cache:=\n  ⟨v .left,v .product,v .axes,v .width,v .rank,[]⟩\n/-- Every dedicated context work/shadow role is empty at an actual fold boundary. -/\ntheorem context_work_empty (v:Values) (k:X.Stack):data v (contextWork k)=[]:=by\n  apply data_other\n  intro s;cases s <;> intro h <;> cases h\n/-- Every dedicated unit work/shadow role is empty at an actual fold boundary. -/\ntheorem unit_work_empty (v:Values) (k:U.Stack):data v (unitWork k)=[]:=by\n  apply data_other\n  intro s;cases s <;> intro h <;> cases h\n/-- Every dedicated addition work/shadow role is empty at an actual fold boundary. -/\ntheorem add_work_empty (v:Values) (k:A.Stack):data v (addWork k)=[]:=by\n  apply data_other\n  intro s;cases s <;> intro h <;> cases h\n/-- The actual full multiplication bank is exactly the frozen clean loop boundary. -/\ntheorem data_main (v:Values) (k:M.Stack):\n    data v (main k)=SemiprimeD1StackJetMulExecution.data (cache v) [] [] (v .result) k:=by\n  fin_cases k <;> first\n    | exact data_get v .axes\n    | exact data_get v .rank\n    | exact data_get v .width\n    | exact data_get v .left\n    | exact data_get v .product\n    | exact data_get v .result\n    | (apply data_other;intro s;cases s <;> decide)\n/-- The actual unit bank has private empty seed operands and the real shared context/product words. -/\ntheorem data_unit (v:Values) (k:U.Stack):\n    data v (unitStack k)=SemiprimeD1StackJetUnit.bank (v .width) (v .rank) [] [] (v .product) k:=by\n  fin_cases k <;> first\n    | exact data_get v .width\n    | exact data_get v .rank\n    | exact data_get v .product\n    | exact unit_work_empty v _\n/-- The actual adder receives the actual product and saved tail sum, with all its work roles empty. -/\ntheorem data_add (v:Values) (k:A.Stack):\n    data v (addStack k)=A.store [] [] [] [] (v .width) [] (v .product) (v .tailSum)\n      (v .rank) [] [] (v .sum) [] [] [] k:=by\n  fin_cases k <;> first\n    | exact data_get v .width\n    | exact data_get v .rank\n    | exact data_get v .product\n    | exact data_get v .tailSum\n    | exact data_get v .sum\n    | exact add_work_empty v _\n/-- Actual context bank view, with physically retained input/rank/precision words and empty private work. -/\ndef contextBank (v:Values):X.Stack→List Bool:=SemiprimeD1StackJetContext.bank (v .axes) (v .precision)\n  (SemiprimeD1StackJetContextExecution.ready (v .rank) [] [])\n  (SemiprimeD1StackAdder.store [] [] [] (v .width))\n/-- The actual context cache aliases all four input/output words and preserves every private empty role. -/\ntheorem data_context (v:Values) (k:X.Stack):data v (contextStack k)=contextBank v k:=by\n  fin_cases k <;> first\n    | exact data_get v .axes\n    | exact data_get v .precision\n    | exact data_get v .rank\n    | exact data_get v .width\n    | exact context_work_empty v _\nend RiemannGaussian.SemiprimeD1StackJetFoldProjection\n","RiemannGaussian.SemiprimeD1StackJetPointExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetPoint\nimport RiemannGaussian.SemiprimeD1StackProcedureInclusion\n\n/-! # Executed component adapters for the physical convolution controller\nThe source of every copy is the actual reached Boolean-stack bank. These lemmas\ncompose real included procedures; none installs a coefficient or routing answer.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxRecDepth 8192\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackJetPointExecution\nopen SemiprimeD1StackJetPoint\nopen SemiprimeD1StackProcedureTrace (Runs one_base runs_trans)\n\n/-- Literal source and target registers of every declared copy are distinct. -/\ntheorem copy_source_ne_target (site : Transfer) : copySource site ≠ copyTarget site := by\n  cases site <;> decide\n/-- Every physical copy scratch register is disjoint from its source. -/\ntheorem copy_source_ne_work (site : Transfer) : copySource site ≠ aux .copyWork := by\n  cases site <;> decide\n/-- Every physical copy scratch register is disjoint from its destination. -/\ntheorem copy_target_ne_work (site : Transfer) : copyTarget site ≠ aux .copyWork := by\n  cases site <;> decide\n\n/-- Real copy-call execution at any of the nine literal controller sites.\nThe source word is read from the actual state; output and scratch emptiness are\nordinary internal loop invariants, not supplied output values or time bounds. -/\ntheorem copy_call (site : Transfer) (pc next : Label) (data : Stack → List Bool)\n    (hcode : program pc=.call (.copy site 0) next)\n    (ht : data (copyTarget site)=[]) (hw : data (aux .copyWork)=[]) :\n    Runs program (5*(data (copySource site)).length+4) pc data next\n      (Function.update data (copyTarget site) (data (copySource site))) := by\n  let word:=data (copySource site)\n  let result:=Function.update data (copyTarget site) word\n  have hst:=copy_source_ne_target site\n  have hsw:=copy_source_ne_work site\n  have htw:=copy_target_ne_work site\n  apply SemiprimeD1StackProcedureTrace.included_call program (copyStack site) (Label.copy site)\n    (copyStack_injective site) SemiprimeD1StackCopy.code (0:Fin 9) (fun _=>rfl)\n    pc next hcode (5*word.length+3) (SemiprimeD1StackCopy.state 0 none word [] [])\n    (SemiprimeD1StackCopy.done word word) data result\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words word [] none\n  · constructor\n    · intro k\n      fin_cases k <;> simp [copyStack,SemiprimeD1StackCopy.state,SemiprimeD1StackCopy.payload,word,ht,hw]\n    · intro k hk\n      rfl\n  · constructor\n    · intro k\n      fin_cases k <;> simp [copyStack,SemiprimeD1StackCopy.done,SemiprimeD1StackCopy.payload,\n        result,word,Function.update_of_ne hst,Function.update_of_ne htw.symm,hw]\n    · intro k hk\n      have hn : k ≠ copyTarget site := fun he=>hk 1 (by simpa [copyStack] using he.symm)\n      exact Function.update_of_ne hn _ _\n\n/-- Physical persistent tapes at the coefficient-controller boundary. -/\nstructure Cache where\n  /-- Original first encoded coefficient vector. -/\n  a : List Bool\n  /-- Original second encoded coefficient vector. -/\n  b : List Bool\n  /-- Original physically encoded positive axes. -/\n  axes : List Bool\n  /-- Retained physical precision marker counter. -/\n  width : List Bool\n  /-- Retained physically acquired rank marker counter. -/\n  rank : List Bool\n  /-- Retained physical output-index marker counter. -/\n  target : List Bool\n\n/-- Clean loop invariant: only actual cached tapes, counters and accumulator live. -/\ndef resting (c : Cache) (i j acc : List Bool) : Stack → List Bool\n  | .inr (.inl (.inr false)) => c.width\n  | .inr (.inr (.inr .a)) => c.a\n  | .inr (.inr (.inr .b)) => c.b\n  | .inr (.inr (.inr .axes)) => c.axes\n  | .inr (.inr (.inr .rank)) => c.rank\n  | .inr (.inr (.inr .i)) => i\n  | .inr (.inr (.inr .j)) => j\n  | .inr (.inr (.inr .target)) => c.target\n  | .inr (.inr (.inr .acc)) => acc\n  | _ => []\n\n/-- The actual two reader outputs occupy the real multiplier's input registers. -/\ndef loaded (c : Cache) (i j acc left right : List Bool) : Stack → List Bool :=\n  Function.update (Function.update (resting c i j acc)\n    (mulStack (.inl SemiprimeD1StackMultiplier.input)) left)\n    (mulStack (.inl SemiprimeD1StackMultiplier.factor)) right\n\n/-- The literal multiplier inclusion has disjoint registers. -/\ntheorem mulStack_injective : Function.Injective mulStack := by\n  intro a b h\n  simpa only [mulStack,Sum.inr.injEq,Sum.inl.injEq] using h\n\n/-- Both cached vector reads feed the actual nested multiplier/reducer; no\nnative product or coefficient answer is supplied to the executed procedure. -/\ntheorem multiply_call (c : Cache) (i j acc left right : List Bool) :\n    Runs program (SemiprimeD1StackJetScalarMulExecution.totalTime left right c.width+1)\n      .multiply (loaded c i j acc left right) .add\n      (Function.update (resting c i j acc) product\n        (SemiprimeD1StackJetScalarMulExecution.result left right c.width)) := by\n  apply SemiprimeD1StackProcedureInclusion.included_call program mulStack Label.scalarMul\n    mulStack_injective SemiprimeD1StackJetScalarMul.program .start (fun _=>rfl)\n    .multiply .add rfl _\n    (SemiprimeD1StackJetScalarMul.state (some .start) none none left right [] [] [] [] [] [] [] c.width [])\n    (SemiprimeD1StackJetScalarMul.state none none none [] [] [] [] [] []\n      (SemiprimeD1StackJetScalarMulExecution.result left right c.width) [] [] c.width [])\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackJetScalarMulExecution.source_run left right c.width\n  · constructor\n    · intro k\n      rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> simp [loaded,resting,mulStack,SemiprimeD1StackJetScalarMul.state,\n            SemiprimeD1StackJetScalarMul.store,SemiprimeD1StackMultiplier.payload,\n            SemiprimeD1StackMultiplier.input,SemiprimeD1StackMultiplier.factor]\n        · rcases k with k|k\n          · fin_cases k <;> rfl\n          · cases k <;> rfl\n      · cases k <;> rfl\n    · intro k hk\n      rfl\n  · constructor\n    · intro k\n      rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> simp [resting,mulStack,product,SemiprimeD1StackJetScalarMul.reduceStack,\n            SemiprimeD1StackJetScalarMul.state,SemiprimeD1StackJetScalarMul.store,\n            SemiprimeD1StackMultiplier.payload]\n        · rcases k with k|k\n          · fin_cases k <;> rfl\n          · cases k <;> rfl\n      · cases k <;> rfl\n    · intro k hk\n      rcases k with k|k\n      · cases k <;> rfl\n      · rcases k with k|k\n        · exact False.elim (hk k rfl)\n        · rcases k with k|k\n          · cases k <;> rfl\n          · cases k <;> rfl\n\n/-- Outside its declared accumulator register the clean invariant is unchanged. -/\ntheorem resting_acc_other (c : Cache) (i j a b : List Bool) (k : Stack)\n    (hk : k ≠ aux .acc) : resting c i j a k=resting c i j b k := by\n  rcases k with k|k\n  · cases k <;> rfl\n  · rcases k with k|k\n    · rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n    · rcases k with k|k\n      · cases k <;> rfl\n      · cases k <;> first | rfl | exact False.elim (hk rfl)\n\n/-- The acquired product is consumed by the actual modular adder, preserving\nall persistent cached input bytes and clearing both binary operands. -/\ntheorem add_call (c : Cache) (i j acc word : List Bool) :\n    Runs program (SemiprimeD1StackJetScalarAddExecution.totalTime word acc c.width+1)\n      .add (Function.update (resting c i j acc) product word) .retain\n      (Function.update (resting c i j []) newAcc\n        (SemiprimeD1StackJetScalarAddExecution.result word acc c.width)) := by\n  apply SemiprimeD1StackProcedureInclusion.included_call program addStack Label.scalarAdd\n    addStack_injective SemiprimeD1StackJetScalarAdd.program .start (fun _=>rfl)\n    .add .retain rfl _\n    (SemiprimeD1StackJetScalarAdd.state (some .start) none none word acc [] [] c.width [])\n    (SemiprimeD1StackJetScalarAdd.state none none none [] [] []\n      (SemiprimeD1StackJetScalarAddExecution.result word acc c.width) c.width [])\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackJetScalarAddExecution.source_run word acc c.width\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> simp [addStack,product,newAcc,addBank,aux,resting,mulStack,SemiprimeD1StackJetScalarMul.reduceStack,\n          SemiprimeD1StackJetScalarAdd.state,SemiprimeD1StackJetScalarAdd.store]\n      · cases k <;> rfl\n    · intro k hk\n      rfl\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> simp [addStack,product,newAcc,addBank,aux,resting,mulStack,SemiprimeD1StackJetScalarMul.reduceStack,\n          SemiprimeD1StackJetScalarAdd.state,SemiprimeD1StackJetScalarAdd.store]\n      · cases k <;> rfl\n    · intro k hk\n      have hprod : k ≠ product := fun he=>hk (.inl .left) he.symm\n      have hnew : k ≠ newAcc := fun he=>hk (.inl .output) he.symm\n      have hacc : k ≠ aux .acc := fun he=>hk (.inl .right) he.symm\n      rw [Function.update_of_ne hnew,Function.update_of_ne hprod]\n      exact resting_acc_other c i j [] acc k hacc\n\n/-- Clearing the real temporary sum consumes every physical output cell. -/\ntheorem clear_new (data : Stack → List Bool) (he : data newAcc=[]) (word : List Bool) :\n    Runs program (word.length+1) .clearNew (Function.update data newAcc word) .inner data := by\n  induction word with\n  | nil =>\n    have hd : Function.update data newAcc []=data := by\n      rw [←he,Function.update_eq_self]\n    rw [hd]\n    apply one_base program .clearNew .inner (.pop newAcc .inner .clearNew .clearNew) data data rfl\n    · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose,he]\n    · simpa only [SemiprimeD1StackBytecode.execute,he,List.tail_nil] using hd\n  | cons bit word ih =>\n    have hs : Runs program 1 .clearNew (Function.update data newAcc (bit::word)) .clearNew\n        (Function.update data newAcc word) := by\n      apply one_base program .clearNew .clearNew (.pop newAcc .inner .clearNew .clearNew) _ _ rfl\n      · cases bit <;> simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose]\n      · simp [SemiprimeD1StackBytecode.execute]\n    have hh:=runs_trans program _ _ _ _ _ _ _ _ hs ih\n    simpa only [List.length_cons,Nat.add_comm,Nat.add_left_comm,Nat.add_assoc] using hh\n\n/-- Literal accumulator replacement in the clean physical state. -/\ntheorem resting_acc_update (c : Cache) (i j a b : List Bool) :\n    Function.update (resting c i j a) (aux .acc) b=resting c i j b := by\n  funext k\n  by_cases hk : k=aux .acc\n  · subst k\n    rfl\n  · rw [Function.update_of_ne hk]\n    exact resting_acc_other c i j a b k hk\n\n/-- Actual copyback and temporary cleanup, with no silently discarded result. -/\ntheorem retain_call (c : Cache) (i j word : List Bool) :\n    Runs program (6*word.length+5) .retain\n      (Function.update (resting c i j []) newAcc word) .inner (resting c i j word) := by\n  have hcopy:=copy_call .accumulator .retain .clearNew\n    (Function.update (resting c i j []) newAcc word) rfl (by rfl) (by rfl)\n  have hsource : (Function.update (resting c i j []) newAcc word) (copySource .accumulator)=word := rfl\n  rw [hsource] at hcopy\n  have hne : newAcc ≠ aux .acc := by decide\n  have hdata : Function.update (Function.update (resting c i j []) newAcc word) (copyTarget .accumulator) word=\n      Function.update (resting c i j word) newAcc word := by\n    change Function.update (Function.update (resting c i j []) newAcc word) (aux .acc) word=_\n    rw [Function.update_comm hne,resting_acc_update]\n  rw [hdata] at hcopy\n  have hclear:=clear_new (resting c i j word) (by rfl) word\n  have hh:=runs_trans program _ _ _ _ _ _ _ _ hcopy hclear\n  simpa only [show (5*word.length+4)+(word.length+1)=6*word.length+5 by omega] using hh\n\n/-- Exact retained transition count of the linked binary arithmetic path. -/\ndef pipelineTime (left right acc width : List Bool) : ℕ :=\n  let product:=SemiprimeD1StackJetScalarMulExecution.result left right width\n  let sum:=SemiprimeD1StackJetScalarAddExecution.result product acc width\n  (SemiprimeD1StackJetScalarMulExecution.totalTime left right width+1)+\n    (SemiprimeD1StackJetScalarAddExecution.totalTime product acc width+1)+(6*sum.length+5)\n\n/-- Complete actual product/sum/copyback path inside the coefficient loop.\nEvery arithmetic result is obtained from its literal linked finite procedure. -/\ntheorem pipeline_run (c : Cache) (i j acc left right : List Bool) :\n    Runs program (pipelineTime left right acc c.width) .multiply (loaded c i j acc left right) .inner\n      (resting c i j (SemiprimeD1StackJetScalarAddExecution.result\n        (SemiprimeD1StackJetScalarMulExecution.result left right c.width) acc c.width)) := by\n  exact runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _ (multiply_call c i j acc left right)\n      (add_call c i j acc (SemiprimeD1StackJetScalarMulExecution.result left right c.width)))\n    (retain_call c i j _)\n\n/-- A fixed polynomial for every executed binary arithmetic path. -/\ndef pipelineBudget (left right acc precision : ℕ) : ℕ :=\n  2000*(left+right+precision+3)^3+30*(2*precision+acc+2)+6*precision+7\n\n/-- The concrete linked scalar path has no external clock or fit premise. -/\ntheorem pipelineTime_le (left right acc width : List Bool) :\n    pipelineTime left right acc width ≤ pipelineBudget left.length right.length acc.length width.length := by\n  have hm:=SemiprimeD1StackJetScalarMulExecution.totalTime_le left right width\n  have hc:=SemiprimeD1StackJetScalarMulExecution.timeBound_le_cube left.length right.length width.length\n  have ha:=SemiprimeD1StackJetScalarAddExecution.totalTime_le\n    (SemiprimeD1StackJetScalarMulExecution.result left right width) acc width\n  have hp : (SemiprimeD1StackJetScalarMulExecution.result left right width).length ≤ width.length :=\n    SemiprimeD1JetScalarBits.mul_length _ _ _\n  have hs : (SemiprimeD1StackJetScalarAddExecution.result\n      (SemiprimeD1StackJetScalarMulExecution.result left right width) acc width).length ≤ width.length :=\n    SemiprimeD1JetScalarBits.add_length _ _ _\n  unfold SemiprimeD1StackJetScalarAddExecution.timeBound at ha\n  dsimp only [pipelineTime,pipelineBudget]\n  omega\n\nend RiemannGaussian.SemiprimeD1StackJetPointExecution\n","RiemannGaussian.SemiprimeD1StackJetRead":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1TensorTapeCodec\nimport RiemannGaussian.SemiprimeD1JetRingBits\n\n/-! # Physical cached coefficient-vector lookup\nA real copy preserves the encoded cache. A physical unary index drives actual\nfield parses and clears. Coefficient payload is always binary; no getter opcode\nor selected-word supplier occurs in the fixed program.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackJetRead\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace Field\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active initial framed_run)\nend Field\n\n/-- Eight literal Boolean stacks; the index word's physical length is its index. -/\ninductive Stack where\n  | cache | reader | index | parser | skipped | output | valid | copy\n  deriving DecidableEq,Repr\n\n/-- Constant stack enumeration before every vector and index input. -/\ninstance : Fintype Stack := Fintype.ofList [.cache,.reader,.index,.parser,.skipped,.output,.valid,.copy]\n  (by intro k; cases k <;> simp)\n\n/-- Literal cache-copy mapping. -/\ndef copyStack (k : Fin 3) : Stack := if k=0 then .cache else if k=1 then .reader else .copy\n\n/-- Literal field-parser instance; skipped words are actually materialized then cleared. -/\ndef fieldStack (skip : Bool) : Field.Stack → Stack\n  | .inl .input => .reader\n  | .inl .scratch => .parser\n  | .inl .output => if skip then .skipped else .output\n  | .inr _ => .valid\n\n/-- Distinct actual copy stacks. -/\ntheorem copyStack_injective : Function.Injective copyStack := by decide\n\n/-- Distinct actual parser stacks. -/\ntheorem fieldStack_injective (skip : Bool) : Function.Injective (fieldStack skip) := by\n  intro i j h\n  cases skip <;> rcases i with i|i <;> rcases j with j|j <;>\n    cases i <;> cases j <;> simp_all [fieldStack]\n\n/-- Fixed physical index/control and literal procedure labels. -/\ninductive Label where\n  | start | loop | skipTag | selectTag | callSkip | skipParsed | clearSkipped\n  | callTake | takeParsed | clearInput | clearIndex | done | abort\n  | copy (pc : Fin 9)\n  | field (skip : Bool) (pc : Field.Label)\n  deriving DecidableEq,Fintype,Repr\n\n/-- Complete fixed lookup code; only actual stack cells decide the branches. -/\ndef program : Label → C.Instruction Stack Label\n  | .start => .call (.copy 0) .loop\n  | .loop => .base (.pop .index .selectTag .skipTag .skipTag)\n  | .skipTag => .base (.pop .reader .clearIndex .clearInput .callSkip)\n  | .selectTag => .base (.pop .reader .clearIndex .clearInput .callTake)\n  | .callSkip => .call (.field true (Field.active .tagPop (none,false))) .skipParsed\n  | .skipParsed => .base (.pop .valid .abort .abort .clearSkipped)\n  | .clearSkipped => .base (.pop .skipped .loop .clearSkipped .clearSkipped)\n  | .callTake => .call (.field false (Field.active .tagPop (none,false))) .takeParsed\n  | .takeParsed => .base (.pop .valid .abort .abort .clearInput)\n  | .clearInput => .base (.pop .reader .clearIndex .clearInput .clearInput)\n  | .clearIndex => .base (.pop .index .done .clearIndex .clearIndex)\n  | .done | .abort => .base .halt\n  | .copy pc => SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n  | .field skip pc => SemiprimeD1StackMultiplierLink.instruction (fieldStack skip) (Label.field skip) (Field.code pc)\n\n/-- Actual cache, query, binary payload and workspace. -/\ndef store (cache reader index parser skipped output valid copy : List Bool) : Stack → List Bool\n  | .cache => cache\n  | .reader => reader\n  | .index => index\n  | .parser => parser\n  | .skipped => skipped\n  | .output => output\n  | .valid => valid\n  | .copy => copy\n\n/-- Actual source configuration with empty real return frames. -/\ndef state (pc : Option Label) (flag : Option Bool) (returned : Option Label)\n    (cache reader index parser skipped output valid copy : List Bool) : C.State Stack Label :=\n  ⟨pc,flag,returned,store cache reader index parser skipped output valid copy,[]⟩\n\n/-- Actual finite-stack machine; a caller provides the physical unary query index. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine Stack.cache Stack.output Label.start program\n\nend RiemannGaussian.SemiprimeD1StackJetRead\n","RiemannGaussian.SemiprimeD1StackJetRouteDigits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetRouteFields\n/-! # Included physical division and digit compatibility calls -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackJetRouteDigits\nopen SemiprimeD1StackJetRoute SemiprimeD1StackJetRouteCalls\nopen SemiprimeD1StackUnaryDivmod (unary)\nlocal notation \"ctl\" => SemiprimeD1StackJetRoute.control\n\ntheorem divide_injective (b : Bool) : Function.Injective (divideStack b) := by\n  intro x y h\n  cases b <;> cases x <;> cases y <;> simp_all [divideStack]\n\ntheorem compare_injective : Function.Injective compareStack := by\n  intro x y h\n  cases x <;> cases y <;> simp_all [compareStack]\n\n/-- Actual left quotient/remainder acquisition preserves the literal divisor. -/\ntheorem divide_left (i j d : ℕ) (records result q : List Bool) :\n    ∃m≤100*(i+d+1)+1,Trace.Runs code m (ctl .divideLeft)\n      (bank [] records (unary i) (unary j) result [] q (unary d) [] [] [] [] []) (ctl .divideRight) (bank [] records [] (unary j) result [] q (unary d) (unary (i/d)) (unary (i%d)) [] [] []) := by\n  obtain ⟨m,hm,hr⟩ := SemiprimeD1StackUnaryDivmodBytecode.divide_run i d\n  refine ⟨m+1,by omega,?_⟩\n  apply Trace.included_call code (divideStack false) divideLeftLabel (divide_injective false)\n    SemiprimeD1StackUnaryDivmodBytecode.code SemiprimeD1StackUnaryDivmodBytecode.entry (fun _=>rfl)\n    (ctl .divideLeft) (ctl .divideRight) rfl m _ _ _ _ rfl rfl hr\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk .input rfl).elim | exact (hk .quotient rfl).elim | exact (hk .remainder rfl).elim\n\n/-- Actual right quotient/remainder acquisition preserves the literal divisor. -/\ntheorem divide_right (j d : ℕ) (records result q qi ri : List Bool) :\n    ∃m≤100*(j+d+1)+1,Trace.Runs code m (ctl .divideRight)\n      (bank [] records [] (unary j) result [] q (unary d) qi ri [] [] []) (ctl .compareCall) (bank [] records [] [] result [] q (unary d) qi ri (unary (j/d)) (unary (j%d)) []) := by\n  obtain ⟨m,hm,hr⟩ := SemiprimeD1StackUnaryDivmodBytecode.divide_run j d\n  refine ⟨m+1,by omega,?_⟩\n  apply Trace.included_call code (divideStack true) divideRightLabel (divide_injective true)\n    SemiprimeD1StackUnaryDivmodBytecode.code SemiprimeD1StackUnaryDivmodBytecode.entry (fun _=>rfl)\n    (ctl .divideRight) (ctl .compareCall) rfl m _ _ _ _ rfl rfl hr\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk .input rfl).elim | exact (hk .quotient rfl).elim | exact (hk .remainder rfl).elim\n\n/-- Compatibility is the actual comparator output, never a supplied digit predicate. -/\ntheorem compare_digits (qi qj q : ℕ) (records result d ri rj : List Bool) :\n    ∃m≤30*(qi+qj+q+1)+11,Trace.Runs code m (ctl .compareCall)\n      (bank [] records [] [] result [] (unary q) d (unary qi) ri (unary qj) rj [])\n      (ctl .compareDone) (bank [] records [] [] result [] [] d [] ri [] rj [decide (qi+qj<q)]) := by\n  obtain ⟨m,hm,hr⟩ := SemiprimeD1StackUnarySumLessBytecode.compare_run qi qj q\n  refine ⟨m+1,by omega,?_⟩\n  apply Trace.included_call code compareStack compareLabel compare_injective\n    SemiprimeD1StackUnarySumLessBytecode.code SemiprimeD1StackUnarySumLessBytecode.entry (fun _=>rfl)\n    (ctl .compareCall) (ctl .compareDone) rfl m _ _ _ _ rfl rfl hr\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk .left rfl).elim | exact (hk .right rfl).elim | exact (hk .limit rfl).elim | exact (hk .valid rfl).elim\n\nend RiemannGaussian.SemiprimeD1StackJetRouteDigits\n","RiemannGaussian.SemiprimeD1StackKernelLinearArithmeticBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackKernelLinearNormalize\n/-! # Own real primitive and signed-subtraction physical-byte bounds -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackKernelLinearArithmeticBounds\nopen SemiprimeD1StackKernelLinearView SemiprimeD1StackKernelLinearPrimitives\nopen SemiprimeBitArithmetic SemiprimeBitDivision\nnamespace Spec\nexport SemiprimeD1StackKernelLinearSpec (magnitude odd decompose power_length)\nend Spec\nnamespace Signed\nexport SemiprimeD1StackKernelLinearSigned (timeBound firstTime reverseTime)\nend Signed\nnamespace Tail\nexport SemiprimeD1StackKernelLinearTail (divideTime quotient remainder)\nend Tail\n/-- The real add/subtract output widths are bounded before any actual operand values. -/\ntheorem add_length (xs ys:List Bool):\n    (addBits xs ys false).bits.length ≤ max xs.length ys.length+1:=(addBits_counts xs ys false).2.2.2.2\n/-- A ripple difference retains exactly the maximum actual physical input width. -/\ntheorem sub_length (xs ys:List Bool):\n    (subBits xs ys false).result.bits.length=max xs.length ys.length:=(subBits_counts xs ys false).2.2.2.2\n/-- Signed reversal preserves all original padding, including a zero magnitude. -/\ntheorem magnitude_length (xs ys:List Bool):\n    (Spec.magnitude xs ys).length=max xs.length ys.length:=by\n  unfold Spec.magnitude\n  split\n  · rw [sub_length,Nat.max_comm]\n  · exact sub_length xs ys\n/-- The actual retained suffix never exceeds the physical input word. -/\ntheorem odd_length (xs:List Bool):(Spec.odd xs).length ≤ xs.length:=by\n  have h:=congrArg List.length (Spec.decompose xs)\n  simp only [List.length_append,List.length_replicate] at h\n  omega\n/-- Actual copy/ripple/reversal/return addition cost. -/\ntheorem addTime_le (xs ys:List Bool):addTime xs ys ≤ 10*(xs.length+ys.length+1):=by\n  have h:=add_length xs ys\n  have hm:max xs.length ys.length ≤ xs.length+ys.length:=max_le (by omega) (by omega)\n  unfold addTime\n  omega\n/-- Actual subtraction includes the true borrow-prefix output and real caller return. -/\ntheorem subTime_le (xs ys:List Bool):subTime xs ys ≤ 10*(xs.length+ys.length+1):=by\n  have h:=sub_length xs ys\n  have hm:max xs.length ys.length ≤ xs.length+ys.length:=max_le (by omega) (by omega)\n  unfold subTime\n  omega\n/-- Actual fitting clock charges padding and the entire discarded source suffix. -/\ntheorem fitTime_le (xs template:List Bool):\n    SemiprimeD1StackKernelLinearCalls.fitTime xs template ≤ 10*template.length+xs.length+9:=by\n  have h: (xs.drop template.length).length ≤ xs.length:=by simp only [List.length_drop];omega\n  unfold SemiprimeD1StackKernelLinearCalls.fitTime SemiprimeD1StackWordFitExecution.totalTime\n  omega\n/-- Both physically executed signed branches have a common linear source-width bound. -/\ntheorem signedTime_le (w:Words) (r:Nat) (hj:w.j.length ≤ r) (hd:w.displacement.length ≤ r):\n    Signed.timeBound w ≤ 100*(r+1):=by\n  have h0:=subTime_le w.j w.displacement\n  have h1:=subTime_le w.displacement w.j\n  have hw:=sub_length w.j w.displacement\n  have hm:max w.j.length w.displacement.length ≤ r:=max_le hj hd\n  unfold Signed.timeBound\n  split\n  · dsimp only [Signed.firstTime,Signed.reverseTime]\n    omega\n  · dsimp only [Signed.firstTime]\n    omega\n/-- Whole actual restoring-divider loop, paid copies and retained quotient cache. -/\ntheorem divideTime_le (w:Words) (r:Nat) (ha:w.alpha.length ≤ r) (hc:w.content.length ≤ r+1):\n    Tail.divideTime w ≤ 20000*(r+2)^2:=by\n  have h0:=SemiprimeD1StackDividerExecution.source_time w.alpha w.content\n  have h1:=SemiprimeD1StackDividerExecution.timeBound_le_square w.alpha.length w.content.length\n  have hw: (Tail.quotient w).length=w.alpha.length:=(divideLoop_widths w.alpha w.content).2.1\n  have hm:w.alpha.length+w.content.length+2 ≤ 2*r+3:=by omega\n  have hp:(w.alpha.length+w.content.length+2)^2 ≤ (2*r+3)^2:=Nat.pow_le_pow_left hm 2\n  unfold Tail.divideTime\n  nlinarith only [h0,h1,hw,ha,hc,hp]\nend RiemannGaussian.SemiprimeD1StackKernelLinearArithmeticBounds\n","RiemannGaussian.SemiprimeD1StackKernelLinearSum":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackKernelLinearView\n/-! # Actual center-plus-y acquisition and retained binary sum -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackKernelLinearSum\nopen SemiprimeD1StackKernelLinear SemiprimeD1StackKernelLinearPrimitives\nopen SemiprimeD1StackKernelLinearView SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic\n/-- Actual full binary sum retained before displacement subtraction. -/\ndef value (w:Words):List Bool:=(addBits w.center w.y false).bits\n/-- Sum-source actual copy, adder, cache and cleanup clock. -/\ndef timeBound (w:Words):Nat:=\n  (5*w.center.length+4)+(5*w.y.length+4)+addTime w.center w.y+(5*(value w).length+4)+((value w).length+3)\n/-- Complete actual sum front door, with every foreign word retained. -/\ntheorem source_trace (w:Words) (hs:w.scratch=[]) (hb:w.buffer=[]):\n    Runs program (timeBound w) (.local .centerAdd) (data w) (.local .bufferSub)\n      (data {w with buffer:=value w}):=by\n  have h0:=copy_call .centerAdd (.local .centerAdd) (.local .yAdd) rfl\n    (arithmeticData w [] [] []) w.center [] rfl rfl hs\n  simp only [List.append_nil] at h0\n  change Runs program _ _ _ _ (Function.update (arithmeticData w [] [] []) (arithmetic .left) w.center) at h0\n  rw [arithmeticData_left_update] at h0\n  have h1:=copy_call .yAdd (.local .yAdd) (.local .add) rfl\n    (arithmeticData w w.center [] []) w.y [] rfl rfl hs\n  simp only [List.append_nil] at h1\n  change Runs program _ _ _ _ (Function.update (arithmeticData w w.center [] []) (arithmetic .right) w.y) at h1\n  rw [arithmeticData_right_update] at h1\n  have h2:=add_call (.local .add) (.local .sum) rfl (fun _=>[]) (words w) w.center w.y\n  have h3:=copy_call .sum (.local .sum) (.local .clearSum) rfl\n    (arithmeticData w [] [] (value w)) (value w) [] rfl hb hs\n  simp only [List.append_nil] at h3\n  change Runs program _ _ _ _ (Function.update (arithmeticData w [] [] (value w)) (aux .buffer) (value w)) at h3\n  rw [arithmeticData_aux_update] at h3\n  have h4:=drain_call (.local .clearSum) (.local .bufferSub) (arithmetic .output)\n    (arithmeticData {w with buffer:=value w} [] [] (value w)) (value w) rfl rfl\n  rw [arithmeticData_output_update] at h4\n  have hh:=join h0 (join h1 (join h2 (join h3 h4)))\n  simpa only [timeBound,value,SemiprimeD1StackKernelLinearView.set,arithmeticData_empty,Nat.add_assoc] using hh\nend RiemannGaussian.SemiprimeD1StackKernelLinearSum\n","RiemannGaussian.SemiprimeD1StackLeafAcquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackLeafLoop\n/-! # Actual context and binary assignment-width acquisition in the leaf caller -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 131072\nset_option maxRecDepth 131072\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackLeafAcquisition\nopen SemiprimeD1StackLeaf SemiprimeD1StackLeafState\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans one_base)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\n\n/-- Actual context supplier shares precisely the retained product registers. -/\ntheorem context_call (p : PS.Values) (v : Values) (axesList : List ℕ)\n    (hp : ∀q∈axesList,0<q) (ha : p .axes=vectorBits (axesList.map unary))\n    (hr : p .rank=[]) (hw : p .width=[]) :\n    ∃ m ≤ 1000*(SemiprimeD1StackJetContextBounds.resource axesList (p .precision)+1)^2+1,\n      Runs program m .start (data p v) .widthCopy\n        (data (Function.update (Function.update p .rank (unary axesList.prod)) .width\n          (SemiprimeD1StackUnaryCounterExecution.markers (SemiprimeBitArithmetic.bitValue (p .precision)))) v) := by\n  obtain ⟨m,hm,hs⟩:=SemiprimeD1StackJetContextBounds.source_run_polynomial axesList hp (p .precision)\n  refine ⟨m+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureInclusion.included_call program contextStack Label.context contextStack_injective\n    SemiprimeD1StackJetContext.program .start (fun _=>rfl) .start .widthCopy rfl m\n    (SemiprimeD1StackJetContext.initial (vectorBits (axesList.map unary)) (p .precision))\n    (⟨none,none,none,SemiprimeD1StackJetContextCorrectness.finalData axesList (p .precision),[]⟩:\n      SemiprimeD1StackCalls.State SemiprimeD1StackJetContext.Stack SemiprimeD1StackJetContext.Label)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hs\n  · constructor\n    · intro k\n      change PS.data p (P.contextStack k)=_\n      rw [SemiprimeD1StackVertexProductProjection.context_project]\n      fin_cases k <;> simp [SemiprimeD1StackJetContext.initial,SemiprimeD1StackJetContext.bank,\n        SemiprimeD1StackJetContext.cached,SemiprimeD1StackJetContext.axesCache,\n        SemiprimeD1StackJetContext.rankCache,SemiprimeD1StackJetContext.widthCache,\n        SemiprimeD1StackJetContext.precisionBits,ha,hr,hw]\n    · intro k hk; rfl\n  · constructor\n    · intro k\n      change PS.data _ (P.contextStack k)=_\n      rw [SemiprimeD1StackVertexProductProjection.context_project]\n      fin_cases k <;> simp [SemiprimeD1StackJetContextCorrectness.finalData,\n        SemiprimeD1StackJetContext.bank,SemiprimeD1StackJetContext.cached,\n        SemiprimeD1StackJetContextExecution.ready,SemiprimeD1StackJetSuffix.data,SemiprimeD1StackAdder.store,\n        SemiprimeD1StackJetContext.axesCache,SemiprimeD1StackJetContext.rankCache,\n        SemiprimeD1StackJetContext.widthCache,SemiprimeD1StackJetContext.precisionBits,ha]\n    · intro k hk\n      have hr : k ≠ productStack (PS.address .rank) := fun he=>hk SemiprimeD1StackJetContext.rankCache he.symm\n      have hw : k ≠ productStack (PS.address .width) := fun he=>hk SemiprimeD1StackJetContext.widthCache he.symm\n      rw [data_product_update,data_product_update]\n      simp only [Function.update_of_ne hr,Function.update_of_ne hw]\n\n/-- Exact small unary-acquisition register projection, including its actual input. -/\ntheorem unary_project (p : PS.Values) (v : Values) (k : U.Stack) :\n    data p v (unaryStack k)=SemiprimeD1StackAdder.store (v .unaryInput) [] [] (v .counter) k := by\n  cases k\n  · exact data_get p v .unaryInput\n  · rfl\n  · rfl\n  · exact data_get p v .counter\n\n/-- The original binary width is really copied to its acquisition procedure. -/\ntheorem width_copy (p : PS.Values) (v : Values) (he : v .unaryInput=[]) :\n    Runs program (5*(v .widthBits).length+4) .widthCopy (data p v) .widthUnary\n      (data p (Function.update v .unaryInput (v .widthBits))) := by\n  apply SemiprimeD1StackProcedureTrace.included_call program (copyStack false) (Label.copy false)\n    (copyStack_injective false) SemiprimeD1StackCopy.code (0:Fin 9) (fun _=>rfl) .widthCopy .widthUnary rfl _\n    (SemiprimeD1StackCopy.state 0 none (v .widthBits) [] [])\n    (SemiprimeD1StackCopy.done (v .widthBits) (v .widthBits))\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words (v .widthBits) [] none\n  · constructor\n    · intro k\n      fin_cases k\n      · exact data_get p v .widthBits\n      · change data p v (address .unaryInput)=[]\n        rw [data_get,he]\n      · rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k\n      fin_cases k\n      · exact data_get p (Function.update v .unaryInput (v .widthBits)) .widthBits\n      · exact data_get p (Function.update v .unaryInput (v .widthBits)) .unaryInput\n      · rfl\n    · intro k hk\n      have hn : k ≠ address .unaryInput := fun he=>hk 1 he.symm\n      rw [data_update]\n      exact Function.update_of_ne hn _ _\n\n/-- Actual binary-to-marker procedure, not an advised width or loop count. -/\ntheorem width_unary (p : PS.Values) (v : Values) (he : v .counter=[]) :\n    Runs program (2*(v .unaryInput).length+1+\n      SemiprimeD1StackUnaryCounterExecution.loopTime (v .unaryInput).reverse 0+1)\n      .widthUnary (data p v) .makeZero\n      (data p (Function.update (Function.update v .unaryInput []) .counter\n        (SemiprimeD1StackUnaryCounterExecution.markers (SemiprimeBitArithmetic.bitValue (v .unaryInput))))) := by\n  apply SemiprimeD1StackProcedureTrace.included_call program unaryStack Label.unary\n    (by intro a b h; simpa only [unaryStack,Sum.inr.injEq,Sum.inl.injEq] using h)\n    U.code .reverse (fun _=>rfl) .widthUnary .makeZero rfl _\n    (SemiprimeD1StackUnaryCounter.state (some .reverse) none (v .unaryInput) [] [] [])\n    (SemiprimeD1StackUnaryCounter.state none none [] [] []\n      (SemiprimeD1StackUnaryCounterExecution.markers (SemiprimeBitArithmetic.bitValue (v .unaryInput))))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackUnaryCounterExecution.source_run (v .unaryInput)\n  · constructor\n    · intro k\n      rw [unary_project]\n      simp only [SemiprimeD1StackUnaryCounter.state,he]\n    · intro k hk; rfl\n  · constructor\n    · intro k\n      rw [unary_project]\n      cases k <;> simp [SemiprimeD1StackUnaryCounter.state,SemiprimeD1StackAdder.store]\n    · intro k hk\n      have hi : k ≠ address .unaryInput := fun he=>hk .left he.symm\n      have ho : k ≠ address .counter := fun he=>hk .output he.symm\n      rw [data_update,data_update]\n      simp only [Function.update_of_ne hi,Function.update_of_ne ho]\n\nend RiemannGaussian.SemiprimeD1StackLeafAcquisition\n","RiemannGaussian.SemiprimeD1StackMarkedPublicInputBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedPublicInputCost\n/-! # SAME finite machine's whole marked-coefficient time certificate -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackMarkedPublicInputBounds\nopen SemiprimeD1StackMarkedPublicInput SemiprimeD1StackMarkedPublicInputEncoding\nopen SemiprimeD1StackMarkedPublicInputExecution SemiprimeD1StackMarkedPublicInputCost\n/-- Whole source has a fixed quadratic in its actual physical source words. -/\ntheorem source_run_bounded (bits raw indexWord : List Bool) (side : Bool) (hb : bits≠[]) :\n    ∃ t ≤ polynomial bits raw indexWord,\n      SemiprimeD1StackCalls.run program t (initial bits raw indexWord [side])=\n        some (done bits raw indexWord side) := by\n  obtain ⟨t,ht,hr⟩ := source_run bits raw indexWord side hb\n  exact ⟨t,ht.trans (runBound_le bits raw indexWord),hr⟩\n/-- Genuine compiled execution, including every actual call/return and final halt. -/\nnoncomputable def machineSource (bits raw indexWord : List Bool) (side : Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits raw indexWord [side]))\n      (some (SemiprimeD1StackCalls.configuration (done bits raw indexWord side)))\n      (polynomial bits raw indexWord) := by\n  apply SemiprimeD1StackCalls.evalsCorrect\n    (checker (.inl SemiprimeD1StackPublicInputWidth.original)) (aux .output) (ctl .start) program\n  let h := source_run_bounded bits raw indexWord side hb\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackMarkedPublicInputBounds\n\n","RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableExecution\n/-! # Own polynomial-per-actual-assignment time and all144-role storage -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableBounds\nopen SemiprimeD1StackMarkedPublicInputTable SemiprimeD1StackMarkedPublicInputTableTrace\nopen SemiprimeD1StackMarkedPublicInputTableExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace G\nexport SemiprimeD1StackStaticWordTableSpec (inputBytes)\nend G\n/-- Actual source bytes only, including every byte of the retained binary scope vector. -/\ndef resource (bits indexWord bank : List Bool) : Nat := bits.length+indexWord.length+bank.length+2\n/-- Fixed polynomial times the physically counted arity's actual full2^n visits. -/\ndef polynomial (bits indexWord : List Bool) (words : List (List Bool)) : Nat :=\n  1000000000000000000000000*(resource bits indexWord (vectorBits words))^2*2^words.length\n/-- The same actual scope scan/source/framing/cleanup budget has a fixed own rate. -/\ntheorem runBound_le (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) :\n    runBound bits indexWord side words ≤ polynomial bits indexWord words := by\n  let r := resource bits indexWord (vectorBits words)\n  let i := G.inputBytes (inputTemplate bits indexWord side)\n  let b := budget bits indexWord words.length\n  have hr : 2 ≤ r := by dsimp [r,resource];omega\n  have hn0 := SemiprimeD1StackStaticWordTableBounds.scope_count_le words\n  have hn : words.length ≤ r := by dsimp [r,resource];omega\n  have hbank : (vectorBits words).length ≤ r := by dsimp [r,resource];omega\n  have hi : i ≤ 66*r := by\n    have hh := template_total_le bits indexWord side\n    dsimp only [i,r,resource]\n    omega\n  have hb : b ≤ 10000000000000000*r^2 := by\n    have h : bits.length+words.length+indexWord.length+2 ≤ r := by dsimp [r,resource];omega\n    exact Nat.mul_le_mul_left _ (Nat.pow_le_pow_left h 2)\n  have hr2 : r ≤ r^2 := Nat.le_pow (by decide : 0<(2:Nat))\n  unfold runBound SemiprimeD1StackStaticWordTableBounds.runBound\n    SemiprimeD1StackStaticWordTableDFS.weight SemiprimeD1StackStaticWordTableLeaf.leafBound polynomial\n  rw [show static.roles.length=66 from roles_length,SemiprimeD1StackMarkedPublicInputCompact.stack_card]\n  change (11*(vectorBits words).length+\n    (66*(6*i+5)+7*words.length+b+66*(66*(i+words.length+b)+1)+50*(i+words.length+b+1)+50+20)+\n      4*(i+words.length+b)+40)*2^words.length ≤ (1000000000000000000000000*r^2)*2^words.length\n  apply Nat.mul_le_mul_right\n  nlinarith\n/-- Entire actual whole144-role source, including all real calls/returns and halt. -/\ntheorem source_run_bounded (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) (hb : bits≠[]) :\n    ∃ t ≤ polynomial bits indexWord words,\n      SemiprimeD1StackCalls.run program t (initial bits indexWord side (vectorBits words))=\n        some (done bits indexWord side words) := by\n  obtain ⟨t,ht,hh⟩ := source_run bits indexWord side words hb\n  exact ⟨t,ht.trans (runBound_le bits indexWord side words),hh⟩\n/-- Genuine finite compiled execution from only actual original inputs and scope-bank bytes. -/\nnoncomputable def machineSource (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits indexWord side (vectorBits words)))\n      (some (SemiprimeD1StackCalls.configuration (done bits indexWord side words)))\n      (polynomial bits indexWord words) := by\n  apply SemiprimeD1StackCalls.evalsCorrect (SemiprimeD1StackStaticWordTable.counter .bank)\n    (SemiprimeD1StackStaticWordTable.aux .output) .start program\n  let hh := source_run_bounded bits indexWord side words hb\n  exact ⟨⟨Classical.choose hh,(Classical.choose_spec hh).2⟩,(Classical.choose_spec hh).1⟩\n/-- Every actual144-role prefix includes all retained templates, dirty shadows,\nwork, accumulated table output and genuine nested return-label cells. -/\ntheorem machine_cells (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) (hb : bits≠[])\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hp : (fun q => q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits indexWord side (vectorBits words))))=some cfg) :\n    (∑ k : Stack, (cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      1000000000000000000000000000*(resource bits indexWord (vectorBits words))^2*2^words.length := by\n  have hs := machine_prefix_cells bits indexWord side words hb fuel cfg hp\n  have ht := runBound_le bits indexWord side words\n  have hi := template_total_le bits indexWord side\n  let r := resource bits indexWord (vectorBits words)\n  have hr : 2 ≤ r := by dsimp [r,resource];omega\n  have hr2 : r ≤ r^2 := Nat.le_pow (by decide : 0<(2:Nat))\n  have hp2 : 1 ≤ (2:Nat)^words.length := by\n    have hh : 0 < (2:Nat)^words.length := by positivity\n    omega\n  have hx : r ≤ r^2*2^words.length := by nlinarith\n  have hi' : G.inputBytes (inputTemplate bits indexWord side) ≤ 66*r := by dsimp [r,resource];omega\n  have hb' : (vectorBits words).length ≤ r := by dsimp [r,resource];omega\n  unfold polynomial at ht\n  change _ ≤ 1000000000000000000000000000*r^2*2^words.length\n  change runBound bits indexWord side words ≤ 1000000000000000000000000*r^2*2^words.length at ht\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableBounds\n\n","RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableTrace\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableBounds\n/-! # Entire actual marked input-table source, with no table or arity input -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableExecution\nopen SemiprimeD1StackMarkedPublicInputTable SemiprimeD1StackMarkedPublicInputTableTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nnamespace G\nexport SemiprimeD1StackStaticWordTableExecution (outputTape result)\nend G\n/-- Every output leaf is one actual compact NONNEGATIVE coefficient word. -/\ndef outputTape (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) : List Bool :=\n  G.outputTape (answer bits indexWord side) words\n/-- Exact stopped whole144-role bank, including retained input template and scope/count cache. -/\ndef result (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) : Stack → List Bool :=\n  G.result (inputTemplate bits indexWord side) words (answer bits indexWord side)\n/-- Actual halt state; every live66 checker field and all DFS work are empty. -/\ndef done (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) :\n    SemiprimeD1StackCalls.State Stack Label :=\n  ⟨none,none,none,result bits indexWord side words,[]⟩\n/-- Complete own source clock, summing actual count, DFS, source, framing and final reverse caps. -/\ndef runBound (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) : Nat :=\n  SemiprimeD1StackStaticWordTableBounds.runBound static (inputTemplate bits indexWord side) words (budget bits indexWord)\n/-- SAME literal full table source runs from original physical template/scope only. -/\ntheorem source_run (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) (hb : bits≠[]) :\n    ∃ t ≤ runBound bits indexWord side words,\n      SemiprimeD1StackCalls.run program t (initial bits indexWord side (vectorBits words))=\n        some (done bits indexWord side words) :=\n  SemiprimeD1StackStaticWordTableBounds.source_run_bounded static (inputTemplate bits indexWord side)\n    (template_raw bits indexWord side) (answer bits indexWord side) (budget bits indexWord)\n    (actual_trace bits indexWord side hb) words\n/-- Every144-role compiled prefix includes both66 banks, the actual counter,\nall DFS fields, the temporarily dirty compaction shadow and all real returns. -/\ntheorem machine_prefix_cells (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) (hb : bits≠[])\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q => q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits indexWord side (vectorBits words))))=some cfg) :\n    (∑ k : Stack, (cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      145*(SemiprimeD1StackStaticWordTableSpec.inputBytes (inputTemplate bits indexWord side)+\n        (vectorBits words).length+runBound bits indexWord side words+1) := by\n  have hh := SemiprimeD1StackStaticWordTableBounds.machine_prefix_cells static\n    (inputTemplate bits indexWord side) (template_raw bits indexWord side)\n    (answer bits indexWord side) (budget bits indexWord) (actual_trace bits indexWord side hb) words fuel cfg hr\n  norm_num only [SemiprimeD1StackMarkedPublicInputCompact.stack_card,runBound] at hh ⊢\n  exact hh\n/-- Actual compact coefficient byte result, with no reordering of assignments. -/\ntheorem output_bytes (bits indexWord : List Bool) (side : Bool) (words : List (List Bool)) :\n    (done bits indexWord side words).data (SemiprimeD1StackStaticWordTable.aux .output)=\n      outputTape bits indexWord side words := by\n  change Function.update (SemiprimeD1StackStaticWordTable.data (inputTemplate bits indexWord side)\n    (vectorBits words) words.length [] []) (SemiprimeD1StackStaticWordTable.aux .output)\n    (outputTape bits indexWord side words) (SemiprimeD1StackStaticWordTable.aux .output)=_\n  exact Function.update_self _ _ _\nend RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableExecution\n\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsPrimitives\n/-! # Paid framed-field parsing with physical true-validity consumption -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsFields\nopen SemiprimeD1StackMarkedRootRecords SemiprimeD1StackMarkedRootRecordsPrimitives\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Parser validity never shares an input-reader word. -/\ntheorem status_ne_reader (what : Field) : aux .status≠fieldReader what := by cases what <;> decide\n/-- Parser validity never shares a parsed destination. -/\ntheorem status_ne_target (what : Field) : aux .status≠fieldTarget what := by cases what <;> decide\n/-- Each paid parser is followed by an actual TRUE pop, including empty tag/port fields. -/\ntheorem field_run (what : Field) (bank : Stack → List Bool) (word tail : List Bool)\n    (hi : bank (fieldReader what)=frame word tail) (ho : bank (fieldTarget what)=[])\n    (hs : bank (aux .fieldScratch)=[]) (hv : bank (aux .status)=[]) :\n    Runs program (8*word.length+8) (ctl (.field what)) bank (fieldNext what)\n      (Function.update (Function.update bank (fieldReader what) tail) (fieldTarget what) word) := by\n  let after := Function.update (Function.update bank (fieldReader what) tail) (fieldTarget what) word\n  have h0 := parse_call what bank word tail hi ho hs hv\n  have h1 : Runs program 1 (ctl (.valid what)) (Function.update after (aux .status) [true])\n      (fieldNext what) (Function.update after (aux .status) []) := by\n    apply one_base program (ctl (.valid what)) (fieldNext what)\n      (.pop (aux .status) (ctl .abort) (ctl .abort) (fieldNext what)) _ _ rfl\n    · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose]\n    · simp [SemiprimeD1StackBytecode.execute,Function.update_idem]\n  have he : after (aux .status)=[] := by\n    dsimp only [after]\n    rw [Function.update_of_ne (status_ne_target what),Function.update_of_ne (status_ne_reader what),hv]\n  have hf : Function.update after (aux .status) []=after := by\n    rw [←he,Function.update_eq_self]\n  rw [hf] at h1\n  simpa only [Nat.add_assoc] using join h0 h1\n/-- The record TRUE is really read before either framed payload is inspected. -/\ntheorem row_tag (bank : Stack → List Bool) (tail : List Bool)\n    (h : bank (aux .recordReader)=true::tail) :\n    Runs program 1 (ctl .rowTag) bank (ctl (.field .ports))\n      (Function.update bank (aux .recordReader) tail) := by\n  apply one_base program (ctl .rowTag) (ctl (.field .ports))\n    (.pop (aux .recordReader) (ctl .abort) (ctl .recordEOF) (ctl (.field .ports))) _ _ rfl\n  · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose,h]\n  · simp [SemiprimeD1StackBytecode.execute,h]\n/-- A final FALSE is physically consumed and is not confused with descriptor EOF. -/\ntheorem record_end (bank : Stack → List Bool) (h : bank (aux .recordReader)=[false]) :\n    Runs program 1 (ctl .rowTag) bank (ctl .recordEOF)\n      (Function.update bank (aux .recordReader) []) := by\n  apply one_base program (ctl .rowTag) (ctl .recordEOF)\n    (.pop (aux .recordReader) (ctl .abort) (ctl .recordEOF) (ctl (.field .ports))) _ _ rfl\n  · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose,h]\n  · simp [SemiprimeD1StackBytecode.execute,h]\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsFields\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsFinish":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsRowView\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsPrimitives\n/-! # Actual owner-first byte rejoin with all borrowed original work restored -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsFinish\nopen SemiprimeD1StackMarkedRootRecords SemiprimeD1StackMarkedRootRecordsView\nopen SemiprimeD1StackMarkedRootRecordsRowView SemiprimeD1StackMarkedRootRecordsPrimitives\nopen SemiprimeD1StackProcedureTrace\n/-- Two actual borrowed original work words; no source/cache role is overwritten. -/\ndef borrowed (r : R.Stack → List Bool) (left rev : List Bool) : R.Stack → List Bool :=\n  Function.update (Function.update r (R.aux .left) left) (R.aux .reverse) rev\n/-- Literal owner-copy workspace boundary, with all144 and local parse work empty. -/\ndef joining (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits left rev out : List Bool) : Stack → List Bool :=\n  view (borrowed r left rev) v bits {} {output := out}\n/-- A real owner-copy write updates only its actually borrowed source-bank role. -/\ntheorem joining_left (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits left rev out word : List Bool) :\n    Function.update (joining r v bits left rev out) ownerCopy word=joining r v bits word rev out := by\n  unfold joining view ownerCopy\n  rw [update_root]\n  unfold borrowed\n  rw [Function.update_comm (by decide : R.aux .left≠R.aux .reverse),Function.update_idem,\n    Function.update_comm (by decide : R.aux .reverse≠R.aux .left)]\n/-- A real reversal write changes only the second borrowed physical word. -/\ntheorem joining_reverse (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits left rev out word : List Bool) :\n    Function.update (joining r v bits left rev out) ownerReverse word=joining r v bits left word out := by\n  unfold joining view ownerReverse\n  rw [update_root]\n  unfold borrowed\n  rw [Function.update_idem]\n/-- A real final append writes only the actual new output. -/\ntheorem joining_output (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits left rev out word : List Bool) :\n    Function.update (joining r v bits left rev out) (aux .output) word=joining r v bits left rev word :=\n  set_output _ _ _ _ _ _\n/-- Restoring BOTH actual borrowed words recovers the entire original1804 bank verbatim. -/\ntheorem borrowed_clean (r : R.Stack → List Bool) (hl : r (R.aux .left)=[]) (hr : r (R.aux .reverse)=[]) :\n    borrowed r [] []=r := by\n  have h0 : Function.update r (R.aux .left) []=r := by rw [←hl,Function.update_eq_self]\n  unfold borrowed\n  rw [h0,←hr,Function.update_eq_self]\n/-- Paid owner copy/reversal/terminator removal/reversal plus actual success push.\nNo prepared owner answer or native append is used by the machine. -/\ntheorem join_run (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits ownerBytes factors : List Bool)\n    (ho : r (R.ownerStack SemiprimeD1StackOwnerRecords.output)=ownerBytes++[false])\n    (hl : r (R.aux .left)=[]) (hr : r (R.aux .reverse)=[]) (hs : r (R.aux .scratch)=[]) :\n    Runs program (9*ownerBytes.length+19) (ctl .copyOwners) (view r v bits {} {output := factors})\n      (ctl .done) (view r v bits {} {status := [true],output := ownerBytes++factors}) := by\n  have h0 := copy_call .owners .copyOwners .reverseOwners rfl (joining r v bits [] [] factors)\n    (ownerBytes++[false]) [] ho rfl hs\n  change Runs program _ _ _ _ (Function.update (joining r v bits [] [] factors) ownerCopy ((ownerBytes++[false])++[])) at h0\n  rw [List.append_nil,joining_left] at h0\n  have h1 := reverse_call false .reverseOwners .stripOwnerEnd rfl\n    (joining r v bits (ownerBytes++[false]) [] factors) (ownerBytes++[false]) [] rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (joining r v bits (ownerBytes++[false]) [] factors) ownerCopy []) ownerReverse ((ownerBytes++[false]).reverse++[])) at h1\n  rw [joining_left,joining_reverse,List.append_nil,List.reverse_append,List.reverse_singleton,List.singleton_append] at h1\n  have h2 : Runs program 1 (ctl .stripOwnerEnd) (joining r v bits [] (false::ownerBytes.reverse) factors)\n      (ctl .join) (joining r v bits [] ownerBytes.reverse factors) := by\n    apply one_base program _ _ (.pop ownerReverse (ctl .abort) (ctl .join) (ctl .abort)) _ _ rfl\n    · rfl\n    · exact joining_reverse _ _ _ _ _ _ _\n  have h3 := reverse_call true .join .accept rfl (joining r v bits [] ownerBytes.reverse factors)\n    ownerBytes.reverse factors rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (joining r v bits [] ownerBytes.reverse factors) ownerReverse []) (aux .output) (ownerBytes.reverse.reverse++factors)) at h3\n  rw [joining_reverse,joining_output,List.reverse_reverse] at h3\n  have h4 : Runs program 1 (ctl .accept) (joining r v bits [] [] (ownerBytes++factors)) (ctl .done)\n      (view (borrowed r [] []) v bits {} {status := [true],output := ownerBytes++factors}) := by\n    apply one_base program _ _ (.push (aux .status) true (ctl .done)) _ _ rfl\n    · rfl\n    · exact set_status _ _ _ _ _ _\n  have h := join (join (join (join h0 h1) h2) h3) h4\n  unfold joining at h\n  rw [borrowed_clean r hl hr] at h\n  convert h using 1\n  simp only [List.length_append,List.length_cons,List.length_nil,List.length_reverse]\n  omega\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsFinish\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsTableView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsView\n/-! # Exact sparse physical table-template and acquired table/cache views -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsTableView\nopen SemiprimeD1StackMarkedRootRecords\n/-- Six actually populated table roles at a clean row boundary. -/\ndef slot (i : Fin 6) : T.Stack :=\n  if i=0 then tableNumber else if i=1 then tableIndex else if i=2 then tableSide\n  else if i=3 then G.counter .bank else if i=4 then G.counter .count else G.aux .output\n/-- All six actual data/cache positions are physically distinct. -/\ntheorem slot_injective : Function.Injective slot := by decide\n/-- Sparse144-role view. Live checker words, DFS words and private shadows are empty. -/\ndef tableWords (bits indexWord sideWord bank countWord output : List Bool) (k : T.Stack) : List Bool :=\n  if k=tableNumber then bits else if k=tableIndex then indexWord else if k=tableSide then sideWord\n  else if k=G.counter .bank then bank else if k=G.counter .count then countWord\n  else if k=G.aux .output then output else []\n/-- Only the physically parsed original index and computed side accompany N and scope bytes. -/\ntheorem initial_table (bits indexWord : List Bool) (sideBit : Bool) (bank : List Bool) :\n    (SemiprimeD1StackMarkedPublicInputTable.initial bits indexWord sideBit bank).data=\n      tableWords bits indexWord [sideBit] bank [] [] := by\n  funext k\n  rcases k with k|k\n  · simp [SemiprimeD1StackMarkedPublicInputTable.initial,SemiprimeD1StackStaticWordTable.initial,\n      SemiprimeD1StackStaticWordTable.data,SemiprimeD1StackStaticWordTable.store,\n      tableWords,tableNumber,tableIndex,tableSide,G.template,G.counter,G.aux]\n  · rcases k with k|k\n    · change SemiprimeD1StackMarkedPublicInputTable.inputTemplate bits indexWord sideBit k=_\n      rw [SemiprimeD1StackMarkedPublicInputTableTrace.template_only]\n      simp only [tableWords,tableNumber,tableIndex,tableSide,G.template,G.counter,G.aux,\n        Sum.inr.injEq,Sum.inl.injEq,Sum.inl_ne_inr,ite_false]\n    · rcases k with k|k\n      · cases k <;> rfl\n      · cases k <;> rfl\n/-- The real completed144 source retains exactly the original scope, template and counted arity. -/\ntheorem result_table (bits indexWord : List Bool) (sideBit : Bool) (words : List (List Bool)) :\n    (SemiprimeD1StackMarkedPublicInputTableExecution.done bits indexWord sideBit words).data=\n      tableWords bits indexWord [sideBit] (SemiprimeD1TensorTapeCodec.vectorBits words)\n        (List.replicate words.length true)\n        (SemiprimeD1StackMarkedPublicInputTableExecution.outputTape bits indexWord sideBit words) := by\n  have h := initial_table bits indexWord sideBit (SemiprimeD1TensorTapeCodec.vectorBits words)\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · exact congrFun h (.inr (.inl k))\n    · rcases k with k|k\n      · cases k <;> rfl\n      · cases k <;> rfl\n/-- The six physical slot evaluations are independent of every other table word. -/\ntheorem tableWords_slot (bits indexWord sideWord bank countWord output : List Bool) (i : Fin 6) :\n    tableWords bits indexWord sideWord bank countWord output (slot i)=\n      (![bits,indexWord,sideWord,bank,countWord,output] : Fin 6 → List Bool) i := by\n  fin_cases i <;> rfl\n/-- Updating the actual indexWord cell preserves every other table/template word. -/\ntheorem update_indexWord (bits indexWord sideWord bank countWord output word : List Bool) :\n    Function.update (tableWords bits indexWord sideWord bank countWord output) (tableIndex) word=\n      tableWords bits word sideWord bank countWord output := by\n  funext k\n  by_cases h : k=(tableIndex)\n  · subst k;rfl\n  · simp only [Function.update_of_ne h,tableWords,h,ite_false]\n/-- Updating the actual sideWord cell preserves every other table/template word. -/\ntheorem update_sideWord (bits indexWord sideWord bank countWord output word : List Bool) :\n    Function.update (tableWords bits indexWord sideWord bank countWord output) (tableSide) word=\n      tableWords bits indexWord word bank countWord output := by\n  funext k\n  by_cases h : k=(tableSide)\n  · subst k;rfl\n  · simp only [Function.update_of_ne h,tableWords,h,ite_false]\n/-- Updating the actual bank cell preserves every other table/template word. -/\ntheorem update_bank (bits indexWord sideWord bank countWord output word : List Bool) :\n    Function.update (tableWords bits indexWord sideWord bank countWord output) (G.counter .bank) word=\n      tableWords bits indexWord sideWord word countWord output := by\n  funext k\n  by_cases h : k=(G.counter .bank)\n  · subst k;rfl\n  · simp only [Function.update_of_ne h,tableWords,h,ite_false]\n/-- Updating the actual countWord cell preserves every other table/template word. -/\ntheorem update_countWord (bits indexWord sideWord bank countWord output word : List Bool) :\n    Function.update (tableWords bits indexWord sideWord bank countWord output) (G.counter .count) word=\n      tableWords bits indexWord sideWord bank word output := by\n  funext k\n  by_cases h : k=(G.counter .count)\n  · subst k;rfl\n  · simp only [Function.update_of_ne h,tableWords,h,ite_false]\n/-- Updating the actual output cell preserves every other table/template word. -/\ntheorem update_output (bits indexWord sideWord bank countWord output word : List Bool) :\n    Function.update (tableWords bits indexWord sideWord bank countWord output) (G.aux .output) word=\n      tableWords bits indexWord sideWord bank countWord word := by\n  funext k\n  by_cases h : k=(G.aux .output)\n  · subst k;rfl\n  · simp only [Function.update_of_ne h,tableWords,h,ite_false]\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsTableView\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseOuterBounds\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseOutputBounds\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseExecution\n/-! # Whole actual normalized inverse has a fixed polynomial bit clock\nAll physical array scans, unary index copies/pops, fitted R36 source calls,\ncoefficient framing/reversal, every58-role boundary and real returns are paid.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseBounds\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseStateBounds SemiprimeD1StackNormalizedInverseOuterBounds\nopen SemiprimeD1StackNormalizedInverseOutputBounds SemiprimeD1StackNormalizedInverseExecution\nopen SemiprimeD1StackNormalizedInverseEncoding SemiprimeD1StackNormalizedInverseReadBuffers\n/-- Coefficient and degree are fixed BEFORE every denominator array, q and W template. -/\ndef polynomial (a : List SemiprimeRationalBits.RationalWord) (q : ℕ) (width : List Bool) : ℕ :=\n  10^42*(inputSize a q width)^10\n/-- SAME actual whole source clock, with cached-prefix lengths and every complete coefficient individually charged. -/\ntheorem runBound_le (a : List SemiprimeRationalBits.RationalWord) (q : ℕ) (width : List Bool) :\n    runBound a q width ≤ polynomial a q width := by\n  have ha:=acquireBound_le a q width\n  have hf:=SemiprimeD1StackNormalizedInverseOutputBounds.finishTime_le a q width\n  have hc:=beforeCleanup_mass a q width\n  have hs:=inputSize_caps a q width\n  have hs8:(inputSize a q width)^8 ≤ (inputSize a q width)^10:=Nat.pow_le_pow_right hs.1 (by decide:8≤10)\n  have hs2:(inputSize a q width)^2 ≤ (inputSize a q width)^10:=Nat.pow_le_pow_right hs.1 (by decide:2≤10)\n  have hp:1 ≤ (inputSize a q width)^10:=Nat.one_le_pow _ _ hs.1\n  unfold runBound polynomial\n  nlinarith only [ha,hf,hc,hs8,hs2,hp]\n/-- ALL typed physical arrays and ALL actual unary q/W words terminate with exact native bytes within this fixed clock. -/\ntheorem source_run_bounded (a : List SemiprimeRationalBits.RationalWord) (q : ℕ) (width : List Bool) :\n    ∃t≤polynomial a q width,SemiprimeD1StackCalls.run program t (initial (tape a) (unary q) width)=some (done a q width) := by\n  obtain ⟨t,ht,hr⟩:=source_run a q width\n  exact ⟨t,ht.trans (runBound_le a q width),hr⟩\n/-- Actual fixed58-role prepared source machine; the denominator producer/literal caller are separate. -/\nnoncomputable def machineSource (a : List SemiprimeRationalBits.RationalWord) (q : ℕ) (width : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial (tape a) (unary q) width))\n      (some (SemiprimeD1StackCalls.configuration (done a q width))) (polynomial a q width) := by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .denominator) (aux .output) (ctl .start) program\n  let h:=source_run_bounded a q width\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseBounds\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseCoefficient":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInversePrepare\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseInner\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseNegate\n/-! # Complete actual noninitial inverse coefficient from the retained arrays and built-prefix count -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseCoefficient\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseCalls SemiprimeD1StackNormalizedInverseReadBuffers\nopen SemiprimeD1StackNormalizedInversePrepare SemiprimeD1StackNormalizedInverseInner\nopen SemiprimeD1StackNormalizedInverseIndices SemiprimeD1StackNormalizedInverseRecurrence\nopen SemiprimeD1StackNormalizedInverseRegisterAlgebra SemiprimeD1StackProcedureTrace\nnamespace Neg\nexport SemiprimeD1StackNormalizedInverseNegate (negateBound negate_run output result)\nend Neg\n/-- The three actual pair counters are empty again when the complete descending loop ends. -/\ntheorem counters_empty (w : Words) (ht : w.auxiliary .terms=[]) (ha : w.auxiliary .aIndex=[])\n    (hb : w.auxiliary .bIndex=[]) : counters w 0 0 0=w := by\n  apply congrArg (fun f=>({w with auxiliary:=f}:Words))\n  funext k;cases k <;> simp [unary,ht,ha,hb]\n/-- Exact raw final coefficient, including every native fit, is a proof specification only. -/\ndef nextWord (width : List Bool) (a reversed : List SemiprimeRationalBits.RationalWord) (n : ℕ) :\n    SemiprimeRationalBits.RationalWord :=\n  (SemiprimeRationalBits.executeOperation .neg (dotLoop width a.toArray reversed n SemiprimeRationalBits.zeroWord)\n    SemiprimeRationalBits.zeroWord width).word\n/-- Exact all-cache-empty endpoint with one actual framed row prepended to the acquired prefix. -/\ndef result (w : Words) (word : SemiprimeRationalBits.RationalWord) : Words :=\n  {w with registers:=fun _=>[],auxiliary:=Function.update w.auxiliary .prefixReverse (row word (w.auxiliary .prefixReverse))}\n/-- Sum of this SAME literal source's preparation, inner dot and final negation/framing/cleanup caps. -/\ndef coefficientBound (w : Words) (a reversed : List SemiprimeRationalBits.RationalWord) (width : List Bool) (n : ℕ) : ℕ :=\n  (15*n+15)+innerBound w a reversed width n SemiprimeRationalBits.zeroWord+\n    Neg.negateBound (putReg w .acc (dotLoop width a.toArray reversed n SemiprimeRationalBits.zeroWord)) width\n/-- Whole coefficient: all query indices come from paid copies of the ACTUAL built-prefix markers. -/\ntheorem coefficient_run (w : Words) (a reversed : List SemiprimeRationalBits.RationalWord) (width : List Bool)\n    (n : ℕ) (hn : 0<n) (hr : w.rational=emptyRational width)\n    (ha : store w (readSource .denominator)=tape a) (hb : store w (readSource .prefix)=tape reversed)\n    (hbuilt : w.auxiliary .built=unary n)\n    (hterms : w.auxiliary .terms=[]) (hai : w.auxiliary .aIndex=[]) (hbi : w.auxiliary .bIndex=[])\n    (hreader : w.auxiliary .reader=[]) (htodo : w.auxiliary .readTodo=[])\n    (hs : w.auxiliary .fieldFrameScratch=[]) (hv : w.auxiliary .valid=[]) (hc : w.auxiliary .copyScratch=[])\n    (hregs : w.registers=fun _=>[]) :\n    ∃q≤coefficientBound w a reversed width n,\n      Runs program q (ctl .copyTerms) (store w) (ctl .bump) (store (result w (nextWord width a reversed n))) := by\n  have h0:=prepare_run w n hn hbuilt hterms hai hbi hc (congrFun hregs (.acc,false)) (congrFun hregs (.acc,true))\n  obtain ⟨q1,hq1,h1⟩:=inner_run w a reversed width n SemiprimeRationalBits.zeroWord hr ha hb\n    hreader htodo hs hv hc (fun r _ den=>congrFun hregs (r,den))\n  let dot:=dotLoop width a.toArray reversed n SemiprimeRationalBits.zeroWord\n  have hempty : indexed w 0 0 0 dot=putReg w .acc dot := by\n    rw [indexed,counters_empty w hterms hai hbi]\n  rw [hempty] at h1\n  have hright (den : Bool) : (putReg w .acc dot).registers (.right,den)=[] := by\n    rw [putReg_other _ .acc .right dot den (by decide)]\n    exact congrFun hregs (.right,den)\n  obtain ⟨q2,hq2,h2⟩:=Neg.negate_run (putReg w .acc dot) width hr hc hv hs\n    (hright false) (hright true) (putReg_nonempty w .acc dot)\n  have hout : Neg.output (putReg w .acc dot) width=nextWord width a reversed n := by\n    rw [Neg.output,getReg_put]\n    rfl\n  have he : Neg.result (putReg w .acc dot) width=result w (nextWord width a reversed n) := by\n    unfold Neg.result\n    rw [hout]\n    rfl\n  rw [he] at h2\n  have h:=PTrace.join (PTrace.join h0 h1) h2\n  refine ⟨15*n+15+q1+q2,?_,h⟩\n  unfold coefficientBound\n  dsimp only [dot] at hq2\n  omega\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseCoefficient\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseOperation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseOperationOutput\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseCleanup\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseReadBuffers\n/-! # Whole real inverse arithmetic call, all normalization/fits and actual private cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseOperation\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseCalls SemiprimeD1StackNormalizedInverseOperationInput\nopen SemiprimeD1StackNormalizedInverseOperationOutput SemiprimeD1StackNormalizedInverseCleanup\nopen SemiprimeD1StackNormalizedInverseReadBuffers SemiprimeD1StackProcedureTrace\n/-- Exact same-source prefix clock, through actual result copies and sign pop/push. -/\ndef prefixTime (site:Site) (w:Words) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd width:List Bool) :Nat:=\n  inputsTime (sx::xn) xd (sy::yn) yd+\n    (SemiprimeD1StackRationalOperationExecution.runBound (operation site) sx xn xd sy yn yd width+1)+\n    ((w.registers (destination site,false)).length+1+(w.registers (destination site,true)).length+1)+\n    saveTime (word (operation site) sx xn xd sy yn yd width)\n/-- Actual stopped R36 bank and acquired result before all35 physical drains. -/\ndef beforeCleanup (site:Site) (w:Words) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd width:List Bool) :Words:=\n  saved {w with rational:=SemiprimeD1StackRationalOperationExecution.result (operation site) sx xn xd sy yn yd width}\n    site (word (operation site) sx xn xd sy yn yd width)\n/-- The four actual input copies finish BEFORE any aliased accumulator/destination is drained. -/\ntheorem prefix_run (site:Site) (w:Words) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd width:List Bool)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[])\n    (hls:w.registers (operand site false,false)=sx::xn) (hld:w.registers (operand site false,true)=xd)\n    (hrs:w.registers (operand site true,false)=sy::yn) (hrd:w.registers (operand site true,true)=yd) :\n    Runs program (prefixTime site w sx xn xd sy yn yd width) (.operation site (.copyInput false false)) (store w)\n      (.operation site (.clear 0)) (store (beforeCleanup site w sx xn xd sy yn yd width)):=by\n  let ready:Words:={w with rational:=SemiprimeD1StackRationalOperation.input (sx::xn) xd (sy::yn) yd width}\n  let stopped:Words:={w with rational:=SemiprimeD1StackRationalOperationExecution.result (operation site) sx xn xd sy yn yd width}\n  have h0:=inputs_run site w width (sx::xn) xd (sy::yn) yd hr hs hls hld hrs hrd\n  have h1:=rational_call site ready sx xn xd sy yn yd width rfl\n  have h2:=erase_run site stopped\n  have hshape:=word_shape (operation site) sx xn xd sy yn yd width\n  have h3:=save_run site stopped (word (operation site) sx xn xd sy yn yd width) hs hshape.1 hshape.2.1 hshape.2.2\n  exact PTrace.join (PTrace.join (PTrace.join h0 h1) h2) h3\n/-- The actual original template survives sign consumption and every R36 instruction. -/\ntheorem beforeCleanup_template (site:Site) (w:Words) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd width:List Bool) :\n    (beforeCleanup site w sx xn xd sy yn yd width).rational (R.aux .template)=width:=by\n  change Function.update (SemiprimeD1StackRationalOperationExecution.result (operation site) sx xn xd sy yn yd width)\n    SemiprimeD1StackRationalOperation.signOutput [] (R.aux .template)=width\n  rw [Function.update_of_ne (by decide)]\n  exact SemiprimeD1StackRationalOperationOriginal.template_retained (operation site) sx xn xd sy yn yd width\n/-- Cleanup returns all35 real arithmetic fields to their honest empty state, retaining every foreign word. -/\ntheorem cleanup_result (site:Site) (w:Words) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd width:List Bool)\n    (hr:w.rational=emptyRational width) :\n    cleared (fun i:Fin 35=>rational (rationalRole i)) (store (beforeCleanup site w sx xn xd sy yn yd width)) 35=\n      store (putReg w (destination site) (word (operation site) sx xn xd sy yn yd width)):=by\n  let stopped:=beforeCleanup site w sx xn xd sy yn yd width\n  rw [rational_cleared stopped]\n  have hf:(fun k=>if k=R.aux .template then stopped.rational k else [])=emptyRational width:=by\n    funext k\n    by_cases hk:k=R.aux .template\n    · subst k\n      simp only [ite_true,emptyRational]\n      exact beforeCleanup_template site w sx xn xd sy yn yd width\n    · simp only [hk,ite_false,emptyRational]\n  rw [hf]\n  change store {putReg w (destination site) (word (operation site) sx xn xd sy yn yd width) with rational:=emptyRational width}=_\n  rw [←hr]\n  rfl\n/-- Own actual elapsed bound includes every retained foreign word during all35 cleanup loops. -/\ndef timeBound (site:Site) (w:Words) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd width:List Bool) :Nat:=\n  2100*(mass (store w)+prefixTime site w sx xn xd sy yn yd width+1)+1\n/-- The complete internal helper ends BEFORE its real return, with its physically acquired TRUE marker. -/\ntheorem operation_run (site:Site) (w:Words) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd width:List Bool)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[]) (hv:w.auxiliary .valid=[])\n    (hls:w.registers (operand site false,false)=sx::xn) (hld:w.registers (operand site false,true)=xd)\n    (hrs:w.registers (operand site true,false)=sy::yn) (hrd:w.registers (operand site true,true)=yd) :\n    ∃q≤timeBound site w sx xn xd sy yn yd width,\n      Runs program q (.operation site (.copyInput false false)) (store w) (.operation site .return)\n        (store (success (putReg w (destination site) (word (operation site) sx xn xd sy yn yd width)))):=by\n  have hp:=prefix_run site w sx xn xd sy yn yd width hr hs hls hld hrs hrd\n  obtain ⟨q,hq,hqrun⟩:=rational_after_trace site (prefixTime site w sx xn xd sy yn yd width)\n    (.operation site (.copyInput false false)) (store w) (store (beforeCleanup site w sx xn xd sy yn yd width)) hp\n  rw [cleanup_result site w sx xn xd sy yn yd width hr] at hqrun\n  let acquired:=putReg w (destination site) (word (operation site) sx xn xd sy yn yd width)\n  have h1:=PTrace.push_run (.operation site .success) (.operation site .return) (aux .valid) true (store acquired) rfl\n  change Runs program 1 _ _ _ (Function.update (store acquired) (aux .valid) (true::acquired.auxiliary .valid)) at h1\n  rw [update_success acquired hv] at h1\n  exact ⟨q+1,Nat.add_le_add_right hq 1,PTrace.join hqrun h1⟩\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseOperation\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseStorage\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseLegacy\n/-! # Original recovery normalized inverse acquired by the SAME actual finite source\nOnly physical denominator-array bytes, the actually derived q markers and W are\nruntime inputs. Original metadata/width facts below derive Valid/Fits internally;\nthe literal upstream Affine caller join and whole scalar counter remain separate.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseOriginal\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseBounds SemiprimeD1StackNormalizedInverseEncoding\nopen SemiprimeD1StackNormalizedInverseStorage SemiprimeD1StackNormalizedInverseLegacy\nopen SemiprimeD1StackNormalizedInverseReadBuffers\n/-- Original q is specified by the actual original geometry/multiplicity, never supplied as a decoded control Nat. -/\ndef multiplicity (a M u : ℕ) (t : ℕ) : ℕ :=\n  SemiprimeD1JetRecoveryGrid.nodeMultiplicity a (SemiprimeD1TaperedLoss.height M u) u t\n/-- Complete actual run, exact WHOLE native bytes and mathematical inverse Valid/Bounded follow from original dimensions alone. -/\ntheorem source_run_original (width : List Bool) (a M u : ℕ) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (hM : u≤M) (hW : SemiprimeD1RecoveryNodeBits.width a M≤width.length) :\n    let den:=denominator width a M u t\n    let q:=multiplicity a M u t.val\n    let inv:=SemiprimeNormalizedInverseBits.build width den q\n    ∃time≤polynomial den.toList q width,\n      SemiprimeD1StackCalls.run program time (initial (tape den.toList) (unary q) width)=some (done den.toList q width) ∧\n      (done den.toList q width).data (aux .output)=tape inv.words.toList ∧\n      SemiprimeJetBits.decode inv.words=(SemiprimeD1JetRecoveryWeights.acquire a (SemiprimeD1TaperedLoss.height M u) u t.val).inverse.coefficients ∧\n      SemiprimeJetBits.Valid inv.words ∧ SemiprimeJetBits.Bounded inv.words width.length := by\n  let den:=denominator width a M u t\n  let q:=multiplicity a M u t.val\n  obtain ⟨time,ht,hr⟩:=source_run_bounded den.toList q width\n  exact ⟨time,ht,hr,output_legacy den q width,original_valid width a M u t hM hW⟩\n/-- The actual original prepared bank follows the SAME fixed finite58-role machine and OWN polynomial clock. -/\nnoncomputable def machineOriginal (width : List Bool) (a M u : ℕ) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) :\n    let den:=denominator width a M u t\n    let q:=multiplicity a M u t.val\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial (tape den.toList) (unary q) width))\n      (some (SemiprimeD1StackCalls.configuration (done den.toList q width))) (polynomial den.toList q width) :=\n  machineSource (denominator width a M u t).toList (multiplicity a M u t.val) width\n/-- Every compiled original-family prefix counts ALL58 data words AND its actual none-label return stack. -/\ntheorem original_prefix_cells (width : List Bool) (a M u : ℕ) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun z=>z.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial\n        (tape (denominator width a M u t).toList) (unary (multiplicity a M u t.val)) width)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      cellsPolynomial (denominator width a M u t).toList (multiplicity a M u t.val) width :=\n  machine_prefix_cells _ _ _ fuel cfg hr\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseOriginal\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseOuter":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseOuterView\n/-! # Whole actual coefficient-acquisition loop driven by the original physical q markers -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseOuter\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseCalls SemiprimeD1StackNormalizedInverseReadBuffers\nopen SemiprimeD1StackNormalizedInverseCoefficient SemiprimeD1StackNormalizedInverseOuterView\nopen SemiprimeD1StackProcedureTrace\n/-- Proof-only exact acquired prefix, not a runtime list/value supplier. -/\ndef more (a : List SemiprimeRationalBits.RationalWord) (width : List Bool) :\n    ℕ→ℕ→List SemiprimeRationalBits.RationalWord→List SemiprimeRationalBits.RationalWord\n  | 0,_,reversed=>reversed\n  | remaining+1,built,reversed=>more a width remaining (built+1) (nextWord width a reversed built::reversed)\n/-- The actual remaining-pop, complete coefficient trace and built-push caps are summed recursively. -/\ndef outerBound (a : List SemiprimeRationalBits.RationalWord) (q : ℕ) (width : List Bool) :\n    ℕ→ℕ→List SemiprimeRationalBits.RationalWord→ℕ\n  | 0,_,_=>1\n  | remaining+1,built,reversed=>1+coefficientBound (outer a q width remaining built reversed) a reversed width built+1+\n      outerBound a q width remaining (built+1) (nextWord width a reversed built::reversed)\n/-- Complete real outer loop: each new coefficient is parsed/computed/framed before its count marker is pushed. -/\ntheorem outer_run (a : List SemiprimeRationalBits.RationalWord) (q : ℕ) (width : List Bool)\n    (remaining built : ℕ) (reversed : List SemiprimeRationalBits.RationalWord) (hn : 0<built) :\n    ∃t≤outerBound a q width remaining built reversed,\n      Runs program t (ctl .outer) (store (outer a q width remaining built reversed)) (ctl .finalTag)\n        (store (outer a q width 0 (built+remaining) (more a width remaining built reversed))) := by\n  induction remaining generalizing built reversed with\n  | zero=>\n    have h:=PTrace.pop_run (ctl .outer) (ctl .finalTag) (ctl (.abort 0)) (ctl .copyTerms) (aux .remaining)\n      (store (outer a q width 0 built reversed)) [] rfl rfl\n    change Runs program 1 _ _ _ (Function.update (store (outer a q width 0 built reversed)) (aux .remaining) (unary 0)) at h\n    rw [update_remaining] at h\n    refine ⟨1,le_rfl,?_⟩\n    exact h\n  | succ remaining ih=>\n    have h0:=PTrace.pop_run (ctl .outer) (ctl .finalTag) (ctl (.abort 0)) (ctl .copyTerms) (aux .remaining)\n      (store (outer a q width (remaining+1) built reversed)) (true::unary remaining) rfl\n      (by change unary (remaining+1)=true::unary remaining;exact List.replicate_succ)\n    simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n    rw [update_remaining] at h0\n    obtain ⟨t1,ht1,h1⟩:=coefficient_run (outer a q width remaining built reversed) a reversed width built hn\n      rfl rfl rfl rfl rfl rfl rfl rfl rfl rfl rfl rfl rfl\n    have h2:=PTrace.push_run (ctl .bump) (ctl .outer) (aux .built) true\n      (store (SemiprimeD1StackNormalizedInverseCoefficient.result (outer a q width remaining built reversed)\n        (nextWord width a reversed built))) rfl\n    change Runs program 1 _ _ _ (Function.update\n      (store (SemiprimeD1StackNormalizedInverseCoefficient.result (outer a q width remaining built reversed)\n        (nextWord width a reversed built))) (aux .built) (true::unary built)) at h2\n    rw [update_built] at h2\n    obtain ⟨t3,ht3,h3⟩:=ih (built+1) (nextWord width a reversed built::reversed) (by omega)\n    have h:=PTrace.join (PTrace.join (PTrace.join h0 h1) h2) h3\n    refine ⟨1+t1+1+t3,?_,?_⟩\n    · change 1+t1+1+t3≤1+coefficientBound (outer a q width remaining built reversed) a reversed width built+1+\n        outerBound a q width remaining (built+1) (nextWord width a reversed built::reversed)\n      omega\n    · have he : built+(remaining+1)=(built+1)+remaining := by omega\n      simpa only [more,he] using h\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseOuter\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseReadFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInversePrimitives\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseReadBuffers\n/-! # Two real signed/denominator field parses, with both actual validity pops -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseReadFields\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseReadBuffers SemiprimeD1StackNormalizedInversePrimitives\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- The next instruction is selected only by the static take/skip bit. -/\ndef next (part : ReadSite) (take : Bool) : Label :=\n  .read part (if take then .drainReader else .clearSigned)\n/-- Both actual field parsers consume their real TRUE flags, retaining every other physical word. -/\ntheorem fields_run (part : ReadSite) (take : Bool) (w : Words)\n    (word : SemiprimeRationalBits.RationalWord) (tail todo : List Bool)\n    (hn : w.registers (readReg part,false)=[]) (hd : w.registers (readReg part,true)=[])\n    (hs : w.auxiliary .fieldFrameScratch=[]) (hv : w.auxiliary .valid=[]) :\n    Runs program (8*((signed word).length+word.denominator.length)+16)\n      (.read part (.field take false))\n      (store (buffers w (frame (signed word) (frame word.denominator tail)) todo))\n      (next part take) (store (buffers (putReg w (readReg part) word) tail todo)) := by\n  let first:=buffers w (frame (signed word) (frame word.denominator tail)) todo\n  let middle : Words := buffers {w with registers:=Function.update w.registers (readReg part,false) (signed word)}\n    (frame word.denominator tail) todo\n  have h0:=field_read (.read part false) (.read part (.field take false))\n    (.read part (.valid take false)) (.read part (.field take true)) (.read part .failed)\n    rfl rfl (store first) (signed word) (frame word.denominator tail) rfl hs hn hv\n  have he0 : Function.update (Function.update (store first) (fieldInput (.read part false))\n      (frame word.denominator tail)) (fieldOutput (.read part false)) (signed word)=store middle := by\n    rw [show fieldInput (.read part false)=aux .reader from rfl,\n      show fieldOutput (.read part false)=reg (readReg part) false from rfl,\n      update_reader,update_register]\n    rfl\n  rw [he0] at h0\n  have h1:=field_read (.read part true) (.read part (.field take true))\n    (.read part (.valid take true)) (next part take) (.read part .failed)\n    rfl (by cases take <;> rfl) (store middle) word.denominator tail rfl hs\n    (by\n      change Function.update w.registers (readReg part,false) (signed word) (readReg part,true)=[]\n      simpa only [Function.update_apply,Prod.mk.injEq,eq_self,true_and,Bool.true_eq_false,ite_false] using hd) hv\n  have he1 : Function.update (Function.update (store middle) (fieldInput (.read part true)) tail)\n      (fieldOutput (.read part true)) word.denominator=\n      store (buffers (putReg w (readReg part) word) tail todo) := by\n    rw [show fieldInput (.read part true)=aux .reader from rfl,\n      show fieldOutput (.read part true)=reg (readReg part) true from rfl,\n      update_reader,update_register]\n    rfl\n  rw [he1] at h1\n  have h:=join h0 h1\n  convert h using 1; omega\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseReadFields\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseSeed":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseCalls\n/-! # Nine actual literal ONE-row bytes, independent of the denominator and W -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseSeed\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseCalls SemiprimeD1StackProcedureTrace\n/-- The native initial ONE is acquired by nine actual pushes even when W=0; a0 is never read. -/\ntheorem one_run (w : Words) :\n    Runs program 9 (ctl (.seedOne 0)) (store w) (ctl .bump)\n      (store {w with auxiliary:=Function.update w.auxiliary .prefixReverse (row SemiprimeJetBits.oneWord (w.auxiliary .prefixReverse))}) := by\n  let w1 : Words := {w with auxiliary:=Function.update w.auxiliary .prefixReverse (false::w.auxiliary .prefixReverse)}\n  have h0:=PTrace.push_run (ctl (.seedOne 0)) (ctl (.seedOne 1)) (aux .prefixReverse) false (store w) rfl\n  change Runs program 1 _ _ _ (Function.update (store w) (aux .prefixReverse) (false::w.auxiliary .prefixReverse)) at h0\n  rw [update_aux] at h0\n  let w2 : Words := {w1 with auxiliary:=Function.update w1.auxiliary .prefixReverse (true::w1.auxiliary .prefixReverse)}\n  have h1:=PTrace.push_run (ctl (.seedOne 1)) (ctl (.seedOne 2)) (aux .prefixReverse) true (store w1) rfl\n  change Runs program 1 _ _ _ (Function.update (store w1) (aux .prefixReverse) (true::w1.auxiliary .prefixReverse)) at h1\n  rw [update_aux] at h1\n  let w3 : Words := {w2 with auxiliary:=Function.update w2.auxiliary .prefixReverse (true::w2.auxiliary .prefixReverse)}\n  have h2:=PTrace.push_run (ctl (.seedOne 2)) (ctl (.seedOne 3)) (aux .prefixReverse) true (store w2) rfl\n  change Runs program 1 _ _ _ (Function.update (store w2) (aux .prefixReverse) (true::w2.auxiliary .prefixReverse)) at h2\n  rw [update_aux] at h2\n  let w4 : Words := {w3 with auxiliary:=Function.update w3.auxiliary .prefixReverse (false::w3.auxiliary .prefixReverse)}\n  have h3:=PTrace.push_run (ctl (.seedOne 3)) (ctl (.seedOne 4)) (aux .prefixReverse) false (store w3) rfl\n  change Runs program 1 _ _ _ (Function.update (store w3) (aux .prefixReverse) (false::w3.auxiliary .prefixReverse)) at h3\n  rw [update_aux] at h3\n  let w5 : Words := {w4 with auxiliary:=Function.update w4.auxiliary .prefixReverse (true::w4.auxiliary .prefixReverse)}\n  have h4:=PTrace.push_run (ctl (.seedOne 4)) (ctl (.seedOne 5)) (aux .prefixReverse) true (store w4) rfl\n  change Runs program 1 _ _ _ (Function.update (store w4) (aux .prefixReverse) (true::w4.auxiliary .prefixReverse)) at h4\n  rw [update_aux] at h4\n  let w6 : Words := {w5 with auxiliary:=Function.update w5.auxiliary .prefixReverse (true::w5.auxiliary .prefixReverse)}\n  have h5:=PTrace.push_run (ctl (.seedOne 5)) (ctl (.seedOne 6)) (aux .prefixReverse) true (store w5) rfl\n  change Runs program 1 _ _ _ (Function.update (store w5) (aux .prefixReverse) (true::w5.auxiliary .prefixReverse)) at h5\n  rw [update_aux] at h5\n  let w7 : Words := {w6 with auxiliary:=Function.update w6.auxiliary .prefixReverse (false::w6.auxiliary .prefixReverse)}\n  have h6:=PTrace.push_run (ctl (.seedOne 6)) (ctl (.seedOne 7)) (aux .prefixReverse) false (store w6) rfl\n  change Runs program 1 _ _ _ (Function.update (store w6) (aux .prefixReverse) (false::w6.auxiliary .prefixReverse)) at h6\n  rw [update_aux] at h6\n  let w8 : Words := {w7 with auxiliary:=Function.update w7.auxiliary .prefixReverse (true::w7.auxiliary .prefixReverse)}\n  have h7:=PTrace.push_run (ctl (.seedOne 7)) (ctl (.seedOne 8)) (aux .prefixReverse) true (store w7) rfl\n  change Runs program 1 _ _ _ (Function.update (store w7) (aux .prefixReverse) (true::w7.auxiliary .prefixReverse)) at h7\n  rw [update_aux] at h7\n  let w9 : Words := {w8 with auxiliary:=Function.update w8.auxiliary .prefixReverse (true::w8.auxiliary .prefixReverse)}\n  have h8:=PTrace.push_run (ctl (.seedOne 8)) (ctl .bump) (aux .prefixReverse) true (store w8) rfl\n  change Runs program 1 _ _ _ (Function.update (store w8) (aux .prefixReverse) (true::w8.auxiliary .prefixReverse)) at h8\n  rw [update_aux] at h8\n  have h:=(PTrace.join (PTrace.join (PTrace.join (PTrace.join (PTrace.join (PTrace.join (PTrace.join (PTrace.join h0 h1) h2) h3) h4) h5) h6) h7) h8)\n  have he : w9={w with auxiliary:=Function.update w.auxiliary .prefixReverse (row SemiprimeJetBits.oneWord (w.auxiliary .prefixReverse))} := by\n    dsimp only [w9,w8,w7,w6,w5,w4,w3,w2,w1]\n    simp only [Function.update_self,Function.update_idem]\n    rfl\n  change Runs program 9 _ _ _ (store w9) at h\n  rw [he] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseSeed\n","RiemannGaussian.SemiprimeD1StackOldVertexStreamRoles":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildLiftVertexMeaning\nimport RiemannGaussian.SemiprimeD1StackChildUnitVertexMeaning\nimport RiemannGaussian.SemiprimeD1StackVertexRecordSpliceStorage\n/-! # Complete literal old-vertex stream workspace and immutable header aliases\nThese are fixed source locations only. Current parent records and acquired\nactivity/scope/order streams are physical words. No table dictionary, native\ngetter or data-valued instruction label is introduced by the role inventory.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOldVertexStreamRoles\nnamespace A\nexport SemiprimeD1StackChildLiftVertex (Stack table aux stack_card)\nend A\nnamespace U\nexport SemiprimeD1StackChildUnitVertex (Stack context unitWork aux stack_card)\nend U\nnamespace V\nexport SemiprimeD1StackVectorTable (checker template counter aux)\nend V\nnamespace E\nexport SemiprimeD1StackChildTableEntry (Stack context aux)\nend E\nnamespace J\nexport SemiprimeD1StackJetContext (axesCache precisionBits)\nend J\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack)\nend F\n/-- The exact whole169-word activity-source allocation, described without importing an unsealed caller. -/\nabbrev ChoiceStack:=A.Stack⊕(U.Stack⊕Unit)\n/-- Eight immutable inputs, four actual readers, old-port disposal and real logging/copy/status work. -/\ninductive Aux where\n  | records | activation | scopes | orders | oldAxes | oldPrecision | newAxes | newPrecision\n  | recordsReader | activationReader | scopesReader | ordersReader | oldPorts | history | output | copyScratch | success\n  deriving DecidableEq,Repr\ninstance auxFintype : Fintype Aux:=Fintype.ofList\n  [.records,.activation,.scopes,.orders,.oldAxes,.oldPrecision,.newAxes,.newPrecision,\n    .recordsReader,.activationReader,.scopesReader,.ordersReader,.oldPorts,.history,.output,.copyScratch,.success]\n    (by intro k;cases k <;> simp)\n/-- All169 source words, all4 parser words and all17 enclosing words, including every displaced shadow. -/\nabbrev Stack:=ChoiceStack⊕(F.Stack⊕Aux)\n/-- Dedicated complete activity-source work bank; its four displaced headers remain counted. -/\ndef work (k : ChoiceStack) : Stack:=.inl k\n/-- All actual parser work and both unused input/output shadows. -/\ndef fieldWork (k : F.Stack) : Stack:=.inr (.inl k)\n/-- Fixed actual enclosing-stream address. -/\ndef aux (k : Aux) : Stack:=.inr (.inr k)\n/-- The actual old/new original axis-header locations in the whole active source. -/\ndef axesRole (new : Bool) : ChoiceStack:=.inl (A.table (V.template (E.context new J.axesCache)))\n/-- The actual old/new original binary-precision locations in that source. -/\ndef precisionRole (new : Bool) : ChoiceStack:=.inl (A.table (V.template (E.context new J.precisionBits)))\n/-- All four caller input headers are read IN PLACE by the included source; its displaced shadows are empty. -/\ndef choice (k : ChoiceStack) : Stack:=\n  if k=axesRole false then aux .oldAxes\n  else if k=precisionRole false then aux .oldPrecision\n  else if k=axesRole true then aux .newAxes\n  else if k=precisionRole true then aux .newPrecision else work k\n/-- Table/counting roles are literal fixed constructors, never runtime graph indices. -/\ndef tableRoles : List SemiprimeD1StackChildLiftTable.Stack:=\n  SemiprimeD1StackChildLiftTable.roles.map V.checker++\n    SemiprimeD1StackChildLiftTable.roles.map V.template++\n    ([.bank,.reader,.count,.word,.fieldScratch,.valid,.copyScratch] : List SemiprimeD1StackDigitCount.Stack).map V.counter++\n    [V.aux .prefix,V.aux .work,V.aux .scratch,V.aux .reversed,V.aux .output]\n/-- Both complete active-record words and every original table word are counted. -/\ndef activeRoles : List A.Stack:=tableRoles.map A.table++[A.aux .record,A.aux .scratch]\n/-- Full literal dense-unit arithmetic allocation, including precision/work and all nine vector roles. -/\ndef unitRoles : List SemiprimeD1StackJetUnit.Stack:=\n  [.inl (.inl .left),.inl (.inl .right),.inl (.inl .scratch),.inl (.inl .output),\n    .inl (.inr false),.inl (.inr true),.inr .leftTape,.inr .rightTape,.inr .rank,.inr .active,\n    .inr .reverseOut,.inr .output,.inr .valid,.inr .parser,.inr .copy]\n/-- The inactive source retains both full context/unit banks and both new record words. -/\ndef inactiveRoles : List U.Stack:=SemiprimeD1StackChildLiftTable.contextRoles.map U.context++\n  unitRoles.map U.unitWork++[U.aux .record,U.aux .scratch]\n/-- Every actual role in the169-word branch source, in a constant literal cleanup order. -/\ndef choiceRoles : List ChoiceStack:=activeRoles.map Sum.inl++inactiveRoles.map (fun k=>.inr (.inl k))++[.inr (.inr ())]\n/-- No source/template/helper/framing/activity shadow is omitted. -/\ntheorem choice_roles_length : choiceRoles.length=169:=by decide\n/-- No physical source word is counted twice. -/\ntheorem choice_roles_nodup : choiceRoles.Nodup:=by decide\n/-- The complete physical activity-source allocation is169 independent of all inputs. -/\ntheorem choice_card : Fintype.card ChoiceStack=169:=by\n  have h : Fintype.card Unit=1:=by decide\n  rw [Fintype.card_sum,A.stack_card,Fintype.card_sum,U.stack_card,h]\n/-- Literal inventory cardinality proves complete169-role coverage. -/\ntheorem choice_roles_complete (k : ChoiceStack) : k∈choiceRoles:=by\n  have h : choiceRoles.toFinset.card=Fintype.card ChoiceStack:=by\n    rw [List.toFinset_card_of_nodup choice_roles_nodup,choice_roles_length,choice_card]\n  have hu:=Finset.eq_univ_of_card choiceRoles.toFinset h\n  apply List.mem_toFinset.mp\n  rw [hu]\n  exact Finset.mem_univ k\n/-- Fixed cleanup positions are bounded literal code sites, never acquired port IDs. -/\ndef role (i : Fin 169) : ChoiceStack:=choiceRoles[i.val]'(by rw [choice_roles_length];exact i.isLt)\n/-- Every actual included-source word is cleaned exactly once. -/\ntheorem role_injective : Function.Injective role:=by\n  intro a b h\n  apply Fin.ext\n  exact choice_roles_nodup.getElem_inj.mp h\n/-- Every physical work/shadow word has an actual bounded cleanup position. -/\ntheorem role_complete (k : ChoiceStack) : ∃i : Fin 169,role i=k:=by\n  obtain ⟨i,hi,he⟩:=List.mem_iff_getElem.mp (choice_roles_complete k)\n  exact ⟨⟨i,by rw [←choice_roles_length];exact hi⟩,he⟩\n/-- Sharing four original headers preserves distinct addresses inside the included source. -/\ntheorem choice_injective : Function.Injective choice:=by decide\n/-- Every data role, including all displaced source/parser shadows and all input caches, is counted. -/\ntheorem stack_card : Fintype.card Stack=190:=by\n  have hf : Fintype.card F.Stack=4:=by decide\n  have ha : Fintype.card Aux=17:=by decide\n  rw [Fintype.card_sum,choice_card,Fintype.card_sum,hf,ha]\nend RiemannGaussian.SemiprimeD1StackOldVertexStreamRoles\n","RiemannGaussian.SemiprimeD1StackOldVertexStreamSetup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOldVertexStreamView\n/-! # All four physical stream copies before the first vertex read -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOldVertexStreamSetup\nopen SemiprimeD1StackOldVertexStream SemiprimeD1StackOldVertexStreamRoles\nopen SemiprimeD1StackOldVertexStreamView SemiprimeD1StackProcedureTrace\nnamespace Q\nexport SemiprimeD1StackOldVertexStreamPrimitives (copy_call join)\nend Q\n/-- Actual four reached readers; no parsed table, scope, order or activity singleton is supplied. -/\ndef loaded (i : Inputs) : Words:={empty with records:=i.records,activation:=i.activation,scopes:=i.scopes,orders:=i.orders}\n/-- Total physical input bytes copied; all four immutable original words survive. -/\ndef streamBytes (i : Inputs) : ℕ:=i.records.length+i.activation.length+i.scopes.length+i.orders.length\n/-- SAME actual source pays all four preserving copies once, with every restoration loop and call/return. -/\ntheorem source_run (i : Inputs) : Runs program (5*streamBytes i+16) (.local .start) (inputData i)\n    (.local .recordTag) (data i (loaded i)):=by\n  let w0:=empty\n  let w1:={w0 with records:=i.records}\n  let w2:={w1 with activation:=i.activation}\n  let w3:={w2 with scopes:=i.scopes}\n  let w4:={w3 with orders:=i.orders}\n  have h0 : Runs program (5*i.records.length+4) (.local .start) (data i w0)\n      (.local .copyActivation) (data i w1):=by\n    have h:=Q.copy_call .records (.local .start) (.local .copyActivation) rfl (data i w0) i.records [] rfl rfl rfl\n    change Runs program _ _ _ _ (Function.update (data i w0) (aux .recordsReader) (i.records++[])) at h\n    simpa only [List.append_nil,update_records] using h\n  have h1 : Runs program (5*i.activation.length+4) (.local .copyActivation) (data i w1)\n      (.local .copyScopes) (data i w2):=by\n    have h:=Q.copy_call .activation (.local .copyActivation) (.local .copyScopes) rfl (data i w1) i.activation [] rfl rfl rfl\n    change Runs program _ _ _ _ (Function.update (data i w1) (aux .activationReader) (i.activation++[])) at h\n    simpa only [List.append_nil,update_activation] using h\n  have h2 : Runs program (5*i.scopes.length+4) (.local .copyScopes) (data i w2)\n      (.local .copyOrders) (data i w3):=by\n    have h:=Q.copy_call .scopes (.local .copyScopes) (.local .copyOrders) rfl (data i w2) i.scopes [] rfl rfl rfl\n    change Runs program _ _ _ _ (Function.update (data i w2) (aux .scopesReader) (i.scopes++[])) at h\n    simpa only [List.append_nil,update_scopes] using h\n  have h3 : Runs program (5*i.orders.length+4) (.local .copyOrders) (data i w3)\n      (.local .recordTag) (data i w4):=by\n    have h:=Q.copy_call .orders (.local .copyOrders) (.local .recordTag) rfl (data i w3) i.orders [] rfl rfl rfl\n    change Runs program _ _ _ _ (Function.update (data i w3) (aux .ordersReader) (i.orders++[])) at h\n    simpa only [List.append_nil,update_orders] using h\n  have h:=Q.join (Q.join (Q.join h0 h1) h2) h3\n  rw [initial_data]\n  have hc : 5*streamBytes i+16=(5*i.records.length+4+(5*i.activation.length+4)+(5*i.scopes.length+4))+(5*i.orders.length+4):=by\n    unfold streamBytes\n    omega\n  rw [hc]\n  exact h\nend RiemannGaussian.SemiprimeD1StackOldVertexStreamSetup\n","RiemannGaussian.SemiprimeD1StackOrdinalBankMoves":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOrdinalBankCalls\n/-! # Physical width allocation, wrapped-word restoration and final materialization -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackOrdinalBankMoves\nopen SemiprimeD1StackOrdinalBank SemiprimeD1StackOrdinalBankCalls\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\nnamespace B\nexport SemiprimeD1StackBytecode (execute choose)\nend B\n\n/-- Physically consume the copied tally to allocate each zero counter bit. -/\ntheorem zero_run (todo word tally : List Bool) :\n    Runs program (2*todo.length+1) (.inl .makeZero) (data word [] [] [] [] tally [] todo [])\n      (.inl .copyRemaining) (data (List.replicate todo.length false++word) [] [] [] [] tally [] [] []) := by\n  induction todo generalizing word with\n  | nil =>\n    apply one_base program _ _ (.pop zeroRemaining (.inl .copyRemaining) (.inl .pushZero) (.inl .pushZero)) _ _ rfl\n    · rfl\n    · funext k; rcases k with k|k <;> cases k <;> simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data,zeroRemaining]\n  | cons bit todo ih =>\n    have h0 : Runs program 1 (.inl .makeZero) (data word [] [] [] [] tally [] (bit::todo) [])\n        (.inl .pushZero) (data word [] [] [] [] tally [] todo []) := by\n      apply one_base program _ _ (.pop zeroRemaining (.inl .copyRemaining) (.inl .pushZero) (.inl .pushZero)) _ _ rfl\n      · cases bit <;> rfl\n      · cases bit <;> funext k <;> rcases k with k|k <;> cases k <;> rfl\n    have h1 : Runs program 1 (.inl .pushZero) (data word [] [] [] [] tally [] todo [])\n        (.inl .makeZero) (data (false::word) [] [] [] [] tally [] todo []) := by\n      apply one_base program _ _ (.push counter false (.inl .makeZero)) _ _ rfl\n      · rfl\n      · funext k; rcases k with k|k <;> cases k <;> simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data,counter]\n    have h:=h0.trans (h1.trans (ih (false::word)))\n    simpa only [List.length_cons,List.replicate_succ',List.append_assoc,List.singleton_append,\n      show 1+(1+(2*todo.length+1))=2*(todo.length+1)+1 by omega] using h\n\n/-- Physical first pass reverses the actual wrapped output into scratch. -/\ntheorem move_drain (xs scratch history output tally todo : List Bool) :\n    Runs program (2*xs.length+1) (.inl .moveDrain) (data [] scratch xs history output tally todo [] [])\n      (.inl .restore) (data [] (xs.reverse++scratch) [] history output tally todo [] []) := by\n  induction xs generalizing scratch with\n  | nil =>\n    apply one_base program _ _ (.pop (.inl .next) (.inl .restore) (.inl (.movePush false)) (.inl (.movePush true))) _ _ rfl\n    · rfl\n    · funext k; rcases k with k|k <;> cases k <;> simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data]\n  | cons bit xs ih =>\n    have h0 : Runs program 1 (.inl .moveDrain) (data [] scratch (bit::xs) history output tally todo [] [])\n        (.inl (.movePush bit)) (data [] scratch xs history output tally todo [] []) := by\n      apply one_base program _ _ (.pop (.inl .next) (.inl .restore) (.inl (.movePush false)) (.inl (.movePush true))) _ _ rfl\n      · cases bit <;> rfl\n      · cases bit <;> funext k <;> rcases k with k|k <;> cases k <;>\n          simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data]\n    have h1 : Runs program 1 (.inl (.movePush bit)) (data [] scratch xs history output tally todo [] [])\n        (.inl .moveDrain) (data [] (bit::scratch) xs history output tally todo [] []) := by\n      apply one_base program _ _ (.push (.inl .scratch) bit (.inl .moveDrain)) _ _ rfl\n      · rfl\n      · funext k; rcases k with k|k <;> cases k <;> simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data]\n    have h:=h0.trans (h1.trans (ih (bit::scratch)))\n    simpa only [List.length_cons,List.reverse_cons,List.append_assoc,List.singleton_append,\n      show 1+(1+(2*xs.length+1))=2*(xs.length+1)+1 by omega] using h\n\n/-- Physical second pass restores little-endian order, without a word getter. -/\ntheorem restore_run (xs word history output tally todo : List Bool) :\n    Runs program (2*xs.length+1) (.inl .restore) (data word xs [] history output tally todo [] [])\n      (.inl .loop) (data (xs.reverse++word) [] [] history output tally todo [] []) := by\n  induction xs generalizing word with\n  | nil =>\n    apply one_base program _ _ (.pop (.inl .scratch) (.inl .loop) (.inl (.restorePush false)) (.inl (.restorePush true))) _ _ rfl\n    · rfl\n    · funext k; rcases k with k|k <;> cases k <;> simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data]\n  | cons bit xs ih =>\n    have h0 : Runs program 1 (.inl .restore) (data word (bit::xs) [] history output tally todo [] [])\n        (.inl (.restorePush bit)) (data word xs [] history output tally todo [] []) := by\n      apply one_base program _ _ (.pop (.inl .scratch) (.inl .loop) (.inl (.restorePush false)) (.inl (.restorePush true))) _ _ rfl\n      · cases bit <;> rfl\n      · cases bit <;> funext k <;> rcases k with k|k <;> cases k <;>\n          simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data]\n    have h1 : Runs program 1 (.inl (.restorePush bit)) (data word xs [] history output tally todo [] [])\n        (.inl .restore) (data (bit::word) xs [] history output tally todo [] []) := by\n      apply one_base program _ _ (.push counter bit (.inl .restore)) _ _ rfl\n      · rfl\n      · funext k; rcases k with k|k <;> cases k <;> simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data,counter]\n    have h:=h0.trans (h1.trans (ih (bit::word)))\n    simpa only [List.length_cons,List.reverse_cons,List.append_assoc,List.singleton_append,\n      show 1+(1+(2*xs.length+1))=2*(xs.length+1)+1 by omega] using h\n\n/-- The actual physical overflow bit is consumed; the marker loop, not overflow,\ndetermines round count. Actual ordinal words are proved nonoverflowing separately. -/\ntheorem continue_run (bit : Bool) (xs history output tally todo : List Bool) :\n    Runs program (4*xs.length+3) (.inl .popOverflow) (data [] [] (bit::xs) history output tally todo [] [])\n      (.inl .loop) (data xs [] [] history output tally todo [] []) := by\n  have h0 : Runs program 1 (.inl .popOverflow) (data [] [] (bit::xs) history output tally todo [] [])\n      (.inl .moveDrain) (data [] [] xs history output tally todo [] []) := by\n    apply one_base program _ _ (.pop (.inl .next) (.inl .abort) (.inl .moveDrain) (.inl .moveDrain)) _ _ rfl\n    · cases bit <;> rfl\n    · cases bit <;> funext k <;> rcases k with k|k <;> cases k <;>\n        simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data]\n  have h1:=move_drain xs [] history output tally todo\n  simp only [List.append_nil] at h1\n  have h2:=restore_run xs.reverse [] history output tally todo\n  have h:=h0.trans (h1.trans h2)\n  simpa only [List.append_nil,List.length_reverse,List.reverse_reverse,\n    show 1+((2*xs.length+1)+(2*xs.length+1))=4*xs.length+3 by omega] using h\n\n/-- Final counter bytes are really cleared; no leftover answer/work is projected away. -/\ntheorem clear_counter (word history output tally : List Bool) :\n    Runs program (word.length+1) (.inl .clearCounter) (data word [] [] history output tally [] [] [])\n      (.inl .seedOutput) (data [] [] [] history output tally [] [] []) := by\n  induction word with\n  | nil =>\n    apply one_base program _ _ (.pop counter (.inl .seedOutput) (.inl .clearCounter) (.inl .clearCounter)) _ _ rfl\n    · rfl\n    · funext k; rcases k with k|k <;> cases k <;> simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data,counter]\n  | cons bit word ih =>\n    have h0 : Runs program 1 (.inl .clearCounter) (data (bit::word) [] [] history output tally [] [] [])\n        (.inl .clearCounter) (data word [] [] history output tally [] [] []) := by\n      apply one_base program _ _ (.pop counter (.inl .seedOutput) (.inl .clearCounter) (.inl .clearCounter)) _ _ rfl\n      · cases bit <;> rfl\n      · cases bit <;> funext k <;> rcases k with k|k <;> cases k <;>\n          simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data,counter]\n    simpa only [List.length_cons,show 1+(word.length+1)=word.length+1+1 by omega] using h0.trans ih\n\n/-- Real nil seeding and one final reversal materialize the original ID order. -/\ntheorem finish_run (word history output tally : List Bool) :\n    Runs program (word.length+2*history.length+5) (.inl .clearCounter)\n      (data word [] [] history output tally [] [] []) (.inl .done)\n      (data [] [] [] [] (history.reverse++false::output) tally [] [] []) := by\n  have h0:=clear_counter word history output tally\n  have h1 : Runs program 1 (.inl .seedOutput) (data [] [] [] history output tally [] [] [])\n      (.inl .reverse) (data [] [] [] history (false::output) tally [] [] []) := by\n    apply one_base program _ _ (.push ids false (.inl .reverse)) _ _ rfl\n    · rfl\n    · funext k; rcases k with k|k <;> cases k <;> simp [B.execute,data,SemiprimeD1StackAssignmentLoop.data,ids]\n  have h2:=reverse_call history (false::output) tally\n  have h:=h0.trans (h1.trans h2)\n  simpa only [show (word.length+1)+(1+(2*history.length+3))=word.length+2*history.length+5 by omega] using h\n\nend RiemannGaussian.SemiprimeD1StackOrdinalBankMoves\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogueClear":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerCatalogueEmit\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogueClear\nopen SemiprimeD1StackOwnerCatalogue SemiprimeD1StackOwnerCatalogueSource\nopen SemiprimeD1StackOwnerCatalogueFields\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\n/-- Fixed mathematical inverse to the physical 47-role cleanup order. -/\ndef workRank : RecipeWork→Fin 47\n  | .inl (.mode i)=>⟨i.val,by omega⟩\n  | .inl .rt=>10\n  | .inl .width=>11\n  | .inl .qa=>12\n  | .inl .ma=>13\n  | .inl .qb=>14\n  | .inl .mb=>15\n  | .inl .tc=>16\n  | .inl .rc=>17\n  | .inl .pbc=>18\n  | .inl .aminus=>19\n  | .inl .bminus=>20\n  | .inl .dminus=>21\n  | .inl .bplus=>22\n  | .inl .slot10=>23\n  | .inl .slot11=>24\n  | .inl .slot12=>25\n  | .inl .wd=>26\n  | .inl .slot13f=>27\n  | .inl .slot13t=>28\n  | .inl .slot14t=>29\n  | .inl .slot14f=>30\n  | .inl .wb=>31\n  | .inl .divInput=>32\n  | .inl .testLeft=>33\n  | .inl .testLimit=>34\n  | .inl .smallA=>35\n  | .inl .ltArt=>36\n  | .inl .ltNext=>37\n  | .inl .tagReader=>38\n  | .inr .copyScratch=>39\n  | .inr .multiplier=>40\n  | .inr .productScratch=>41\n  | .inr .maddScratch=>42\n  | .inr .divCopy=>43\n  | .inr .divScratch=>44\n  | .inr .frameScratch=>45\n  | .inr .output=>46\n/-- Every work role is physically visited exactly once. -/\ntheorem workRole_rank (k:RecipeWork) : workRole (workRank k)=k := by\n  rcases k with k|k\n  · cases k with\n    | mode i=>fin_cases i <;> decide\n    | _=>decide\n  · cases k <;> decide\n/-- The mathematical rank agrees with each actual static cleanup call. -/\ntheorem rank_workRole (part:Fin 47) : workRank (workRole part)=part := by\n  fin_cases part <;> decide\n/-- The actual arithmetic work after n literal cleanup roles have been erased. -/\ndef workCleared (w:RecipeWork→List Bool) (n:Nat) (k:RecipeWork) : List Bool :=\n  if (workRank k).val<n then [] else w k\n/-- An actual drain changes precisely the next role in the cleanup order. -/\ntheorem workCleared_step (w:RecipeWork→List Bool) (part:Fin 47) :\n    Function.update (workCleared w part.val) (workRole part) []=workCleared w (part.val+1) := by\n  funext k\n  by_cases hk:k=workRole part\n  · subst k;simp only [Function.update_same,workCleared,rank_workRole,Nat.lt_succ_self,ite_true]\n  · have hn:(workRank k).val≠part.val:=by\n      intro h;have he:workRank k=part:=Fin.ext h\n      have hrole:=workRole_rank k\n      rw [he] at hrole\n      exact hk hrole.symm\n    simp only [Function.update_of_ne hk,workCleared]\n    split <;> split <;> simp_all <;> omega\n/-- No arithmetic payload is discarded without its real pop trace. -/\ntheorem workCleared_end (w:RecipeWork→List Bool) : workCleared w 47=fun _=>[] := by\n  funext k;exact ite_eq_left (workRank k).isLt\n/-- Static actual continuation following a work-role EOF pop. -/\ndef workNext (part:Fin 47) : Label :=\n  if h:part.val<46 then .local (.clearRecipe ⟨part.val+1,by omega⟩) else .local (.clearCache 0)\n/-- Actual one-role erasure, including the final EOF pop. -/\ntheorem work_call (s:S.Stack→List Bool) (w:RecipeWork→List Bool) (f:Fin 7→List Bool)\n    (a:Aux→List Bool) (part:Fin 47) :\n    Runs program ((w (workRole part)).length+1) (.local (.clearRecipe part))\n      (data s (workCleared w part.val) f a) (workNext part)\n      (data s (workCleared w (part.val+1)) f a) := by\n  let before:=data s (workCleared w part.val) f a\n  have hv:before (work (workRole part))=w (workRole part):=by\n    simp only [before,data_work,workCleared,rank_workRole,Nat.lt_irrefl,ite_false]\n  have hi:Function.update before (work (workRole part)) (w (workRole part))=before:=by\n    rw [←hv];exact Function.update_eq_self _ _\n  have h:=SemiprimeD1StackPhysicalLoops.drain program (.local (.clearRecipe part))\n    (workNext part) (work (workRole part)) rfl before (w (workRole part))\n  rw [hi] at h\n  simpa only [before,update_work,workCleared_step] using h\n/-- Exact static position within all 47 actual cleanup loops. -/\ndef workPC (n:Nat) : Label :=\n  if h:n<47 then .local (.clearRecipe ⟨n,h⟩) else .local (.clearCache 0)\n/-- Chronological sum of the actual erased work payload lengths and EOF pops. -/\ndef workTime (w:RecipeWork→List Bool) : Nat→Nat\n  | 0=>0\n  | n+1=>workTime w n+(w (workRole ⟨n%47,Nat.mod_lt _ (by omega)⟩)).length+1\n/-- Every real role drain advances the same actual cleanup source. -/\ntheorem work_step (s:S.Stack→List Bool) (w:RecipeWork→List Bool) (f:Fin 7→List Bool)\n    (a:Aux→List Bool) (n:Nat) (hn:n<47) :\n    Runs program ((w (workRole ⟨n,hn⟩)).length+1) (workPC n)\n      (data s (workCleared w n) f a) (workPC (n+1)) (data s (workCleared w (n+1)) f a) := by\n  have h:=work_call s w f a ⟨n,hn⟩\n  have hp:workNext ⟨n,hn⟩=workPC (n+1):=by\n    unfold workNext workPC\n    by_cases hn':n<46\n    · simp only [hn',show n+1<47 by omega,dite_eq_left]\n    · have he:n=46:=by omega\n      subst n;rfl\n  rw [hp] at h\n  simpa only [workPC,dite_eq_left hn] using h\n/-- Exact actual trace erasing the first n fixed arithmetic roles. -/\ntheorem work_prefix (s:S.Stack→List Bool) (w:RecipeWork→List Bool) (f:Fin 7→List Bool)\n    (a:Aux→List Bool) (n:Nat) (hn:n≤47) :\n    Runs program (workTime w n) (workPC 0) (data s (workCleared w 0) f a)\n      (workPC n) (data s (workCleared w n) f a) := by\n  induction n with\n  | zero=>exact SemiprimeD1StackProcedureTrace.runs_refl program _ _\n  | succ n ih=>\n    have hlt:n<47:=by omega\n    have hm:n%47=n:=Nat.mod_eq_of_lt hlt\n    have h:=runs_trans program _ _ _ _ _ _ _ _ (ih (by omega)) (work_step s w f a n hlt)\n    simpa only [workTime,hm,Nat.add_assoc] using h\n/-- Complete physical cleanup of every arithmetic register, scratch and output word. -/\ntheorem work_run (s:S.Stack→List Bool) (w:RecipeWork→List Bool) (f:Fin 7→List Bool)\n    (a:Aux→List Bool) :\n    Runs program (workTime w 47) (.local (.clearRecipe 0)) (data s w f a)\n      (.local (.clearCache 0)) (data s (fun _=>[]) f a) := by\n  have h:=work_prefix s w f a 47 (by omega)\n  have hz:workCleared w 0=w:=by funext k;exact ite_eq_right (Nat.not_lt_zero _)\n  have hp0:workPC 0=.local (.clearRecipe 0):=by simp [workPC]\n  have hp47:workPC 47=.local (.clearCache 0):=by simp [workPC]\n  simpa only [hz,hp0,hp47,workCleared_end] using h\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogueClear\n","RiemannGaussian.SemiprimeD1StackOwnerPrefixBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerPrefixExecution\n/-! # Closed physical owner-prefix costs and all ten roles/real return cells\nThe scan consumes original records; it never asks for an allowed-value answer.\nIts cost is linear in prefix bytes times actual binary query-key width.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackOwnerPrefixBounds\nopen SemiprimeD1StackOwnerPrefix SemiprimeD1StackOwnerPrefixExecution\nopen SemiprimeD1OwnerPrefixBits (records records_length scan_original)\n\n/-- All actual field/copy/equality/read branches summed over original records. -/\ntheorem loopTime_le (query : List Bool) (rows : List (List Bool×Bool)) :\n    loopTime query rows≤10*(rows.map (fun x=>x.1.length)).sum+(7*query.length+24)*rows.length+3 := by\n  induction rows with\n  | nil=>simp only [loopTime,List.map_nil,List.sum_nil,List.length_nil,Nat.mul_zero,Nat.zero_add,le_refl]\n  | cons row rows ih=>\n    rcases row with ⟨key,value⟩\n    have he:=SemiprimeD1StackWordEqualExecution.executionTime_le key query\n    simp only [loopTime,List.map_cons,List.sum_cons,List.length_cons]\n    nlinarith\n/-- Fixed SAME-program bound before every binary key and physical prefix. -/\ndef runBound (query : List Bool) (rows : List (List Bool×Bool)) : ℕ :=\n  100*(query.length+1)*((records rows []).length+1)\n/-- The exact source trace, including every call and halt, obeys this bound. -/\ntheorem time_le (query : List Bool) (rows : List (List Bool×Bool)) : loopTime query rows+1≤runBound query rows := by\n  have h:=loopTime_le query rows\n  unfold runBound\n  rw [records_length]\n  simp only [List.length_nil,Nat.add_zero]\n  let K:=100*(query.length+1)\n  let s:=(rows.map (fun x=>x.1.length)).sum\n  have hs:10*s≤K*(2*s) := by\n    calc\n      _ ≤ (K*2)*s := Nat.mul_le_mul_right s (by dsimp [K];omega)\n      _ = _ := by ring\n  have hr:(7*query.length+24)*rows.length≤K*(3*rows.length) := by\n    calc\n      _ ≤ (K*3)*rows.length := Nat.mul_le_mul_right rows.length (by dsimp [K];omega)\n      _ = _ := by ring\n  have hc:4≤K*2 := by dsimp [K];omega\n  calc\n    _ ≤ 10*s+(7*query.length+24)*rows.length+4 := by omega\n    _ ≤ K*(2*s)+K*(3*rows.length)+K*2 := Nat.add_le_add (Nat.add_le_add hs hr) hc\n    _ = _ := by dsimp [K,s];ring\n/-- Actual complete source execution, retaining every unread suffix byte. -/\ndef sourceScan (query : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool) :\n    StateTransition.EvalsToInTime (C.step program) (initial query (records rows tail))\n      (some (done query rows tail)) (runBound query rows) :=\n  ⟨⟨_,source_run query rows tail⟩,time_le query rows⟩\n/-- Genuine SAME finite machine with no source-length/count/equality premise. -/\ndef machineScan (query : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial query (records rows tail)))\n      (some (SemiprimeD1StackCalls.configuration (done query rows tail))) (runBound query rows) :=\n  SemiprimeD1StackCalls.evalsCorrect (Sum.inr Aux.reader : Stack) (Sum.inr Aux.output : Stack)\n    (Label.loop true true) program _ _ _\n    (sourceScan query rows tail)\n/-- Every original finite-wire prefix, including duplicate/conflicting records,\nproduces the exact original pair of compatible owner values. -/\ntheorem output_original {n : ℕ} (wire : Fin n) (fixed : List (Fin n×Bool))\n    (encode : Fin n→List Bool) (he : ∀i,SemiprimeBitArithmetic.bitValue (encode i)=i.val)\n    (tail : List Bool) :\n    (done (encode wire) (fixed.map (fun x=>(encode x.1,x.2))) tail).data (.inr .output)=\n      [SemiprimeD1RootOwnerTables.allowed fixed wire false,SemiprimeD1RootOwnerTables.allowed fixed wire true] := by\n  change [(SemiprimeD1OwnerPrefixBits.scan _ _ true true).1,(SemiprimeD1OwnerPrefixBits.scan _ _ true true).2]=_\n  rw [scan_original wire fixed encode he]\n/-- No successful physical prefix extends beyond the actual literal halt. -/\ntheorem prefix_fuel_le (query : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool)\n    (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial query (records rows tail))=some out) : fuel≤loopTime query rows+1 := by\n  by_contra hn\n  have he:fuel=(loopTime query rows+1)+(1+(fuel-(loopTime query rows+2))) := by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,source_run,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add] at hr\n  have hz:C.run program 1 (done query rows tail)=none := rfl\n  rw [hz,Option.bind_none] at hr\n  cases hr\n/-- EVERY prefix counts all ten actual Boolean roles, all unread suffix/cache\nbytes and all real finite-label return cells; no pointer/stack is omitted. -/\ntheorem prefix_cells (query : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool)\n    (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial query (records rows tail))=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤\n      11*(query.length+(records rows tail).length+runBound query rows) := by\n  let I:=query.length+(records rows tail).length\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel I _ out (by\n    intro k;rcases k with k|k <;> cases k <;> simp [initial,data,SemiprimeD1StackAdder.store,I]) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k : Stack,(out.data k).length)≤10*(I+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(I+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=(prefix_fuel_le query rows tail fuel out hr).trans (time_le query rows)\n  change _≤11*(I+runBound query rows)\n  omega\n/-- The same all-role/return inventory for the genuine compiled machine. -/\ntheorem machine_prefix_cells (query : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool)\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial query (records rows tail))))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      11*(query.length+(records rows tail).length+runBound query rows) := by\n  have he:=SemiprimeD1StackCalls.run_correct (.inr .reader) (.inr .output) (.loop true true) program fuel\n    (initial query (records rows tail))\n  change (C.run program fuel (initial query (records rows tail))).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial query (records rows tail)))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial query (records rows tail)) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells query rows tail fuel out hc\nend RiemannGaussian.SemiprimeD1StackOwnerPrefixBounds\n","RiemannGaussian.SemiprimeD1StackOwnerRecordsLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerRecordsLog\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerRecordsLoop\nopen SemiprimeD1StackOwnerRecords SemiprimeD1StackOwnerRecordsView\nopen SemiprimeD1StackOwnerRecordsRead SemiprimeD1StackOwnerRecordsEmit\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1OwnerPrefixBits (records)\n/-- Proof-side acquired row description with degree derived from the original graph.\nNo Row, list, degree or numeric scope value appears in the finite instruction table. -/\nabbrev Row := {x:List Bool×List (List Bool) //x.2.length≤2}\n/-- Proof-only key projection from an already acquired owner row. -/\nabbrev keyOf (r:Row) :List Bool:=r.val.1\n/-- Proof-only ordered scope-word projection from an already acquired owner row. -/\nabbrev wordsOf (r:Row) :List (List Bool):=r.val.2\n/-- Exact acquired catalogue grammar for the proof-side original row sequence. -/\ndef encoded (rows:List Row) :List Bool:=\n  SemiprimeD1StackOwnerLookup.records (rows.map fun r=>(keyOf r,vectorBits (wordsOf r))) []\n/-- Exact row bytes written by the actual table, ordinal and consuming logger source. -/\ndef rowBytes (r:Row) (fixed:List (List Bool×Bool)) :List Bool:=\n  L.row (SemiprimeD1StackOwnerRecord.S.result (wordsOf r))\n    (E.table (keyOf r) fixed [] (wordsOf r) r.property)\n/-- All actual emitted row bytes in original owner order, before the final list tag. -/\ndef bytes (rows:List Row) (fixed:List (List Bool×Bool)) :List Bool:=\n  (rows.map fun r=>rowBytes r fixed).flatten\n/-- Whole actual row parse, prefix copy, source execution and retained-operand drain allowance. -/\ndef rowBudget (r:Row) (fixed:List (List Bool×Bool)) (tail:List Bool) :Nat:=\n  (8*(keyOf r).length+8*(vectorBits (wordsOf r)).length+17)+\n    (5*(records fixed tail).length+4)+(E.timeBound (keyOf r) fixed (wordsOf r) r.property+1)+\n    ((keyOf r).length+tail.length+(vectorBits (wordsOf r)).length+3)\n/-- One ACTUAL acquired owner row, including prefix copying, all34 source roles and physical drains. -/\ntheorem row_run (s:S.Stack→List Bool) (r:Row) (fixed:List (List Bool×Bool)) (tail reader hist out:List Bool) :\n    ∃time≤rowBudget r fixed tail,Runs program time (.local .loop)\n      (data s (payload [] [] [] hist out)\n        (rowAux (true::SemiprimeSourceHistogramKeyBits.frame (keyOf r)\n          (SemiprimeSourceHistogramKeyBits.frame (vectorBits (wordsOf r)) reader)) (records fixed tail)))\n      (.local .loop)\n      (data s (payload [] [] [] ((rowBytes r fixed).reverse++hist) out) (rowAux reader (records fixed tail))):=by\n  let a:=rowAux reader (records fixed tail)\n  have h0:=row_read s (keyOf r) (vectorBits (wordsOf r)) reader (records fixed tail) hist out\n  have h1:=prefix_copy s (keyOf r) (vectorBits (wordsOf r)) reader (records fixed tail) hist out\n  obtain ⟨t,ht,h2⟩:=record_call s a (keyOf r) fixed tail (wordsOf r) r.property hist out\n  rw [done_payload] at h2\n  have h3:=clear_run s a (keyOf r) tail (vectorBits (wordsOf r))\n    ((L.row (SemiprimeD1StackOwnerRecord.S.result (wordsOf r))\n      (E.table (keyOf r) fixed tail (wordsOf r) r.property)).reverse++hist) out\n  have h:=runs_trans program _ _ _ _ _ _ _ _ h0\n    (runs_trans program _ _ _ _ _ _ _ _ h1 (runs_trans program _ _ _ _ _ _ _ _ h2 h3))\n  refine ⟨(8*(keyOf r).length+8*(vectorBits (wordsOf r)).length+17)+\n    ((5*(records fixed tail).length+4)+(t+((keyOf r).length+tail.length+(vectorBits (wordsOf r)).length+3))),?_,?_⟩\n  · unfold rowBudget;omega\n  · exact h\n/-- Exact source-catalogue loop budget, dependent only on actual parsed/copied bytes. -/\ndef loopBudget (rows:List Row) (fixed:List (List Bool×Bool)) (tail:List Bool) :Nat:=\n  (rows.map fun r=>rowBudget r fixed tail).sum\n/-- Every acquired owner is visited in original E order, including isolated owners and repeated scopes. -/\ntheorem loop_run (s:S.Stack→List Bool) (rows:List Row) (fixed:List (List Bool×Bool)) (tail hist out:List Bool) :\n    ∃time≤loopBudget rows fixed tail,Runs program time (.local .loop)\n      (data s (payload [] [] [] hist out) (rowAux (encoded rows) (records fixed tail)))\n      (.local .loop)\n      (data s (payload [] [] [] ((bytes rows fixed).reverse++hist) out) (rowAux [false] (records fixed tail))):=by\n  induction rows generalizing hist with\n  | nil=>\n    refine ⟨0,Nat.zero_le _,?_⟩\n    exact SemiprimeD1StackProcedureTrace.runs_refl program _ _\n  | cons r rows ih=>\n    obtain ⟨a,ha,h0⟩:=row_run s r fixed tail (encoded rows) hist out\n    obtain ⟨b,hb,h1⟩:=ih ((rowBytes r fixed).reverse++hist)\n    refine ⟨a+b,?_,?_⟩\n    · simpa only [loopBudget,List.map_cons,List.sum_cons] using Nat.add_le_add ha hb\n    · have h:=runs_trans program _ _ _ _ _ _ _ _ h0 h1\n      simpa only [encoded,List.map_cons,SemiprimeD1StackOwnerLookup.records,bytes,\n        List.flatten_cons,List.reverse_append,List.append_assoc] using h\nend RiemannGaussian.SemiprimeD1StackOwnerRecordsLoop\n","RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryCopies":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryPrimitives\n/-! # Physical arithmetic-operand copy views for the fixed recovery controller -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryCopies\nopen SemiprimeD1StackPackedFactorRecovery SemiprimeD1StackPackedFactorRecoveryEncoding\nopen SemiprimeD1StackPackedFactorRecoveryPrimitives SemiprimeD1StackProcedureTrace\n/-- Actual preserving copy into the real adder left operand. -/\ntheorem adder_left (site : Copy) (pc finish : Label) (r m x w v u) (left right scratch output value : List Bool)\n    (hc : program pc=.call (copyLabel site 0) finish)\n    (hd : copyStack site 1=adder .left) (hv : (view r m (A.store left right scratch output) x w v u) (copyStack site 0)=value) (hs : u .scratch=[]) :\n    Runs program (5*value.length+4) pc (view r m (A.store left right scratch output) x w v u) finish (view r m (A.store (value++left) right scratch output) x w v u) := by\n  have ht : (view r m (A.store left right scratch output) x w v u) (copyStack site 1)=left := by rw [hd];rfl\n  have h:=copy_call site pc finish hc (view r m (A.store left right scratch output) x w v u) value left hv ht hs\n  rw [hd,view_adder,SemiprimeD1StackAdder.store_left] at h\n  exact h\n/-- Actual preserving copy into the real adder right operand. -/\ntheorem adder_right (site : Copy) (pc finish : Label) (r m x w v u) (left right scratch output value : List Bool)\n    (hc : program pc=.call (copyLabel site 0) finish)\n    (hd : copyStack site 1=adder .right) (hv : (view r m (A.store left right scratch output) x w v u) (copyStack site 0)=value) (hs : u .scratch=[]) :\n    Runs program (5*value.length+4) pc (view r m (A.store left right scratch output) x w v u) finish (view r m (A.store left (value++right) scratch output) x w v u) := by\n  have ht : (view r m (A.store left right scratch output) x w v u) (copyStack site 1)=right := by rw [hd];rfl\n  have h:=copy_call site pc finish hc (view r m (A.store left right scratch output) x w v u) value right hv ht hs\n  rw [hd,view_adder,SemiprimeD1StackAdder.store_right] at h\n  exact h\n/-- Actual preserving copy into the real multiply input operand. -/\ntheorem multiply_input (site : Copy) (pc finish : Label) (r m a w v u) (xs ys ds left acc scratch out cp cs value : List Bool)\n    (hc : program pc=.call (copyLabel site 0) finish)\n    (hd : copyStack site 1=multiply X.input) (hv : (view r m a (X.payload xs ys ds left acc scratch out cp cs) w v u) (copyStack site 0)=value) (hs : u .scratch=[]) :\n    Runs program (5*value.length+4) pc (view r m a (X.payload xs ys ds left acc scratch out cp cs) w v u) finish (view r m a (X.payload (value++xs) ys ds left acc scratch out cp cs) w v u) := by\n  have ht : (view r m a (X.payload xs ys ds left acc scratch out cp cs) w v u) (copyStack site 1)=xs := by rw [hd];rfl\n  have h:=copy_call site pc finish hc (view r m a (X.payload xs ys ds left acc scratch out cp cs) w v u) value xs hv ht hs\n  rw [hd,view_multiply,SemiprimeD1StackMultiplierExecution.payload_xs] at h\n  exact h\n/-- Actual preserving copy into the real multiply factor operand. -/\ntheorem multiply_factor (site : Copy) (pc finish : Label) (r m a w v u) (xs ys ds left acc scratch out cp cs value : List Bool)\n    (hc : program pc=.call (copyLabel site 0) finish)\n    (hd : copyStack site 1=multiply X.factor) (hv : (view r m a (X.payload xs ys ds left acc scratch out cp cs) w v u) (copyStack site 0)=value) (hs : u .scratch=[]) :\n    Runs program (5*value.length+4) pc (view r m a (X.payload xs ys ds left acc scratch out cp cs) w v u) finish (view r m a (X.payload xs (value++ys) ds left acc scratch out cp cs) w v u) := by\n  have ht : (view r m a (X.payload xs ys ds left acc scratch out cp cs) w v u) (copyStack site 1)=ys := by rw [hd];rfl\n  have h:=copy_call site pc finish hc (view r m a (X.payload xs ys ds left acc scratch out cp cs) w v u) value ys hv ht hs\n  rw [hd,view_multiply,SemiprimeD1StackMultiplierExecution.payload_ys] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryCopies\n","RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryFamily\n/-! # All59 actual words and saved returns at every prepared recovery prefix -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryStorage\nopen scoped BigOperators\nopen SemiprimeD1StackPackedFactorRecovery SemiprimeD1StackPackedFactorRecoveryMeaning\nopen SemiprimeD1StackPackedFactorRecoveryClock SemiprimeD1StackPackedFactorRecoveryFamily\nopen SemiprimeD1StackPackedFactorRecoveryWidths SemiprimeBitArithmetic SemiprimeSourceCompactBits\n/-- The two physical inputs, including arbitrary scalar padding, bound every original source word. -/\ntheorem initial_length (bits scalar : List Bool) (k : Stack) :\n    ((initial bits scalar).data k).length≤3*inputSize bits scalar := by\n  rcases k with k|k|k\n  · exact SemiprimeD1StackPackedMomentReadoutStorage.initial_length bits scalar k\n  · exact Nat.zero_le _\n  · exact Nat.zero_le _\n/-- No physical word or unused source role is omitted from the total storage count. -/\ntheorem word_sum (data : Stack→List Bool) (cap : ℕ) (h : ∀k,(data k).length≤cap) :\n    (∑k : Stack,(data k).length)≤59*cap := by\n  calc\n    _ ≤ ∑_k : Stack,cap := Finset.sum_le_sum (fun k _=>h k)\n    _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n/-- Fixed storage coefficient and degree precede every physical input and semiprime family. -/\ndef cellsPolynomial (bits scalar : List Bool) : ℕ := 1000000000000000000*(inputSize bits scalar)^4\n/-- Every actual source prefix counts all59 data words plus its real finite-label return stack. -/\ntheorem prefix_cells (bits scalar : List Bool) (hc : Compact bits) (p q : ℕ)\n    (hp : Nat.Prime p) (hq : Nat.Prime q) (hN : bitValue bits=p*q)\n    (hscalar : bitValue scalar=SemiprimeD1PackedMomentSemiprime.packedValue (p*q) (Nat.mul_pos hp.pos hq.pos))\n    (fuel : ℕ) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial bits scalar)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤cellsPolynomial bits scalar := by\n  obtain ⟨t,ht,hs⟩:=source_run_bounded bits scalar hc p q hp hq hN hscalar\n  have hf : fuel≤t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hs,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hh : SemiprimeD1StackCalls.run program 1 (done bits scalar)=none := rfl\n    rw [hh,Option.bind_none] at hr\n    cases hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (3*inputSize bits scalar)\n    (initial bits scalar) out (initial_length bits scalar) hr\n  have hsum:=word_sum out.data (3*inputSize bits scalar+fuel) hd\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel (initial bits scalar) out hr\n  change out.frames.length≤0+fuel at hframes\n  have hl : inputSize bits scalar≤(inputSize bits scalar)^4 := Nat.le_self_pow (by decide : 4≠0) _\n  unfold cellsPolynomial polynomial at *\n  nlinarith\n/-- Actual finite two-word prepared machine certificate; scalar acquisition is NOT claimed. -/\nnoncomputable def machinePrepared (bits scalar : List Bool) (hc : Compact bits) (p q : ℕ)\n    (hp : Nat.Prime p) (hq : Nat.Prime q) (hN : bitValue bits=p*q)\n    (hscalar : bitValue scalar=SemiprimeD1PackedMomentSemiprime.packedValue (p*q) (Nat.mul_pos hp.pos hq.pos)) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (initial bits scalar))\n      (some (SemiprimeD1StackCalls.configuration (done bits scalar))) (polynomial bits scalar) := by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput (aux .small) (ctl .start) program\n  let h:=source_run_bounded bits scalar hc p q hp hq hN hscalar\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Every compiled prefix counts the SAME59 data words AND the actual saved-return word. -/\ntheorem machine_prefix_cells (bits scalar : List Bool) (hc : Compact bits) (p q : ℕ)\n    (hp : Nat.Prime p) (hq : Nat.Prime q) (hN : bitValue bits=p*q)\n    (hscalar : bitValue scalar=SemiprimeD1PackedMomentSemiprime.packedValue (p*q) (Nat.mul_pos hp.pos hq.pos))\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun z=>z.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial bits scalar)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤cellsPolynomial bits scalar := by\n  have he:=SemiprimeD1StackCalls.run_correct originalInput (aux .small) (ctl .start) program fuel (initial bits scalar)\n  have hh:=he.trans hr\n  cases hout : SemiprimeD1StackCalls.run program fuel (initial bits scalar) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have heq : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits scalar hc p q hp hq hN hscalar fuel out hout\nend RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryStorage\n","RiemannGaussian.SemiprimeD1StackPacketInventoryRoles":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyCounterEntry\nimport RiemannGaussian.SemiprimeD1StackPacketRowsOriginal\nimport RiemannGaussian.SemiprimeD1StackPacketOrientationOriginal\n/-! # Fixed physical inventory for sparse real-occurrence replay\nAll fifty-nine allocations are real. Five displaced component-input allocations\nare repurposed as catalogue, maps and histories, and counted explicitly. The\nactual old class index has its own retained word through increment and reading.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketInventoryRoles\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace F\nexport SemiprimeD1StackSourceKeyFrequency (Stack Label Aux program aux lookupStack oldCount query copyScratch)\nend F\nnamespace R\nexport SemiprimeD1StackPacketRows (Stack Label Aux program output success)\nend R\nnamespace O\nexport SemiprimeD1StackPacketOrientation (Stack Label Aux program aux answer)\nend O\n/-- All21 real frequency/counter words, all19 reader allocations and all19 orientation allocations. -/\nabbrev Stack:=F.Stack⊕(R.Stack⊕O.Stack)\n/-- Direct complete bank for the actual reusable real-ret counter. -/\ndef frequencyStack:F.Stack→Stack:=Sum.inl\n/-- Real allocated reader address; two displaced input allocations hold persistent output histories. -/\ndef readerAllocation:R.Stack→Stack:=fun k=>.inr (.inl k)\n/-- Real allocated orientation address; three displaced input allocations hold the original catalogue and two maps. -/\ndef orientationAllocation:O.Stack→Stack:=fun k=>.inr (.inr k)\n/-- The only retained selected-key vector, with no supplied key list, count or index. -/\ndef source:Stack:=frequencyStack (F.aux .source)\n/-- Actual paid copy of the selected-key vector, consumed once in original occurrence order. -/\ndef stream:Stack:=frequencyStack (F.aux .reader)\n/-- The real current parsed joint key, retained until its placement is logged. -/\ndef raw:Stack:=frequencyStack (F.aux .raw)\n/-- The only retained actual alphabet catalogue. Its physical allocation is outside the mapped orientation image. -/\ndef catalogue:Stack:=orientationAllocation (O.aux .leftInput)\n/-- Newest-first class-counter overrides, with real sentinel-encoded raw keys. -/\ndef classes:Stack:=frequencyStack (F.aux .dictionary)\n/-- Exact OLD class count copied before its consuming real increment; never frame scratch in this client. -/\ndef oldIndex:Stack:=frequencyStack (F.aux .frameScratch)\n/-- Actual compact positive occurrence counter, shared unchanged through class operations. -/\ndef edge:Stack:=frequencyStack (F.aux .maximum)\n/-- Real fresh/seen marker overrides, outside the complete mapped orientation image. -/\ndef seen:Stack:=orientationAllocation (O.aux .rightInput)\n/-- Real packet/slot-address to positive-edge overrides, outside the complete mapped orientation image. -/\ndef slots:Stack:=orientationAllocation (O.aux .indexInput)\n/-- Actual packet vector in newest-first first-discovery order, outside the mapped reader image. -/\ndef packets:Stack:=readerAllocation (.inr .key)\n/-- Actual reversed placement-row history, outside the mapped reader image. -/\ndef placementHistory:Stack:=readerAllocation (.inr .catalogue)\n/-- Final chronological placement vector; this real counter scratch is reused only after all counter calls finish. -/\ndef output:Stack:=frequencyStack (F.aux .trimScratch)\n/-- Real lookup/parser/copy words stay in the included21-role bank. -/\ndef lookupStack:SemiprimeD1StackOwnerLookup.Stack→Stack:=fun k=>frequencyStack (F.lookupStack k)\n/-- Actual shared numeric query, always supplied by a real sentinel procedure. -/\ndef query:Stack:=frequencyStack F.query\n/-- Actual lookup payload and consuming counter operand. -/\ndef oldCount:Stack:=frequencyStack F.oldCount\n/-- Actually acquired successor count, not a supplied numeric answer. -/\ndef count:Stack:=frequencyStack (F.aux .count)\n/-- Copy/Sentinel restoration word, also used by NEW Frame injections after its actual restoration. -/\ndef scratch:Stack:=frequencyStack F.copyScratch\n/-- A physically written singleton true used for seen markers and placement validity after real guards pass. -/\ndef marker:Stack:=frequencyStack (F.aux .incNext)\n/-- Public whole-source success, written only after every replay call and drain. -/\ndef success:Stack:=lookupStack (.inl .output)\n/-- Exact physical reader inclusion: only the key and catalogue input addresses are redirected. -/\ndef readerStack:R.Stack→Stack\n  | .inr .key=>raw\n  | .inr .catalogue=>catalogue\n  | k=>readerAllocation k\n/-- Exact physical orientation inclusion: its three input addresses directly reference actual acquired words. -/\ndef orientationStack:O.Stack→Stack\n  | .inr .leftInput=>readerStack (R.output false)\n  | .inr .rightInput=>readerStack (R.output true)\n  | .inr .indexInput=>oldIndex\n  | k=>orientationAllocation k\n/-- Actual orientation key after its complete frozen source returns. -/\ndef packet:Stack:=orientationStack (O.aux .keyOutput)\n/-- Actual orientation slot word after its complete frozen source returns. -/\ndef slot:Stack:=orientationStack (O.aux .slotOutput)\n/-- Drained orientation high-output word becomes a real raw address/placement-frame buffer. -/\ndef buffer:Stack:=orientationStack (O.aux .highOutput)\n/-- Already drained orientation slot history becomes the real outer-placement frame buffer. -/\ndef outerBuffer:Stack:=orientationStack (O.aux .slotHistory)\n/-- Every actual physical allocation, including the five repurposed globals, is counted. -/\ntheorem stack_card:Fintype.card Stack=59:=by\n  rw [Fintype.card_sum,SemiprimeD1StackSourceKeyFrequency.stack_card,Fintype.card_sum,\n    SemiprimeD1StackPacketRows.stack_card,SemiprimeD1StackPacketOrientation.stack_card]\n/-- Complete counter bank inclusion is physically distinct. -/\ntheorem frequency_injective:Function.Injective frequencyStack:=Sum.inl_injective\n/-- Redirected reader inputs remain distinct from each other and all seventeen real reader work/output roles. -/\ntheorem reader_injective:Function.Injective readerStack:=by decide\n/-- Redirected orientation inputs remain distinct from each other and all sixteen real orientation work/output roles. -/\ntheorem orientation_injective:Function.Injective orientationStack:=by decide\n/-- Catalogue and persistent maps are outside ALL mapped orientation fields, not merely its cleanup loop. -/\ntheorem orientation_globals_outside (k:O.Stack):\n    orientationStack k≠catalogue ∧ orientationStack k≠seen ∧ orientationStack k≠slots :=by\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> decide\n  · cases k <;> decide\n/-- Packet-discovery vector and placement history are outside ALL mapped reader fields. -/\ntheorem reader_globals_outside (k:R.Stack):readerStack k≠packets ∧ readerStack k≠placementHistory :=by\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> decide\n  · cases k <;> decide\n/-- OLD j is outside every actual reader address and survives all real reading work. -/\ntheorem reader_oldIndex_outside (k:R.Stack):readerStack k≠oldIndex :=by\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> decide\n  · cases k <;> decide\n/-- The NEW actual Frame scratch is separate from the retained OLD-j cache. -/\ntheorem scratch_ne_oldIndex:scratch≠oldIndex:=by decide\nend RiemannGaussian.SemiprimeD1StackPacketInventoryRoles\n","RiemannGaussian.SemiprimeD1StackPacketInventoryStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketInventoryBounds\n/-! # Every actual sparse inventory data role and real return cell at every prefix -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketInventoryStorage\nopen SemiprimeD1StackPacketInventory SemiprimeD1StackPacketInventoryExecution\nopen SemiprimeD1StackPacketInventoryClock\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackPacketInventoryEncoding\n/-- No reached prefix passes the actual same-program successful final halt. -/\ntheorem prefix_fuel (a:Nat) (pairs:SemiprimeD1StackPacketInventoryLoop.Pairs) (hv:SemiprimeD1StackPacketInventoryLoop.Valid a pairs)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (source a (SemiprimeD1StackPacketInventoryLoop.keys pairs))=some out):\n    fuel ≤ polynomial a pairs :=by\n  obtain ⟨t,ht,hstop⟩:=source_run_bounded a pairs hv\n  have hf:fuel ≤ t:=by\n    by_contra hn\n    have he:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hp\n    have hh:SemiprimeD1StackCalls.run program 1 (done (vectorBits (SemiprimeD1StackPacketInventoryLoop.keys pairs)) (alphabet a) (acquire a (SemiprimeD1StackPacketInventoryLoop.keys pairs)))=none:=rfl\n    rw [hh,Option.bind_none] at hp\n    cases hp\n  exact hf.trans ht\n/-- SAME source trace counts all59 actual Bool stacks and every genuine nested return frame. -/\ntheorem prefix_cells (a:Nat) (pairs:SemiprimeD1StackPacketInventoryLoop.Pairs) (hv:SemiprimeD1StackPacketInventoryLoop.Valid a pairs)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (source a (SemiprimeD1StackPacketInventoryLoop.keys pairs))=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤\n      1000000000000000*(inputSize a pairs)^4 :=by\n  let S:=inputSize a pairs\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel S _ out (initial_length _ _) hp\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hp\n  change out.frames.length ≤ 0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length) ≤ 59*(S+fuel):=by\n    calc\n      _ ≤ ∑_k:Stack,(S+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _ = _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel a pairs hv fuel out hp\n  change fuel ≤ 1000000000000*S^4 at ht\n  have hp:S≤S^4:=Nat.le_pow (by decide:0<(4:Nat))\n  change _ ≤ 1000000000000000*S^4\n  omega\n/-- Every genuine compiled prefix includes the physical none-labelled return stack in the same polynomial byte cap. -/\ntheorem machine_prefix_cells (a:Nat) (pairs:SemiprimeD1StackPacketInventoryLoop.Pairs) (hv:SemiprimeD1StackPacketInventoryLoop.Valid a pairs)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hp:(fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (source a (SemiprimeD1StackPacketInventoryLoop.keys pairs))))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      1000000000000000*(inputSize a pairs)^4 :=by\n  have he:=SemiprimeD1StackCalls.run_correct SemiprimeD1StackPacketInventory.source output (SemiprimeD1StackPacketInventory.Label.local .start)\n    program fuel (source a (SemiprimeD1StackPacketInventoryLoop.keys pairs))\n  have hh:=he.trans hp\n  cases hout:SemiprimeD1StackCalls.run program fuel (source a (SemiprimeD1StackPacketInventoryLoop.keys pairs)) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells a pairs hv fuel out hout\n/-- Every actual source prefix, specified directly from the two existing physical input words. -/\ntheorem prefix_cells_keys (a:Nat) (rawKeys:List (List Bool))\n    (hv:SemiprimeD1StackPacketInventoryBounds.ValidKeys a rawKeys)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (initial (vectorBits rawKeys) (alphabet a))=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤\n      1000000000000000*((vectorBits rawKeys).length+(alphabet a).length+1)^4:=by\n  obtain ⟨pairs,hv,hkeys⟩:=SemiprimeD1StackPacketInventoryBounds.describe a rawKeys hv\n  have hh:=prefix_cells a pairs hv fuel out (by simpa only [SemiprimeD1StackPacketInventoryEncoding.source,hkeys] using hp)\n  simpa only [inputSize,hkeys] using hh\n/-- Every actual compiled prefix counts all59 physical roles and the none-labelled genuine return stack. -/\ntheorem machine_prefix_cells_keys (a:Nat) (rawKeys:List (List Bool))\n    (hv:SemiprimeD1StackPacketInventoryBounds.ValidKeys a rawKeys)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hp:(fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial (vectorBits rawKeys) (alphabet a))))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      1000000000000000*((vectorBits rawKeys).length+(alphabet a).length+1)^4:=by\n  obtain ⟨pairs,hv,hkeys⟩:=SemiprimeD1StackPacketInventoryBounds.describe a rawKeys hv\n  have hh:=machine_prefix_cells a pairs hv fuel cfg (by simpa only [SemiprimeD1StackPacketInventoryEncoding.source,hkeys] using hp)\n  simpa only [inputSize,hkeys] using hh\nend RiemannGaussian.SemiprimeD1StackPacketInventoryStorage\n","RiemannGaussian.SemiprimeD1StackPacketOrientationOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketOrientationStorage\nimport RiemannGaussian.SemiprimeD1StackPacketRowsOriginal\n/-! # Exact old orientation and actual acquired packet-row lineage\nThe generic source preserves arbitrary physical colour/index padding. The\noriginal-family pipeline below retains two actual executions and both own\nclocks: real PacketRows19 acquisition, then this real Orientation19 source.\nAn outer inventory controller still has to compose their literal calls.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketOrientationOriginal\nopen SemiprimeD1StackPacketOrientation SemiprimeD1StackPacketOrientationExecution\nopen SemiprimeD1StackPacketOrientationClock\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace Native\nexport SemiprimeD1OrientationBits (acquire)\nend Native\nnamespace Reader\nexport SemiprimeD1StackPacketRows (program initial output)\nexport SemiprimeD1StackPacketRowsOriginal (catalogue)\nexport SemiprimeD1StackPacketRowsMeaning (fields)\nend Reader\nnamespace Read\nexport SemiprimeD1PacketRows (read)\nend Read\n/-- Exact original packet class key, including its remaining index as a RAW tail. -/\ntheorem result_key (left right:List (List Bool)) (index:List Bool):\n    (done left right index).data (aux .keyOutput)=(Native.acquire left right index).key:=rfl\n/-- Exactly one original slot bit per coordinate, with no added vector terminator. -/\ntheorem result_slots (left right:List (List Bool)) (index:List Bool):\n    (done left right index).data (aux .slotOutput)=(Native.acquire left right index).slots:=rfl\n/-- Exact remaining raw high-index bytes, preserving arbitrary zero padding. -/\ntheorem result_high (left right:List (List Bool)) (index:List Bool):\n    (done left right index).data (aux .highOutput)=(Native.acquire left right index).high:=rfl\n/-- Successful physical flags agree with the original paired-row validity. -/\ntheorem result_valid (left right:List (List Bool)) (index:List Bool) (hlen:left.length=right.length):\n    (done left right index).data answer=[(Native.acquire left right index).valid] :=by\n  rw [(SemiprimeD1OrientationBits.acquire_valid left right index).mpr hlen]\n  rfl\n/-- All three acquired physical input words are preserved literally. -/\ntheorem inputs_retained (left right:List (List Bool)) (index:List Bool):\n    (done left right index).data (aux .leftInput)=vectorBits left ∧\n      (done left right index).data (aux .rightInput)=vectorBits right ∧\n      (done left right index).data (aux .indexInput)=index:=⟨rfl,rfl,rfl⟩\n/-- Complete SAME program, exact original key/slots/high, all numerical padding and own linear source clock. -/\ntheorem source_run_original (left right:List (List Bool)) (index:List Bool) (hlen:left.length=right.length):\n    ∃t ≤ polynomial (vectorBits left) (vectorBits right) index,\n      SemiprimeD1StackCalls.run program t (initial (vectorBits left) (vectorBits right) index)=some (done left right index) ∧\n      (done left right index).data (aux .keyOutput)=(Native.acquire left right index).key ∧\n      (done left right index).data (aux .slotOutput)=(Native.acquire left right index).slots ∧\n      (done left right index).data (aux .highOutput)=(Native.acquire left right index).high :=by\n  obtain ⟨t,ht,h⟩:=source_run_bounded left right index hlen\n  exact ⟨t,ht,h,rfl,rfl,rfl⟩\n/-- Two actually executed prepared sources, with the orientation input taken DIRECTLY from the stopped real reader.\nThis proof statement is not a runtime row getter or a claim of an assembled inventory controller. -/\ndef Pipeline (a:Nat) (key index:List Bool):Prop:=\n  ∃r ≤ SemiprimeD1StackPacketRowsClock.polynomial key (Reader.catalogue a),\n    ∃rd:SemiprimeD1StackPacketRows.C.State SemiprimeD1StackPacketRows.Stack SemiprimeD1StackPacketRows.Label,\n      SemiprimeD1StackCalls.run Reader.program r (Reader.initial key (Reader.catalogue a))=some rd ∧\n      ∃t ≤ polynomial (rd.data (Reader.output false)) (rd.data (Reader.output true)) index,\n        SemiprimeD1StackCalls.run program t (initial (rd.data (Reader.output false)) (rd.data (Reader.output true)) index)=\n          some (done (Read.read (SemiprimeSourceHistogramRows.acquire 64 a) a key).left\n            (Read.read (SemiprimeSourceHistogramRows.acquire 64 a) a key).right index)\n/-- The original acquired catalogue and both actual selected IDs discharge every row/order/presence premise internally. -/\ntheorem source_pipeline_original (a:Nat) (owner factor index:List Bool)\n    (ho:owner∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids)\n    (hf:factor∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids):\n    Pipeline a (SemiprimeSourceHistogramKeyBits.frame owner factor) index :=by\n  obtain ⟨r,hr,hread,_,_,_,_⟩:=SemiprimeD1StackPacketRowsOriginal.source_run_original a owner factor ho hf\n  have hl:=SemiprimeD1StackPacketRowsMeaning.original_lookup 64 a owner ho\n  have hg:=SemiprimeD1StackPacketRowsMeaning.original_lookup 64 a factor hf\n  obtain ⟨t,ht,h⟩:=source_run_bounded (Reader.fields 64 a owner) (Reader.fields 64 a factor) index\n    (hl.2.2.trans hg.2.2.symm)\n  have hol:Reader.fields 64 a owner=(Read.read (SemiprimeSourceHistogramRows.acquire 64 a) a\n      (SemiprimeSourceHistogramKeyBits.frame owner factor)).left:=by\n    rw [(SemiprimeD1PacketRows.read_frame _ a owner factor).1]\n    exact SemiprimeD1StackPacketRowsMeaning.fields_original 64 a owner ho\n  have hor:Reader.fields 64 a factor=(Read.read (SemiprimeSourceHistogramRows.acquire 64 a) a\n      (SemiprimeSourceHistogramKeyBits.frame owner factor)).right:=by\n    rw [(SemiprimeD1PacketRows.read_frame _ a owner factor).2]\n    exact SemiprimeD1StackPacketRowsMeaning.fields_original 64 a factor hf\n  refine ⟨r,hr,_,hread,t,ht,?_⟩\n  change SemiprimeD1StackCalls.run program t (initial (vectorBits (Reader.fields 64 a owner))\n    (vectorBits (Reader.fields 64 a factor)) index)=_\n  rw [←hol,←hor]\n  exact h\n/-- ALL original selected occurrence keys have two actual source executions with exact old packet acquisition.\nNo desired colour fields, comparison, remaining index or packet result is an operand of either program. -/\ntheorem source_pipeline_selected (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (p:(e:Fin F)×Fin (arity e)) (index:List Bool):\n    Pipeline a (SemiprimeD1IncidenceAcquisition.originalKey n F 64 a arity owner p) index :=by\n  obtain ⟨l,r,hl,hr,hkey⟩:=SemiprimeD1StackPacketRowsOriginal.selected_key_lineage n F a arity owner p\n  rw [hkey]\n  exact source_pipeline_original a l r index hl hr\nend RiemannGaussian.SemiprimeD1StackPacketOrientationOriginal\n","RiemannGaussian.SemiprimeD1StackPacketOrientationPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketOrientation\n/-! # Real packet orientation copy, Field, comparison, frame, reverse and cleanup calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketOrientationPrimitives\nopen SemiprimeD1StackPacketOrientation SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\nlocal notation \"ctl\" => Label.local\n/-- Exact chronological source-fragment composition preserves every real outer return. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Actual complete preserving copy, including both restoration loops and its real caller return. -/\ntheorem copy_call (what:Copy) (pc next:Control)\n    (hc:program (ctl pc)=.call (.copier what 0) (ctl next)) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack what 0)=xs) (hy:before (copyStack what 1)=ys) (hs:before (copyStack what 2)=[]) :\n    Runs program (5*xs.length+4) (ctl pc) before (ctl next)\n      (Function.update before (copyStack what 1) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack what) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack what) (copy_injective what) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack what) (Label.copier what) (copy_injective what) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl pc) (ctl next) hc (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- Complete real field read pays all input/output bits and leaves its physical true-valid flag. -/\ntheorem field_call (part:Bool) (pc next:Control)\n    (hc:program (ctl pc)=.call (.field part (F.active .tagPop (none,false))) (ctl next))\n    (before:Stack→List Bool) (word tail:List Bool)\n    (hi:before (fieldStack part (.inl .input))=frame word tail)\n    (ho:before (fieldStack part (.inl .output))=[])\n    (hs:before (fieldStack part (.inl .scratch))=[])\n    (hv:before (fieldStack part (.inr ()))=[]) :\n    Runs program (8*word.length+7) (ctl pc) before (ctl next)\n      (Function.update (Function.update (Function.update before (fieldStack part (.inl .input)) tail)\n        (fieldStack part (.inl .output)) word) (fieldStack part (.inr ())) [true]) :=by\n  let start:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let stop:SemiprimeD1StackBytecode.State F.Stack F.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel (fieldStack part) before start.store before:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact hi\n        · exact hs\n        · exact ho\n      · cases k;exact hv\n    · intro k _;rfl\n  have h0:=Link.data_update (fieldStack part) (field_injective part) before start.store before hin (.inl .input) tail\n  have h1:=Link.data_update (fieldStack part) (field_injective part) before _ _ h0 (.inl .output) word\n  have h2:=Link.data_update (fieldStack part) (field_injective part) before _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update start.store (.inl .input) tail) (.inl .output) word) (.inr ()) [true]=stop.store:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  exact included_call program (fieldStack part) (Label.field part) (field_injective part) F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) (ctl pc) (ctl next) hc (8*word.length+6) start stop before _ rfl rfl\n    (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin h2\n/-- Real preserving Frame writes a physical field onto its existing dictionary/vector tail. -/\ntheorem frame_call (right:Frame) (pc next:Control)\n    (hc:program (ctl pc)=.call (.frame right 0) (ctl next)) (before:Stack→List Bool) (word buffer:List Bool)\n    (hw:before (frameStack right 0)=word) (hb:before (frameStack right 1)=buffer) (hs:before (frameStack right 2)=[]) :\n    Runs program (6*word.length+5) (ctl pc) before (ctl next)\n      (Function.update before (frameStack right 1) (frame word buffer)) :=by\n  let start:=SemiprimeD1StackFrame.state 0 none word buffer []\n  let stop:=SemiprimeD1StackFrame.done word (frame word buffer)\n  have hi:Link.DataRel (frameStack right) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hw\n      · exact hb\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (frameStack right) (frame_injective right) before start.store before hi (1:Fin 3) (frame word buffer)\n  have he:Function.update start.store 1 (frame word buffer)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (frameStack right) (Label.frame right) (frame_injective right) SemiprimeD1StackFrame.code 0 (fun _=>rfl)\n    (ctl pc) (ctl next) hc (6*word.length+4) start stop before _ rfl rfl\n    (SemiprimeD1StackFrame.frame_words word buffer none) hi ho\n/-- Every coordinate/key/slot reversal consumes its real source and pays all bytes and return cells. -/\ntheorem reverse_call (what:Reverse) (pc next:Control)\n    (hc:program (ctl pc)=.call (.reverse what 0) (ctl next)) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (reverseStack what 0)=xs) (hy:before (reverseStack what 1)=ys) :\n    Runs program (2*xs.length+3) (ctl pc) before (ctl next)\n      (Function.update (Function.update before (reverseStack what 0) []) (reverseStack what 1) (xs.reverse++ys)) :=by\n  let start:=SemiprimeD1StackReverseWord.state none xs ys\n  let stop:=SemiprimeD1StackReverseWord.done (xs.reverse++ys)\n  have hi:Link.DataRel (reverseStack what) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n    · intro k _;rfl\n  have h0:=Link.data_update (reverseStack what) (reverse_injective what) before start.store before hi (0:Fin 2) []\n  have h1:=Link.data_update (reverseStack what) (reverse_injective what) before _ _ h0 (1:Fin 2) (xs.reverse++ys)\n  have he:Function.update (Function.update start.store 0 []) 1 (xs.reverse++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at h1\n  exact included_call program (reverseStack what) (Label.reverse what) (reverse_injective what)\n    SemiprimeD1StackReverseWord.code 0 (fun _=>rfl) (ctl pc) (ctl next) hc (2*xs.length+2) start stop before _ rfl rfl\n    (SemiprimeD1StackReverseWord.reverse_run xs ys none) hi h1\n/-- One literal local push preserves the entire other physical bank and all real outer returns. -/\ntheorem push_run (pc:Control) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program (ctl pc)=.base (.push k b next)) :\n    Runs program 1 (ctl pc) before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One literal local pop consumes ONLYthe actual physical Boolean head. -/\ntheorem pop_run (pc:Control) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program (ctl pc)=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 (ctl pc) before (SemiprimeD1StackBytecode.choose empty low high xs.head?) (Function.update before k xs.tail) :=by\n  apply one_base program (ctl pc) _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Real EOF peek does not silently discard any remaining singleton-result bytes. -/\ntheorem peek_run (pc:Control) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program (ctl pc)=.base (.peek k empty low high)) (hx:before k=xs) :\n    Runs program 1 (ctl pc) before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before :=by\n  apply one_base program (ctl pc) _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Every colour/key/cursor cleanup actually visits every byte and its final empty branch. -/\ntheorem drain_loop (pc:Control) (next:Label) (k:Stack)\n    (hc:program (ctl pc)=.base (.pop k next (ctl pc) (ctl pc))) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) (ctl pc) before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next (ctl pc) (ctl pc) k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next (ctl pc) (ctl pc) k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\n/-- The real parser's true-valid byte is physically consumed before returning the complete unframed word. -/\ntheorem field_valid (part:Bool) (pc validPC:Control) (next:Label)\n    (hc:program (ctl pc)=.call (.field part (F.active .tagPop (none,false))) (ctl validPC))\n    (hp:program (ctl validPC)=.base (.pop answer (ctl .reject) (ctl .reject) next))\n    (before:Stack→List Bool) (word tail:List Bool)\n    (hi:before (fieldStack part (.inl .input))=frame word tail)\n    (ho:before (fieldStack part (.inl .output))=[])\n    (hs:before (fieldStack part (.inl .scratch))=[])\n    (hv:before answer=[]) :\n    Runs program (8*word.length+8) (ctl pc) before next\n      (Function.update (Function.update before (fieldStack part (.inl .input)) tail)\n        (fieldStack part (.inl .output)) word) :=by\n  let after:=Function.update (Function.update before (fieldStack part (.inl .input)) tail)\n    (fieldStack part (.inl .output)) word\n  have hout:answer ≠ fieldStack part (.inl .output):=\n    by\n      intro h\n      have he:=field_injective part (show fieldStack part (.inr ())=fieldStack part (.inl .output) from h)\n      cases he\n  have hin:answer ≠ fieldStack part (.inl .input):=\n    by\n      intro h\n      have he:=field_injective part (show fieldStack part (.inr ())=fieldStack part (.inl .input) from h)\n      cases he\n  have hvalid:after answer=[]:=by\n    dsimp only [after]\n    rw [Function.update_of_ne hout,Function.update_of_ne hin,hv]\n  have h0:=field_call part pc validPC hc before word tail hi ho hs hv\n  change Runs program (8*word.length+7) _ _ _ (Function.update after answer [true]) at h0\n  have h1:=pop_run validPC (ctl .reject) (ctl .reject) next answer\n    (Function.update after answer [true]) [true] hp (Function.update_self _ _ _)\n  change Runs program 1 _ _ _ (Function.update (Function.update after answer [true]) answer []) at h1\n  have hz:Function.update after answer []=after:=by\n    simpa only [hvalid] using (Function.update_eq_self answer after)\n  rw [Function.update_idem,hz] at h1\n  have h:=join h0 h1\n  simpa only [Nat.add_assoc,SemiprimeD1StackBytecode.choose,List.head?_cons,after] using h\n/-- Complete real numeric comparison consumes only actual copied operands and restores all scratch words. -/\ntheorem less_call (backward:Bool) (before:Stack→List Bool) (a b:List Bool)\n    (ha:before (operand false)=a) (hb:before (operand true)=b)\n    (hs:before scratch=[]) (hd:before buffer=[]) (ho:before answer=[]) :\n    Runs program (SemiprimeD1StackWordLessExecution.totalTime a b+1) (ctl (.compare backward)) before (ctl (.compared backward))\n      (Function.update (Function.update (Function.update before (operand false) [])\n        (operand true) []) answer [SemiprimeD1StackWordLessExecution.answer a b]) :=by\n  let start:=SemiprimeD1StackWordLess.initial a b\n  let stop:=SemiprimeD1StackWordLessExecution.done a b\n  have hin:Link.DataRel lessStack before start.data before:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact ha\n        · exact hb\n        · exact hs\n        · exact hd\n      · cases k;exact ho\n    · intro k _;rfl\n  have h0:=Link.data_update lessStack Sum.inl_injective before start.data before hin (.inl .left) []\n  have h1:=Link.data_update lessStack Sum.inl_injective before _ _ h0 (.inl .right) []\n  have h2:=Link.data_update lessStack Sum.inl_injective before _ _ h1 (.inr ()) [SemiprimeD1StackWordLessExecution.answer a b]\n  have he:Function.update (Function.update (Function.update start.data (.inl .left) []) (.inl .right) [])\n      (.inr ()) [SemiprimeD1StackWordLessExecution.answer a b]=stop.data:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program lessStack Label.less Sum.inl_injective\n    Less.program .start (fun _=>rfl) (ctl (.compare backward)) (ctl (.compared backward)) rfl\n    (SemiprimeD1StackWordLessExecution.totalTime a b) start stop before _ rfl rfl rfl rfl\n    (SemiprimeD1StackWordLessExecution.source_run a b) hin h2\nend RiemannGaussian.SemiprimeD1StackPacketOrientationPrimitives\n","RiemannGaussian.SemiprimeD1StackPacketOrientationStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketOrientationClock\n/-! # Every actual orientation data role and real return cell at every prefix -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketOrientationStorage\nopen SemiprimeD1StackPacketOrientation SemiprimeD1StackPacketOrientationExecution\nopen SemiprimeD1StackPacketOrientationClock\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- All three retained physical inputs and all sixteen initially empty helper/output words are counted. -/\ntheorem initial_role_bound (left right index:List Bool) (k:Stack):\n    ((initial left right index).data k).length ≤ inputSize left right index :=by\n  rcases k with k|k\n  · exact Nat.zero_le _\n  · cases k <;> dsimp only [initial,input,Sum.elim_inr,List.length_nil] <;> unfold inputSize <;> omega\n/-- No reached prefix passes the actual same-program successful final halt. -/\ntheorem prefix_fuel (left right:List (List Bool)) (index:List Bool) (hlen:left.length=right.length)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (initial (vectorBits left) (vectorBits right) index)=some out):\n    fuel ≤ polynomial (vectorBits left) (vectorBits right) index :=by\n  obtain ⟨t,ht,hstop⟩:=source_run_bounded left right index hlen\n  have hf:fuel ≤ t:=by\n    by_contra hn\n    have he:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hp\n    have hh:SemiprimeD1StackCalls.run program 1 (done left right index)=none:=rfl\n    rw [hh,Option.bind_none] at hp\n    cases hp\n  exact hf.trans ht\n/-- SAME source trace counts all19 actual Bool stacks and every genuine nested return frame. -/\ntheorem prefix_cells (left right:List (List Bool)) (index:List Bool) (hlen:left.length=right.length)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (initial (vectorBits left) (vectorBits right) index)=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤\n      1000000*inputSize (vectorBits left) (vectorBits right) index :=by\n  let S:=inputSize (vectorBits left) (vectorBits right) index\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel S _ out (initial_role_bound _ _ _) hp\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hp\n  change out.frames.length ≤ 0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length) ≤ 19*(S+fuel):=by\n    calc\n      _ ≤ ∑_k:Stack,(S+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _ = _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel left right index hlen fuel out hp\n  change fuel ≤ 10000*S at ht\n  change _ ≤ 1000000*S\n  omega\n/-- Every genuine compiled prefix includes the physical none-labelled return stack in the same linear byte cap. -/\ntheorem machine_prefix_cells (left right:List (List Bool)) (index:List Bool) (hlen:left.length=right.length)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hp:(fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial (vectorBits left) (vectorBits right) index)))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      1000000*inputSize (vectorBits left) (vectorBits right) index :=by\n  have he:=SemiprimeD1StackCalls.run_correct (aux .leftInput) (aux .keyOutput) (SemiprimeD1StackPacketOrientation.Label.local .start)\n    program fuel (initial (vectorBits left) (vectorBits right) index)\n  have hh:=he.trans hp\n  cases hout:SemiprimeD1StackCalls.run program fuel (initial (vectorBits left) (vectorBits right) index) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells left right index hlen fuel out hout\nend RiemannGaussian.SemiprimeD1StackPacketOrientationStorage\n","RiemannGaussian.SemiprimeD1StackPhaseChildContextFresh":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseChildContextOriginal\nimport RiemannGaussian.SemiprimeD1StackReverseWord\n/-! # Physical original fresh-generator allocation from the actual child-context cache\nThe source derives old/new rank from real header acquisition, consumes paid copies\nof those actual counters, emits each coefficient's literal codec bytes, and makes\none actual reversal. No q/P/rank/vector answer is supplied at either entry.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 8192\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackPhaseChildContextFresh\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace H\nexport SemiprimeD1StackPhaseChildContext (Stack Label program initial input ready phaseStack oldStack childStack aux)\nnamespace J\nexport SemiprimeD1StackJetContext (rankCache widthCache axesCache)\nend J\nend H\n/-- Physical allocation counters, reverse byte history, output vector and restoration scratch. -/\ninductive Aux where | remaining | skip | history | output | scratch deriving DecidableEq,Repr\ninstance : Fintype Aux :=Fintype.ofList [.remaining,.skip,.history,.output,.scratch] (by intro k;cases k <;> simp)\n/-- Retained actual80-role context cache and five literal allocator roles. -/\nabbrev Stack :=H.Stack⊕Aux\n/-- Entire actual cache remains disjoint from allocator storage. -/\ndef contextStack : H.Stack→Stack :=Sum.inl\n/-- Literal allocator register inclusion. -/\ndef aux : Aux→Stack :=Sum.inr\n/-- Actual new-rank counter acquired from the new header by the real context source. -/\ndef newRank : Stack :=contextStack (H.childStack H.J.rankCache)\n/-- Actual old-rank counter acquired from the caller's old header by the real context source. -/\ndef oldRank : Stack :=contextStack (H.oldStack H.J.rankCache)\n/-- Actual width VALUE markers determine the reduced scalar unit's bit. -/\ndef width : Stack :=contextStack (H.childStack H.J.widthCache)\n/-- Physical child-context presence flag; no verdict operand is supplied. -/\ndef valid : Stack :=contextStack (H.aux .valid)\n/-- Fixed finite allocation control; all counts live on actual Boolean tapes. -/\ninductive Label where\n  | start | phaseReady | guard | copyNew | copyOld | before | choose | unit\n  | zeroBefore0 | zeroBefore1 | zeroAfter0 | zeroAfter1\n  | one0 | one1 | one2 | one3 | after | clearSkip | seed | reverse | done\n  | context (pc : H.Label) | copy (old : Bool) (pc : Fin 9) | reversal (pc : Fin 4)\n  deriving Fintype\n/-- Two real preserving copies read ACTUALLY acquired ranks. -/\ndef copyStack (old : Bool) (k : Fin 3) : Stack :=\n  if k=0 then (if old then oldRank else newRank)\n  else if k=1 then (if old then aux .skip else aux .remaining) else aux .scratch\n/-- Actual one-pass byte reversal consumes history into the actual output tape. -/\ndef reverseStack (k : Fin 2) : Stack :=if k=0 then aux .history else aux .output\n/-- Literal original-source→header/cache→rank-counter→coefficient-byte pipeline. -/\ndef program : Label→C.Instruction Stack Label\n  | .start=>.call (.context .start) .guard\n  | .phaseReady=>.call (.context .guard) .guard\n  | .guard=>.base (.peek valid .done .done .copyNew)\n  | .copyNew=>.call (.copy false 0) .copyOld\n  | .copyOld=>.call (.copy true 0) .before\n  | .before=>.base (.pop (aux .remaining) .clearSkip .choose .choose)\n  | .choose=>.base (.pop (aux .skip) .unit .zeroBefore0 .zeroBefore0)\n  | .unit=>.base (.peek width .zeroAfter0 .one0 .one0)\n  | .zeroBefore0=>.base (.push (aux .history) true .zeroBefore1)\n  | .zeroBefore1=>.base (.push (aux .history) false .before)\n  | .zeroAfter0=>.base (.push (aux .history) true .zeroAfter1)\n  | .zeroAfter1=>.base (.push (aux .history) false .after)\n  | .one0=>.base (.push (aux .history) true .one1)\n  | .one1=>.base (.push (aux .history) true .one2)\n  | .one2=>.base (.push (aux .history) true .one3)\n  | .one3=>.base (.push (aux .history) false .after)\n  | .after=>.base (.pop (aux .remaining) .clearSkip .zeroAfter0 .zeroAfter0)\n  | .clearSkip=>.base (.pop (aux .skip) .seed .clearSkip .clearSkip)\n  | .seed=>.base (.push (aux .output) false .reverse)\n  | .reverse=>.call (.reversal 0) .done\n  | .done=>.base .halt\n  | .context pc=>SemiprimeD1StackValidationLink.instruction contextStack Label.context (H.program pc)\n  | .copy old pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack old) (Label.copy old) (SemiprimeD1StackCopy.code pc)\n  | .reversal pc=>SemiprimeD1StackMultiplierLink.instruction reverseStack Label.reversal (SemiprimeD1StackReverseWord.code pc)\n/-- Exact bank views are proof invariants, absent from finite executed control. -/\ndef store (context : H.Stack→List Bool) (remaining skip history output scratch : List Bool) : Stack→List Bool :=\n  Sum.elim context (fun k=>match k with\n    | .remaining=>remaining | .skip=>skip | .history=>history | .output=>output | .scratch=>scratch)\n/-- Original physical a/u/M and binary t/p plus original UNARY old-header only. -/\ndef input (a u edges : Nat) (t p axes : List Bool) : Stack→List Bool :=store (H.input a u edges t p axes) [] [] [] [] []\n/-- Whole source starts before every phase/context/rank supplier. -/\ndef initial (a u edges : Nat) (t p axes : List Bool) : C.State Stack Label :=⟨some .start,none,none,input a u edges t p axes,[]⟩\n/-- SAME-program ready entry retains the ACTUALLY acquired complete old/new context caches. -/\ndef ready (a u edges : Nat) (t p : List Bool) (axes : List Nat) : C.State Stack Label :=\n  ⟨some .guard,none,none,store (SemiprimeD1StackPhaseChildContextComponents.result a u edges t p axes) [] [] [] [] [],[]⟩\n/-- SAME program also accepts the exact actual P48 cache before old/new context acquisition. -/\ndef phaseReady (a u edges : Nat) (t p axes : List Bool) : C.State Stack Label :=\n  ⟨some .phaseReady,none,none,store (H.ready a u edges t p axes).data [] [] [] [] [],[]⟩\n/-- One fixed genuine finite machine, with Boolean data and finite actual returns. -/\ndef machine : Turing.FinTM2 :=SemiprimeD1StackCalls.machine (contextStack (H.oldStack H.J.axesCache)) (aux .output) .start program\n/-- Complete allocator/context cache bank contains85 physical Boolean roles. -/\ntheorem stack_card : Fintype.card Stack=85 :=by rw [Fintype.card_sum,SemiprimeD1StackPhaseChildContext.stack_card];decide\n/-- Actual context inclusion preserves every80-role field separately. -/\ntheorem context_injective : Function.Injective contextStack :=Sum.inl_injective\n/-- Rank copy banks have distinct actual source/destination/restoration tapes. -/\ntheorem copy_injective (old : Bool) : Function.Injective (copyStack old) :=by cases old <;> decide\n/-- Byte reversal has two distinct physical tapes. -/\ntheorem reverse_injective : Function.Injective reverseStack :=by decide\n/-- Numeric axes/precision/rank do not occur in executed finite control. -/\ntheorem control_finite : Finite machine.σ :=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- Every physical alphabet, including actual return cells, is fixed finite. -/\ntheorem alphabets_finite (k : machine.K) : Finite (machine.Γ k) :=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _ k\nend RiemannGaussian.SemiprimeD1StackPhaseChildContextFresh\n","RiemannGaussian.SemiprimeD1StackPhaseGeometrySubtract":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseGeometryPower\n/-! # Actual borrow dispatch and exact absolute-value subtraction -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseGeometrySubtract\nopen SemiprimeD1StackPhaseGeometry SemiprimeD1StackPhaseGeometryArithmetic\nopen SemiprimeD1StackPhaseGeometryPrimitives SemiprimeD1StackProcedureTrace\n/-- Full physical phase state retaining original operands and acquired binary powers. -/\ndef phase (a t left right output sign : List Bool) : Stack→List Bool :=\n  data a t [] (powerWord a.length) (powerWord (a.length+1)) sign [] [] [] left right output\n/-- One real copy of EACH original operand precedes every actual ripple call. -/\ntheorem operands (negative : Bool) (a t sign : List Bool) :\n    Runs program (5*t.length+5*(powerWord a.length).length+8) (.left negative)\n      (phase a t [] [] [] sign) (.subtract negative)\n      (phase a t (if negative then powerWord a.length else t)\n        (if negative then t else powerWord a.length) [] sign) :=by\n  have h0:=copy_empty (if negative then 4 else 2) (.left negative) (.right negative) rfl\n    (phase a t [] [] [] sign) rfl (by cases negative <;> rfl)\n  have he0:Function.update (phase a t [] [] [] sign) (copyTarget (if negative then 4 else 2))\n      (phase a t [] [] [] sign (copySource (if negative then 4 else 2)))=\n      phase a t (if negative then powerWord a.length else t) [] [] sign:=by\n    funext k;cases negative <;> rcases k with k|k <;> cases k <;> rfl\n  rw [he0] at h0\n  have h1:=copy_empty (if negative then 5 else 3) (.right negative) (.subtract negative) rfl\n    (phase a t (if negative then powerWord a.length else t) [] [] sign) rfl (by cases negative <;> rfl)\n  have he1:Function.update (phase a t (if negative then powerWord a.length else t) [] [] sign)\n      (copyTarget (if negative then 5 else 3))\n      (phase a t (if negative then powerWord a.length else t) [] [] sign (copySource (if negative then 5 else 3)))=\n      phase a t (if negative then powerWord a.length else t) (if negative then t else powerWord a.length) [] sign:=by\n    funext k;cases negative <;> rcases k with k|k <;> cases k <;> rfl\n  rw [he1] at h1\n  have hh:=join h0 h1\n  cases negative\n  · change Runs program ((5*t.length+4)+(5*(powerWord a.length).length+4)) _ _ _ _ at hh\n    convert hh using 1\n    omega\n  · change Runs program ((5*(powerWord a.length).length+4)+(5*t.length+4)) _ _ _ _ at hh\n    convert hh using 1\n    omega\n/-- Included subtraction has exact physical store and actual final borrow prefix. -/\ntheorem ripple (negative : Bool) (a t xs ys sign : List Bool) :\n    Runs program (3*(max xs.length ys.length+1)+2*(difference xs ys).length+4)\n      (.subtract negative) (phase a t xs ys [] sign)\n      (if negative then .readSecond else .readFirst)\n      (phase a t [] [] ((SemiprimeBitDivision.subBits xs ys false).borrow::difference xs ys) sign) :=by\n  have h:=subtract_call negative (phase a t xs ys [] sign) xs ys (fun _=>rfl)\n  have he:withSub (phase a t xs ys [] sign)\n      (S.store [] [] [] ((SemiprimeBitDivision.subBits xs ys false).borrow::difference xs ys))=\n      phase a t [] [] ((SemiprimeBitDivision.subBits xs ys false).borrow::difference xs ys) sign:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h\n  exact h\n/-- The actual first borrow is popped and saved as one physical singleton sign. -/\ntheorem read_first (a t diff : List Bool) (b : Bool) :\n    Runs program 2 .readFirst (phase a t [] [] (b::diff) [])\n      (if b then .clearWrapped else .scanCopy) (phase a t [] [] diff [b]) :=by\n  have h0:Runs program 1 .readFirst (phase a t [] [] (b::diff) [])\n      (.saveSign b) (phase a t [] [] diff []):=by\n    apply one_base program .readFirst (.saveSign b)\n      (.pop (subStack .output) (.saveSign false) (.saveSign false) (.saveSign true)) _ _ rfl\n    · cases b <;> rfl\n    · funext k;rcases k with k|k <;> cases k <;> rfl\n  have h1:=push (.saveSign b) (if b then .clearWrapped else .scanCopy) (aux .sign) b\n    (phase a t [] [] diff []) rfl\n  have he:Function.update (phase a t [] [] diff []) (aux .sign)\n      (b::phase a t [] [] diff [] (aux .sign))=phase a t [] [] diff [b]:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h1\n  exact join h0 h1\n/-- Underflow's wrapped low word is physically erased before the second subtraction. -/\ntheorem clear_wrapped (a t diff : List Bool) :\n    Runs program (diff.length+1) .clearWrapped (phase a t [] [] diff [true])\n      (.left true) (phase a t [] [] [] [true]) :=by\n  have h:=SemiprimeD1StackPhysicalLoops.drain program .clearWrapped (.left true) (subStack .output)\n    rfl (phase a t [] [] diff [true]) diff\n  have hi:Function.update (phase a t [] [] diff [true]) (subStack .output) diff=\n      phase a t [] [] diff [true]:=Function.update_eq_self _ _\n  have ho:Function.update (phase a t [] [] diff [true]) (subStack .output) []=\n      phase a t [] [] [] [true]:=by funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [hi,ho] at h\n  exact h\n/-- The second actual borrow is consumed; only its actual absolute low word remains. -/\ntheorem read_second (a t diff : List Bool) (b : Bool) :\n    Runs program 1 .readSecond (phase a t [] [] (b::diff) [true])\n      .scanCopy (phase a t [] [] diff [true]) :=by\n  apply one_base program .readSecond .scanCopy (.pop (subStack .output) .scanCopy .scanCopy .scanCopy) _ _ rfl\n  · cases b <;> rfl\n  · funext k;rcases k with k|k <;> cases k <;> rfl\n/-- Actual physical absolute subtraction, with paid underflow cleanup and all copies. -/\ntheorem source_run (a t : List Bool) :\n    ∃q≤200*(a.length+t.length+1),Runs program q (.left false)\n      (SemiprimeD1StackPhaseGeometryPower.prepared a t) .scanCopy\n      (phase a t [] [] (magnitude a.length t) [negative a.length t]) :=by\n  have h0:=operands false a t []\n  have h1:=ripple false a t t (powerWord a.length) []\n  have h2:=read_first a t (difference t (powerWord a.length)) (negative a.length t)\n  have hfirst:=join (join h0 h1) h2\n  have hlen:=difference_length t (powerWord a.length)\n  have hpow:=powerWord_length a.length\n  have hm:max t.length (powerWord a.length).length≤ t.length+a.length+1:=max_le (by omega) (by omega)\n  cases hn:negative a.length t with\n  | false=>\n    rw [hn] at hfirst\n    refine ⟨_,?_,by simpa only [magnitude,hn,Bool.false_eq_true,ite_false,phase,SemiprimeD1StackPhaseGeometryPower.prepared] using hfirst⟩\n    omega\n  | true=>\n    rw [hn] at hfirst\n    have h3:=clear_wrapped a t (difference t (powerWord a.length))\n    have h4:=operands true a t [true]\n    have h5:=ripple true a t (powerWord a.length) t [true]\n    have h6:=read_second a t (difference (powerWord a.length) t)\n      (SemiprimeBitDivision.subBits (powerWord a.length) t false).borrow\n    have hh:=join (join (join (join hfirst h3) h4) h5) h6\n    have hlen2:=difference_length (powerWord a.length) t\n    have hm2:max (powerWord a.length).length t.length≤ t.length+a.length+1:=max_le (by omega) (by omega)\n    refine ⟨_,?_,by simpa only [magnitude,hn,ite_true,phase,SemiprimeD1StackPhaseGeometryPower.prepared] using hh⟩\n    omega\nend RiemannGaussian.SemiprimeD1StackPhaseGeometrySubtract\n","RiemannGaussian.SemiprimeD1StackPortOrdinalStreamComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOrdinalStream\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\n/-! # Actual component calls for binary ordinal stream conversion -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortOrdinalStreamComponents\nopen SemiprimeD1StackPortOrdinalStream SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeD1StackProcedureTrace (runs_trans)\nlocal notation \"ctl\" => SemiprimeD1StackPortOrdinalStream.Label.control\n/-- Clean loop payload; all included private scratch is physically empty. -/\ndef data (bank reader word valid unary hist out:List Bool) : Stack→List Bool\n  | .bank => bank | .reader => reader | .word => word | .valid => valid\n  | .unary => unary | .history => hist | .output => out | _ => []\n/-- The actual parser reads one field, including a zero-length field. -/\ntheorem field_call (bank word tail hist:List Bool) :\n    Runs program (8*word.length+7) (ctl .parse) (data bank (frame word tail) [] [] [] hist [])\n      (ctl .clearValid) (data bank tail word [true] [] hist []) := by\n  apply included_call program fieldStack Label.field fieldStack_injective Field.code\n    (Field.active .tagPop (none,false)) (fun _=>rfl) (ctl .parse) (ctl .clearValid) rfl\n    (8*word.length+6) (Field.initial (frame word tail) [])\n    (⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩:\n      SemiprimeD1StackBytecode.State Field.Stack Field.Label)\n    (data bank (frame word tail) [] [] [] hist []) (data bank tail word [true] [] hist [])\n  · rfl\n  · rfl\n  · exact SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  · constructor\n    · intro k;cases k with\n      | inl k => cases k <;> rfl\n      | inr k => cases k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k with\n      | inl k => cases k <;> rfl\n      | inr k => cases k;rfl\n    · intro k hk;cases k <;> first\n        | rfl\n        | exact False.elim (hk (.inl .input) rfl)\n        | exact False.elim (hk (.inl .output) rfl)\n        | exact False.elim (hk (.inl .scratch) rfl)\n        | exact False.elim (hk (.inr ()) rfl)\n/-- Actual binary-to-unary conversion, retaining no native decoded answer. -/\ntheorem unary_call (bank tail word hist:List Bool) :\n    ∃m≤7*SemiprimeBitArithmetic.bitValue word+6*word.length+4,\n      Runs program m (ctl .convert) (data bank tail word [] [] hist []) (ctl .log)\n        (data bank tail [] [] (List.replicate (SemiprimeBitArithmetic.bitValue word) true) hist []) := by\n  let t:=2*word.length+1+SemiprimeD1StackUnaryCounterExecution.loopTime word.reverse 0\n  refine ⟨t+1,by have h:=SemiprimeD1StackUnaryCounterExecution.source_time word;omega,?_⟩\n  apply included_call program unaryStack Label.unary unaryStack_injective Unary.code .reverse\n    (fun _=>rfl) (ctl .convert) (ctl .log) rfl t\n    (SemiprimeD1StackUnaryCounter.state (some .reverse) none word [] [] [])\n    (SemiprimeD1StackUnaryCounter.state none none [] [] []\n      (List.replicate (SemiprimeBitArithmetic.bitValue word) true))\n    (data bank tail word [] [] hist [])\n    (data bank tail [] [] (List.replicate (SemiprimeBitArithmetic.bitValue word) true) hist [])\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackUnaryCounterExecution.source_run word\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk;cases k <;> first\n        | rfl\n        | exact False.elim (hk .left rfl)\n        | exact False.elim (hk .right rfl)\n        | exact False.elim (hk .scratch rfl)\n        | exact False.elim (hk .output rfl)\n\n\n/-- The original binary vector is physically copied and retained. -/\ntheorem copy_call (bank:List Bool) :\n    Runs program (5*bank.length+4) (ctl .start) (data bank [] [] [] [] [] [])\n      (ctl .next) (data bank bank [] [] [] [] []) := by\n  apply included_call program copyStack Label.copy copyStack_injective SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl .start) (ctl .next) rfl (5*bank.length+3)\n    (SemiprimeD1StackCopy.state 0 none bank [] []) (SemiprimeD1StackCopy.done bank bank)\n    (data bank [] [] [] [] [] []) (data bank bank [] [] [] [] [])\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words bank [] none\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k hk;cases k <;> first\n        | rfl\n        | exact False.elim (hk 1 rfl)\n/-- Empty unary words are logged as genuine empty vector fields. -/\ntheorem log_call (bank tail word hist:List Bool) :\n    ∃m≤6*(2*word.length+3)+1,Runs program m (ctl .log)\n      (data bank tail [] [] word hist []) (ctl .clearUnary)\n      (data bank tail [] [] word ((true::frame word []).reverse++hist) []) := by\n  obtain ⟨m,hm,hr⟩:=SemiprimeD1StackAssignmentBody.body_run word hist\n  refine ⟨m+1,by omega,?_⟩\n  apply included_call program bodyStack Label.body bodyStack_injective Body.code Body.entry\n    (fun _=>rfl) (ctl .log) (ctl .clearUnary) rfl m\n    (⟨some Body.entry,none,SemiprimeD1StackAssignmentBody.contents word [] hist⟩:\n      SemiprimeD1StackBytecode.State Body.Stack Body.Label)\n    (⟨none,none,SemiprimeD1StackAssignmentBody.contents word [] ((true::frame word []).reverse++hist)⟩:\n      SemiprimeD1StackBytecode.State Body.Stack Body.Label)\n    (data bank tail [] [] word hist [])\n    (data bank tail [] [] word ((true::frame word []).reverse++hist) [])\n  · rfl\n  · rfl\n  · exact hr\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk;cases k <;> first\n        | rfl\n        | exact False.elim (hk .history rfl)\n\n/-- Clear the physically written parser-valid bit before conversion. -/\ntheorem clear_valid (bank tail word hist:List Bool) :\n    Runs program 1 (ctl .clearValid) (data bank tail word [true] [] hist [])\n      (ctl .convert) (data bank tail word [] [] hist []) := by\n  apply one_base program (ctl .clearValid) (ctl .convert)\n    (.pop .valid (ctl .convert) (ctl .convert) (ctl .convert)) _ _ rfl\n  · rfl\n  · funext k;cases k <;> rfl\n/-- Physically clear the restored unary word after it has been logged. -/\ntheorem clear_unary (bank tail word hist:List Bool) :\n    Runs program (word.length+1) (ctl .clearUnary) (data bank tail [] [] word hist [])\n      (ctl .next) (data bank tail [] [] [] hist []) := by\n  have h:=SemiprimeD1StackPhysicalLoops.drain program (ctl .clearUnary) (ctl .next) Stack.unary rfl\n    (data bank tail [] [] [] hist []) word\n  have hi : Function.update (data bank tail [] [] [] hist []) Stack.unary word=\n      data bank tail [] [] word hist [] := by\n    funext k;cases k <;> simp [Function.update,data]\n  have ho : Function.update (data bank tail [] [] [] hist []) Stack.unary []=\n      data bank tail [] [] [] hist [] := Function.update_eq_self _ _\n  rw [hi,ho] at h\n  exact h\n/-- One physical reversal restores the original record ordering. -/\ntheorem reverse_run (hist bank out:List Bool) :\n    Runs program (2*hist.length+1) (ctl .reverse) (data bank [] [] [] [] hist out)\n      (ctl .done) (data bank [] [] [] [] [] (hist.reverse++out)) := by\n  induction hist generalizing out with\n  | nil =>\n    apply one_base program (ctl .reverse) (ctl .done)\n      (.pop .history (ctl .done) (ctl (.emit false)) (ctl (.emit true))) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  | cons b hist ih =>\n    have h0 : Runs program 1 (ctl .reverse) (data bank [] [] [] [] (b::hist) out)\n        (ctl (.emit b)) (data bank [] [] [] [] hist out) := by\n      apply one_base program (ctl .reverse) (ctl (.emit b))\n        (.pop .history (ctl .done) (ctl (.emit false)) (ctl (.emit true))) _ _ rfl\n      · cases b <;> rfl\n      · funext k;cases k <;> rfl\n    have h1 : Runs program 1 (ctl (.emit b)) (data bank [] [] [] [] hist out)\n        (ctl .reverse) (data bank [] [] [] [] hist (b::out)) := by\n      apply one_base program (ctl (.emit b)) (ctl .reverse) (.push .output b (ctl .reverse)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> rfl\n    have h:=runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ h0 h1) (ih (b::out))\n    simpa only [List.length_cons,List.reverse_cons,List.append_assoc,List.singleton_append,\n      show (1+1)+(2*hist.length+1)=2*(hist.length+1)+1 by omega] using h\nend RiemannGaussian.SemiprimeD1StackPortOrdinalStreamComponents\n","RiemannGaussian.SemiprimeD1StackPortOwnerRecipeClassify":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRecipeDecision\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nnamespace RiemannGaussian.SemiprimeD1StackPortOwnerRecipeClassify\nopen SemiprimeD1StackPortOwnerRecipe SemiprimeD1StackPortOwnerRecipeSpec\nopen SemiprimeD1StackPortOwnerRecipeEmit SemiprimeD1StackPortOwnerRecipeDecision\nopen SemiprimeD1StackProcedureTrace (Runs one_base runs_trans)\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Literal store during physical consumption of the copied original tag field. -/\ndef store (p:Counters) (remaining:ℕ) : Stack→List Bool :=\n  Function.update (prepared p) (reg .tagReader) (unary remaining)\n/-- The actual acquired tag counter starts with its exact original bytes. -/\ntheorem store_initial (p:Counters) : store p p.tag=prepared p := by\n  have he:prepared p (reg .tagReader)=unary p.tag:=rfl\n  unfold store\n  rw [←he]\n  exact Function.update_eq_self _ _\n/-- The original eight finite tags select exactly their original constructor branch. -/\ntheorem tagEnd_code (tag:Tag) : tagEnd (tagCode tag)=.local (.half tag) := by cases tag <;> rfl\n/-- Every tag marker and the final EOF are physically consumed. -/\ntheorem classify_suffix (p:Counters) (tag:Tag) (remaining count:ℕ)\n    (hc:count+remaining=(tagCode tag).val) :\n    Runs program (remaining+1) (.local (.classify ⟨count,by omega⟩))\n      (store p remaining) (.local (.half tag)) (ready p) := by\n  induction remaining generalizing count with\n  | zero=>\n    have he:count=(tagCode tag).val:=by omega\n    subst count\n    change Runs program 1 (.local (.classify (tagCode tag))) (ready p) (.local (.half tag)) (ready p)\n    apply one_base program _ _\n      (.pop (reg .tagReader) (tagEnd (tagCode tag))\n        (if h:(tagCode tag).val<17 then .local (.classify ⟨(tagCode tag).val+1,by omega⟩) else .local .abort)\n        (if h:(tagCode tag).val<17 then .local (.classify ⟨(tagCode tag).val+1,by omega⟩) else .local .abort))\n      _ _ rfl\n    · change some (tagEnd (tagCode tag))=some (.local (.half tag))\n      rw [tagEnd_code]\n    · change Function.update (ready p) (reg .tagReader) []=ready p\n      have hz:ready p (reg .tagReader)=[]:=Function.update_self _ _ _\n      rw [←hz]\n      exact Function.update_eq_self _ _\n  | succ remaining ih=>\n    have hcount:count<17:=by omega\n    have hn:count+1+remaining=(tagCode tag).val:=by omega\n    have hr:=ih (count+1) hn\n    let j:Fin 18:=⟨count,by omega⟩\n    let next:Label:=.local (.classify ⟨count+1,by omega⟩)\n    have hp:program (.local (.classify j))=.base (.pop (reg .tagReader) (tagEnd j) next next):=by\n      simp [program,j,next,hcount]\n    have hs:Runs program 1 (.local (.classify j)) (store p (remaining+1)) next (store p remaining):=by\n      apply one_base program _ _ (.pop (reg .tagReader) (tagEnd j) next next) _ _ hp\n      · rfl\n      · change Function.update (store p (remaining+1)) (reg .tagReader)\n          ((store p (remaining+1)) (reg .tagReader)).tail=store p remaining\n        unfold store\n        rw [Function.update_self,Function.update_idem]\n        rw [SemiprimeD1StackUnaryDivmod.unary_succ]\n        rfl\n    have h:=runs_trans program _ _ _ _ _ _ _ _ hs hr\n    simpa only [j,next,show 1+(remaining+1)=remaining+1+1 by omega] using h\n/-- Actual tag acquisition/classification, with at most eighteen literal reads. -/\ntheorem classify_run (p:Counters) (tag:Tag) (ht:p.tag=(tagCode tag).val) :\n    Runs program (p.tag+1) (.local (.classify 0)) (prepared p) (.local (.half tag)) (ready p) := by\n  have h:=classify_suffix p tag p.tag 0 (by omega)\n  rw [store_initial] at h\n  exact h\n/-- Original tag cases are a proof-side observation of the acquired edge fields. -/\ndef originalTag {r t digits:ℕ} (e:SemiprimeMacroGraph.Edge r t digits) : Tag :=\n  match e.1 with\n  | .inl (.input _ _,_)=>.input\n  | .inl (.first _ _ _,_)=>.first\n  | .inl (.twiddle _ _ _,_)=>.twiddle\n  | .inl (.second _ _ _,_)=>.second\n  | .inl (.product _,_)=>.product\n  | .inl (.carry _,_)=>.carry\n  | .inr (.digit _ _)=>.digit\n  | .inr (.orOut _ _)=>.orOut\n/-- Every actual original edge produces one of the eight physically classified tag words. -/\ntheorem original_tag {r t digits:ℕ} (e:SemiprimeMacroGraph.Edge r t digits) :\n    (original e).tag=(tagCode (originalTag e)).val := by\n  rcases e with ⟨s,half⟩\n  rcases s with ⟨w,bit⟩|flag\n  · cases w <;> rfl\n  · cases flag <;> rfl\nend RiemannGaussian.SemiprimeD1StackPortOwnerRecipeClassify\n","RiemannGaussian.SemiprimeD1StackPortOwnerRoutingLookup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRoutingKey\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPortOwnerRoutingLookup\nopen SemiprimeD1StackPortOwnerRouting SemiprimeD1StackPortOwnerRoutingAcquisition\nopen SemiprimeD1StackPortOwnerRoutingView\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\n/-- Real nested numeric lookup call, including its actual parser/comparison and final halt. -/\ntheorem lookup_call (m:Map.Stack→List Bool) (s:Scope.Stack→List Bool) (w:Fin 9→List Bool)\n    (a:Aux→List Bool) (query:List Bool) (rows:List (List Bool×List Bool)) :\n    Runs program (SemiprimeD1StackOwnerLookupExecution.loopTime query rows+2) (.local .lookup)\n      (data m s (SemiprimeD1StackOwnerLookup.initial query (SemiprimeD1StackOwnerLookup.records rows [])).data w a)\n      (.local .emitTag) (data m s (SemiprimeD1StackOwnerLookup.done query rows []).data w a) := by\n  apply SemiprimeD1StackProcedureInclusion.included_call program lookupStack Label.lookup lookup_injective\n    Lookup.program .loop (fun _=>rfl) (.local .lookup) (.local .emitTag) rfl\n    (SemiprimeD1StackOwnerLookupExecution.loopTime query rows+1)\n    (SemiprimeD1StackOwnerLookup.initial query (SemiprimeD1StackOwnerLookup.records rows []))\n    (SemiprimeD1StackOwnerLookup.done query rows []) _ _ rfl rfl rfl rfl\n    (SemiprimeD1StackOwnerLookupExecution.source_run query rows [])\n  · exact ⟨fun _=>rfl,fun _ _=>rfl⟩\n  · constructor\n    · intro k;rfl\n    · intro k hk;rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · exact False.elim (hk k rfl)\n          · rfl\n/-- Key-only actual lookup state has precisely the physically framed query and empty map reader. -/\ntheorem key_state (m:Map.Stack→List Bool) (s:Scope.Stack→List Bool) (w:Fin 9→List Bool) (a:Aux→List Bool) :\n    SemiprimeD1StackPortOwnerRoutingKey.store m s w a 6=\n      data m s (SemiprimeD1StackOwnerLookup.initial (SemiprimeD1PortOwnerRoutingSpec.query w) []).data w a := by\n  unfold SemiprimeD1StackPortOwnerRoutingKey.store\n  congr 1\n  funext k;rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- The retained actual complete E-map is copied into the real lookup reader for this occurrence. -/\ntheorem map_copy (m:Map.Stack→List Bool) (s:Scope.Stack→List Bool) (w:Fin 9→List Bool)\n    (a:Aux→List Bool) (hs:a .copyScratch=[]) :\n    Runs program (5*(m (SemiprimeD1StackOwnerCatalogue.aux .output)).length+4) (.local .copyMap)\n      (SemiprimeD1StackPortOwnerRoutingKey.store m s w a 6) (.local .lookup)\n      (data m s (SemiprimeD1StackOwnerLookup.initial (SemiprimeD1PortOwnerRoutingSpec.query w)\n        (m (SemiprimeD1StackOwnerCatalogue.aux .output))).data w a) := by\n  rw [key_state]\n  have h:=copy_call 2\n    (data m s (SemiprimeD1StackOwnerLookup.initial (SemiprimeD1PortOwnerRoutingSpec.query w) []).data w a)\n    (.local .copyMap) (.local .lookup) rfl hs\n  change Runs program _ _ _ _ (Function.update _ (lookupStack (.inr .reader))\n    (m (SemiprimeD1StackOwnerCatalogue.aux .output)++[])) at h\n  rw [List.append_nil,update_lookup] at h\n  have he:Function.update (SemiprimeD1StackOwnerLookup.initial (SemiprimeD1PortOwnerRoutingSpec.query w) []).data\n      (.inr .reader) (m (SemiprimeD1StackOwnerCatalogue.aux .output))=\n      (SemiprimeD1StackOwnerLookup.initial (SemiprimeD1PortOwnerRoutingSpec.query w)\n        (m (SemiprimeD1StackOwnerCatalogue.aux .output))).data:=by\n    funext k;rcases k with k|k\n    · cases k <;> rfl\n    · cases k <;> rfl\n  rw [he] at h\n  exact h\n/-- SAME-source actual preserved E-map copy followed by actual numeric owner lookup. -/\ntheorem copy_lookup_run (m:Map.Stack→List Bool) (s:Scope.Stack→List Bool) (w:Fin 9→List Bool)\n    (a:Aux→List Bool) (hs:a .copyScratch=[]) (rows:List (List Bool×List Bool))\n    (hm:m (SemiprimeD1StackOwnerCatalogue.aux .output)=SemiprimeD1StackOwnerLookup.records rows []) :\n    ∃time≤5*(SemiprimeD1StackOwnerLookup.records rows []).length+\n      SemiprimeD1StackOwnerLookupBounds.runBound (SemiprimeD1PortOwnerRoutingSpec.query w) rows+5,\n      Runs program time (.local .copyMap) (SemiprimeD1StackPortOwnerRoutingKey.store m s w a 6)\n        (.local .emitTag) (data m s (SemiprimeD1StackOwnerLookup.done (SemiprimeD1PortOwnerRoutingSpec.query w) rows []).data w a) := by\n  have hcopy:=map_copy m s w a hs\n  rw [hm] at hcopy\n  have hlook:=lookup_call m s w a (SemiprimeD1PortOwnerRoutingSpec.query w) rows\n  have h:=runs_trans program _ _ _ _ _ _ _ _ hcopy hlook\n  refine ⟨_,?_,h⟩\n  have ht:=SemiprimeD1StackOwnerLookupBounds.time_le (SemiprimeD1PortOwnerRoutingSpec.query w) rows\n  omega\nend RiemannGaussian.SemiprimeD1StackPortOwnerRoutingLookup\n","RiemannGaussian.SemiprimeD1StackProcedureCallsTrace":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1StackValidationLink\n\n/-! # Exact nested-procedure caller composition\nThis joins complete proved nested-call traces to actual larger callers. Every\ninternal call/return is preserved, not abstracted as a component evaluator.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 600000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\nopen SemiprimeD1StackProcedureTrace\n\n/-- A literal real call executes the included nested-call component trace,\nthen physically returns, preserving every outer frame and auxiliary cell. -/\ntheorem included_call {A K L G : Type} [DecidableEq A] [DecidableEq K]\n    (program : G→C.Instruction K G) (stack : A→K) (label : L→G)\n    (hinj : Function.Injective stack) (component : L→C.Instruction A L) (entry : L)\n    (hcode : ∀l,program (label l)=SemiprimeD1StackValidationLink.instruction stack label (component l))\n    (pc next : G) (hcall : program pc=.call (label entry) next)\n    (time : ℕ) (source out : C.State A L) (data result : K→List Bool)\n    (hentry : source.pc=some entry) (hstart : source.frames=[])\n    (hstop : out.pc=none) (hframes : out.frames=[])\n    (hr : C.run component time source=some out)\n    (hin : SemiprimeD1StackMultiplierLink.DataRel stack data source.data data)\n    (hout : SemiprimeD1StackMultiplierLink.DataRel stack data out.data result) :\n    Runs program (time+1) pc data next result := by\n  intro frames target h\n  rcases h with ⟨hpc,hdata,houter⟩\n  let mid:=C.execute (.call (label entry) next) target\n  have hm : C.run program 1 target=some mid := by\n    change C.step program target=some mid\n    simp only [C.step,SemiprimeD1StackCalls.step,hpc,Option.map_some,hcall,mid]\n  have hrel : SemiprimeD1StackValidationLink.Rel stack label data next frames source mid := by\n    constructor\n    · change SemiprimeD1StackMultiplierLink.DataRel stack data source.data target.data\n      rw [hdata]\n      exact hin\n    · simp only [SemiprimeD1StackValidationLink.PcRel,hentry,hstart,List.map_nil,List.nil_append,\n        mid,C.execute,houter,and_self]\n  obtain ⟨finish,hfinish,hrel⟩:=SemiprimeD1StackValidationLink.run_rel stack label hinj\n    program component hcode data next frames time source out mid hrel hr hframes\n  have hd : finish.data=result:=SemiprimeD1StackMultiplierLink.data_unique stack data\n    out.data finish.data result hrel.1 hout\n  have hp : finish.pc=some next ∧ finish.frames=frames := by\n    simpa only [SemiprimeD1StackValidationLink.PcRel,hstop] using hrel.2\n  refine ⟨finish,?_,hp.1,hd,hp.2⟩\n  rw [show time+1=1+time by omega,SemiprimeD1StackReturnLink.run_add,hm,Option.bind_some,hfinish]\n\nend RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n","RiemannGaussian.SemiprimeD1StackPublicCarryTableBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicCarryTableExecution\n/-! # Concrete carry-family whole bit clock and full114-role prefix cells -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicCarryTableBounds\nopen SemiprimeD1StackPublicCarryTable SemiprimeD1StackPublicCarryTableTrace\nopen SemiprimeD1StackPublicCarryTableExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace S\nexport SemiprimeD1StackStaticTableSpec (inputBytes)\nend S\n/-- Only original input/index bytes populate the actual51-role template bank. -/\ntheorem template_bytes (bits indexWord : List Bool) :\n    S.inputBytes (inputTemplate bits indexWord)≤51*(bits.length+indexWord.length) := by\n  change (∑k:P.Stack,(inputTemplate bits indexWord k).length)≤_\n  calc\n    _≤∑_k:P.Stack,(bits.length+indexWord.length):=Finset.sum_le_sum (fun k _=>template_cell_le bits indexWord k)\n    _= _:=by simp only [Finset.sum_const,Finset.card_univ,SemiprimeD1StackPublicCarry.stack_card,smul_eq_mul]\n/-- Honest actual original input inventory; scope IDs and padding are fully paid. -/\ndef inventory (bits indexWord : List Bool) (words : List (List Bool)) : Nat :=\n  bits.length+indexWord.length+(vectorBits words).length+2\n/-- One fixed whole-source polynomial per actually materialized scalar leaf. -/\ndef runBound (bits indexWord : List Bool) (words : List (List Bool)) : Nat :=\n  100000000000000000000*(inventory bits indexWord words)^2*2^words.length\n/-- Fixed natural arithmetic for the51-role source; the lemma keeps the\nkernel's closed role inventory separate from polynomial normalization. -/\ntheorem arithmetic_weight_bound (T n B scope I : Nat)\n    (hT:T≤51*I^2) (hn:n≤I^2) (hB:B≤1000000000000*I^2) (hs:scope≤I^2) (hOne:1≤I^2) :\n    11*scope+(51*(6*T+5)+7*n+B+51*(51*(T+n+B)+1)+20+20)+30≤\n      100000000000000000000*I^2 := by omega\n/-- Own complete carry-family bit time is polynomial in actual supplied input\nBYTES times2^physicallyCountedArity. The native checker report is never substituted. -/\ntheorem timeBound_le (bits indexWord : List Bool) (words : List (List Bool)) :\n    timeBound bits indexWord words≤ runBound bits indexWord words := by\n  let I:=inventory bits indexWord words\n  have hI:1≤ I:=by dsimp [I,inventory];omega\n  have hI2:I≤ I^2:=by simpa only [pow_one] using Nat.pow_le_pow_right hI (by decide : 1≤2)\n  have hn:=SemiprimeD1StackStaticTableBounds.scope_count_le words\n  have hRaw:bits.length+words.length+indexWord.length+2≤ I:=by dsimp [I,inventory];omega\n  have hbudget:budget bits indexWord words.length≤1000000000000*I^2:=\n    Nat.mul_le_mul_left _ (Nat.pow_le_pow_left hRaw 2)\n  have hT:=template_bytes bits indexWord\n  have hT2:S.inputBytes (inputTemplate bits indexWord)≤51*I^2:=\n    hT.trans (Nat.mul_le_mul_left _ (by dsimp [I,inventory] at *;omega))\n  have hn2:words.length≤ I^2:=by dsimp [I,inventory] at *;omega\n  have hb2:(vectorBits words).length≤ I^2:=by dsimp [I,inventory] at *;omega\n  have hOne:1≤I^2:=by omega\n  have hw:=arithmetic_weight_bound (S.inputBytes (inputTemplate bits indexWord)) words.length\n    (budget bits indexWord words.length) (vectorBits words).length I hT2 hn2 hbudget hb2 hOne\n  unfold timeBound SemiprimeD1StackStaticTableBounds.runBound\n    SemiprimeD1StackStaticTableDFS.weight SemiprimeD1StackStaticTableLeaf.leafBound\n  have hroles:static.roles.length=51:=roles_length\n  rw [SemiprimeD1StackPublicCarry.stack_card,hroles]\n  exact Nat.mul_le_mul_right (2^words.length) hw\n/-- Full actual original-N/index/scope execution with the closed same-source clock. -/\ntheorem source_run_bounded (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool)) :\n    ∃t≤ runBound bits indexWord words,SemiprimeD1StackCalls.run program t\n      (initial bits indexWord (vectorBits words))=some (done bits indexWord words) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits indexWord hb words\n  exact ⟨t,ht.trans (timeBound_le bits indexWord words),hr⟩\n/-- The genuine fixed114-role finite machine, with the same complete source clock. -/\nnoncomputable def machineTable (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool)) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits indexWord (vectorBits words)))\n      (some (SemiprimeD1StackCalls.configuration (done bits indexWord words))) (runBound bits indexWord words) := by\n  let h:=tableInTime bits indexWord hb words\n  exact ⟨h.toEvalsTo,h.steps_le_m.trans (timeBound_le bits indexWord words)⟩\n/-- All114 source roles and every actual nested return cell at EVERY prefix. -/\ntheorem prefix_cells (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (fuel : Nat) (finish : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial bits indexWord (vectorBits words))=some finish) :\n    (∑k:Stack,(finish.data k).length)+finish.frames.length≤\n      115*(51*(bits.length+indexWord.length)+(vectorBits words).length+runBound bits indexWord words+1) := by\n  have hs:=SemiprimeD1StackStaticTableBounds.prefix_cells static (inputTemplate bits indexWord)\n    (template_raw bits indexWord) (answer bits indexWord) (budget bits indexWord)\n    (actual_trace bits indexWord hb) words fuel finish hr\n  rw [SemiprimeD1StackPublicCarry.stack_card] at hs\n  change (∑k:Stack,(finish.data k).length)+finish.frames.length≤\n    115*(S.inputBytes (inputTemplate bits indexWord)+(vectorBits words).length+timeBound bits indexWord words+1) at hs\n  have hT:=template_bytes bits indexWord\n  have ht:=timeBound_le bits indexWord words\n  change timeBound bits indexWord words≤_ at ht\n  omega\n/-- Same full114-role and actual-return prefix certificate on the ACTUAL compiled machine. -/\ntheorem machine_prefix_cells (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits indexWord (vectorBits words))))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      115*(51*(bits.length+indexWord.length)+(vectorBits words).length+runBound bits indexWord words+1) := by\n  have hs:=SemiprimeD1StackStaticTableBounds.machine_prefix_cells static (inputTemplate bits indexWord)\n    (template_raw bits indexWord) (answer bits indexWord) (budget bits indexWord)\n    (actual_trace bits indexWord hb) words fuel cfg hr\n  rw [SemiprimeD1StackPublicCarry.stack_card] at hs\n  change (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n    115*(S.inputBytes (inputTemplate bits indexWord)+(vectorBits words).length+timeBound bits indexWord words+1) at hs\n  have hT:=template_bytes bits indexWord\n  have ht:=timeBound_le bits indexWord words\n  change timeBound bits indexWord words≤_ at ht\n  omega\nend RiemannGaussian.SemiprimeD1StackPublicCarryTableBounds\n","RiemannGaussian.SemiprimeD1StackPublicInputRecordBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicInputRecordExecution\nimport RiemannGaussian.SemiprimeD1StackStaticRecordBounds\nimport RiemannGaussian.SemiprimeD1StackPublicInputTableBounds\n/-! # Concrete input record clock and all132-role physical prefixes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicInputRecordBounds\nopen SemiprimeD1StackPublicInputRecord SemiprimeD1StackPublicInputRecordExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Actual scalar compiler bound plus paid scope conversion, logging and returns. -/\ndef runBound (bits indexWord : List Bool) (words : List (List Bool)) : Nat :=\n  SemiprimeD1StackPublicInputTableBounds.runBound bits indexWord words+\n    SemiprimeD1StackPortOrdinalStreamExecution.timeBound words+\n    SemiprimeD1StackVertexRecordStream.recordTime (SemiprimeD1StackPortOrdinalStream.result words)\n      (SemiprimeD1StackPublicInputTableExecution.table bits indexWord words)+4\n/-- Complete source bound uses the actual original checker's proved clock. -/\ntheorem timeBound_le (bits indexWord : List Bool) (words : List (List Bool)) :\n    timeBound bits indexWord words≤runBound bits indexWord words := by\n  have h0:=SemiprimeD1StackStaticTableBounds.timeBound_le I.static (I.inputTemplate bits indexWord)\n    words (T.answer bits indexWord) (T.budget bits indexWord)\n  have h1:=SemiprimeD1StackPublicInputTableBounds.timeBound_le bits indexWord words\n  unfold timeBound SemiprimeD1StackStaticRecordExecution.timeBound runBound\n    SemiprimeD1StackPublicInputTableExecution.table\n  change SemiprimeD1StackStaticTableExecution.timeBound I.static (I.inputTemplate bits indexWord)\n    words (T.answer bits indexWord) (T.budget bits indexWord)≤_ at h0\n  change SemiprimeD1StackStaticTableBounds.runBound I.static (I.inputTemplate bits indexWord)\n    words (T.budget bits indexWord)≤_ at h1\n  omega\n/-- Fully closed concrete source execution, no checker trace supplier remains. -/\ntheorem source_run_bounded (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (hist out : List Bool) :\n    ∃t≤runBound bits indexWord words,SemiprimeD1StackCalls.run program t\n      (initial bits indexWord (vectorBits words) hist out)=some (done bits indexWord words hist out) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits indexWord hb words hist out\n  exact ⟨t,ht.trans (timeBound_le bits indexWord words),hr⟩\n/-- Same genuine finite machine with the full concrete own source bound. -/\nnoncomputable def machineRecord (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (hist out : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits indexWord (vectorBits words) hist out))\n      (some (SemiprimeD1StackCalls.configuration (done bits indexWord words hist out))) (runBound bits indexWord words) := by\n  let h:=recordInTime bits indexWord hb words hist out\n  exact ⟨h.toEvalsTo,h.steps_le_m.trans (timeBound_le bits indexWord words)⟩\n/-- Every132-role source word and every real nested return cell at every prefix. -/\ntheorem prefix_cells (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (hist out : List Bool) (fuel : Nat) (finish : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial bits indexWord (vectorBits words) hist out)=some finish) :\n    (∑k:Stack,(finish.data k).length)+finish.frames.length≤\n      133*(52*(bits.length+indexWord.length)+(vectorBits words).length+hist.length+out.length+\n        runBound bits indexWord words+1) := by\n  have h:=SemiprimeD1StackStaticRecordBounds.prefix_cells I.static (I.inputTemplate bits indexWord)\n    (I.template_raw bits indexWord) (T.answer bits indexWord) (T.budget bits indexWord)\n    (T.actual_trace bits indexWord hb) words hist out fuel finish hr\n  rw [SemiprimeD1StackPublicInput.stack_card] at h\n  have ht:=timeBound_le bits indexWord words\n  have hb:=SemiprimeD1StackPublicInputTableBounds.template_bytes bits indexWord\n  change _≤133*(SemiprimeD1StackStaticTableSpec.inputBytes (I.inputTemplate bits indexWord)+\n    (vectorBits words).length+hist.length+out.length+timeBound bits indexWord words+1) at h\n  exact h.trans (by omega)\n/-- The complete inventory on the actual finite-control machine itself. -/\ntheorem machine_prefix_cells (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (hist out : List Bool) (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits indexWord (vectorBits words) hist out)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      133*(52*(bits.length+indexWord.length)+(vectorBits words).length+hist.length+out.length+\n        runBound bits indexWord words+1) := by\n  have h:=SemiprimeD1StackStaticRecordBounds.machine_prefix_cells I.static (I.inputTemplate bits indexWord)\n    (I.template_raw bits indexWord) (T.answer bits indexWord) (T.budget bits indexWord)\n    (T.actual_trace bits indexWord hb) words hist out fuel cfg hr\n  rw [SemiprimeD1StackPublicInput.stack_card] at h\n  have ht:=timeBound_le bits indexWord words\n  have hb:=SemiprimeD1StackPublicInputTableBounds.template_bytes bits indexWord\n  change _≤133*(SemiprimeD1StackStaticTableSpec.inputBytes (I.inputTemplate bits indexWord)+\n    (vectorBits words).length+hist.length+out.length+timeBound bits indexWord words+1) at h\n  exact h.trans (by omega)\nend RiemannGaussian.SemiprimeD1StackPublicInputRecordBounds\n","RiemannGaussian.SemiprimeD1StackPublicInputState":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicInputMeaning\n/-! # Exact physical states of the closed original public input program\nThese payload functions describe executed configurations only. They are not\nruntime/cache/getter/guard/verdict inputs to the fixed Core52 program.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 8192\nnamespace RiemannGaussian.SemiprimeD1StackPublicInputState\nopen SemiprimeD1StackPublicInput\nnamespace M\nexport SemiprimeD1StackPublicInputMeaning (cached word rawFlag actualBound expected)\nend M\n/-- Complete actual header source result, including original public metadata. -/\ndef acquired (bits indexWord : List Bool) : H.Stack→List Bool :=\n  SemiprimeD1StackPublicInputWidthExecution.result bits indexWord\n/-- Only the ACTUAL disposable header bound changes after comparison/draining. -/\ndef header (bits indexWord bd : List Bool) : H.Stack→List Bool :=\n  fun k=>if k=H.output then bd else acquired bits indexWord k\n/-- Exact52-role payload; every unused private/shadow/work cell is explicit empty.\nThe physical alias for the template/right operand is in the header, not the\nunused private shadow. Equality's output aliases the real comparison cell. -/\ndef store (h : H.Stack→List Bool) (raw reader word left comparison result : List Bool) : Stack→List Bool :=\n  Sum.elim h (Sum.elim\n    (fun k=>if k=0 then reader else if k=4 then word else [])\n    (Sum.elim (SemiprimeD1StackWordLess.store left [] [] [] comparison)\n      (Sum.elim (SemiprimeD1StackAdder.store [] [] [] result) (fun _=>raw))))\n/-- Actual original raw suffix after width-sized fitting (including short input). -/\ndef suffix (bits raw : List Bool) : List Bool := raw.drop (M.cached bits).length\n/-- Reached cells after the single real H37 call. -/\ndef ready (bits raw indexWord : List Bool) : Stack→List Bool :=\n  store (acquired bits indexWord) raw [] [] [] [] []\n/-- Reached cells after actual preserving raw-assignment Copy. -/\ndef afterCopy (bits raw indexWord : List Bool) : Stack→List Bool :=\n  store (acquired bits indexWord) raw raw [] [] [] []\n/-- Actual completed WordBlock, preserving every suffix byte and the original raw. -/\ndef afterBlock (bits raw indexWord : List Bool) : Stack→List Bool :=\n  store (acquired bits indexWord) raw (suffix bits raw) (M.word bits raw) [] [] []\n/-- Exact final state retains public metadata/index/raw/suffix, clears all\nbound/word/comparison work, and returns only the ACTUALLY computed verdict. -/\ndef done (bits raw indexWord : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,store (header bits indexWord []) raw (suffix bits raw) [] [] []\n    [M.expected bits raw indexWord],[]⟩\n/-- The SAME source's template is the actual shared block width. -/\n@[simp] theorem acquired_modulus (bits indexWord : List Bool) : acquired bits indexWord modulusKey=M.cached bits := rfl\n/-- The SAME actual source supplies the strict comparison bound. -/\n@[simp] theorem acquired_bound (bits indexWord : List Bool) : acquired bits indexWord H.output=M.actualBound bits indexWord := rfl\n/-- Updating the disposable bound preserves the shared original template. -/\n@[simp] theorem header_modulus (bits indexWord bd : List Bool) : header bits indexWord bd modulusKey=M.cached bits := rfl\n/-- Exact disposable bound projection. -/\n@[simp] theorem header_bound (bits indexWord bd : List Bool) : header bits indexWord bd H.output=bd := by simp [header]\n/-- The original header itself is this payload at its actually produced bound. -/\ntheorem header_acquired (bits indexWord : List Bool) :\n    header bits indexWord (M.actualBound bits indexWord)=acquired bits indexWord := by\n  funext k\n  by_cases hk:k=H.output\n  · subst k; rw [header_bound,acquired_bound]\n  · simp [header,hk]\n/-- The closed entry contains only original N, raw assignment and physical index. -/\ntheorem initial_data (bits raw indexWord : List Bool) :\n    (initial bits raw indexWord).data=store (SemiprimeD1StackPublicInputWidth.input bits indexWord) raw [] [] [] [] [] := by\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · fin_cases k <;> rfl\n    · rcases k with k|k\n      · rcases k with k|k <;> cases k <;> rfl\n      · rcases k with k|k <;> cases k <;> rfl\n/-- Exact real pop/push update of the physical extracted-word cell. -/\ntheorem update_word (h : H.Stack→List Bool) (raw reader word left cmp out fresh : List Bool) :\n    Function.update (store h raw reader word left cmp out) (blockStack 4) fresh=\n      store h raw reader fresh left cmp out := by\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · fin_cases k <;> rfl\n    · rfl\n/-- Exact real update of the only comparison-result cell. -/\ntheorem update_comparison (h : H.Stack→List Bool) (raw reader word left cmp out fresh : List Bool) :\n    Function.update (store h raw reader word left cmp out) comparison fresh=\n      store h raw reader word left fresh out := by\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rcases k with k|k <;> cases k <;> rfl\n      · rfl\n/-- Exact real update of the private final-output cell. -/\ntheorem update_output (h : H.Stack→List Bool) (raw reader word left cmp out fresh : List Bool) :\n    Function.update (store h raw reader word left cmp out) output fresh=\n      store h raw reader word left cmp fresh := by\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k <;> cases k <;> rfl\n/-- Actual bound consumption preserves EVERY other original header cell. -/\ntheorem update_bound (bits indexWord bd raw reader word left cmp out fresh : List Bool) :\n    Function.update (store (header bits indexWord bd) raw reader word left cmp out) bound fresh=\n      store (header bits indexWord fresh) raw reader word left cmp out := by\n  funext k\n  rcases k with k|k\n  · by_cases hk:k=H.output\n    · subst k; rfl\n    · simp [Function.update,store,bound,header,hk]\n  · rfl\n\n/-- Exact final computed singleton, with no supplied verdict input. -/\n@[simp] theorem done_output (bits raw indexWord : List Bool) :\n    (done bits raw indexWord).data output=[M.expected bits raw indexWord] := rfl\n/-- Entire original assignment is retained literally. -/\n@[simp] theorem done_raw (bits raw indexWord : List Bool) :\n    (done bits raw indexWord).data assignment=raw := rfl\n/-- The actual unread suffix, including any flag cell, is retained literally. -/\n@[simp] theorem done_suffix (bits raw indexWord : List Bool) :\n    (done bits raw indexWord).data (blockStack 0)=suffix bits raw := rfl\n/-- The original physical index is not normalized, consumed or replaced. -/\n@[simp] theorem done_index (bits raw indexWord : List Bool) :\n    (done bits raw indexWord).data index=indexWord := rfl\n/-- Every actual original public metadata cache survives the whole checker. -/\n@[simp] theorem done_public (bits raw indexWord : List Bool) (k : SemiprimeD1BinaryPublicAcquisition.Stack) :\n    (done bits raw indexWord).data (.inl (.inl k))=\n      SemiprimeD1BinaryPublicAcquisitionComponents.result bits k := rfl\n/-- The physically acquired disposable bound has been completely drained. -/\n@[simp] theorem done_bound (bits raw indexWord : List Bool) :\n    (done bits raw indexWord).data bound=[] := rfl\n/-- No fitted word remains in a private arithmetic cell. -/\n@[simp] theorem done_word (bits raw indexWord : List Bool) :\n    (done bits raw indexWord).data (blockStack 4)=[] := rfl\n\nend RiemannGaussian.SemiprimeD1StackPublicInputState\n","RiemannGaussian.SemiprimeD1StackPublicTransformMetadata":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransform\n/-! # Original acquired axes and canonical normalizer for the closed transform\nAll functions below are specifications of ACTUAL original-N acquisition fields.\nNo metadata, normalization value, source AST or canonicality answer is a runtime\nargument. The binary normalizer is the already executed Fermat construction.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformMetadata\nopen SemiprimeD1StackPublicTransform SemiprimeBitArithmetic SemiprimeMacroParameters\nopen SemiprimeMacroEntryBitPrimitives SemiprimeMacroEntryBitCheck\n/-- Actual completed root/source bank, proof view only. -/\ndef rootData (bits : List Bool) : R.Stack→List Bool := SemiprimeD1StackPublicScaleState.roots bits\n/-- Actual acquired original M word, not a supplied modulus. -/\ndef cached (bits : List Bool) : List Bool := SemiprimeD1StackPublicScaleState.cached bits\n/-- Actual acquired original root-code bytes, proof view only. -/\ndef baseCode (bits : List Bool) (inverse : Bool) : List Bool := SemiprimeD1StackPublicScaleState.baseCode bits inverse\n/-- Computable expected expression of the ACTUAL code, never runtime AST control. -/\ndef expression (bits : List Bool) (inverse : Bool) : Expr := SemiprimeD1StackPublicScaleInputs.expression bits inverse\n/-- Actual acquired n marker cells: t at first, r at second. -/\ndef count (bits : List Bool) (second : Bool) : List Bool := rootData bits (axisRole second)\n/-- Actual acquired complementary stride marker cells. -/\ndef stride (bits : List Bool) (second : Bool) : List Bool := count bits (!second)\n/-- Numerical specification of actual acquired marker count; not a runtime field. -/\ndef size (bits : List Bool) (second : Bool) : ℕ := if second then firstAxis bits.length else secondAxis bits.length\n/-- Actual normalization bytes: one literal cell, or the physically acquired\ncanonical inverse normalizer word, never a numerical/evaluator answer input. -/\ndef normalizer (bits : List Bool) (second inverse : Bool) : List Bool :=\n  if second && inverse then rootData bits (.inl (SemiprimeD1BinaryPublicAcquisition.fermatStack (.inr true))) else [true]\n/-- Original transform direction, with shared forward root4. -/\ndef transform (inverse : Bool) : SemiprimeMacroGraph.Transform := SemiprimeD1StackPublicScaleInputs.transform inverse\n/-- The actual n cache contains exactly original physically acquired unary cells. -/\ntheorem count_unary (bits : List Bool) (second : Bool) : count bits second=SemiprimeD1StackUnaryDivmod.unary (size bits second) := by\n  cases second <;> rfl\n/-- Complementary stride is acquired exactly as physical unary markers. -/\ntheorem stride_unary (bits : List Bool) (second : Bool) : stride bits second=SemiprimeD1StackUnaryDivmod.unary (size bits (!second)) :=\n  count_unary bits (!second)\n/-- The actual cached M is exactly original physical modulus bytes. -/\ntheorem original_modulus (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    cached bits=modulus (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) :=\n  SemiprimeD1StackPublicScaleInputs.original_modulus bits hc hN\n/-- The actual selected source bytes are exact, with no external AST/source. -/\ntheorem source_code (bits : List Bool) (inverse : Bool) :\n    baseCode bits inverse=SemiprimeD1StackExprCodec.encode (expression bits inverse) [] :=\n  SemiprimeD1StackPublicScaleInputs.source_code bits inverse\n/-- Every base-validity and modulus requirement is original-derived. -/\ntheorem original_valid (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) (inverse : Bool) :\n    1<bitValue (cached bits) ∧ Valid (cached bits) (expression bits inverse) := by\n  have h:=SemiprimeD1StackPublicScaleInputs.original_valid bits hc hN inverse\n  rw [←SemiprimeD1StackPublicScaleInputs.expression_original bits hc hN inverse] at h\n  exact h\n/-- Actual acquired inverse-normalizer word has the OLD original normalizer value. -/\ntheorem normalizer_source_value (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    bitValue (rootData bits (.inl (SemiprimeD1BinaryPublicAcquisition.fermatStack (.inr true))))=\n      (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN).normalizer.val :=\n  SemiprimeD1BinaryPublicAcquisitionBounds.public_normalizer bits hc hN\n/-- Canonicality of actual acquired normalization is derived, not guard advice. -/\ntheorem normalizer_canonical (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (second inverse : Bool) : bitValue (normalizer bits second inverse)<bitValue (cached bits) := by\n  rw [original_modulus bits hc hN]\n  cases second <;> cases inverse\n  · change 1<bitValue (modulus _)\n    have h:=modulus_gt_four (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN);omega\n  · change 1<bitValue (modulus _)\n    have h:=modulus_gt_four (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN);omega\n  · change 1<bitValue (modulus _)\n    have h:=modulus_gt_four (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN);omega\n  · change bitValue (rootData bits (.inl (SemiprimeD1BinaryPublicAcquisition.fermatStack (.inr true))))<_\n    rw [normalizer_source_value bits hc hN,modulus_value]\n    exact ZMod.val_lt _\nprivate theorem cast_heq {M N : ℕ} [NeZero N] (h : M=N) (x : ZMod N) : HEq (x.val : ZMod M) x := by\n  cases h\n  exact heq_of_eq (ZMod.natCast_zmod_val x)\n/-- Acquired normalization WORD is semantically the exact original factor,\nwithout re-evaluating its larger AST or transporting any old execution clock. -/\ntheorem normalizer_meaning (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (second inverse : Bool) :\n    meaning (cached bits) (.literal (normalizer bits second inverse))=\n      meaning (cached bits) (if second then normalizationExpr\n        (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) (transform inverse) else oneExpr) := by\n  cases second <;> cases inverse\n  · rfl\n  · rfl\n  · rfl\n  · rw [original_modulus bits hc hN]\n    let p:=SemiprimePublicFactorCount.publicConfig (bitValue bits) hN\n    have hv:=normalizer_source_value bits hc hN\n    have h1 : HEq (meaning (modulus p) (.literal (normalizer bits true true))) p.normalizer := by\n      change HEq (bitValue (rootData bits (.inl (SemiprimeD1BinaryPublicAcquisition.fermatStack (.inr true)))) :\n        ZMod (bitValue (modulus p))) p.normalizer\n      rw [hv]\n      exact cast_heq (modulus_value p) p.normalizer\n    have h2:=ringMeaning_eq p (normalizationExpr p (.inr ()))\n    rw [normalizationExpr_meaning] at h2\n    change HEq (meaning (modulus p) (normalizationExpr p (.inr ()))) p.normalizer at h2\n    exact eq_of_heq (h1.trans h2.symm)\nend RiemannGaussian.SemiprimeD1StackPublicTransformMetadata\n","RiemannGaussian.SemiprimeD1StackPublicTransformTableTrace":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformTable\nimport RiemannGaussian.SemiprimeD1StackStaticTableSpec\n/-! # Concrete complete trace contract from the frozen actual transform checker\nThere is no unknown checker/acquisition supplier in this instance. The entire\nliteral204-role source executes for every leaf, with its own proved bit clock.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformTableTrace\nopen SemiprimeD1StackPublicTransformTable SemiprimeD1StackStaticTableSpec\n/-- Actual complete transform postcondition, used only in specifications. -/\ndef answer (bits : List Bool) (second inverse : Bool) (raw : List Bool) : Bool :=\n  SemiprimeD1StackPublicTransformOriginal.verdict bits raw second inverse\n/-- The frozen complete original-input arithmetic source allowance. -/\ndef budget (bits : List Bool) (width : Nat) : Nat :=10^90*(bits.length+width+1)^18\n/-- Real template copy and reversed physical prefix reproduce the frozen input. -/\ntheorem initial_eq (bits raw : List Bool) (second inverse : Bool) :\n    checkerInitial static (inputTemplate bits second inverse) raw=P.initial bits raw second inverse := by\n  apply congrArg (fun d=>(⟨some .start,none,none,d,[]⟩:SemiprimeD1StackCalls.State P.Stack P.Label))\n    (template_raw_update bits raw second inverse)\n/-- Concrete contract discharged by the frozen ENTIRE original transform source,\nincluding actual roots/axes/modulus/normalization/vectors/guards/every query. -/\ntheorem actual_trace (bits : List Bool) (second inverse : Bool)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<SemiprimeBitArithmetic.bitValue bits) :\n    CheckerTrace static (inputTemplate bits second inverse) (answer bits second inverse) (budget bits) := by\n  intro raw\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackPublicTransformResources.source_run_bounded bits raw second inverse hc hN\n  refine ⟨t,ht,SemiprimeD1StackPublicTransformMachine.done bits raw second inverse,rfl,rfl,?_,?_⟩\n  · rw [initial_eq];exact hr\n  · exact SemiprimeD1StackPublicTransformOriginal.final_output bits raw second inverse\n/-- ONLY N and two physical singleton descriptor flags populate the template.\nNo arithmetic source, width/count, normalizer, vector, guard or verdict is present. -/\ntheorem template_only (bits : List Bool) (second inverse : Bool) (k : P.Stack) :\n    inputTemplate bits second inverse k=\n      if k=P.inputRole then bits else if k=P.second then [second] else if k=P.inverse then [inverse] else [] := by\n  have hk:=roles_complete k\n  change k∈roles at hk\n  simp only [roles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h | h\n  all_goals subst k;rfl\n/-- Each initialized physical field is paid by actual N bytes and a flag cell. -/\ntheorem template_cell_le (bits : List Bool) (second inverse : Bool) (k : P.Stack) :\n    (inputTemplate bits second inverse k).length≤bits.length+1 := by\n  rw [template_only]\n  split\n  · omega\n  · split\n    · simp only [List.length_cons,List.length_nil];omega\n    · split <;> simp only [List.length_cons,List.length_nil] <;> omega\nend RiemannGaussian.SemiprimeD1StackPublicTransformTableTrace\n","RiemannGaussian.SemiprimeD1StackPublicZeroBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicZeroExecution\nimport RiemannGaussian.SemiprimeD1StackRootSourceOriginal\n\n/-! # Whole actual zero-word checker: original-input time and all-prefix storage -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackPublicZeroBounds\nopen SemiprimeD1StackPublicZero SemiprimeD1StackPublicZeroExecution\n/-- Actual acquired modulus-word cell count, derived from original preprocessing. -/\ntheorem cached_length (bits : List Bool) : (cached bits).length=SemiprimeMacroParameters.transformLength bits.length+1 :=\n  SemiprimeD1StackRootSourceOriginal.modulus_length bits\n/-- The actual binary cache has linearly many cells in original physical width. -/\ntheorem cached_length_le (bits : List Bool) : (cached bits).length≤66*(bits.length+1) := by\n  rw [cached_length]\n  have h:=(SemiprimeD1StackTransformArithmetic.prefix_powers bits.length _ le_rfl).1\n  change SemiprimeMacroParameters.transformLength bits.length≤64*bits.length+1 at h\n  omega\n/-- The actual extracted word includes every original fixed-width padding bit. -/\ntheorem word_length (bits raw : List Bool) : (word bits raw).length=(cached bits).length :=\n  SemiprimeD1StackWordBlockExecution.result_length raw (cached bits)\n/-- Fixed whole-program quadratic in original binary N and actual raw assignment. -/\ndef runBound (bits raw : List Bool) : ℕ := 1000000000*(bits.length+raw.length+2)^2\n/-- All actual preprocessing, input copying, extraction, comparison and caller\ninstructions fit this bound on the SAME program, including rejected raw words. -/\ntheorem timeBound_le (bits raw : List Bool) : timeBound bits raw≤runBound bits raw := by\n  let I:=bits.length+raw.length+2\n  have hI : 1≤I := by dsimp [I];omega\n  have hi : I≤I^2 := by simpa only [pow_one] using Nat.pow_le_pow_right hI (by decide : 1≤2)\n  have hc : (cached bits).length≤66*I := by have h:=cached_length_le bits;dsimp [I];omega\n  have hr : raw.length≤I := by dsimp [I];omega\n  have hP : (bits.length+1)^2≤I^2 := Nat.pow_le_pow_left (by dsimp [I];omega) 2\n  have he:=SemiprimeD1StackWordEqualExecution.executionTime_le (word bits raw) []\n  simp only [List.length_nil,Nat.add_zero,word_length] at he\n  have hpos : 0<I^2 := Nat.pow_pos (by omega)\n  unfold timeBound SemiprimeD1BinaryPublicAcquisitionExecution.timeBound\n  rw [SemiprimeD1StackWordBlockBounds.totalTime_eq]\n  change _≤1000000000*I^2\n  omega\n/-- Complete same-source execution with fixed original-input polynomial clock. -/\ntheorem source_run_bounded (bits raw : List Bool) (hb : bits≠[]) :\n    ∃t≤runBound bits raw,C.run program t (initial bits raw)=some (done bits raw) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits raw hb\n  exact ⟨t,ht.trans (timeBound_le bits raw),hr⟩\n/-- Proof-only actual trace choice, absent from the executing instruction table. -/\nnoncomputable def sourceCheck (bits raw : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime (C.step program) (initial bits raw) (some (done bits raw)) (runBound bits raw) := by\n  let h:=source_run_bounded bits raw hb\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Genuine fixed finite-machine certificate, with the same actual source clock. -/\nnoncomputable def checkInTime (bits raw : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits raw))\n      (some (SemiprimeD1StackCalls.configuration (done bits raw))) (runBound bits raw) :=\n  SemiprimeD1StackCalls.evalsCorrect original output Label.start program _ _ _ (sourceCheck bits raw hb)\n/-- All successful prefixes occur before the proved complete actual halt. -/\ntheorem prefix_fuel_le (bits raw : List Bool) (hb : bits≠[]) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits raw)=some out) : fuel≤runBound bits raw := by\n  obtain ⟨t,ht,hh⟩:=source_run_bounded bits raw hb\n  have hf : fuel≤t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done bits raw)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Only original binary N and actual assignment bytes occupy initial cells. -/\ntheorem initial_length (bits raw : List Bool) (k : Stack) :\n    ((initial bits raw).data k).length≤bits.length+raw.length := by\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · cases k <;> simp only [initial,store,P.input,SemiprimeD1BinaryPublicAcquisition.store,\n          SemiprimeD1BinaryPublicAcquisition.Digits.input,SemiprimeD1BinaryDigitAcquisition.store,\n          SemiprimeD1StackTransform.input,Sum.elim_inl,List.length_nil] <;> omega\n      · rcases k with k|k <;> exact Nat.zero_le _\n    · rcases k with k|k <;> exact Nat.zero_le _\n  · rcases k with k|k\n    · fin_cases k <;> exact Nat.zero_le _\n    · rcases k with k|k\n      · cases k <;> exact Nat.zero_le _\n      · cases k;change raw.length≤bits.length+raw.length;omega\n/-- EVERY actual prefix counts all38 data roles, original caches/raw/suffix,\nevery parser/comparison shadow/work cell AND real finite-label return cells. -/\ntheorem prefix_cells (bits raw : List Bool) (hb : bits≠[]) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits raw)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤100000000000*(bits.length+raw.length+2)^2 := by\n  let I:=bits.length+raw.length\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel I _ out (initial_length bits raw) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length)≤38*(I+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(I+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits raw hb fuel out hr\n  change fuel≤1000000000*(I+2)^2 at ht\n  have hI : I≤(I+2)^2 := by\n    have h:=Nat.pow_le_pow_right (by omega : 1≤I+2) (by decide : 1≤2)\n    simp only [pow_one] at h\n    omega\n  change _≤100000000000*(I+2)^2\n  omega\n/-- Identical complete all-prefix inventory on the compiled finite machine. -/\ntheorem machine_prefix_cells (bits raw : List Bool) (hb : bits≠[]) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits raw)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤100000000000*(bits.length+raw.length+2)^2 := by\n  have he:=SemiprimeD1StackCalls.run_correct original output Label.start program fuel (initial bits raw)\n  change (C.run program fuel (initial bits raw)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits raw))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial bits raw) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits raw hb fuel out hc\nend RiemannGaussian.SemiprimeD1StackPublicZeroBounds\n","RiemannGaussian.SemiprimeD1StackRationalNormalizeExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalNormalizeSetup\nimport RiemannGaussian.SemiprimeD1StackRationalNormalizeArithmetic\n/-! # Whole actual two-word normalizer, exact legacy bytes and its own instruction clock -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalNormalizeExecution\nopen SemiprimeD1StackRationalNormalize SemiprimeD1StackRationalNormalizeEncoding SemiprimeD1StackRationalNormalizeCalls\nopen SemiprimeD1StackRationalNormalizeSetup SemiprimeD1StackRationalNormalizeArithmetic\nopen SemiprimeD1StackProcedureTrace\nnamespace S\nexport SemiprimeD1StackRationalNormalizeSpec (gcd numerator denominator word)\nend S\n/-- Actual positive-branch calls and drains; no legacy report clock appears. -/\ndef positiveTime (num den:List Bool) :Nat:=\n  (SemiprimeD1StackEuclidGCDExecution.runBound num den+1)+quotientTime num (S.gcd num den)+\n    quotientTime den (S.gcd num den)+(((S.gcd num den).length+1)+(num.length+1))\n/-- Complete actual positive arithmetic branch, including every real return and private-word drain. -/\ntheorem positive_run (negative:Bool) (num den:List Bool) :\n    Runs program (positiveTime num den) .gcdCall (bank (parsed negative num den)) .done\n      (bank {originalSigned:=negative::num,originalRight:=den,signOutput:=[negative], numeratorOutput:=S.numerator num den,denominatorOutput:=S.denominator num den}) :=by\n  have h0:=gcd_ready negative num den\n  have h1:=numerator_run negative num den (S.gcd num den) [] []\n  simp only [List.append_nil] at h1\n  have h2:=denominator_run negative num den (S.gcd num den) (S.numerator num den) []\n  simp only [List.append_nil] at h2\n  have h3:=cleanup_run negative num den (S.gcd num den) (S.numerator num den) (S.denominator num den)\n  exact P.join (P.join (P.join h0 h1) h2) h3\n/-- Own exact branch clock is selected by the actual copied-denominator OR bit. -/\ndef branchTime (num den:List Bool) :Nat:=\n  if (SemiprimeBitDivision.nonzeroBits den).nonzero then positiveTime num den else 2+1+1+(num.length+1)\n/-- Own whole source includes paid signed-word acquisition, guard, arithmetic/zero branch, cleanup and actual halt. -/\ndef runBound (num den:List Bool) :Nat:=setupTime num den+branchTime num den+1\n/-- Honest whole entry has only the original sign-prefixed binary numerator and original binary denominator.\nThe sign and magnitude are actually parsed; zero denominator is physically guarded. -/\ntheorem source_trace (negative:Bool) (num den:List Bool) :\n    Runs program (runBound num den-1) .start (input (negative::num) den) .done (result negative num den) :=by\n  have h0:=setup_run negative num den\n  cases hc:(SemiprimeBitDivision.nonzeroBits den).nonzero with\n  | false=>\n    have hz:SemiprimeBitArithmetic.bitValue den=0:=by\n      have hn:¬0<SemiprimeBitArithmetic.bitValue den:=by\n        intro hp\n        have he:=(SemiprimeBitDivision.nonzeroBits_correct den).mpr hp\n        rw [hc] at he;cases he\n      omega\n    rw [hc] at h0\n    have h1:=zero_run negative num den\n    have h:=P.join h0 h1\n    have he:bank {originalSigned:=negative::num,originalRight:=den,signOutput:=[false],denominatorOutput:=[true]}=\n        result negative num den:=by\n      unfold result SemiprimeD1StackRationalNormalizeSpec.word\n      rw [ite_eq_left hz]\n      rfl\n    rw [he] at h\n    simpa only [runBound,branchTime,hc,Bool.false_eq_true,ite_false,Nat.add_sub_cancel] using h\n  | true=>\n    have hp:=(SemiprimeBitDivision.nonzeroBits_correct den).mp hc\n    have hz:SemiprimeBitArithmetic.bitValue den≠0:=by omega\n    rw [hc] at h0\n    have h1:=positive_run negative num den\n    have h:=P.join h0 h1\n    have he:bank {originalSigned:=negative::num,originalRight:=den,signOutput:=[negative], numeratorOutput:=S.numerator num den,denominatorOutput:=S.denominator num den}=result negative num den:=by\n      unfold result SemiprimeD1StackRationalNormalizeSpec.word\n      rw [ite_eq_right hz]\n    rw [he] at h\n    simpa only [runBound,branchTime,hc,ite_true,Nat.add_sub_cancel] using h\n/-- Exact actual final halt clears flags and whole-entry return cells within the SAME complete source clock. -/\ntheorem source_run (negative:Bool) (num den:List Bool) :\n    SemiprimeD1StackCalls.run program (runBound num den) (initial (negative::num) den)=some (done negative num den) :=by\n  obtain ⟨finish,hfin,hAt⟩:=source_trace negative num den [] (initial (negative::num) den) ⟨rfl,rfl,rfl⟩\n  have he:runBound num den=(runBound num den-1)+1:=by unfold runBound;omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,hfin,Option.bind_some]\n  exact halt_run program .done rfl (result negative num den) [] finish hAt\n/-- Genuine fixed22-role finite machine executes from the original two actual words to exact normalized output. -/\nnoncomputable def normalizeInTime (negative:Bool) (num den:List Bool) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (initial (negative::num) den))\n      (some (SemiprimeD1StackCalls.configuration (done negative num den))) (runBound num den):=by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .originalSigned) (aux .numeratorOutput) .start program\n  exact ⟨⟨runBound num den,source_run negative num den⟩,le_rfl⟩\n/-- All three physical stopped output words equal exact legacy normalized bytes, without a padding shortcut. -/\ntheorem output_legacy (negative:Bool) (num den:List Bool) :\n    outputWord (done negative num den).data=(SemiprimeRationalBits.reduceBits ⟨⟨negative,num⟩,den⟩).word:=\n  SemiprimeD1StackRationalNormalizeSpec.word_legacy negative num den\n/-- The actual stopped signed numerator and denominator represent the original rational exactly. -/\ntheorem output_value (negative:Bool) (num den:List Bool) :\n    (outputWord (done negative num den).data).value=(⟨⟨negative,num⟩,den⟩:SemiprimeRationalBits.RationalWord).value:=\n  SemiprimeD1StackRationalNormalizeSpec.word_value negative num den\n/-- Actual normalized denominator is always positive, including the physically guarded total zero branch. -/\ntheorem output_valid (negative:Bool) (num den:List Bool) :(outputWord (done negative num den).data).Valid:=\n  SemiprimeD1StackRationalNormalizeSpec.word_valid negative num den\n/-- Canonical integer numerator and denominator are read from the three actual stopped output words. -/\ntheorem output_components (negative:Bool) (num den:List Bool) :\n    (outputWord (done negative num den).data).numerator.value=(⟨⟨negative,num⟩,den⟩:SemiprimeRationalBits.RationalWord).value.num ∧\n      SemiprimeBitArithmetic.bitValue (outputWord (done negative num den).data).denominator=\n        (⟨⟨negative,num⟩,den⟩:SemiprimeRationalBits.RationalWord).value.den:=\n  SemiprimeD1StackRationalNormalizeSpec.word_components negative num den\nend RiemannGaussian.SemiprimeD1StackRationalNormalizeExecution\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerStep\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineConvolution\n/-! # Complete actual descending-k convolution, with physical marker pops and all real source calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerLoop\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackRecoveryAffineCache (counter put_counter update_counter)\nopen SemiprimeD1StackRecoveryAffineReadCount (unary)\nopen SemiprimeD1StackRecoveryAffineOperationInput (emptyRational)\nopen SemiprimeD1StackRecoveryAffinePairMeaning (step)\n/-- Whole-loop proof clock is the sum of the same source iterations and actual marker pops. -/\ndef runBound (part:Part) (w:Words) (xs:List SemiprimeRationalBits.RationalWord)\n    (c:SemiprimeRationalBits.RationalWord) (width:List Bool) (n:Nat) (suffix:SemiprimeRationalBits.RationalWord):Nat:=\n  SemiprimeD1StackRecoveryAffineInnerStep.runBound part (counter w n) xs n c suffix width+1+\n    match n with\n    | 0=>0\n    | n+1=>runBound (nextPart part) w xs c width n\n      (step width (SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs (n+1))\n        (SemiprimeD1StackRecoveryAffineFactor.value part c) suffix)\n/-- Every k through zero is read and evaluated by the SAME fixed actual program; no zero terms are skipped. -/\ntheorem source_run (part:Part) (w:Words) (xs:List SemiprimeRationalBits.RationalWord) (n:Nat)\n    (c suffix:SemiprimeRationalBits.RationalWord) (width:List Bool)\n    (ha:w.added .array=vector xs) (hrd:w.added .reader=[]) (ht:w.added .readTodo=[])\n    (hx:∀b,w.registers (.numBase,b)=[]) (hy:∀b,w.registers (.denBase,b)=[]) (hp:∀b,w.registers (.numPower,b)=[])\n    (hc:w.auxiliary .copyScratch=[]) (hf:w.auxiliary .frameScratch=[]) (hv:w.auxiliary .scan=[])\n    (hr:w.rational=emptyRational width)\n    (hs:w.registers (.slope,false)=signed c) (hd:w.registers (.slope,true)=c.denominator):\n    ∃q≤runBound part w xs c width n suffix,\n      Runs program q (.local (.inner part)) (bank (putReg (counter w n) .denPower suffix))\n        (.local (.frame (.coefficient true)))\n        (bank (putReg (counter w 0) .denPower\n          (SemiprimeD1StackRecoveryAffineConvolution.descend width xs c part n suffix))):=by\n  induction n generalizing part suffix with\n  | zero=>\n    obtain ⟨t,htime,h0⟩:=SemiprimeD1StackRecoveryAffineInnerStep.source_run part (counter w 0) xs 0 c suffix width\n      ha (by simp only [counter,Function.update_self]) hrd ht hx hy hp hc hf hv hr hs hd\n    let answer:=step width (SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs 0)\n      (SemiprimeD1StackRecoveryAffineFactor.value part c) suffix\n    have h1:=SemiprimeD1StackRecoveryAffinePrimitives.pop_run (.local (.innerNext part))\n      (.local (.frame (.coefficient true))) (.local .abort) (.local (.inner (nextPart part))) (aux .k)\n      (bank (counter (putReg w .denPower answer) 0)) [] rfl rfl\n    change Runs program 1 _ _ (.local (.frame (.coefficient true)))\n      (Function.update (bank (counter (putReg w .denPower answer) 0)) (aux .k) (unary 0)) at h1\n    rw [update_counter] at h1\n    rw [←put_counter] at h1\n    refine ⟨t+1,?_,SemiprimeD1StackRecoveryAffinePrimitives.join h0 h1⟩\n    change t+1≤SemiprimeD1StackRecoveryAffineInnerStep.runBound part (counter w 0) xs 0 c suffix width+1+0\n    omega\n  | succ n ih=>\n    obtain ⟨t,htime,h0⟩:=SemiprimeD1StackRecoveryAffineInnerStep.source_run part (counter w (n+1)) xs (n+1) c suffix width\n      ha (by simp only [counter,Function.update_self]) hrd ht hx hy hp hc hf hv hr hs hd\n    let answer:=step width (SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs (n+1))\n      (SemiprimeD1StackRecoveryAffineFactor.value part c) suffix\n    have h1:=SemiprimeD1StackRecoveryAffinePrimitives.pop_run (.local (.innerNext part))\n      (.local (.frame (.coefficient true))) (.local .abort) (.local (.inner (nextPart part))) (aux .k)\n      (bank (counter (putReg w .denPower answer) (n+1))) (true::unary n) rfl\n      (by simp [bank,counter,aux,unary,List.replicate_succ])\n    change Runs program 1 _ _ (.local (.inner (nextPart part)))\n      (Function.update (bank (counter (putReg w .denPower answer) (n+1))) (aux .k) (unary n)) at h1\n    rw [update_counter] at h1\n    rw [←put_counter,←put_counter] at h1\n    obtain ⟨s,hstime,h2⟩:=ih (nextPart part) answer\n    refine ⟨t+1+s,?_,SemiprimeD1StackRecoveryAffinePrimitives.join\n      (SemiprimeD1StackRecoveryAffinePrimitives.join h0 h1) h2⟩\n    change t+1+s≤SemiprimeD1StackRecoveryAffineInnerStep.runBound part (counter w (n+1)) xs (n+1) c suffix width+1+\n      runBound (nextPart part) w xs c width n answer\n    omega\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerLoop\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineRetained":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineGeometry\n/-! # Whole actual retained-q acquisition, restoring every Grid104 word\nThe true geometry source, real marker subtraction/product, paid result copy and\ncomplete cleanup execute on the reached Grid bank. No q answer is supplied.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineRetained\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView SemiprimeD1StackRecoveryAffineCalls\nopen SemiprimeD1StackProcedureTrace\nnamespace Geom\nexport SemiprimeD1StackRecoveryAffineGeometry (result geometry_run order_bytes)\nend Geom\nnamespace Meta\nexport SemiprimeD1StackRecoveryAffineMultiplicity (words multiplicity_run runBound)\nend Meta\nnamespace Clear\nexport SemiprimeD1StackRecoveryAffineCleanup (geometry_run geometry_cleared)\nend Clear\n/-- Actual scanned order, interpreted only for the same-source invariant. -/\ndef order (a:Nat) (t:List Bool):Nat:=SemiprimeD1StackRecoveryGridRow.order a t\n/-- Physical originalt copy into the borrowed actual geometry index. -/\ndef asked (w:Words) (t:List Bool):Words:={w with auxiliary:=Function.update w.auxiliary .q t}\n/-- Exact actual true geometry bank after its shared-point cleanup. -/\ndef geometric (w:Words) (a:Nat) (t:List Bool):Words:=Geom.result (asked w t) (List.replicate a true) t\n/-- Exact actual unary retained-q product after real u-order and h multiplication. -/\ndef multiplied (w:Words) (a h u:Nat) (t:List Bool):Words:=\n  Meta.words (geometric w a t) [] [] (List.replicate (h*(u-order a t)) true) []\n/-- Actual preserving result copy retains q in its one additional readonly output word. -/\ndef saved (w:Words) (a h u:Nat) (t:List Bool):Words:=\n  {multiplied w a h u t with added:=Function.update w.added .retainedQ (List.replicate (h*(u-order a t)) true)}\n/-- All four actual unary-product work words are EMPTY after the paid product drain. -/\ndef productCleared (w:Words) (a h u:Nat) (t:List Bool):Words:=\n  {saved w a h u t with product:=SemiprimeD1StackUnaryProduct.contents [] [] [] []}\n/-- All ten geometry roles, including displaced shadows, are physically clear. -/\ndef geometryCleared (w:Words) (a h u:Nat) (t:List Bool):Words:=\n  {productCleared w a h u t with geometry:=fun _=>[]}\n/-- Actual final originalt scratch drain restores its original EMPTY value. -/\ndef result (w:Words) (a h u:Nat) (t:List Bool):Words:=\n  {geometryCleared w a h u t with auxiliary:=Function.update (geometryCleared w a h u t).auxiliary .q []}\n/-- This whole source retains EVERY original104 word and changes only its actual new q output. -/\ntheorem result_eq (w:Words) (a h u:Nat) (t:List Bool)\n    (hg:∀slot,w.geometry slot=[]) (hp:w.product=SemiprimeD1StackUnaryProduct.contents [] [] [] [])\n    (hq:w.auxiliary .q=[]) (ho:w.auxiliary .orderTodo=[]):\n    result w a h u t={w with added:=Function.update w.added .retainedQ (List.replicate (h*(u-order a t)) true)}:=by\n  have haux:Function.update (Function.update (Function.update w.auxiliary .q t) .orderTodo []) .q []=w.auxiliary:=by\n    funext slot\n    cases slot <;> simp only [Function.update_apply] <;> simp_all\n  have hgeom:w.geometry=(fun _=>[] ) :=funext hg\n  dsimp only [result,geometryCleared,productCleared,saved,multiplied,Meta.words,geometric,Geom.result,asked]\n  rw [haux,←hp,←hgeom]\n/-- Own whole q-acquisition budget sums the SAME actual source/copy/scan/drain clocks. -/\ndef runBound (w:Words) (a h u:Nat) (t:List Bool):Nat:=\n  (5*t.length+4)+(SemiprimeD1StackPhaseGeometryComponents.runBound (List.replicate a true) t+1+\n    (SemiprimeD1StackPhaseGeometryArithmetic.magnitude a t).length+1)+Meta.runBound h u (order a t)+\n    (5*(h*(u-order a t))+4)+(h*(u-order a t)+1)+\n    10*(SemiprimeD1StackRecoveryGridCleanup.mass (SemiprimeD1StackRecoveryGridView.bank (productCleared w a h u t).toWords)+1)+(t.length+1)\n/-- The original parameters, actual height and EMPTY work bank suffice; no multiplicity value or geometry answer is an input. -/\ntheorem retained_run (w:Words) (a h u:Nat) (t:List Bool)\n    (ha:w.auxiliary .originalA=List.replicate a true) (hu:w.auxiliary .originalU=List.replicate u true)\n    (ht:w.auxiliary .originalT=t) (hh:w.division .quotient=List.replicate h true)\n    (hg:∀slot,w.geometry slot=[]) (hr:∀slot,w.rational (SemiprimeD1StackRationalOperation.adderStack slot)=[])\n    (hp:w.product=SemiprimeD1StackUnaryProduct.contents [] [] [] [])\n    (hq:w.auxiliary .q=[]) (ho:w.auxiliary .orderTodo=[]) (hs:w.auxiliary .copyScratch=[]) (hz:w.added .retainedQ=[]):\n    ∃q≤runBound w a h u t,Runs program q (.local .ready) (bank w) (.local .copySlopes)\n      (bank {w with added:=Function.update w.added .retainedQ (List.replicate (h*(u-order a t)) true)}):=by\n  have h0:=PTrace.copy_call .originalT (.local .ready) (.local .geometry) rfl (bank w) t [] ht hq hs\n  change Runs program (5*t.length+4) _ _ _ (Function.update (bank w) (oldAux .q) (t++[])) at h0\n  rw [List.append_nil,update_oldAux] at h0\n  change Runs program (5*t.length+4) _ _ _ (bank (asked w t)) at h0\n  have hi:∀slot,bank (asked w t) (geometry slot)=SemiprimeD1StackPhaseGeometry.input (List.replicate a true) t slot:=by\n    intro slot\n    rcases slot with slot|slot\n    · cases slot <;> exact hr _\n    · cases slot\n      · exact ha\n      · rfl\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n  obtain ⟨p,hpBound,h1⟩:=Geom.geometry_run (asked w t) (List.replicate a true) t hi (hr .output)\n  change Runs program p _ _ _ (bank (geometric w a t)) at h1\n  have hord:(geometric w a t).geometry .order=List.replicate (order a t) true:=Geom.order_bytes (asked w t) a t\n  have ho0:(geometric w a t).auxiliary .orderTodo=[]:=ho\n  have hprod:(geometric w a t).product=SemiprimeD1StackUnaryProduct.contents [] [] [] []:=hp\n  have hupdate:Function.update (geometric w a t).auxiliary .orderTodo []=(geometric w a t).auxiliary:=Function.update_eq_self_iff.mpr ho0.symm\n  have hin:Meta.words (geometric w a t) [] [] [] []=geometric w a t:=by unfold Meta.words;rw [←hprod,hupdate]\n  obtain ⟨q,hqBound,h2⟩:=Meta.multiplicity_run (geometric w a t) h u (order a t) hu hord hh hs\n  rw [hin] at h2\n  change Runs program q _ _ _ (bank (multiplied w a h u t)) at h2\n  have h3:=PTrace.copy_call .retained (.local .retained) (.local .clearProduct) rfl\n    (bank (multiplied w a h u t)) (List.replicate (h*(u-order a t)) true) [] rfl hz hs\n  change Runs program _ _ _ _ (Function.update (bank (multiplied w a h u t)) (aux .retainedQ) (List.replicate (h*(u-order a t)) true++[])) at h3\n  rw [List.append_nil,update_added] at h3\n  change Runs program _ _ _ _ (bank (saved w a h u t)) at h3\n  have h4:=PTrace.drain_loop (.local .clearProduct) (.local (.clearGeometry 0)) (product .product) rfl\n    (bank (saved w a h u t)) (List.replicate (h*(u-order a t)) true) rfl\n  rw [update_product] at h4\n  have hpf:Function.update (saved w a h u t).product .product []=SemiprimeD1StackUnaryProduct.contents [] [] [] []:=by\n    funext slot\n    cases slot <;> rfl\n  rw [hpf] at h4\n  change Runs program _ _ _ _ (bank (productCleared w a h u t)) at h4\n  obtain ⟨s,hsBound,h5⟩:=Clear.geometry_run (productCleared w a h u t)\n  rw [Clear.geometry_cleared] at h5\n  change Runs program s _ _ _ (bank (geometryCleared w a h u t)) at h5\n  have h6:=PTrace.drain_loop (.local .clearQ) (.local .copySlopes) (oldAux .q) rfl\n    (bank (geometryCleared w a h u t)) t rfl\n  rw [update_oldAux] at h6\n  change Runs program (t.length+1) _ _ _ (bank (result w a h u t)) at h6\n  rw [result_eq w a h u t hg hp hq ho] at h6\n  have hrun:=PTrace.join (PTrace.join (PTrace.join (PTrace.join (PTrace.join (PTrace.join h0 h1) h2) h3) h4) h5) h6\n  simp only [List.length_replicate] at hrun hpBound\n  refine ⟨(5*t.length+4)+p+q+(5*(h*(u-order a t))+4)+(h*(u-order a t)+1)+s+(t.length+1),?_,hrun⟩\n  unfold runBound\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineRetained\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeBuffers":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineOperationOutput\n/-! # Exact physical slope-row reversal buffers and restored scalar cache -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeBuffers\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView\n/-- Only actual forward reader and reversed-row output change during slope acquisition. -/\ndef buffers (w:Words) (reader reversed:List Bool):Words:=\n  {w with added:=fun slot=>if slot=.reader then reader else if slot=.reverseSlopes then reversed else w.added slot}\n/-- A real reader write preserves the entire original bank and every accumulated reversed row. -/\ntheorem update_reader (w:Words) (reader reversed xs:List Bool):\n    Function.update (bank (buffers w reader reversed)) (aux .reader) xs=bank (buffers w xs reversed):=by\n  rw [update_added]\n  congr 1\n  congr 1\n  funext slot\n  cases slot <;> simp [buffers]\n/-- A real frame/tag write preserves the unread forward suffix and every other110 word. -/\ntheorem update_reversed (w:Words) (reader reversed xs:List Bool):\n    Function.update (bank (buffers w reader reversed)) (aux .reverseSlopes) xs=bank (buffers w reader xs):=by\n  rw [update_added]\n  congr 1\n  congr 1\n  funext slot\n  cases slot <;> simp [buffers]\n/-- Acquired scalar caches and added physical row buffers are disjoint actual data roles. -/\ntheorem put_buffers (w:Words) (r:SemiprimeD1StackRecoveryGrid.Reg) (x:SemiprimeRationalBits.RationalWord) (reader reversed:List Bool):\n    putReg (buffers w reader reversed) r x=buffers (putReg w r x) reader reversed:=rfl\n/-- Both literal signed/denominator drains restore the original EMPTY slope cache, including W0. -/\ntheorem erase_put (w:Words) (x:SemiprimeRationalBits.RationalWord)\n    (hn:w.registers (.slope,false)=[]) (hd:w.registers (.slope,true)=[]):\n    SemiprimeD1StackRecoveryAffineOperationOutput.emptyReg (putReg w .slope x) .slope=w:=by\n  dsimp only [SemiprimeD1StackRecoveryAffineOperationOutput.emptyReg,putReg]\n  congr 1\n  congr 1\n  funext slot\n  rcases slot with ⟨r,b⟩\n  cases r <;> cases b <;> simp [hn,hd]\n/-- The two row buffers initially equal their actual existing physical words. -/\ntheorem buffers_self (w:Words):buffers w (w.added .reader) (w.added .reverseSlopes)=w:=by\n  unfold buffers\n  congr 1\n  funext slot\n  cases slot <;> rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeBuffers\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopesBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineReadBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopes\n/-! # One paid row reversal has linear whole-source cost in the ACTUAL original framed slope bytes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopesBounds\nopen SemiprimeD1StackRecoveryAffineView\nopen SemiprimeRationalBits (RationalWord)\n/-- The actual complete framed vector length is the sum of actual per-row bit lengths plus its terminator. -/\ntheorem vector_sum (xs:List RationalWord):\n    (vector xs).length=(xs.map (fun x=>2*(x.numerator.magnitude.length+x.denominator.length)+5)).sum+1:=by\n  induction xs with\n  | nil=>rfl\n  | cons x xs ih=>\n    change (SemiprimeD1StackRecoveryGridView.slopeRow x (vector xs)).length=_\n    rw [SemiprimeD1StackRecoveryGridByteBounds.slopeRow_length,ih]\n    simp only [List.map_cons,List.sum_cons]\n    omega\n/-- Reversing row ORDER changes none of the physically copied raw sign/padding/framing bytes. -/\ntheorem vector_reverse_length (xs:List RationalWord):(vector xs.reverse).length=(vector xs).length:=by\n  rw [vector_sum,List.map_reverse,List.sum_reverse,←vector_sum]\n/-- Every TRUE tag, actual two-Field/two-Frame call, both scalar drains and final EOF are paid once. -/\ntheorem reverse_le (xs:List RationalWord):\n    SemiprimeD1StackRecoveryAffineSlopeReverse.runBound xs≤ 30*(vector xs).length:=by\n  induction xs with\n  | nil=>change 2≤30*1;decide\n  | cons x xs ih=>\n    change SemiprimeD1StackRecoveryAffineSlopeReverse.rowTime x+\n      SemiprimeD1StackRecoveryAffineSlopeReverse.runBound xs≤ _\n    rw [SemiprimeD1StackRecoveryAffineReadBounds.row_length]\n    unfold SemiprimeD1StackRecoveryAffineSlopeReverse.rowTime\n    omega\n/-- Whole real original-tape copy/reversal/literal-ONE seed costs a fixed linear actual-byte budget. -/\ntheorem source_le (xs:List RationalWord):\n    SemiprimeD1StackRecoveryAffineSlopes.runBound xs≤ 50*((vector xs).length+1):=by\n  have h:=reverse_le xs\n  unfold SemiprimeD1StackRecoveryAffineSlopes.runBound\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopesBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineBounds\n/-! # All112 actual affine data words and real return cells at every compiled prefix\nThe initial configuration has the honest five acquired physical input words.\nThis does not assert N-only initList for a prepared metadata/template source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineStorage\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineBounds\nnamespace R\nexport SemiprimeD1StackRecoveryGridResource (resource resource_pos)\nend R\nnamespace E\nexport SemiprimeD1StackRecoveryAffineEncoding (done)\nend E\n/-- Exactly five actual words start populated; all additional affine words start empty. -/\ntheorem initial_role_bound (a M u:Nat) (t width:List Bool) (slot:Stack):\n    ((initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width).data slot).length≤ R.resource a M u t width:=by\n  rcases slot with slot|slot\n  · exact SemiprimeD1StackRecoveryGridStorage.initial_role_bound a M u t width slot\n  · exact Nat.zero_le _\n/-- Every genuine actual source prefix stops before the SAME program's own proved whole halt. -/\ntheorem prefix_fuel (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val) (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel\n      (initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width)=some out):\n    fuel≤ polynomial a M u t width:=by\n  obtain ⟨s,hs,hstop⟩:=source_run_bounded a M u selected t width ht\n  have hbefore:fuel≤ s:=by\n    by_contra hn\n    have he:fuel=s+(1+(fuel-(s+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hh:SemiprimeD1StackCalls.run program 1 (E.done a M u selected t width)=none:=rfl\n    rw [hh,Option.bind_none] at hr\n    cases hr\n  exact hbefore.trans hs\n/-- Whole112-role mass counts every retained Grid word, every actual array/count buffer and every displaced shadow. -/\ntheorem word_sum (data:Stack→List Bool) (cap:Nat) (h:∀slot,(data slot).length≤ cap):\n    (∑slot:Stack,(data slot).length)≤ 112*cap:=SemiprimeD1StackRecoveryAffineCleanup.word_sum data cap h\n/-- Every actual data cell and every saved real return at the SAME whole-program prefix is paid. -/\ntheorem prefix_cells (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val) (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel\n      (initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width)=some out):\n    (∑slot:Stack,(out.data slot).length)+out.frames.length≤ 113*(R.resource a M u t width+polynomial a M u t width):=by\n  have hf:=prefix_fuel a M u selected t width ht fuel out hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (R.resource a M u t width)\n    (initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width) out (initial_role_bound a M u t width) hr\n  have hm:=word_sum out.data (R.resource a M u t width+fuel) hd\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel\n    (initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width) out hr\n  change out.frames.length≤ 0+fuel at hframes\n  omega\n/-- Fixed whole physical-storage polynomial precedes every actual input and every selected node. -/\ndef spacePolynomial (a M u:Nat) (t width:List Bool):Nat:=10^78*(R.resource a M u t width)^14\n/-- Same source clock and actual input word mass give a fixed complete112-plus-return cap. -/\ntheorem cells_le (a M u:Nat) (t width:List Bool):\n    113*(R.resource a M u t width+polynomial a M u t width)≤ spacePolynomial a M u t width:=by\n  have hp:R.resource a M u t width≤ (R.resource a M u t width)^14:=Nat.le_pow (by decide:0<14)\n  unfold polynomial spacePolynomial\n  omega\n/-- All112 Boolean roles plus the actual finite return-cell alphabet are counted at EVERY genuine compiled prefix. -/\ntheorem machine_prefix_cells (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val) (fuel:Nat) (cfg:machine.Cfg)\n    (hp:(fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width)))=some cfg):\n    (∑slot:Stack,(cfg.stk (some slot)).length)+(cfg.stk none).length≤ spacePolynomial a M u t width:=by\n  have he:=SemiprimeD1StackCalls.run_correct (oldAux .originalA) (aux .array) (.local .start) program fuel\n    (initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width)\n  have hh:=he.trans hp\n  cases hout:SemiprimeD1StackCalls.run program fuel\n      (initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:cfg=SemiprimeD1StackCalls.configuration out:=(Option.some.inj hh).symm\n    subst cfg\n    exact (prefix_cells a M u selected t width ht fuel out hout).trans (cells_le a M u t width)\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineStorage\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesFields\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesRead\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesOrder\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesCleanup\n/-! # Complete actual row-to-entry acquisition and occurrence-preserving order\nEvery input row is parsed, read twice through actual binary indexed scans,\nframed, logged and cleaned. Missing child coordinates produce empty payloads;\nthey never remove rows. One final actual reverse restores original row order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesLoop\nopen SemiprimeD1StackRecoveryEntries SemiprimeD1StackRecoveryEntriesState\nopen SemiprimeD1StackRecoveryEntriesPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackRecoveryDenominatorEncoding (Row fields tape)\nopen SemiprimeD1StackRecoveryEntriesEncoding (childTape selectedChild)\nopen SemiprimeD1StackRecoveryEntriesOrder (chunks)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeBitArithmetic (bitValue)\nnamespace P\nexport SemiprimeD1StackRecoveryEntriesFields (parse_run time)\nend P\nnamespace R\nexport SemiprimeD1StackRecoveryEntriesRead (read_run time)\nend R\nnamespace L\nexport SemiprimeD1StackRecoveryEntriesLogger (row_run rowTime chunk reverse_call)\nend L\nnamespace K\nexport SemiprimeD1StackRecoveryEntriesCleanup (source_run cleared_words mass)\nend K\n/-- Exact seven actually cleared source/cache word-byte lengths. -/\ndef clearMass (r:Row) (row child:List Bool):Nat:=\n  (r 0).length+(r 1).length+(r 2).length+(r 3).length+(r 4).length+row.length+child.length\n/-- Actual per-row cleanup work does not rescan prior output/history. -/\ntheorem mass_words (original reader:List Bool) (r:Row) (row child valid history buffer out:List Bool):\n    K.mass (words original reader r row child valid history buffer out) 0=clearMass r row child:=by\n  simp only [K.mass,SemiprimeD1StackRecoveryEntriesCleanup.cleanup,List.drop_zero,List.map_cons,List.map_nil,List.sum_cons,List.sum_nil,words]\n  unfold clearMass\n  omega\n/-- Exact actually acquired encoded row cache, including the missing-node empty-vector sentinel. -/\ndef selectedRow (children:List (List (List Bool))) (r:Row):List Bool:=vectorBits ((children[bitValue (r 0)]?).getD [])\n/-- SAME actual row-step clock, independent of previous entry history and output bytes. -/\ndef rowTime (children:List (List (List Bool))) (r:Row):Nat:=\n  1+P.time r+R.time children r+L.rowTime r (selectedChild children (r 0) (r 1))+\n    (clearMass r (selectedRow children r) (selectedChild children (r 0) (r 1))+7)\n/-- One actual row produces one entry, preserving duplicates, zeros and both EOF defaults. -/\ntheorem row_run (children:List (List (List Bool))) (original:List Bool) (r:Row) (rs:List Row) (history out:List Bool):\n    Runs program (rowTime children r) (.local .loop)\n      (data (childTape children) (words original (tape (r::rs)) (fun _=>[]) [] [] [] history [] out)) (.local .loop)\n      (data (childTape children) (words original (tape rs) (fun _=>[]) [] [] []\n        ((L.chunk r (selectedChild children (r 0) (r 1))).reverse++history) [] out)):=by\n  have h0:=pop_run (.local .loop) (.local .abort) (.local .finish) (.local (.field 0)) .reader (childTape children)\n    (words original (tape (r::rs)) (fun _=>[]) [] [] [] history [] out) (true::fields r (tape rs)) rfl rfl\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n  rw [update_reader] at h0\n  have h1:=P.parse_run (childTape children) original (fields r (tape rs)) r (tape rs) [] [] history [] out rfl\n  have h2:=R.read_run children original (tape rs) r history [] out\n  have h3:=L.row_run (childTape children) original (tape rs) r (selectedRow children r)\n    (selectedChild children (r 0) (r 1)) history out\n  have h4:=K.source_run (childTape children) (words original (tape rs) r (selectedRow children r)\n    (selectedChild children (r 0) (r 1)) [] ((L.chunk r (selectedChild children (r 0) (r 1))).reverse++history) [] out)\n  rw [mass_words,K.cleared_words] at h4\n  exact join (join (join (join h0 h1) h2) h3) h4\n/-- Exact own whole row-loop clock, including the single actual final reverse. -/\ndef budget (children:List (List (List Bool))):List Row → List Bool → Nat\n  | [],history=>1+(2*history.length+3)\n  | r::rs,history=>rowTime children r+budget children rs ((L.chunk r (selectedChild children (r 0) (r 1))).reverse++history)\n/-- Whole actual entry loop restores original row order after one final physical reverse. -/\ntheorem loop_run (children:List (List (List Bool))) (rs:List Row) (original history out:List Bool):\n    Runs program (budget children rs history) (.local .loop)\n      (data (childTape children) (words original (tape rs) (fun _=>[]) [] [] [] history [] out)) (.local .done)\n      (data (childTape children) (words original [] (fun _=>[]) [] [] [] [] []\n        (history.reverse++chunks children rs++out))):=by\n  induction rs generalizing history with\n  | nil=>\n    have h0:=pop_run (.local .loop) (.local .abort) (.local .finish) (.local (.field 0)) .reader (childTape children)\n      (words original [false] (fun _=>[]) [] [] [] history [] out) [false] rfl rfl\n    simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n    rw [update_reader] at h0\n    have h1:=L.reverse_call true (.local .finish) (.local .done) (childTape children)\n      (words original [] (fun _=>[]) [] [] [] history [] out) rfl\n    change Runs program (2*history.length+3) (.local .finish)\n      (data (childTape children) (words original [] (fun _=>[]) [] [] [] history [] out)) (.local .done)\n      (data (childTape children) (Function.update (Function.update (words original [] (fun _=>[]) [] [] [] history [] out) .history []) .output (history.reverse++out))) at h1\n    rw [update_history,update_out] at h1\n    simpa only [budget,chunks,List.append_nil,tape] using join h0 h1\n  | cons r rs ih=>\n    have h0:=row_run children original r rs history out\n    have h1:=ih ((L.chunk r (selectedChild children (r 0) (r 1))).reverse++history)\n    have h:=join h0 h1\n    simpa only [budget,chunks,List.reverse_append,List.reverse_reverse,List.append_assoc] using h\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesLoop\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishCache":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishMoves\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishOperators\n/-! # Four actual copy/reduce/cache stages of the fixed recovery source\nEach stage physically copies WIDTH, executes the existing canonical reducer,\nand physically transfers/drains its output. The finite kind below describes\nfixed existing source labels in proofs; it is not a runtime procedure argument.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishCache\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState\nopen SemiprimeD1StackRecoveryFinishPrimitives SemiprimeD1StackRecoveryFinishMoves\nopen SemiprimeD1StackRecoveryFinishProjection SemiprimeD1StackRecoveryFinishOperators SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\"=>Label.local\n/-- Four fixed existing reduction/cache sites, independent of all source words. -/\ninductive Kind where | quotient | odd | two | one deriving DecidableEq,Repr\n/-- Existing literal WIDTH-copy control site. -/\ndef widthSite:Kind → Control | .quotient=>.qWidth | .odd=>.aWidth | .two=>.twoWidth | .one=>.oneWidth\n/-- Existing literal reducer-call control site. -/\ndef reduceSite:Kind → Control | .quotient=>.qReduce | .odd=>.aReduce | .two=>.twoReduce | .one=>.oneReduce\n/-- Existing literal result-transfer control site. -/\ndef saveSite:Kind → Control | .quotient=>.saveQ | .odd=>.saveA | .two=>.saveTwo | .one=>.saveOne\n/-- Existing actual continuation after the physical result cache has been acquired. -/\ndef nextSite:Kind → Control | .quotient=>.oddInput | .odd=>.negativeWord | .two=>.one | .one=>.copyTodo\n/-- Existing literal consuming transfer site. -/\ndef transfer:Kind→MoveSite | .quotient=>.residue | .odd=>.inverseInput | .two=>.two | .one=>.one\n/-- Exact actual cached destination role. -/\ndef target (kind:Kind):Slot:=moveTo (transfer kind)\n/-- Exact canonical bits produced by the real WIDTH-sized reduction. -/\ndef word (v:Values):List Bool:=(SemiprimeD1JetScalarBits.reduce (v .width).length (v .reduceInput)).bits\n/-- Exact actual reducer invocation clock after WIDTH was physically copied. -/\ndef reducerTime (v:Values):Nat:=\n  SemiprimeD1StackReduceExecution.trimTime ((v .reduceInput).take (v .width).length).reverse+\n    SemiprimeD1StackReduceExecution.prefixTime (v .reduceInput) (v .width)+1\n/-- Complete actual copy/reduce/move stage clock, including every real call and return. -/\ndef time (v:Values):Nat:=(5*(v .width).length+4)+reducerTime v+(6*(word v).length+7)\n/-- Exact clean cache boundary after consuming the actual reducer input. -/\ndef cached (v:Values) (kind:Kind):Values:=\n  Function.update (Function.update v .reduceInput []) (target kind) (word v)\n/-- The SAME literal source executes each whole existing reduction/cache stage. -/\ntheorem cache_run (kind:Kind) (v:Values) (hs:v (.aux .copyScratch)=[])\n    (hw:v .reduceWidth=[]) (ho:v .output=[]) (ht:v (target kind)=[]):\n    Runs program (time v) (ctl (widthSite kind)) (data v) (ctl (nextSite kind)) (data (cached v kind)):=by\n  let v1:=Function.update v .reduceWidth (v .width)\n  let v2:=reduced v1 (word v)\n  have hc0:program (ctl (widthSite kind))=.call (.copy .width 0) (ctl (reduceSite kind)):=by cases kind <;> rfl\n  have h0:=copy_view .width (ctl (widthSite kind)) (ctl (reduceSite kind)) v hc0 hs\n  simp only [copyFrom,copyTo,hw,List.append_nil] at h0\n  change Runs program (5*(v .width).length+4) _ _ _ (data v1) at h0\n  have hc1:program (ctl (reduceSite kind))=.call (.reduce .take) (ctl (saveSite kind)):=by cases kind <;> rfl\n  have ho1:v1 .output=[]:=by simp [v1,ho]\n  have h1:=reduce_call (ctl (reduceSite kind)) (ctl (saveSite kind)) v1 hc1 ho1\n  have hword:reduceWord v1=word v:=by simp [reduceWord,word,v1]\n  have htime:reduceTime v1=reducerTime v:=by simp [reduceTime,reducerTime,v1]\n  rw [hword,htime] at h1\n  change Runs program (reducerTime v) _ _ _ (data v2) at h1\n  have hc2:program (ctl (saveSite kind))=.call (.move (transfer kind) false) (ctl (nextSite kind)):=by cases kind <;> rfl\n  have hs2:v2 (.aux .copyScratch)=[]:=by simp [v2,reduced,v1,hs]\n  have h2:=move_call (transfer kind) (ctl (saveSite kind)) (ctl (nextSite kind)) v2 hc2 hs2\n  have hf:moveFrom (transfer kind)=.output:=by cases kind <;> rfl\n  have hov:v2 .output=word v:=by simp [v2,reduced]\n  rw [hf,hov] at h2\n  have he:moved v2 (transfer kind)=cached v kind:=by\n    cases kind <;> dsimp only [target,transfer,moveTo] at ht <;> funext s <;> cases s with\n    | aux a=>cases a <;> simp [moved,v2,reduced,v1,cached,target,transfer,moveFrom,moveTo,ht]\n    | _=>simp [moved,v2,reduced,v1,cached,target,transfer,moveFrom,moveTo,hw,ho]\n  rw [he] at h2\n  exact join (join h0 h1) h2\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishCache\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishLoopBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishOperatorBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishNewtonOriginal\n/-! # Actual precision-marker loop has its own fixed quartic source clock\nIntrinsic real scalar-output widths are propagated through every physical stage.\nNo intermediate width premise remains in the original three-input endpoint.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishLoopBounds\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState\nnamespace B\nexport SemiprimeD1StackRecoveryFinishOperatorBounds\n  (Small sizedSlots small_update small_foreign small_multiply small_correction multiply_time correction_time linear_cube)\nend B\nnamespace N\nexport SemiprimeD1StackRecoveryFinishNewton (first second correction stepResult stepTime advance budget states)\nend N\nnamespace O\nexport SemiprimeD1StackRecoveryFinishNewtonOriginal\n  (prepared_width prepared_a prepared_negative prepared_two prepared_one)\nend O\nnamespace P\nexport SemiprimeD1StackRecoveryFinishPreparation (result)\nend P\nopen SemiprimeBitIndexClipping (SignedWord)\n/-- Each actual three-product/one-sum stage preserves all intrinsic scalar widths. -/\ntheorem small_step (v:Values) (p:Nat) (hv:B.Small v p):B.Small (N.stepResult v) p:=\n  B.small_multiply _ p (B.small_correction _ p\n    (B.small_multiply _ p (B.small_multiply v p hv .product) .opposite)) .update\n/-- Actual todo pop touches no scalar cache or precision WIDTH. -/\ntheorem small_popped (v:Values) (p:Nat) (hv:B.Small v p):\n    B.Small (Function.update v (.aux .todo) (v (.aux .todo)).tail) p:=\n  B.small_foreign v p hv (.aux .todo) (by decide) (by simp [B.sizedSlots]) _\n/-- Actual marker pop and complete physical stage preserve intrinsic scalar cache widths. -/\ntheorem small_advance (v:Values) (p:Nat) (hv:B.Small v p):B.Small (N.advance v) p:=small_step _ p (small_popped v p hv)\n/-- SAME complete actual Newton stage clock, including every copy, old-cache drain and real return. -/\ntheorem step_time (v:Values) (p:Nat) (hv:B.Small v p):N.stepTime v≤400000*(p+1)^3:=by\n  have h1:=B.small_multiply v p hv .product\n  have h2:=B.small_multiply (N.first v) p h1 .opposite\n  have h3:=B.small_correction (N.second v) p h2\n  have t0:=B.multiply_time v p hv .product\n  have t1:=B.multiply_time (N.first v) p h1 .opposite\n  have t2:=B.correction_time (N.second v) p h2\n  have t3:=B.multiply_time (N.correction v) p h3 .update\n  unfold N.stepTime\n  omega\n/-- Actual n-marker source clock is linear in actual visits, with the genuine final EOF test. -/\ntheorem budget_linear (n:Nat) (v:Values) (p:Nat) (hv:B.Small v p):\n    N.budget n v≤1+n*(400000*(p+1)^3+1):=by\n  induction n generalizing v with\n  | zero=>simp only [N.budget,Nat.zero_mul,Nat.add_zero,le_refl]\n  | succ n ih=>\n    have hs:=step_time (Function.update v (.aux .todo) (v (.aux .todo)).tail) p (small_popped v p hv)\n    have hr:=ih (N.advance v) (small_advance v p hv)\n    change 1+N.stepTime (Function.update v (.aux .todo) (v (.aux .todo)).tail)+N.budget n (N.advance v)≤_\n    rw [Nat.succ_mul]\n    omega\n/-- Actual P-marker loop has a fixed quartic own-source bound, with no native inverse report-clock equation. -/\ntheorem budget_quartic (v:Values) (p:Nat) (hv:B.Small v p):N.budget p v≤500000*(p+1)^4:=by\n  have h:=budget_linear p v p hv\n  have hp:=B.linear_cube p\n  calc\n    _≤(p+1)*(400000*(p+1)^3+1):=by nlinarith\n    _≤(p+1)*(500000*(p+1)^3):=by gcongr;omega\n    _=500000*(p+1)^4:=by ring\n/-- Actual acquired initial scalar caches satisfy all width caps intrinsically, including P0 and P1. -/\ntheorem prepared_small (n:SignedWord) (d:List Bool) (p:Nat):B.Small (P.result n d (List.replicate p true)) p:=by\n  constructor\n  · rw [O.prepared_width,List.length_replicate]\n  · intro s hs\n    simp only [B.sizedSlots,List.mem_cons,List.not_mem_nil,or_false] at hs\n    rcases hs with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n    · rw [O.prepared_a,List.length_replicate]\n      exact SemiprimeD1JetScalarBits.reduce_length _ _\n    · rw [O.prepared_negative,List.length_replicate]\n    · rw [O.prepared_two,List.length_replicate]\n      exact SemiprimeD1JetScalarBits.reduce_length _ _\n    · rw [O.prepared_one,List.length_replicate]\n      exact SemiprimeD1JetScalarBits.reduce_length _ _\n    · exact Nat.zero_le p\n    · exact Nat.zero_le p\n    · exact Nat.zero_le p\n    · exact Nat.zero_le p\n    · change (SemiprimeD1JetScalarBits.reduce (List.replicate p true).length\n        (SemiprimeD1StackRecoveryFinishWords.corrected n.negative d n.magnitude)).bits.length≤p\n      simpa only [List.length_replicate] using SemiprimeD1JetScalarBits.reduce_length p\n        (SemiprimeD1StackRecoveryFinishWords.corrected n.negative d n.magnitude)\n    · exact Nat.zero_le p\n/-- Actual loop beginning with ONLY source-acquired scalar caches has the fixed quartic own-source clock. -/\ntheorem original_loop (n:SignedWord) (d:List Bool) (p:Nat):\n    N.budget p (P.result n d (List.replicate p true))≤500000*(p+1)^4:=budget_quartic _ p (prepared_small n d p)\n/-- Every scalar cache after any number of actual stages retains the original precision-byte bound. -/\ntheorem states_small (n:Nat) (v:Values) (p:Nat) (hv:B.Small v p):B.Small (N.states n v) p:=by\n  induction n generalizing v with\n  | zero=>exact hv\n  | succ n ih=>exact ih (N.advance v) (small_advance v p hv)\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishLoopBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishState\n/-! # Actual copy, pop, push, drain and nested-return traces\nEvery preservation/restoration loop and every actual return symbol is charged.\nOnly finite literal roles/sites appear in instructions; live-bank functions\nbelow describe physical words in proofs and are never accepted by the program.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishPrimitives\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState SemiprimeD1StackProcedureTrace\n/-- Exact composition of actual traces for this one fixed recovery source. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after):\n    Runs program (m+n) pc before next after:=runs_trans program m n pc mid next before between after h g\n/-- Literal proof-side live source slot for each consuming transfer. -/\ndef moveFrom:MoveSite→Slot\n  | .plain|.roundingInput=>.aux .numeratorWork\n  | .rounded|.correction=>.addOutput\n  | _=>.output\n/-- Literal proof-side live destination for each consuming transfer. -/\ndef moveTo:MoveSite→Slot\n  | .plain|.rounded=>.reduceInput | .roundingInput=>.addLeft | .residue=>.aux .numeratorResidue\n  | .inverseInput=>.aux .inverseInput | .two=>.aux .two | .one|.update=>.aux .current\n  | .product=>.aux .product | .opposite=>.aux .opposite | .signed=>.aux .signedResidue | .correction=>.aux .correction\n/-- Actual cached left multiplier operand slot. -/\ndef multiplyFromLeft:MulSite→Slot\n  | .product=>.aux .inverseInput | .opposite|.signed=>.aux .negative\n  | .update=>.aux .current | .final=>.aux .signedResidue\n/-- Actual cached right multiplier operand slot. -/\ndef multiplyFromRight:MulSite→Slot\n  | .product|.final=>.aux .current | .opposite=>.aux .product | .update=>.aux .correction | .signed=>.aux .numeratorResidue\n/-- Literal proof-side source slot of each actual preserving copy. -/\ndef copyFrom:Copy→Slot\n  | .numerator=>.aux .numerator | .denominator=>.aux .denominator | .width|.negative|.todo=>.width\n  | .odd=>.aux .denominatorWork | .addLeft=>.aux .two | .addRight=>.aux .opposite | .positive=>.aux .numeratorResidue\n  | .mulLeft site=>multiplyFromLeft site | .mulRight site=>multiplyFromRight site | .move site=>moveFrom site\n/-- Literal proof-side target slot of each actual preserving copy. -/\ndef copyTo:Copy→Slot\n  | .numerator=>.aux .numeratorWork | .denominator=>.aux .denominatorWork | .width=>.reduceWidth\n  | .negative=>.aux .negative | .todo=>.aux .todo | .odd=>.reduceInput | .addLeft=>.addLeft | .addRight=>.addRight\n  | .positive=>.aux .signedResidue | .mulLeft _=>.mulLeft | .mulRight _=>.mulRight | .move site=>moveTo site\n/-- Actual copy source is its named physical live address. -/\ntheorem copy_source (site:Copy):copyStack site 0=address (copyFrom site):=by\n  cases site with\n  | mulLeft site=>cases site <;> rfl\n  | mulRight site=>cases site <;> rfl\n  | move site=>cases site <;> rfl\n  | _=>rfl\n/-- Actual copy destination is its named physical live address. -/\ntheorem copy_target (site:Copy):copyStack site 1=address (copyTo site):=by\n  cases site with\n  | move site=>cases site <;> rfl\n  | _=>rfl\n/-- Every real copy's source and destination are separate. -/\ntheorem copy_ne (site:Copy):address (copyFrom site)≠address (copyTo site):=by\n  rw [←copy_source,←copy_target]\n  exact fun h=>(by decide:(0:Fin 3)≠1) ((copy_injective site) h)\n/-- Real restoring-copy scratch is separate from every actual destination. -/\ntheorem copy_work_ne (site:Copy):aux .copyScratch≠address (copyTo site):=by\n  rw [←copy_target]\n  change copyStack site 2≠copyStack site 1\n  exact fun h=>(by decide:(2:Fin 3)≠1) ((copy_injective site) h)\n/-- Every real preserving copy pays its physical call, cells and return. -/\ntheorem copy_view (site:Copy) (pc next:Label) (v:Values)\n    (hc:program pc=.call (.copy site 0) next) (hs:v (.aux .copyScratch)=[]):\n    Runs program (5*(v (copyFrom site)).length+4) pc (data v) next\n      (data (Function.update v (copyTo site) (v (copyFrom site)++v (copyTo site)))):=by\n  rw [data_update]\n  apply included_call program (copyStack site) (Label.copy site) (copy_injective site)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hc (5*(v (copyFrom site)).length+3)\n    (SemiprimeD1StackCopy.state 0 none (v (copyFrom site)) (v (copyTo site)) [])\n    (SemiprimeD1StackCopy.done (v (copyFrom site)) (v (copyFrom site)++v (copyTo site))) _ _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words _ _ none)\n  · constructor\n    · intro k;fin_cases k\n      · change data v (copyStack site 0)=v (copyFrom site)\n        rw [copy_source,data_get]\n      · change data v (copyStack site 1)=v (copyTo site)\n        rw [copy_target,data_get]\n      · change data v (address (.aux .copyScratch))=[]\n        rw [data_get,hs]\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update (data v) (address (copyTo site)) _ (copyStack site 0)=v (copyFrom site)\n        rw [copy_source,Function.update_of_ne (copy_ne site),data_get]\n      · change Function.update (data v) (address (copyTo site)) _ (copyStack site 1)=_\n        rw [copy_target,Function.update_self]\n        rfl\n      · change Function.update (data v) (address (copyTo site)) _ (aux .copyScratch)=[]\n        rw [Function.update_of_ne (copy_work_ne site)]\n        exact (data_get v (.aux .copyScratch)).trans hs\n    · intro k hk\n      exact Function.update_of_ne (fun he=>hk 1 (by rw [copy_target];exact he.symm)) _ _\n/-- One physical push writes exactly one actual Boolean cell. -/\ntheorem push_view (pc next:Label) (s:Slot) (b:Bool) (v:Values)\n    (hc:program pc=.base (.push (address s) b next)):\n    Runs program 1 pc (data v) next (data (Function.update v s (b::v s))):=by\n  rw [data_update]\n  exact one_base program _ _ _ _ _ hc rfl (by rw [←data_get v s];rfl)\n/-- One physical pop branches solely on the actual leading cell and exposes the actual tail. -/\ntheorem pop_view (pc empty low high:Label) (s:Slot) (v:Values) (word:List Bool)\n    (hc:program pc=.base (.pop (address s) empty low high)) (hx:v s=word):\n    Runs program 1 pc (data v) (SemiprimeD1StackBytecode.choose empty low high word.head?)\n      (data (Function.update v s word.tail)):=by\n  rw [data_update]\n  apply one_base program _ _ _ _ _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,data_get,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,data_get,hx]\n/-- Every drain bit, including its final EOF test, is actually executed. -/\ntheorem drain_view (pc next:Label) (s:Slot) (v:Values)\n    (hc:program pc=.base (.pop (address s) next pc pc)):\n    Runs program ((v s).length+1) pc (data v) next (data (Function.update v s [])):=by\n  generalize hw:v s=word\n  induction word generalizing v with\n  | nil=>simpa only [hw,List.length_nil,Nat.zero_add,List.head?_nil,List.tail_nil,SemiprimeD1StackBytecode.choose]\n      using pop_view pc next pc pc s v [] hc hw\n  | cons b word ih=>\n    have h0:=pop_view pc next pc pc s v (b::word) hc hw\n    have h1:=ih (Function.update v s word) (Function.update_self _ _ _)\n    have h:=join (by cases b <;> exact h0) h1\n    simpa only [hw,Function.update_idem,List.length_cons,Nat.add_comm,Nat.add_left_comm,Nat.add_assoc] using h\n/-- A real nested call pushes and later pops its finite return symbol; no saved frame is supplied. -/\ntheorem returning_call (pc entry next:Label) (before after:Stack→List Bool) (time:Nat)\n    (hc:program pc=.call entry next)\n    (hr:Runs program time entry before (.local .returning) after):\n    Runs program (time+2) pc before next after:=by\n  intro frames target h\n  rcases h with ⟨hp,hd,hf⟩\n  let mid:=SemiprimeD1StackCalls.execute (.call entry next) target\n  have hm:SemiprimeD1StackCalls.run program 1 target=some mid:=by\n    change SemiprimeD1StackCalls.step program target=some mid\n    simp only [SemiprimeD1StackCalls.step,hp,Option.map_some,hc,mid]\n  obtain ⟨finish,hRun,hAt⟩:=hr (next::frames) mid (by\n    simp only [At,mid,SemiprimeD1StackCalls.execute,hd,hf,and_self])\n  let last:=SemiprimeD1StackCalls.execute .ret finish\n  have hl:SemiprimeD1StackCalls.run program 1 finish=some last:=by\n    change SemiprimeD1StackCalls.step program finish=some last\n    simp only [SemiprimeD1StackCalls.step,hAt.1,Option.map_some,program,last]\n  refine ⟨last,?_,?_,?_,?_⟩\n  · rw [show time+2=1+(time+1) by omega,SemiprimeD1StackReturnLink.run_add,hm,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hRun,Option.bind_some]\n    exact hl\n  · simp only [last,SemiprimeD1StackCalls.execute,hAt.2.2]\n  · simpa only [last,SemiprimeD1StackCalls.execute,hAt.2.2] using hAt.2.1\n  · simp only [last,SemiprimeD1StackCalls.execute,hAt.2.2]\n/-- A real drain subcall charges both its true call/return and every consumed cell. -/\ntheorem drain_call (pc next:Label) (s:Slot) (v:Values)\n    (hc:program pc=.call (.drain (address s)) next):\n    Runs program ((v s).length+3) pc (data v) next (data (Function.update v s [])):=by\n  have h:=drain_view (.drain (address s)) (.local .returning) s v rfl\n  exact returning_call pc (.drain (address s)) next _ _ _ hc h\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishPrimitives\n","RiemannGaussian.SemiprimeD1StackRecoveryGridCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridPrimitives\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridView\n/-! # Actual geometry, height/product and normalized twice-fitted operation calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridCalls\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\nopen SemiprimeD1StackProcedureTrace\nnamespace PTrace\nexport SemiprimeD1StackRecoveryGridPrimitives (join copy_call push_run pop_run peek_run drain_loop frame_call local_call)\nend PTrace\n/-- Whole actual R36 source runs on the four physically copied operands and actual retained W, preserving every68 external word. -/\ntheorem rational_call (site:Site) (w:Words) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd width:List Bool)\n    (hi:w.rational=SemiprimeD1StackRationalOperation.input (sx::xn) xd (sy::yn) yd width) :\n    Runs program (SemiprimeD1StackRationalOperationExecution.runBound (operation site) sx xn xd sy yn yd width+1)\n      (.operation site .call) (bank w) (.operation site .clearSigned)\n      (bank {w with rational:=SemiprimeD1StackRationalOperationExecution.result (operation site) sx xn xd sy yn yd width}):=by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program rationalStack Label.rational rational_injective R.program\n    (SemiprimeD1StackRationalOperation.localLabel .start (operation site) false false) (fun _=>rfl)\n    (.operation site .call) (.operation site .clearSigned) rfl _\n    (SemiprimeD1StackRationalOperation.initial (operation site) (sx::xn) xd (sy::yn) yd width)\n    (SemiprimeD1StackRationalOperationExecution.done (operation site) sx xn xd sy yn yd width) _ _ rfl rfl rfl rfl\n    (SemiprimeD1StackRationalOperationExecution.source_run (operation site) sx xn xd sy yn yd width)\n  · constructor\n    · intro k;exact congrFun hi k\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\n/-- Exact acquired geometry outputs overwrite only their actual included fields; both displaced shadows remain untouched. -/\ndef geometryResult (w:Words) (a q:List Bool) :Words:=\n  {w with rational:=Function.update w.rational (SemiprimeD1StackRationalOperation.adderStack .output) (SemiprimeD1StackPhaseGeometryComponents.result a q (SemiprimeD1StackPhaseGeometry.subStack .output)),geometry:=fun k=>if k=.exponent ∨ k=.index then w.geometry k else SemiprimeD1StackPhaseGeometryComponents.result a q (.inr k)}\n/-- Actual true geometry acquisition, independent of all fitted rational registers and W. -/\ntheorem geometry_call (w:Words) (a q:List Bool) (pc next:Label)\n    (hc:program pc=.call (.geometry .start) next)\n    (hi:∀k,bank w (geometryStack k)=SemiprimeD1StackPhaseGeometry.input a q k) :\n    ∃t ≤ SemiprimeD1StackPhaseGeometryComponents.runBound a q+1,\n      Runs program t pc (bank w) next (bank (geometryResult w a q)):=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackPhaseGeometryExecution.source_run a q\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program geometryStack Label.geometry geometry_injective G.program\n    .start (fun _=>rfl) pc next hc t (SemiprimeD1StackPhaseGeometry.initial a q)\n    (SemiprimeD1StackPhaseGeometryExecution.done a q) _ _ rfl rfl rfl rfl hr\n  · exact ⟨hi,fun _ _=>rfl⟩\n  · constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact hi (.inl .left)\n        · exact hi (.inl .right)\n        · exact hi (.inl .scratch)\n        · rfl\n      · cases k\n        · exact hi (.inr .exponent)\n        · exact hi (.inr .index)\n        · rfl\n        · rfl\n        · rfl\n        · rfl\n        · rfl\n        · rfl\n        · rfl\n        · rfl\n    · intro k hk;rcases k with k|k\n      · have hn:k≠SemiprimeD1StackRationalOperation.adderStack .output:=by\n          intro he\n          exact (hk (.inl .output) (congrArg rationalStack he.symm)).elim\n        change Function.update w.rational (SemiprimeD1StackRationalOperation.adderStack .output)\n          (SemiprimeD1StackPhaseGeometryComponents.result a q (SemiprimeD1StackPhaseGeometry.subStack .output)) k=w.rational k\n        exact Function.update_of_ne hn _ _\n      · rcases k with k|k\n        · cases k\n          · rfl\n          · rfl\n          · exact (hk (.inr .counter) rfl).elim\n          · exact (hk (.inr .center) rfl).elim\n          · exact (hk (.inr .alpha) rfl).elim\n          · exact (hk (.inr .sign) rfl).elim\n          · exact (hk (.inr .zero) rfl).elim\n          · exact (hk (.inr .order) rfl).elim\n          · exact (hk (.inr .scan) rfl).elim\n          · exact (hk (.inr .scratch) rfl).elim\n        · rfl\n/-- Actual unary division of the physically built 3M+u−1 numerator by physically copied u. -/\ntheorem division_call (w:Words) (n d:Nat) (hi:w.division=SemiprimeD1StackUnaryDivmod.contents\n    (List.replicate n true) (List.replicate d true) [] [] [] []) :\n    ∃t ≤100*(n+d+1)+1,Runs program t (.local .divide) (bank w) (.local .clearRemainder)\n      (bank {w with division:=SemiprimeD1StackUnaryDivmod.contents [] (List.replicate d true) [] [] (List.replicate (n/d) true) (List.replicate (n%d) true)}):=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackUnaryDivmodBytecode.divide_run n d\n  refine ⟨t+1,by omega,?_⟩\n  apply included_call program divisionStack Label.division division_injective D.code D.entry (fun _=>rfl)\n    (.local .divide) (.local .clearRemainder) rfl t\n    ⟨some D.entry,none,SemiprimeD1StackUnaryDivmod.contents (List.replicate n true) (List.replicate d true) [] [] [] []⟩\n    ⟨none,none,SemiprimeD1StackUnaryDivmod.contents [] (List.replicate d true) [] [] (List.replicate (n/d) true) (List.replicate (n%d) true)⟩\n    _ _ rfl rfl hr\n  · constructor\n    · intro k;exact congrFun hi k\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · exact (hk k rfl).elim\n          · rfl\n/-- Actual unary multiplicity product h*(u−order), after paid copies and physical truncated subtraction. -/\ntheorem product_call (w:Words) (h levels:Nat) (hi:w.product=SemiprimeD1StackUnaryProduct.contents\n    (List.replicate h true) (List.replicate levels true) [] []) :\n    ∃t ≤5*(h*(2*levels+3)+1)+1,Runs program t (.local .multiplicity) (bank w) (.local .clearLevels)\n      (bank {w with product:=SemiprimeD1StackUnaryProduct.contents [] (List.replicate levels true) [] (List.replicate (h*levels) true)}):=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackUnaryProduct.product_run h levels\n  refine ⟨t+1,by omega,?_⟩\n  apply included_call program productStack Label.product product_injective P.code P.entry (fun _=>rfl)\n    (.local .multiplicity) (.local .clearLevels) rfl t\n    ⟨some P.entry,none,SemiprimeD1StackUnaryProduct.contents (List.replicate h true) (List.replicate levels true) [] []⟩\n    ⟨none,none,SemiprimeD1StackUnaryProduct.contents [] (List.replicate levels true) [] (List.replicate (h*levels) true)⟩\n    _ _ rfl rfl hr\n  · constructor\n    · intro k;exact congrFun hi k\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · rfl\n          · rcases k with k|k\n            · exact (hk k rfl).elim\n            · rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryGridCalls\n","RiemannGaussian.SemiprimeD1StackRecoveryGridFrontClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridFrontBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridEnvelope\n/-! # Fixed whole frontend polynomial, charging actual grid-size VALUE acquisition -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridFrontClock\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\nnamespace F\nexport SemiprimeD1StackRecoveryGridFront (result clean centered decremented runBound)\nend F\nnamespace R\nexport SemiprimeD1StackRecoveryGridResource (resource cacheWidth dataWidth resource_pos a_le cache_le width_cache cache_data counts_data)\nend R\nnamespace Caps\nexport SemiprimeD1StackRecoveryGridWordCaps (mass_le power_width put_registers put_data)\nend Caps\n/-- The same honest five-word source pays all metadata acquisition, physical drains, both full powers and real returns. -/\ntheorem front_le (a M u:Nat) (t width:List Bool) :\n    F.runBound a M u t width≤10^54*(R.resource a M u t width)^8:=by\n  let r:=R.resource a M u t width\n  let B:=R.cacheWidth a width\n  let L:=R.dataWidth a M u t width\n  have hR:1≤r:=R.resource_pos a M u t width\n  have ha:a≤r:=R.a_le a M u t width\n  have hBL:B≤L:=R.cache_data a M u t width\n  have hWB:width.length+2≤B:=R.width_cache a width\n  have hB:B≤2*r:=R.cache_le a M u t width\n  have hL:L=10^9*r^3:=rfl\n  have hcount:=R.counts_data a M u t width\n  have hc:a+1≤L:=by omega\n  have hn:SemiprimeD1RecoveryGridBits.twoWord.numerator.magnitude.length≤B:=by change 2≤B;dsimp [B,R.cacheWidth];omega\n  have hd:SemiprimeD1RecoveryGridBits.twoWord.denominator.length≤B:=by change 1≤B;dsimp [B,R.cacheWidth];omega\n  obtain ⟨hr0,hd0⟩:=SemiprimeD1StackRecoveryGridFrontBounds.clean_caps a M u t width\n  have hp0:=SemiprimeD1StackRecoveryGridPowerBounds.source_le .center (F.clean a M u t width) width\n    SemiprimeD1RecoveryGridBits.twoWord a B L hWB hBL hn hd hc hr0 hd0\n  have hx:=Caps.power_width width SemiprimeD1RecoveryGridBits.twoWord a B hWB\n  have hr1:=Caps.put_registers (F.clean a M u t width) .center _ B hr0 hx.1 hx.2\n  have hd1:=Caps.put_data (F.clean a M u t width) .center _ L hd0 (hx.1.trans hBL) (hx.2.trans hBL)\n  have hp1:=SemiprimeD1StackRecoveryGridPowerBounds.source_le .alpha (F.centered a M u t width) width\n    SemiprimeD1RecoveryGridBits.twoWord a B L hWB hBL hn hd hc hr1 hd1\n  have he:=SemiprimeD1StackRecoveryGridEnvelope.power_le r B L a hR hB (by rw [hL]) (by omega)\n  change _≤SemiprimeD1StackRecoveryGridStageBounds.powerCap a B L at hp0 hp1\n  have hp0':_≤10^53*r^7:=hp0.trans he\n  have hp1':_≤10^53*r^7:=hp1.trans he\n  have hmass:=Caps.mass_le (F.decremented a M u t width) L (SemiprimeD1StackRecoveryGridFrontBounds.decremented_data a M u t width)\n  have hacq:=SemiprimeD1StackRecoveryGridFrontBounds.acquisition_le a M u t width\n  have hdec:=SemiprimeD1StackRecoveryGridFrontBounds.decrement_le a M u t width\n  change _≤10000*r^2 at hacq\n  change _≤300*r at hdec\n  have h28:r^2≤r^8:=Nat.pow_le_pow_right hR (by decide:2≤8)\n  have h38:r^3≤r^8:=Nat.pow_le_pow_right hR (by decide:3≤8)\n  have h78:r^7≤r^8:=Nat.pow_le_pow_right hR (by decide:7≤8)\n  have h18:r≤r^8:=Nat.le_pow (by decide:0<8)\n  have h08:1≤r^8:=Nat.one_le_pow 8 _ hR\n  rw [hL] at hmass\n  unfold F.runBound\n  change _≤10^54*r^8\n  norm_num1 at hp0' hp1' ⊢\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryGridFrontClock\n","RiemannGaussian.SemiprimeD1StackRecoveryGridGrowth":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridCalls\n/-! # Paid physical grid-size doubling and index-template growth -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridGrowth\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView SemiprimeD1StackRecoveryGridCalls\nopen SemiprimeD1StackProcedureTrace\n/-- Only four actual mutable growth buffers; every other original/cache word is retained. -/\ndef buffers (w:Words) (scan todo work index:List Bool) :Words:=\n  {w with auxiliary:=fun k=>match k with\n    | .scan=>scan | .todo=>todo | .doubleWork=>work | .indexTemplate=>index | _=>w.auxiliary k}\n/-- A real write of scan changes exactly its actual growth buffer. -/\ntheorem update_scan (w:Words) (scan todo work index xs:List Bool) :\n    Function.update (bank (buffers w scan todo work index)) (aux .scan) xs=\n      bank (buffers w xs todo work index):=by\n  funext p\n  rcases p with p|p\n  · rfl\n  · rcases p with p|p\n    · rfl\n    · rcases p with p|p\n      · rfl\n      · rcases p with p|p\n        · rfl\n        · rcases p with p|p\n          · rfl\n          · cases p <;> simp [bank,buffers,aux]\n/-- A real write of todo changes exactly its actual growth buffer. -/\ntheorem update_todo (w:Words) (scan todo work index xs:List Bool) :\n    Function.update (bank (buffers w scan todo work index)) (aux .todo) xs=\n      bank (buffers w scan xs work index):=by\n  funext p\n  rcases p with p|p\n  · rfl\n  · rcases p with p|p\n    · rfl\n    · rcases p with p|p\n      · rfl\n      · rcases p with p|p\n        · rfl\n        · rcases p with p|p\n          · rfl\n          · cases p <;> simp [bank,buffers,aux]\n/-- A real write of doubleWork changes exactly its actual growth buffer. -/\ntheorem update_doubleWork (w:Words) (scan todo work index xs:List Bool) :\n    Function.update (bank (buffers w scan todo work index)) (aux .doubleWork) xs=\n      bank (buffers w scan todo xs index):=by\n  funext p\n  rcases p with p|p\n  · rfl\n  · rcases p with p|p\n    · rfl\n    · rcases p with p|p\n      · rfl\n      · rcases p with p|p\n        · rfl\n        · rcases p with p|p\n          · rfl\n          · cases p <;> simp [bank,buffers,aux]\n/-- A real write of indexTemplate changes exactly its actual growth buffer. -/\ntheorem update_indexTemplate (w:Words) (scan todo work index xs:List Bool) :\n    Function.update (bank (buffers w scan todo work index)) (aux .indexTemplate) xs=\n      bank (buffers w scan todo work xs):=by\n  funext p\n  rcases p with p|p\n  · rfl\n  · rcases p with p|p\n    · rfl\n    · rcases p with p|p\n      · rfl\n      · rcases p with p|p\n        · rfl\n        · rcases p with p|p\n          · rfl\n          · cases p <;> simp [bank,buffers,aux]\n/-- Actual TRUE cells are consumed individually and two actual TRUE cells are pushed for each. -/\ntheorem double_drain (w:Words) (scan index:List Bool) (n m:Nat) :\n    Runs program (3*n+1) (.local .doubleDrain)\n      (bank (buffers w scan (List.replicate n true) (List.replicate m true) index))\n      (.local .doubleRestore)\n      (bank (buffers w scan [] (List.replicate (m+2*n) true) index)):=by\n  induction n generalizing m with\n  | zero=>\n    have h:=PTrace.pop_run (.local .doubleDrain) (.local .doubleRestore) (.local .abort)\n      (.local .doubleFirst) (aux .todo) (bank (buffers w scan [] (List.replicate m true) index)) [] rfl rfl\n    rw [update_todo] at h\n    exact h\n  | succ n ih=>\n    have h0:=PTrace.pop_run (.local .doubleDrain) (.local .doubleRestore) (.local .abort)\n      (.local .doubleFirst) (aux .todo)\n      (bank (buffers w scan (List.replicate (n+1) true) (List.replicate m true) index))\n      (true::List.replicate n true) rfl (by simp [bank,buffers,aux,List.replicate_succ])\n    rw [update_todo] at h0\n    change Runs program 1 _ _ (.local .doubleFirst) _ at h0\n    have h1:=PTrace.push_run (.local .doubleFirst) (.local .doubleSecond) (aux .doubleWork) true\n      (bank (buffers w scan (List.replicate n true) (List.replicate m true) index)) rfl\n    change Runs program 1 _ _ _ (Function.update _ (aux .doubleWork) (true::List.replicate m true)) at h1\n    rw [update_doubleWork] at h1\n    rw [←List.replicate_succ] at h1\n    have h2:=PTrace.push_run (.local .doubleSecond) (.local .doubleDrain) (aux .doubleWork) true\n      (bank (buffers w scan (List.replicate n true) (List.replicate (m+1) true) index)) rfl\n    change Runs program 1 _ _ _ (Function.update _ (aux .doubleWork) (true::List.replicate (m+1) true)) at h2\n    rw [update_doubleWork,←List.replicate_succ] at h2\n    have h3:=ih (m+1+1)\n    have h:=PTrace.join (PTrace.join (PTrace.join h0 h1) h2) h3\n    simpa only [show 1+1+1+(3*n+1)=3*(n+1)+1 by omega,\n      show m+1+1+2*n=m+2*(n+1) by omega] using h\n/-- The real reverse-style restore consumes each work marker and pushes it onto todo. -/\ntheorem double_restore (w:Words) (scan index:List Bool) (n m:Nat) :\n    Runs program (2*n+1) (.local .doubleRestore)\n      (bank (buffers w scan (List.replicate m true) (List.replicate n true) index))\n      (.local .grow)\n      (bank (buffers w scan (List.replicate (m+n) true) [] index)):=by\n  induction n generalizing m with\n  | zero=>\n    have h:=PTrace.pop_run (.local .doubleRestore) (.local .grow) (.local .abort)\n      (.local .doubleSave) (aux .doubleWork) (bank (buffers w scan (List.replicate m true) [] index)) [] rfl rfl\n    rw [update_doubleWork] at h\n    exact h\n  | succ n ih=>\n    have h0:=PTrace.pop_run (.local .doubleRestore) (.local .grow) (.local .abort)\n      (.local .doubleSave) (aux .doubleWork)\n      (bank (buffers w scan (List.replicate m true) (List.replicate (n+1) true) index))\n      (true::List.replicate n true) rfl (by simp [bank,buffers,aux,List.replicate_succ])\n    rw [update_doubleWork] at h0\n    change Runs program 1 _ _ (.local .doubleSave) _ at h0\n    have h1:=PTrace.push_run (.local .doubleSave) (.local .doubleRestore) (aux .todo) true\n      (bank (buffers w scan (List.replicate m true) (List.replicate n true) index)) rfl\n    change Runs program 1 _ _ _ (Function.update _ (aux .todo) (true::List.replicate m true)) at h1\n    rw [update_todo,←List.replicate_succ] at h1\n    have h2:=ih (m+1)\n    have h:=PTrace.join (PTrace.join h0 h1) h2\n    simpa only [show 1+1+(2*n+1)=2*(n+1)+1 by omega,\n      show m+1+n=m+(n+1) by omega] using h\n/-- One actual doubling pays both complete marker passes and preserves every source/cache word. -/\ntheorem double_run (w:Words) (scan index:List Bool) (n:Nat) :\n    Runs program (7*n+2) (.local .doubleDrain)\n      (bank (buffers w scan (List.replicate n true) [] index))\n      (.local .grow) (bank (buffers w scan (List.replicate (2*n) true) [] index)):=by\n  have h0:=double_drain w scan index n 0\n  have h1:=double_restore w scan index (2*n) 0\n  simp only [Nat.zero_add,List.replicate_zero] at h0 h1\n  have h:=PTrace.join h0 h1\n  simpa only [show 3*n+1+(2*(2*n)+1)=7*n+2 by omega] using h\n/-- Own exact instruction budget of the physically nested marker-doubling loop. -/\ndef growTime :Nat→Nat→Nat\n  | 0,_=>1\n  | steps+1,n=>7*n+4+growTime steps (2*n)\n/-- Actual original a markers drive the entire doubling loop; no numerical grid size is supplied. -/\ntheorem grow_run (w:Words) (steps n width:Nat) :\n    Runs program (growTime steps n) (.local .grow)\n      (bank (buffers w (List.replicate steps true) (List.replicate n true) [] (List.replicate width false)))\n      (.local .heightCheck)\n      (bank (buffers w [] (List.replicate (n*2^steps) true) [] (List.replicate (width+steps) false))):=by\n  induction steps generalizing n width with\n  | zero=>\n    have h:=PTrace.pop_run (.local .grow) (.local .heightCheck) (.local .abort) (.local .indexBit)\n      (aux .scan) (bank (buffers w [] (List.replicate n true) [] (List.replicate width false))) [] rfl rfl\n    rw [update_scan] at h\n    change Runs program 1 _ _ (.local .heightCheck) (bank (buffers w [] (List.replicate n true) [] (List.replicate width false))) at h\n    simpa only [growTime,pow_zero,Nat.mul_one,Nat.add_zero,List.replicate_zero] using h\n  | succ steps ih=>\n    have h0:=PTrace.pop_run (.local .grow) (.local .heightCheck) (.local .abort) (.local .indexBit)\n      (aux .scan)\n      (bank (buffers w (List.replicate (steps+1) true) (List.replicate n true) [] (List.replicate width false)))\n      (true::List.replicate steps true) rfl (by simp [bank,buffers,aux,List.replicate_succ])\n    rw [update_scan] at h0\n    change Runs program 1 _ _ (.local .indexBit) _ at h0\n    have h1:=PTrace.push_run (.local .indexBit) (.local .doubleDrain) (aux .indexTemplate) false\n      (bank (buffers w (List.replicate steps true) (List.replicate n true) [] (List.replicate width false))) rfl\n    change Runs program 1 _ _ _ (Function.update _ (aux .indexTemplate) (false::List.replicate width false)) at h1\n    rw [update_indexTemplate,←List.replicate_succ] at h1\n    have h2:=double_run w (List.replicate steps true) (List.replicate (width+1) false) n\n    have h3:=ih (2*n) (width+1)\n    have h:=PTrace.join (PTrace.join (PTrace.join h0 h1) h2) h3\n    have hn:(2*n)*2^steps=n*2^(steps+1):=by rw [pow_succ];ring\n    simpa only [growTime,hn,show width+1+steps=width+(steps+1) by omega,\n      show 1+1+(7*n+2)=7*n+4 by omega] using h\n/-- All emitted markers and all actual growing passes have a uniform VALUE bound. -/\ntheorem growTime_le (steps n:Nat) :growTime steps n≤20*(steps+1)*(n*2^steps+1):=by\n  induction steps generalizing n with\n  | zero=>simp only [growTime,pow_zero,Nat.mul_one];omega\n  | succ steps ih=>\n    have hi:=ih (2*n)\n    have hp:1≤2^steps:=Nat.one_le_pow steps 2 (by decide)\n    have hn:n≤n*2^steps:=by nlinarith\n    rw [growTime,pow_succ]\n    nlinarith\nend RiemannGaussian.SemiprimeD1StackRecoveryGridGrowth\n","RiemannGaussian.SemiprimeD1StackRecoveryGridRegisters":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridOperation\n/-! # Exact physical rational register/cache updates used by actual grid power and row loops -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridRegisters\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\n/-- Physical signed and unsigned destination fields are exactly the actual word's bytes. -/\ntheorem putReg_fields (w:Words) (r:Reg) (word:SemiprimeRationalBits.RationalWord) :\n    (putReg w r word).registers (r,false)=signed word ∧\n    (putReg w r word).registers (r,true)=word.denominator:=by\n  simp only [putReg,Function.update_apply,Prod.mk.injEq,eq_self,true_and,Bool.false_eq_true,\n    Bool.true_eq_false,ite_true,ite_false]\n/-- All other register words remain literally unchanged. -/\ntheorem putReg_other (w:Words) (r q:Reg) (word:SemiprimeRationalBits.RationalWord) (den:Bool) (hne:q≠r) :\n    (putReg w r word).registers (q,den)=w.registers (q,den):=by\n  simp only [putReg,Function.update_apply,Prod.mk.injEq,hne,false_and,ite_false]\n/-- Proof-side interpretation of the actual saved two-word cache recovers the precise rational bytes. -/\ntheorem getReg_putReg (w:Words) (r:Reg) (word:SemiprimeRationalBits.RationalWord) :getReg (putReg w r word) r=word:=by\n  unfold getReg\n  rw [(putReg_fields w r word).1,(putReg_fields w r word).2]\n  rfl\n/-- Replacing the same two actual register fields twice preserves only the latest actual word. -/\ntheorem putReg_idem (w:Words) (r:Reg) (old word:SemiprimeRationalBits.RationalWord) :\n    putReg (putReg w r old) r word=putReg w r word:=by\n  dsimp only [putReg]\n  congr 1\n  funext k\n  by_cases h0:k=(r,false)\n  · subst k;simp [signed]\n  · by_cases h1:k=(r,true)\n    · subst k;simp\n    · simp [h0,h1]\n/-- Cache writes preserve the actual acquired width and all rational arithmetic fields. -/\ntheorem putReg_rational (w:Words) (r:Reg) (word:SemiprimeRationalBits.RationalWord) :(putReg w r word).rational=w.rational:=rfl\n/-- Cache writes preserve every actual source/counter/copy/framing field. -/\ntheorem putReg_auxiliary (w:Words) (r:Reg) (word:SemiprimeRationalBits.RationalWord) :(putReg w r word).auxiliary=w.auxiliary:=rfl\n/-- A physical counter update commutes with rational-cache replacement because their literal roles are disjoint. -/\ntheorem putReg_aux_update (w:Words) (r:Reg) (word:SemiprimeRationalBits.RationalWord) (k:Aux) (bits:List Bool) :\n    {putReg w r word with auxiliary:=Function.update w.auxiliary k bits}=\n      putReg {w with auxiliary:=Function.update w.auxiliary k bits} r word:=rfl\n/-- Every fixed power's actual base survives initialization/replacement of its distinct accumulator register. -/\ntheorem power_base_ne_destination (part:PowerSite) :powerBase part≠powerDestination part:=by cases part <;> decide\n/-- The actual base signed/denominator words are unaffected by its power accumulator updates. -/\ntheorem power_base_retained (w:Words) (part:PowerSite) (word:SemiprimeRationalBits.RationalWord) (den:Bool) :\n    (putReg w (powerDestination part) word).registers (powerBase part,den)=w.registers (powerBase part,den):=\n  putReg_other w _ _ word den (power_base_ne_destination part)\nend RiemannGaussian.SemiprimeD1StackRecoveryGridRegisters\n","RiemannGaussian.SemiprimeD1StackRecoveryGridRowBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridModelBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridWorkBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridEnvelope\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridRow\n/-! # Whole actual row clock at the physical original-grid loop invariant -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridRowBounds\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\nnamespace Row\nexport SemiprimeD1StackRecoveryGridRow (geometry indexed order runBound)\nend Row\nnamespace Model\nexport SemiprimeD1StackRecoveryGridModel (view Payload)\nend Model\nnamespace R\nexport SemiprimeD1StackRecoveryGridResource (resource gridSize cacheWidth dataWidth resource_pos a_le M_le u_le t_le width_le grid_le index_le cache_le width_cache cache_data counts_data small_le_cubic height_le height_product_le)\nend R\nnamespace Caps\nexport SemiprimeD1StackRecoveryGridWordCaps (Registers Data put_registers put_data auxiliary_data)\nend Caps\nnamespace Payload\nexport SemiprimeD1StackRecoveryGridPayloadBounds (Bounded)\nend Payload\n/-- The actual acquired order markers never exceed the actual scanned geometry magnitude width. -/\ntheorem order_le (a:Nat) (q:List Bool) (hq:q.length≤a+2) :Row.order a q≤a+2:=by\n  have h:=SemiprimeD1StackPhaseGeometryArithmetic.valuation_le (SemiprimeD1StackPhaseGeometryArithmetic.magnitude a q)\n  rw [SemiprimeD1StackPhaseGeometryArithmetic.magnitude_length] at h\n  exact h.trans (by omega)\n/-- Actual row entry, true geometry and paid current-index copy retain semantic register/data caps. -/\ntheorem input_caps (a M u n v:Nat) (t q width:List Bool) (p:Model.Payload)\n    (hp:Payload.Bounded width p v (SemiprimeD1TaperedLoss.height M u*u))\n    (hv:v+(n+1)≤R.gridSize a) (hq:q.length≤a+2) :\n    Caps.Registers (Row.geometry (Model.view a M u (n+1) t q width p) a n q) (R.cacheWidth a width) ∧\n    Caps.Data (Row.geometry (Model.view a M u (n+1) t q width p) a n q) (R.dataWidth a M u t width) ∧\n    Caps.Registers (Row.indexed (Model.view a M u (n+1) t q width p) a n q) (R.cacheWidth a width) ∧\n    Caps.Data (Row.indexed (Model.view a M u (n+1) t q width p) a n q) (R.dataWidth a M u t width):=by\n  have hr:=SemiprimeD1StackRecoveryGridModelBounds.registers_le a M u (n+1) v t q width p hp\n  have hd:=SemiprimeD1StackRecoveryGridModelBounds.data_le a M u (n+1) v t q width p hp hv hq\n  have hR:=R.resource_pos a M u t width\n  have ha:=R.a_le a M u t width\n  have hqR:q.length≤R.resource a M u t width:=hq.trans (R.index_le a M u t width)\n  have hN:=R.grid_le a M u t width\n  have hL:=R.counts_data a M u t width\n  have hn:n≤R.dataWidth a M u t width:=by omega\n  have hd0:=Caps.auxiliary_data (Model.view a M u (n+1) t q width p) .todo (List.replicate n true) _ hd (by rwa [List.length_replicate])\n  have hg:20000*((List.replicate a true).length+q.length+1)≤R.dataWidth a M u t width:=by\n    rw [List.length_replicate]\n    apply R.small_le_cubic _ _ hR\n    omega\n  have hd1:=SemiprimeD1StackRecoveryGridStateCaps.geometry_data _ (List.replicate a true) q _ hd0 hg\n  have hr1:Caps.Registers (Row.geometry (Model.view a M u (n+1) t q width p) a n q) (R.cacheWidth a width):=hr\n  have hnB:q.length+1≤R.cacheWidth a width:=by unfold R.cacheWidth;omega\n  have hb:=R.cache_data a M u t width\n  refine ⟨hr1,hd1,?_,?_⟩\n  · apply Caps.put_registers _ .index _ _ hr1 hnB\n    change 1≤R.cacheWidth a width\n    unfold R.cacheWidth;omega\n  · apply Caps.put_data _ .index _ _ hd1 (hnB.trans hb)\n    change 1≤R.dataWidth a M u t width\n    omega\n/-- Whole actual row budget, including both skip paths and the complete unskipped body, is uniformly eighth degree in paid source bytes/VALUEs. -/\ntheorem row_le (a M u n v:Nat) (t q width:List Bool) (p:Model.Payload)\n    (hp:Payload.Bounded width p v (SemiprimeD1TaperedLoss.height M u*u))\n    (hv:v+(n+1)≤R.gridSize a) (hq:q.length≤a+2) :\n    Row.runBound (Model.view a M u (n+1) t q width p) width a (SemiprimeD1TaperedLoss.height M u) u n q t≤\n      10^55*(R.resource a M u t width)^8:=by\n  let r:=R.resource a M u t width\n  let B:=R.cacheWidth a width\n  let L:=R.dataWidth a M u t width\n  have hR:1≤r:=R.resource_pos a M u t width\n  have ha:a≤r:=R.a_le a M u t width\n  have hu:u≤r:=R.u_le a M u t width\n  have ht:t.length≤r:=R.t_le a M u t width\n  have hW:width.length≤r:=R.width_le a M u t width\n  have hqR:q.length≤r:=hq.trans (R.index_le a M u t width)\n  have hh:SemiprimeD1TaperedLoss.height M u≤3*r:=R.height_le a M u t width\n  have hmul:SemiprimeD1TaperedLoss.height M u*(u-Row.order a q)≤3*r:=\n    (Nat.mul_le_mul_left _ (Nat.sub_le u (Row.order a q))).trans (R.height_product_le a M u t width)\n  have ho:Row.order a q≤r:=(order_le a q hq).trans (R.index_le a M u t width)\n  have hB:B≤2*r:=R.cache_le a M u t width\n  have hL:L=10^9*r^3:=rfl\n  have hBL:B≤L:=R.cache_data a M u t width\n  have hWB:width.length+2≤B:=R.width_cache a width\n  have hcount:=R.counts_data a M u t width\n  obtain ⟨hr0,hd0,hr1,hd1⟩:=input_caps a M u n v t q width p hp hv hq\n  have hbytes:SemiprimeD1TaperedLoss.height M u*(u-Row.order a q)*(4*width.length+5)≤L:=\n    SemiprimeD1StackRecoveryGridEnvelope.frame_bytes_le r width.length _ hR hW hmul\n  have hw:=SemiprimeD1StackRecoveryGridWorkBounds.work_le\n    (Row.indexed (Model.view a M u (n+1) t q width p) a n q) width\n    (SemiprimeD1TaperedLoss.height M u) u (Row.order a q) B L hWB hBL hr1 hd1 (by omega) hbytes\n  have he:=SemiprimeD1StackRecoveryGridEnvelope.work_le r (SemiprimeD1TaperedLoss.height M u) u (Row.order a q)\n    width.length _ B L hR hh hu ho hW hmul hB hL\n  have hwork:=hw.trans he\n  have hcleanup:=SemiprimeD1StackRecoveryGridStageBounds.cleanup_le\n    (Row.geometry (Model.view a M u (n+1) t q width p) a n q) L hd0\n  have hcompare:=SemiprimeD1StackRecoveryGridCompare.runBound_le q t\n  have hmag:(SemiprimeD1StackPhaseGeometryArithmetic.magnitude a q).length≤r:=by\n    rw [SemiprimeD1StackPhaseGeometryArithmetic.magnitude_length]\n    have hi:=R.index_le a M u t width\n    omega\n  have hstart:SemiprimeD1StackRecoveryGridRowStart.runBound a q≤4000*r:=by\n    unfold SemiprimeD1StackRecoveryGridRowStart.runBound SemiprimeD1StackPhaseGeometryComponents.runBound\n    rw [List.length_replicate]\n    omega\n  have h38:r^3≤r^8:=Nat.pow_le_pow_right hR (by decide:3≤8)\n  have h18:r≤r^8:=Nat.le_pow (by decide:0<8)\n  have h08:1≤r^8:=Nat.one_le_pow 8 _ hR\n  unfold Row.runBound\n  change _≤10^55*r^8\n  rw [hL] at hcleanup\n  norm_num1 at hwork hcleanup ⊢\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryGridRowBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsEncoding\n/-! # Three real whole-source calls with exact direct-alias input lineage and actual returns -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsCalls\nopen SemiprimeD1StackRecoveryNodeInputs SemiprimeD1StackRecoveryNodeInputsInventory\nopen SemiprimeD1StackRecoveryNodeInputsEncoding SemiprimeD1StackProcedureTrace\nnamespace V\nexport SemiprimeD1StackRecoveryNodeInputsView (empty inverse_initial powers_initial)\nend V\n/-- ACTUAL affine source includes exactly one whole Grid call and acquires q/denominator internally. -/\ntheorem affine_call (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool)\n    (ht : SemiprimeBitArithmetic.bitValue t=selected.val) :\n    ∃s≤SemiprimeD1StackRecoveryAffineExecution.timeBound a M u selected t width+1,\n      Runs program s (ctl .start)\n        (input (List.replicate a true) (List.replicate M true) (List.replicate u true) t width)\n        (ctl .inverse) (afterAffine a M u selected t width) := by\n  obtain ⟨s,hs,hr⟩:=SemiprimeD1StackRecoveryAffineExecution.source_run a M u selected t width ht\n  refine ⟨s+1,Nat.add_le_add_right hs 1,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program affine affineLabel affine_injective A.program\n    (.local .start) (fun _=>rfl) (ctl .start) (ctl .inverse) rfl s\n    (A.initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width)\n    (SemiprimeD1StackRecoveryAffineEncoding.done a M u selected t width) _ _ rfl rfl rfl rfl hr\n  · exact ⟨fun _=>rfl,fun _ _=>rfl⟩\n  · constructor\n    · intro k;rfl\n    · intro k hk;rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\n/-- The ENTIRE real inverse uses actual acquired affine-array/q/W aliases, preserving ALL112 old words. -/\ntheorem inverse_call (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) :\n    ∃s≤SemiprimeD1StackNormalizedInverseBounds.polynomial (E.array a M u selected width) (E.retained a M u selected) width+1,\n      Runs program s (ctl .inverse) (afterAffine a M u selected t width)\n        (ctl .powers) (afterInverse a M u selected t width) := by\n  let den:=E.array a M u selected width\n  let q:=E.retained a M u selected\n  let before:=afterAffine a M u selected t width\n  have hin:=V.inverse_initial (E.result a M u selected t width)\n    (SemiprimeD1StackNormalizedInverse.tape den) (List.replicate q true) width\n    (rational_image a M u selected t width) (denominator_image a M u selected t width) (q_image a M u selected t width)\n  obtain ⟨s,hs,hr⟩:=SemiprimeD1StackNormalizedInverseBounds.source_run_bounded den q width\n  refine ⟨s+1,Nat.add_le_add_right hs 1,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program inverse inverseLabel inverse_injective I.program\n    (I.ctl .start) (fun _=>rfl) (ctl .inverse) (ctl .powers) rfl s\n    (I.initial (SemiprimeD1StackNormalizedInverse.tape den) (List.replicate q true) width)\n    (SemiprimeD1StackNormalizedInverseEncoding.done den q width) _ _ rfl rfl rfl rfl hr hin\n  have ho:=SemiprimeD1StackMultiplierLink.data_update inverse inverse_injective before\n    (I.input (SemiprimeD1StackNormalizedInverse.tape den) (List.replicate q true) width) before hin\n    (I.aux .output) (inverseTape a M u selected width)\n  exact ho\n/-- The real powers source reads the SAME retained Grid argument/q/W; no argument/grid/source replay occurs. -/\ntheorem powers_call (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) :\n    ∃s≤SemiprimeD1StackRecoveryPowersExecution.timeBound (argument a M u selected width) width (E.retained a M u selected)+1,\n      Runs program s (ctl .powers) (afterInverse a M u selected t width)\n        (ctl .done) (result a M u selected t width) := by\n  let arg:=argument a M u selected width\n  let q:=E.retained a M u selected\n  let before:=afterInverse a M u selected t width\n  have hin:=V.powers_initial (E.result a M u selected t width) (inverseTape a M u selected width)\n    (SemiprimeD1StackRecoveryPowersSpec.signed arg) arg.denominator (List.replicate q true) width\n    (rational_image a M u selected t width) (argument_signed a M u selected t width)\n    (argument_den a M u selected t width) (q_image a M u selected t width)\n  obtain ⟨s,hs,hr⟩:=SemiprimeD1StackRecoveryPowersExecution.source_run arg q width\n  refine ⟨s+1,Nat.add_le_add_right hs 1,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program powers powersLabel powers_injective P.program\n    (.local .start) (fun _=>rfl) (ctl .powers) (ctl .done) rfl s\n    (P.initial (SemiprimeD1StackRecoveryPowersSpec.signed arg) arg.denominator (List.replicate q true) width)\n    (SemiprimeD1StackRecoveryPowersEncoding.done arg q width) _ _ rfl rfl rfl rfl hr hin\n  have ho:=SemiprimeD1StackMultiplierLink.data_update powers powers_injective before\n    (P.input (SemiprimeD1StackRecoveryPowersSpec.signed arg) arg.denominator (List.replicate q true) width) before hin\n    (P.aux .output) (powerTape a M u selected width)\n  exact ho\nend RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsCalls\n","RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsReadyCall":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsEncoding\nimport RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsAffineReady\n/-! # Real same-program ready call from an ACTUAL acquired Grid bank without Grid replay -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsReadyCall\nopen SemiprimeD1StackRecoveryNodeInputs SemiprimeD1StackRecoveryNodeInputsInventory\nopen SemiprimeD1StackRecoveryNodeInputsEncoding SemiprimeD1StackProcedureTrace\n/-- Actual Grid-cache ready entry executes actual q/affine work and its real return, with no supplied q/array answer. -/\ntheorem ready_call (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool)\n    (ht : SemiprimeBitArithmetic.bitValue t=selected.val) :\n    ∃s≤SemiprimeD1StackRecoveryNodeInputsAffineReady.timeBound a M u selected t width+1,\n      Runs program s (ctl .readyGrid) (gridReady a M u selected t width).data\n        (ctl .inverse) (afterAffine a M u selected t width) := by\n  obtain ⟨s,hs,hr⟩:=SemiprimeD1StackRecoveryNodeInputsAffineReady.source_run a M u selected t width ht\n  refine ⟨s+1,Nat.add_le_add_right hs 1,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program affine affineLabel affine_injective A.program\n    (.local .ready) (fun _=>rfl) (ctl .readyGrid) (ctl .inverse) rfl s\n    (SemiprimeD1StackRecoveryNodeInputsAffineReady.initial a M u selected t width)\n    (SemiprimeD1StackRecoveryAffineEncoding.done a M u selected t width) _ _ rfl rfl rfl rfl hr\n  · exact ⟨fun _=>rfl,fun _ _=>rfl⟩\n  · constructor\n    · intro k;rfl\n    · intro k hk;rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsReadyCall\n","RiemannGaussian.SemiprimeD1StackRecoveryWeightsWidths":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsExecution\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseWidths\n/-! # Physical input and fitted coefficient widths, independent of validity and elapsed time -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWeightsWidths\nopen SemiprimeD1StackRecoveryWeights SemiprimeD1StackRecoveryWeightsView\nopen SemiprimeRationalBits (RationalWord zeroWord)\nnamespace B\nexport SemiprimeD1StackNormalizedInverseWidths (bytes execute_bytes row_bytes read_bytes tape_bytes zero_bytes)\nend B\nnamespace Spec\nexport SemiprimeD1StackRecoveryWeightsSpec (combine dotLoop weight array)\nend Spec\n/-- All six actual original words, including q unary markers and every paid W byte. -/\ndef inputSize (inverse powers:List RationalWord) (scalar:RationalWord) (q:Nat) (width:List Bool):Nat:=\n  (SemiprimeD1StackNormalizedInverse.tape inverse).length+(SemiprimeD1StackNormalizedInverse.tape powers).length+B.bytes scalar+q+width.length+1\n/-- Every physical input is paid; no dimension or numerical value is hidden in this size. -/\ntheorem input_caps (inverse powers:List RationalWord) (scalar:RationalWord) (q:Nat) (width:List Bool):\n    1 ≤ inputSize inverse powers scalar q width ∧\n    (SemiprimeD1StackNormalizedInverse.tape inverse).length ≤ inputSize inverse powers scalar q width ∧\n    (SemiprimeD1StackNormalizedInverse.tape powers).length ≤ inputSize inverse powers scalar q width ∧\n    B.bytes scalar ≤ inputSize inverse powers scalar q width ∧ q ≤ inputSize inverse powers scalar q width ∧ width.length ≤ inputSize inverse powers scalar q width:=by\n  unfold inputSize\n  omega\n/-- Each sum successor is physically twice-fitted, regardless of zero denominators or W0. -/\ntheorem combine_bytes (width:List Bool) (inverse powers:List RationalWord) (j k:Nat) (acc:RationalWord):\n    B.bytes (Spec.combine width inverse powers j k acc)=2*width.length+1:=B.execute_bytes .add _ _ width\n/-- Every actual accumulated suffix is fitted or its literal ZERO seed; elapsed steps are irrelevant. -/\ntheorem dot_bytes (width:List Bool) (inverse powers:List RationalWord) (j n:Nat) (acc:RationalWord)\n    (hacc:B.bytes acc ≤ 2*width.length+2):B.bytes (Spec.dotLoop width inverse powers j n acc) ≤ 2*width.length+2:=by\n  induction n generalizing acc with\n  | zero=>exact hacc\n  | succ n ih=>exact ih _ (by rw [combine_bytes];omega)\n/-- The final scalar product has exactly both fitted fields and its sign, even at W0. -/\ntheorem weight_bytes (width:List Bool) (q j:Nat) (scalar:RationalWord) (inverse powers:List RationalWord):\n    B.bytes (Spec.weight width q j scalar inverse powers)=2*width.length+1:=B.execute_bytes .mul _ _ width\n/-- Every chronological output coefficient has the actual fitted cap, without a Valid/Fits premise. -/\ntheorem array_bytes (width:List Bool) (q:Nat) (scalar:RationalWord) (inverse powers:List RationalWord):\n    ∀word∈Spec.array width q scalar inverse powers,B.bytes word=2*width.length+1:=by\n  intro word hw\n  obtain ⟨j,_,rfl⟩:=List.mem_map.mp hw\n  exact weight_bytes width q j scalar inverse powers\n/-- Entire physical output is paid by q and W VALUES, not by their logarithms. -/\ntheorem array_tape_bytes (width:List Bool) (q:Nat) (scalar:RationalWord) (inverse powers:List RationalWord):\n    (SemiprimeD1StackNormalizedInverse.tape (Spec.array width q scalar inverse powers)).length ≤ q*(4*width.length+5)+1:=by\n  have h:=B.tape_bytes (Spec.array width q scalar inverse powers) (2*width.length+1)\n    (by intro word hw;exact (array_bytes width q scalar inverse powers word hw).le)\n  simpa only [Spec.array,List.length_map,List.length_range,show 2*(2*width.length+1)+3=4*width.length+5 by omega] using h\n/-- The finite loop's arbitrary reached suffix pays its entire physical output tail. -/\ntheorem rows_bytes (inverse powers:List RationalWord) (scalar:RationalWord) (q:Nat) (width:List Bool) (r:Nat) (out:List Bool):\n    (SemiprimeD1StackRecoveryWeightsOuter.rows inverse powers scalar q width r out).length=r*(4*width.length+5)+out.length:=by\n  induction r generalizing out with\n  | zero=>simp only [SemiprimeD1StackRecoveryWeightsOuter.rows,List.range_zero,List.map_nil,List.foldr_nil,Nat.zero_mul,Nat.zero_add]\n  | succ r ih=>\n    rw [SemiprimeD1StackRecoveryWeightsOuter.rows_succ,ih,B.row_bytes,weight_bytes,Nat.add_mul]\n    omega\nend RiemannGaussian.SemiprimeD1StackRecoveryWeightsWidths\n","RiemannGaussian.SemiprimeD1StackReturnLink":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCalls\nimport RiemannGaussian.SemiprimeD1StackRename\nimport RiemannGaussian.SemiprimeD1StackHeapAllocate\n\n/-! # Actual procedure-return linking of literal stack programs\nA fixed main pushes its literal continuation, enters the included program,\nand returns through an actual return-stack pop. A component halt is replaced\nby return, never by a free semantic submachine operation.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 700000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackReturnLink\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run)\nend B\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\n\n/-- Literal component instruction; component halt becomes actual return. -/\ndef instruction {K L:Type} : B.Instruction K L→C.Instruction K (L⊕Bool)\n  | .halt => .ret\n  | .push k bit next => .base (.push k bit (.inl next))\n  | .pop k empty low high => .base (.pop k (.inl empty) (.inl low) (.inl high))\n  | .peek k empty low high => .base (.peek k (.inl empty) (.inl low) (.inl high))\n  | .jump next => .base (.jump (.inl next))\n\n/-- One fixed linked code with two static caller labels. -/\ndef code {K L:Type} (entry:L) (component:L→B.Instruction K L) :\n    L⊕Bool→C.Instruction K (L⊕Bool)\n  | .inl label => instruction (component label)\n  | .inr false => .call (.inl entry) (.inr true)\n  | .inr true => .base .halt\n\n/-- Ignore finite read flags but preserve exact data, labels and actual return stack. -/\ndef Rel {K L:Type} (s:B.State K L) (t:C.State K (L⊕Bool)) : Prop :=\n  t.data=s.store ∧ match s.pc with\n    | none => t.pc=some (.inr true) ∧ t.frames=[]\n    | some label => t.pc=some (.inl label) ∧ t.frames=[.inr true]\n\n/-- The actual linked instruction preserves the exact payload/return correspondence. -/\ntheorem instruction_rel {K L:Type} [DecidableEq K] (op:B.Instruction K L)\n    (s:B.State K L) (t:C.State K (L⊕Bool)) (label:L)\n    (hp:s.pc=some label) (h:Rel s t) :\n    Rel (B.execute op s) (C.execute (instruction op) t) := by\n  rcases h with ⟨hd,ht⟩\n  simp only [hp] at ht\n  rcases ht with ⟨ht,hf⟩\n  cases op <;> simp [Rel,instruction,B.execute,C.execute,hd,hf,\n    SemiprimeD1StackRename.choose_inl]\n\n/-- Actual source and linked program run composition. -/\ntheorem run_add {K L:Type} [DecidableEq K] (program:L→C.Instruction K L)\n    (m n:ℕ) (s:C.State K L) :\n    C.run program (m+n) s=(C.run program m s).bind (C.run program n) := by\n  unfold C.run\n  rw [Nat.add_comm m n,Function.iterate_add_apply]\n  generalize (fun state=>state.bind (C.step program))^[m] (some s)=o\n  cases o with\n  | some s => rfl\n  | none => exact Function.iterate_fixed rfl n\n\n/-- Every successful component trace executes as literal linked instructions. -/\ntheorem run_rel {K L:Type} [DecidableEq K] (entry:L) (component:L→B.Instruction K L)\n    (fuel:ℕ) (s out:B.State K L) (t:C.State K (L⊕Bool))\n    (h:Rel s t) (hr:B.run component fuel s=some out) :\n    ∃finish,C.run (code entry component) fuel t=some finish ∧ Rel out finish := by\n  induction fuel generalizing s t with\n  | zero => change some s=some out at hr;cases hr;exact ⟨t,rfl,h⟩\n  | succ fuel ih =>\n    rw [show fuel+1=1+fuel by omega,SemiprimeD1StackCopy.run_add] at hr\n    change (B.step component s).bind (B.run component fuel)=some out at hr\n    cases hp:s.pc with\n    | none => simp [B.step,SemiprimeD1StackBytecode.step,hp] at hr\n    | some label =>\n      have hs:B.step component s=some (B.execute (component label) s):=by\n        simp [B.step,SemiprimeD1StackBytecode.step,hp]\n      rw [hs,Option.bind_some] at hr\n      have htpc:t.pc=some (.inl label):=by\n        have hh:=h.2\n        rw [hp] at hh\n        exact hh.1\n      have ht:C.step (code entry component) t=some (C.execute (instruction (component label)) t):=by\n        simp [C.step,SemiprimeD1StackCalls.step,htpc,code]\n      obtain ⟨finish,hfinish,hrel⟩:=ih (B.execute (component label) s)\n        (C.execute (instruction (component label)) t) (instruction_rel _ _ _ label hp h) hr\n      refine ⟨finish,?_,hrel⟩\n      rw [show fuel+1=1+fuel by omega,run_add]\n      change (C.step (code entry component) t).bind (C.run (code entry component) fuel)=some finish\n      rw [ht,Option.bind_some,hfinish]\n\n/-- Actual caller state; no preloaded return frame is assumed. -/\ndef initial {K L:Type} (store:K→List Bool) : C.State K (L⊕Bool) :=\n  ⟨some (.inr false),none,none,store,[]⟩\n\n/-- Actual caller halt with all return frames consumed. -/\ndef final {K L:Type} (store:K→List Bool) : C.State K (L⊕Bool) :=\n  ⟨none,none,none,store,[]⟩\n\n/-- Call push, included execution, real return pop and caller halt are all executed. -/\ntheorem linked_run {K L:Type} [DecidableEq K] (entry:L) (component:L→B.Instruction K L)\n    (time:ℕ) (input output:K→List Bool)\n    (h:B.run component time ⟨some entry,none,input⟩=some ⟨none,none,output⟩) :\n    C.run (code entry component) (time+2) (initial input)=some (final output) := by\n  have hstart:C.run (code entry component) 1 (initial input)=\n      some (⟨some (.inl entry),none,none,input,[.inr true]⟩:C.State K (L⊕Bool)):=rfl\n  have hrel:Rel (⟨some entry,none,input⟩:B.State K L)\n      (⟨some (.inl entry),none,none,input,[.inr true]⟩:C.State K (L⊕Bool)):=⟨rfl,rfl,rfl⟩\n  obtain ⟨finish,hfinish,hrel⟩:=run_rel entry component time _ _ _ hrel h\n  have hdata:finish.data=output:=hrel.1\n  have hpc:finish.pc=some (.inr true):=hrel.2.1\n  have hframes:finish.frames=[]:=hrel.2.2\n  have hend:C.run (code entry component) 1 finish=some (final output):=by\n    simp [C.run,SemiprimeD1StackCalls.run,C.step,SemiprimeD1StackCalls.step,\n      C.execute,SemiprimeD1StackCalls.execute,code,hpc,final,hdata,hframes]\n  rw [show time+2=1+(time+1) by omega,run_add,hstart,Option.bind_some,run_add,hfinish,Option.bind_some,hend]\n\n/-- Genuine larger finite-machine certificate with both linking transitions paid. -/\ndef linkedInTime {K L:Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (entry:L) (component:L→B.Instruction K L) (inputStack outputStack:K)\n    (time:ℕ) (input output:K→List Bool)\n    (h:B.run component time ⟨some entry,none,input⟩=some ⟨none,none,output⟩) :\n    StateTransition.EvalsToInTime\n      (SemiprimeD1StackCalls.machine inputStack outputStack (.inr false) (code entry component)).step\n      (SemiprimeD1StackCalls.configuration (initial input))\n      (some (SemiprimeD1StackCalls.configuration (final output))) (time+2) := by\n  apply SemiprimeD1StackCalls.evalsCorrect inputStack outputStack (.inr false) (code entry component)\n  exact ⟨⟨time+2,linked_run entry component time input output h⟩,le_refl _⟩\n/-- Each actual linked instruction increases each data stack by at most one cell. -/\ntheorem execute_data_bound {K L:Type} [DecidableEq K] (op:C.Instruction K L)\n    (s:C.State K L) (cap:ℕ) (h:∀k,(s.data k).length ≤ cap) :\n    ∀k,((C.execute op s).data k).length ≤ cap+1 := by\n  cases op with\n  | base op =>\n    have hb:=SemiprimeD1StackCopy.execute_bound op (⟨none,s.flag,s.data⟩:B.State K L) cap h\n    cases op <;> exact hb\n  | call callee continuation => exact fun k=>(h k).trans (Nat.le_succ cap)\n  | ret =>\n    cases hf:s.frames <;> intro k <;> simpa [C.execute,SemiprimeD1StackCalls.execute,hf] using (h k).trans (Nat.le_succ cap)\n\n/-- Actual call/return prefixes bound Boolean payload, independently of debug reports. -/\ntheorem run_data_bound {K L:Type} [DecidableEq K] (program:L→C.Instruction K L)\n    (fuel cap:ℕ) (s out:C.State K L) (h:∀k,(s.data k).length ≤ cap)\n    (hr:C.run program fuel s=some out) : ∀k,(out.data k).length ≤ cap+fuel := by\n  induction fuel generalizing s out cap with\n  | zero => change some s=some out at hr;cases hr;exact h\n  | succ fuel ih =>\n    rw [show fuel+1=1+fuel by omega,run_add] at hr\n    change (C.step program s).bind (C.run program fuel)=some out at hr\n    cases hp:s.pc with\n    | none => simp [C.step,SemiprimeD1StackCalls.step,hp] at hr\n    | some label =>\n      have he:C.step program s=some (C.execute (program label) s):=by simp [C.step,SemiprimeD1StackCalls.step,hp]\n      rw [he,Option.bind_some] at hr\n      have hb:=ih (cap+1) (C.execute (program label) s) out (execute_data_bound _ _ _ h) hr\n      simpa only [Nat.add_assoc,Nat.add_comm 1 fuel] using hb\n\n/-- Concrete fixed caller and actual allocator, with no input-dependent code labels. -/\ndef allocatorMachine : Turing.FinTM2 :=\n  SemiprimeD1StackCalls.machine (0:Fin 6) 4 (.inr false)\n    (code (0:Fin 22) SemiprimeD1StackHeapAllocate.code)\n\n/-- Concrete allocator call executes its own return push/pop and final caller halt. -/\ndef allocateInTime (record heap counter:List Bool) :\n    StateTransition.EvalsToInTime allocatorMachine.step\n      (SemiprimeD1StackCalls.configuration\n        (initial (L:=Fin 22) (SemiprimeD1StackHeapAllocate.payload record heap [] counter [] [])))\n      (some (SemiprimeD1StackCalls.configuration\n        (final (L:=Fin 22) (SemiprimeD1StackHeapAllocate.payload record\n          (SemiprimeSourceHistogramKeyBits.frame record heap) [] (true::counter) counter []))))\n      (5*counter.length+6*record.length+9) := by\n  have h:=linkedInTime (0:Fin 22) SemiprimeD1StackHeapAllocate.code (0:Fin 6) 4\n    (5*counter.length+6*record.length+7)\n    (SemiprimeD1StackHeapAllocate.payload record heap [] counter [] [])\n    (SemiprimeD1StackHeapAllocate.payload record (SemiprimeSourceHistogramKeyBits.frame record heap)\n      [] (true::counter) counter [])\n    (SemiprimeD1StackHeapAllocate.allocate_run record heap counter none)\n  exact h\n\n/-- Concrete linked allocator source prefixes include every Boolean and return-frame cell. -/\ntheorem allocator_prefix_cells (record heap counter:List Bool) (fuel:ℕ)\n    (out:C.State (Fin 6) (Fin 22⊕Bool))\n    (hr:C.run (code (0:Fin 22) SemiprimeD1StackHeapAllocate.code) fuel\n      (initial (SemiprimeD1StackHeapAllocate.payload record heap [] counter [] []))=some out) :\n    (out.data 0).length+(out.data 1).length+(out.data 2).length+\n      (out.data 3).length+(out.data 4).length+(out.data 5).length+out.frames.length ≤\n      7*(record.length+heap.length+counter.length+fuel) := by\n  have h:=run_data_bound (code (0:Fin 22) SemiprimeD1StackHeapAllocate.code) fuel\n    (record.length+heap.length+counter.length) _ out (by\n      intro k\n      fin_cases k <;> simp [initial,SemiprimeD1StackHeapAllocate.payload] <;> omega) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound _ fuel _ out hr\n  change out.frames.length ≤ 0+fuel at hf\n  have h0:=h 0\n  have h1:=h 1\n  have h2:=h 2\n  have h3:=h 3\n  have h4:=h 4\n  have h5:=h 5\n  omega\n/-- The complete linked allocator has a proved bound at every actual target-machine prefix. -/\ntheorem allocator_machine_prefix_cells (record heap counter:List Bool) (fuel:ℕ)\n    (cfg:allocatorMachine.Cfg)\n    (hr:(fun cfg=>cfg.bind allocatorMachine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (initial (L:=Fin 22) (SemiprimeD1StackHeapAllocate.payload record heap [] counter [] []))))=some cfg) :\n    (cfg.stk (some (0:Fin 6))).length+(cfg.stk (some (1:Fin 6))).length+\n      (cfg.stk (some (2:Fin 6))).length+(cfg.stk (some (3:Fin 6))).length+\n      (cfg.stk (some (4:Fin 6))).length+(cfg.stk (some (5:Fin 6))).length+(cfg.stk none).length ≤\n      7*(record.length+heap.length+counter.length+fuel) := by\n  let start:C.State (Fin 6) (Fin 22⊕Bool):=\n    initial (SemiprimeD1StackHeapAllocate.payload record heap [] counter [] [])\n  let program:=code (0:Fin 22) SemiprimeD1StackHeapAllocate.code\n  have he:=SemiprimeD1StackCalls.run_correct (0:Fin 6) 4 (.inr false) program fuel start\n  change (C.run program fuel start).map SemiprimeD1StackCalls.configuration=\n    (fun cfg=>cfg.bind allocatorMachine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration start)) at he\n  cases hc:C.run program fuel start with\n  | none => rw [hc,hr] at he;cases he\n  | some out =>\n    rw [hc,hr] at he\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj he\n    rw [←hcfg]\n    exact allocator_prefix_cells record heap counter fuel out hc\nend RiemannGaussian.SemiprimeD1StackReturnLink\n","RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsPrimitives\n/-! # Real pointer parser, cached Fresh source, heap allocation and ordinal-log calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsCalls\nopen SemiprimeD1StackRootPhaseFreshRecords SemiprimeD1StackRootPhaseFreshRecordsEncoding\nopen SemiprimeD1StackRootPhaseFreshRecordsPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- One actual framed UNARY issued reference is consumed, copied and validated physically. -/\ntheorem parse_call (bank:Stack→List Bool) (word tail:List Bool)\n    (hi:bank (aux .reader)=frame word tail) (ho:bank (aux .pointer)=[])\n    (hs:bank (aux .fieldScratch)=[]) (hv:bank (aux .valid)=[]) :\n    Runs program (8*word.length+7) .parse bank .check\n      (Function.update (Function.update (Function.update bank (aux .reader) tail) (aux .pointer) word) (aux .valid) [true]) :=by\n  let before:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let after:SemiprimeD1StackBytecode.State Field.Stack Field.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel fieldStack bank before.store bank:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k <;> simp [fieldStack,before,SemiprimeD1TensorTapeFieldBytecode.initial,\n          SemiprimeD1TensorTapeFieldMachine.contents,hi,ho,hs]\n      · cases k;exact hv\n    · intro k _;rfl\n  apply included_call program fieldStack Label.field field_injective Field.code\n    (Field.active .tagPop (none,false)) (fun _=>rfl) .parse .check rfl (8*word.length+6)\n    before after _ _ rfl rfl (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin\n  have h0:=Link.data_update fieldStack field_injective bank before.store bank hin (.inl .input) tail\n  have h1:=Link.data_update fieldStack field_injective bank _ _ h0 (.inl .output) word\n  have h2:=Link.data_update fieldStack field_injective bank _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update before.store (.inl .input) tail)\n      (.inl .output) word) (.inr ()) [true]=after.store:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  simpa only [he,fieldStack] using h2\n/-- One REAL restore→Fresh call starts only from actual allocator/header bytes.\nThe logical bank list/index identify producer bytes in proofs, not runtime operands. -/\ntheorem fresh_call (root:R.Stack→List Bool) (work:Aux→List Bool)\n    (banks:List (SemiprimeD1StackPhaseWorkingPrecision.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t:List Bool)\n    (hbank:banks[i.val]=SemiprimeD1StackPhaseCacheFreshComponents.phase a u edges t [false,true]) :\n    ∃q ≤ SemiprimeD1StackPhaseCacheFreshExecution.runBound banks i a u edges t [false,true] [],\n      Runs program (q+1) .freshCall\n        (view root (SemiprimeD1StackPhaseCacheFreshExecution.source banks i []).data work)\n        (.serialize 0)\n        (view root (SemiprimeD1StackPhaseCacheFreshExecution.done banks i a u edges t [false,true] []).data work) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackPhaseCacheFreshExecution.source_run banks i a u edges t [false,true] []\n    (by intro x hx;cases hx) hbank\n  refine ⟨q,hq,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program cacheStack Label.cache cache_injective\n    Q.program (.inl .start) (fun _=>rfl) .freshCall (.serialize 0) rfl q\n    (SemiprimeD1StackPhaseCacheFreshExecution.source banks i [])\n    (SemiprimeD1StackPhaseCacheFreshExecution.done banks i a u edges t [false,true] []) _ _ rfl rfl rfl rfl hr\n  · exact view_rel _ _ _ _\n  · exact view_rel _ _ _ _\n/-- Actual allocation physically copies the old counter to the stable reference,\nincrements the real counter and writes every byte of the complete fresh85 record. -/\ntheorem allocate_call (bank:Stack→List Bool) (hs:bank (aux .recordScratch)=[])\n    (hr:bank (aux .reference)=[]) (ht:bank (aux .counterScratch)=[]) :\n    Runs program (5*(bank (aux .counter)).length+6*(bank (aux .record)).length+8) .allocate bank .logReference\n      (Function.update (Function.update (Function.update bank (aux .heap)\n        (frame (bank (aux .record)) (bank (aux .heap)))) (aux .counter) (true::bank (aux .counter)))\n        (aux .reference) (bank (aux .counter))) :=by\n  let before:=SemiprimeD1StackHeapAllocate.state 0 none (bank (aux .record)) (bank (aux .heap)) [] (bank (aux .counter)) [] []\n  let after:=SemiprimeD1StackHeapAllocate.done (bank (aux .record))\n    (frame (bank (aux .record)) (bank (aux .heap))) (true::bank (aux .counter)) (bank (aux .counter))\n  have hin:Link.DataRel heapStack bank before.store bank:=by\n    constructor\n    · intro k;fin_cases k\n      · rfl\n      · rfl\n      · exact hs\n      · rfl\n      · exact hr\n      · exact ht\n    · intro k _;rfl\n  apply included_call program heapStack Label.allocator heap_injective SemiprimeD1StackHeapAllocate.code\n    0 (fun _=>rfl) .allocate .logReference rfl\n    (5*(bank (aux .counter)).length+6*(bank (aux .record)).length+7) before after _ _ rfl rfl\n    (SemiprimeD1StackHeapAllocate.allocate_run _ _ _ none) hin\n  have h0:=Link.data_update heapStack heap_injective bank before.store bank hin 1\n    (frame (bank (aux .record)) (bank (aux .heap)))\n  have h1:=Link.data_update heapStack heap_injective bank _ _ h0 3 (true::bank (aux .counter))\n  have h2:=Link.data_update heapStack heap_injective bank _ _ h1 4 (bank (aux .counter))\n  have he:Function.update (Function.update (Function.update before.store 1\n      (frame (bank (aux .record)) (bank (aux .heap)))) 3 (true::bank (aux .counter))) 4\n      (bank (aux .counter))=after.store:=by funext k;fin_cases k <;> rfl\n  simpa only [he,show heapStack 1=aux .heap from rfl,show heapStack 3=aux .counter from rfl,show heapStack 4=aux .reference from rfl] using h2\n/-- The reference logger executes the literal restoring body; the ordinal itself\nwas acquired from the real counter, not supplied as a native append result. -/\ntheorem reference_call (bank:Stack→List Bool) (hs:bank (aux .refScratch)=[]) :\n    ∃q≤6*(2*(bank (aux .reference)).length+3),\n      Runs program (q+1) .logReference bank (.clear 0)\n        (Function.update bank (aux .refsHistory)\n          ((true::frame (bank (aux .reference)) []).reverse++bank (aux .refsHistory))) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackAssignmentBody.body_run (bank (aux .reference)) (bank (aux .refsHistory))\n  refine ⟨q,hq,?_⟩\n  let before:SemiprimeD1StackBytecode.State Body.Stack Body.Label:=\n    ⟨some Body.entry,none,SemiprimeD1StackAssignmentBody.contents (bank (aux .reference)) [] (bank (aux .refsHistory))⟩\n  let after:SemiprimeD1StackBytecode.State Body.Stack Body.Label:=\n    ⟨none,none,SemiprimeD1StackAssignmentBody.contents (bank (aux .reference)) []\n      ((true::frame (bank (aux .reference)) []).reverse++bank (aux .refsHistory))⟩\n  have hin:Link.DataRel bodyStack bank before.store bank:=by\n    constructor\n    · intro k;cases k\n      · rfl\n      · exact hs\n      · rfl\n    · intro k _;rfl\n  apply included_call program bodyStack Label.body body_injective Body.code Body.entry (fun _=>rfl)\n    .logReference (.clear 0) rfl q before after _ _ rfl rfl hr hin\n  have hh:=Link.data_update bodyStack body_injective bank before.store bank hin .history\n    ((true::frame (bank (aux .reference)) []).reverse++bank (aux .refsHistory))\n  have he:Function.update before.store .history\n      ((true::frame (bank (aux .reference)) []).reverse++bank (aux .refsHistory))=after.store:=by\n    funext k;cases k <;> rfl\n  simpa only [he,bodyStack] using hh\nend RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsCalls\n","RiemannGaussian.SemiprimeD1StackRootPhaseGridBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseGridExecution\n/-! # Own polynomial phase-grid clock and all126 physical/return-cell prefixes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseGridBounds\nopen SemiprimeD1StackRootPhaseGrid SemiprimeD1StackRootPhaseGridEncoding\nopen SemiprimeD1StackRootPhaseGridExecution\nopen SemiprimeBitArithmetic (bitValue)\n/-- Exact acquired logarithm in original canonical input width; proof-side only. -/\ntheorem lambda_eq (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    SemiprimeD1StackRootRecursiveControlEncoding.lambdaValue bits=Nat.clog 2 (2^20*bits.length+2) :=by\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  simp only [SemiprimeD1StackRootRecursiveControlEncoding.lambdaValue,\n    SemiprimeD1StackRootScheduleOriginal.originalLambda,SemiprimeD1PublicPackingReady.scale,←hw]\n/-- The actually acquired original parent exponent has the fixed logarithmic envelope. -/\ntheorem exponent_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    exponentValue bits≤4*Nat.clog 2 (2^20*bits.length+2) :=by\n  have h:=SemiprimeD1Schedule.exponent_le_lam\n    (SemiprimeD1StackRootRecursiveControlEncoding.lambdaValue bits) 0\n  simpa only [exponentValue,lambda_eq bits hc] using h\n/-- The usual ceiling-log bound is proved arithmetically, with no clock or operand oracle. -/\ntheorem pow_clog_le (x:Nat) (hx:1<x) : 2^(Nat.clog 2 x)≤2*x :=by\n  have hp:=Nat.pow_pred_clog_lt_self (by decide : 1<2) hx\n  have hl:=Nat.clog_pos (by decide : 1<2) hx\n  rw [Nat.pred_eq_sub_one] at hp\n  have he:Nat.clog 2 x=(Nat.clog 2 x-1)+1:=by omega\n  calc\n    _=2^((Nat.clog 2 x-1)+1):=congrArg (fun n:Nat=>2^n) he\n    _=2^(Nat.clog 2 x-1)*2:=pow_succ _ _\n    _≤_:=by omega\n/-- Fixed numerical envelopes for actual binary width and phase count. The\nexponential is only in logarithmic metadata; original N is never unary. -/\ntheorem numeric_bounds (ell a:Nat) (ha:a≤4*Nat.clog 2 (2^20*ell+2)) :\n    a+2≤10^8*(ell+1) ∧ 2^(a+1)≤10^30*(ell+1)^4 :=by\n  let x:Nat:=2^20*ell+2\n  have hx:1<x:=by dsimp [x];omega\n  have hs:x≤10^7*(ell+1):=by dsimp [x];omega\n  have hl:Nat.clog 2 x≤x:=Nat.clog_le_of_le_pow x.lt_two_pow_self.le\n  have hp:=pow_clog_le x hx\n  change a≤4*Nat.clog 2 x at ha\n  refine ⟨by omega,?_⟩\n  calc\n    2^(a+1)≤2^(4*Nat.clog 2 x+1):=Nat.pow_le_pow_right (by decide) (by omega)\n    _=2*(2^(Nat.clog 2 x))^4:=by\n      rw [show 4*Nat.clog 2 x+1=Nat.clog 2 x*4+1 by omega,pow_add,pow_mul,pow_one]\n      omega\n    _≤2*(2*x)^4:=Nat.mul_le_mul_left 2 (Nat.pow_le_pow_left hp 4)\n    _=32*x^4:=by ring\n    _≤32*(10^7*(ell+1))^4:=Nat.mul_le_mul_left 32 (Nat.pow_le_pow_left hs 4)\n    _=32*(10^7)^4*(ell+1)^4:=by ring\n    _≤10^30*(ell+1)^4:=Nat.mul_le_mul_right _ (by norm_num)\n/-- The entire real copy/fill/enum work is bounded by one fixed degree-five polynomial. -/\ntheorem preparedBound_le (ell a:Nat) (ha:a≤4*Nat.clog 2 (2^20*ell+2)) :\n    preparedBound a≤10^42*(ell+1)^5 :=by\n  obtain ⟨hw,hp⟩:=numeric_bounds ell a ha\n  have hm:=Nat.mul_le_mul (Nat.mul_le_mul_left 100 hw) hp\n  have he:100*(10^8*(ell+1))*(10^30*(ell+1)^4)=10^40*(ell+1)^5:=by ring\n  rw [he] at hm\n  have h1:1≤(ell+1)^5:=one_le_pow₀ (by omega)\n  have h5:ell+1≤(ell+1)^5:=by\n    simpa only [pow_one] using Nat.pow_le_pow_right (by omega : 1≤ell+1) (by decide : 1≤5)\n  unfold preparedBound\n  nlinarith\n/-- One actual original-input bit-clock pays the entire root call and conditional catalogue. -/\ntheorem runBound_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    runBound bits≤10^60*(bits.length+1)^10 :=by\n  have hr:=SemiprimeD1StackRootRecursiveControlBounds.runBound_le bits hc hN\n  have he:=preparedBound_le bits.length (exponentValue bits) (exponent_le bits hc)\n  have h5:(bits.length+1)^5≤(bits.length+1)^10:=Nat.pow_le_pow_right (by omega) (by decide)\n  have hp:=he.trans (Nat.mul_le_mul_left (10^42) h5)\n  have h1:1≤(bits.length+1)^10:=one_le_pow₀ (by omega)\n  unfold runBound\n  omega\n/-- Complete same-program trace under that fixed degree-ten original-input clock. -/\ntheorem source_run_polynomial (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t≤10^60*(bits.length+1)^10,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) :=by\n  obtain ⟨t,ht,hr⟩:=source_run bits hc hN\n  exact ⟨t,ht.trans (runBound_le bits hc hN),hr⟩\n/-- Actual retained source initialization has exactly one supplied N word. -/\ntheorem root_input (bits:List Bool) (k:R.Stack) : R.input bits k=(if k=R.originalInput then bits else []) :=by\n  have hi:=SemiprimeD1StackCalls.initial_correct R.originalInput R.output (.inl .start) R.program bits\n  have he:=hi.trans (SemiprimeD1StackRootRecursiveControlBounds.initial_eq bits)\n  exact (congrArg (fun cfg:SemiprimeD1StackRootRecursiveControl.machine.Cfg=>cfg.stk (some k)) he).symm\n/-- The genuine target machine starts from original N alone, with no second operand. -/\ntheorem initial_eq (bits:List Bool) : Turing.initList machine bits=SemiprimeD1StackCalls.configuration (initial bits) :=by\n  have hs:SemiprimeD1StackCalls.initial originalInput (.inl .start) bits=initial bits:=by\n    apply congrArg (fun d=>(⟨some (.inl .start),none,none,d,[]⟩:C.State Stack Label))\n    funext k\n    cases k with\n    | inl k=>\n      change (if (Sum.inl k:Stack)=originalInput then bits else [])=R.input bits k\n      rw [root_input]\n      simp only [originalInput,rootStack,Sum.inl.injEq]\n    | inr k=>cases k with\n      | inl k=>cases k <;> rfl\n      | inr i=>fin_cases i <;> rfl\n  exact (SemiprimeD1StackCalls.initial_correct originalInput output (.inl .start) program bits).symm.trans\n    (congrArg SemiprimeD1StackCalls.configuration hs)\n/-- Genuine N-only finite-machine certificate with the same complete own bit clock. -/\nnoncomputable def gridInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (10^60*(bits.length+1)^10) :=by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output (.inl .start) program\n  let h:=source_run_polynomial bits hc hN\n  let t:=Classical.choose h\n  have ht:=Classical.choose_spec h\n  exact ⟨⟨t,ht.2⟩,ht.1⟩\n/-- Every initial allocated role is paid by the sole original N word. -/\ntheorem initial_role_bound (bits:List Bool) (k:Stack) : ((initial bits).data k).length≤bits.length :=by\n  cases k with\n  | inl k=>change (R.input bits k).length≤bits.length;rw [root_input];split <;> simp\n  | inr k=>cases k with\n    | inl k=>cases k <;> exact Nat.zero_le _\n    | inr i=>fin_cases i <;> exact Nat.zero_le _\n/-- The actual same-source halt bounds every successful prefix on either branch. -/\ntheorem prefix_fuel_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel (initial bits)=some out) : fuel≤ runBound bits :=by\n  obtain ⟨t,ht,he⟩:=source_run bits hc hN\n  have hf:fuel≤t:=by\n    by_contra hn\n    have h:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:SemiprimeD1StackCalls.run program 1 (done bits)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- All126 Boolean roles, all119 retained source cells and every real return\ncell are counted at every reached original-input prefix, on both branches. -/\ntheorem prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel (initial bits)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤127*(bits.length+runBound bits+1) :=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length (initial bits) out (initial_role_bound bits) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel (initial bits) out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length)≤126*(bits.length+fuel):=by\n    calc\n      _≤∑_k:Stack,(bits.length+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits hc hN fuel out hr\n  omega\n/-- Same complete storage inventory on the genuine compiled finite-control machine. -/\ntheorem machine_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤127*(bits.length+runBound bits+1) :=by\n  rw [initial_eq] at hr\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output (.inl .start) program fuel (initial bits)\n  have hh:(SemiprimeD1StackCalls.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=some cfg:=he.trans hr\n  cases hrun:SemiprimeD1StackCalls.run program fuel (initial bits) with\n  | none=>rw [hrun] at hh;cases hh\n  | some out=>\n    rw [hrun] at hh\n    have heq:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hc hN fuel out hrun\n/-- A fixed polynomial bounds all actual data and real-return cells. -/\ntheorem polynomial_space (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    127*(bits.length+runBound bits+1)≤10^63*(bits.length+1)^10 :=by\n  have ht:=runBound_le bits hc hN\n  have hn:bits.length+1≤(bits.length+1)^10:=by\n    simpa only [pow_one] using Nat.pow_le_pow_right (by omega : 1≤bits.length+1) (by decide : 1≤10)\n  omega\n/-- Every actual compiled instruction has at most four fundamental commands. -/\ntheorem compile_depth (pc:Label) : SemiprimeD1StackBytecode.statementDepth (machine.m pc)≤4 :=\n  SemiprimeD1StackCalls.compile_depth (.inl .start:Label) (program pc)\nend RiemannGaussian.SemiprimeD1StackRootPhaseGridBounds\n","RiemannGaussian.SemiprimeD1StackRootPhaseParametersInventory":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionOriginal\n/-! # Fixed complete physical order of the forty-eight acquired phase words -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseParametersInventory\nnamespace P\nexport SemiprimeD1StackPhaseWorkingPrecision (Stack input metadataStack aux)\nend P\nnamespace M\nexport SemiprimeD1StackPhaseWorkingPrecisionMetadata (Stack guardStack divStack aux)\nend M\nnamespace G\nexport SemiprimeD1StackPhaseGeometryGuard (geometryStack aux)\nend G\nnamespace Geo\nexport SemiprimeD1StackPhaseGeometry (subStack aux)\nend Geo\n/-- All four literal subtraction roles, including consumed work. -/\ndef subtraction : List SemiprimeD1StackAdder.Stack :=[.left,.right,.scratch,.output]\n/-- All ten original and acquired geometry words. -/\ndef geometry : List SemiprimeD1StackPhaseGeometry.Aux :=\n  [.exponent,.index,.counter,.center,.alpha,.sign,.zero,.order,.scan,.scratch]\n/-- All seven original and acquired guard words. -/\ndef guards : List SemiprimeD1StackPhaseGeometryGuard.Aux :=[.levels,.left,.right,.limit,.valid,.scratch,.output]\n/-- All six literal division roles. -/\ndef division : List SemiprimeD1StackUnaryDivmod.Stack :=[.input,.divisor,.copied,.scratch,.quotient,.remainder]\n/-- All ten original and acquired bounded metadata words. -/\ndef metadata : List SemiprimeD1StackPhaseWorkingPrecisionMetadata.Aux :=\n  [.edges,.precision,.multiplier,.multiplicand,.productScratch,.q,.r,.delta,.subtractWork,.copyScratch]\n/-- All eleven binary work and output words, including both binary P and D. -/\ndef binary : List SemiprimeD1StackPhaseWorkingPrecision.Aux :=\n  [.left,.right,.scratch,.output,.counter,.next,.todo,.zeroTodo,.shiftTodo,.copyScratch,.power]\n/-- Literal fixed role order; all original, rejected and unused words are retained. -/\ndef roles : List P.Stack :=\n  subtraction.map (P.metadataStack ∘ M.guardStack ∘ G.geometryStack ∘ Geo.subStack) ++\n  geometry.map (P.metadataStack ∘ M.guardStack ∘ G.geometryStack ∘ Geo.aux) ++\n  guards.map (P.metadataStack ∘ M.guardStack ∘ G.aux) ++\n  division.map (P.metadataStack ∘ M.divStack) ++metadata.map (P.metadataStack ∘ M.aux) ++binary.map P.aux\n/-- Exactly forty-eight serialized words, independent of every original input. -/\ntheorem roles_length : roles.length=48 :=by decide\n/-- No physical role occurs twice in the fixed record order. -/\ntheorem roles_nodup : roles.Nodup :=by decide\n/-- Every physical stopped phase role is serialized, with none omitted. -/\ntheorem roles_complete (k:P.Stack) : k∈roles :=by\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> simp [roles,subtraction,geometry,guards,division,metadata,binary,P.metadataStack,M.guardStack,G.geometryStack,Geo.subStack,Geo.aux,G.aux,M.divStack,M.aux,P.aux,Function.comp_def]\n        · cases k <;> simp [roles,subtraction,geometry,guards,division,metadata,binary,P.metadataStack,M.guardStack,G.geometryStack,Geo.subStack,Geo.aux,G.aux,M.divStack,M.aux,P.aux,Function.comp_def]\n      · cases k <;> simp [roles,subtraction,geometry,guards,division,metadata,binary,P.metadataStack,M.guardStack,G.geometryStack,Geo.subStack,Geo.aux,G.aux,M.divStack,M.aux,P.aux,Function.comp_def]\n    · rcases k with k|k\n      · cases k <;> simp [roles,subtraction,geometry,guards,division,metadata,binary,P.metadataStack,M.guardStack,G.geometryStack,Geo.subStack,Geo.aux,G.aux,M.divStack,M.aux,P.aux,Function.comp_def]\n      · cases k <;> simp [roles,subtraction,geometry,guards,division,metadata,binary,P.metadataStack,M.guardStack,G.geometryStack,Geo.subStack,Geo.aux,G.aux,M.divStack,M.aux,P.aux,Function.comp_def]\n  · cases k <;> simp [roles,subtraction,geometry,guards,division,metadata,binary,P.metadataStack,M.guardStack,G.geometryStack,Geo.subStack,Geo.aux,G.aux,M.divStack,M.aux,P.aux,Function.comp_def]\n/-- Fixed-position role selection lives entirely in finite program control. -/\ndef role (i:Fin 48) : P.Stack :=roles.get ⟨i.val,by simpa only [roles_length] using i.isLt⟩\n/-- Fixed serialization visits the literal list in its declared order. -/\ntheorem role_get (i:Fin 48) : role i=roles[i.val] :=rfl\n/-- The finite serialization index covers every stopped physical role. -/\ntheorem role_surjective : Function.Surjective role :=by\n  intro k\n  obtain ⟨i,hi⟩:=List.mem_iff_get.mp (roles_complete k)\n  refine ⟨⟨i.val,by simpa only [roles_length] using i.isLt⟩,?_⟩\n  exact hi\n/-- The five original operands are the only nonempty input words. -/\ntheorem input_only (a u edges:Nat) (t p:List Bool) (k:P.Stack) :\n    P.input a u edges t p k=\n      if k=P.metadataStack (M.guardStack (G.geometryStack (Geo.aux .exponent))) then List.replicate a true\n      else if k=P.metadataStack (M.guardStack (G.aux .levels)) then List.replicate u true\n      else if k=P.metadataStack (M.aux .edges) then List.replicate edges true\n      else if k=P.metadataStack (M.guardStack (G.geometryStack (Geo.aux .index))) then t\n      else if k=P.metadataStack (M.aux .precision) then p else [] :=by\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n      · cases k <;> rfl\n    · rcases k with k|k\n      · cases k <;> rfl\n      · cases k <;> rfl\n  · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackRootPhaseParametersInventory\n","RiemannGaussian.SemiprimeD1StackRootScaleLeafBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootScaleLeafExecution\n/-! # Complete25-role and real-return bounds for both actual entries -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1StackRootScaleLeafBounds\nopen SemiprimeD1StackRootScaleLeaf SemiprimeD1StackRootScaleLeafComponents\nopen SemiprimeD1StackRootScaleLeafExecution\n/-- Actual full-source prefixes cannot exceed the proved actual halt. -/\ntheorem prefix_fuel_le (bits : List Bool) (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial bits)=some out) :fuel≤runBound bits :=by\n  obtain ⟨t,ht,hh⟩:=source_run bits\n  have hf:fuel≤t:=by\n    by_contra hn\n    have he:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:SemiprimeD1StackCalls.run program 1 (done bits)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- The ready entry's own clock excludes the earlier metadata source call. -/\ntheorem ready_prefix_fuel_le (bits : List Bool) (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (ready bits)=some out) :fuel≤readyBound bits :=by\n  obtain ⟨t,ht,hh⟩:=ready_run bits\n  have hf:fuel≤t:=by\n    by_contra hn\n    have he:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:SemiprimeD1StackCalls.run program 1 (done bits)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Only the original binary word is present at the whole-source entry. -/\ntheorem initial_bound (bits : List Bool) (j : Stack) :((initial bits).data j).length≤bits.length :=by\n  rcases j with j|j\n  · exact SemiprimeD1StackRootScheduleBounds.initial_bound bits j\n  · rcases j with j|j <;> exact Nat.zero_le _\n/-- Every old cached field is bounded using its ACTUAL concrete producing trace,\nnot an unknown cache/time supplier or a decoded numerical magnitude. -/\ntheorem old_cache_bound (bits : List Bool) (j : R.Stack) :\n    (SemiprimeD1StackRootScheduleExecution.result bits j).length≤\n      bits.length+SemiprimeD1StackRootScheduleExecution.runBound bits :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackRootScheduleExecution.source_run bits\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound R.program t bits.length (R.initial bits)\n    (SemiprimeD1StackRootScheduleExecution.done bits) (SemiprimeD1StackRootScheduleBounds.initial_bound bits) hr j\n  exact hd.trans (by omega)\n/-- ALL ready input roles are actual cache words or EMPTY fresh work/output. -/\ntheorem ready_initial_bound (bits : List Bool) (j : Stack) :((ready bits).data j).length≤\n    bits.length+SemiprimeD1StackRootScheduleExecution.runBound bits :=by\n  rcases j with j|j\n  · exact old_cache_bound bits j\n  · rcases j with j|j <;> exact Nat.zero_le _\n/-- Full actual prefix counts all25 Boolean stacks and every real return cell. -/\ntheorem prefix_cells (bits : List Bool) (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial bits)=some out) :\n    (∑j:Stack,(out.data j).length)+out.frames.length≤26*(bits.length+runBound bits) :=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length (initial bits) out (initial_bound bits) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel (initial bits) out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑j:Stack,(out.data j).length)≤25*(bits.length+fuel):=by\n    calc\n      _≤∑_j:Stack,(bits.length+fuel):=Finset.sum_le_sum (fun j _=>hd j)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits fuel out hr\n  omega\n/-- The ready prefix counts the entire old cache and all fresh work/output/frame\ncells, even while real scaling creates its largest unary metadata word. -/\ntheorem ready_prefix_cells (bits : List Bool) (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (ready bits)=some out) :\n    (∑j:Stack,(out.data j).length)+out.frames.length≤\n      26*(bits.length+SemiprimeD1StackRootScheduleExecution.runBound bits+readyBound bits) :=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel\n    (bits.length+SemiprimeD1StackRootScheduleExecution.runBound bits) (ready bits) out (ready_initial_bound bits) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel (ready bits) out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑j:Stack,(out.data j).length)≤25*(bits.length+SemiprimeD1StackRootScheduleExecution.runBound bits+fuel):=by\n    calc\n      _≤∑_j:Stack,(bits.length+SemiprimeD1StackRootScheduleExecution.runBound bits+fuel):=Finset.sum_le_sum (fun j _=>hd j)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=ready_prefix_fuel_le bits fuel out hr\n  omega\n/-- One original-width cubic bounds the entire whole-source footprint. -/\ntheorem polynomial_space (bits : List Bool) :\n    26*(bits.length+runBound bits)≤1000000000000000*(bits.length+1)^3 :=by\n  have hn:bits.length≤(bits.length+1)^3:=by\n    have h:bits.length+1≤(bits.length+1)^3:=by simpa only [pow_one] using Nat.pow_le_pow_right (by omega :1≤bits.length+1) (by decide :1≤3)\n    omega\n  unfold runBound\n  omega\n/-- The same cubic also bounds every ready-stage cache and fresh/return cell. -/\ntheorem ready_polynomial_space (bits : List Bool) :\n    26*(bits.length+SemiprimeD1StackRootScheduleExecution.runBound bits+readyBound bits)≤\n      1000000000000000*(bits.length+1)^3 :=by\n  have hn:bits.length≤(bits.length+1)^3:=by\n    have h:bits.length+1≤(bits.length+1)^3:=by simpa only [pow_one] using Nat.pow_le_pow_right (by omega :1≤bits.length+1) (by decide :1≤3)\n    omega\n  unfold readyBound SemiprimeD1StackRootScheduleExecution.runBound\n  omega\n/-- Complete actual one-input finite-machine prefix, including all real frames. -/\ntheorem machine_prefix_cells (bits : List Bool) (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑j:Stack,(cfg.stk (some j)).length)+(cfg.stk none).length≤26*(bits.length+runBound bits) :=by\n  rw [initial_eq] at hr\n  have he:=SemiprimeD1StackCalls.run_correct (rootStack (R.boot .input)) (aux .leaf) Label.start program fuel (initial bits)\n  change (SemiprimeD1StackCalls.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial bits))) at he\n  have hh:=he.trans hr\n  cases hrun:SemiprimeD1StackCalls.run program fuel (initial bits) with\n  | none=>rw [hrun] at hh;cases hh\n  | some out=>\n    rw [hrun] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits fuel out hrun\n/-- Complete actual ready-stage finite-machine prefix with the same real return accounting. -/\ntheorem ready_machine_prefix_cells (bits : List Bool) (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (ready bits)))=some cfg) :\n    (∑j:Stack,(cfg.stk (some j)).length)+(cfg.stk none).length≤\n      26*(bits.length+SemiprimeD1StackRootScheduleExecution.runBound bits+readyBound bits) :=by\n  have he:=SemiprimeD1StackCalls.run_correct (rootStack (R.boot .input)) (aux .leaf) Label.start program fuel (ready bits)\n  change (SemiprimeD1StackCalls.run program fuel (ready bits)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (ready bits))) at he\n  have hh:=he.trans hr\n  cases hrun:SemiprimeD1StackCalls.run program fuel (ready bits) with\n  | none=>rw [hrun] at hh;cases hh\n  | some out=>\n    rw [hrun] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact ready_prefix_cells bits fuel out hrun\n/-- Constant elementary-command bound pays the fixed compiled statements too. -/\ntheorem compile_depth (pc : Label) :SemiprimeD1StackBytecode.statementDepth (machine.m pc)≤4 :=\n  SemiprimeD1StackCalls.compile_depth Label.start (program pc)\nend RiemannGaussian.SemiprimeD1StackRootScaleLeafBounds\n","RiemannGaussian.SemiprimeD1StackRootScaleLeafSqrt":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootScaleLeafSubtract\nimport RiemannGaussian.SemiprimeD1StackRootScaleLeafArithmetic\n/-! # Exact integer square root by executed physical odd subtraction -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 100000\nnamespace RiemannGaussian.SemiprimeD1StackRootScaleLeafSqrt\nopen SemiprimeD1StackRootScaleLeaf SemiprimeD1StackRootScaleLeafPrimitives\nopen SemiprimeD1StackRootScaleLeafArithmetic SemiprimeD1StackProcedureTrace\n/-- Fixed-bank view of the actual remaining word, retained odd counter and copied block. -/\ndef context (old : R.Stack→List Bool) (s : List Bool) (n d c : Nat) (rootWord : List Bool) : Stack→List Bool :=\n  store old (D.contents (D.unary n) (D.unary d) (D.unary c) [] [] []) (metadata s rootWord [] [])\n/-- The mathematical invariant indexes ONLY physical unary words, never control. -/\ndef data (old : R.Stack→List Bool) (s : List Bool) (n k c : Nat) : Stack→List Bool :=\n  context old s n (odd k) c (D.unary k)\n/-- Exact stop state after both odd-work words have really been erased. -/\ndef result (old : R.Stack→List Bool) (s : List Bool) (k : Nat) : Stack→List Bool :=\n  context old s 0 0 0 (D.unary k)\n/-- Three literal pushes increment the actual root by one and actual odd block by two. -/\ntheorem advance (old : R.Stack→List Bool) (s : List Bool) (n k : Nat) :\n    Runs program 3 (.advance 0) (data old s n k 0) .squareCopy (data old s n (k+1) 0) :=by\n  let first:=context old s n (odd k) 0 (D.unary (k+1))\n  let second:=context old s n (odd k+1) 0 (D.unary (k+1))\n  let third:=context old s n (odd k+2) 0 (D.unary (k+1))\n  have h0:=push (.advance 0) (.advance 1) (aux .root) (data old s n k 0) rfl\n  have he0:Function.update (data old s n k 0) (aux .root) (true::data old s n k 0 (aux .root))=first:=by\n    funext j;rcases j with j|j\n    · rfl\n    · rcases j with j|j\n      · cases j <;> rfl\n      · cases j <;> rfl\n  rw [he0] at h0\n  have h1:=push (.advance 1) (.advance 2) (divStack .divisor) first rfl\n  have he1:Function.update first (divStack .divisor) (true::first (divStack .divisor))=second:=by\n    funext j;rcases j with j|j\n    · rfl\n    · rcases j with j|j\n      · cases j <;> rfl\n      · cases j <;> rfl\n  rw [he1] at h1\n  have h2:=push (.advance 2) .squareCopy (divStack .divisor) second rfl\n  have he2:Function.update second (divStack .divisor) (true::second (divStack .divisor))=third:=by\n    funext j;rcases j with j|j\n    · rfl\n    · rcases j with j|j\n      · cases j <;> rfl\n      · cases j <;> rfl\n  rw [he2] at h2\n  have hv:odd k+2=odd (k+1):=by unfold odd;omega\n  have he3:third=data old s n (k+1) 0:=by\n    change context old s n (odd k+2) 0 (D.unary (k+1))=_\n    rw [hv]\n    rfl\n  rw [he3] at h2\n  exact join (join h0 h1) h2\n/-- Copying the retained actual odd counter pays restoration and preserves\nALL15 original root-cache fields and all accumulated scale/root/output words. -/\ntheorem copy_odd (old : R.Stack→List Bool) (s : List Bool) (n k : Nat) :\n    Runs program (5*odd k+4) .squareCopy (data old s n k 0) .popOdd (data old s n k (odd k)) :=by\n  have h:=copy_call 2 .squareCopy .popOdd rfl (data old s n k 0) rfl\n  have hl:(data old s n k 0 (copySource 2)).length=odd k:=by\n    change (List.replicate (odd k) true).length=odd k\n    simp only [List.length_replicate]\n  rw [hl] at h\n  have he:Function.update (data old s n k 0) (copyTarget 2)\n      (data old s n k 0 (copySource 2)++data old s n k 0 (copyTarget 2))=data old s n k (odd k):=by\n    funext j;rcases j with j|j\n    · rfl\n    · rcases j with j|j\n      · cases j <;> first | rfl | (change D.unary (odd k)++[]=D.unary (odd k);exact List.append_nil _)\n      · cases j <;> rfl\n  rw [he] at h\n  exact h\n/-- Both success and final failure are REAL physical branches. The only square\nroot is in the proved postcondition, never in the finite instruction table. -/\ntheorem square_root (old : R.Stack→List Bool) (s : List Bool) (n k : Nat) :\n    ∃t≤100000*(2*n+k+1)^2,Runs program t .squareCopy (data old s n k 0)\n      .copyRoot (result old s (Nat.sqrt (n+k^2))) :=by\n  induction n using Nat.strong_induction_on generalizing k with\n  | h n ih=>\n    have hc:=copy_odd old s n k\n    let base:=store old (fun _=>[]) (metadata s (D.unary k) [] [])\n    have hview (m c:Nat):SemiprimeD1StackRootScaleLeafSubtract.data base m (odd k) c=data old s m k c:=by\n      funext j;rcases j with j|j\n      · rfl\n      · rcases j with j|j <;> rfl\n    by_cases hfit:odd k≤ n\n    · have hs:=SemiprimeD1StackRootScaleLeafSubtract.fits base (odd k) n (odd k) hfit\n      rw [hview n (odd k),hview (n-odd k) 0] at hs\n      have ha:=advance old s (n-odd k) k\n      have hsmall:n-odd k<n:=subtract_lt n k hfit\n      obtain ⟨tr,ht,hr⟩:=ih (n-odd k) hsmall (k+1)\n      have h:=join (join (join hc hs) ha) hr\n      have hv:(n-odd k)+(k+1)^2=n+k^2:=subtract_invariant n k hfit\n      rw [hv] at h\n      refine ⟨((5*odd k+4)+(2*odd k+1))+3+tr,?_,h⟩\n      have hp:2*(n-odd k)+(k+1)+1+1≤2*n+k+1:=by have h:=potential_decreases n k hfit;omega\n      have hsq: (2*(n-odd k)+(k+1)+1+1)^2≤(2*n+k+1)^2:=Nat.pow_le_pow_left hp 2\n      unfold odd at *\n      nlinarith\n    · have hshort:n<odd k:=by omega\n      have hs:=SemiprimeD1StackRootScaleLeafSubtract.short base n (odd k) (odd k) hshort\n      rw [hview n (odd k)] at hs\n      have hd:=SemiprimeD1StackRootScaleLeafSubtract.clear base (odd k) (odd k-n-1)\n      have h:=join (join hc hs) hd\n      have he:SemiprimeD1StackRootScaleLeafSubtract.data base 0 0 0=result old s k:=by\n        funext j;rcases j with j|j\n        · rfl\n        · rcases j with j|j <;> rfl\n      rw [he] at h\n      have hv:Nat.sqrt (n+k^2)=k:=stop_exact n k hshort\n      rw [hv]\n      refine ⟨(5*odd k+4)+(2*n+2)+((odd k-n-1+1)+(odd k+1)),?_,h⟩\n      have hp:1≤2*n+k+1:=by omega\n      have hsq:2*n+k+1≤(2*n+k+1)^2:=by simpa only [pow_one] using Nat.pow_le_pow_right hp (by decide : 1≤2)\n      have hle:odd k-n-1≤ odd k:=by omega\n      unfold odd at *\n      nlinarith\nend RiemannGaussian.SemiprimeD1StackRootScaleLeafSqrt\n","RiemannGaussian.SemiprimeD1StackRootSelectionAcquireBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireExecution\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireInputBounds\n/-! # Own original-input whole-program acquisition bound\nThe only exponential factor comes from the actual row producer. Its fixed\npower is preserved through the genuinely executed whole selection source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSelectionAcquireBounds\nopen SemiprimeD1StackRootSelectionAcquire SemiprimeD1StackRootSelectionAcquireEncoding\nopen SemiprimeD1StackRootSelectionAcquireExecution SemiprimeD1StackRootSelectionAcquireInputBounds\nopen SemiprimeBitArithmetic (bitValue)\n/-- Fixed coefficient before every original N and before every actual acquired row/selection. -/\ndef clockCoefficient :Nat :=10^500*5^100+100\n/-- Own original-input cap uses only paid source allowances, with no semantic result oracle. -/\ndef runBound (bits:List Bool) :Nat :=clockCoefficient*(envelope bits)^100\n/-- The actual complete selection stage is charged to the actual original-input producer envelope. -/\ntheorem selection_clock_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) :\n    E.polynomial (net bits hN) (dimension bits) ≤(10^500*5^100)*(envelope bits)^100 :=by\n  have h:=Nat.mul_le_mul_left (10^500) (Nat.pow_le_pow_left (selection_input_bound bits hc hN) 100)\n  simpa only [SemiprimeD1StackSourceSelectionAcquireBounds.polynomial,mul_pow,Nat.mul_assoc] using h\nset_option exponentiation.threshold 512 in\n/-- SAME whole actual clock pays acquisition, four copies, all three calls and halt. -/\ntheorem timeBound_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) :timeBound bits hN ≤runBound bits :=by\n  obtain ⟨hpos,hbits,hrows,hparameters⟩:=envelope_parts bits\n  have hcopy:=acquisition_copy_bound bits hc hN\n  have hselection:=selection_clock_bound bits hc hN\n  have hlinear:envelope bits ≤(envelope bits)^100:=by\n    simpa only [pow_one] using Nat.pow_le_pow_right hpos (by decide:1 ≤100)\n  unfold parameterBound at hparameters\n  unfold timeBound runBound clockCoefficient\n  nlinarith only [hpos,hbits,hrows,hparameters,hcopy,hselection,hlinear]\n/-- The identical actual source halts under its own complete original-input cap. -/\ntheorem source_run_bounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) :\n    ∃q ≤runBound bits,SemiprimeD1StackCalls.run program q (initial bits)=some (done bits hN) :=by\n  obtain ⟨q,hq,hr⟩:=source_run bits hc hN\n  exact ⟨q,hq.trans (timeBound_le bits hc hN),hr⟩\nend RiemannGaussian.SemiprimeD1StackRootSelectionAcquireBounds\n","RiemannGaussian.SemiprimeD1StackRootSelectionAcquireEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireCalls\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireInput\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireRate\n/-! # Exact original-N interpretation of the physically acquired source banks\nAll graphs, dimensions and stopped states below describe physical runs.\nThe actual source accepts only binary N and computes every derived byte.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSelectionAcquireEncoding\nopen SemiprimeD1StackRootSelectionAcquire SemiprimeD1StackRootSelectionAcquireInput\nopen SemiprimeBitArithmetic (bitValue)\nnamespace E\nexport SemiprimeD1StackSourceSelectionAcquireEncoding (source done)\nexport SemiprimeD1StackSourceSelectionAcquireBounds (polynomial)\nend E\n/-- Original typed root is a proof interpretation of the actually acquired records/rows. -/\ndef net (bits:List Bool) (hN:0 < bitValue bits) :SemiprimeD1TensorNetwork.Network :=\n  SemiprimeD1StackRootOwnerIndexComponents.net bits hN []\n/-- Exact original root dimension; no dimension is supplied to runtime control. -/\ndef dimension (bits:List Bool) :Nat :=SemiprimeD1StackRootSelectionAcquireRate.originalDimension (bitValue bits)\n/-- Actual whole original row source halt, including every retained record/cache word. -/\ndef rootDone (bits:List Bool) (hN:0 < bitValue bits) :C.State R.Stack R.Label :=\n  SemiprimeD1StackRootNetworkRowsExecution.done bits hN [] []\n/-- Actual original parameter-source halt, including all108 words. -/\ndef parameterDone (bits:List Bool) :C.State P.Stack P.Label :=SemiprimeD1StackRootParametersExecution.done bits\n/-- Entire actual selected-key source halt from those acquired original operands. -/\ndef acquisitionDone (bits:List Bool) (hN:0 < bitValue bits) :C.State Q.Stack Q.Label :=\n  E.done (net bits hN) (dimension bits)\n/-- All2114 actual words are physically retained at the whole original-input halt. -/\ndef result (bits:List Bool) (hN:0 < bitValue bits) :Stack→List Bool :=\n  data (rootDone bits hN).data (parameterDone bits).data (acquisitionDone bits hN).data\n/-- Exact full halt has clear flags and no outstanding actual component return. -/\ndef done (bits:List Bool) (hN:0 < bitValue bits) :C.State Stack Label :=⟨none,none,none,result bits hN,[]⟩\n/-- Own whole clock includes all three actual sources, four copies, three calls and halt. -/\ndef timeBound (bits:List Bool) (hN:0 < bitValue bits) :Nat :=\n  5*bits.length+10^51*(bits.length+1)^10+SemiprimeD1StackRootNetworkRowsBounds.runBound bits+\n    acquisitionCopyTime (rootDone bits hN).data (parameterDone bits).data+\n    E.polynomial (net bits hN) (dimension bits)+8\n/-- The three actual stopped-producer words form the exact original acquired selection entry. -/\ntheorem acquisitionReady_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) :\n    acquisitionReady (rootDone bits hN).data (parameterDone bits).data=(E.source (net bits hN) (dimension bits)).data :=by\n  rw [acquisitionReady_input]\n  change SemiprimeD1StackSourceSelectionAcquire.input\n    ((rootDone bits hN).data R.output) ((rootDone bits hN).data R.leftCount)\n      ((parameterDone bits).data P.exponent)=_\n  have hr:(rootDone bits hN).data R.output=SemiprimeD1StackNetworkRowsEncoding.originalTape (net bits hN):=\n    SemiprimeD1StackRootNetworkRowsOriginal.output_original bits hc hN [] []\n  have hn:(rootDone bits hN).data R.leftCount=List.replicate (net bits hN).leftCount true:=\n    SemiprimeD1StackRootNetworkRowsOriginal.left_count bits hc hN [] []\n  have ha:(parameterDone bits).data P.exponent=List.replicate (dimension bits) true:=\n    SemiprimeD1StackRootParametersOriginal.exponent_original bits hc\n  rw [hr,hn,ha]\n  rw [←SemiprimeD1StackSourceOccurrencesEncoding.original_input]\n  rfl\nend RiemannGaussian.SemiprimeD1StackRootSelectionAcquireEncoding\n","RiemannGaussian.SemiprimeD1StackRootSelectionAcquirePrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireView\n/-! # Actual original-input handoff copies with their own physical calls and returns -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSelectionAcquirePrimitives\nopen SemiprimeD1StackRootSelectionAcquire SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Actual fragments concatenate with all external real return frames retained. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Every cache/input handoff is a real preserving copy, not a semantic operand assignment. -/\ntheorem copy_call (site:Copy) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copySource site)=xs) (hy:before (copyTarget site)=ys) (hs:before copyScratch=[]) :\n    Runs program (5*xs.length+4) (ctl (.copy site)) before (copyNext site)\n      (Function.update before (copyTarget site) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack site) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack site) (copy_injective site) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack site) (Label.copy site) (copy_injective site) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl (.copy site)) (copyNext site) rfl (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\nend RiemannGaussian.SemiprimeD1StackRootSelectionAcquirePrimitives\n","RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesComponents\n/-! # Whole original-binary-N to ordered compact occurrence-key source execution\nThe real records/index source runs once. Its actual index cache then enters\nthe same occurrence source program. Both real calls and the final halt share one clock.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesExecution\nopen SemiprimeD1StackRootSourceOccurrences SemiprimeD1StackRootSourceOccurrencesComponents\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (bitValue)\nlocal notation \"ctl\" => (Sum.inl :Control→Label)\n/-- Exact clean halt of the same whole original-N program, retaining every1852source word. -/\ndef done (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :C.State Stack Label :=\n  ⟨none,none,none,result bits hN fixed tail,[]⟩\n/-- Own whole source clock pays the actual original records/index source, actual occurrence source, both calls and halt. -/\ndef timeBound (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :Nat :=\n  SemiprimeD1StackRootNetworkRowsExecution.timeBound bits hN fixed tail+\n    E.timeBound (rootn bits hN fixed) (rootrows bits hN fixed)+3\n/-- The actual N-only row/index acquisition runs inside the one whole caller. -/\ntheorem root_call (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃q≤SemiprimeD1StackRootNetworkRowsExecution.timeBound bits hN [] [],\n      Runs program (q+1) (ctl .start) (input bits) (ctl .occurrences) (data (R.done bits hN [] []).data (fun _=>[])) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackRootNetworkRowsExecution.source_run bits hc hN\n  exact ⟨q,hq,root_lift (.inl .start) .start rfl (R.initial bits) (R.done bits hN [] []) q rfl rfl rfl rfl hr⟩\n/-- The actual caller-prefix row/index acquisition enters the same occurrence source call. -/\ntheorem root_prefix_call (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    ∃q≤SemiprimeD1StackRootNetworkRowsExecution.timeBound bits hN fixed tail,\n      Runs program (q+1) (ctl .prescribed)\n        (initialPrefix bits (SemiprimeD1StackRootNetworkRecordsAcquisition.prescription bits fixed tail)).data\n        (ctl .occurrences) (data (R.done bits hN fixed tail).data (fun _=>[])) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackRootNetworkRowsExecution.source_run_prefix bits hc hN fixed tail\n  exact ⟨q,hq,root_lift (.inl .prescribed) .prescribed rfl\n    (R.initialPrefix bits (SemiprimeD1StackRootNetworkRecordsAcquisition.prescription bits fixed tail))\n    (R.done bits hN fixed tail) q rfl rfl rfl rfl hr⟩\n/-- One actual prescribed-prefix trace includes real source acquisition and exact occurrence-key construction. -/\ntheorem source_prefix_trace (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    ∃q,q+1≤timeBound bits hN fixed tail ∧ Runs program q (ctl .prescribed)\n      (initialPrefix bits (SemiprimeD1StackRootNetworkRecordsAcquisition.prescription bits fixed tail)).data\n      (ctl .done) (result bits hN fixed tail) :=by\n  obtain ⟨a,ha,h0⟩:=root_prefix_call bits hc hN fixed tail\n  obtain ⟨b,hb,h1⟩:=occurrence_call bits hc hN fixed tail\n  refine ⟨(a+1)+(b+1),?_,runs_trans program _ _ _ _ _ _ _ _ h0 h1⟩\n  unfold timeBound\n  omega\n/-- One actual N-only trace includes all acquisition and every row/tally output byte. -/\ntheorem source_trace (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃q,q+1≤timeBound bits hN [] [] ∧ Runs program q (ctl .start) (input bits)\n      (ctl .done) (result bits hN [] []) :=by\n  obtain ⟨a,ha,h0⟩:=root_call bits hc hN\n  obtain ⟨b,hb,h1⟩:=occurrence_call bits hc hN [] []\n  refine ⟨(a+1)+(b+1),?_,runs_trans program _ _ _ _ _ _ _ _ h0 h1⟩\n  unfold timeBound\n  omega\n/-- Complete actual original-N source and its real final halt. -/\ntheorem source_run (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃q≤timeBound bits hN [] [],SemiprimeD1StackCalls.run program q (initial bits)=some (done bits hN [] []) :=by\n  obtain ⟨q,hq,hr⟩:=source_trace bits hc hN\n  obtain ⟨finish,hf,hAt⟩:=hr [] (initial bits) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result bits hN [] []) [] finish hAt\n  exact ⟨q+1,hq,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- The same actual source covers every physical prescription, including repeated/conflicting entries and retained tails. -/\ntheorem source_run_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    ∃q≤timeBound bits hN fixed tail,SemiprimeD1StackCalls.run program q\n      (initialPrefix bits (SemiprimeD1StackRootNetworkRecordsAcquisition.prescription bits fixed tail))=\n        some (done bits hN fixed tail) :=by\n  obtain ⟨q,hq,hr⟩:=source_prefix_trace bits hc hN fixed tail\n  obtain ⟨finish,hf,hAt⟩:=hr []\n    (initialPrefix bits (SemiprimeD1StackRootNetworkRecordsAcquisition.prescription bits fixed tail)) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result bits hN fixed tail) [] finish hAt\n  exact ⟨q+1,hq,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- Every actual1852original source/index word survives literally at the row boundary. -/\ntheorem root_retained (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) (k:R.Stack) :\n    (done bits hN fixed tail).data (rootStack k)=(R.done bits hN fixed tail).data k :=rfl\nend RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesExecution\n","RiemannGaussian.SemiprimeD1StackSourceAlphabet64Arithmetic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Bounds\nimport RiemannGaussian.SemiprimeSourceHistogramHeadRefinement\n/-! # Proof-only exact head-major radix64 packing of the actual fixed-width counter -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceAlphabet64Arithmetic\nopen SemiprimeD1StackSourceAlphabet64Encoding SemiprimeD1StackSourceAlphabet64Bounds\nopen SemiprimeBitArithmetic (bitValue bitNat)\nnamespace A\nexport SemiprimeD1StackAssignmentOrder (assignments assignments_values assignments_width word_value_injective zero_remaining)\nend A\n/-- General numeric concatenation identity for actual little-endian Boolean words. -/\ntheorem value_append (xs ys:List Bool) :bitValue (xs++ys)=bitValue xs+2^xs.length*bitValue ys :=by\n  induction xs with\n  | nil=>simp only [List.nil_append,bitValue,List.length_nil,pow_zero,Nat.one_mul,Nat.zero_add]\n  | cons b xs ih=>simp only [List.cons_append,bitValue,ih,List.length_cons,pow_succ];ring\n/-- Fixed-width all-false words represent zero, including empty width. -/\ntheorem zero_value (n:Nat) :bitValue (List.replicate n false)=0 :=by\n  induction n with\n  | zero=>rfl\n  | succ n ih=>simp only [List.replicate_succ,bitValue,bitNat,Bool.false_eq_true,ite_false,ih,Nat.mul_zero,Nat.add_zero]\n/-- Literal complete six-bit counter bank used only to identify each bounded colour in proofs. -/\ndef digit (c:Fin 64) :List Bool :=((A.assignments 64 (List.replicate 6 false))[c.val]?).getD []\n/-- Each original finite colour has one exact six-bit physical representation. -/\ntheorem digit_length (c:Fin 64) :(digit c).length=6 :=by\n  have hc:c.val<(A.assignments 64 (List.replicate 6 false)).length:=by\n    rw [SemiprimeD1StackAssignmentOrder.assignments_length];exact c.isLt\n  rw [digit,List.getElem?_eq_getElem hc,Option.getD_some]\n  exact (A.assignments_width _ _ _ (List.getElem_mem hc)).trans List.length_replicate\n/-- Counter order identifies exactly the native finite colour ordinal. -/\ntheorem digit_value (c:Fin 64) :bitValue (digit c)=c.val :=by\n  have hv:=A.assignments_values 64 (List.replicate 6 false) (by rw [A.zero_remaining];decide)\n  rw [zero_value,←List.range_eq_range'] at hv\n  have hc:c.val<(A.assignments 64 (List.replicate 6 false)).length:=by\n    rw [SemiprimeD1StackAssignmentOrder.assignments_length];exact c.isLt\n  have h:=congrArg (fun xs:List Nat=>(xs[c.val]?).getD 0) hv\n  simpa only [digit,List.getElem?_map,List.getElem?_eq_getElem hc,List.getElem?_range c.isLt,\n    Option.map_some,Option.getD_some] using h\n/-- Exact old canonical colour ABI, including the EMPTY colour-zero representation. -/\ntheorem digit_compact (c:Fin 64) :compact (digit c)=SemiprimeSourceHistogramHeadRefinement.numberKey c.val :=by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective _ _\n    (SemiprimeSourceCompactBits.trim_compact _) (SemiprimeSourceHistogramHeadRefinement.numberKey_compact _)\n  rw [SemiprimeSourceCompactBits.trim_value,digit_value,SemiprimeSourceHistogramHeadRefinement.numberKey_value]\n/-- Pure head-major finite coordinate enumeration; this is never a runtime operand. -/\ndef digits :Nat→List (List (Fin 64))\n  | 0=>[[]]\n  | a+1=>(List.finRange 64).flatMap (fun c=>(digits a).map (c::.))\n/-- Original physical little-endian packed counter layout: the last coordinate contributes low bits. -/\ndef pack :List (Fin 64)→List Bool\n  | []=>[]\n  | c::cs=>pack cs++digit c\n/-- Proof-side head-major ordinal of one original colour tuple. -/\ndef rank :List (Fin 64)→Nat\n  | []=>0\n  | c::cs=>c.val*64^cs.length+rank cs\n/-- Every proof tuple retains its exact coordinate count. -/\ntheorem digits_width (a:Nat) (cs:List (Fin 64)) (hc:cs∈digits a) :cs.length=a :=by\n  induction a generalizing cs with\n  | zero=>have he:cs=[]:=List.mem_singleton.mp hc;subst cs;rfl\n  | succ a ih=>\n    obtain ⟨c,hcMember,hmapped⟩:=List.mem_flatMap.mp hc\n    obtain ⟨rest,hrest,he⟩:=List.mem_map.mp hmapped\n    subst cs\n    exact congrArg Nat.succ (ih rest hrest)\n/-- Literal packed width is six actual bits per original coordinate. -/\ntheorem pack_length (cs:List (Fin 64)) :(pack cs).length=6*cs.length :=by\n  induction cs with\n  | nil=>rfl\n  | cons c cs ih=>simp only [pack,List.length_append,ih,digit_length,List.length_cons];omega\n/-- Packed counter value is its exact head-major finite tuple ordinal. -/\ntheorem pack_value (cs:List (Fin 64)) :bitValue (pack cs)=rank cs :=by\n  induction cs with\n  | nil=>rfl\n  | cons c cs ih=>\n    rw [pack,value_append,pack_length,cardinality,ih,digit_value]\n    change _=c.val*64^cs.length+rank cs\n    ring\n/-- Finite ordinal values retain their exact original order. -/\ntheorem fin_values (n:Nat) :(List.finRange n).map Fin.val=List.range n :=by\n  induction n with\n  | zero=>rfl\n  | succ n ih=>simp only [List.finRange_succ,List.map_cons,List.map_map,Fin.val_zero,Fin.val_succ,\n      List.range_succ_eq_map,←ih,List.map_map,Function.comp_def,Nat.succ_eq_add_one]\n/-- Head-major rectangle traversal is the contiguous original mixed-radix ordinal range. -/\ntheorem rectangle_values (heads tails:Nat) :\n    (List.range heads).flatMap (fun h=>(List.range tails).map (fun t=>h*tails+t))=List.range (heads*tails) :=by\n  induction heads with\n  | zero=>simp only [List.range_zero,List.flatMap_nil,Nat.zero_mul]\n  | succ heads ih=>\n    rw [List.range_succ,List.flatMap_append,List.flatMap_singleton,ih,Nat.succ_mul,List.range_add]\n/-- The original head-major tuple ranks enumerate EVERY counter ordinal in exactly ascending order. -/\ntheorem ranks_values (a:Nat) :(digits a).map rank=List.range (64^a) :=by\n  induction a with\n  | zero=>rfl\n  | succ a ih=>\n    simp only [digits,List.map_flatMap,List.map_map]\n    have he:∀c:Fin 64,(digits a).map (fun cs=>rank (c::cs))=\n        (List.range (64^a)).map (fun t=>c.val*64^a+t):=by\n      intro c\n      calc\n        _=(digits a).map (fun cs=>c.val*64^a+rank cs):=by\n          apply List.map_congr_left\n          intro cs hc\n          simp only [rank,digits_width a cs hc]\n        _=((digits a).map rank).map (fun t=>c.val*64^a+t):=by rw [List.map_map];rfl\n        _= _:=by rw [ih]\n    change (List.finRange 64).flatMap (fun c=>(digits a).map (fun cs=>rank (c::cs)))=_\n    simp_rw [he]\n    rw [show (List.finRange 64).flatMap (fun c=>(List.range (64^a)).map (fun t=>c.val*64^a+t))=\n      ((List.finRange 64).map Fin.val).flatMap (fun c=>(List.range (64^a)).map (fun t=>c*64^a+t)) by rw [List.flatMap_map]]\n    rw [fin_values,rectangle_values,pow_succ,Nat.mul_comm]\n/-- Physical complete counter values are the same original ascending ordinal range. -/\ntheorem words_values (a:Nat) :(words a).map bitValue=List.range (64^a) :=by\n  rw [words,A.assignments_values _ _ (by rw [A.zero_remaining])]\n  rw [zero_value,←List.range_eq_range',cardinality]\n/-- Fixed-width lists are determined by their actual numeric sequences, without a permutation premise. -/\ntheorem fixed_lists_eq (xs ys:List (List Bool)) (width:Nat)\n    (hx:∀x∈xs,x.length=width) (hy:∀y∈ys,y.length=width) (hv:xs.map bitValue=ys.map bitValue) :xs=ys :=by\n  induction xs generalizing ys with\n  | nil=>cases ys with | nil=>rfl | cons y ys=>cases hv\n  | cons x xs ih=>\n    cases ys with\n    | nil=>cases hv\n    | cons y ys=>\n      have hh:=List.cons.inj hv\n      have hxy:x=y:=A.word_value_injective x y\n        ((hx x List.mem_cons_self).trans (hy y List.mem_cons_self).symm) hh.1\n      have ht:=ih ys (fun z hz=>hx z (List.mem_cons_of_mem _ hz))\n        (fun z hz=>hy z (List.mem_cons_of_mem _ hz)) hh.2\n      rw [hxy,ht]\n/-- The actual counter enumeration is LITERALLY the packed old head-major colour enumeration. -/\ntheorem packed_words (a:Nat) :(digits a).map pack=words a :=by\n  apply fixed_lists_eq _ _ (6*a)\n  · intro w hw\n    obtain ⟨cs,hc,rfl⟩:=List.mem_map.mp hw\n    rw [pack_length,digits_width a cs hc]\n  · exact word_width a\n  · rw [List.map_map]\n    simp only [Function.comp_def,pack_value]\n    rw [ranks_values,words_values]\n/-- Every real six-bit parsed/normalized colour is exactly the old finite coordinate word. -/\ntheorem colours_pack (cs:List (Fin 64)) :\n    colours cs.length (pack cs).reverse=cs.map (fun c=>compact (digit c)) :=by\n  induction cs with\n  | nil=>rfl\n  | cons c cs ih=>\n    have ht:((digit c).reverse++(pack cs).reverse).take 6=(digit c).reverse:=by\n      simpa only [List.length_reverse,digit_length] using (List.take_left (l₁:=(digit c).reverse) (l₂:=(pack cs).reverse))\n    have hd:((digit c).reverse++(pack cs).reverse).drop 6=(pack cs).reverse:=by\n      simpa only [List.length_reverse,digit_length] using (List.drop_left (l₁:=(digit c).reverse) (l₂:=(pack cs).reverse))\n    simp only [List.length_cons,pack,List.reverse_append,colours,ht,hd,List.reverse_reverse,List.map_cons,ih]\nend RiemannGaussian.SemiprimeD1StackSourceAlphabet64Arithmetic\n","RiemannGaussian.SemiprimeD1StackSourceAlphabet64Rows":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64ColourLoop\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Calls\n/-! # One actual full compact-ID/base64-row catalogue write with all cleanup charged -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceAlphabet64Rows\nopen SemiprimeD1StackSourceAlphabet64 SemiprimeD1StackSourceAlphabet64Encoding\nopen SemiprimeD1StackSourceAlphabet64Primitives SemiprimeD1StackSourceAlphabet64Calls\nopen SemiprimeD1StackSourceAlphabet64ColourLoop SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- The actual twelve row-local/cursor/history fields; every other physical word is retained. -/\ndef view (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist:List Bool) :Stack→List Bool\n  | .inr .reader=>reader | .inr .raw=>raw | .inr .bits=>bits | .inr .bitsReverse=>rev\n  | .inr .trimScratch=>tr | .inr .id=>ident | .inr .colourRaw=>rawcol | .inr .colour=>col\n  | .inr .rowHistory=>rowhist | .inr .row=>rowword | .inr .frameBuffer=>buf | .inr .history=>hist\n  | k=>base k\n/-- One actual reader write retains every other physical role. -/\ntheorem update_reader (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .reader) next=view base next raw bits rev tr ident rawcol col rowhist rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual raw write retains every other physical role. -/\ntheorem update_raw (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .raw) next=view base reader next bits rev tr ident rawcol col rowhist rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual bits write retains every other physical role. -/\ntheorem update_bits (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .bits) next=view base reader raw next rev tr ident rawcol col rowhist rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual bitsReverse write retains every other physical role. -/\ntheorem update_rev (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .bitsReverse) next=view base reader raw bits next tr ident rawcol col rowhist rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual trimScratch write retains every other physical role. -/\ntheorem update_tr (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .trimScratch) next=view base reader raw bits rev next ident rawcol col rowhist rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual id write retains every other physical role. -/\ntheorem update_ident (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .id) next=view base reader raw bits rev tr next rawcol col rowhist rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual colourRaw write retains every other physical role. -/\ntheorem update_rawcol (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .colourRaw) next=view base reader raw bits rev tr ident next col rowhist rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual colour write retains every other physical role. -/\ntheorem update_col (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .colour) next=view base reader raw bits rev tr ident rawcol next rowhist rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual rowHistory write retains every other physical role. -/\ntheorem update_rowhist (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .rowHistory) next=view base reader raw bits rev tr ident rawcol col next rowword buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual row write retains every other physical role. -/\ntheorem update_rowword (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .row) next=view base reader raw bits rev tr ident rawcol col rowhist next buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual frameBuffer write retains every other physical role. -/\ntheorem update_buf (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .frameBuffer) next=view base reader raw bits rev tr ident rawcol col rowhist rowword next hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual history write retains every other physical role. -/\ntheorem update_hist (base:Stack→List Bool) (reader raw bits rev tr ident rawcol col rowhist rowword buf hist next:List Bool) :\n    Function.update (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist) (aux .history) next=view base reader raw bits rev tr ident rawcol col rowhist rowword buf next :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- The real colour-loop view touches exactly its six actual row-local fields. -/\ntheorem colour_view (base:Stack→List Bool)\n    (reader raw bits rev tr ident rawcol col rowhist rowword buf hist rev' rawcol' tr' col' buf' rowhist':List Bool) :\n    SemiprimeD1StackSourceAlphabet64Colours.view (view base reader raw bits rev tr ident rawcol col rowhist rowword buf hist)\n      rev' rawcol' tr' col' buf' rowhist'=\n      view base reader raw bits rev' tr' ident rawcol' col' rowhist' rowword buf' hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One exact dictionary row is its actual tag and TWO actual framed fields. -/\ndef chunk (a:Nat) (word:List Bool) :List Bool :=true::frame (compact word) (frame (row a word) [])\n/-- One real saveWord path consumes the actual raw fixed-width assignment and\nwrites its canonical-ID/full-row pair while clearing every row-local work word. -/\ntheorem word_run (base:Stack→List Bool) (a:Nat) (word reader hist:List Bool) (hlen:word.length=6*a)\n    (hc:base (aux .copyScratch)=[]) (hl:base (aux .trimLeft)=[]) (hr:base (aux .trimRight)=[])\n    (hs:base (aux .frameScratch)=[]) :\n    ∃q ≤ 1000*(a+1),Runs program q .saveWord\n      (view base reader word [] [] [] [] [] [] [] [] [] hist) .header\n      (view base reader [] [] [] [] [] [] [] [] [] [] ((chunk a word).reverse++hist)) :=by\n  let ident:=compact word\n  let rowword:=row a word\n  have h0:=copy_call .word .saveWord .reverseID rfl (view base reader word [] [] [] [] [] [] [] [] [] hist) rfl hc\n  change Runs program (5*word.length+4) .saveWord _ .reverseID\n    (Function.update (view base reader word [] [] [] [] [] [] [] [] [] hist) (aux .bits) word) at h0\n  rw [update_bits] at h0\n  change Runs program (5*word.length+4) .saveWord _ .reverseID (view base reader word word [] [] [] [] [] [] [] [] hist) at h0\n  have h1:=reverse_call .id .reverseID (.normalize .id) rfl (view base reader word word [] [] [] [] [] [] [] [] hist)\n  change Runs program (2*word.length+3) .reverseID _ (.normalize .id)\n    (Function.update (Function.update (view base reader word word [] [] [] [] [] [] [] [] hist) (aux .raw) [])\n      (aux .trimScratch) (word.reverse++[])) at h1\n  rw [update_raw,update_tr,List.append_nil] at h1\n  have h2:=trim_call .id (view base reader [] word [] word.reverse [] [] [] [] [] [] hist) hl hr\n  change Runs program (SemiprimeD1StackReduceExecution.trimTime word.reverse+1) (.normalize .id) _ .reverseBits\n    (Function.update (Function.update (view base reader [] word [] word.reverse [] [] [] [] [] [] hist) (aux .trimScratch) [])\n      (aux .id) (SemiprimeD1StackReduceExecution.trimReverse word.reverse++[])) at h2\n  rw [update_tr,update_ident,List.append_nil,trim_reverse] at h2\n  have h3:=reverse_call .bits .reverseBits .colourStart rfl (view base reader [] word [] [] ident [] [] [] [] [] hist)\n  change Runs program (2*word.length+3) .reverseBits _ .colourStart\n    (Function.update (Function.update (view base reader [] word [] [] ident [] [] [] [] [] hist) (aux .bits) [])\n      (aux .bitsReverse) (word.reverse++[])) at h3\n  rw [update_bits,update_rev,List.append_nil] at h3\n  obtain ⟨c,hcBound,h4⟩:=colours_run (view base reader [] [] [] [] ident [] [] [] [] [] hist) a word.reverse []\n    (by rw [List.length_reverse];exact hlen) hl hr hs\n  rw [colour_view,colour_view,List.append_nil] at h4\n  change Runs program c .colourStart _ .reverseRow\n    (view base reader [] [] [] [] ident [] [] (fields (colours a word.reverse)).reverse [] [] hist) at h4\n  have h5:=reverse_call .row .reverseRow .frameRow rfl\n    (view base reader [] [] [] [] ident [] [] rowword.reverse [] [] hist)\n  change Runs program (2*rowword.reverse.length+3) .reverseRow _ .frameRow\n    (Function.update (Function.update (view base reader [] [] [] [] ident [] [] rowword.reverse [] [] hist) (aux .rowHistory) [])\n      (aux .row) (rowword.reverse.reverse++[])) at h5\n  rw [update_rowhist,update_rowword,List.reverse_reverse,List.append_nil] at h5\n  have h6:=frame_call .row .frameRow .frameID rfl (view base reader [] [] [] [] ident [] [] [] rowword [] hist) hs\n  change Runs program (6*rowword.length+5) .frameRow _ .frameID\n    (Function.update (view base reader [] [] [] [] ident [] [] [] rowword [] hist) (aux .frameBuffer) (frame rowword [])) at h6\n  rw [update_buf] at h6\n  have h7:=frame_call .id .frameID .pairTag rfl (view base reader [] [] [] [] ident [] [] [] rowword (frame rowword []) hist) hs\n  change Runs program (6*ident.length+5) .frameID _ .pairTag\n    (Function.update (view base reader [] [] [] [] ident [] [] [] rowword (frame rowword []) hist) (aux .frameBuffer)\n      (frame ident (frame rowword []))) at h7\n  rw [update_buf] at h7\n  have h8:Runs program 1 .pairTag (view base reader [] [] [] [] ident [] [] [] rowword (frame ident (frame rowword [])) hist)\n      .reversePair (view base reader [] [] [] [] ident [] [] [] rowword (chunk a word) hist):=by\n    apply one_base program _ _ (.push (aux .frameBuffer) true .reversePair) _ _ rfl\n    · rfl\n    · exact update_buf _ _ _ _ _ _ _ _ _ _ _ _ _ _\n  have h9:=reverse_call .pair .reversePair .clearID rfl\n    (view base reader [] [] [] [] ident [] [] [] rowword (chunk a word) hist)\n  change Runs program (2*(chunk a word).length+3) .reversePair _ .clearID\n    (Function.update (Function.update (view base reader [] [] [] [] ident [] [] [] rowword (chunk a word) hist) (aux .frameBuffer) [])\n      (aux .history) ((chunk a word).reverse++hist)) at h9\n  rw [update_buf,update_hist] at h9\n  have h10:=SemiprimeD1StackPhysicalLoops.drain program .clearID .clearRow (aux .id) rfl\n    (view base reader [] [] [] [] ident [] [] [] rowword [] ((chunk a word).reverse++hist)) ident\n  rw [update_ident,update_ident] at h10\n  have h11:=SemiprimeD1StackPhysicalLoops.drain program .clearRow .header (aux .row) rfl\n    (view base reader [] [] [] [] [] [] [] [] rowword [] ((chunk a word).reverse++hist)) rowword\n  rw [update_rowword,update_rowword] at h11\n  have hall:=compose (compose (compose (compose (compose (compose (compose (compose (compose (compose (compose h0 h1) h2) h3) h4) h5) h6) h7) h8) h9) h10) h11\n  refine ⟨_,?_,hall⟩\n  have hi:ident.length ≤ word.length:=SemiprimeSourceCompactBits.trim_length word\n  have hrow:rowword.length ≤ 13*a:=row_length a word\n  have ht:=SemiprimeD1StackReduceExecution.trimTime_le word.reverse\n  have hchunk:(chunk a word).length=2*ident.length+2*rowword.length+3:=by\n    change (true::frame ident (frame rowword [])).length=_\n    simp only [List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n    omega\n  rw [List.length_reverse,hlen] at ht\n  rw [List.length_reverse,hchunk]\n  omega\nend RiemannGaussian.SemiprimeD1StackSourceAlphabet64Rows\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectOccurrences":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectMeaning\nimport RiemannGaussian.SemiprimeD1StackSourceOccurrencesOriginal\n/-! # Original physical occurrence stream in the exact selector order\nThis proof connects the acquired row stream to the original factor/local-slot\nmetadata. No incidence list, owner function or native index is an operand of the\nfixed physical selector.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectOccurrences\nopen SemiprimeD1StackSourceIncidenceSelectMeaning\nnamespace O\nexport SemiprimeD1StackSourceOccurrencesOriginal (originalPairsFrom)\nend O\n/-- Generic ordered-factor row expansion, retaining repetitions and empty rows. -/\ntheorem pairsFrom_indexed (n F start:Nat) (es:List (Fin F)) (rows:Fin F→List (Fin n))\n    (h:es.map Fin.val=List.range' start es.length) :\n    O.originalPairsFrom n start (es.map rows)=\n      es.flatMap (fun e=>(rows e).map (fun v=>(Keys.numberKey v.val,Keys.numberKey (n+e.val)))) :=by\n  induction es generalizing start with\n  | nil=>rfl\n  | cons e es ih=>\n    change e.val::es.map Fin.val=start::List.range' (start+1) es.length at h\n    have he: e.val=start:=(List.cons.inj h).1\n    have ht:=ih (start+1) (List.cons.inj h).2\n    simp only [List.map_cons,O.originalPairsFrom,List.flatMap_cons,he,ht]\n/-- The original factor-major metadata stream is exactly the physically acquired row-key stream. -/\ntheorem original_keys_rows (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) :\n    originalKeys n F a arity owner=\n      O.originalPairsFrom n 0 ((List.finRange F).map\n        (fun e=>(List.finRange (arity e)).map (fun i=>owner ⟨e,i⟩))) :=by\n  rw [pairsFrom_indexed n F 0 _ _ (by simp only [List.map_coe_finRange,List.length_finRange,List.range_eq_range'])]\n  simp only [originalKeys,SemiprimeSourceHistogramMetadata.acquire,\n    SemiprimePaidFiniteEnumerationLists.flat_value,SemiprimeSourceHistogramMetadata.finFast_value,\n    SemiprimeSourceHistogramMetadata.ports_value,List.map_flatMap,List.map_map,Function.comp_def]\n/-- The same identity on the standard original finite row representation. -/\ntheorem original_keys_ofFn (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) :\n    originalKeys n F a arity owner=\n      O.originalPairsFrom n 0 (List.ofFn (fun e:Fin F=>List.ofFn (fun i:Fin (arity e)=>owner ⟨e,i⟩))) :=by\n  simpa only [List.ofFn_eq_map] using original_keys_rows n F a arity owner\n/-- On every actual network row list, the source keys are exactly the original incidence metadata keys. -/\ntheorem network_original_keys (net:SemiprimeD1TensorNetwork.Network) (a:Nat) :\n    originalKeys net.leftCount net.rows.length a (SemiprimeD1TensorNetwork.arity net.rows)\n      (SemiprimeD1TensorNetwork.owner net.rows)=O.originalPairsFrom net.leftCount 0 net.rows :=by\n  rw [original_keys_ofFn]\n  congr 1\n  have hinner:∀e:Fin net.rows.length,\n      List.ofFn (fun i:Fin (SemiprimeD1TensorNetwork.arity net.rows e)=>\n        SemiprimeD1TensorNetwork.owner net.rows ⟨e,i⟩)=net.rows[e.val] :=by\n    intro e\n    exact List.ofFn_getElem\n  simp only [hinner,List.ofFn_getElem]\n/-- Every physically acquired original endpoint lies in the exact owner-plus-factor variable range. -/\ntheorem original_key_ranges (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (row:List Bool×List Bool)\n    (hr:row∈originalKeys n F a arity owner) :\n    SemiprimeBitArithmetic.bitValue row.1 < n+F ∧ SemiprimeBitArithmetic.bitValue row.2 < n+F :=by\n  obtain ⟨i,_,rfl⟩:=List.mem_map.mp hr\n  simp only [Keys.numberKey_value]\n  have h0:=(owner i).isLt\n  have h1:=i.1.isLt\n  constructor <;> omega\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectOccurrences\n","RiemannGaussian.SemiprimeD1StackSourceOccurrencesOwners":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceOccurrencesOperations\n/-! # Whole actual inner binary-owner scan and ordered pair log\nEach real owner field is parsed, normalized by the real trim routine, framed\nwith the retained factor key and counted once. Parallel/repeated owners remain\nseparate emitted occurrences; all input/counter/factor caches survive.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceOccurrencesOwners\nopen SemiprimeD1StackSourceOccurrences SemiprimeD1StackSourceOccurrencesPrimitives\nopen SemiprimeD1StackSourceOccurrencesView SemiprimeD1StackSourceOccurrencesEncoding\nopen SemiprimeD1StackSourceOccurrencesOperations SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeD1StackNetworkOwnerIndexEncoding (pairBytes payload)\nlocal notation \"ctl\" => Label.local\n/-- Exact original ordered compact-owner/factor pairs for one actual physical inner row. -/\ndef rowPairs (words:List (List Bool)) (factor:List Bool) :List (List Bool×List Bool) :=\n  words.map (fun word=>(normal word,factor))\n/-- Conservative sum of the actual paid owner parse/trim/emission bounds plus the final false-tag pop. -/\ndef ownerBudget (factor:List Bool) (words:List (List Bool)) :Nat :=\n  (words.map (fun word=>100*(word.length+factor.length+1))).sum+1\n/-- One actual owner field goes through real parse/validation/trim/frame/reversal/count steps. -/\ntheorem owner_step (source number reader tail counter factor hist factors occurrences word:List Bool) :\n    ∃q≤100*(word.length+factor.length+1),Runs program q (ctl .ownerTag)\n      (data source number reader (true::frame word tail) [] [] counter [] factor hist factors occurrences)\n      (ctl .ownerTag) (data source number reader tail [] [] counter [] factor\n        ((pairBytes (normal word,factor)).reverse++hist) factors (true::occurrences)) :=by\n  let b0:=data source number reader (true::frame word tail) [] [] counter [] factor hist factors occurrences\n  let b1:=data source number reader (frame word tail) [] [] counter [] factor hist factors occurrences\n  let parsed:=data source number reader tail word [] counter [] factor hist factors occurrences\n  let normalized:=data source number reader tail [] [] counter (normal word) factor hist factors occurrences\n  have h0:Runs program 1 (ctl .ownerTag) b0 (ctl .ownerField) b1:=by\n    apply one_base program (ctl .ownerTag) (ctl .ownerField)\n      (.pop .row (ctl .abort) (ctl .clearFactor) (ctl .ownerField)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  have h1:=field_call .owner .ownerField .ownerValid rfl b1 word tail rfl rfl rfl rfl\n  have he1:Function.update (Function.update (Function.update b1 (fieldInput .owner) tail)\n      (fieldOutput .owner) word) .valid [true]=Function.update parsed .valid [true]:=by\n    funext k;cases k <;> simp [b1,parsed,fieldInput,fieldOutput,fieldStack,data,Function.update]\n  rw [he1] at h1\n  have h2:Runs program 1 (ctl .ownerValid) (Function.update parsed .valid [true]) (ctl (.normalizeReverse .owner)) parsed:=by\n    apply one_base program (ctl .ownerValid) (ctl (.normalizeReverse .owner))\n      (.pop .valid (ctl .abort) (ctl .abort) (ctl (.normalizeReverse .owner))) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  obtain ⟨a,ha,h3⟩:=normalize_run .owner parsed word rfl rfl rfl rfl rfl\n  have he3:Function.update (Function.update parsed .word []) (trimStack .owner .output) (normal word)=normalized:=by\n    dsimp only [parsed,normalized,trimStack]\n    rw [data_word,data_ownerKey]\n  rw [he3] at h3\n  have h4:=emit_pair normalized (normal word) factor hist occurrences rfl rfl rfl rfl rfl rfl\n  have he4:Function.update (emitAfter normalized (normal word) factor hist) .occurrences (true::occurrences)=\n      data source number reader tail [] [] counter [] factor ((pairBytes (normal word,factor)).reverse++hist)\n        factors (true::occurrences):=by\n    funext k;cases k <;> simp [emitAfter,normalized,data,Function.update]\n  rw [he4] at h4\n  have h:=join (join (join (join h0 h1) h2) h3) h4\n  refine ⟨1+(8*word.length+7)+1+a+(10*factor.length+11*(normal word).length+22),?_,h⟩\n  have hn:=normal_length word\n  omega\n/-- Whole actual inner row loop retains every occurrence in exact original order. -/\ntheorem owners_loop (source number reader counter factor hist factors occurrences:List Bool) (words:List (List Bool)) :\n    ∃q≤ownerBudget factor words,Runs program q (ctl .ownerTag)\n      (data source number reader (vectorBits words) [] [] counter [] factor hist factors occurrences)\n      (ctl .clearFactor) (data source number reader [] [] [] counter [] factor\n        ((payload (rowPairs words factor)).reverse++hist) factors (List.replicate words.length true++occurrences)) :=by\n  induction words generalizing hist occurrences with\n  | nil=>\n    refine ⟨1,by simp only [ownerBudget,List.map_nil,List.sum_nil,Nat.zero_add];omega,?_⟩\n    apply one_base program (ctl .ownerTag) (ctl .clearFactor)\n      (.pop .row (ctl .abort) (ctl .clearFactor) (ctl .ownerField)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  | cons word words ih=>\n    obtain ⟨a,ha,h0⟩:=owner_step source number reader (vectorBits words) counter factor hist factors occurrences word\n    obtain ⟨b,hb,h1⟩:=ih ((pairBytes (normal word,factor)).reverse++hist) (true::occurrences)\n    have hm:List.replicate words.length true++true::occurrences=List.replicate (words.length+1) true++occurrences:=by\n      calc\n        _=(List.replicate words.length true++List.replicate 1 true)++occurrences:=by\n          simp only [List.replicate_succ,List.replicate_zero,List.append_assoc,List.singleton_append]\n        _= _:=by rw [←List.replicate_add]\n    rw [hm] at h1\n    refine ⟨a+b,?_,?_⟩\n    · simp only [ownerBudget,List.map_cons,List.sum_cons] at hb ⊢\n      omega\n    · have h:=join h0 h1\n      rw [show vectorBits (word::words)=true::frame word (vectorBits words) from rfl]\n      simpa only [rowPairs,List.map_cons,payload,List.foldr_cons,List.reverse_append,List.append_assoc,List.length_cons] using h\n/-- Exact sum of actual owner-field and retained factor-key widths. -/\ntheorem ownerBudget_eq (factor:List Bool) (words:List (List Bool)) :\n    ownerBudget factor words=100*(words.map List.length).sum+100*factor.length*words.length+100*words.length+1 :=by\n  induction words with\n  | nil=>simp only [ownerBudget,List.map_nil,List.sum_nil,List.length_nil,Nat.mul_zero,Nat.zero_add]\n  | cons word words ih=>\n    have hc:ownerBudget factor (word::words)=100*(word.length+factor.length+1)+ownerBudget factor words:=by\n      simp only [ownerBudget,List.map_cons,List.sum_cons]\n      omega\n    rw [hc,ih]\n    simp only [List.map_cons,List.sum_cons,List.length_cons]\n    ring\n/-- The whole inner scan is paid by the actual physical row bytes and actual retained factor-key width. -/\ntheorem ownerBudget_le (factor:List Bool) (words:List (List Bool)) :\n    ownerBudget factor words≤1000*(factor.length+1)*(vectorBits words).length :=by\n  have hl:=SemiprimeD1StackNetworkRowsEncoding.vector_length words\n  have hn:words.length≤(vectorBits words).length:=by omega\n  have hb:(words.map List.length).sum≤(vectorBits words).length:=by omega\n  have hz:1≤(vectorBits words).length:=by omega\n  have hp:100*factor.length*words.length≤100*factor.length*(vectorBits words).length:=by gcongr\n  have he:1000*(factor.length+1)*(vectorBits words).length=\n      1000*(factor.length*(vectorBits words).length)+1000*(vectorBits words).length:=by ring\n  rw [ownerBudget_eq,he]\n  simp only [Nat.mul_assoc] at hp ⊢\n  omega\nend RiemannGaussian.SemiprimeD1StackSourceOccurrencesOwners\n","RiemannGaussian.SemiprimeD1StackSourcePacketPaddingSetup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourcePacketPaddingEncoding\nimport RiemannGaussian.SemiprimeD1StackSourcePacketPaddingCalls\n/-! # Two actual exponent copies and the physically acquired maximum copy -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourcePacketPaddingSetup\nopen SemiprimeD1StackSourcePacketPadding SemiprimeD1StackSourcePacketPaddingEncoding\nopen SemiprimeD1StackSourcePacketPaddingPrimitives SemiprimeD1StackSourcePacketPaddingCalls\nopen SemiprimeD1StackProcedureTrace\n/-- The paid copies, including actual source restoration and returns, precede every low-bit scan. -/\ndef setupTime (a:Nat) (bits:List Bool) :Nat:=10*a+5*bits.length+12\n/-- All exponent and maximum bytes come from retained actual source words, never from an advised a/maximum cache. -/\ntheorem setup_run (src:List Bool) (s:FE.Summary) (a:Nat) :\n    Runs program (setupTime a s.maximum) .copyCut (bank (readyWords src s a)) (.cut false)\n      (bank {readyWords src s a with cutTodo:=List.replicate a true,prefixTodo:=List.replicate a true,frequency:={ (readyWords src s a).frequency with oldCount:=s.maximum}}) :=by\n  let w0:=readyWords src s a\n  let w1:Words:={w0 with cutTodo:=List.replicate a true}\n  let w2:Words:={w1 with prefixTodo:=List.replicate a true}\n  let w3:Words:={w2 with frequency:={w2.frequency with oldCount:=s.maximum}}\n  have h0:=copy_call .cut .copyCut .copyPrefix rfl (bank w0) (List.replicate a true) [] rfl rfl rfl\n  change Runs program (5*(List.replicate a true).length+4) .copyCut (bank w0) .copyPrefix\n    (Function.update (bank w0) (aux .cutTodo) (List.replicate a true++[])) at h0\n  rw [List.append_nil,update_cutTodo,List.length_replicate] at h0\n  have h1:=copy_call .prefix .copyPrefix .copyMaximum rfl (bank w1) (List.replicate a true) [] rfl rfl rfl\n  change Runs program (5*(List.replicate a true).length+4) .copyPrefix (bank w1) .copyMaximum\n    (Function.update (bank w1) (aux .prefixTodo) (List.replicate a true++[])) at h1\n  rw [List.append_nil,update_prefixTodo,List.length_replicate] at h1\n  have h2:=copy_call .maximum .copyMaximum (.cut false) rfl (bank w2) s.maximum [] rfl rfl rfl\n  change Runs program (5*s.maximum.length+4) .copyMaximum (bank w2) (.cut false)\n    (Function.update (bank w2) (frequencyStack F.oldCount) (s.maximum++[])) at h2\n  rw [List.append_nil,update_oldCount] at h2\n  have h:=join (join h0 h1) h2\n  convert h using 1; unfold setupTime;omega\nend RiemannGaussian.SemiprimeD1StackSourcePacketPaddingSetup\n","RiemannGaussian.SemiprimeD1StackStaticWordTableDFSParts":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableSpec\n/-! # Literal product-table DFS transitions preserving exact local-port order -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackStaticWordTableDFSParts\nopen SemiprimeD1StackStaticWordTable SemiprimeD1StackStaticWordTableSpec SemiprimeD1StackProcedureTrace\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Actual depth EOF enters the real leaf checker procedure. -/\ntheorem visit_zero (original : K→List Bool) (bank front hist : List Bool) :\n    Runs (program s) 1 .visit (data original bank 0 front hist) .leaf (data original bank 0 front hist) := by\n  apply one_base (program s) .visit .leaf (.pop (counter .count) .leaf .fork .fork) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- One actual acquired depth marker is popped at an internal node. -/\ntheorem visit_succ (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .visit (data original bank (n+1) front hist) .fork (data original bank n front hist) := by\n  apply one_base (program s) .visit .fork (.pop (counter .count) .leaf .fork .fork) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- The physical old-codec fork tag is written before either child. -/\ntheorem fork_push (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .fork (data original bank n front hist) .low (data original bank n front (true::hist)) := by\n  apply one_base (program s) .fork .low (.push (aux .reversed) true .low) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- FALSE is physically prepended to the reverse-prefix before the first child. -/\ntheorem low_push (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .low (data original bank n front hist) .high (data original bank n (false::front) hist) := by\n  apply one_base (program s) .low .high (.push (aux .prefix) false .high) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- The first child's physical prefix bit is consumed after its real return. -/\ntheorem low_pop (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .afterLow (data original bank n (false::front) hist) .setHigh (data original bank n front hist) := by\n  apply one_base (program s) .afterLow .setHigh (.pop (aux .prefix) .bad .setHigh .setHigh) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- TRUE is physically prepended before the second child, in old table order. -/\ntheorem high_push (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .setHigh (data original bank n front hist) .afterHigh (data original bank n (true::front) hist) := by\n  apply one_base (program s) .setHigh .afterHigh (.push (aux .prefix) true .afterHigh) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- The second child's actual prefix bit is popped after its real return. -/\ntheorem high_pop (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .restore (data original bank n (true::front) hist) .returnDone (data original bank n front hist) := by\n  apply one_base (program s) .restore .returnDone (.pop (aux .prefix) .bad .returnDone .returnDone) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- The original acquired depth marker is physically restored before return. -/\ntheorem depth_restore (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .returnDone (data original bank n front hist) .leafReturn (data original bank (n+1) front hist) := by\n  apply one_base (program s) .returnDone .leafReturn (.push (counter .count) true .leafReturn) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackStaticWordTableDFSParts\n","RiemannGaussian.SemiprimeD1StackVectorTableDFSParts":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVectorTableSpec\n/-! # Literal product-table DFS transitions preserving exact local-port order -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackVectorTableDFSParts\nopen SemiprimeD1StackVectorTable SemiprimeD1StackVectorTableSpec SemiprimeD1StackProcedureTrace\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Actual depth EOF enters the real leaf checker procedure. -/\ntheorem visit_zero (original : K→List Bool) (bank front hist : List Bool) :\n    Runs (program s) 1 .visit (data original bank 0 front hist) .leaf (data original bank 0 front hist) := by\n  apply one_base (program s) .visit .leaf (.pop (counter .count) .leaf .fork .fork) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- One actual acquired depth marker is popped at an internal node. -/\ntheorem visit_succ (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .visit (data original bank (n+1) front hist) .fork (data original bank n front hist) := by\n  apply one_base (program s) .visit .fork (.pop (counter .count) .leaf .fork .fork) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- The physical old-codec fork tag is written before either child. -/\ntheorem fork_push (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .fork (data original bank n front hist) .low (data original bank n front (true::hist)) := by\n  apply one_base (program s) .fork .low (.push (aux .reversed) true .low) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- FALSE is physically prepended to the reverse-prefix before the first child. -/\ntheorem low_push (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .low (data original bank n front hist) .high (data original bank n (false::front) hist) := by\n  apply one_base (program s) .low .high (.push (aux .prefix) false .high) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- The first child's physical prefix bit is consumed after its real return. -/\ntheorem low_pop (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .afterLow (data original bank n (false::front) hist) .setHigh (data original bank n front hist) := by\n  apply one_base (program s) .afterLow .setHigh (.pop (aux .prefix) .bad .setHigh .setHigh) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- TRUE is physically prepended before the second child, in old table order. -/\ntheorem high_push (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .setHigh (data original bank n front hist) .afterHigh (data original bank n (true::front) hist) := by\n  apply one_base (program s) .setHigh .afterHigh (.push (aux .prefix) true .afterHigh) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- The second child's actual prefix bit is popped after its real return. -/\ntheorem high_pop (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .restore (data original bank n (true::front) hist) .returnDone (data original bank n front hist) := by\n  apply one_base (program s) .restore .returnDone (.pop (aux .prefix) .bad .returnDone .returnDone) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n/-- The original acquired depth marker is physically restored before return. -/\ntheorem depth_restore (original : K→List Bool) (bank : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs (program s) 1 .returnDone (data original bank n front hist) .leafReturn (data original bank (n+1) front hist) := by\n  apply one_base (program s) .returnDone .leafReturn (.push (counter .count) true .leafReturn) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackVectorTableDFSParts\n","RiemannGaussian.SemiprimeD1StackVectorTableLeafCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVectorTableLoad\nimport RiemannGaussian.SemiprimeD1StackVectorTableEmit\n/-! # Every actual static checker leaf copy, reversal and real call -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackVectorTableLeafCalls\nopen SemiprimeD1StackVectorTable SemiprimeD1StackVectorTableSpec\nopen SemiprimeD1StackVectorTablePrimitives SemiprimeD1StackVectorTableCleanup\nopen SemiprimeD1StackVectorTableLoad SemiprimeD1StackVectorTableEmit\nopen SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Updating one real checker role commutes with the complete caller-bank view. -/\ntheorem withChecker_update (base : Stack K→List Bool) (live : K→List Bool) (key : K) (word : List Bool) :\n    Function.update (withChecker base live) (checker key) word=\n      withChecker base (Function.update live key word) := by\n  funext k\n  cases k with\n  | inl k=>\n    by_cases h:k=key\n    · subst k\n      change Function.update (withChecker base live) (Sum.inl key) word (Sum.inl key)=\n        Function.update live key word key\n      rw [Function.update_self,Function.update_self]\n    · have hn:(Sum.inl k : Stack K)≠checker key:=by intro he;exact h (Sum.inl.inj he)\n      rw [Function.update_of_ne hn]\n      change live k=Function.update live key word k\n      rw [Function.update_of_ne h]\n  | inr k=>rw [Function.update_of_ne (by intro h;cases h)];rfl\n/-- A literal full-bank load enters every physical original input field. -/\ntheorem load_call [Fintype K] (original : K→List Bool) (bank front hist : List Bool) :\n    ∃t≤ s.roles.length*(6*inputBytes original+5)+2,Runs (program s) t .leaf\n      (data original bank 0 front hist) .prefixCopy (loadedData original bank front hist) := by\n  obtain ⟨t,ht,hr⟩:=load_returns s (data original bank 0 front hist) rfl\n  have h:=SemiprimeD1StackProcedureReturns.call (program s) t .leaf (.load 0) .prefixCopy _ _ rfl hr\n  have he:loaded (data original bank 0 front hist)=loadedData original bank front hist:=by\n    funext k;cases k <;> rfl\n  rw [he] at h\n  refine ⟨1+t,?_,h⟩\n  have hi:inventory (data original bank 0 front hist)=0 := by simp [inventory,data,store,checker]\n  have hT:templateInventory (data original bank 0 front hist)=inputBytes original := rfl\n  unfold loadUnit at ht\n  rw [hi,hT] at ht\n  simp only [Nat.zero_add] at ht\n  omega\n/-- Current reverse-prefix copying retains the actual prefix and original template. -/\ntheorem copy_prefix (original : K→List Bool) (bank front hist : List Bool) :\n    Runs (program s) (5*front.length+4) .prefixCopy (loadedData original bank front hist) .reversePrefix\n      (Function.update (loadedData original bank front hist) (aux .work) front) :=\n  copy_call s none .prefixCopy .reversePrefix rfl (loadedData original bank front hist) rfl rfl\n/-- The real consuming reversal supplies the raw operand directly; the template\nraw field is empty, as proved by each concrete original-input client. -/\ntheorem reverse_prefix (original : K→List Bool) (hraw : original s.raw=[])\n    (bank front hist : List Bool) :\n    Runs (program s) (2*front.length+3) .reversePrefix\n      (Function.update (loadedData original bank front hist) (aux .work) front) .check\n      (withChecker (data original bank 0 front hist) (Function.update original s.raw front.reverse)) := by\n  let d:=loadedData original bank front hist\n  have hr:=reverse_call s false .reversePrefix .check rfl (Function.update d (aux .work) front)\n  have h0:(Function.update d (aux .work) front) (reverseStack s false 0)=front :=\n    Function.update_self _ _ _\n  have h1:(Function.update d (aux .work) front) (reverseStack s false 1)=[] := by\n    change Function.update d (aux .work) front (checker s.raw)=[]\n    rw [Function.update_of_ne (by intro h;cases h)]\n    exact hraw\n  rw [h0,h1,List.append_nil] at hr\n  have he:Function.update (Function.update (Function.update d (aux .work) front) (aux .work) [])\n      (checker s.raw) front.reverse=Function.update d (checker s.raw) front.reverse := by\n    funext k\n    by_cases hc:k=checker s.raw\n    · subst k;rw [Function.update_self,Function.update_self]\n    · rw [Function.update_of_ne hc,Function.update_of_ne hc]\n      by_cases hw:k=aux .work\n      · subst k;rw [Function.update_self];rfl\n      · rw [Function.update_of_ne hw,Function.update_of_ne hw]\n  change Runs (program s) (2*front.length+3) .reversePrefix (Function.update d (aux .work) front) .check\n    (Function.update (Function.update (Function.update d (aux .work) front) (aux .work) [])\n      (checker s.raw) front.reverse) at hr\n  have hd:Function.update d (checker s.raw) front.reverse=\n      withChecker (data original bank 0 front hist) (Function.update original s.raw front.reverse):=\n    withChecker_update (data original bank 0 front hist) original s.raw front.reverse\n  rw [he,hd] at hr\n  exact hr\n/-- A concrete proved checker trace is included as a REAL call; its original\nprogram executes, rather than a predicate/callback/evaluator opcode. -/\ntheorem checker_call (original : K→List Bool) (answer : List Bool→List (List Bool)) (budget : Nat→Nat)\n    (hc : CheckerTrace s original answer budget) (bank front hist : List Bool) :\n    ∃t≤ budget front.length,∃finish:C.State K L,\n      C.run s.code t (checkerInitial s original front.reverse)=some finish ∧\n      finish.data s.output=SemiprimeD1TensorTapeCodec.vectorBits (answer front.reverse) ∧\n      Runs (program s) (t+1) .check\n        (withChecker (data original bank 0 front hist) (Function.update original s.raw front.reverse)) .emitSentinel\n        (withChecker (data original bank 0 front hist) finish.data) := by\n  obtain ⟨t,ht,finish,hpc,hframes,hr,hvalue⟩:=hc front.reverse\n  refine ⟨t,by simpa only [List.length_reverse] using ht,finish,hr,hvalue,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call (program s) checker _root_.RiemannGaussian.SemiprimeD1StackStaticWordTable.Label.checker\n    Sum.inl_injective s.code s.entry (fun _=>rfl) .check .emitSentinel rfl t\n    (checkerInitial s original front.reverse) finish\n  · rfl\n  · rfl\n  · exact hpc\n  · exact hframes\n  · exact hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k=>exact (hk k rfl).elim\n      | inr k=>rfl\nend RiemannGaussian.SemiprimeD1StackVectorTableLeafCalls\n","RiemannGaussian.SemiprimeD1StackVectorTableSpec":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVectorTable\n/-! # Proof-only actual checker trace contract and whole table specification\nNo definition in this module is an operand of the compiler program. Concrete\nclients prove the contract from their already kernel-checked literal checker.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVectorTableSpec\nopen SemiprimeD1StackVectorTable\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Exact ordinary checker initialization, after actual physical template copy\nand assignment reversal. It is a theorem-side state view only. -/\ndef checkerInitial (original : K→List Bool) (raw : List Bool) : C.State K L :=\n  ⟨some s.entry,none,none,Function.update original s.raw raw,[]⟩\n/-- A PROVED actual trace of the fixed checker, for every raw word. The budget\nand postcondition are proof arguments; neither is carried in runtime state. -/\ndef CheckerTrace (original : K→List Bool) (answer : List Bool→List (List Bool)) (budget : Nat→Nat) : Prop :=\n  ∀raw,∃t≤ budget raw.length,∃finish:C.State K L,\n    finish.pc=none ∧ finish.frames=[] ∧\n    C.run s.code t (checkerInitial s original raw)=some finish ∧ finish.data s.output=SemiprimeD1TensorTapeCodec.vectorBits (answer raw)\n/-- All actual original-template input bytes, including empty private fields. -/\ndef inputBytes [Fintype K] (original : K→List Bool) : Nat :=∑k:K,(original k).length\n/-- The exact full coefficient vector returned by the fixed physical source. -/\ndef leafWords (answer : List Bool→List (List Bool)) (raw : List Bool) : List (List Bool) :=\n  answer raw\n/-- Exact original false-first/first-port-outermost tree; a specification only. -/\ndef tree (answer : List Bool→List (List Bool)) (front : List Bool) : (n : Nat)→SemiprimeD1TensorTables.Table n\n  | 0=>.leaf (leafWords answer front)\n  | n+1=>.fork (tree answer (front++[false]) n) (tree answer (front++[true]) n)\n/-- Proof view of replacing the actual checker bank, leaving all other cells alone. -/\ndef withChecker (base : Stack K→List Bool) (live : K→List Bool) : Stack K→List Bool :=\n  Sum.elim live (fun k=>base (.inr k))\n/-- Actual whole template copy retains every template, scanner and caller byte. -/\ndef loadedData (original : K→List Bool) (bank front hist : List Bool) : Stack K→List Bool :=\n  withChecker (data original bank 0 front hist) original\n/-- Every ordinary checker input field is paid by actual original and raw bytes. -/\ntheorem initial_cell_le [Fintype K] (original : K→List Bool) (raw : List Bool) (k : K) :\n    ((checkerInitial s original raw).data k).length≤ inputBytes original+raw.length := by\n  by_cases h:k=s.raw\n  · subst k\n    change (Function.update original s.raw raw s.raw).length≤_\n    rw [Function.update_self]\n    omega\n  · change (Function.update original s.raw raw k).length≤_\n    rw [Function.update_of_ne h]\n    have hs:(original k).length≤∑j:K,(original j).length:=\n      Finset.single_le_sum (f:=fun j:K=>(original j).length) (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\n    unfold inputBytes\n    omega\n/-- Every actual checker output field has its own executed-step byte bound. -/\ntheorem output_cell_le [Fintype K] (original : K→List Bool) (raw : List Bool)\n    (t : Nat) (finish : C.State K L)\n    (hr : C.run s.code t (checkerInitial s original raw)=some finish) (k : K) :\n    (finish.data k).length≤ inputBytes original+raw.length+t :=\n  SemiprimeD1StackReturnLink.run_data_bound s.code t (inputBytes original+raw.length)\n    _ finish (initial_cell_le s original raw) hr k\n/-- The generic tree visits every finite assignment in its original local order. -/\ntheorem tree_entry (answer : List Bool→List (List Bool)) (front : List Bool) (n : Nat) (input : Fin n→Bool) :\n    SemiprimeD1TensorTables.valueAt (tree answer front n) input=leafWords answer (front++List.ofFn input) := by\n  induction n generalizing front with\n  | zero=>simp only [tree,SemiprimeD1TensorTables.valueAt,List.ofFn_zero,List.append_nil]\n  | succ n ih=>\n    cases h:input 0\n    · simp only [tree,SemiprimeD1TensorTables.valueAt,h,Bool.false_eq_true,ite_false]\n      simpa only [List.ofFn_succ,h,List.append_assoc,List.singleton_append] using\n        ih (front++[false]) (fun j=>input j.succ)\n    · simp only [tree,SemiprimeD1TensorTables.valueAt,h,ite_true]\n      simpa only [List.ofFn_succ,h,List.append_assoc,List.singleton_append] using\n        ih (front++[true]) (fun j=>input j.succ)\nend RiemannGaussian.SemiprimeD1StackVectorTableSpec\n","RiemannGaussian.SemiprimeD1StackVertexArityRecipes":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexArityStatic\nimport RiemannGaussian.SemiprimeD1StackVertexArityArithmetic\nimport RiemannGaussian.SemiprimeD1StackVertexArityDecode\n\n/-! # Every actual original arity recipe, with uniform quadratic execution bound -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 8192\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVertexArityRecipes\nopen SemiprimeD1StackVertexArity SemiprimeD1StackVertexArityView\nopen SemiprimeD1StackVertexArityStatic SemiprimeD1StackVertexArityArithmetic SemiprimeD1StackVertexArityDecode\nopen SemiprimeD1StackProcedureFragments (Runs)\nopen SemiprimeD1StackUnaryDivmod (unary)\n\n/-- Mathematical value of the actual static recipe; not an executable graph-arity supplier. -/\ndef value (code:Fin 18) (index radius first second digits:ℕ) : ℕ :=\n  if code.val=0 then radius+(if index<digits then 1 else 0)\n  else if code.val=1 then second*radius+second*radius\n  else if code.val=2 then radius+radius\n  else if code.val=3 then first*radius+first*radius\n  else if code.val=4 then radius+(radius+radius)\n  else if code.val=5 then radius\n  else if code.val=6 then radius+(radius+radius)\n  else if code.val=7 then radius\n  else if code.val=8 then 3\n  else if code.val=9 then 1 else 2\n/-- Actual source-counter size parameter, kept separate from logical graph scope. -/\ndef dimensionSum (index radius first second digits:ℕ) : ℕ := index+radius+first+second+digits+1\n/-- One fixed quadratic recipe envelope in actual unary metadata lengths. -/\ndef recipeBudget (index radius first second digits:ℕ) : ℕ := 100*(dimensionSum index radius first second digits)^2+100\n\n/-- Pure scalar product substitution; no executable term is unfolded here. -/\ntheorem product_budget_le (axis radius S:ℕ) (ha:axis≤S) (hr:radius≤S) :\n    productBudget axis radius≤100*S^2+100 := by\n  have hm:(axis+axis)*(2*radius+3)≤(S+S)*(2*S+3):=Nat.mul_le_mul (by omega) (by omega)\n  unfold productBudget\n  nlinarith\n/-- Pure scalar comparison/copy substitution. -/\ntheorem input_budget_le (index radius digits S:ℕ) (hi:index≤S) (hr:radius≤S) (hd:digits≤S) (hp:1≤S) :\n    inputBudget index radius digits≤100*S^2+100 := by\n  have hs:S≤S^2:=by nlinarith\n  unfold inputBudget\n  omega\n/-- Three readonly-source copies dominate every radius-only recipe. -/\ntheorem radius_budget_le (radius S:ℕ) (hr:radius≤S) (hp:1≤S) : 15*radius+12≤100*S^2+100 := by\n  have hs:S≤S^2:=by nlinarith\n  omega\n/-- All eighteen recipes execute actual instructions and return the original-value tally. -/\ntheorem recipe_run (code:Fin 18) (index radius first second digits:ℕ) :\n    ∃time≤recipeBudget index radius first second digits,Runs program time (recipe code)\n      (store (header code.val index radius first second digits) [] [] [] [] [] []) (.inl .halt)\n      (store (header code.val index radius first second digits) (unary (value code index radius first second digits)) [] [] [] [] []) := by\n  let S:=dimensionSum index radius first second digits\n  have hi:index≤S:=by dsimp [S,dimensionSum];omega\n  have hr:radius≤S:=by dsimp [S,dimensionSum];omega\n  have hf:first≤S:=by dsimp [S,dimensionSum];omega\n  have hs:second≤S:=by dsimp [S,dimensionSum];omega\n  have hd:digits≤S:=by dsimp [S,dimensionSum];omega\n  have hp:1≤S:=by dsimp [S,dimensionSum];omega\n  have hbI:inputBudget index radius digits≤recipeBudget index radius first second digits:=input_budget_le _ _ _ S hi hr hd hp\n  have hbF:productBudget first radius≤recipeBudget index radius first second digits:=product_budget_le _ _ S hf hr\n  have hbS:productBudget second radius≤recipeBudget index radius first second digits:=product_budget_le _ _ S hs hr\n  have hbR:15*radius+12≤recipeBudget index radius first second digits:=radius_budget_le _ S hr hp\n  have hbL:3≤recipeBudget index radius first second digits:=by unfold recipeBudget;omega\n  fin_cases code\n  · obtain ⟨time,ht,he⟩:=input_run 0 index radius first second digits\n    exact ⟨time,ht.trans hbI,he⟩\n  · obtain ⟨time,ht,he⟩:=axis_run false 1 index radius first second digits\n    exact ⟨time,ht.trans hbS,he⟩\n  · exact ⟨10*radius+8,by omega,radius_two 2 index radius first second digits⟩\n  · obtain ⟨time,ht,he⟩:=axis_run true 3 index radius first second digits\n    exact ⟨time,ht.trans hbF,he⟩\n  · exact ⟨15*radius+12,hbR,radius_three 4 index radius first second digits⟩\n  · exact ⟨5*radius+4,by omega,radius_one 5 index radius first second digits⟩\n  · exact ⟨15*radius+12,hbR,radius_three 6 index radius first second digits⟩\n  · exact ⟨5*radius+4,by omega,radius_one 7 index radius first second digits⟩\n  · exact ⟨3,hbL,literal_three _ []⟩\n  · exact ⟨1,by omega,literal_one _ []⟩\n  all_goals exact ⟨2,by omega,literal_two _ []⟩\n\n/-- Whole actual copy/decode/recipe trace, before the caller's final halt instruction. -/\ntheorem ready (code:Fin 18) (index radius first second digits:ℕ) :\n    ∃time≤recipeBudget index radius first second digits+107,Runs program time (.inl .main)\n      (store (header code.val index radius first second digits) [] [] [] [] [] []) (.inl .halt)\n      (store (header code.val index radius first second digits) (unary (value code index radius first second digits)) [] [] [] [] []) := by\n  have h0:=tag_run code index radius first second digits\n  obtain ⟨time,ht,h1⟩:=recipe_run code index radius first second digits\n  refine ⟨(6*code.val+5)+time,?_,h0.trans h1⟩\n  have hc:=code.isLt\n  omega\nend RiemannGaussian.SemiprimeD1StackVertexArityRecipes\n","RiemannGaussian.SemiprimeD1StackVertexArityView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexArityComponents\n\n/-! # Physical arity source and working stores -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 8192\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVertexArityView\nopen SemiprimeD1StackVertexArity SemiprimeD1StackVertexArityComponents\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\nopen SemiprimeD1StackUnaryDivmod (unary)\n\n/-- Literal source-counter representation, later tied to the original-N cache. -/\ndef header (tag index radius first second digits:ℕ) : Source→List Bool\n  | .tag => unary tag\n  | .index => unary index\n  | .radiusSucc => unary radius\n  | .firstAxis => unary first\n  | .secondAxis => unary second\n  | .digits => unary digits\n/-- Exact physical words at all procedure boundaries; scratch and compare-left are empty. -/\ndef work (arity tag multiplier right limit result:List Bool) : Aux→List Bool\n  | .arity => arity\n  | .tagReader => tag\n  | .multiplier => multiplier\n  | .compareRight => right\n  | .compareLimit => limit\n  | .compareResult => result\n  | _ => []\n/-- The complete physical fifteen-stack boundary store. -/\ndef store (h:Source→List Bool) (arity tag multiplier right limit result:List Bool) : Stack→List Bool :=\n  data h (work arity tag multiplier right limit result)\n/-- Actual writes do not change any source metadata word. -/\ntheorem update_aux (h:Source→List Bool) (w:Aux→List Bool) (key:Aux) (word:List Bool) :\n    Function.update (data h w) (aux key) word=data h (Function.update w key word) := by\n  funext k\n  rcases k with k|k\n  · simp [data,aux,Function.update]\n  · by_cases hk:k=key\n    · subst k;simp [data,aux,Function.update]\n    · simp [data,aux,Function.update,hk]\n/-- Physical arity update preserves the other working words. -/\ntheorem work_arity (arity tag multiplier right limit result word:List Bool) :\n    Function.update (work arity tag multiplier right limit result) Aux.arity word=work word tag multiplier right limit result := by\n  funext k\n  cases k <;> rfl\n/-- Physical tagReader update preserves the other working words. -/\ntheorem work_tagReader (arity tag multiplier right limit result word:List Bool) :\n    Function.update (work arity tag multiplier right limit result) Aux.tagReader word=work arity word multiplier right limit result := by\n  funext k\n  cases k <;> rfl\n/-- Physical multiplier update preserves the other working words. -/\ntheorem work_multiplier (arity tag multiplier right limit result word:List Bool) :\n    Function.update (work arity tag multiplier right limit result) Aux.multiplier word=work arity tag word right limit result := by\n  funext k\n  cases k <;> rfl\n/-- Physical compareRight update preserves the other working words. -/\ntheorem work_compareRight (arity tag multiplier right limit result word:List Bool) :\n    Function.update (work arity tag multiplier right limit result) Aux.compareRight word=work arity tag multiplier word limit result := by\n  funext k\n  cases k <;> rfl\n/-- Physical compareLimit update preserves the other working words. -/\ntheorem work_compareLimit (arity tag multiplier right limit result word:List Bool) :\n    Function.update (work arity tag multiplier right limit result) Aux.compareLimit word=work arity tag multiplier right word result := by\n  funext k\n  cases k <;> rfl\n/-- Physical compareResult update preserves the other working words. -/\ntheorem work_compareResult (arity tag multiplier right limit result word:List Bool) :\n    Function.update (work arity tag multiplier right limit result) Aux.compareResult word=work arity tag multiplier right limit word := by\n  funext k\n  cases k <;> rfl\n/-- A literal global push, including its actual data-cell allocation. -/\ntheorem push_run (pc next:Label) (stack:Stack) (bit:Bool) (data:Stack→List Bool)\n    (hc:program pc=.base (.push stack bit next)) :\n    Runs program 1 pc data next (Function.update data stack (bit::data stack)) := by\n  exact one_base program pc next (.push stack bit next) data _ hc rfl rfl\n\n/-- A literal global pop with one continuation, including actual EOF. -/\ntheorem pop_run (pc next:Label) (stack:Stack) (data:Stack→List Bool)\n    (hc:program pc=.base (.pop stack next next next)) :\n    Runs program 1 pc data next (Function.update data stack (data stack).tail) := by\n  apply one_base program pc next (.pop stack next next next) data _ hc\n  · cases h:(data stack).head? with\n    | none => simp [B.execute,SemiprimeD1StackBytecode.choose,h]\n    | some bit => cases bit <;> simp [B.execute,SemiprimeD1StackBytecode.choose,h]\n  · rfl\n\n/-- Every old limit byte is physically cleared; no stale field is discarded for free. -/\ntheorem clear_run (word:List Bool) (pc next:Label) (stack:Stack) (data:Stack→List Bool)\n    (hw:data stack=word) (hc:program pc=.base (.pop stack next pc pc)) :\n    Runs program (word.length+1) pc data next (Function.update data stack []) := by\n  induction word generalizing data with\n  | nil =>\n    apply one_base program pc next (.pop stack next pc pc) data _ hc\n    · simp [B.execute,SemiprimeD1StackBytecode.choose,hw]\n    · change Function.update data stack (data stack).tail=_\n      rw [hw,List.tail_nil]\n  | cons bit word ih =>\n    have h0:Runs program 1 pc data pc (Function.update data stack word):=by\n      apply one_base program pc pc (.pop stack next pc pc) data _ hc\n      · cases bit <;> simp [B.execute,SemiprimeD1StackBytecode.choose,hw]\n      · change Function.update data stack (data stack).tail=_\n        rw [hw,List.tail_cons]\n    have h1:=ih (Function.update data stack word) (Function.update_self _ _ _)\n    have h:=h0.trans h1\n    rw [Function.update_idem] at h\n    simpa only [List.length_cons,show 1+(word.length+1)=word.length+1+1 by omega] using h\nend RiemannGaussian.SemiprimeD1StackVertexArityView\n","RiemannGaussian.SemiprimeD1StackVertexCatalogueBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexCatalogueExecution\n\n/-! # Actual complete vertex-catalogue resource bounds\nAll cache sizes below come from the executed original-input acquisition.\nPorts, edge identifiers and checkers are separate subsequent stages.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 4096\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVertexCatalogueBounds\nopen SemiprimeD1StackVertexCatalogue SemiprimeD1StackVertexCatalogueExecution\nopen SemiprimeD1StackVertexCatalogueCaches SemiprimeD1StackVertexCatalogueTags\nopen SemiprimeMacroParameters\n\n/-- Actual retained digit bytes are bounded by the proved executed source storage. -/\ntheorem cache_bytes (bits:List Bool) (hb:bits≠[]) :\n    (SemiprimeD1TensorTapeCodec.vectorBits (SemiprimeD1StackDigitCountBounds.originalWords bits)).length≤\n      24000000*(bits.length+1)^2 := by\n  obtain ⟨time,_,hr⟩:=SemiprimeD1BinaryPublicAcquisitionExecution.source_run bits hb\n  have hs:=SemiprimeD1BinaryPublicAcquisitionBounds.prefix_cells bits hb time _ hr\n  have hk:=Finset.single_le_sum (fun k (_:k∈(Finset.univ:Finset SemiprimeD1BinaryPublicAcquisition.Stack))=>\n    Nat.zero_le ((SemiprimeD1BinaryPublicAcquisitionComponents.result bits k).length))\n    (Finset.mem_univ SemiprimeD1StackDigitCountBounds.bankRole)\n  change (SemiprimeD1BinaryPublicAcquisitionComponents.result bits SemiprimeD1StackDigitCountBounds.bankRole).length≤_\n  exact hk.trans (by simpa using hs)\n\n/-- Pure arithmetic substitution, isolated from executable configurations. -/\ntheorem numeric_budget (n R d bytes:ℕ) (hR:R≤64*n+1) (hd:d≤R)\n    (hb:bytes≤24000000*(n+1)^2) :\n    1+(800000*(n+1)^2+1)+(11*bytes+5+1)+(5*R+5*d+16)+18+\n      18*(24*(64*n+3)+43*(64*n+21)^5+22)+1≤10000000000000*(n+1)^5 := by\n  have hp:(64*n+21)^5≤4437053125*(n+1)^5 := by\n    calc\n      _≤(85*(n+1))^5:=Nat.pow_le_pow_left (by omega) 5\n      _= _:=by rw [mul_pow];norm_num\n  have h2:(n+1)^2≤(n+1)^5:=Nat.pow_le_pow_right (by omega) (by omega)\n  have hn:n≤(n+1)^5:=by\n    have h1:n+1≤(n+1)^5:=by simpa using (Nat.pow_le_pow_right (by omega : 1≤n+1) (by omega : 1≤5))\n    omega\n  have hpos:1≤(n+1)^5:=by\n    have h:(0:ℕ)<(n+1)^5:=by positivity\n    omega\n  omega\n\n/-- Fixed polynomial bound for the WHOLE actually executed original-input producer. -/\ntheorem budget_le (bits:List Bool) (hb:bits≠[]) : budget bits≤10000000000000*(bits.length+1)^5 := by\n  have hr:transformLength bits.length≤64*bits.length+1:=\n    (SemiprimeD1StackTransformArithmetic.prefix_powers bits.length (transformExponent bits.length) (le_refl _)).1\n  have hd:digitCountValue bits≤transformLength bits.length:=by\n    rw [digitCount_raw bits hb]\n    exact ((digitCount_bounds (List.length_pos_iff.mpr hb)).2).trans (Nat.div_le_self _ _)\n  have hc:=SemiprimeD1StackDigitCountExecution.totalTime_le (SemiprimeD1StackDigitCountBounds.originalWords bits)\n  have hn:=numeric_budget bits.length (transformLength bits.length) (digitCountValue bits) _ hr hd (cache_bytes bits hb)\n  unfold budget SemiprimeD1BinaryPublicAcquisitionExecution.timeBound SemiprimeD1StackVertexCatalogueModes.blockBudget\n  simp only [show 64*bits.length+3+18=64*bits.length+21 by omega]\n  omega\n\n/-- Real complete producer trace with no resource-answer premise. -/\ntheorem source_run_polynomial (bits:List Bool) (hb:bits≠[]) :\n    ∃m≤10000000000000*(bits.length+1)^5,C.run program m (initial bits)=some (done bits) := by\n  obtain ⟨m,hm,hr⟩:=source_run bits hb\n  exact ⟨m,hm.trans (budget_le bits hb),hr⟩\n\n/-- Successful actual source prefixes cannot run beyond the proved final halt. -/\ntheorem prefix_fuel_le (bits:List Bool) (hb:bits≠[]) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial bits)=some out) : fuel≤10000000000000*(bits.length+1)^5 := by\n  obtain ⟨time,ht,he⟩:=source_run_polynomial bits hb\n  have hf:fuel≤time:=by\n    by_contra hn\n    have h:fuel=time+(1+(fuel-(time+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:C.run program 1 (done bits)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n\n/-- All fifty-three actual Boolean stacks and actual return frames at EVERY executed prefix. -/\ntheorem prefix_cells (bits:List Bool) (hb:bits≠[]) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial bits)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤1000000000000000*(bits.length+1)^5 := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length _ out (by\n    intro k\n    rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> simp only [initial,input,Root.input,SemiprimeD1BinaryPublicAcquisition.store,\n            SemiprimeD1BinaryDigitAcquisition.input,SemiprimeD1BinaryDigitAcquisition.store,\n            SemiprimeD1StackTransform.input,Sum.elim_inl,List.length_nil] <;> omega\n        · rcases k with k|k <;> exact Nat.zero_le _\n      · rcases k with k|k <;> exact Nat.zero_le _\n    · exact Nat.zero_le _) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length)≤53*(bits.length+fuel):=by\n    calc\n      _≤∑_k:Stack,(bits.length+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _= _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits hb fuel out hr\n  have hn:bits.length≤(bits.length+1)^5:=by\n    have hh:bits.length+1≤(bits.length+1)^5:=by\n      simpa only [pow_one] using Nat.pow_le_pow_right (show 1≤bits.length+1 by omega) (show 1≤5 by omega)\n    omega\n  omega\n\n/-- Compiled finite-machine storage starts from binary N alone. -/\ntheorem machine_prefix_cells (bits:List Bool) (hb:bits≠[]) (fuel:ℕ) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤1000000000000000*(bits.length+1)^5 := by\n  have he:=SemiprimeD1StackCalls.run_correct originalInput (kernelStack (Kernel.aux 2)) (.inl .main)\n    program fuel (initial bits)\n  change (C.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial bits))) at he\n  have hh:(C.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=some cfg:=\n    he.trans ((congrArg (fun start:machine.Cfg=>\n      (fun q:Option machine.Cfg=>q.bind machine.step)^[fuel] (some start)) (initial_eq bits).symm).trans hr)\n  cases hc:C.run program fuel (initial bits) with\n  | none => rw [hc] at hh;cases hh\n  | some out =>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hb fuel out hc\n\n/-- Actual complete finite-machine certificate, not a retained-report cost assumption. -/\nnoncomputable def catalogueInTime (bits:List Bool) (hb:bits≠[]) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (10000000000000*(bits.length+1)^5) := by\n  rw [initial_eq bits]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput (kernelStack (Kernel.aux 2)) (.inl .main) program\n  let cert:=source_run_polynomial bits hb\n  let m:=Classical.choose cert\n  have hs:=Classical.choose_spec cert\n  exact ⟨⟨m,hs.2⟩,hs.1⟩\nend RiemannGaussian.SemiprimeD1StackVertexCatalogueBounds\n\n","RiemannGaussian.SemiprimeD1StackVertexCatalogueTags":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexCatalogueCaches\n\n/-! # Literal constructor-tag acquisition and original source-role bounds -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 4096\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVertexCatalogueTags\nopen SemiprimeD1StackVertexCatalogue SemiprimeD1StackVertexCatalogueComponents SemiprimeD1StackVertexCatalogueView\nopen SemiprimeD1StackVertexCataloguePrepare SemiprimeD1StackVertexCatalogueModes SemiprimeD1StackVertexCatalogueCaches\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\nopen SemiprimeMacroParameters\n\n/-- The finite tag counter is acquired by actual pushes, not encoded from an advised mode value. -/\ntheorem init_run (n i:ℕ) (hi:i+n=17) (base:Stack→List Bool) (limits:Fin 4→List Bool) (output:List Bool) :\n    Runs program (n+1) (.inl (.initTag ⟨i,by omega⟩)) (view base limits (List.replicate i true) output)\n      (.inl (.clearLimit .flagOr 0)) (view base limits (List.replicate 17 true) output) := by\n  induction n generalizing i with\n  | zero =>\n    have he:i=17:=by omega\n    subst i\n    exact one_base program _ _ (.jump (.inl (.clearLimit .flagOr 0))) _ _ rfl rfl rfl\n  | succ n ih =>\n    have hit:i<17:=by omega\n    have hcode:program (.inl (.initTag ⟨i,by omega⟩))=\n        .base (.push (kernelStack (Kernel.aux 3)) true (.inl (.initTag ⟨i+1,by omega⟩))):=by\n      simp [program,hit]\n    have h0:=push_run (.inl (.initTag ⟨i,by omega⟩)) (.inl (.initTag ⟨i+1,by omega⟩))\n      (kernelStack (Kernel.aux 3)) true (view base limits (List.replicate i true) output) hcode\n    change Runs program 1 _ _ _ (Function.update (view base limits (List.replicate i true) output)\n      (kernelStack (Kernel.aux 3)) (true::List.replicate i true)) at h0\n    rw [view_tag,←List.replicate_succ] at h0\n    have h1:=ih (i+1) (by omega)\n    simpa only [show 1+(n+1)=n+1+1 by omega] using h0.trans h1\n\n/-- The actual cached count has ORIGINAL raw-width digitCount, including all empty zero-digit fields. -/\ntheorem digitCount_raw (bits:List Bool) (hb:bits≠[]) : digitCountValue bits=digitCount bits.length := by\n  exact SemiprimeD1StackDigitBankSpec.original_count bits.length (List.length_pos_iff.mpr hb) bits\n    (SemiprimeD1BinaryDigitAcquisitionComponents.radix bits) rfl\n    (SemiprimeD1BinaryDigitAcquisitionComponents.radix_length bits)\n\n/-- One original-input bound covers every actually acquired readonly limit role. -/\ntheorem base_bound (bits:List Bool) (hb:bits≠[]) : RoleBound (64*bits.length+3) (base bits) := by\n  have hell:0<bits.length:=List.length_pos_iff.mpr hb\n  have hR:transformLength bits.length≤64*bits.length+1:=\n    (SemiprimeD1StackTransformArithmetic.prefix_powers bits.length (transformExponent bits.length) (le_refl _)).1\n  have hP:firstAxis bits.length≤transformLength bits.length:=\n    Nat.pow_le_pow_right (by decide) (Nat.div_le_self _ _)\n  have hQ:secondAxis bits.length≤transformLength bits.length:=by\n    rw [secondAxis_eq_power]\n    exact Nat.pow_le_pow_right (by decide) (Nat.sub_le _ _)\n  have hD:digitCountValue bits≤transformLength bits.length:=by\n    rw [digitCount_raw bits hb]\n    exact ((digitCount_bounds hell).2).trans (Nat.div_le_self (transformLength bits.length) 4)\n  intro role\n  rw [base_format]\n  rw [List.length_replicate]\n  apply SemiprimeD1VertexCatalogueModes.dimension_le _ _ _ _ (by omega) (by omega) ?_ (by omega) (by omega) role\n  rw [axes_product]\n  omega\n\n/-- The whole actual mode trace begins only after the physical17-marker tag is acquired. -/\ntheorem catalogue_run (bits:List Bool) (hb:bits≠[]) :\n    ∃m≤18*blockBudget (64*bits.length+3),Runs program m (.inl (.clearLimit .flagOr 0))\n      (view (base bits) (fun _=>[]) (List.replicate 17 true) []) (.inl .halt)\n      (view (base bits) (preparedLimits (base bits) .input) []\n        (SemiprimeD1VertexCatalogueEncoding.catalogue (firstAxis bits.length) (secondAxis bits.length) (digitCountValue bits) [])) := by\n  have h:=mode_run (firstAxis bits.length) (secondAxis bits.length) (digitCountValue bits) (base bits)\n    (64*bits.length+3) (base_scratch bits) (base_format bits) (base_bound bits hb) .flagOr (fun _=>[]) []\n    (by intro axis;simp)\n  simpa only [SemiprimeD1VertexCatalogueModes.code,prefix_full] using h\nend RiemannGaussian.SemiprimeD1StackVertexCatalogueTags\n","RiemannGaussian.SemiprimeD1StackVertexProduct":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetUnitBounds\nimport RiemannGaussian.SemiprimeD1StackVertexReadBounds\n/-! # Fixed parsed-vertex physical product caller\nContext rank/precision are acquired from the actual original headers. The vertex\nloop parses original port/table fields, calls physical gather/tree lookup, and\nfeeds its encoded vector directly to the closed physical dense multiplier.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 65536\nset_option maxRecDepth 65536\nset_option maxHeartbeats 1500000\nnamespace RiemannGaussian.SemiprimeD1StackVertexProduct\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace M\nexport SemiprimeD1StackJetMul (Stack Label program output)\nend M\nnamespace X\nexport SemiprimeD1StackJetContext (Stack Label program axesCache precisionBits rankCache widthCache)\nend X\nnamespace U\nexport SemiprimeD1StackJetUnit (Stack Label program widthCache rankCache output)\nend U\nnamespace V\nexport SemiprimeD1StackVertexRead (Stack Label code control)\nend V\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n\n/-- Original input caches and literal parsing/copy work. -/\ninductive Aux where\n  | verticesCache | verticesReader | assignment | precisionBits | ports | table\n  | fieldScratch | fieldValid | copyWork\n  deriving DecidableEq,Repr\ninstance : Fintype Aux := Fintype.ofList\n  [.verticesCache,.verticesReader,.assignment,.precisionBits,.ports,.table,.fieldScratch,.fieldValid,.copyWork]\n  (by intro k; cases k <;> simp)\n\n/-- One fixed finite Boolean register bank, including all literal callee work. -/\nabbrev Stack := M.Stack ⊕ ((X.Stack ⊕ U.Stack) ⊕ (V.Stack ⊕ (F.Stack ⊕ Aux)))\n/-- Actual multiplier data address. -/\ndef main (k : M.Stack) : Stack := .inl k\n/-- Actual dedicated context work address. -/\ndef contextWork (k : X.Stack) : Stack := .inr (.inl (.inl k))\n/-- Actual dedicated unit work address. -/\ndef unitWork (k : U.Stack) : Stack := .inr (.inl (.inr k))\n/-- Actual dedicated vertex-reader work address. -/\ndef vertexWork (k : V.Stack) : Stack := .inr (.inr (.inl k))\n/-- Actual caller cache/work address. -/\ndef aux (k : Aux) : Stack := .inr (.inr (.inr (.inr k)))\n/-- First encoded-vector operand of the literal multiplier. -/\ndef left : Stack := main (.inl (SemiprimeD1StackJetPoint.aux .a))\n/-- Current encoded product, retained as the second literal multiplier operand. -/\ndef product : Stack := main (.inl (SemiprimeD1StackJetPoint.aux .b))\n/-- Shared original axis tape. -/\ndef axes : Stack := main (.inl (SemiprimeD1StackJetPoint.aux .axes))\n/-- Shared physically acquired rank cache. -/\ndef rank : Stack := main (.inl (SemiprimeD1StackJetPoint.aux .rank))\n/-- Shared physically acquired precision markers. -/\ndef width : Stack := main (.inl SemiprimeD1StackJetPoint.precision)\n/-- Actual newly acquired product tape. -/\ndef result : Stack := main M.output\n\n/-- Actual context outputs ARE the later arithmetic caches; no native projection\nor recoding of the computed rank/precision is executed. -/\ndef contextStack (k : X.Stack) : Stack :=\n  if k=X.axesCache then axes else if k=X.rankCache then rank else if k=X.widthCache then width\n  else if k=X.precisionBits then aux .precisionBits else contextWork k\n\n/-- Literal unit construction uses the same empty operands and actual caches. -/\ndef unitStack (k : U.Stack) : Stack :=\n  if k=U.widthCache then width else if k=U.rankCache then rank else if k=U.output then result\n  else if k=Sum.inr SemiprimeD1StackJetAdd.Aux.leftTape then left\n  else if k=Sum.inr SemiprimeD1StackJetAdd.Aux.rightTape then product else unitWork k\n\n/-- Real table read writes its encoded vector DIRECTLY into the multiplier operand. -/\ndef vertexStack : V.Stack → Stack\n  | .ports => aux .ports\n  | .assignment => aux .assignment\n  | .tableTape => aux .table\n  | .output => left\n  | k => vertexWork k\n\n/-- Both original vertex fields are physically parsed from the same input stream. -/\ndef fieldStack (table : Bool) : F.Stack → Stack\n  | .inl .input => aux .verticesReader\n  | .inl .scratch => aux .fieldScratch\n  | .inl .output => aux (if table then .table else .ports)\n  | .inr _ => aux .fieldValid\n\n/-- Literal original-record and current-result copies, both actually executed. -/\ndef copyStack (vertices : Bool) (k : Fin 3) : Stack :=\n  if k=0 then (if vertices then aux .verticesCache else result)\n  else if k=1 then (if vertices then aux .verticesReader else product) else aux .copyWork\n\n/-- Fixed caller and included-program labels, independent of context and network size. -/\ninductive Label where\n  | start | prepared | unitDone | clearUnitOut | copyVertices | vertexTag | readPorts | portsDone\n  | readTable | tableDone | callVertex | callMul | clearA | clearB | copyProduct | clearOutput | done | abort\n  | context (pc : X.Label)\n  | unit (pc : U.Label)\n  | vertex (pc : V.Label)\n  | multiply (pc : M.Label)\n  | field (table : Bool) (pc : F.Label)\n  | copy (vertices : Bool) (pc : Fin 9)\n  deriving DecidableEq,Fintype\n\n/-- Actual context acquisition and parsed-vertex product. The prepared label is\nan internal entry for an assignment caller that ALREADY executed this context\nsupplier; the top-level start always acquires its own original context caches. -/\ndef program : Label → C.Instruction Stack Label\n  | .start => .call (.context .start) .prepared\n  | .prepared => .call (.unit .seed0) .unitDone\n  | .unitDone => .call (.copy false 0) .clearUnitOut\n  | .clearUnitOut => .base (.pop result .copyVertices .clearUnitOut .clearUnitOut)\n  | .copyVertices => .call (.copy true 0) .vertexTag\n  | .vertexTag => .base (.pop (aux .verticesReader) .done .done .readPorts)\n  | .readPorts => .call (.field false (F.active .tagPop (none,false))) .portsDone\n  | .portsDone => .base (.pop (aux .fieldValid) .abort .abort .readTable)\n  | .readTable => .call (.field true (F.active .tagPop (none,false))) .tableDone\n  | .tableDone => .base (.pop (aux .fieldValid) .abort .abort .callVertex)\n  | .callVertex => .call (.vertex (V.control .start)) .callMul\n  | .callMul => .call (.multiply .start) .clearA\n  | .clearA => .base (.pop left .clearB .clearA .clearA)\n  | .clearB => .base (.pop product .copyProduct .clearB .clearB)\n  | .copyProduct => .call (.copy false 0) .clearOutput\n  | .clearOutput => .base (.pop result .vertexTag .clearOutput .clearOutput)\n  | .done | .abort => .base .halt\n  | .context pc => SemiprimeD1StackValidationLink.instruction contextStack Label.context (X.program pc)\n  | .unit pc => SemiprimeD1StackValidationLink.instruction unitStack Label.unit (U.program pc)\n  | .vertex pc => SemiprimeD1StackValidationLink.instruction vertexStack Label.vertex (V.code pc)\n  | .multiply pc => SemiprimeD1StackValidationLink.instruction main Label.multiply (M.program pc)\n  | .field table pc => SemiprimeD1StackMultiplierLink.instruction (fieldStack table) (Label.field table) (F.code pc)\n  | .copy vertices pc => SemiprimeD1StackMultiplierLink.instruction (copyStack vertices) (Label.copy vertices)\n      (SemiprimeD1StackCopy.code pc)\n\n/-- Input representation only, never an executed vertex/entry getter.\nEach original field is physically parsed by the literal program above. -/\ndef records : List SemiprimeD1LeafCounter.Vertex → List Bool\n  | [] => [false]\n  | v::vs => true::SemiprimeSourceHistogramKeyBits.frame\n      (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n      (SemiprimeSourceHistogramKeyBits.frame (SemiprimeD1TensorTapeCodec.tape v.table) (records vs))\n\n/-- Literal original physical headers, vertex records and assignment, no rank,\nprecision-count, selected entry, product or leaf answer prepared. -/\ndef inputData (axisTape precisionBits vertexTape assignment : List Bool) : Stack → List Bool :=\n  Function.update (Function.update (Function.update (Function.update (fun _=>[]) axes axisTape)\n    (aux .precisionBits) precisionBits) (aux .verticesCache) vertexTape) (aux .assignment) assignment\n/-- Actual start has cleared flags/frames and all work/arithmetic operands empty. -/\ndef initial (axisTape precisionBits vertexTape assignment : List Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,inputData axisTape precisionBits vertexTape assignment,[]⟩\n/-- Actual fixed finite-stack original-header vertex-product machine. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (aux .verticesCache) product Label.start program\n\n/-- Context-cache/output aliases preserve distinct physical component registers. -/\ntheorem contextStack_injective : Function.Injective contextStack := by decide\n/-- Unit-cache/output aliases preserve distinct physical component registers. -/\ntheorem unitStack_injective : Function.Injective unitStack := by decide\n/-- The literal vertex-read operands have disjoint physical registers. -/\ntheorem vertexStack_injective : Function.Injective vertexStack := by decide\n/-- Both physical field parsers have distinct registers. -/\ntheorem fieldStack_injective (table : Bool) : Function.Injective (fieldStack table) := by cases table <;> decide\n/-- Both physical copies have distinct source/target/work registers. -/\ntheorem copyStack_injective (vertices : Bool) : Function.Injective (copyStack vertices) := by cases vertices <;> decide\n\nend RiemannGaussian.SemiprimeD1StackVertexProduct\n","RiemannGaussian.SemiprimeD1StackVertexProductMultiply":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexProductRead\n/-! # The actual dense multiplication call inside the parsed vertex product -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 65536\nset_option maxRecDepth 65536\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackVertexProductMultiply\nopen SemiprimeD1StackVertexProduct SemiprimeD1StackVertexProductState\nopen SemiprimeD1StackVertexProductProjection\nopen SemiprimeD1StackProcedureTrace (Runs)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\n\n/-- The literal multiplier is invoked on the two physically present vectors;\nall routing, coefficient reads, scalar arithmetic and framing execute inside it. -/\ntheorem multiply_call (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive)\n    (v : Values) (a b : List (List Bool))\n    (ha : v .left=vectorBits a) (hb : v .product=vectorBits b)\n    (haxes : v .axes=vectorBits (ctx.axes.map unary))\n    (hw : (v .width).length=ctx.precision) (hr : v .rank=unary ctx.rank)\n    (hout : v .result=[]) :\n    ∃ m ≤ 2000000*(SemiprimeD1StackJetMulBounds.inputSize ctx (multiplierCache v)+1)^6+1,\n      Runs program m .callMul (data v) .clearA\n        (data (Function.update v .result (vectorBits (SemiprimeD1JetRingBits.mul ctx a b).words))) := by\n  obtain ⟨m,hm,hs⟩:=SemiprimeD1StackJetMulBounds.source_run_polynomial ctx hp\n    (multiplierCache v) a b ha hb haxes hw hr\n  refine ⟨m+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureInclusion.included_call program main Label.multiply\n    (by intro a b h; exact Sum.inl.inj h) M.program .start (fun _=>rfl)\n    .callMul .clearA rfl m\n    (SemiprimeD1StackJetMul.initial (v .left) (v .product) (v .axes) (v .width) (v .rank))\n    (⟨none,none,none,SemiprimeD1StackJetMulExecution.data (multiplierCache v) [] []\n      (vectorBits (SemiprimeD1JetRingBits.mul ctx a b).words),[]⟩:\n      SemiprimeD1StackCalls.State M.Stack M.Label)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hs\n  · constructor\n    · intro k\n      rw [main_project]\n      have hi:=congrFun (SemiprimeD1StackJetMulExecution.initial_data (multiplierCache v)) k\n      simpa only [multiplierCache,hout] using hi.symm\n    · intro k hk\n      rfl\n  · constructor\n    · intro k\n      rw [main_project]\n      fin_cases k <;> simp [multiplierCache]\n    · intro k hk\n      have hn : k ≠ address .result := fun he=>hk M.output he.symm\n      rw [data_update]\n      exact Function.update_of_ne hn _ _\n\nend RiemannGaussian.SemiprimeD1StackVertexProductMultiply\n","RiemannGaussian.SemiprimeD1StackVertexProductSetup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexProductProjection\n/-! # Actual original-header context and unit setup inside the product caller -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 65536\nset_option maxRecDepth 65536\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackVertexProductSetup\nopen SemiprimeD1StackVertexProduct SemiprimeD1StackVertexProductState\nopen SemiprimeD1StackVertexProductProjection\nopen SemiprimeD1StackProcedureTrace (Runs)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeD1JetAxes (Context)\n\n/-- Acquired context fields come from the original physical producers, not\nprepared rank/precision-count answer words in the vertex-product entry. -/\ntheorem context_call (v : Values) (axisList : List ℕ) (hp : ∀q∈axisList,0<q)\n    (ha : v .axes=vectorBits (axisList.map unary)) (hr : v .rank=[]) (hw : v .width=[]) :\n    ∃ m ≤ 1000*(SemiprimeD1StackJetContextBounds.resource axisList (v .precision)+1)^2+1,\n      Runs program m .start (data v) .prepared\n        (data (Function.update (Function.update v .rank (unary axisList.prod)) .width\n          (SemiprimeD1StackUnaryCounterExecution.markers (SemiprimeBitArithmetic.bitValue (v .precision))))) := by\n  obtain ⟨m,hm,hsource⟩:=SemiprimeD1StackJetContextBounds.source_run_polynomial axisList hp (v .precision)\n  refine ⟨m+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureInclusion.included_call program contextStack Label.context contextStack_injective\n    X.program .start (fun _=>rfl) .start .prepared rfl m\n    (SemiprimeD1StackJetContext.initial (vectorBits (axisList.map unary)) (v .precision))\n    (⟨none,none,none,SemiprimeD1StackJetContextCorrectness.finalData axisList (v .precision),[]⟩:\n      SemiprimeD1StackCalls.State X.Stack X.Label)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hsource\n  · constructor\n    · intro k\n      rw [context_project]\n      fin_cases k <;> simp [SemiprimeD1StackJetContext.initial,SemiprimeD1StackJetContext.bank,\n        SemiprimeD1StackJetContext.cached,X.axesCache,X.rankCache,X.widthCache,X.precisionBits,ha,hr,hw]\n    · intro k hk\n      rfl\n  · constructor\n    · intro k\n      rw [context_project]\n      fin_cases k <;> simp [SemiprimeD1StackJetContextCorrectness.finalData,\n        SemiprimeD1StackJetContext.bank,SemiprimeD1StackJetContext.cached,\n        SemiprimeD1StackJetContextExecution.ready,SemiprimeD1StackJetSuffix.data,SemiprimeD1StackAdder.store,\n        X.axesCache,X.rankCache,X.widthCache,X.precisionBits,ha]\n    · intro k hk\n      have hnR : k ≠ address .rank := fun he=>hk X.rankCache he.symm\n      have hnW : k ≠ address .width := fun he=>hk X.widthCache he.symm\n      rw [data_update,data_update]\n      simp only [Function.update_of_ne hnW,Function.update_of_ne hnR]\n\n/-- Actual literal-unit setup inside the product caller uses only the already\nacquired context caches and physically creates its canonical dense vector. -/\ntheorem unit_call (ctx : Context) (v : Values) (hw : (v .width).length=ctx.precision)\n    (hr : (v .rank).length=ctx.rank) (hleft : v .left=[]) (hprod : v .product=[]) (hout : v .result=[]) :\n    Runs program (SemiprimeD1StackJetUnitExecution.totalTime (v .width) (v .rank)+1) .prepared (data v) .unitDone\n      (data (Function.update v .result (vectorBits (SemiprimeD1JetAffineCoefficient.one ctx).words))) := by\n  apply SemiprimeD1StackProcedureInclusion.included_call program unitStack Label.unit unitStack_injective\n    U.program .seed0 (fun _=>rfl) .prepared .unitDone rfl _\n    (SemiprimeD1StackJetUnit.initial (v .width) (v .rank))\n    (⟨none,none,none,SemiprimeD1StackJetUnit.bank (v .width) (v .rank) [] []\n      (vectorBits (SemiprimeD1JetAffineCoefficient.one ctx).words),[]⟩:\n      SemiprimeD1StackCalls.State U.Stack U.Label)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackJetUnitExecution.source_run ctx (v .width) (v .rank) hw hr\n  · constructor\n    · intro k\n      rw [unit_project]\n      fin_cases k <;> simp [SemiprimeD1StackJetUnit.initial,SemiprimeD1StackJetUnit.bank,\n        SemiprimeD1StackJetAdd.store,SemiprimeD1StackJetScalarAdd.store,\n        U.widthCache,U.rankCache,U.output,hleft,hprod,hout]\n    · intro k hk\n      rfl\n  · constructor\n    · intro k\n      rw [unit_project]\n      fin_cases k <;> simp [SemiprimeD1StackJetUnit.bank,SemiprimeD1StackJetAdd.store,\n        SemiprimeD1StackJetScalarAdd.store,U.widthCache,U.rankCache,U.output,hleft,hprod]\n    · intro k hk\n      have hn : k ≠ address .result := fun he=>hk U.output he.symm\n      rw [data_update]\n      exact Function.update_of_ne hn _ _\n\nend RiemannGaussian.SemiprimeD1StackVertexProductSetup\n","RiemannGaussian.SemiprimeD1StackVertexRecordSpliceStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexRecordSpliceMeaning\n/-! # Complete physical storage for singleton-record EOF cancellation\nRuntime is independent of accumulated history length; space honestly includes\nthat existing history, the new row and every actual saved return cell.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackVertexRecordSpliceStorage\nopen SemiprimeD1StackVertexRecordSplice SemiprimeD1StackVertexRecordSpliceExecution\n/-- No successful actual source prefix exceeds the exact new-row-only halt clock. -/\ntheorem prefix_fuel (row history : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial (row++[false]) history)=some out) : fuel≤timeBound row := by\n  have hs:=source_run row history\n  by_contra hn\n  have he : fuel=timeBound row+(1+(fuel-(timeBound row+1))) := by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,hs,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n  have hh : SemiprimeD1StackCalls.run program 1 (done (row.reverse++history))=none := rfl\n  rw [hh,Option.bind_none] at hr\n  cases hr\n/-- Both actual initialized input words are physically counted, including the old history. -/\ntheorem initial_length (row history : List Bool) (k : Stack) :\n    ((initial (row++[false]) history).data k).length≤row.length+history.length+1 := by\n  fin_cases k\n  · change (row++[false]).length≤_\n    simp only [List.length_append,List.length_singleton]\n    omega\n  · change history.length≤_\n    omega\n/-- Every actual source prefix counts both data words AND every real return cell, with a fixed linear cap. -/\ntheorem prefix_cells (row history : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial (row++[false]) history)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤30*(row.length+history.length+1) := by\n  have hf:=prefix_fuel row history fuel out hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (row.length+history.length+1)\n    _ out (initial_length row history) hr\n  have hm : (∑k : Stack,(out.data k).length)≤2*(row.length+history.length+1+fuel) := by\n    calc\n      _≤∑_k : Stack,(row.length+history.length+1+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,Fintype.card_fin,smul_eq_mul]\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel (initial (row++[false]) history) out hr\n  change out.frames.length≤0+fuel at hframes\n  unfold timeBound at hf\n  omega\n/-- Actual fixed FinTM2 execution has the SAME two-word-plus-return storage cap at every prefix. -/\ntheorem machine_prefix_cells (row history : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial (row++[false]) history)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤30*(row.length+history.length+1) := by\n  have heq:=SemiprimeD1StackCalls.run_correct 0 1 (.local .start) program fuel (initial (row++[false]) history)\n  have hh:=heq.trans hr\n  cases hout : SemiprimeD1StackCalls.run program fuel (initial (row++[false]) history) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg : cfg=SemiprimeD1StackCalls.configuration out:=(Option.some.inj hh).symm\n    subst cfg\n    exact prefix_cells row history fuel out hout\nend RiemannGaussian.SemiprimeD1StackVertexRecordSpliceStorage\n","RiemannGaussian.SemiprimeD1StackWeightedMode":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1StackFrame\nimport RiemannGaussian.SemiprimeD1StackAssignmentBody\nimport RiemannGaussian.SemiprimeD1StackReverseWord\nimport RiemannGaussian.SemiprimeD1WeightedTuples\n/-! # Real feasible-only weighted-tuple recursion with physical activation records\nThis prepared entry takes an actual framed positive-weight tape and the actual\nunary precision WIDTH. It copies WIDTH and physically removes one marker for\nits budget. Every child has a real return frame and five saved Boolean words.\nOnly successful repeated subtraction creates another child. Catalogue/packet\nacquisition is a separate frontend, never an evaluator hidden in this control.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedMode\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace Field\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend Field\nnamespace Body\nexport SemiprimeD1StackAssignmentBody (Stack Label code entry)\nend Body\n/-- Seventeen fixed Boolean words; activation records and outputs are ordinary tape data. -/\ninductive Stack where\n  | catalogue | width | weights | budget | path | weight | exponent | frames | tuple | pathReader\n  | fieldScratch | valid | copyScratch | frameScratch | subTodo | history | output\n  deriving DecidableEq,Repr\ninstance :Fintype Stack where\n  elems:={.catalogue,.width,.weights,.budget,.path,.weight,.exponent,.frames,.tuple,.pathReader,\n    .fieldScratch,.valid,.copyScratch,.frameScratch,.subTodo,.history,.output}\n  complete:=by intro k;cases k <;> simp\n/-- Four actual preserving-copy sites, each independent of all numerical values. -/\ninductive Copy where | catalogue | width | path | weight deriving DecidableEq,Repr\ninstance :Fintype Copy where\n  elems:={.catalogue,.width,.path,.weight}\n  complete:=by intro k;cases k <;> simp\n/-- Five literal saved activation fields, in their physical restore order. -/\ndef saved : Fin 5→Stack :=![.weight,.weights,.budget,.exponent,.path]\n/-- Nine actual mutable words are physically drained before every recursive return. -/\ndef cleared : Fin 9→Stack :=![.weights,.budget,.path,.weight,.exponent,.subTodo,.tuple,.pathReader,.valid]\n/-- Seven fixed parser sites: one weight, one leaf-path field and five restored activation fields. -/\ninductive Parse where | weight | path | restore (part:Fin 5) deriving DecidableEq,Repr,Fintype\n/-- Three fixed frame sites: activation save, recursive path push and leaf tuple reversal. -/\ninductive Frame where | save (part:Fin 5) | path | tuple deriving DecidableEq,Repr,Fintype\n/-- Fixed finite locations; recursion depth, weights, budgets and exponents never enter labels. -/\ninductive Control where\n  | start | widthCopy | budgetPred | pathSeed | root | finishSeed | reverse | done | abort\n  | visit | weightRead | weightValid | weightPositive | save (part:Fin 5)\n  | pathFrame | pathTag | clearWeight | clearExponent | child | afterChild\n  | restore (part:Fin 5) | restoreValid (part:Fin 5)\n  | copyWeight | subtract | budgetPop | increment | failure\n  | tupleSeed | copyPath | tupleNext | tupleRead | tupleValid | tupleFrame | tupleTag | tupleClear | emit\n  | cleanup (part:Fin 9) | returning\n  deriving DecidableEq,Repr,Fintype\n/-- Real primitive and recursive return-label alphabets are fixed before every input. -/\nabbrev Label :=Control⊕((Copy×Fin 9)⊕((Parse×Field.Label)⊕((Frame×Fin 11)⊕(Body.Label⊕Fin 4))))\n/-- Actual included copy labels. -/\ndef copyLabel (site:Copy) (pc:Fin 9) : Label :=.inr (.inl (site,pc))\n/-- Actual included field-parser labels. -/\ndef parseLabel (site:Parse) (pc:Field.Label) : Label :=.inr (.inr (.inl (site,pc)))\n/-- Actual included preserving frame labels. -/\ndef frameLabel (site:Frame) (pc:Fin 11) : Label :=.inr (.inr (.inr (.inl (site,pc))))\n/-- Actual tuple logger labels. -/\ndef bodyLabel (pc:Body.Label) : Label :=.inr (.inr (.inr (.inr (.inl pc))))\n/-- Actual final whole-history reversal labels. -/\ndef reverseLabel (pc:Fin 4) : Label :=.inr (.inr (.inr (.inr (.inr pc))))\n/-- Real copy source and initially empty target; the scratch is always counted. -/\ndef copyStack (site:Copy) (k:Fin 3) : Stack :=\n  if k=0 then match site with | .catalogue=>.catalogue | .width=>.width | .path=>.path | .weight=>.weight\n  else if k=1 then match site with | .catalogue=>.weights | .width=>.budget | .path=>.pathReader | .weight=>.subTodo\n  else .copyScratch\n/-- Each field comes from the physical weight suffix, copied path, or actual activation stack. -/\ndef parseStack (site:Parse) : Field.Stack→Stack\n  | .inl .input=>match site with | .weight=>.weights | .path=>.pathReader | .restore _=>.frames\n  | .inl .output=>match site with | .weight | .path=>.weight | .restore i=>saved i\n  | .inl .scratch=>.fieldScratch\n  | .inr _=>.valid\n/-- Actual activation/path/tuple framing uses one separate restoring scratch word. -/\ndef frameStack (site:Frame) (k:Fin 3) : Stack :=\n  if k=0 then match site with | .save i=>saved i | .path=>.exponent | .tuple=>.weight\n  else if k=1 then match site with | .save _=>.frames | .path=>.path | .tuple=>.tuple\n  else .frameScratch\n/-- Every emitted tuple is restored and copied into the same chronological reverse log. -/\ndef bodyStack : Body.Stack→Stack | .word=>.tuple | .scratch=>.copyScratch | .history=>.history\n/-- One final real reversal writes the physical output, seeded with its false terminator. -/\ndef reverseStack (k:Fin 2) : Stack :=if k=0 then .history else .output\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- The next literal save field; fields are pushed last-first and restored first-last. -/\ndef saveNext (i:Fin 5) : Label :=if h:0 < i.val then ctl (.save ⟨i.val-1,by omega⟩) else ctl .pathFrame\n/-- The next literal restore field, followed by the feasible-branch subtraction test. -/\ndef restoreNext (i:Fin 5) : Label :=if h:i.val<4 then ctl (.restore ⟨i.val+1,by omega⟩) else ctl .copyWeight\n/-- The next physical cleanup word, with actual return after all nine words are empty. -/\ndef cleanupNext (i:Fin 9) : Label :=if h:i.val<8 then ctl (.cleanup ⟨i.val+1,by omega⟩) else ctl .returning\n/-- One fixed finite controller: actual positive-weight traversal, feasible children only and real recursion. -/\ndef program : Label→C.Instruction Stack Label\n  | .inl .start=>.call (copyLabel .catalogue 0) (ctl .widthCopy)\n  | .inl .widthCopy=>.call (copyLabel .width 0) (ctl .budgetPred)\n  | .inl .budgetPred=>.base (.pop .budget (ctl .pathSeed) (ctl .pathSeed) (ctl .pathSeed))\n  | .inl .pathSeed=>.base (.push .path false (ctl .root))\n  | .inl .root=>.call (ctl .visit) (ctl .finishSeed)\n  | .inl .finishSeed=>.base (.push .output false (ctl .reverse))\n  | .inl .reverse=>.call (reverseLabel 0) (ctl .done)\n  | .inl .done|.inl .abort=>.base .halt\n  | .inl .visit=>.base (.pop .weights (ctl .abort) (ctl .tupleSeed) (ctl .weightRead))\n  | .inl .weightRead=>.call (parseLabel .weight (Field.active .tagPop (none,false))) (ctl .weightValid)\n  | .inl .weightValid=>.base (.pop .valid (ctl .abort) (ctl .abort) (ctl .weightPositive))\n  | .inl .weightPositive=>.base (.peek .weight (ctl .abort) (ctl (.save 4)) (ctl (.save 4)))\n  | .inl (.save i)=>.call (frameLabel (.save i) 0) (saveNext i)\n  | .inl .pathFrame=>.call (frameLabel .path 0) (ctl .pathTag)\n  | .inl .pathTag=>.base (.push .path true (ctl .clearWeight))\n  | .inl .clearWeight=>.base (.pop .weight (ctl .clearExponent) (ctl .clearWeight) (ctl .clearWeight))\n  | .inl .clearExponent=>.base (.pop .exponent (ctl .child) (ctl .clearExponent) (ctl .clearExponent))\n  | .inl .child=>.call (ctl .visit) (ctl .afterChild)\n  | .inl .afterChild=>.base (.jump (ctl (.restore 0)))\n  | .inl (.restore i)=>.call (parseLabel (.restore i) (Field.active .tagPop (none,false))) (ctl (.restoreValid i))\n  | .inl (.restoreValid i)=>.base (.pop .valid (ctl .abort) (ctl .abort) (restoreNext i))\n  | .inl .copyWeight=>.call (copyLabel .weight 0) (ctl .subtract)\n  | .inl .subtract=>.base (.pop .subTodo (ctl .increment) (ctl .budgetPop) (ctl .budgetPop))\n  | .inl .budgetPop=>.base (.pop .budget (ctl .failure) (ctl .subtract) (ctl .subtract))\n  | .inl .increment=>.base (.push .exponent true (ctl (.save 4)))\n  | .inl .failure=>.base (.pop .subTodo (ctl (.cleanup 0)) (ctl .failure) (ctl .failure))\n  | .inl .tupleSeed=>.base (.push .tuple false (ctl .copyPath))\n  | .inl .copyPath=>.call (copyLabel .path 0) (ctl .tupleNext)\n  | .inl .tupleNext=>.base (.pop .pathReader (ctl .abort) (ctl .emit) (ctl .tupleRead))\n  | .inl .tupleRead=>.call (parseLabel .path (Field.active .tagPop (none,false))) (ctl .tupleValid)\n  | .inl .tupleValid=>.base (.pop .valid (ctl .abort) (ctl .abort) (ctl .tupleFrame))\n  | .inl .tupleFrame=>.call (frameLabel .tuple 0) (ctl .tupleTag)\n  | .inl .tupleTag=>.base (.push .tuple true (ctl .tupleClear))\n  | .inl .tupleClear=>.base (.pop .weight (ctl .tupleNext) (ctl .tupleClear) (ctl .tupleClear))\n  | .inl .emit=>.call (bodyLabel Body.entry) (ctl (.cleanup 0))\n  | .inl (.cleanup i)=>.base (.pop (cleared i) (cleanupNext i) (ctl (.cleanup i)) (ctl (.cleanup i)))\n  | .inl .returning=>.ret\n  | .inr (.inl (site,pc))=>SemiprimeD1StackMultiplierLink.instruction (copyStack site) (copyLabel site) (SemiprimeD1StackCopy.code pc)\n  | .inr (.inr (.inl (site,pc)))=>SemiprimeD1StackMultiplierLink.instruction (parseStack site) (parseLabel site) (Field.code pc)\n  | .inr (.inr (.inr (.inl (site,pc))))=>SemiprimeD1StackMultiplierLink.instruction (frameStack site) (frameLabel site) (SemiprimeD1StackFrame.code pc)\n  | .inr (.inr (.inr (.inr (.inl pc))))=>SemiprimeD1StackMultiplierLink.instruction bodyStack bodyLabel (Body.code pc)\n  | .inr (.inr (.inr (.inr (.inr pc))))=>SemiprimeD1StackMultiplierLink.instruction reverseStack reverseLabel (SemiprimeD1StackReverseWord.code pc)\n/-- Prepared input has only actual catalogue bytes and actual unary precision WIDTH. -/\ndef input (catalogue width:List Bool) : Stack→List Bool\n  | .catalogue=>catalogue | .width=>width | _=>[]\n/-- Actual two-operand prepared front door; no feasible tuple/count/answer is supplied. -/\ndef initial (catalogue width:List Bool) : C.State Stack Label :=⟨some (ctl .start),none,none,input catalogue width,[]⟩\n/-- One genuine finite machine; explicit prepared inputs are accounted separately. -/\ndef machine : Turing.FinTM2 :=SemiprimeD1StackCalls.machine Stack.width Stack.output (ctl .start) program\n/-- All actual data roles are counted. -/\ntheorem stack_card :Fintype.card Stack=17:=by decide\n/-- Actual copy operands are pairwise distinct. -/\ntheorem copy_injective (site:Copy) :Function.Injective (copyStack site):=by cases site <;> decide\n/-- Actual parser operands are pairwise distinct. -/\ntheorem parse_injective (site:Parse) :Function.Injective (parseStack site):=by\n  cases site with\n  | weight|path=>decide\n  | restore i=>fin_cases i <;> decide\n/-- Actual frame operands are pairwise distinct. -/\ntheorem frame_injective (site:Frame) :Function.Injective (frameStack site):=by\n  cases site with\n  | path|tuple=>decide\n  | save i=>fin_cases i <;> decide\n/-- Actual logger operands are pairwise distinct. -/\ntheorem body_injective :Function.Injective bodyStack:=by decide\n/-- Actual final reversal operands are distinct. -/\ntheorem reverse_injective :Function.Injective reverseStack:=by decide\n/-- No infinite numerical or callback alphabet enters internal control. -/\ntheorem control_finite :Finite machine.σ:=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- Every actual data/real-return alphabet is fixed finite before all inputs. -/\ntheorem alphabets_finite :∀k,Finite (machine.Γ k):=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackWeightedMode\n","RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueExecution\nimport RiemannGaussian.SemiprimeReportPolynomialGrowth\n/-! # Same physical catalogue/enumeration clock, polynomial per feasible visit\nGenerated log sizes are bounded from the actual successful source trace.\nPhysical unary metadata sizes are charged, while coefficients/N stay binary\nin the upstream caller. No native cost report is transported.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueBounds\nopen SemiprimeD1StackWeightedModeCatalogue SemiprimeD1StackWeightedModeCatalogueView\nopen SemiprimeD1StackWeightedModeCatalogueOrders SemiprimeD1StackWeightedModeCatalogueFinish\nopen SemiprimeD1StackWeightedModeCatalogueExecution\nopen SemiprimeD1StackWeightedModeView (unary unary_length vector history)\nopen SemiprimeD1StackWeightedModeResources (inputSize vector_length)\nopen SemiprimeReportPolynomialGrowth\nlocal notation \"ctl\" => (Sum.inl :Control→Label)\nattribute [local irreducible] acquisitionBudget timeBound\n/-- Every initial physical metadata word fits the real total input bytes. -/\ntheorem initial_length (p t width:Nat) (k:Stack):\n    ((initial (unary p) (unary t) (unary width)).data k).length ≤p+t+width:=by\n  rcases k with k|k\n  · cases k <;> simp only [initial,input,unary_length,List.length_nil] <;> omega\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> simp only [initial,input,unary_length,List.length_nil] <;> omega\n    · cases k <;> simp only [initial,input,List.length_nil] <;> omega\n/-- Both actual generated logs fit the SAME successful acquisition trace. -/\ntheorem log_lengths (p t width:Nat):\n    (history (orderWeights (p*t) 0 (width-1)) []).length ≤p+t+width+acquisitionBudget p t width ∧\n    (history (orderLabels (p*t) 0 (width-1)) []).length ≤p+t+width+acquisitionBudget p t width:=by\n  obtain ⟨time,ht,hr⟩:=acquisition_trace p t width\n  obtain ⟨finish,hf,ha⟩:=hr [] (initial (unary p) (unary t) (unary width)) ⟨rfl,rfl,rfl⟩\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program time (p+t+width)\n    _ _ (initial_length p t width) hf\n  have hw:=hd (aux .weightHistory)\n  have hl:=hd (aux .labelHistory)\n  rw [ha.2.1] at hw hl\n  change (history (orderWeights (p*t) 0 (width-1)) []).length ≤p+t+width+time at hw\n  change (history (orderLabels (p*t) 0 (width-1)) []).length ≤p+t+width+time at hl\n  constructor <;> omega\n/-- No output-size oracle is needed to pay either actual catalogue reversal. -/\ntheorem timeBound_le (p t width:Nat):timeBound p t width ≤\n    5*acquisitionBudget p t width+4*(p+t+width)+\n      SemiprimeD1StackWeightedModeBounds.runBound (weights p t width) width+10:=by\n  obtain ⟨hw,hl⟩:=log_lengths p t width\n  unfold timeBound\n  omega\n/-- A literal polynomial upper envelope for the paid multiplier and physical catalogue loops. -/\ndef acquisitionEnvelope (p t width:Nat):Nat:=\n  5*p+5*(p*(2*t+3)+1)+5*width+17+1000*(width+1)*(p*t+1)*(width+p*t+2)\ntheorem acquisitionBudget_le (p t width:Nat):acquisitionBudget p t width ≤acquisitionEnvelope p t width:=by\n  unfold acquisitionBudget acquisitionEnvelope\n  have h:width-1 ≤width:=Nat.sub_le _ _\n  gcongr\ntheorem acquisitionEnvelope_mono {p t width n:Nat} (hp:p ≤ n) (ht:t ≤ n) (hw:width ≤ n):\n    acquisitionEnvelope p t width ≤acquisitionEnvelope n n n:=by\n  unfold acquisitionEnvelope\n  gcongr\n/-- The actual generated weight-vector byte length is polynomial in real input metadata bytes. -/\ntheorem generated_bytes (p t width:Nat):\n    inputSize (weights p t width) width ≤10*(p+t+width+1)^4:=by\n  let n:=p+t+width\n  let P:=width-1\n  let ws:=weights p t width\n  have hp:p ≤n:=by dsimp [n];omega\n  have ht:t ≤n:=by dsimp [n];omega\n  have hP:P ≤n:=by dsimp [P,n];omega\n  have hw:width ≤n:=by dsimp [n];omega\n  have hlen:ws.length=P*(p*t):=by\n    dsimp [ws,weights,P]\n    simp only [SemiprimeD1ModeCatalog.weights,List.length_map,SemiprimeD1ModeCatalog.catalog_length]\n  have hsum:ws.sum ≤ws.length*P:=by\n    have sum_bound (xs:List Nat) (h:∀w∈xs,w ≤P):xs.sum ≤xs.length*P:=by\n      induction xs with\n      | nil=>simp only [List.sum_nil,List.length_nil,Nat.zero_mul,Nat.le_refl]\n      | cons x xs ih=>\n        have hx:=h x (by simp)\n        have hs:=ih (fun w hw=>h w (by simp [hw]))\n        simp only [List.sum_cons,List.length_cons]\n        nlinarith only [hx,hs]\n    exact sum_bound ws (SemiprimeD1ModeCatalog.weights_le _ _)\n  have hslots:p*t ≤n^2:=by simpa only [pow_two] using Nat.mul_le_mul hp ht\n  have hdegree:ws.length ≤n^3:=by\n    rw [hlen]\n    have h:=Nat.mul_le_mul hP hslots\n    convert h using 1;ring\n  have hweight:ws.sum ≤n^4:=by\n    have h:=hsum.trans (Nat.mul_le_mul hdegree hP)\n    convert h using 1;ring\n  have hN:1 ≤n+1:=by omega\n  have h3:n^3 ≤(n+1)^4:=(Nat.pow_le_pow_left (by omega:n ≤n+1) 3).trans\n    (Nat.pow_le_pow_right hN (by omega:3 ≤4))\n  have h4:n^4 ≤(n+1)^4:=Nat.pow_le_pow_left (by omega) 4\n  have h1:n+1 ≤(n+1)^4:=by simpa only [pow_one] using Nat.pow_le_pow_right hN (by omega:1 ≤4)\n  change (vector ws).length+width+2 ≤10*(n+1)^4\n  rw [vector_length]\n  omega\n/-- Fixed width polynomial for the same three-input physical source. -/\ndef polynomial (n:Nat):Nat:=\n  5*acquisitionEnvelope n n n+4*n+10+10000*(10*(n+1)^4)^3\n/-- Same actual source allowance is polynomial per actual feasible visit after real catalogue acquisition. -/\ntheorem timeBound_polynomial (p t width:Nat):\n    timeBound p t width ≤polynomial (p+t+width)*\n      SemiprimeD1WeightedTuples.visits (weights p t width) (width-1):=by\n  let n:=p+t+width\n  let v:=SemiprimeD1WeightedTuples.visits (weights p t width) (width-1)\n  have hv:1 ≤v:=Nat.succ_le_of_lt (SemiprimeD1WeightedTuples.visits_positive _ _)\n  have hf:5*acquisitionBudget p t width+4*n+10 ≤5*acquisitionEnvelope n n n+4*n+10:=by\n    have h:acquisitionBudget p t width ≤acquisitionEnvelope n n n:=\n      (acquisitionBudget_le p t width).trans (acquisitionEnvelope_mono (by dsimp [n];omega)\n        (by dsimp [n];omega) (by dsimp [n];omega))\n    omega\n  have hfront:5*acquisitionBudget p t width+4*n+10 ≤(5*acquisitionEnvelope n n n+4*n+10)*v:=\n    hf.trans (by simpa only [Nat.mul_one] using Nat.mul_le_mul_left _ hv)\n  have hc:=SemiprimeD1StackWeightedModeResources.runBound_bytes (weights p t width) width\n  have hbytes:=generated_bytes p t width\n  have hpow:=Nat.pow_le_pow_left hbytes 3\n  have hcore:SemiprimeD1StackWeightedModeBounds.runBound (weights p t width) width ≤\n      10000*(10*(n+1)^4)^3*v:=\n    hc.trans (Nat.mul_le_mul_right v (Nat.mul_le_mul_left 10000 hpow))\n  have hall:=timeBound_le p t width\n  change timeBound p t width ≤5*acquisitionBudget p t width+4*n+\n    SemiprimeD1StackWeightedModeBounds.runBound (weights p t width) width+10 at hall\n  change _ ≤polynomial n*v\n  unfold polynomial\n  calc\n    _ ≤(5*acquisitionBudget p t width+4*n+10)+\n        SemiprimeD1StackWeightedModeBounds.runBound (weights p t width) width:=by omega\n    _ ≤(5*acquisitionEnvelope n n n+4*n+10)*v+10000*(10*(n+1)^4)^3*v:=\n      Nat.add_le_add hfront hcore\n    _= _:=by ring\n/-- One own bound for the full actual finite program and actual generated weights. -/\ndef runBound (p t width:Nat):Nat:=polynomial (p+t+width)*\n  SemiprimeD1WeightedTuples.visits (weights p t width) (width-1)\ntheorem source_run_bounded (p t width:Nat):∃time ≤runBound p t width,\n    C.run program time (initial (unary p) (unary t) (unary width))=some (done p t width):=by\n  obtain ⟨time,ht,hr⟩:=source_run p t width\n  exact ⟨time,ht.trans (timeBound_polynomial p t width),hr⟩\n/-- Fixed coefficient and degree are chosen before every input metadata triple. -/\ntheorem polynomial_monomial:∃A d:Nat,∀n,polynomial n ≤A*(n+1)^d:=by\n  change Bound polynomial\n  unfold polynomial acquisitionEnvelope\n  boundArithmetic\n/-- Existing feasible-menu cardinality bounds apply to this SAME physical program. -/\ntheorem runBound_le_leaves (p t width:Nat):\n    runBound p t width ≤polynomial (p+t+width)*((weights p t width).length+1)*\n      (SemiprimeD1WeightedTuples.tuples (weights p t width) (width-1)).length:=by\n  have h:=Nat.mul_le_mul_left (polynomial (p+t+width))\n    (SemiprimeD1WeightedTuples.visits_le (weights p t width) (width-1))\n  simpa only [runBound,Nat.mul_assoc] using h\nend RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueBounds\n","RiemannGaussian.SemiprimeD1WordTapeEnvelopeArithmetic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1OriginalEnvelopeRate\n\n/-! # Fixed local envelope absorbs actual active and tape-leaf components\nAll constants are chosen before the input. This module is pure arithmetic;\nactual program reports are bound to its premises by the counter theorem.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1WordTapeEnvelopeArithmetic\nopen SemiprimeD1OriginalEnvelopeRate SemiprimeD1PackingReady SemiprimeD1Schedule\n\n/-- Active fixed coefficients fit the single uniform local envelope. -/\ntheorem active_raise (A ka B kb s : ℕ) :\n    A*(scalar s+1)^ka*2^(A*degreeCap s) ≤ localEnvelope (A+B+16) (ka+kb+1) s := by\n  unfold localEnvelope\n  apply Nat.mul_le_mul\n  · exact Nat.mul_le_mul (by omega) (Nat.pow_le_pow_right (by omega) (by omega))\n  · apply Nat.pow_le_pow_right (by decide)\n    have h:=Nat.mul_le_mul_right (degreeCap s) (show A ≤ A+B+16 by omega)\n    omega\n\n/-- An executed tape leaf plus every actual native frame control fits the same\nfixed envelope. No desired intermediate width or output value is assumed. -/\ntheorem leaf_control_le (A ka B kb s leaf control : ℕ)\n    (hleaf : leaf ≤ B*(scalar s+1)^kb*2^(B*degreeCap s)*2^leafSize s (logarithm s))\n    (hcontrol : control ≤ 4*scalar s+8) :\n    leaf+control ≤ localEnvelope (A+B+16) (ka+kb+1) s := by\n  let K:=ka+kb+1\n  let C:=A+B+16\n  let base:=(scalar s+1)^K\n  let factor:=2^(C*degreeCap s+leafSize s (logarithm s))\n  have hp : (scalar s+1)^kb ≤ base := Nat.pow_le_pow_right (by omega) (by dsimp only [K];omega)\n  have he : 2^(B*degreeCap s+leafSize s (logarithm s)) ≤ factor := by\n    apply Nat.pow_le_pow_right (by decide)\n    dsimp only [C]\n    have h:=Nat.mul_le_mul_right (degreeCap s) (show B ≤ A+B+16 by omega)\n    omega\n  have hl : leaf ≤ B*base*factor := by\n    calc\n      _ ≤ B*(scalar s+1)^kb*2^(B*degreeCap s)*2^leafSize s (logarithm s) := hleaf\n      _ = B*(scalar s+1)^kb*2^(B*degreeCap s+leafSize s (logarithm s)) := by rw [Nat.mul_assoc,←pow_add]\n      _ ≤ _ := Nat.mul_le_mul (Nat.mul_le_mul_left B hp) he\n  have hbase : scalar s+1 ≤ base := Nat.le_self_pow (by dsimp only [K];omega) _\n  have hfactor : 1 ≤ factor := Nat.one_le_two_pow\n  have hc : control ≤ 8*base*factor := by\n    have h8 : control ≤ 8*(scalar s+1) := by omega\n    calc\n      _ ≤ 8*base := h8.trans (Nat.mul_le_mul_left _ hbase)\n      _ ≤ _ := by simpa only [Nat.mul_one] using Nat.mul_le_mul_left (8*base) hfactor\n  change _ ≤ C*base*factor\n  calc\n    _ ≤ B*base*factor+8*base*factor := Nat.add_le_add hl hc\n    _ = (B+8)*base*factor := by ring\n    _ ≤ _ := Nat.mul_le_mul_right _ (Nat.mul_le_mul_right _ (by dsimp only [C];omega))\n\nend RiemannGaussian.SemiprimeD1WordTapeEnvelopeArithmetic\n","RiemannGaussian.SemiprimeD1WordTapePublicCounter":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WordTapeRecursiveReport\nimport RiemannGaussian.SemiprimeD1PhysicalPublicCounter\nimport RiemannGaussian.SemiprimeD1RootTapeNetwork\n\n/-! # Actual original-input public prefix caller with tape-backed recursion\nEvery query acquires its root and executes the new closed recursion. Only word\nsemantics transfer; its actual setup and recursive reports remain distinct.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1WordTapePublicCounter\nopen SemiprimeBitArithmetic SemiprimePublicAcquiredExecution\nattribute [local irreducible] SemiprimeD1RootTensorTables.acquirePositive\n  SemiprimeD1RootTapeNetwork.acquirePositive SemiprimeD1RootNetwork.acquirePositive\n  SemiprimeD1WordTapeRecursiveCounter.run SemiprimeD1PhysicalRecursiveCounter.run\n\n/-- Actual original-N/prefix root acquisition followed by the new tape recursion. -/\ndef prefixRun (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    SemiprimeD1JetRingBits.Run :=\n  let root:=SemiprimeD1RootTapeNetwork.acquirePositive N hN fixed\n  let s:=SemiprimeD1PublicPackingReady.scale (SemiprimeMacroParameters.bitLength N)\n  let lam:=SemiprimeD1PackingReady.logarithm s\n  let out:=SemiprimeD1WordTapeRecursiveCounter.run s (lam+1) 0\n    SemiprimeD1RootOwnerTables.rootContext root.network\n  ⟨out.words,root.clock+out.clock+10*(wireCount N+fixed.length+SemiprimeMacroParameters.bitLength N+1)⟩\n\n/-- Public words agree literally, with no old/new query-clock identification. -/\ntheorem prefixRun_words_eq_physical (N : ℕ) (hN : 0<N)\n    (fixed : List (Fin (wireCount N)×Bool)) :\n    (prefixRun N hN fixed).words=(SemiprimeD1PhysicalPublicCounter.prefixRun N hN fixed).words := by\n  let s:=SemiprimeD1PublicPackingReady.scale (SemiprimeMacroParameters.bitLength N)\n  let lam:=SemiprimeD1PackingReady.logarithm s\n  have hp : SemiprimeD1RootOwnerTables.rootContext.Positive := by\n    simp [SemiprimeD1JetAxes.Context.Positive,SemiprimeD1RootOwnerTables.rootContext]\n  have he:=SemiprimeD1RootTapeNetwork.acquirePositive_network N hN fixed\n  change (SemiprimeD1WordTapeRecursiveCounter.run s (lam+1) 0\n    SemiprimeD1RootOwnerTables.rootContext (SemiprimeD1RootTapeNetwork.acquirePositive N hN fixed).network).words=\n    (SemiprimeD1PhysicalRecursiveCounter.run s (lam+1) 0\n    SemiprimeD1RootOwnerTables.rootContext (SemiprimeD1RootNetwork.acquirePositive N hN fixed).network).words\n  exact (congrArg (fun net => (SemiprimeD1WordTapeRecursiveCounter.run s (lam+1) 0\n    SemiprimeD1RootOwnerTables.rootContext net).words) he).trans\n    (SemiprimeD1WordTapeRecursiveCounter.run_words_eq_physical s (lam+1) 0 _ _ hp)\n\n/-- Actual two-bit scalar count returned by the new executed query. -/\ndef prefixCount (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) : ℕ :=\n  bitValue (((prefixRun N hN fixed).words[0]?).getD [])\n\n/-- Literal scalar equality, not a supplied conditional-count oracle. -/\ntheorem prefixCount_eq_physical (N : ℕ) (hN : 0<N)\n    (fixed : List (Fin (wireCount N)×Bool)) :\n    prefixCount N hN fixed=SemiprimeD1PhysicalPublicCounter.prefixCount N hN fixed := by\n  unfold prefixCount SemiprimeD1PhysicalPublicCounter.prefixCount\n  rw [prefixRun_words_eq_physical]\n\n/-- Closed original count semantics for every semiprime prefix, including squares. -/\ntheorem prefixCount_exact (N p q : ℕ) (hN : 0<N) (hp : p.Prime) (hq : q.Prime)\n    (hsem : N=p*q) (fixed : List (Fin (wireCount N)×Bool)) :\n    prefixCount N hN fixed=SemiprimeCountRecovery.acceptedCount\n      (SemiprimeCountRecovery.restricted SemiprimeCounterSearch.assignmentBit\n        (indexedPredicate N hN) fixed) :=\n  (prefixCount_eq_physical N hN fixed).trans\n    (SemiprimeD1PhysicalPublicCounter.prefixCount_exact N p q hN hp hq hsem fixed)\n\n/-- Mathematical search specification using this same actual prefix value. -/\ndef search (N : ℕ) (hN : 0<N) : SemiprimeCountRecovery.SearchResult (Fin (wireCount N)) :=\n  SemiprimeCountRecovery.search (prefixCount N hN) (List.finRange (wireCount N))\n\n/-- Exact search data and query counter, without transferring report fields. -/\ntheorem search_eq_physical (N : ℕ) (hN : 0<N) :\n    search N hN=SemiprimeD1PhysicalPublicCounter.search N hN := by\n  have he : prefixCount N hN=SemiprimeD1PhysicalPublicCounter.prefixCount N hN :=\n    funext (prefixCount_eq_physical N hN)\n  exact congrArg (fun count => SemiprimeCountRecovery.search count (List.finRange (wireCount N))) he\n\n/-- Original linear query count for the actual new prefix values. -/\ntheorem search_queries (N : ℕ) (hN : 0<N) : (search N hN).queries ≤ wireCount N+1 := by\n  rw [search_eq_physical]\n  exact SemiprimeD1PhysicalPublicCounter.search_queries N hN\n\nend RiemannGaussian.SemiprimeD1WordTapePublicCounter\n","RiemannGaussian.SemiprimeDistinctAcquisitionObstruction":"import RiemannGaussian.SemiprimePartnerAcquisitionObstruction\nimport Mathlib.LinearAlgebra.Matrix.Rank\nimport Mathlib.RingTheory.Polynomial.Cyclotomic.Factorization\n\n/-!\n# Finite kernels for distinct-tag acquisition obstructions\n\nAn integer multiplication matrix whose reduction has a kernel of\ndimension at least f has determinant divisible by p^f. Invertible\nresidue-field transformations and their integer lifts are constructed\ninternally. Cyclotomic component degrees equal the hidden prime's\npublic residue order; a finite union bounds the small-order classes.\n\nThe original quotient-row giant exponent, weighted hit polynomial,\ntrue-tag specialization and literal centered lift retain their exact\ninteger source. These identities support the journal's all-local-hit\nsmall-weight obstruction and honest three-term Gauss obstruction.\n\nThe actual-input density counts, cyclotomic Gauss norm construction,\nCRT kernel-dimension implication and norm-size estimates remain\nclassical. No analytic or coverage premise is introduced as an axiom.\nThe complete guaranteed one-sixth factorization and bit clock remain open.\n-/\n\nnamespace RiemannGaussian.SemiprimeDistinctAcquisitionObstruction\n\nopen scoped BigOperators\nopen Matrix\n\n/-- Every prime-divisible integer row supplies one factor of that prime\nin the integer determinant, retaining its full multiplicity. -/\ntheorem prime_rows_det_power_dvd {n : ℕ} (A : Matrix (Fin n) (Fin n) ℤ)\n    (p : ℤ) (F : Finset (Fin n))\n    (hrows : ∀ i ∈ F, ∀ j, p ∣ A i j) : p^F.card ∣ A.det := by\n  classical\n  let B : Matrix (Fin n) (Fin n) ℤ := fun i j => if i ∈ F then A i j/p else A i j\n  have hfactor : A=diagonal (fun i => if i ∈ F then p else 1)*B := by\n    ext i j\n    rw [diagonal_mul]\n    dsimp only [B]\n    by_cases hi : i ∈ F\n    · simp only [ite_eq_left hi]\n      exact (Int.mul_ediv_cancel' (hrows i hi j)).symm\n    · simp only [ite_eq_right hi,one_mul]\n  have hprod : (∏ i : Fin n, if i ∈ F then p else 1)=p^F.card := by\n    rw [Finset.prod_ite_mem_eq]\n    simp only [Finset.prod_const]\n  rw [hfactor,det_mul,det_diagonal,hprod]\n  exact dvd_mul_right _ _\n\n/-- Integer lifts of invertible row/column transformations preserve the\nprime-power divisibility extracted from their transformed zero rows. -/\ntheorem transformed_prime_rows_det_power_dvd {n : ℕ}\n    (A V U : Matrix (Fin n) (Fin n) ℤ) (p : ℤ) (F : Finset (Fin n))\n    (hV : IsCoprime p V.det) (hU : IsCoprime p U.det)\n    (hrows : ∀ i ∈ F, ∀ j, p ∣ (V*A*U) i j) : p^F.card ∣ A.det := by\n  have hd := prime_rows_det_power_dvd (V*A*U) p F hrows\n  rw [det_mul,det_mul] at hd\n  have h := (hU.pow_left (m:=F.card)).dvd_of_dvd_mul_right hd\n  exact (hV.pow_left (m:=F.card)).dvd_of_dvd_mul_left h\n\n/-- The canonical pointwise lift from a prime residue field to integers. -/\ndef integerLift {p n : ℕ} (A : Matrix (Fin n) (Fin n) (ZMod p)) :\n    Matrix (Fin n) (Fin n) ℤ := fun i j => (A i j).val\n\ntheorem integerLift_map {p n : ℕ} [NeZero p]\n    (A : Matrix (Fin n) (Fin n) (ZMod p)) :\n    (integerLift A).map (Int.castRingHom (ZMod p))=A := by\n  ext i j\n  change (((A i j).val : ℤ) : ZMod p)=A i j\n  simp only [Int.cast_natCast,ZMod.natCast_zmod_val]\n\ntheorem integerLift_det_coprime {p n : ℕ} (hp : p.Prime)\n    (A : Matrix (Fin n) (Fin n) (ZMod p)) (hA : IsUnit A) :\n    IsCoprime (p : ℤ) (integerLift A).det := by\n  let : Fact p.Prime := ⟨hp⟩\n  have hz : ((integerLift A).det : ZMod p)≠0 := by\n    have hdet := (isUnit_iff_isUnit_det A).mp hA\n    rw [Int.cast_det]\n    have hmap : (integerLift A).map (fun z : ℤ => (z : ZMod p))=A := integerLift_map A\n    rw [hmap]\n    exact hdet.ne_zero\n  apply Int.isCoprime_iff_nat_coprime.mpr\n  rw [Int.natAbs_natCast]\n  apply hp.coprime_iff_not_dvd.mpr\n  intro hd\n  exact hz ((ZMod.intCast_zmod_eq_zero_iff_dvd _ p).mpr (Int.natCast_dvd.mpr hd))\n\n/-- A rank deficiency f in reduction modulo p supplies at least f prime\nfactors in the ORIGINAL integer determinant. The residue field\ntransformations are lifted internally; none is an extra premise. -/\ntheorem rank_deficiency_det_prime_power_dvd {p n : ℕ} (hp : p.Prime)\n    (A : Matrix (Fin n) (Fin n) ℤ) :\n    (p : ℤ)^(n-(A.map (Int.castRingHom (ZMod p))).rank) ∣ A.det := by\n  classical\n  let : Fact p.Prime := ⟨hp⟩\n  let M := A.map (Int.castRingHom (ZMod p))\n  obtain ⟨V,U,e,hV,hU,hNormal⟩ := exists_rank_normal_form M\n  let F : Finset (Fin n) := Finset.univ.image\n    fun i : Fin (Fintype.card (Fin n)-M.rank) => e.symm (Sum.inr i)\n  have hcard : F.card=n-M.rank := by\n    rw [Finset.card_image_of_injective]\n    · simp only [Finset.card_univ,Fintype.card_fin]\n    · exact e.symm.injective.comp Sum.inr_injective\n  have hrows : ∀ i ∈ F, ∀ j, (p : ℤ) ∣ (integerLift V*A*integerLift U) i j := by\n    intro i hi j\n    obtain ⟨k,_,rfl⟩ := Finset.mem_image.mp hi\n    apply (ZMod.intCast_zmod_eq_zero_iff_dvd _ p).mp\n    have hmap : (integerLift V*A*integerLift U).map (Int.castRingHom (ZMod p))=\n        V*M*U := by\n      rw [Matrix.map_mul,Matrix.map_mul,integerLift_map,integerLift_map]\n    change ((integerLift V*A*integerLift U).map (Int.castRingHom (ZMod p)))\n      (e.symm (Sum.inr k)) j=0\n    rw [hmap,hNormal]\n    simp only [Matrix.submatrix,Matrix.of_apply,e.apply_symm_apply]\n    cases e j <;> rfl\n  have hd := transformed_prime_rows_det_power_dvd A (integerLift V) (integerLift U)\n    (p : ℤ) F (integerLift_det_coprime hp V hV) (integerLift_det_coprime hp U hU) hrows\n  simpa only [hcard] using hd\n\ntheorem rank_deficiency_at_least_det_prime_power_dvd {p n f : ℕ} (hp : p.Prime)\n    (A : Matrix (Fin n) (Fin n) ℤ)\n    (hf : f≤n-(A.map (Int.castRingHom (ZMod p))).rank) : (p : ℤ)^f ∣ A.det :=\n  (pow_dvd_pow (p : ℤ) hf).trans (rank_deficiency_det_prime_power_dvd hp A)\n\n/-- A residue-field kernel of dimension at least f supplies p^f in the\ninteger determinant. This is the finite matrix contract used by the\ncyclotomic residue-degree argument. -/\ntheorem kernel_dimension_det_prime_power_dvd {p n f : ℕ} [Fact p.Prime]\n    (A : Matrix (Fin n) (Fin n) ℤ)\n    (hf : f≤Module.finrank (ZMod p)\n      (LinearMap.ker (A.map (Int.castRingHom (ZMod p))).mulVecLin)) :\n    (p : ℤ)^f ∣ A.det := by\n  apply rank_deficiency_at_least_det_prime_power_dvd Fact.out A\n  have h := LinearMap.finrank_range_add_finrank_ker\n    (A.map (Int.castRingHom (ZMod p))).mulVecLin\n  rw [Module.finrank_fin_fun] at h\n  change f≤n-Module.finrank (ZMod p)\n    (LinearMap.range (A.map (Int.castRingHom (ZMod p))).mulVecLin)\n  omega\n\nopen scoped BigOperators\nopen Polynomial\n\n/-- Public residues that satisfy some positive exponent at most the\nthreshold. This overcounts all residues of small multiplicative order. -/\nnoncomputable def lowOrderResidues {m : ℕ} [Fact m.Prime] (T : ℕ) : Finset (ZMod m) :=\n  (Finset.range T).biUnion fun r =>\n    ((X : (ZMod m)[X])^(r+1)-C 1).roots.toFinset\n\n/-- Polynomial root counts bound the complete low-order residue union,\nwithout using prime distribution or a primitive-root computation. -/\ntheorem lowOrderResidues_card_le {m : ℕ} [Fact m.Prime] (T : ℕ) :\n    (lowOrderResidues (m:=m) T).card ≤ T^2 := by\n  classical\n  unfold lowOrderResidues\n  apply (Finset.card_biUnion_le).trans\n  calc\n    ∑ r ∈ Finset.range T,\n        (((X : (ZMod m)[X])^(r+1)-C 1).roots.toFinset).card\n      ≤ ∑ _r ∈ Finset.range T, T := by\n        apply Finset.sum_le_sum\n        intro r hr\n        have hdeg := Polynomial.card_roots_X_pow_sub_C\n          (R:=ZMod m) (n:=r+1) (Nat.succ_pos r) (1 : ZMod m)\n        exact (Multiset.toFinset_card_le _).trans\n          (hdeg.trans (by have h := Finset.mem_range.mp hr; omega))\n    _ = T^2 := by simp [pow_two]\n\n/-- Every actual prime residue of small cyclotomic residue degree lies\nin the displayed public union, via its supplied unit modulo m. -/\ntheorem unit_mem_lowOrderResidues {m : ℕ} [Fact m.Prime]\n    (u : (ZMod m)ˣ) (T : ℕ) (hdegree : orderOf u ≤ T) :\n    (u : ZMod m) ∈ lowOrderResidues (m:=m) T := by\n  classical\n  have hpos : 0 < orderOf u := orderOf_pos u\n  have hpow : (u : ZMod m) ^ orderOf u = 1 := by\n    simpa only [Units.val_pow_eq_pow_val, Units.val_one] using\n      congrArg (fun w : (ZMod m)ˣ => (w : ZMod m)) (pow_orderOf_eq_one u)\n  unfold lowOrderResidues\n  apply Finset.mem_biUnion.mpr\n  refine ⟨orderOf u-1, Finset.mem_range.mpr (by omega), ?_⟩\n  apply Multiset.mem_toFinset.mpr\n  apply (Polynomial.mem_roots\n    (X_pow_sub_C_ne_zero (by omega : 0<orderOf u-1+1) (1 : ZMod m))).mpr\n  change ((X : (ZMod m)[X])^(orderOf u-1+1)-C 1).eval (u : ZMod m)=0\n  simp only [eval_sub, eval_pow, eval_X, eval_C,\n    Nat.sub_add_cancel hpos, hpow, sub_self]\n\n/-- The actual degree of every irreducible cyclotomic component is the\npublic multiplicative order of the hidden prime residue modulo m. -/\ntheorem cyclotomic_component_degree {P m : ℕ} [Fact P.Prime]\n    (hcop : P.Coprime m) {F : (ZMod P)[X]}\n    (hfactor : F ∣ cyclotomic m (ZMod P)) (hirr : Irreducible F) :\n    F.natDegree = orderOf (ZMod.unitOfCoprime P hcop) := by\n  simpa only [pow_one] using\n    Polynomial.natDegree_of_dvd_cyclotomic_of_irreducible\n      (p:=P) (f:=1) (by simp : Fintype.card (ZMod P)=P^1) hcop hfactor hirr\n\nopen SemiprimeQuotientRows SemiprimeMaskAcquisitionObstruction\n\n/-- The retained offset of the original signed quotient row. -/\ndef weightedOffset (m j a b : ℤ) : ℤ := a+m*b-2*a*j\n\n/-- The exact original-hit polynomial after fixing both public digits. -/\ndef weightedHitPolynomial (p v K t δ n : ℤ) : ℤ :=\n  K*p^2-(K+v*δ)*p-v*t*n\n\n/-- This exponent is the actual quadratic-row exponent, including its\ninteger centered coefficient, rather than only its lower projection. -/\ntheorem weighted_giantExponent_eq {N m j a b c t : ℤ}\n    (h : quotientRelation N m j a b c t) :\n    giantExponent m j a b c=t*N+weightedOffset m j a b := by\n  rw [giantExponent_eq h]\n  unfold weightedOffset\n  ring\n\n/-- Clearing an actual weighted hit eliminates its signed index while\nretaining the exact multiple of m squared. -/\ntheorem weighted_hit_multiplier_identity\n    (p q m v R j a b t i K : ℤ) (hcofactor : p-1=v*R)\n    (hhit : t*q+weightedOffset m j a b-m^2*i=K*R) :\n    weightedHitPolynomial p v K t (weightedOffset m j a b) (p*q)\n      =-v*p*m^2*i := by\n  have h := hit_multiplier_polynomial_identity p (t*q) m v R\n    (weightedOffset m j a b) i K hcofactor hhit\n  convert h using 1\n  dsimp only [weightedHitPolynomial]\n  ring\n\n/-- The weighted polynomial is fixed by the complete two-digit public\nstate, even when the hit came from a false residue row. -/\ntheorem weighted_hit_multiplier_modEq {m : ℕ}\n    (p q v R j a b t i K n : ℤ) (hcofactor : p-1=v*R)\n    (hhit : t*q+weightedOffset m j a b-(m : ℤ)^2*i=K*R)\n    (hstate : p*q ≡ n [ZMOD (m : ℤ)^2]) :\n    weightedHitPolynomial p v K t (weightedOffset m j a b) n\n      ≡0 [ZMOD (m : ℤ)^2] := by\n  have hs : p*(t*q) ≡ t*n [ZMOD (m : ℤ)^2] := by\n    convert hstate.mul_left t using 1\n    ring\n  have h := hit_multiplier_polynomial_modEq p (t*q) v R\n    (weightedOffset m j a b) i K (t*n) hcofactor hhit hs\n  convert h using 1\n  dsimp only [weightedHitPolynomial]\n  ring\n\n/-- At its own tag the original quotient relation reduces the hit\npolynomial exactly, before any reduction modulo m squared. -/\ntheorem weighted_true_tag_polynomial_identity {N m j a b c t v K : ℤ}\n    (h : quotientRelation N m j a b c t) :\n    weightedHitPolynomial j v K t (weightedOffset m j a b) N\n      =(K+v*a)*j*(j-1)-v*m^2*c := by\n  unfold quotientRelation at h\n  unfold weightedHitPolynomial weightedOffset\n  linear_combination v*h\n\n/-- Shifting the upper public carry changes the ACTUAL centered lift's\nlinear coefficient by the corresponding inverse-tag carry modulo m. -/\ntheorem liftRow_upper_carry_shift {N inverse a t u : ℤ} {m j : ℕ}\n    (hm : 0<m) (hinv : (j : ℤ)*inverse ≡1 [ZMOD m])\n    (hpair : a ≡N*inverse^2*t [ZMOD m]) :\n    t*u ≡-(j : ℤ)*((liftRow (N+(m : ℤ)*u) m j inverse a t).b-\n      (liftRow N m j inverse a t).b) [ZMOD m] := by\n  have hN : N ≡N+(m : ℤ)*u [ZMOD m] := by\n    apply Int.modEq_iff_dvd.mpr\n    exact ⟨u,by ring⟩\n  have hpairNew : a ≡(N+(m : ℤ)*u)*inverse^2*t [ZMOD m] :=\n    hpair.trans ((hN.mul_right (inverse^2)).mul_right t)\n  have h := liftRow_correct hinv hpair\n  have hNew := liftRow_correct hinv hpairNew\n  change quotientRelation N m j a (liftRow N m j inverse a t).b\n    (liftRow N m j inverse a t).c t at h\n  change quotientRelation (N+(m : ℤ)*u) m j a\n    (liftRow (N+(m : ℤ)*u) m j inverse a t).b\n    (liftRow (N+(m : ℤ)*u) m j inverse a t).c t at hNew\n  unfold quotientRelation at h hNew\n  apply Int.modEq_iff_dvd.mpr\n  refine ⟨(liftRow N m j inverse a t).c-\n    (liftRow (N+(m : ℤ)*u) m j inverse a t).c,?_⟩\n  apply mul_left_cancel₀ (by exact_mod_cast hm.ne' : (m : ℤ)≠0)\n  linear_combination hNew-h\n\nend RiemannGaussian.SemiprimeDistinctAcquisitionObstruction\n","RiemannGaussian.SemiprimeGroupCoverage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeGroupSelection\nimport Mathlib.Data.Nat.Log\nimport Mathlib.Data.Nat.Sqrt\n\n/-!\n# Quantitative targets for useful-group coverage\n\nA power of two of size B supplies an arithmetically admissible Hasse order\nwhose cofactor is at most B²+1 when B² ≤ p ≤ B³. Realising that order over\nthe unknown prime and finding a separating public curve remain unproved.\nThe generic collision obstruction includes both equal and inverse channels.\nThis side-investigation algebra is checked in the ordinary library; numerical probes remain optional.\n-/\n\nnamespace RiemannGaussian.SemiprimeGroupCoverage\n\nopen SemiprimeOrderSeparation SemiprimeRoughProjection SemiprimeGroupSelection\nopen scoped BigOperators\n\n/-- The smallest power of two not less than the desired cover width. -/\ndef dyadicDivisor (B : ℕ) : ℕ := 2 ^ Nat.clog 2 B\n\ntheorem dyadicDivisor_bounds {B : ℕ} (hB : 0 < B) :\n    B ≤ dyadicDivisor B ∧ dyadicDivisor B < 2*B := by\n  refine ⟨Nat.le_pow_clog (by decide) B, ?_⟩\n  by_cases hB1 : B = 1\n  · subst B\n    norm_num [dyadicDivisor]\n  · have hBgt : 1 < B := by omega\n    have hc := Nat.clog_pos (by decide : 1 < 2) hBgt\n    have hp := Nat.pow_pred_clog_lt_self (by decide : 1 < 2) hBgt\n    unfold dyadicDivisor\n    rw [← Nat.succ_pred hc.ne', pow_succ]\n    omega\n\n/-- Cofactor of the first D-multiple strictly above p. -/\ndef roundedCofactor (p D : ℕ) : ℕ := p/D+1\n\n/-- Candidate curve order, before any unknown-field realisation. -/\ndef roundedOrder (p D : ℕ) : ℕ := D*roundedCofactor p D\n\ntheorem roundedOrder_interval {p D : ℕ} (hD : 0 < D) :\n    p+1 ≤ roundedOrder p D ∧ roundedOrder p D ≤ p+D := by\n  have hm := Nat.mod_lt p hD\n  have he := Nat.mod_add_div p D\n  unfold roundedOrder roundedCofactor\n  constructor\n  · calc\n      p+1 = D*(p/D)+(p%D+1) := by omega\n      _ ≤ D*(p/D)+D := Nat.add_le_add_left (Nat.succ_le_of_lt hm) _\n      _ = D*(p/D+1) := by ring\n  · calc\n      D*(p/D+1) = p/D*D+D := by ring\n      _ ≤ p+D := Nat.add_le_add_right (Nat.div_mul_le_self p D) D\n\ntheorem roundedCofactor_pos (p D : ℕ) : 0 < roundedCofactor p D := by\n  unfold roundedCofactor\n  exact Nat.succ_pos _\n\ntheorem roundedCofactor_bound {p B D : ℕ}\n    (hB : 0 < B) (hBD : B ≤ D) (hp : p ≤ B^3) :\n    roundedCofactor p D ≤ B^2+1 := by\n  have hd := Nat.div_mul_le_self p D\n  have hm : B*(p/D) ≤ D*(p/D) := Nat.mul_le_mul_right _ hBD\n  have he : B^3 = B*B^2 := by ring\n  unfold roundedCofactor\n  by_contra hn\n  have hlarge : B^2+1 ≤ p/D := by omega\n  have hs := Nat.mul_le_mul_left B hlarge\n  nlinarith\n\n/-- A constructive Hasse-interval arithmetic target. This does not assert\nthat a public curve realising it can be found without the hidden prime. -/\ntheorem dyadic_hasse_order_target {p B : ℕ} (hB : 0 < B)\n    (hlo : B^2 ≤ p) (hhi : p ≤ B^3) :\n    B ≤ dyadicDivisor B ∧ dyadicDivisor B < 2*B ∧\n      0 < roundedCofactor p (dyadicDivisor B) ∧\n      roundedCofactor p (dyadicDivisor B) ≤ B^2+1 ∧\n      p+1 ≤ roundedOrder p (dyadicDivisor B) ∧\n      roundedOrder p (dyadicDivisor B) ≤ p+1+2*Nat.sqrt p := by\n  obtain ⟨hDlo, hDhi⟩ := dyadicDivisor_bounds hB\n  have hD : 0 < dyadicDivisor B := lt_of_lt_of_le hB hDlo\n  obtain ⟨hordlo, hordhi⟩ := roundedOrder_interval (p := p) hD\n  have hs : B ≤ Nat.sqrt p := Nat.le_sqrt'.mpr hlo\n  refine ⟨hDlo, hDhi, roundedCofactor_pos _ _,\n    roundedCofactor_bound hB hDlo hhi, hordlo, ?_⟩\n  omega\n\n/-- Every prime-size range below B³ has a candidate Hasse order with a\nsmall cofactor. Small p use trace zero; larger p use the dyadic target.\nThis is an arithmetic existence theorem, not a curve-generation algorithm. -/\ntheorem exists_hasse_order_small_cofactor {p B : ℕ}\n    (hB : 0 < B) (hp : p ≤ B^3) :\n    ∃ a c : ℕ, 0 < c ∧ c ≤ (B+1)^2 ∧\n      p+1 ≤ 2^a*c ∧ 2^a*c ≤ p+1+2*Nat.sqrt p := by\n  by_cases hlo : p ≤ B^2\n  · refine ⟨0, p+1, Nat.succ_pos _, ?_, ?_, ?_⟩\n    · nlinarith\n    · simp\n    · simp\n  · obtain ⟨_, _, hc, hcB, horderlo, horderhi⟩ :=\n      dyadic_hasse_order_target hB (by omega) hp\n    refine ⟨Nat.clog 2 B, roundedCofactor p (dyadicDivisor B), hc, ?_,\n      horderlo, horderhi⟩\n    exact hcB.trans (by nlinarith)\n\n/-- The smaller factor of a semiprime lies below the cubic width scale. -/\ntheorem smaller_factor_le_cubic_width {p q B : ℕ}\n    (hpq : p ≤ q) (hbudget : p*q ≤ B^6) : p ≤ B^3 := by\n  have hs : p*p ≤ p*q := Nat.mul_le_mul_left p hpq\n  have he : B^6 = B^3*B^3 := by ring\n  rw [he] at hbudget\n  apply (Nat.pow_le_pow_iff_left (by decide : (2 : ℕ) ≠ 0)).mp\n  simpa only [pow_two] using hs.trans hbudget\n\n/-- Arithmetic useful-order targets cover every smaller semiprime factor.\nThe input-dependent public curve and the separating point are still missing. -/\ntheorem semiprime_hasse_order_target {p q B : ℕ}\n    (hB : 0 < B) (hpq : p ≤ q) (hbudget : p*q ≤ B^6) :\n    ∃ a c : ℕ, 0 < c ∧ c ≤ (B+1)^2 ∧\n      p+1 ≤ 2^a*c ∧ 2^a*c ≤ p+1+2*Nat.sqrt p :=\n  exists_hasse_order_small_cofactor hB (smaller_factor_le_cubic_width hpq hbudget)\n\n/-- Once a curve order actually divides this target and the chosen exponent\ncontains D, its residual point order fits the slightly padded cover. -/\ntheorem projected_candidate_order_bound {G : Type*} [Group G]\n    (a : G) {p B D E : ℕ} (hB : 0 < B) (hBD : B ≤ D)\n    (hp : p ≤ B^3) (ha : orderOf a ∣ roundedOrder p D) (hDE : D ∣ E) :\n    orderOf (a^E) ≤ (B+1)^2 := by\n  have hD : 0 < D := lt_of_lt_of_le hB hBD\n  have hc := partial_projection_order_dvd a hD ha hDE\n  have hb := roundedCofactor_bound hB hBD hp\n  have hle := Nat.le_of_dvd (roundedCofactor_pos p D) hc\n  have hpad : B^2+1 ≤ (B+1)^2 := by nlinarith\n  exact hle.trans (hb.trans hpad)\n\n/-- Actual order realisation and separation are distinct requirements.\nNeither is inferred from semiprimality or from Hasse's interval alone. -/\ntheorem candidate_has_separating_cover {G H : Type*}\n    [Group G] [Group H] [Finite G] (a : G) (b : H)\n    {p B D E : ℕ} (hB : 0 < B) (hBD : B ≤ D) (hp : p ≤ B^3)\n    (ha : orderOf a ∣ roundedOrder p D) (hDE : D ∣ E)\n    (hc : (orderOf (a^E)).Coprime (orderOf (b^E)))\n    (hb : orderOf (b^E) ≠ 1) :\n    ∃ j i : ℕ, 1 ≤ j ∧ j ≤ B+1 ∧ i < B+1 ∧\n      (a^E)^((B+1)*j) = (a^E)^i ∧ (b^E)^((B+1)*j) ≠ (b^E)^i := by\n  have hbound := projected_candidate_order_bound a hB hBD hp ha hDE\n  obtain ⟨d, hd, hdB, had, hbd⟩ :=\n    bounded_separating_witness (a^E) (b^E) hc (orderOf_pos _) hbound hb\n  exact partial_witness_in_linear_cover (by omega) hd hdB had hbd\n\n/-- A smaller positive period separates two local groups. Coprimality of\nthe periods is sufficient but unnecessary: a strict inequality suffices. -/\ntheorem smaller_period_separates {G H : Type*} [Group G] [Group H]\n    (a : G) (b : H) (ha : 0 < orderOf a) (hab : orderOf a < orderOf b) :\n    a^(orderOf a) = 1 ∧ b^(orderOf a) ≠ 1 := by\n  refine ⟨pow_orderOf_eq_one a, ?_⟩\n  intro h\n  have hd := orderOf_dvd_of_pow_eq_one h\n  exact (Nat.not_dvd_of_pos_of_lt ha hab) hd\n\n/-- A useful group only needs unequal local periods and a small minimum.\nThis removes the unnecessary coprimality premise from a coverage search. -/\ntheorem unequal_small_periods_have_cover {G H : Type*}\n    [Group G] [Group H] [Finite G] [Finite H] (a : G) (b : H)\n    {B : ℕ} (hB : 0 < B) (hne : orderOf a ≠ orderOf b)\n    (hsmall : min (orderOf a) (orderOf b) ≤ B^2) :\n    ∃ j i : ℕ, 1 ≤ j ∧ j ≤ B ∧ i < B ∧\n      ((a^(B*j) = a^i ∧ b^(B*j) ≠ b^i) ∨\n       (b^(B*j) = b^i ∧ a^(B*j) ≠ a^i)) := by\n  rcases lt_or_gt_of_ne hne with hab | hba\n  · rw [min_eq_left hab.le] at hsmall\n    obtain ⟨hleft, hright⟩ := smaller_period_separates a b (orderOf_pos _) hab\n    obtain ⟨j, i, hj, hjB, hi, hpa, hpb⟩ :=\n      partial_witness_in_linear_cover hB (orderOf_pos _) hsmall hleft hright\n    exact ⟨j, i, hj, hjB, hi, Or.inl ⟨hpa, hpb⟩⟩\n  · rw [min_eq_right hba.le] at hsmall\n    obtain ⟨hleft, hright⟩ := smaller_period_separates b a (orderOf_pos _) hba\n    obtain ⟨j, i, hj, hjB, hi, hpa, hpb⟩ :=\n      partial_witness_in_linear_cover hB (orderOf_pos _) hsmall hleft hright\n    exact ⟨j, i, hj, hjB, hi, Or.inr ⟨hpa, hpb⟩⟩\n\n/-- The smaller period supplies either a baby identity or a cover leaf\nseparated in BOTH x-coordinate orientations. For i=0 the second branch is\na giant identity. This avoids losing the factor to an opposite-sign alias. -/\ntheorem smaller_period_has_two_orientation_cover {G H : Type*}\n    [Group G] [Group H] (a : G) (b : H) {B : ℕ}\n    (hB : 0 < B) (ha : 0 < orderOf a)\n    (hab : orderOf a < orderOf b) (hsmall : orderOf a ≤ B^2) :\n    (orderOf a < B ∧ a^(orderOf a) = 1 ∧ b^(orderOf a) ≠ 1) ∨\n      ∃ j i : ℕ, 1 ≤ j ∧ j ≤ B ∧ i < B ∧\n        a^(B*j)*a^i = 1 ∧ b^(B*j) ≠ b^i ∧ b^(B*j)*b^i ≠ 1 := by\n  obtain ⟨haa, hbb⟩ := smaller_period_separates a b ha hab\n  by_cases hbelow : orderOf a < B\n  · exact Or.inl ⟨hbelow, haa, hbb⟩\n  · let j := orderOf a / B\n    let i := orderOf a % B\n    have hi : i < B := Nat.mod_lt _ hB\n    have hj : 1 ≤ j := Nat.div_pos (by omega) hB\n    have hprod : B*j ≤ orderOf a := by\n      simpa [j, Nat.mul_comm] using Nat.div_mul_le_self (orderOf a) B\n    have hjB : j ≤ B := by nlinarith\n    have he : B*j+i = orderOf a := by\n      simpa [j, i, Nat.add_comm] using Nat.mod_add_div (orderOf a) B\n    have hile : i ≤ B*j := by nlinarith\n    have hBj : B ≤ B*j := by nlinarith\n    have hdiffpos : 0 < B*j-i := by omega\n    have hdifflt : B*j-i < orderOf b :=\n      lt_of_le_of_lt ((Nat.sub_le _ _).trans hprod) hab\n    refine Or.inr ⟨j, i, hj, hjB, hi, ?_, ?_, ?_⟩\n    · rw [← pow_add, he]\n      exact haa\n    · intro halias\n      have hpow : b^(B*j-i) = 1 := by\n        apply mul_right_cancel (b := b^i)\n        rw [← pow_add, Nat.sub_add_cancel hile, halias, one_mul]\n      exact Nat.not_dvd_of_pos_of_lt hdiffpos hdifflt\n        (orderOf_dvd_of_pow_eq_one hpow)\n    · rw [← pow_add, he]\n      exact hbb\n\n/-- Equal periods make every integer-exponent alias coherent across the\ntwo groups, including negative exponents and inverse channels. -/\ntheorem same_period_coherent_aliases {G H : Type*} [Group G] [Group H]\n    (a : G) (b : H) (hab : orderOf a = orderOf b) (i j : ℤ) :\n    a^i = a^j ↔ b^i = b^j := by\n  rw [← orderOf_dvd_sub_iff_zpow_eq_zpow, ← orderOf_dvd_sub_iff_zpow_eq_zpow, hab]\n\n/-- Constant forced torsion cannot alone supply the growing cofactor bound\nwhen the group order is on the cubic scale. This is an arithmetic envelope\nobstruction, not an impossibility theorem for ECM or other algorithms. -/\ntheorem fixed_divisor_cubic_gap {B D : ℕ} (hD : D < B) (hB : 0 < B) :\n    D*B^2 < B^3 := by\n  have hs : 0 < B^2 := pow_pos hB _\n  simpa only [pow_succ, Nat.mul_comm] using Nat.mul_lt_mul_of_pos_right hD hs\n\n/-- A group homomorphism whose kernel is killed by a coprime exponent\npreserves the entire element period. Cheap isogeny-like changes cannot\nshorten a long prime period unless their kernel reaches that prime. -/\ntheorem period_preserved_by_coprime_kernel {G H : Type*} [Group G] [Group H]\n    (f : G →* H) (a : G) {D : ℕ}\n    (hkernel : ∀ x : G, f x = 1 → x^D = 1)\n    (hc : (orderOf a).Coprime D) : orderOf (f a) = orderOf a := by\n  apply Nat.dvd_antisymm\n  · exact orderOf_map_dvd f a\n  · have hm : f (a^(orderOf (f a))) = 1 := by\n      rw [map_pow, pow_orderOf_eq_one]\n    have hp := hkernel _ hm\n    rw [← pow_mul, ← orderOf_dvd_iff_pow_eq_one] at hp\n    exact hc.dvd_of_dvd_mul_right (by simpa [Nat.mul_comm] using hp)\n\n/-- A prime larger than a factorial prefix cannot occur in that prefix. -/\ntheorem prime_not_dvd_factorial_above {q : ℕ} (hq : q.Prime) :\n    ∀ k : ℕ, k < q → ¬q ∣ k.factorial := by\n  intro k\n  induction k with\n  | zero =>\n    intro _\n    simpa using hq.not_dvd_one\n  | succ k ih =>\n    intro hk hd\n    rw [Nat.factorial_succ] at hd\n    rcases hq.dvd_mul.mp hd with hleft | hright\n    · exact Nat.not_dvd_of_pos_of_lt (Nat.succ_pos k) hk hleft\n    · exact ih (by omega) hright\n\n/-- The additive integer-prefix group has unconditional separating\ncoverage when the smaller prime lies in the quadratic cover. Polynomial\nbatching evaluates this prefix without materialising the factorial. -/\ntheorem factorial_prefix_recovers_smaller_prime {p q B : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hsmall : p ≤ B^2) (hlarge : B^2 < q) :\n    (p*q).gcd ((B^2).factorial) = p := by\n  apply gcd_semiprime_of_separating_residue hq\n  · exact Nat.dvd_factorial hp.pos hsmall\n  · exact prime_not_dvd_factorial_above hq _ hlarge\n\ntheorem sixth_budget_above_quadratic_prefix {B : ℕ} (hB : 4 ≤ B) :\n    B^4 < (B-1)^6 := by\n  have hk : 3 ≤ B-1 := by omega\n  have he : B = (B-1)+1 := by omega\n  have hsq : B^2 ≤ 2*(B-1)^2 := by\n    rw [he]\n    simp only [Nat.add_sub_cancel]\n    nlinarith\n  have hfour := Nat.mul_le_mul hsq hsq\n  have hfour' : B^4 ≤ 4*(B-1)^4 := by convert hfour using 1 <;> ring\n  have hgt : 4 < (B-1)^2 := by nlinarith\n  have hp : 0 < (B-1)^4 := pow_pos (by omega) _\n  have hlast := Nat.mul_lt_mul_of_pos_right hgt hp\n  have hlast' : 4*(B-1)^4 < (B-1)^6 := by convert hlast using 1; ring\n  exact hfour'.trans_lt hlast'\n\n/-- For the actual ceiling-sixth-root budget, the larger factor is outside\nthe quadratic prefix, so the prefix automatically separates the small one. -/\ntheorem larger_factor_above_prefix {p q B : ℕ} (hB : 4 ≤ B)\n    (hpq : p ≤ q) (hbudget : (B-1)^6 < p*q) : B^2 < q := by\n  by_contra hn\n  have hq : q ≤ B^2 := by omega\n  have hp := hpq.trans hq\n  have hprod := Nat.mul_le_mul hp hq\n  have hprod' : p*q ≤ B^4 := by convert hprod using 1; ring\n  have hgap := sixth_budget_above_quadratic_prefix hB\n  omega\n\ntheorem prefix_recovers_under_sixth_budget {p q B : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hB : 4 ≤ B) (hpq : p ≤ q)\n    (hbudget : (B-1)^6 < p*q) (hsmall : p ≤ B^2) :\n    (p*q).gcd ((B^2).factorial) = p :=\n  factorial_prefix_recovers_smaller_prime hp hq hsmall\n    (larger_factor_above_prefix hB hpq hbudget)\n\n/-- Degree-B polynomial evaluation at a positive block endpoint. -/\ntheorem descending_block_eq_polynomial (n : ℕ) :\n    ∀ B : ℕ, n.descFactorial B = ∏ i ∈ Finset.range B, (n-i)\n  | 0 => by simp\n  | B+1 => by\n    rw [Nat.descFactorial, Finset.prod_range_succ_comm, descending_block_eq_polynomial n B]\n\ntheorem prefix_rows_eq_factorial (B : ℕ) :\n    ∀ J : ℕ, (∏ j ∈ Finset.range J, (B*(j+1)).descFactorial B) = (B*J).factorial\n  | 0 => by simp\n  | J+1 => by\n    rw [Finset.prod_range_succ, prefix_rows_eq_factorial B J]\n    have hB : B ≤ B*(J+1) := by nlinarith\n    have he : B*(J+1)-B = B*J := by\n      rw [Nat.mul_add, Nat.mul_one, Nat.add_sub_cancel]\n    simpa only [he] using Nat.factorial_mul_descFactorial hB\n\n/-- The joined B-by-B integer cover evaluated by polynomial batching. -/\ndef prefixProduct (B : ℕ) : ℕ :=\n  ∏ j ∈ Finset.range B, (B*(j+1)).descFactorial B\n\ntheorem prefixProduct_eq_factorial (B : ℕ) : prefixProduct B = (B^2).factorial := by\n  simpa only [prefixProduct, pow_two] using prefix_rows_eq_factorial B B\n\n/-- A guaranteed separating prefix, with every degree-B row retained.\nThe identity supplies coverage, not a formal bit-cost theorem for the\nPython product/remainder-tree implementation. -/\ntheorem polynomial_prefix_recovers_under_sixth_budget {p q B : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hB : 4 ≤ B) (hpq : p ≤ q)\n    (hbudget : (B-1)^6 < p*q) (hsmall : p ≤ B^2) :\n    (p*q).gcd (prefixProduct B) = p := by\n  rw [prefixProduct_eq_factorial]\n  exact prefix_recovers_under_sixth_budget hp hq hB hpq hbudget hsmall\n\n/-- A failed complete prefix rules out all small prime factors. This\ncertifies exactly which population still needs useful curve coverage. -/\ntheorem failed_prefix_excludes_small_prime {n p B : ℕ}\n    (hp : p.Prime) (hpn : p ∣ n) (hclear : n.gcd ((B^2).factorial) = 1) :\n    B^2 < p := by\n  by_contra hn\n  have hd := Nat.dvd_factorial hp.pos (by omega : p ≤ B^2)\n  have hboth := Nat.dvd_gcd hpn hd\n  rw [hclear] at hboth\n  exact hp.not_dvd_one hboth\n\ntheorem counterexample_semiprime_and_budget :\n    Nat.Prime 248909 ∧ Nat.Prime 249521 ∧\n      248909*249521 = (62108022589 : ℕ) ∧\n      62^6 < (62108022589 : ℕ) ∧ (62108022589 : ℕ) ≤ 63^6 := by\n  norm_num\n\n/-- A second implementation control lies outside both the quadratic\nsmall-factor prefix and the allotted near-square window. These arithmetic\nchecks do not verify the whole Python ECM pipeline. -/\ntheorem separated_control_semiprime_and_windows :\n    Nat.Prime 203653 ∧ Nat.Prime 230003 ∧\n      203653*230003 = (46840800959 : ℕ) ∧\n      60^6 < (46840800959 : ℕ) ∧ (46840800959 : ℕ) ≤ 61^6 ∧\n      61^2 < (203653 : ℕ) ∧\n      216427^2 < (46840800959 : ℕ) ∧ (46840800959 : ℕ) ≤ 216428^2 ∧\n      203653+230003 = 2*(216828 : ℕ) ∧\n      (216428+61)^2 < (216828 : ℕ)^2 := by\n  norm_num\n\n/-- Observed residual periods; these constants are not asserted to be\nelliptic point orders without a separate group-law certificate. -/\ndef counterexamplePeriods : List ℕ :=\n  [5189, 20789, 20773, 20753, 20719, 20873, 5189, 6949]\n\ntheorem counterexample_periods_above_cover :\n    ∀ d ∈ counterexamplePeriods, 63^2+63 < d := by\n  simp only [counterexamplePeriods, List.mem_cons]\n  norm_num\n\n/-- Under an actual period certificate, neither orientation of any cover\nleaf can vanish. Includes every smaller probe width. -/\ntheorem counterexample_periods_miss_every_stage {B d i j : ℕ}\n    (hB : 0 < B) (hcap : B ≤ 63) (hd : d ∈ counterexamplePeriods)\n    (hi : i < B) (hj : 0 < j) (hjB : j ≤ B) :\n    ¬d ∣ B*j-i ∧ ¬d ∣ B*j+i := by\n  have hs : B^2 ≤ 63^2 := Nat.pow_le_pow_left hcap 2\n  have hlarge := counterexample_periods_above_cover d hd\n  exact long_order_outside_linear_cover hB hi hj hjB (by omega)\n\ntheorem sigma13_recovery_certificate :\n    checkedSignal 62108022589 35762846846 = some 249521 := by\n  norm_num [checkedSignal]\n\nend RiemannGaussian.SemiprimeGroupCoverage\n","RiemannGaussian.SemiprimeLongPowerRouting":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeKernelDescent\nimport RiemannGaussian.SemiprimeLongPeriodExtraction\n\n/-!\n# Public power refinement and exact long-order decoding\n\nRetain the two long coprime local periods. A known global order would\ndetermine the literal factor sum, but is not supplied to the public\nrefinement. Two additional short batches use the public N and N+1 powers.\nTheir failed outcomes preserve the original long carrier and certify\nadditional coprimality. The final linear-source extractor and complete\none-sixth bit bound remain open.\n-/\n\nnamespace RiemannGaussian.SemiprimeLongPowerRouting\n\nopen SemiprimeGroupSelection SemiprimeLocalOrderRouting SemiprimeCentreFreeCover\n\n/-- Retain the original long-period, coprime and rough local information. -/\ndef CoreData (p q B : ℕ) (h : (ZMod (p*q))ˣ) : Prop :=\n  LocalLong h (2*B) ∧\n    (orderOf (leftUnit h)).Coprime (orderOf (rightUnit h)) ∧\n    (∀ r, r.Prime → r∣orderOf (leftUnit h) → B<r) ∧\n    (∀ r, r.Prime → r∣orderOf (rightUnit h) → B<r)\n\n/-- The actual public projected unit supplies the complete retained core. -/\ntheorem projected_core {p q B : ℕ} (g : (ZMod (p*q))ˣ) (hd : LongData g B) :\n    CoreData p q B (SemiprimeCentreFreeCover.projectedUnit g B) :=\n  ⟨hd.2.2.2.1,hd.2.2.2.2⟩\n\n/-- The retained projected unit has the literal public scalar value;\nthis view keeps the original unit available for later channels. -/\ntheorem projectedUnit_val {N : ℕ} (g : (ZMod N)ˣ) (B : ℕ) :\n    (projectedUnit g B : ZMod N)=\n      ((g : ZMod N)^(N-1))^((B.factorial)^(Nat.clog 2 (N+1))) := by\n  simp only [projectedUnit,Units.val_pow_eq_pow_val]\n\n/-- Prime-field orders divide their literal group cardinalities. -/\ntheorem local_card_divisors {p q : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (h : (ZMod (p*q))ˣ) :\n    orderOf (leftUnit h)∣p-1 ∧ orderOf (rightUnit h)∣q-1 := by\n  let : Fact p.Prime := ⟨hp⟩\n  let : Fact q.Prime := ⟨hq⟩\n  exact ⟨ZMod.orderOf_units_dvd_card_sub_one _,ZMod.orderOf_units_dvd_card_sub_one _⟩\n\n/-- Long local periods give public lower bounds for both prime factors. -/\ntheorem local_card_bounds {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (h : (ZMod (p*q))ˣ) (hl : LocalLong h (2*B)) :\n    (2*B)^2<p-1 ∧ (2*B)^2<q-1 := by\n  have hd := local_card_divisors hp hq h\n  exact ⟨hl.1.trans_le (Nat.le_of_dvd (by have hh:=hp.one_lt; omega) hd.1),\n    hl.2.trans_le (Nat.le_of_dvd (by have hh:=hq.one_lt; omega) hd.2)⟩\n\n/-- The long-period complement also has a small literal factor sum. -/\ntheorem factor_sum_bound {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hB : 0<B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hl : LocalLong h (2*B)) : p+q≤2*B^4 := by\n  have hb2 : 0<B^2 := pow_pos hB 2\n  obtain ⟨hP,hQ⟩ := local_card_bounds hp hq h hl\n  have hpB : B^2≤p := by\n    have hh : p-1<p := by omega\n    nlinarith\n  have hqB : B^2≤q := by\n    have hh : q-1<q := by omega\n    nlinarith\n  have he : B^6=B^4*B^2 := by ring\n  have hpup : p≤B^4 := by\n    have hm : p*B^2≤B^4*B^2 :=\n      (Nat.mul_le_mul_left p hqB).trans (he ▸ hbudget)\n    nlinarith\n  have hqup : q≤B^4 := by\n    have hm : q*B^2≤B^4*B^2 := by\n      calc q*B^2≤q*p := Nat.mul_le_mul_left q hpB\n           _=p*q := Nat.mul_comm _ _\n           _≤B^4*B^2 := he ▸ hbudget\n    nlinarith\n  omega\n\n/-- Coprime long periods make the global order a divisor of the actual\ntotient, strictly exceeding the factor sum. This is proof-side information. -/\ntheorem global_order_totient_and_sum {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≠q) (hB : 0<B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hl : LocalLong h (2*B))\n    (hc : (orderOf (leftUnit h)).Coprime (orderOf (rightUnit h))) :\n    orderOf h∣(p-1)*(q-1) ∧ p+q<orderOf h := by\n  have he := global_order_eq_lcm hp hq hpq h\n  rw [hc.lcm_eq_mul] at he\n  have hd := local_card_divisors hp hq h\n  constructor\n  · rw [he]\n    exact Nat.mul_dvd_mul hd.1 hd.2\n  · have hn : 0<orderOf (rightUnit h) := orderOf_pos _\n    have hm : 16*B^4<orderOf (leftUnit h)*orderOf (rightUnit h) := by\n      calc 16*B^4=(2*B)^2*(2*B)^2 := by ring\n           _≤(2*B)^2*orderOf (rightUnit h) := Nat.mul_le_mul_left _ hl.2.le\n           _<orderOf (leftUnit h)*orderOf (rightUnit h) :=\n             Nat.mul_lt_mul_of_pos_right hl.1 hn\n    have hsum := factor_sum_bound hp hq hB hbudget h hl\n    rw [he]\n    have hb4 : 0<B^4 := pow_pos hB 4\n    omega\n\n/-- Retain the exact integer factor-sum encoding from a supplied modulus. -/\ndef sumSignal (N m : ℕ) : ℕ := (N+1)%m\n\n/-- A large known divisor of the totient determines the literal factor sum. -/\ntheorem sumSignal_eq_sum {p q m : ℕ} (hp : 1<p) (hq : 1<q)\n    (hd : m∣(p-1)*(q-1)) (hs : p+q<m) : sumSignal (p*q) m=p+q := by\n  have he : p*q+1=(p-1)*(q-1)+(p+q) := by\n    have hP := Nat.sub_add_cancel hp.le\n    have hQ := Nat.sub_add_cancel hq.le\n    nlinarith\n  unfold sumSignal\n  rw [he,Nat.add_mod,Nat.mod_eq_zero_of_dvd hd,zero_add,\n    Nat.mod_eq_of_lt hs,Nat.mod_eq_of_lt hs]\n\n/-- Public quadratic candidate from the retained factor-sum signal. -/\ndef sumCandidate (N m : ℕ) : ℕ :=\n  let s := sumSignal N m\n  (s-(s^2-4*N).sqrt)/2\n\n/-- The candidate recovers the smaller prime exactly when its sum is known. -/\ntheorem sumCandidate_of_sum {p q m : ℕ} (hpq : p≤q)\n    (hs : sumSignal (p*q) m=p+q) : sumCandidate (p*q) m=p := by\n  unfold sumCandidate\n  rw [hs]\n  dsimp only\n  rw [SemiprimeCommonOrder.index_discriminant_square hpq,Nat.sqrt_eq']\n  have he := Nat.sub_add_cancel hpq\n  omega\n\n/-- Independently check the single factor-sum candidate before returning it. -/\ndef recoverKnownOrder (N m : ℕ) : Option ℕ := checkedSignal N (sumCandidate N m)\n\n/-- The decoder never returns an improper divisor, even for an incorrect modulus. -/\ntheorem recoverKnownOrder_sound {N m d : ℕ} (hd : recoverKnownOrder N m=some d) :\n    ProperDivisor N d := checkedSignal_sound hd\n\n/-- An actual known global long order gives one direct quadratic recovery.\nAcquiring that order is a charged frontier, not an input to the public router. -/\ntheorem recoverKnownOrder_of_long {p q B m : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p<q) (hB : 0<B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hl : LocalLong h (2*B))\n    (hc : (orderOf (leftUnit h)).Coprime (orderOf (rightUnit h)))\n    (hm : orderOf h=m) : recoverKnownOrder (p*q) m=some p := by\n  obtain ⟨hd,hs⟩ := global_order_totient_and_sum hp hq hpq.ne hB hbudget h hl hc\n  rw [hm] at hd hs\n  have he := sumCandidate_of_sum hpq.le (sumSignal_eq_sum hp.one_lt hq.one_lt hd hs)\n  have hg : (p*q).gcd p=p := Nat.gcd_eq_right (dvd_mul_right p q)\n  unfold recoverKnownOrder\n  rw [he,checkedSignal,hg,ite_eq_left]\n  exact ⟨hp.one_lt,by nlinarith [hp.pos,hq.one_lt]⟩\n\n/-- The public successor exponent cannot annihilate both long coprime channels. -/\ntheorem successor_power_ne_one {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≠q) (hB : 0<B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hl : LocalLong h (2*B))\n    (hc : (orderOf (leftUnit h)).Coprime (orderOf (rightUnit h))) : h^(p*q+1)≠1 := by\n  obtain ⟨hd,hs⟩ := global_order_totient_and_sum hp hq hpq hB hbudget h hl hc\n  intro he\n  have hm := orderOf_dvd_of_pow_eq_one he\n  have hsum : orderOf h∣p+q := by\n    have hid : p*q+1=(p-1)*(q-1)+(p+q) := by\n      have hP := Nat.sub_add_cancel hp.one_lt.le\n      have hQ := Nat.sub_add_cancel hq.one_lt.le\n      nlinarith\n    rw [hid] at hm\n    exact (Nat.dvd_add_iff_right hd).mpr hm\n  have hpos : 0<p+q := by omega\n  exact (not_le_of_gt hs) (Nat.le_of_dvd hpos hsum)\n\n/-- If one local period contains the other prime, the public N power\nkeeps one long channel and reduces the other inside the quadratic short\ncover. Both original group cardinalities and the input budget are charged. -/\ntheorem cross_power_order_bounds {G H : Type*} [Group G] [Finite G] [Group H] [Finite H]\n    {p q B : ℕ} (hp : p.Prime) (hq : q.Prime) (hbudget : p*q≤B^6)\n    (a : G) (b : H) (hda : orderOf a∣p-1) (hdb : orderOf b∣q-1)\n    (hla : (2*B)^2<orderOf a) (hcross : p∣orderOf b) :\n    (2*B)^2<orderOf (a^(p*q)) ∧ orderOf (b^(p*q))≤B^2 := by\n  have haPos := orderOf_pos a\n  have hbPos := orderOf_pos b\n  have hpCard : 0<p-1 := by have hh:=hp.one_lt; omega\n  have hqCard : 0<q-1 := by have hh:=hq.one_lt; omega\n  have haLe := Nat.le_of_dvd hpCard hda\n  have hbLe := Nat.le_of_dvd hqCard hdb\n  have hpLe := Nat.le_of_dvd hbPos hcross\n  have hpq : p<q := by omega\n  have haP : orderOf a<p := by omega\n  have haQ : orderOf a<q := haP.trans hpq\n  have hcP : (orderOf a).Coprime p :=\n    (hp.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt haPos haP)).symm\n  have hcQ : (orderOf a).Coprime q :=\n    (hq.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt haPos haQ)).symm\n  have he := (hcP.mul_right hcQ).orderOf_pow\n  constructor\n  · rw [he]\n    exact hla\n  · have hdCard : p∣q-1 := hcross.trans hdb\n    have hafter := SemiprimeOrderSeparation.order_pow_dvd_quotient b hdb hdCard\n      (dvd_mul_right p q)\n    have hquotPos : 0<(q-1)/p := Nat.div_pos (Nat.le_of_dvd hqCard hdCard) hp.pos\n    have hafterLe := Nat.le_of_dvd hquotPos hafter\n    have hpB : B^2≤p := by\n      have hh : p-1<p := by omega\n      nlinarith\n    have hs : B^6≤p*p*B^2 := by\n      calc B^6=(B^2*B^2)*B^2 := by ring\n           _≤(p*p)*B^2 := Nat.mul_le_mul_right _ (Nat.mul_le_mul hpB hpB)\n    have hqp : q≤p*B^2 := by nlinarith [hp.pos]\n    have hquot : (q-1)/p≤B^2 := by\n      calc (q-1)/p≤(p*B^2)/p := Nat.div_le_div_right ((Nat.sub_le q 1).trans hqp)\n           _=B^2 := Nat.mul_div_cancel_left _ hp.pos\n    exact hafterLe.trans hquot\n\n/-- Either orientation of a cross-prime period is recovered by the N batch. -/\ntheorem recover_N_of_cross {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hB : 0<B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hl : LocalLong h (2*B))\n    (hcross : p∣orderOf (rightUnit h) ∨ q∣orderOf (leftUnit h)) :\n    ∃ d, recoverShort (h^(p*q)) (2*B)=some d := by\n  obtain ⟨hda,hdb⟩ := local_card_divisors hp hq h\n  have hP : leftUnit (h^(p*q))=(leftUnit h)^(p*q) := by simp only [leftUnit,map_pow]\n  have hQ : rightUnit (h^(p*q))=(rightUnit h)^(p*q) := by simp only [rightUnit,map_pow]\n  apply recoverShort_of_unequal hp hq _ (by omega)\n  · rcases hcross with hc | hc\n    · obtain ⟨hleft,hright⟩ := cross_power_order_bounds hp hq hbudget\n        (leftUnit h) (rightUnit h) hda hdb hl.1 hc\n      rw [hP,hQ]\n      intro he\n      rw [he] at hleft\n      nlinarith\n    · obtain ⟨hright,hleft⟩ := cross_power_order_bounds hq hp\n        (by simpa only [Nat.mul_comm q p] using hbudget)\n        (rightUnit h) (leftUnit h) hdb hda hl.2 hc\n      rw [Nat.mul_comm q p] at hright hleft\n      rw [hP,hQ]\n      intro he\n      rw [he] at hleft\n      nlinarith\n  · rcases hcross with hc | hc\n    · have hs := (cross_power_order_bounds hp hq hbudget\n        (leftUnit h) (rightUnit h) hda hdb hl.1 hc).2\n      rw [hP,hQ]\n      have hm := (min_le_right (orderOf ((leftUnit h)^(p*q)))\n        (orderOf ((rightUnit h)^(p*q)))).trans hs\n      nlinarith\n    · have hs := (cross_power_order_bounds hq hp\n        (by simpa only [Nat.mul_comm q p] using hbudget)\n        (rightUnit h) (leftUnit h) hdb hda hl.2 hc).2\n      rw [Nat.mul_comm q p] at hs\n      rw [hP,hQ]\n      have hm := (min_le_left (orderOf ((leftUnit h)^(p*q)))\n        (orderOf ((rightUnit h)^(p*q)))).trans hs\n      nlinarith\n\n/-- A failed N batch excludes both cross-prime periods and makes the\nglobal order coprime to N. The original two channels remain retained. -/\ntheorem failed_N_forces_coprime {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≠q) (hB : 0<B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hl : LocalLong h (2*B)) (hnone : recoverShort (h^(p*q)) (2*B)=none) :\n    (orderOf h).Coprime (p*q) := by\n  have hpOne := hp.one_lt\n  have hqOne := hq.one_lt\n  have hnot : ¬(p∣orderOf (rightUnit h) ∨ q∣orderOf (leftUnit h)) := by\n    intro hc\n    obtain ⟨d,hd⟩ := recover_N_of_cross hp hq hB hbudget h hl hc\n    rw [hnone] at hd\n    contradiction\n  obtain ⟨hda,hdb⟩ := local_card_divisors hp hq h\n  have hpa : ¬p∣orderOf (leftUnit h) := by\n    have hle := Nat.le_of_dvd (show 0<p-1 by have hh:=hp.one_lt; omega) hda\n    exact Nat.not_dvd_of_pos_of_lt (orderOf_pos _) (by omega)\n  have hqb : ¬q∣orderOf (rightUnit h) := by\n    have hle := Nat.le_of_dvd (show 0<q-1 by have hh:=hq.one_lt; omega) hdb\n    exact Nat.not_dvd_of_pos_of_lt (orderOf_pos _) (by omega)\n  have hqa : ¬q∣orderOf (leftUnit h) := fun hc => hnot (Or.inr hc)\n  have hpb : ¬p∣orderOf (rightUnit h) := fun hc => hnot (Or.inl hc)\n  have hcA : (orderOf (leftUnit h)).Coprime (p*q) :=\n    (hp.coprime_iff_not_dvd.mpr hpa).symm.mul_right\n      (hq.coprime_iff_not_dvd.mpr hqa).symm\n  have hcB : (orderOf (rightUnit h)).Coprime (p*q) :=\n    (hp.coprime_iff_not_dvd.mpr hpb).symm.mul_right\n      (hq.coprime_iff_not_dvd.mpr hqb).symm\n  rw [global_order_eq_lcm hp hq hpq h]\n  exact (hcA.mul_left hcB).of_dvd_left (Nat.lcm_dvd_mul _ _)\n\n/-- Two coprime powered local orders cannot be equal when the powered\nglobal unit is nontrivial. This retains both fields through the CRT step. -/\ntheorem powered_orders_unequal {p q E : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≠q) (h : (ZMod (p*q))ˣ)\n    (hc : (orderOf (leftUnit h)).Coprime (orderOf (rightUnit h)))\n    (hne : h^E≠1) : orderOf (leftUnit (h^E))≠orderOf (rightUnit (h^E)) := by\n  have hP : leftUnit (h^E)=(leftUnit h)^E := by simp only [leftUnit,map_pow]\n  have hQ : rightUnit (h^E)=(rightUnit h)^E := by simp only [rightUnit,map_pow]\n  have hcop : (orderOf (leftUnit (h^E))).Coprime (orderOf (rightUnit (h^E))) := by\n    rw [hP,hQ]\n    exact hc.of_dvd (orderOf_pow_dvd E) (orderOf_pow_dvd E)\n  intro he\n  rw [←he,Nat.coprime_self] at hcop\n  have hg := global_order_eq_lcm hp hq hpq (h^E)\n  rw [←he,Nat.lcm_self,hcop] at hg\n  exact hne (orderOf_eq_one_iff.mp hg)\n\n/-- A rough prime shared by a powering exponent and a cubic-bounded\nfield cardinality reduces that field inside the short quadratic cover. -/\ntheorem small_card_power_bound {G : Type*} [Group G]\n    {p B r E : ℕ} (hp : 1<p) (hB : 0<B) (hpB : p≤B^3)\n    (a : G) (hda : orderOf a∣p-1) (hr : B<r) (hrd : r∣orderOf a) (hrE : r∣E) :\n    orderOf (a^E)≤B^2 := by\n  have hrCard := hrd.trans hda\n  have hpCard : 0<p-1 := by omega\n  have hquotPos : 0<(p-1)/r :=\n    Nat.div_pos (Nat.le_of_dvd hpCard hrCard) (by omega)\n  have hafter := SemiprimeOrderSeparation.order_pow_dvd_quotient a hda hrCard hrE\n  have hle := Nat.le_of_dvd hquotPos hafter\n  have hpr : p≤r*B^2 := by\n    have hs : B^3≤r*B^2 := by\n      calc B^3=B*B^2 := by ring\n           _≤r*B^2 := Nat.mul_le_mul_right _ hr.le\n    exact hpB.trans hs\n  have hquot : (p-1)/r≤B^2 := by\n    calc (p-1)/r≤(r*B^2)/r := Nat.div_le_div_right ((Nat.sub_le p 1).trans hpr)\n         _=B^2 := Nat.mul_div_cancel_left _ (by omega)\n  exact hle.trans hquot\n\n/-- Failure of the N+1 batch forces the smaller field's retained period\nto be coprime to that public exponent, in either prime orientation. -/\ntheorem failed_successor_forces_min_coprime {p q B : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hB : 0<B)\n    (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ) (hcore : CoreData p q B h)\n    (hnone : recoverShort (h^(p*q+1)) (2*B)=none) :\n    (p≤q → (orderOf (leftUnit h)).Coprime (p*q+1)) ∧\n    (q≤p → (orderOf (rightUnit h)).Coprime (p*q+1)) := by\n  obtain ⟨hda,hdb⟩ := local_card_divisors hp hq h\n  have hne := powered_orders_unequal hp hq hpq h hcore.2.1\n    (successor_power_ne_one hp hq hpq hB hbudget h hcore.1 hcore.2.1)\n  have hP : leftUnit (h^(p*q+1))=(leftUnit h)^(p*q+1) := by simp only [leftUnit,map_pow]\n  have hQ : rightUnit (h^(p*q+1))=(rightUnit h)^(p*q+1) := by simp only [rightUnit,map_pow]\n  have hmin : (2*B)^2<min (orderOf (leftUnit (h^(p*q+1))))\n      (orderOf (rightUnit (h^(p*q+1)))) := by\n    by_contra hn\n    obtain ⟨d,hd⟩ := recoverShort_of_unequal (b:=2*B) hp hq _ (by omega) hne (by omega)\n    rw [hnone] at hd\n    contradiction\n  constructor\n  · intro horder\n    by_contra hn\n    obtain ⟨r,hr,hrd,hrE⟩ := Nat.Prime.not_coprime_iff_dvd.mp hn\n    have hpB : p≤B^3 := by\n      have hs := SemiprimeLongPeriodExtraction.smaller_factor_group_budget horder hbudget\n      omega\n    have hs := small_card_power_bound hp.one_lt hB hpB (leftUnit h) hda\n      (hcore.2.2.1 r hr hrd) hrd hrE\n    rw [hP,hQ] at hmin\n    have hm := hmin.trans_le (min_le_left _ _)\n    nlinarith\n  · intro horder\n    by_contra hn\n    obtain ⟨r,hr,hrd,hrE⟩ := Nat.Prime.not_coprime_iff_dvd.mp hn\n    have hqB : q≤B^3 := by\n      have hs := SemiprimeLongPeriodExtraction.smaller_factor_group_budget horder\n        (by simpa only [Nat.mul_comm q p] using hbudget)\n      omega\n    have hs := small_card_power_bound hq.one_lt hB hqB (rightUnit h) hdb\n      (hcore.2.2.2 r hr hrd) hrd hrE\n    rw [hP,hQ] at hmin\n    have hm := hmin.trans_le (min_le_right _ _)\n    nlinarith\n\n/-- A divisor surviving the raw exponent consumes one stripped copy and the retained final period in the original group cardinality. -/\ntheorem retained_raw_power_dvd {G : Type*} [Group G] [Finite G] (a : G)\n    {A E M r : ℕ} (ha : orderOf a∣A) (hrE : r∣E)\n    (hr : r∣orderOf ((a^E)^M)) : r*orderOf ((a^E)^M)∣A := by\n  have hraw : r∣orderOf (a^E) := hr.trans (orderOf_pow_dvd M)\n  have hstrip := surviving_power_dvd a hrE 1 (by simpa only [pow_one] using hraw)\n  have hstep : r*orderOf ((a^E)^M)∣r*orderOf (a^E) :=\n    Nat.mul_dvd_mul_left r (orderOf_pow_dvd M)\n  have hstrip' : r*orderOf (a^E)∣orderOf a := by\n    simpa only [pow_one] using hstrip\n  exact hstep.trans (hstrip'.trans ha)\n\n/-- A prime above B cannot be a shared cardinality divisor when both retained local periods exceed the short cap and N is at most B^6. -/\ntheorem large_common_survivor_impossible {p q B A D r : ℕ}\n    (hp : 1<p) (hq : 1<q) (hB : 0<B) (hbudget : p*q≤B^6)\n    (hA : (2*B)^2<A) (hD : (2*B)^2<D) (hr : B<r)\n    (ha : r*A∣p-1) (hd : r*D∣q-1) : False := by\n  have hb2 : 0<B^2 := pow_pos hB 2\n  have hrpos : 0<r := by omega\n  have hPA : r*A≤p-1 := Nat.le_of_dvd (by omega) ha\n  have hQD : r*D≤q-1 := Nat.le_of_dvd (by omega) hd\n  have hp3 : B^3<p := by\n    have hh : B*B^2<r*B^2 := Nat.mul_lt_mul_of_pos_right hr hb2\n    have hl : r*B^2≤r*A := Nat.mul_le_mul_left r (by nlinarith)\n    have he : B^3=B*B^2 := by ring\n    rw [he]\n    omega\n  have hq3 : B^3<q := by\n    have hh : B*B^2<r*B^2 := Nat.mul_lt_mul_of_pos_right hr hb2\n    have hl : r*B^2≤r*D := Nat.mul_le_mul_left r (by nlinarith)\n    have he : B^3=B*B^2 := by ring\n    rw [he]\n    omega\n  have he : B^6=B^3*B^3 := by ring\n  have hlt : B^6<p*q := by\n    rw [he]\n    exact (Nat.mul_le_mul_left (B^3) hq3.le).trans_lt\n      (Nat.mul_lt_mul_of_pos_right hp3 (by omega))\n  omega\n\n/-- The surviving left period is coprime to N-1. Otherwise one stripped prime copy at each factor violates the literal product budget. -/\ntheorem projected_left_coprime_predecessor {p q B : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hB : 0<B) (hbudget : p*q≤B^6)\n    (g : (ZMod (p*q))ˣ) (hc : CoreData p q B (projectedUnit g B)) :\n    (orderOf (leftUnit (projectedUnit g B))).Coprime (p*q-1) := by\n  let : Fact p.Prime := ⟨hp⟩\n  let : Fact q.Prime := ⟨hq⟩\n  apply Nat.coprime_of_dvd\n  intro r hr hrA hrE\n  have hcard := local_card_divisors hp hq (projectedUnit g B)\n  have hsurvive : r*orderOf (leftUnit (projectedUnit g B))∣p-1 := by\n    have hr' : r∣orderOf (((leftUnit g)^(p*q-1))^((B.factorial)^(Nat.clog 2 (p*q+1)))) := by\n      simpa only [leftUnit,projectedUnit,map_pow] using hrA\n    have hh := retained_raw_power_dvd (leftUnit g)\n      (ZMod.orderOf_units_dvd_card_sub_one _) hrE hr'\n    simpa only [leftUnit,projectedUnit,map_pow] using hh\n  have hrgcd := Nat.dvd_gcd (hrA.trans hcard.1) hrE\n  rw [SemiprimeOrderSeparation.gcd_sub_one_mul hp.pos hq.pos] at hrgcd\n  have hrq : r∣q-1 := hrgcd.trans (Nat.gcd_dvd_right _ _)\n  have hcR : r.Coprime (orderOf (rightUnit (projectedUnit g B))) :=\n    hc.2.1.of_dvd_left hrA\n  have hother := hcR.mul_dvd_of_dvd_of_dvd hrq hcard.2\n  exact large_common_survivor_impossible hp.one_lt hq.one_lt hB hbudget\n    hc.1.1 hc.1.2 (hc.2.2.1 r hr hrA) hsurvive hother\n\n/-- The same cardinality-budget argument retains the right field and proves its surviving period coprime to N-1. -/\ntheorem projected_right_coprime_predecessor {p q B : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hB : 0<B) (hbudget : p*q≤B^6)\n    (g : (ZMod (p*q))ˣ) (hc : CoreData p q B (projectedUnit g B)) :\n    (orderOf (rightUnit (projectedUnit g B))).Coprime (p*q-1) := by\n  let : Fact p.Prime := ⟨hp⟩\n  let : Fact q.Prime := ⟨hq⟩\n  apply Nat.coprime_of_dvd\n  intro r hr hrD hrE\n  have hcard := local_card_divisors hp hq (projectedUnit g B)\n  have hsurvive : r*orderOf (rightUnit (projectedUnit g B))∣q-1 := by\n    have hr' : r∣orderOf (((rightUnit g)^(p*q-1))^((B.factorial)^(Nat.clog 2 (p*q+1)))) := by\n      simpa only [rightUnit,projectedUnit,map_pow] using hrD\n    have hh := retained_raw_power_dvd (rightUnit g)\n      (ZMod.orderOf_units_dvd_card_sub_one _) hrE hr'\n    simpa only [rightUnit,projectedUnit,map_pow] using hh\n  have hrgcd := Nat.dvd_gcd (hrD.trans hcard.2) hrE\n  rw [SemiprimeOrderSeparation.gcd_sub_one_mul_right hp.pos hq.pos] at hrgcd\n  have hrp : r∣p-1 := hrgcd.trans (Nat.gcd_dvd_left _ _)\n  have hcR : r.Coprime (orderOf (leftUnit (projectedUnit g B))) :=\n    hc.2.1.symm.of_dvd_left hrD\n  have hother := hcR.mul_dvd_of_dvd_of_dvd hrp hcard.1\n  exact large_common_survivor_impossible hq.one_lt hp.one_lt hB\n    (by simpa only [Nat.mul_comm] using hbudget)\n    hc.1.2 hc.1.1 (hc.2.2.2 r hr hrD) hsurvive hother\n\n/-- Both retained fields certify that the actual projected global order is coprime to N-1, without any additional public query. -/\ntheorem projected_predecessor_coprime {p q B : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hB : 0<B) (hbudget : p*q≤B^6)\n    (g : (ZMod (p*q))ˣ) (hc : CoreData p q B (projectedUnit g B)) :\n    (orderOf (projectedUnit g B)).Coprime (p*q-1) := by\n  have hleft := projected_left_coprime_predecessor hp hq hB hbudget g hc\n  have hright := projected_right_coprime_predecessor hp hq hB hbudget g hc\n  rw [global_order_eq_lcm hp hq hpq]\n  exact (hleft.mul_left hright).of_dvd_left (Nat.lcm_dvd_mul _ _)\n\n\n/-- Retain the cached N power as its own public unit. -/\ndef nPower {N : ℕ} (h : (ZMod N)ˣ) : (ZMod N)ˣ := h^N\n\n/-- The successor channel uses one multiplication of the cached N power. -/\ndef successorPower {N : ℕ} (h : (ZMod N)ˣ) : (ZMod N)ˣ := nPower h*h\n\n/-- The cached successor channel is the literal N+1 power. -/\ntheorem successorPower_eq {N : ℕ} (h : (ZMod N)ˣ) : successorPower h=h^(N+1) :=\n  (pow_succ h N).symm\n\n/-- Check one closing residue before building its short batch. -/\ndef checkPower {N : ℕ} (h : (ZMod N)ˣ) : Option ℕ :=\n  checkedSignal N ((h : ZMod N)-1).val\n\n/-- The direct power GCD returns only proper factors. -/\ntheorem checkPower_sound {N d : ℕ} (h : (ZMod N)ˣ) (hd : checkPower h=some d) :\n    ProperDivisor N d := checkedSignal_sound hd\n\n/-- Two public power channels, each followed by a degree-at-most-2B\nshort batch only when its direct GCD did not already recover a factor. -/\nnoncomputable def scanPowers {N : ℕ} (h : (ZMod N)ˣ) (B : ℕ) : Option ℕ :=\n  match checkPower (nPower h) with\n  | some d => some d\n  | none =>\n    match recoverShort (nPower h) (2*B) with\n    | some d => some d\n    | none =>\n      match checkPower (successorPower h) with\n      | some d => some d\n      | none => recoverShort (successorPower h) (2*B)\n\n/-- A successful first direct test determines the scan without unfolding\nany numerical short-batch construction. -/\ntheorem scanPowers_eq_of_first {N B d : ℕ} (h : (ZMod N)ˣ)\n    (hc : checkPower (nPower h)=some d) : scanPowers h B=some d := by\n  simp only [scanPowers,hc]\n\n/-- A successful successor direct test determines the scan after the\nliteral preceding direct test and short batch are both clear. -/\ntheorem scanPowers_eq_of_successor {N B d : ℕ} (h : (ZMod N)ˣ)\n    (hc : checkPower (nPower h)=none) (hn : recoverShort (nPower h) (2*B)=none)\n    (hs : checkPower (successorPower h)=some d) : scanPowers h B=some d := by\n  simp only [scanPowers,hc,hn,hs]\n\n/-- Every factor from either channel is proper, without period advice. -/\ntheorem scanPowers_sound {N B d : ℕ} (h : (ZMod N)ˣ) (hd : scanPowers h B=some d) :\n    ProperDivisor N d := by\n  unfold scanPowers at hd\n  cases hn : checkPower (nPower h) with\n  | some f =>\n    rw [hn] at hd\n    have he := Option.some.inj hd\n    exact he ▸ checkPower_sound _ hn\n  | none =>\n    rw [hn] at hd\n    cases hs : recoverShort (nPower h) (2*B) with\n    | some f =>\n      rw [hs] at hd\n      have he := Option.some.inj hd\n      exact he ▸ recoverShort_sound _ hs\n    | none =>\n      rw [hs] at hd\n      cases hx : checkPower (successorPower h) with\n      | some f =>\n        rw [hx] at hd\n        have he := Option.some.inj hd\n        exact he ▸ checkPower_sound _ hx\n      | none =>\n        rw [hx] at hd\n        exact recoverShort_sound _ hd\n\n/-- A failed scan preserves both actual failed short-batch results. -/\ntheorem scanPowers_none_info {N B : ℕ} (h : (ZMod N)ˣ) (hn : scanPowers h B=none) :\n    recoverShort (nPower h) (2*B)=none ∧\n    recoverShort (successorPower h) (2*B)=none := by\n  unfold scanPowers at hn\n  cases hc : checkPower (nPower h) with\n  | some d => rw [hc] at hn; contradiction\n  | none =>\n    rw [hc] at hn\n    cases hs : recoverShort (nPower h) (2*B) with\n    | some d => rw [hs] at hn; contradiction\n    | none =>\n      rw [hs] at hn\n      cases hx : checkPower (successorPower h) with\n      | some d => rw [hx] at hn; contradiction\n      | none =>\n        rw [hx] at hn\n        exact ⟨rfl,hn⟩\n\n/-- GCD queries along the literal two-channel scan, including direct tests. -/\nnoncomputable def scanGcdCount {N : ℕ} (h : (ZMod N)ˣ) (B : ℕ) : ℕ :=\n  1 + match checkPower (nPower h) with\n  | some _ => 0\n  | none => shortGcdCount (nPower h) (2*B)+\n    match recoverShort (nPower h) (2*B) with\n    | some _ => 0\n    | none => 1 + match checkPower (successorPower h) with\n      | some _ => 0\n      | none => shortGcdCount (successorPower h) (2*B)\n\n/-- All added batches and direct tests cost at most 8B+2 GCD queries. -/\ntheorem scanGcdCount_le {N : ℕ} (h : (ZMod N)ˣ) (B : ℕ) : scanGcdCount h B≤8*B+2 := by\n  have hn := shortGcdCount_le (nPower h) (2*B)\n  have hs := shortGcdCount_le (successorPower h) (2*B)\n  cases hc : checkPower (nPower h) with\n  | some d => simp only [scanGcdCount,hc,Nat.add_zero]; omega\n  | none =>\n    cases hb : recoverShort (nPower h) (2*B) with\n    | some d => simp only [scanGcdCount,hc,hb,Nat.add_zero]; omega\n    | none =>\n      cases hx : checkPower (successorPower h) with\n      | some d =>\n        simp only [scanGcdCount,hc,hb,hx,Nat.add_zero]\n        calc\n          1+(shortGcdCount (nPower h) (2*B)+1) ≤ 1+(2*(2*B)+1) :=\n            Nat.add_le_add_left (Nat.add_le_add_right hn 1) 1\n          _ ≤ 8*B+2 := by omega\n      | none =>\n        simp only [scanGcdCount,hc,hb,hx]\n        calc\n          1+(shortGcdCount (nPower h) (2*B)+(1+shortGcdCount (successorPower h) (2*B)))\n              ≤ 1+(2*(2*B)+(1+2*(2*B))) :=\n            Nat.add_le_add_left (Nat.add_le_add hn (Nat.add_le_add_left hs 1)) 1\n          _ ≤ 8*B+2 := by omega\n\n/-- The original core cannot live at a prime square: equal reductions\nwould have equal coprime orders and hence a trivial local period. -/\ntheorem core_distinct {p q B : ℕ} (hB : 0<B) (h : (ZMod (p*q))ˣ)\n    (hc : CoreData p q B h) : p≠q := by\n  intro he\n  subst q\n  have heq : leftUnit h=rightUnit h := rfl\n  have hcop := hc.2.1\n  rw [←heq,Nat.coprime_self] at hcop\n  have hl := hc.1.1\n  rw [hcop] at hl\n  nlinarith\n\n/-- A factor or a retained richer power carrier. No known order is stored\nas advice: all four units are derived from the public input and seed. -/\ninductive PowerRoute (N : ℕ) where\n  | factor (d : ℕ)\n  | remaining (original active nPower successor : (ZMod N)ˣ)\n  | unresolved\n\n/-- Keep the original long certificate and both public power channels,\nalongside the exact additional facts extracted by their failed batches. -/\ndef GoodPower (p q B : ℕ) : PowerRoute (p*q) → Prop\n  | .factor d => ProperDivisor (p*q) d\n  | .remaining g h z s => LongData g B ∧ h=projectedUnit g B ∧\n      z=nPower h ∧ s=z*h ∧ recoverShort z (2*B)=none ∧ recoverShort s (2*B)=none ∧\n      (orderOf h).Coprime (p*q) ∧\n      (orderOf h).Coprime (p*q-1) ∧\n      (p≤q → (orderOf (leftUnit h)).Coprime (p*q+1)) ∧\n      (q≤p → (orderOf (rightUnit h)).Coprime (p*q+1))\n  | .unresolved => False\n\n/-- N-only refinement of a certified long seed. Projection regeneration\nand its unit GCD are part of the implementation, not free cached advice. -/\nnoncomputable def refineLong (N B k : ℕ) : PowerRoute N :=\n  if hc : k.Coprime N then\n    let g := ZMod.unitOfCoprime k hc\n    let h := projectedUnit g B\n    match scanPowers h B with\n    | some d => .factor d\n    | none => .remaining g h (nPower h) (successorPower h)\n  else .unresolved\n\n/-- A checked scan factors the public long handler directly; the theorem\nkeeps numerical short-source reductions out of the wrapper proof. -/\ntheorem refineLong_eq_of_scan {N B k d : ℕ} (hc : k.Coprime N)\n    (hs : scanPowers (projectedUnit (ZMod.unitOfCoprime k hc) B) B=some d) :\n    refineLong N B k=.factor d := by\n  simp only [refineLong,dite_eq_left hc,hs]\n\n/-- The public long handler either factors or retains its original\ncertificate plus the newly proved coprimality facts and failed sources. -/\ntheorem refineLong_good {p q B k : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hB : 0<B) (hbudget : p*q≤B^6)\n    (hroute : GoodRoute p q B (.longBase k)) : GoodPower p q B (refineLong (p*q) B k) := by\n  obtain ⟨hc,hdata⟩ := hroute\n  let g := ZMod.unitOfCoprime k hc\n  let h := projectedUnit g B\n  have hcore := projected_core g hdata\n  have hpq := core_distinct hB h hcore\n  unfold refineLong\n  rw [dite_eq_left hc]\n  dsimp only\n  cases hs : scanPowers h B with\n  | some d => exact scanPowers_sound h hs\n  | none =>\n    obtain ⟨hn,hnext⟩ := scanPowers_none_info h hs\n    have hn' : recoverShort (h^(p*q)) (2*B)=none := hn\n    have hnext' : recoverShort (h^(p*q+1)) (2*B)=none := by\n      rwa [successorPower_eq] at hnext\n    have hcN := failed_N_forces_coprime hp hq hpq hB hbudget h hcore.1 hn'\n    have hcPrevious := projected_predecessor_coprime hp hq hpq hB hbudget g hcore\n    have hcNext := failed_successor_forces_min_coprime hp hq hpq hB hbudget h hcore hnext'\n    exact ⟨hdata,rfl,rfl,rfl,hn,hnext,hcN,hcPrevious,hcNext⟩\n\n/-- The public wrapper additionally pays its input-unit check. -/\nnoncomputable def refinementGcdCount (N B k : ℕ) : ℕ :=\n  1 + if hc : k.Coprime N then scanGcdCount (projectedUnit (ZMod.unitOfCoprime k hc) B) B\n      else 0\n\n/-- At most 8B+3 GCDs are added, including the public seed-unit test. -/\ntheorem refinementGcdCount_le (N B k : ℕ) : refinementGcdCount N B k≤8*B+3 := by\n  unfold refinementGcdCount\n  split_ifs with hc\n  · have hs := scanGcdCount_le (projectedUnit (ZMod.unitOfCoprime k hc) B) B\n    omega\n  · omega\n\n/-- Leaf certificates retain a real semiprime and the strengthened long\npower data, rather than treating a failed refinement as a factor. -/\ninductive PowerCertified : {N : ℕ} → PowerRoute N → Prop where\n  | factor {p q d : ℕ} (hp : p.Prime) (hq : q.Prime)\n      (hd : ProperDivisor (p*q) d) : PowerCertified (.factor d : PowerRoute (p*q))\n  | remaining {p q : ℕ} {g h z s : (ZMod (p*q))ˣ}\n      (hp : p.Prime) (hq : q.Prime)\n      (hd : GoodPower p q (SemiprimeLehmanCoverage.sixthWidth (p*q)) (.remaining g h z s)) :\n      PowerCertified (.remaining g h z s)\n\n/-- A good literal public leaf result supplies its indexed certificate. -/\ntheorem powerCertified_of_good {p q : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (route : PowerRoute (p*q))\n    (hg : GoodPower p q (SemiprimeLehmanCoverage.sixthWidth (p*q)) route) :\n    PowerCertified route := by\n  cases route with\n  | factor d => exact .factor hp hq hg\n  | remaining g h z s => exact .remaining hp hq hg\n  | unresolved => exact False.elim hg\n\n/-- A certified leaf factor is proper for its exact leaf input. -/\ntheorem powerCertified_factor {N d : ℕ} (hc : PowerCertified (.factor d : PowerRoute N)) :\n    ProperDivisor N d := by\n  cases hc with\n  | factor hp hq hd => exact hd\n\n/-- An unresolved leaf has no semiprime power certificate. -/\ntheorem powerCertified_not_unresolved {N : ℕ}\n    (hc : PowerCertified (.unresolved : PowerRoute N)) : False := by\n  cases hc\n\n/-- Refine only the terminal long seed, while keeping the entire original\nkernel descent available as a separate richer carrier. -/\nnoncomputable def leafRefinement {N : ℕ} (trace : SemiprimeKernelDescent.Trace N) :\n    PowerRoute (SemiprimeKernelDescent.leafInput trace) :=\n  match SemiprimeKernelDescent.leafRoute trace with\n  | .factor d => .factor d\n  | .longBase k => refineLong (SemiprimeKernelDescent.leafInput trace)\n      (SemiprimeLehmanCoverage.sixthWidth (SemiprimeKernelDescent.leafInput trace)) k\n  | _ => .unresolved\n\n/-- Every certified original descent produces a certified refined leaf. -/\ntheorem leafRefinement_certified {N : ℕ} {trace : SemiprimeKernelDescent.Trace N}\n    (hc : SemiprimeKernelDescent.Certified trace) : PowerCertified (leafRefinement trace) := by\n  induction hc with\n  | factor hp hq hd => exact .factor hp hq hd\n  | longBase hp hq hgood =>\n    exact powerCertified_of_good hp hq _ (refineLong_good hp hq\n      (SemiprimeKernelDescent.sixthWidth_pos (Nat.mul_pos hp.pos hq.pos))\n      (SemiprimeLehmanCoverage.sixthWidth_upper _) hgood)\n  | child hp hq hgood hchild ih => exact ih\n\n/-- Lift a newly obtained leaf factor through every retained active unit.\nThe original trace is not discarded by this downstream recovery view. -/\nnoncomputable def transportCandidate {N : ℕ} : SemiprimeKernelDescent.Trace N → ℕ → Option ℕ\n  | .factor d, _ => some d\n  | .longBase _, d => checkedSignal N d\n  | .unresolved, _ => none\n  | .child R _ h _ _ trace, d =>\n    match transportCandidate trace d with\n    | some f => SemiprimeKernelResidual.recoverResidual h R f\n    | none => none\n\n/-- The transported option returns only proper original-input factors. -/\ntheorem transportCandidate_sound {N d f : ℕ} {trace : SemiprimeKernelDescent.Trace N}\n    (hc : SemiprimeKernelDescent.Certified trace) (hf : transportCandidate trace d=some f) :\n    ProperDivisor N f := by\n  cases hc with\n  | factor hp hq hd =>\n    have he := Option.some.inj hf\n    exact he ▸ hd\n  | longBase hp hq hgood => exact checkedSignal_sound hf\n  | @child p q R g h primes route trace hp hq hgood hchild =>\n    dsimp only [transportCandidate] at hf\n    cases hs : transportCandidate trace d with\n    | none => rw [hs] at hf; contradiction\n    | some f' =>\n      rw [hs] at hf\n      exact SemiprimeKernelResidual.recoverResidual_sound h hf\n\n/-- Any proper refined leaf factor is transported back completely.\nAll successful edge powers, candidates and GCDs remain charged calls. -/\ntheorem transportCandidate_complete {N d : ℕ} {trace : SemiprimeKernelDescent.Trace N}\n    (hc : SemiprimeKernelDescent.Certified trace)\n    (hd : ProperDivisor (SemiprimeKernelDescent.leafInput trace) d) :\n    ∃ f, transportCandidate trace d=some f ∧ ProperDivisor N f := by\n  induction hc generalizing d with\n  | factor hp hq hproper => exact ⟨_,rfl,hproper⟩\n  | @longBase p q k hp hq hgood =>\n    have hg : (p*q).gcd d=d := Nat.gcd_eq_right hd.2.2\n    have hproper : 1<d ∧ d<p*q := ⟨hd.1,hd.2.1⟩\n    refine ⟨d,?_,hd⟩\n    simp only [transportCandidate,checkedSignal,hg,ite_eq_left hproper]\n  | @child p q R g h primes route trace hp hq hgood hchild ih =>\n    obtain ⟨f,hf,hproper⟩ := ih hd\n    obtain ⟨f',hf',hproper'⟩ :=\n      SemiprimeKernelResidual.residual_transport hp hq g h primes route hgood hproper\n    refine ⟨f',?_,hproper'⟩\n    simp only [transportCandidate,hf,hf']\n\n/-- Decode the original factor option once; a newly successful leaf is\nthen lifted through the unchanged retained descent. -/\nnoncomputable def factorWithLeaf {N : ℕ} (trace : SemiprimeKernelDescent.Trace N)\n    (leaf : PowerRoute (SemiprimeKernelDescent.leafInput trace)) : Option ℕ :=\n  match SemiprimeKernelDescent.recoveredFactor trace with\n  | some d => some d\n  | none => match leaf with\n    | .factor d => transportCandidate trace d\n    | _ => none\n\n/-- Exhaustive refined result: a recovered original factor or a retained\ncertified nonfactor leaf. The pending mathematics remains explicit. -/\ntheorem factorWithLeaf_cases {N : ℕ} {trace : SemiprimeKernelDescent.Trace N}\n    (hc : SemiprimeKernelDescent.Certified trace)\n    (leaf : PowerRoute (SemiprimeKernelDescent.leafInput trace)) (hl : PowerCertified leaf) :\n    (∃ d, factorWithLeaf trace leaf=some d ∧ ProperDivisor N d) ∨\n    (factorWithLeaf trace leaf=none ∧ PowerCertified leaf ∧ ∀ d,leaf≠.factor d) := by\n  cases ho : SemiprimeKernelDescent.recoveredFactor trace with\n  | some d =>\n    exact Or.inl ⟨d,by simp only [factorWithLeaf,ho],\n      SemiprimeKernelDescent.recoveredFactor_sound hc ho⟩\n  | none =>\n    cases leaf with\n    | factor d =>\n      obtain ⟨f,hf,hproper⟩ := transportCandidate_complete hc (powerCertified_factor hl)\n      exact Or.inl ⟨f,by simp only [factorWithLeaf,ho,hf],hproper⟩\n    | remaining g h z s =>\n      exact Or.inr ⟨by simp only [factorWithLeaf,ho],hl,by intro d he; cases he⟩\n    | unresolved => exact False.elim (powerCertified_not_unresolved hl)\n\n/-- Rich public result retains both the original descent and its refined\nleaf, with the proper original factor option as a downstream summary. -/\nstructure Packet (N : ℕ) where\n  /-- Complete original descent, retaining every transport frame. -/\n  source : SemiprimeKernelDescent.Trace N\n  /-- The actual refined terminal leaf with its retained power channels. -/\n  leaf : PowerRoute (SemiprimeKernelDescent.leafInput source)\n  /-- A downstream checked original-input factor when recovery succeeds. -/\n  factor : Option ℕ\n\n/-- Complete N-only refinement, computing the initial descent and actual\nleaf once each. No supplied numerical order enters this procedure. -/\nnoncomputable def publicPacket (N : ℕ) : Packet N :=\n  let source := SemiprimeKernelDescent.publicTrace N\n  let leaf := leafRefinement source\n  ⟨source,leaf,factorWithLeaf source leaf⟩\n\n/-- Universal original-factor-or-strengthened-long-leaf routing, including\nall kernel descent. The final one-sixth extractor and bit theorem are open. -/\ntheorem publicPacket_cases {p q : ℕ} (hp : p.Prime) (hq : q.Prime) :\n    (∃ d,(publicPacket (p*q)).factor=some d ∧ ProperDivisor (p*q) d) ∨\n    ((publicPacket (p*q)).factor=none ∧ PowerCertified (publicPacket (p*q)).leaf ∧\n      ∀ d,(publicPacket (p*q)).leaf≠.factor d) :=\n  factorWithLeaf_cases (SemiprimeKernelDescent.publicTrace_certified hp hq) _\n    (leafRefinement_certified (SemiprimeKernelDescent.publicTrace_certified hp hq))\n\n/-- The terminal input is no larger than the original input in every\ncertified trace, including traces that already recover a factor. -/\ntheorem certified_leaf_input_le {N : ℕ} {trace : SemiprimeKernelDescent.Trace N}\n    (hc : SemiprimeKernelDescent.Certified trace) :\n    SemiprimeKernelDescent.leafInput trace≤N := by\n  induction hc with\n  | factor hp hq hd => exact Nat.le_refl _\n  | longBase hp hq hg => exact Nat.le_refl _\n  | child hp hq hgood hchild ih =>\n    have hh := hgood.1\n    exact ih.trans (by omega)\n\n/-- Count only the actual new terminal refinement; factor leaves add no\npower scan. Projection construction remains a separate charged operation. -/\nnoncomputable def leafRefinementGcdCount {N : ℕ} (trace : SemiprimeKernelDescent.Trace N) : ℕ :=\n  match SemiprimeKernelDescent.leafRoute trace with\n  | .longBase k => refinementGcdCount (SemiprimeKernelDescent.leafInput trace)\n      (SemiprimeLehmanCoverage.sixthWidth (SemiprimeKernelDescent.leafInput trace)) k\n  | _ => 0\n\n/-- The new refinement allowance uses the original input's sixth-root\nwidth even after any number of retained kernel descents. -/\ntheorem publicPacket_refinement_queries_le {p q : ℕ} (hp : p.Prime) (hq : q.Prime) :\n    leafRefinementGcdCount (SemiprimeKernelDescent.publicTrace (p*q))≤\n      8*SemiprimeLehmanCoverage.sixthWidth (p*q)+3 := by\n  have hw := SemiprimeKernelDescent.sixthWidth_mono\n    (certified_leaf_input_le (SemiprimeKernelDescent.publicTrace_certified hp hq))\n  cases he : SemiprimeKernelDescent.leafRoute (SemiprimeKernelDescent.publicTrace (p*q)) with\n  | factor d => simp only [leafRefinementGcdCount,he]; omega\n  | kernelBase k => simp only [leafRefinementGcdCount,he]; omega\n  | unresolved => simp only [leafRefinementGcdCount,he]; omega\n  | longBase k =>\n    simp only [leafRefinementGcdCount,he]\n    exact (refinementGcdCount_le _ _ k).trans (by omega)\n\nset_option maxRecDepth 32768 in\n/-- Exact arithmetic of the cross-period control. Its actual public seed\nand projection are checked separately in the charged replay. -/\ntheorem control_cross_arithmetic :\n    Nat.Prime 10163 ∧ Nat.Prime 20327 ∧ 10163*20327=206583301 ∧\n    206583301≤(25 : ℕ)^6 ∧ (2*25 : ℕ)^2<5081 ∧ (2*25 : ℕ)^2<10163 ∧\n    Nat.Coprime 5081 10163 ∧ sumSignal 206583301 51638203=30490 ∧\n    recoverKnownOrder 206583301 51638203=some 10163 := by\n  norm_num [sumSignal,recoverKnownOrder,sumCandidate,checkedSignal,Nat.Coprime]\n\n/-- The cross control's public N-power is checked by fast modular\nexponentiation inside Lean; no supplied order is used for this test. -/\ntheorem control_cross_power :\n    (125510454 : ZMod 206583301)^206583301=2967743 := by\n  reduce_mod_char\n\nset_option maxRecDepth 32768 in\n/-- The first control's projected scalar is calculated from the public\nbase two and the literal public exponents, rather than supplied as advice. -/\ntheorem control_cross_projection_value :\n    ((2 : ZMod 206583301)^(206583301-1 : ℕ))^\n      ((Nat.factorial 25)^(Nat.clog 2 (206583301+1)))=125510454 := by\n  have hlog : Nat.clog 2 (206583301+1)=28 := by decide\n  have hfact : Nat.factorial 25=15511210043330985984000000 := by\n    norm_num [Nat.factorial]\n  rw [hlog,hfact]\n  reduce_mod_char\n\nset_option maxRecDepth 32768 in\n/-- On the certified projected value the first added direct GCD already\nrecovers the larger factor; no new short source is needed on this control. -/\ntheorem control_cross_scan (h : (ZMod 206583301)ˣ)\n    (hh : (h : ZMod 206583301)=125510454) : scanPowers h 25=some 20327 := by\n  have hv : (nPower h : ZMod 206583301)=2967743 := by\n    rw [nPower,Units.val_pow_eq_pow_val,hh]\n    exact control_cross_power\n  have hc : checkPower (nPower h)=some 20327 := by\n    have he : (2967743 : ZMod 206583301)-1=2967742 := by reduce_mod_char\n    unfold checkPower\n    rw [hv,he,ZMod.val_ofNat]\n    norm_num [checkedSignal]\n  exact scanPowers_eq_of_first h hc\n\nset_option maxRecDepth 32768 in\n/-- The complete new long handler at public base two recovers 20327 on\nthe first control. Its full preceding routing is covered by the replay. -/\ntheorem control_cross_refine : refineLong 206583301 25 2=.factor 20327 := by\n  have hc : Nat.Coprime 2 206583301 := by norm_num [Nat.Coprime]\n  have hg : (ZMod.unitOfCoprime 2 hc : ZMod 206583301)=2 := ZMod.coe_unitOfCoprime 2 hc\n  have hp : (projectedUnit (ZMod.unitOfCoprime 2 hc) 25 : ZMod 206583301)=125510454 := by\n    rw [projectedUnit_val,hg]\n    exact control_cross_projection_value\n  exact refineLong_eq_of_scan hc (control_cross_scan _ hp)\n\nset_option maxRecDepth 32768 in\n/-- Exact factor, budget and direct signal data for the successor control.\nThe first short batch's failed outcome remains an independent replay check. -/\ntheorem control_successor_arithmetic :\n    Nat.Prime 11483 ∧ Nat.Prime 22963 ∧ 11483*22963=263684129 ∧\n    263684129≤(26 : ℕ)^6 ∧ (2*26 : ℕ)^2<5741 ∧ (2*26 : ℕ)^2<3827 ∧\n    Nat.Coprime 5741 3827 := by\n  norm_num [Nat.Coprime]\n\n/-- Both public power channels of the successor control are checked\nwithout constructing the unreduced integer powers. -/\ntheorem control_successor_powers :\n    (116995666 : ZMod 263684129)^263684129=243780042 ∧\n    (243780042 : ZMod 263684129)*116995666=191639788 := by\n  constructor <;> reduce_mod_char\n\nset_option maxRecDepth 32768 in\n/-- The second control's literal projected scalar is also checked from\nthe public base and public projection exponents inside Lean. -/\ntheorem control_successor_projection_value :\n    ((2 : ZMod 263684129)^(263684129-1 : ℕ))^\n      ((Nat.factorial 26)^(Nat.clog 2 (263684129+1)))=116995666 := by\n  have hlog : Nat.clog 2 (263684129+1)=28 := by decide\n  have hfact : Nat.factorial 26=403291461126605635584000000 := by\n    norm_num [Nat.factorial]\n  rw [hlog,hfact]\n  reduce_mod_char\n\nset_option maxRecDepth 32768 in\n/-- The N test is clear, while the N+1 direct signal recovers 11483. -/\ntheorem control_successor_checks (h : (ZMod 263684129)ˣ)\n    (hh : (h : ZMod 263684129)=116995666) :\n    checkPower (nPower h)=none ∧ checkPower (successorPower h)=some 11483 := by\n  have hv : (nPower h : ZMod 263684129)=243780042 := by\n    rw [nPower,Units.val_pow_eq_pow_val,hh]\n    exact control_successor_powers.1\n  have hs : (successorPower h : ZMod 263684129)=191639788 := by\n    rw [successorPower,Units.val_mul,hv,hh]\n    exact control_successor_powers.2\n  have heN : (243780042 : ZMod 263684129)-1=243780041 := by reduce_mod_char\n  have heS : (191639788 : ZMod 263684129)-1=191639787 := by reduce_mod_char\n  unfold checkPower\n  rw [hv,hs,heN,heS,ZMod.val_ofNat,ZMod.val_ofNat]\n  norm_num [checkedSignal]\n\nset_option maxRecDepth 32768 in\n/-- If the preceding N short batch is clear, the successor control\nreturns its checked factor. This hypothesis is not silently assumed. -/\ntheorem control_successor_scan (h : (ZMod 263684129)ˣ)\n    (hh : (h : ZMod 263684129)=116995666)\n    (hn : recoverShort (nPower h) 52=none) : scanPowers h 26=some 11483 := by\n  obtain ⟨hc,hs⟩ := control_successor_checks h hh\n  exact scanPowers_eq_of_successor h hc hn hs\n\nend RiemannGaussian.SemiprimeLongPowerRouting\n","RiemannGaussian.SemiprimeMacroFiniteEnumerations":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeFiniteEnumerations\nimport RiemannGaussian.SemiprimeMacroGraph\n\n/-! # Explicit constructor lists for the actual macro graph\nNo finite-type enumeration or classical inverse is used in the data path.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeMacroFiniteEnumerations\nopen SemiprimeFiniteEnumerations SemiprimeMacroGraph\nopen OAI.Algorithms.SubexponentialSAT.Subexp.ConstructivePacking\n\n/-- Explicit constructor data for `unit`. -/\ndef unit : FiniteEnumeration Unit := ⟨[()], by simp, by intro x; cases x; simp⟩\n/-- Explicit constructor data for `boolean`. -/\ndef boolean : FiniteEnumeration Bool := ⟨[false,true], by simp, by intro x; cases x <;> simp⟩\n/-- Explicit constructor data for `transforms`. -/\ndef transforms : FiniteEnumeration Transform := sum (fin 2) unit\n\n/-- Explicit constructor data for `wordsCode`. -/\nabbrev wordsCode (r t _digits : ℕ) := Fin 2 × Fin (r*t) ⊕ Transform × Fin r × Fin t ⊕ Transform × Fin r × Fin t ⊕ Transform × Fin t × Fin r ⊕ Fin (r*t) ⊕ Fin (r*t+1)\n/-- Explicit constructor data for `wordsEquiv`. -/\ndef wordsEquiv (r t digits : ℕ) : wordsCode r t digits ≃ WordSignal r t where\n  toFun := fun x => match x with\n    | Sum.inl ((a,b)) => .input a b\n    | Sum.inr (Sum.inl ((a,b,c))) => .first a b c\n    | Sum.inr (Sum.inr (Sum.inl ((a,b,c)))) => .twiddle a b c\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inl ((a,b,c))))) => .second a b c\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (a))))) => .product a\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (a))))) => .carry a\n  invFun := fun x => match x with\n    | .input a b => Sum.inl ((a,b))\n    | .first a b c => Sum.inr (Sum.inl ((a,b,c)))\n    | .twiddle a b c => Sum.inr (Sum.inr (Sum.inl ((a,b,c))))\n    | .second a b c => Sum.inr (Sum.inr (Sum.inr (Sum.inl ((a,b,c)))))\n    | .product a => Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (a)))))\n    | .carry a => Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (a)))))\n  left_inv := by intro x; rcases x with x | x | x | x | x | x <;> simp_all\n  right_inv := by intro x; cases x <;> rfl\n/-- Explicit constructor data for `words`. -/\ndef words (r t digits : ℕ) : FiniteEnumeration (WordSignal r t) :=\n  transport (sum (prod (fin 2) (fin (r*t))) (sum (prod transforms (prod (fin r) (fin t))) (sum (prod transforms (prod (fin r) (fin t))) (sum (prod transforms (prod (fin t) (fin r))) (sum (fin (r*t)) (fin (r*t+1))))))) (wordsEquiv r t digits)\n\n/-- Explicit constructor data for `flagsCode`. -/\nabbrev flagsCode (_r _t digits : ℕ) := Fin 2 × Fin digits ⊕ Fin 2 × Fin (digits-1)\n/-- Explicit constructor data for `flagsEquiv`. -/\ndef flagsEquiv (r t digits : ℕ) : flagsCode r t digits ≃ FlagSignal digits where\n  toFun := fun x => match x with\n    | Sum.inl ((a,b)) => .digit a b\n    | Sum.inr ((a,b)) => .orOut a b\n  invFun := fun x => match x with\n    | .digit a b => Sum.inl ((a,b))\n    | .orOut a b => Sum.inr ((a,b))\n  left_inv := by intro x; rcases x with x | x <;> simp_all\n  right_inv := by intro x; cases x <;> rfl\n/-- Explicit constructor data for `flags`. -/\ndef flags (r t digits : ℕ) : FiniteEnumeration (FlagSignal digits) :=\n  transport (sum (prod (fin 2) (fin digits)) (prod (fin 2) (fin (digits-1)))) (flagsEquiv r t digits)\n\n/-- Explicit constructor data for `verticesCode`. -/\nabbrev verticesCode (r t digits : ℕ) := Fin 2 × Fin (r*t) ⊕ Transform × Fin r ⊕ Transform × Fin r × Fin t ⊕ Transform × Fin t ⊕ Fin (r*t) ⊕ Unit ⊕ Fin (r*t) ⊕ Unit ⊕ Fin 2 × Fin (digits-1) ⊕ Fin 2\n/-- Explicit constructor data for `verticesEquiv`. -/\ndef verticesEquiv (r t digits : ℕ) : verticesCode r t digits ≃ Vertex r t digits where\n  toFun := fun x => match x with\n    | Sum.inl ((a,b)) => .input a b\n    | Sum.inr (Sum.inl ((a,b))) => .first a b\n    | Sum.inr (Sum.inr (Sum.inl ((a,b,c)))) => .scale a b c\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inl ((a,b))))) => .second a b\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (a))))) => .product a\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (())))))) => .carryInitial\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (a))))))) => .carry a\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (())))))))) => .carryTerminal\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl ((a,b)))))))))) => .orGate a b\n    | Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (a))))))))) => .inputCheck a\n  invFun := fun x => match x with\n    | .input a b => Sum.inl ((a,b))\n    | .first a b => Sum.inr (Sum.inl ((a,b)))\n    | .scale a b c => Sum.inr (Sum.inr (Sum.inl ((a,b,c))))\n    | .second a b => Sum.inr (Sum.inr (Sum.inr (Sum.inl ((a,b)))))\n    | .product a => Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (a)))))\n    | .carryInitial => Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (()))))))\n    | .carry a => Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (a)))))))\n    | .carryTerminal => Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl (()))))))))\n    | .orGate a b => Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inl ((a,b))))))))))\n    | .inputCheck a => Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (Sum.inr (a)))))))))\n  left_inv := by intro x; rcases x with x | x | x | x | x | x | x | x | x | x <;> simp_all\n  right_inv := by intro x; cases x <;> rfl\n/-- Explicit constructor data for `vertices`. -/\ndef vertices (r t digits : ℕ) : FiniteEnumeration (Vertex r t digits) :=\n  transport (sum (prod (fin 2) (fin (r*t))) (sum (prod transforms (fin r)) (sum (prod transforms (prod (fin r) (fin t))) (sum (prod transforms (fin t)) (sum (fin (r*t)) (sum (unit) (sum (fin (r*t)) (sum (unit) (sum (prod (fin 2) (fin (digits-1))) (fin 2)))))))))) (verticesEquiv r t digits)\n\n/-- Explicit constructor data for `bits`. -/\ndef bits (r t digits : ℕ) : FiniteEnumeration (BitSignal r t digits) :=\n  sum (prod (words r t digits) (fin (r*t+1))) (flags r t digits)\n/-- Explicit constructor data for `edges`. -/\ndef edges (r t digits : ℕ) : FiniteEnumeration (Edge r t digits) :=\n  prod (bits r t digits) boolean\n/-- Explicit constructor data for `subdividedVertices`. -/\ndef subdividedVertices (r t digits : ℕ) : FiniteEnumeration (SubdividedVertex r t digits) :=\n  sum (vertices r t digits) (bits r t digits)\n/-- Explicit constructor data for `incidences`. -/\ndef incidences (r t digits : ℕ) : FiniteEnumeration\n    ((v : SubdividedVertex r t digits) × Fin (subdividedArity v)) :=\n  sigma (subdividedVertices r t digits) (fun v => fin (subdividedArity v))\n\n/-- Actual macro-graph source enumerations, retaining all ordered port constructors. -/\ndef source (r t digits palette Q : ℕ) [NeZero palette] :=\n  sourceEnumerations (incidences r t digits) (edges r t digits)\n    (subdividedVertices r t digits) palette Q\n\n/-- Every source list is nodup, complete and has the exact actual finite size. -/\ntheorem edges_count (r t digits : ℕ) :\n    (edges r t digits).values.length=Fintype.card (Edge r t digits) :=\n  (edges r t digits).length_eq_card\n\n#print axioms edges_count\nend RiemannGaussian.SemiprimeMacroFiniteEnumerations\n","RiemannGaussian.SemiprimeMaterializedAcquiredCounter":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeMaterializedFibreNative\nimport RiemannGaussian.SemiprimeAcquiredSourceCounter\n\n/-!\n# Actual source acquisition feeds the materialized-head counter\n\nThe coefficient arrays and runtime designs are computed from the original\nnetwork. They are not supplied answers. The selected interpreter ledger and\nsource-preprocessing bit clock remain distinct interfaces.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeMaterializedAcquiredCounter\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT\nopen SemiprimeLocalArrayFrontend SemiprimeRuntimeDesignAcquisition SemiprimeJetArray\nopen SemiprimeAcquiredSourceCounter (raw layout sourceDesign sourceDesign_runtime)\nvariable {n F r Q : ℕ} [NeZero r]\n\n/-- Compute the original source arrays and integer designs, then execute the NEW\ncomplete cached-head counter, including actual native factors and Hermite recovery. -/\ndef count (arity : Fin F → ℕ) (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R B J : ℕ)\n    (T : (e : Fin F) → (Fin (arity e) → Bool) → EntryReport) :\n    SemiprimeAcquiredHermite.ScalarRun :=\n  let en := SemiprimeFiniteEnumerations.indexed n F r Q arity\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  let source := SemiprimeSourceArrayAcquisition.acquire owner Sigma.fst en eps R\n  let designs := Array.ofFn (fun t : Fin Q => build (raw (r := r) arity coordinate eps R B t))\n  SemiprimeMaterializedFibreNative.count Q J R\n    (fun t => designs[t.val]'(by simp [designs]))\n    (fun e i v => SemiprimeSourceArrayAcquisition.read en.incidences source ⟨e,i⟩ v) T\n\n/-- The materialized source-to-scalar count is the original network contraction.\nNo coefficient, integer row, native locality, fibre, group, or count oracle occurs. -/\ntheorem count_correct (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n) (eps : ℚ) (R B J : ℕ)\n    (T : (e : Fin F) → (Fin (arity e) → Bool) → EntryReport)\n    (howner : ∀ v, (Finset.univ.filter\n      (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2=v)).card ≤ B)\n    (hQ : 1≤Q) (hAQ : Subexp.TailInterval.intervalStart r Q R ≤ Q)\n    (hJ : 0<J) (hprecision : (∑ e, arity e)*R<Q*J) :\n    (count (r := r) (Q := Q) arity coordinate eps R B J T).value =\n      SemiprimeCounterNative.originalContraction arity\n        (fun e eta => ((T e eta).value : ℚ)) coordinate := by\n  let en := SemiprimeFiniteEnumerations.indexed n F r Q arity\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  let source := SemiprimeSourceArrayAcquisition.acquire owner Sigma.fst en eps R\n  let readSource := fun (e : Fin F) (i : Fin (arity e)) (v : Fin n) =>\n    SemiprimeSourceArrayAcquisition.read en.incidences source ⟨e,i⟩ v\n  have hs (e : Fin F) (i : Fin (arity e)) (v : Fin n) (k : ℕ) (hk : k≤R) :\n      coefficient (readSource e i v) k=((layout (r := r) (Q := Q) arity coordinate eps R).row ⟨e,i⟩ v).coeff k :=\n    SemiprimeSourceArrayAcquisition.acquire_coefficient owner Sigma.fst en eps R ⟨e,i⟩ v k hk\n  have h := SemiprimeMaterializedFibreNative.count_correct Q J R hJ\n    (fun t => sourceDesign (r := r) (Q := Q) arity coordinate eps R B howner hQ hAQ t) readSource T\n    (fun e i v => (layout (r := r) (Q := Q) arity coordinate eps R).row_degree ⟨e,i⟩ v)\n    hs hprecision coordinate\n    (fun e i v => (layout (r := r) (Q := Q) arity coordinate eps R).row_origin ⟨e,i⟩ v)\n  simp only [sourceDesign_runtime] at h\n  simpa only [count,Array.getElem_ofFn] using h\n\n/-- The NEW actual traversal has the same scalar value as the previous executed\nsource counter; their work reports and execution paths need not agree. -/\ntheorem count_value_eq_old (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n) (eps : ℚ) (R B J : ℕ)\n    (T : (e : Fin F) → (Fin (arity e) → Bool) → EntryReport)\n    (howner : ∀ v, (Finset.univ.filter\n      (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2=v)).card ≤ B)\n    (hQ : 1≤Q) (hAQ : Subexp.TailInterval.intervalStart r Q R ≤ Q)\n    (hJ : 0<J) (hprecision : (∑ e, arity e)*R<Q*J) :\n    (count (r := r) (Q := Q) arity coordinate eps R B J T).value =\n      (SemiprimeAcquiredSourceCounter.count (r := r) (Q := Q) arity coordinate eps R B J T).value :=\n  (count_correct arity coordinate eps R B J T howner hQ hAQ hJ hprecision).trans\n    (SemiprimeAcquiredSourceCounter.count_correct arity coordinate eps R B J T\n      howner hQ hAQ hJ hprecision).symm\n\nend RiemannGaussian.SemiprimeMaterializedAcquiredCounter\n","RiemannGaussian.SemiprimeNativeGroupBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeNativeLocalBits\nimport RiemannGaussian.SemiprimeNativeGroupExecution\n\n/-! # Physical native group multiplication in the original factor order\nThe width uses total incidence only polynomially. Every Boolean interpolation\nstill runs at its own original local arity. Source-word acquisition and the\nfinal rational boundary are explicitly separate from physical group arithmetic.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2500000\nnamespace RiemannGaussian.SemiprimeNativeGroupBits\nopen scoped BigOperators\nopen SemiprimeRationalBits SemiprimeJetBits SemiprimeJetArray SemiprimeJetArrayHeight\nopen SemiprimeLocalExecutionHeight SemiprimeLocalBits SemiprimeLocalBitsBounds\nopen SemiprimeLocalArrayFrontend SemiprimeHermiteArrayHeight\n\n/-- Derived factor/product coefficient exponent, using original parameter bits. -/\ndef factorExponent (b R s : ℕ) : ℕ :=\n  b+(2*SemiprimeNativeLocalBits.portExponent b R+4)*(s+1)+3\n\n/-- A common polynomial width for all physical local calls and product suffixes. -/\ndef groupWidth (b R F s : ℕ) : ℕ :=\n  SemiprimeNativeLocalBits.publicWidth b R s+factorExponent b R s*(2*F+2)+1\n\n/-- Literal physical truncated-one report. -/\ndef oneBits (J : ℕ) : JetReport := ⟨oneArray J,3*J+1⟩\n\n/-- The same tail-first factor product as the original native group. Each\ncallback and suffix report is cached once and retained before multiplication. -/\ndef productList {A : Type} (template : List Bool) (J : ℕ) : List A → (A → JetReport) → JetReport\n  | [],_ => oneBits J\n  | e::tail,f =>\n      let left := f e\n      let right := productList template J tail f\n      let out := multiplyBits template left.words right.words J\n      ⟨out.words,left.clock+right.clock+out.clock+J+3⟩\n\n/-- Selected finite base-bit allocation and factor-control allowance. -/\ndef groupControl (n F J W : ℕ) : ℕ := 20*(n+F+1)*(J+1)*(W+1)+10*n+10*F+10\n\n/-- Actual word-backed group, with the original factor order and gated table\nownership. Total incidence affects width only, never a Boolean exponential. -/\ndef run {n F r : ℕ} {h : Fin r → ℕ} (b : ℕ) (arity : Fin F → ℕ) (J R : ℕ)\n    (tw : RationalWord) (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (grouping : Fin n ≃ ((g : Fin r) × Fin (h g))) (assigned : Fin F → Fin r)\n    (correction : Fin n → Bool) (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (g : Fin r) (a : (g : Fin r) → Fin (h g) → Bool) : JetReport :=\n  let W := groupWidth b R F (∑ e,arity e)\n  let template := List.replicate W false\n  let bits := Array.ofFn (SemiprimeNativeGroupExecution.baseBits grouping a)\n  let getBit := fun v : Fin n => bits[v.val]'(by simp [bits])\n  let result := productList template J (List.ofFn (fun e : Fin F => e)) (fun e =>\n    if assigned e=g then SemiprimeNativeLocalBits.nativeLocal template (arity e) J R tw\n      (source e) getBit correction (entries e) else oneBits J)\n  ⟨result.words,result.clock+groupControl n F J W⟩\n\n/-- Actual output-word normalization/copy allowance at the retained rational\ncounter boundary. This is a ledger boundary, not a claimed tape compiler. -/\ndef decodeWork (words : Array RationalWord) : ℕ :=\n  (words.toList.map (fun w => 20000*(w.numerator.magnitude.length+w.denominator.length+1)^3+5)).sum+\n    2*words.size+1\n\n/-- Embed one actual physical report in the original scalar traversal while\nretaining its complete clock and actual output-copy allowance. -/\ndef toScalarRun (report : JetReport) : SemiprimeFibreArrayExecution.Run :=\n  ⟨⟨decode report.words,0,0⟩,report.clock+decodeWork report.words⟩\n\n/-- The scalar boundary keeps exactly the actual decoded word array. -/\ntheorem toScalarRun_coefficients (report : JetReport) :\n    (toScalarRun report).jet.coefficients=decode report.words := rfl\n\n/-- No physical group work is erased by the scalar traversal boundary. -/\ntheorem toScalarRun_work (report : JetReport) :\n    (toScalarRun report).work=report.clock+decodeWork report.words := by\n  simp only [toScalarRun,SemiprimeFibreArrayExecution.Run.work,Nat.zero_add]\n\n/-- Every suffix has exactly the retained precision. -/\ntheorem productList_size {A : Type} (template : List Bool) (J : ℕ) (xs : List A) (f : A → JetReport) :\n    (productList template J xs f).words.size=J := by\n  cases xs <;> simp only [productList,oneBits,oneArray_size,multiplyBits_size]\n\n/-- The actual group result has the requested precision. -/\ntheorem run_size {n F r : ℕ} {h : Fin r → ℕ} (b : ℕ) (arity : Fin F → ℕ) (J R : ℕ)\n    (tw : RationalWord) (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (grouping : Fin n ≃ ((g : Fin r) × Fin (h g))) (assigned : Fin F → Fin r)\n    (correction : Fin n → Bool) (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (g : Fin r) (a : (g : Fin r) → Fin (h g) → Bool) :\n    (run b arity J R tw source grouping assigned correction entries g a).words.size=J := by\n  simp only [run,productList_size]\n\n/-- Physical one words decode exactly to the original one-jet array. -/\ntheorem oneBits_decode (J : ℕ) : decode (oneBits J).words=(SemiprimeArrayOps.oneJet J).coefficients := by\n  apply SemiprimeCorrectedPortBits.array_eq_of_coeff J\n  · simp only [oneBits,decode_size,oneArray_size]\n  · simp only [SemiprimeArrayOps.oneJet,Array.size_ofFn]\n  · exact oneArray_coefficient J\n\n/-- The original same-order product also has exactly its requested precision. -/\ntheorem scalarProduct_size {A : Type} (J : ℕ) (xs : List A)\n    (f : A → SemiprimeFibreArrayExecution.Run) :\n    (SemiprimeFibreArrayExecution.productList J xs f).jet.coefficients.size=J := by\n  cases xs <;> simp only [SemiprimeFibreArrayExecution.productList,\n    SemiprimeFibreArrayExecution.oneRun,SemiprimeFibreArrayExecution.mulRun,\n    SemiprimeArrayOps.oneJet,SemiprimeJetArray.multiply_size,Array.size_ofFn]\n\n/-- A public dyadic base bound controls every required product power. -/\ntheorem power_lt_width (N k L e W : ℕ) (hN : N ≤ 2^k)\n    (he : e ≤ 2*L+2) (hW : k*(2*L+2)<W) : N^e<2^W := by\n  have hp := Nat.pow_le_pow_left hN e\n  rw [← pow_mul] at hp\n  exact hp.trans_lt (Nat.pow_lt_pow_right (by decide)\n    ((Nat.mul_le_mul_left k he).trans_lt hW))\n\n/-- Same-order physical product correctness and all suffix fits follow from\ncommon original callback representations and a derived dyadic base. -/\ntheorem productList_correct {A : Type} (template : List Bool) (J D B N k : ℕ)\n    (xs : List A) (f : A → JetReport) (legacy : A → SemiprimeFibreArrayExecution.Run)\n    (hD : 0<D) (hDN : D ≤ N) (hBN : B ≤ N) (hJN : J ≤ N) (hNk : N ≤ 2^k)\n    (hwidth : k*(2*xs.length+2)<template.length)\n    (hf : ∀ e∈xs, decode (f e).words=(legacy e).jet.coefficients ∧\n      Valid (f e).words ∧ ArrayBound (decode (f e).words) J D B) :\n    decode (productList template J xs f).words=\n      (SemiprimeFibreArrayExecution.productList J xs legacy).jet.coefficients ∧\n    Valid (productList template J xs f).words ∧\n    ArrayBound (decode (productList template J xs f).words) J (D^xs.length) (N^(2*xs.length)) := by\n  induction xs with\n  | nil =>\n    refine ⟨oneBits_decode J,oneArray_valid J,?_⟩\n    simpa only [List.length_nil,pow_zero,mul_zero,productList,oneBits] using\n      SemiprimeLocalBitsCorrectness.one_bound J 1 (by decide)\n  | cons e tail ih =>\n    have ht : k*(2*tail.length+2)<template.length := by\n      simp only [List.length_cons,Nat.mul_succ] at hwidth ⊢\n      omega\n    have hs := ih ht (fun x hx => hf x (by simp only [List.mem_cons]; exact Or.inr hx))\n    have he := hf e (by simp only [List.mem_cons,true_or])\n    have hden : D*D^tail.length<2^template.length := by\n      rw [← pow_succ']\n      exact (Nat.pow_le_pow_left hDN _).trans_lt\n        (power_lt_width N k (tail.length+1) (tail.length+1) template.length hNk (by omega)\n          (by simpa only [List.length_cons] using hwidth))\n    have hnum0 : J*B*N^(2*tail.length) ≤ N^(2*(tail.length+1)) := by\n      have hm := Nat.mul_le_mul_right (N^(2*tail.length)) (Nat.mul_le_mul hJN hBN)\n      calc\n        _ ≤ N*N*N^(2*tail.length) := hm\n        _ = _ := by rw [← pow_two,← pow_add]; congr 1; omega\n    have hnum := hnum0.trans_lt (power_lt_width N k (tail.length+1)\n      (2*(tail.length+1)) template.length hNk (by omega)\n      (by simpa only [List.length_cons] using hwidth))\n    have hm := multiplyBits_correct template (f e).words (productList template J tail f).words\n      J D (D^tail.length) B (N^(2*tail.length)) he.2.1 hs.2.1 hD (pow_pos hD _)\n      hden hnum he.2.2 hs.2.2\n    have heq : decode (multiplyBits template (f e).words (productList template J tail f).words J).words=\n        (SemiprimeJetArray.multiply (decode (f e).words)\n          (decode (productList template J tail f).words) J).coefficients := by\n      apply SemiprimeCorrectedPortBits.array_eq_of_coeff J\n      · simp only [decode_size,multiplyBits_size]\n      · exact SemiprimeJetArray.multiply_size _ _ _\n      · exact hm.1\n    refine ⟨?_,hm.2,?_⟩\n    · change decode (multiplyBits template (f e).words (productList template J tail f).words J).words=_\n      rw [heq,he.1,hs.1]\n      rfl\n    · intro i hi\n      change Representation (coefficient (decode\n        (multiplyBits template (f e).words (productList template J tail f).words J).words) i)\n          (D^(e::tail).length) (N^(2*(e::tail).length))\n      rw [heq]\n      have hr := multiply_representation (decode (f e).words)\n        (decode (productList template J tail f).words) D (D^tail.length)\n        B (N^(2*tail.length)) J he.2.2 hs.2.2 i hi\n      have hb := representation_mono hr hnum0\n      simpa only [List.length_cons,pow_succ'] using hb\n\n/-- An original factor arity is at most total incidence. -/\ntheorem arity_le_total {F : ℕ} (arity : Fin F → ℕ) (e : Fin F) : arity e ≤ ∑ x,arity x :=\n  Finset.single_le_sum (fun _ _ => Nat.zero_le _) (Finset.mem_univ e)\n\n/-- The original local numerator base and a common denominator give a single\npublic dyadic base for all factor and product-suffix representations. -/\ntheorem factor_base_dyadic (b R J d B T n s : ℕ)\n    (hdb : d ≤ 2^b) (hBb : B ≤ 2^b) (hTb : T ≤ 2^b) (hJb : J ≤ 2^b) (hnb : n ≤ 2^b) :\n    (J+1)*(d^s+(localBase J d (n*hornerBound J B T (R+1))+d+1)^s+1) ≤\n      2^(factorExponent b R s) := by\n  let p := SemiprimeNativeLocalBits.portExponent b R\n  have hbp : b ≤ p := by dsimp [p,SemiprimeNativeLocalBits.portExponent]; omega\n  have hdp := hdb.trans (Nat.pow_le_pow_right (by decide : 0<2) hbp)\n  have hJp := hJb.trans (Nat.pow_le_pow_right (by decide : 0<2) hbp)\n  have hP := SemiprimeNativeLocalBits.port_numerator_le b R J B T n hJb hBb hTb hnb\n  have hL := SemiprimeLocalExecutionBitBounds.localBase_le J d\n    (n*hornerBound J B T (R+1)) p hJp hdp hP\n  have hq : p ≤ 2*p+2 := by omega\n  have hdq := hdp.trans (Nat.pow_le_pow_right (by decide : 0<2) hq)\n  have hone : 1 ≤ 2^(2*p+2) := Nat.one_le_pow _ _ (by decide)\n  have hbase : localBase J d (n*hornerBound J B T (R+1))+d+1 ≤ 2^(2*p+4) := by\n    rw [show 2*p+4=(2*p+2)+2 by omega,pow_add]\n    norm_num\n    omega\n  have hdlarge := hdp.trans (Nat.pow_le_pow_right (by decide : 0<2) (show p ≤ 2*p+4 by omega))\n  have hD := Nat.pow_le_pow_left hdlarge s\n  have hB := Nat.pow_le_pow_left hbase s\n  rw [← pow_mul] at hD hB\n  have hone' : 1 ≤ 2^((2*p+4)*s) := Nat.one_le_pow _ _ (by decide)\n  have hsum : d^s+(localBase J d (n*hornerBound J B T (R+1))+d+1)^s+1 ≤\n      2^((2*p+4)*s+2) := by\n    rw [pow_add]\n    norm_num\n    omega\n  have hJ : J+1 ≤ 2^(b+1) := by rw [pow_succ]; have := Nat.one_le_pow b 2 (by decide); omega\n  have hm := Nat.mul_le_mul hJ hsum\n  rw [← pow_add] at hm\n  apply hm.trans\n  apply Nat.pow_le_pow_right (by decide)\n  dsimp [factorExponent,p]\n  nlinarith\n\n/-- Full physical group refinement with no runtime d/B inputs and no\nintermediate Fits advice. The common width uses total incidence polynomially. -/\ntheorem run_spec {n F r : ℕ} {h : Fin r → ℕ} (b : ℕ) (arity : Fin F → ℕ) (J R d B T : ℕ)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (tw : RationalWord) (t : ℤ) (grouping : Fin n ≃ ((g : Fin r) × Fin (h g)))\n    (assigned : Fin F → Fin r) (correction : Fin n → Bool)\n    (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (g : Fin r) (a : (g : Fin r) → Fin (h g) → Bool)\n    (hvalid : ∀ e i v,Valid (source e i v)) (htw : tw.Valid) (htval : tw.value=(t:ℚ))\n    (hd : 0<d) (ht : t.natAbs ≤ T)\n    (hdb : d ≤ 2^b) (hBb : B ≤ 2^b) (hTb : T ≤ 2^b) (hJb : J ≤ 2^b) (hnb : n ≤ 2^b)\n    (hsource : ∀ e i v k,k ≤ R → Representation (coefficient (decode (source e i v)) k) d B)\n    (hentries : ∀ e eta,(entries e eta).bits.value.natAbs ≤ 1) :\n    decode (run b arity J R tw source grouping assigned correction entries g a).words=\n      (SemiprimeNativeGroupExecution.nativeGroup arity J R (t:ℚ)\n        (fun e i v => decode (source e i v)) grouping assigned correction\n        (fun e => table (entries e)) g a).jet.coefficients ∧\n    Valid (run b arity J R tw source grouping assigned correction entries g a).words := by\n  let s := ∑ e,arity e\n  let W := groupWidth b R F s\n  let template := List.replicate W false\n  let bits := Array.ofFn (SemiprimeNativeGroupExecution.baseBits grouping a)\n  let getBit := fun v : Fin n => bits[v.val]'(by simp [bits])\n  let callback := fun e => if assigned e=g then\n    SemiprimeNativeLocalBits.nativeLocal template (arity e) J R tw\n      (source e) getBit correction (entries e) else oneBits J\n  let legacy := fun e => if assigned e=g then\n    SemiprimeNativeGroupExecution.localRun (arity e) J R (t:ℚ)\n      (fun i v => decode (source e i v)) getBit correction (table (entries e))\n    else SemiprimeFibreArrayExecution.oneRun J\n  let base := localBase J d (n*hornerBound J B T (R+1))+d+1\n  let D := d^s\n  let B0 := base^s\n  let N := (J+1)*(D+B0+1)\n  let k := factorExponent b R s\n  have hdBase : d ≤ base := by dsimp [base]; omega\n  have hlocalBase : localBase J d (n*hornerBound J B T (R+1)) ≤ base := by dsimp [base]; omega\n  have hD : 0<D := pow_pos hd _\n  have hB0 : D ≤ B0 := Nat.pow_le_pow_left hdBase s\n  have hDN : D ≤ N := by\n    have hm := Nat.mul_le_mul_right (D+B0+1) (show 1 ≤ J+1 by omega)\n    simp only [one_mul] at hm\n    dsimp [N]\n    omega\n  have hBN : B0 ≤ N := by\n    have hm := Nat.mul_le_mul_right (D+B0+1) (show 1 ≤ J+1 by omega)\n    simp only [one_mul] at hm\n    dsimp [N]\n    omega\n  have hJN : J ≤ N := by\n    have hm := Nat.mul_le_mul_left (J+1) (show 1 ≤ D+B0+1 by omega)\n    simp only [mul_one] at hm\n    dsimp [N]\n    omega\n  have hNk : N ≤ 2^k := factor_base_dyadic b R J d B T n s hdb hBb hTb hJb hnb\n  have hf (e : Fin F) (_ : e∈List.ofFn (fun e : Fin F => e)) :\n      decode (callback e).words=(legacy e).jet.coefficients ∧\n        Valid (callback e).words ∧ ArrayBound (decode (callback e).words) J D B0 := by\n    by_cases he : assigned e=g\n    · have hw : SemiprimeNativeLocalBits.publicWidth b R (arity e) ≤ template.length := by\n        have hm := SemiprimeNativeLocalBits.publicWidth_mono_arity b R (arity_le_total arity e)\n        dsimp only [template,W]\n        rw [List.length_replicate]\n        unfold groupWidth\n        change SemiprimeNativeLocalBits.publicWidth b R (arity e) ≤\n          SemiprimeNativeLocalBits.publicWidth b R s at hm\n        omega\n      have hl := SemiprimeNativeLocalBits.nativeLocal_correct template b (arity e) R J d B T\n        (source e) tw t getBit correction (entries e) hw (hvalid e) htw htval hd ht\n        hdb hBb hTb hJb hnb (hsource e) (hentries e)\n      refine ⟨?_,?_,?_⟩\n      · simpa only [callback,legacy,ite_eq_left he,SemiprimeNativeGroupExecution.localRun] using hl.1\n      · simpa only [callback,ite_eq_left he] using hl.2.1\n      · intro i hi\n        have hp := representation_mono (hl.2.2 i hi)\n          (Nat.pow_le_pow_left hlocalBase (arity e))\n        have hext := representation_power_extend d base (arity e) s hd hdBase (arity_le_total arity e) hp\n        simpa only [callback,ite_eq_left he,D,B0] using hext\n    · refine ⟨?_,?_,?_⟩\n      · simpa only [callback,legacy,ite_eq_right he,SemiprimeFibreArrayExecution.oneRun] using oneBits_decode J\n      · simpa only [callback,ite_eq_right he,oneBits] using oneArray_valid J\n      · have hb := arrayBound_mono (SemiprimeLocalBitsCorrectness.one_bound J D hD) hB0\n        simpa only [callback,ite_eq_right he,oneBits] using hb\n  have hwidth : k*(2*(List.ofFn (fun e : Fin F => e)).length+2)<template.length := by\n    dsimp only [template,W,groupWidth,k]\n    simp only [List.length_ofFn,List.length_replicate]\n    omega\n  have hp := productList_correct template J D B0 N k (List.ofFn (fun e : Fin F => e))\n    callback legacy hD hDN hBN hJN hNk hwidth hf\n  refine ⟨?_,?_⟩\n  · simpa only [run,SemiprimeNativeGroupExecution.nativeGroup,template,W,s,bits,getBit,callback,legacy] using hp.1\n  · simpa only [run,template,W,s,bits,getBit,callback] using hp.2.1\n\n/-- Exact decoded native-group array for the parent counter adapter. -/\ntheorem run_correct {n F r : ℕ} {h : Fin r → ℕ} (b : ℕ) (arity : Fin F → ℕ) (J R d B T : ℕ)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (tw : RationalWord) (t : ℤ) (grouping : Fin n ≃ ((g : Fin r) × Fin (h g)))\n    (assigned : Fin F → Fin r) (correction : Fin n → Bool)\n    (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (g : Fin r) (a : (g : Fin r) → Fin (h g) → Bool)\n    (hvalid : ∀ e i v,Valid (source e i v)) (htw : tw.Valid) (htval : tw.value=(t:ℚ))\n    (hd : 0<d) (ht : t.natAbs ≤ T)\n    (hdb : d ≤ 2^b) (hBb : B ≤ 2^b) (hTb : T ≤ 2^b) (hJb : J ≤ 2^b) (hnb : n ≤ 2^b)\n    (hsource : ∀ e i v k,k ≤ R → Representation (coefficient (decode (source e i v)) k) d B)\n    (hentries : ∀ e eta,(entries e eta).bits.value.natAbs ≤ 1) :\n    decode (run b arity J R tw source grouping assigned correction entries g a).words=\n      (SemiprimeNativeGroupExecution.nativeGroup arity J R (t:ℚ)\n        (fun e i v => decode (source e i v)) grouping assigned correction\n        (fun e => table (entries e)) g a).jet.coefficients :=\n  (run_spec b arity J R d B T source tw t grouping assigned correction entries g a\n    hvalid htw htval hd ht hdb hBb hTb hJb hnb hsource hentries).1\n\nend RiemannGaussian.SemiprimeNativeGroupBits\n","RiemannGaussian.SemiprimeNativeLocalBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeCorrectedPortBitsBounds\nimport RiemannGaussian.SemiprimeLocalBitsBounds\n\n/-! # Physical corrected ports joined to the actual local Boolean tree\nThe runtime acquires each corrected port once, caches its report, and calls the\nphysical local evaluator. Source-word acquisition remains an explicit boundary.\nAll arithmetic fits are derived from original common source representations.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeNativeLocalBits\nopen scoped BigOperators\nopen SemiprimeRationalBits SemiprimeJetBits SemiprimeJetArray SemiprimeJetArrayHeight\nopen SemiprimeLocalExecutionHeight SemiprimeLocalBits SemiprimeLocalBitsBounds\nopen SemiprimeLocalArrayFrontend\n\n/-- Derived binary exponent for every acquired corrected-port coefficient. -/\ndef portExponent (b R : ℕ) : ℕ := 2*b+(2*b+2)*(R+1)\n\n/-- One polynomial original-parameter width accommodates physical acquisition\nand the entire multilinear tree. It is not supplied intermediate fit advice. -/\ndef publicWidth (b R w : ℕ) : ℕ :=\n  SemiprimeCorrectedPortBits.portWidth b R+bufferWidth (portExponent b R) w+b+1\n\n/-- The constructed physical width is positive for every original parameter. -/\ntheorem publicWidth_pos (b R w : ℕ) : 0<publicWidth b R w := by\n  unfold publicWidth\n  omega\n\n/-- Larger actual arity only enlarges the polynomial width, not the runtime\narity of any local Boolean traversal. -/\ntheorem publicWidth_mono_arity (b R : ℕ) : Monotone (publicWidth b R) := by\n  intro w W h\n  unfold publicWidth bufferWidth\n  gcongr\n\n/-- Finite report-cache allocation, outer port access and local control allowance.\nLiteral address/tape compilation is separate from this selected control ledger. -/\ndef cacheControl (w J W : ℕ) : ℕ := 20*(w+1)*(J+1)*(W+1)*(2^w+1)+10*w+10\n\n/-- Physical local execution: one cached acquired report per original port,\nfollowed by the actual two-branch Boolean multilinear word evaluator. -/\ndef nativeLocal {n : ℕ} (template : List Bool) (w J R : ℕ) (tw : RationalWord)\n    (source : Fin w → Fin n → Array RationalWord) (base correction : Fin n → Bool)\n    (T : (Fin w → Bool) → EntryWord) : JetReport :=\n  let inputs := Array.ofFn (fun v : Fin w => SemiprimeCorrectedPortBits.acquireCorrectedFin\n    template (source v) tw R J base correction)\n  let out := localEvaluateBits template J w T\n    (fun v => (inputs[v.val]'(by simp [inputs])).words)\n  ⟨out.words,(∑ v : Fin w, (inputs[v.val]'(by simp [inputs])).clock)+out.clock+\n    cacheControl w J template.length⟩\n\n/-- The public variant constructs its width template from original parameter bits. -/\ndef run {n : ℕ} (b w J R : ℕ) (tw : RationalWord)\n    (source : Fin w → Fin n → Array RationalWord) (base correction : Fin n → Bool)\n    (T : (Fin w → Bool) → EntryWord) : JetReport :=\n  nativeLocal (List.replicate (publicWidth b R w) false) w J R tw source base correction T\n\n/-- Exact acquired words always have the requested local output length. -/\ntheorem nativeLocal_size {n : ℕ} (template : List Bool) (w J R : ℕ) (tw : RationalWord)\n    (source : Fin w → Fin n → Array RationalWord) (base correction : Fin n → Bool)\n    (T : (Fin w → Bool) → EntryWord) :\n    (nativeLocal template w J R tw source base correction T).words.size=J := by\n  simp only [nativeLocal,localEvaluateBits_size]\n\n/-- The original rational local tree also retains exactly its requested length. -/\ntheorem localEvaluate_size (J w : ℕ)\n    (T : (Fin w → Bool) → SemiprimeLocalArrayFrontend.EntryReport)\n    (inputs : Fin w → Array ℚ) :\n    (SemiprimeLocalArrayFrontend.localEvaluate J w T inputs).coefficients.size=J := by\n  cases w <;> simp only [SemiprimeLocalArrayFrontend.localEvaluate,\n    SemiprimeArrayOps.scaleJet,SemiprimeArrayOps.addJet,Array.size_ofFn]\n\n/-- Original dyadic source/node bounds control the full corrected-port numerator. -/\ntheorem port_numerator_le (b R J B T n : ℕ)\n    (hJ : J ≤ 2^b) (hB : B ≤ 2^b) (hT : T ≤ 2^b) (hn : n ≤ 2^b) :\n    n*hornerBound J B T (R+1) ≤ 2^(portExponent b R) := by\n  have hh := SemiprimeLocalExecutionBitBounds.hornerBound_le J B T b (R+1) hJ hB hT\n  have hm := Nat.mul_le_mul hn hh\n  convert hm using 1\n  rw [← pow_add]\n  unfold portExponent\n  congr 1\n  omega\n\n/-- Derived public-width correctness of the ACTUAL physical local call, with\nexact decoded arrays and a shared denominator bound for subsequent group folds. -/\ntheorem nativeLocal_correct {n : ℕ} (template : List Bool) (b w R J d B T : ℕ)\n    (source : Fin w → Fin n → Array RationalWord) (tw : RationalWord) (t : ℤ)\n    (base correction : Fin n → Bool) (entries : (Fin w → Bool) → EntryWord)\n    (hwidth : publicWidth b R w ≤ template.length)\n    (hvalid : ∀ v u, Valid (source v u)) (htw : tw.Valid) (htval : tw.value=(t:ℚ))\n    (hd : 0<d) (ht : t.natAbs ≤ T)\n    (hdb : d ≤ 2^b) (hBb : B ≤ 2^b) (hTb : T ≤ 2^b) (hJb : J ≤ 2^b) (hnb : n ≤ 2^b)\n    (hsource : ∀ v u i, i ≤ R → Representation (coefficient (decode (source v u)) i) d B)\n    (hentries : ∀ eta, (entries eta).bits.value.natAbs ≤ 1) :\n    decode (nativeLocal template w J R tw source base correction entries).words=\n      (SemiprimeLocalArrayFrontend.nativeLocal w J R (t:ℚ)\n        (fun v u => decode (source v u)) base correction (table entries)).coefficients ∧\n    Valid (nativeLocal template w J R tw source base correction entries).words ∧\n    ArrayBound (decode (nativeLocal template w J R tw source base correction entries).words)\n      J (d^w) ((localBase J d (n*hornerBound J B T (R+1)))^w) := by\n  let inputs := fun v : Fin w => SemiprimeCorrectedPortBits.acquireCorrectedFin\n    template (source v) tw R J base correction\n  have hp (v : Fin w) : decode (inputs v).words=\n      (SemiprimeLocalArrayFrontend.acquireCorrectedFin (fun u => decode (source v u)) (t:ℚ)\n        R J base correction).coefficients ∧ Valid (inputs v).words := by\n    have hn := SemiprimeCorrectedPortBits.port_numeric_bounds b R J d B T n hdb hBb hTb hJb hnb\n    have hw : SemiprimeCorrectedPortBits.portWidth b R ≤ template.length := by\n      unfold publicWidth at hwidth\n      omega\n    have he := Nat.pow_le_pow_right (by decide : 0<2) hw\n    exact SemiprimeCorrectedPortBits.acquireCorrectedFin_correct template (source v) tw t R J d B T\n      base correction (hvalid v) htw htval hd ht (hn.1.trans_le he) (hn.2.1.trans_le he)\n      (hn.2.2.trans_le he) (hsource v)\n  have hinput (v : Fin w) : ArrayBound (decode (inputs v).words) J d\n      (n*hornerBound J B T (R+1)) := by\n    rw [(hp v).1]\n    exact SemiprimeLocalExecutionHeight.acquireCorrectedFin_bound\n      (fun u => decode (source v u)) t R J d B T base correction ht (hsource v)\n  have hbp : b ≤ portExponent b R := by unfold portExponent; omega\n  have hpow := Nat.pow_le_pow_right (by decide : 0<2) hbp\n  have hlocal := local_correct_at_public_width template J d (n*hornerBound J B T (R+1))\n    (portExponent b R) w (by unfold publicWidth at hwidth; omega) hd\n    (hJb.trans hpow) (hdb.trans hpow) (port_numerator_le b R J B T n hJb hBb hTb hnb)\n    entries (fun v => (inputs v).words) hentries hinput (fun v => (hp v).2)\n  have heq : decode (localEvaluateBits template J w entries (fun v => (inputs v).words)).words=\n      (SemiprimeLocalArrayFrontend.localEvaluate J w (table entries)\n        (fun v => decode (inputs v).words)).coefficients := by\n    apply SemiprimeCorrectedPortBits.array_eq_of_coeff J\n    · simp only [decode_size,localEvaluateBits_size]\n    · exact localEvaluate_size J w _ _\n    · exact hlocal.1\n  have hin : (fun v => decode (inputs v).words)=\n      (fun v => (SemiprimeLocalArrayFrontend.acquireCorrectedFin\n        (fun u => decode (source v u)) (t:ℚ) R J base correction).coefficients) :=\n    funext (fun v => (hp v).1)\n  refine ⟨?_,?_,?_⟩\n  · simpa only [nativeLocal,SemiprimeLocalArrayFrontend.nativeLocal,Array.getElem_ofFn,hin] using heq\n  · simpa only [nativeLocal,Array.getElem_ofFn,inputs] using hlocal.2.1\n  · simpa only [nativeLocal,Array.getElem_ofFn,inputs] using hlocal.2.2\n\n/-- Structural fitting bounds every retained physical local output word. -/\ntheorem nativeLocal_bounded {n : ℕ} (template : List Bool) (w J R : ℕ) (tw : RationalWord)\n    (source : Fin w → Fin n → Array RationalWord) (base correction : Fin n → Bool)\n    (T : (Fin w → Bool) → EntryWord) :\n    Bounded (nativeLocal template w J R tw source base correction T).words template.length := by\n  exact localEvaluateBits_bounded template J w T _\n\n/-- Exact retained clock of the physical port-acquisition/cache/tree composition. -/\ntheorem nativeLocal_clock_eq {n : ℕ} (template : List Bool) (w J R : ℕ) (tw : RationalWord)\n    (source : Fin w → Fin n → Array RationalWord) (base correction : Fin n → Bool)\n    (entries : (Fin w → Bool) → EntryWord) :\n    (nativeLocal template w J R tw source base correction entries).clock=\n      (∑ v : Fin w, (SemiprimeCorrectedPortBits.acquireCorrectedFin\n        template (source v) tw R J base correction).clock)+\n      (localEvaluateBits template J w entries (fun v =>\n        (SemiprimeCorrectedPortBits.acquireCorrectedFin\n          template (source v) tw R J base correction).words)).clock+\n      cacheControl w J template.length := by\n  simp only [nativeLocal,Array.getElem_ofFn]\n\n/-- Explicit native-local physical arithmetic/control budget. The only\nexponential is the actual local arity, never total network incidence. -/\ndef localBudget (n w R J W A E : ℕ) : ℕ :=\n  w*SemiprimeCorrectedPortBitsBounds.portBudget W A R J n+\n    2^w*(E+(w+1)*nodeBudget J W)+cacheControl w J W\n\n/-- All corrected-port reports and every actual original table call are paid.\nInput widths and sizes concern the original encoded cache, not computed Fits. -/\ntheorem nativeLocal_clock {n : ℕ} (template : List Bool) (w J R A E : ℕ) (tw : RationalWord)\n    (source : Fin w → Fin n → Array RationalWord) (base correction : Fin n → Bool)\n    (entries : (Fin w → Bool) → EntryWord) (ht : 0<template.length)\n    (htw : Width tw template.length)\n    (ha : ∀ v u,Bounded (source v u) template.length)\n    (hsize : ∀ v u,(source v u).size ≤ A)\n    (hentries : ∀ eta,(entries eta).clock ≤ E)\n    (hentryWidth : ∀ eta,(entries eta).bits.magnitude.length ≤ template.length) :\n    (nativeLocal template w J R tw source base correction entries).clock ≤\n      localBudget n w R J template.length A E := by\n  have hp := Finset.sum_le_sum (s:=Finset.univ) (fun (v : Fin w) _ =>\n    SemiprimeCorrectedPortBitsBounds.acquireCorrectedFin_clock template (source v) tw R J A\n      base correction ht htw (ha v) (hsize v))\n  simp only [Finset.sum_const,Finset.card_univ,Fintype.card_fin,smul_eq_mul] at hp\n  have hl := local_clock template J w E ht entries\n    (fun v => (SemiprimeCorrectedPortBits.acquireCorrectedFin\n      template (source v) tw R J base correction).words) hentries hentryWidth\n    (fun v => SemiprimeCorrectedPortBitsBounds.acquireCorrectedFin_bounded\n      template (source v) tw R J base correction ht)\n    (fun _ => (SemiprimeCorrectedPortBitsBounds.acquireCorrectedFin_size _ _ _ _ _ _ _).le)\n  rw [nativeLocal_clock_eq]\n  exact Nat.add_le_add_right (Nat.add_le_add hp hl) _\n\n/-- The initialized public local executor is exactly the old rational frontend. -/\ntheorem run_correct {n : ℕ} (b w R J d B T : ℕ)\n    (source : Fin w → Fin n → Array RationalWord) (tw : RationalWord) (t : ℤ)\n    (base correction : Fin n → Bool) (entries : (Fin w → Bool) → EntryWord)\n    (hvalid : ∀ v u, Valid (source v u)) (htw : tw.Valid) (htval : tw.value=(t:ℚ))\n    (hd : 0<d) (ht : t.natAbs ≤ T)\n    (hdb : d ≤ 2^b) (hBb : B ≤ 2^b) (hTb : T ≤ 2^b) (hJb : J ≤ 2^b) (hnb : n ≤ 2^b)\n    (hsource : ∀ v u i, i ≤ R → Representation (coefficient (decode (source v u)) i) d B)\n    (hentries : ∀ eta, (entries eta).bits.value.natAbs ≤ 1) :\n    decode (run b w J R tw source base correction entries).words=\n      (SemiprimeLocalArrayFrontend.nativeLocal w J R (t:ℚ)\n        (fun v u => decode (source v u)) base correction (table entries)).coefficients ∧\n    Valid (run b w J R tw source base correction entries).words ∧\n    ArrayBound (decode (run b w J R tw source base correction entries).words)\n      J (d^w) ((localBase J d (n*hornerBound J B T (R+1)))^w) := by\n  exact nativeLocal_correct _ b w R J d B T source tw t base correction entries\n    (by simp only [List.length_replicate]; exact le_rfl) hvalid htw htval hd ht hdb hBb hTb hJb hnb hsource hentries\n\nend RiemannGaussian.SemiprimeNativeLocalBits\n","RiemannGaussian.SemiprimeNormalizedInverseBitsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeNormalizedInverseBits\n\n/-! # Actual normalized inverse loop clock\nThe bound charges physical arithmetic, cached pair reads, list allocation and\narray-prefix copying. Initial source production and a full address/tape simulation\nare separate. There is no inverse coefficient or intermediate fit input.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeNormalizedInverseBitsBounds\nopen SemiprimeRationalBits SemiprimeDotBits SemiprimeJetBits\nopen SemiprimeNormalizedInverseBits\n\n/-- A polynomial uniform bound for one cached extension. -/\ndef stepBudget (W A J : ℕ) : ℕ :=\n  J*(40000*(W+1)^3+4)+4+20000*(W+1)^3+\n    J*((A+1)*(2*W+3)+(J+1)*(2*W+3)+5)+\n    (J+1)*(2*W+3)+2*W+10\n\n/-- Paid pair formation and scalar operations are bounded at every prefix. -/\ntheorem extend_clock (template : List Bool) (ht : 0<template.length)\n    (a : Array RationalWord) (A J n : ℕ) (old : JetReport)\n    (ha : a.size≤A) (hn : n≤J) (hold : old.words.size≤J)\n    (haw : Bounded a template.length) (how : Bounded old.words template.length) :\n    (extend template a n old).clock≤old.clock+stepBudget template.length A J := by\n  by_cases hz : n=0\n  · simp only [extend,ite_eq_left hz]\n    unfold stepBudget\n    omega\n  · have hp (p) (hm : p∈pairs a old.words n) : Width p.1 template.length ∧ Width p.2 template.length := by\n      obtain ⟨i,rfl⟩ := List.mem_ofFn.mp hm\n      exact ⟨wordAt_width a ht haw _,wordAt_width old.words ht how _⟩\n    have hs := dotBits_cost template ht (pairs a old.words n) hp\n    rw [pairs_length] at hs\n    have ho := executeOperation_cost .neg (dotBits template (pairs a old.words n)).word\n      zeroWord template (dotBits_width template ht _) (show Width zeroWord template.length from ⟨by simp [zeroWord],by simpa [zeroWord] using (show 1≤template.length by omega)⟩) le_rfl\n    have hm : n*(accessCost template a+accessCost template old.words+5)+\n        (old.words.size+1)*(2*template.length+3) ≤\n        J*((A+1)*(2*template.length+3)+(J+1)*(2*template.length+3)+5)+\n          (J+1)*(2*template.length+3) := by\n      unfold accessCost\n      gcongr\n    have hn' := Nat.mul_le_mul_right (40000*(template.length+1)^3+4) hn\n    simp only [extend,ite_eq_right hz]\n    unfold stepBudget\n    omega\n\n/-- Polynomial clock for the actual complete cached inverse construction. -/\ntheorem build_clock (template : List Bool) (ht : 0<template.length)\n    (a : Array RationalWord) (A J : ℕ) (ha : a.size≤A)\n    (haw : Bounded a template.length) :\n    ∀ n≤J, (build template a n).clock≤1+n*stepBudget template.length A J := by\n  intro n hn\n  induction n with\n  | zero => simp [build]\n  | succ n ih =>\n    have hc := extend_clock template ht a A J n (build template a n) ha (by omega)\n      (by simpa using (show n≤J by omega)) haw (build_bounded template ht a n)\n    have hh := ih (by omega)\n    change (extend template a n (build template a n)).clock≤_\n    calc\n      _ ≤ (build template a n).clock+stepBudget template.length A J := hc\n      _ ≤ 1+(n+1)*stepBudget template.length A J := by nlinarith\n\nend RiemannGaussian.SemiprimeNormalizedInverseBitsBounds\n","RiemannGaussian.SemiprimePartnerRecoveryObstruction":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeRowPartnerOffsets\n\n/-!\n# Reciprocal degeneracy of the actual residue-partner recovery equations\n\nSwapped public coefficient rows have an exact integral index transport.\nAfter that transport, the N-normalized reciprocal of the partner's\nquadratic is a scalar multiple of the original quadratic, for every index\nin any commutative ring. Their genuine Sylvester resultant is identically\nzero, even with a symbolic index. The true-factor witnesses satisfy this\nsame relation: there is no second independent polynomial equation from\nthis pairing. Integrality, other rows, and useful cross-residue incidence\nremain separate arithmetic requirements.\n-/\n\nnamespace RiemannGaussian.SemiprimePartnerRecoveryObstruction\n\nopen SemiprimeQuotientRows SemiprimeQuotientCentering SemiprimeEuclidRowFamily\nopen SemiprimeCompanionRows SemiprimeCompanionCenterSpectrum SemiprimeAffineRowRoots\nopen SemiprimeRowAreaSpectrum SemiprimeRowPartnerOffsets SemiprimeCenteredOffsetExtractor\nopen Polynomial\n\n/-- The exact public correction between the two hidden collision indices. -/\ndef partnerStep (m : ℕ) (u v : FamilyPacket) (s : ℤ) : ℤ :=\n  partnerDelta m u v s/(m : ℤ)^2\n\n/-- The quotient is exact on the original public source. -/\ntheorem publicPacket_partner_step_exact {N m : ℕ} (hm : 0<m)\n    {u v : FamilyPacket} (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) :\n    packetOffset m v=s*packetOffset m u+(m : ℤ)^2*partnerStep m u v s := by\n  have he := Int.mul_ediv_cancel' (publicPacket_partner_delta_dvd hm hu hv s ha ht hprod)\n  change (m : ℤ)^2*partnerStep m u v s=partnerDelta m u v s at he\n  unfold partnerDelta at he\n  linear_combination -he\n\n/-- Opposite public centers give only a zero or one-step change of index. -/\ntheorem publicPacket_partner_step_cases {N m : ℕ} (hm : 0<m)\n    {u v : FamilyPacket} (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (hs : s=-1 ∨ s=1) (ha : v.original.a=s*u.original.t)\n    (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) (side : Bool)\n    (huc : CenterChoice N m u side) (hvc : CenterChoice N m v (!side)) :\n    partnerStep m u v s=0 ∨ partnerStep m u v s=1 ∨ partnerStep m u v s=-1 := by\n  have hmz : (0 : ℤ)<m := by exact_mod_cast hm\n  have hpow := sq_pos_of_pos hmz\n  have hd := publicPacket_partner_delta_dvd hm hu hv s ha ht hprod\n  have hb := partner_delta_abs_le hm u v s hs ha ht side huc hvc\n  have he := Int.mul_ediv_cancel' hd\n  change (m : ℤ)^2*partnerStep m u v s=partnerDelta m u v s at he\n  rcases bounded_multiple hpow hd hb with h0|hplus|hminus\n  · left\n    apply mul_left_cancel₀ hpow.ne'\n    simpa only [h0,mul_zero] using he\n  · right; left\n    apply mul_left_cancel₀ hpow.ne'\n    simpa only [hplus,mul_one] using he\n  · right; right\n    apply mul_left_cancel₀ hpow.ne'\n    simpa only [hminus,mul_neg_one] using he\n\n/-- Keep the actual signed factor sum before eliminating an unknown index. -/\ndef factorSum (m : ℕ) (w : FamilyPacket) (p q : ℤ) : ℤ :=\n  w.original.a*p+packetOffset m w+w.original.t*q\n\n/-- Swapping the factor orientation supplies the same linear equation. -/\ntheorem partner_factor_sum (m : ℕ) (u v : FamilyPacket) (s p q : ℤ)\n    (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a) :\n    factorSum m v q p=s*factorSum m u p q+partnerDelta m u v s := by\n  simp only [factorSum,partnerDelta,ha,ht]\n  ring\n\n/-- Every actual packet at the true residue has an integral collision index.\nNo short-window assumption, primality, or balanced-ratio assumption is used. -/\ntheorem publicPacket_factor_index {p q m : ℕ} (hm : 0<m) (hp : 0<p)\n    {w : FamilyPacket} (hw : w∈publicPackets (p*q) m) (hj : w.residue=p%m) :\n    ∃ i : ℤ, (m : ℤ)^2*i=factorSum m w p q ∧\n      quadratic (centeredPacketRow m w).a (centeredPacketRow m w).b\n        (centeredPacketRow m w).c (p/m : ℕ)=(p : ℤ)*i := by\n  have hcoord : (p : ℤ)=(m : ℤ)*(p/m : ℕ)+w.residue := by\n    rw [hj]\n    have hd := Nat.mod_add_div p m\n    exact_mod_cast (by omega : p=m*(p/m)+p%m)\n  have hcop : IsCoprime (p : ℤ) (m : ℤ) := by\n    obtain ⟨x,y,hxy⟩ := (publicPacket_residue_coprime hw).isCoprime\n    refine ⟨x,y-x*(p/m : ℕ),?_⟩\n    linear_combination hxy+x*hcoord\n  have hrel : quotientRelation ((p : ℤ)*q) m w.residue\n      (centeredPacketRow m w).a (centeredPacketRow m w).b\n      (centeredPacketRow m w).c (centeredPacketRow m w).t := by\n    simpa only [Nat.cast_mul] using publicPacket_relation hm hw\n  obtain ⟨i,hi⟩ := quotient_row_integer_index hcoord hrel hcop\n  refine ⟨i,?_,hi⟩\n  have he := scaled_quadratic_factor_sum hcoord hrel\n  rw [hi] at he\n  have hpz : (p : ℤ)≠0 := by exact_mod_cast hp.ne'\n  apply mul_left_cancel₀ hpz\n  simp only [factorSum,packetOffset,centeredPacketRow,shiftRow] at he ⊢\n  linear_combination he\n\n/-- The integral indices of the two true-factor rows are affinely dependent. -/\ntheorem publicPacket_factor_indices_related {p q m : ℕ} (hm : 0<m)\n    (hp : 0<p) (hq : 0<q) {u v : FamilyPacket}\n    (hu : u∈publicPackets (p*q) m) (hv : v∈publicPackets (p*q) m)\n    (hj : u.residue=p%m) (hk : v.residue=q%m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a) :\n    ∃ i k : ℤ, (m : ℤ)^2*i=factorSum m u p q ∧\n      (m : ℤ)^2*k=factorSum m v q p ∧ k=s*i+partnerStep m u v s := by\n  obtain ⟨i,hi,_⟩ := publicPacket_factor_index hm hp hu hj\n  obtain ⟨k,hkIndex,_⟩ := publicPacket_factor_index (p:=q) (q:=p) hm hq\n    (by simpa only [Nat.mul_comm q p] using hv) hk\n  have hprod : (m : ℤ)∣(p*q : ℕ)-(u.residue : ℤ)*v.residue := by\n    simpa only [hj,hk,Nat.cast_mul] using factor_residue_product_dvd p q m\n  have hstep := publicPacket_partner_step_exact hm hu hv s ha ht hprod\n  have hsum := partner_factor_sum m u v s p q ha ht\n  have hmz : (0 : ℤ)<m := by exact_mod_cast hm\n  refine ⟨i,k,hi,hkIndex,?_⟩\n  apply mul_left_cancel₀ (sq_pos_of_pos hmz).ne'\n  rw [hkIndex]\n  unfold partnerDelta at hsum\n  linear_combination hsum-s*hi+hstep\n\n/-- The quadratic in the original factor coordinate, retaining its unknown index. -/\nnoncomputable def recoveryPolynomial {R : Type*} [CommRing R]\n    (N m : ℕ) (w : FamilyPacket) (i : R) : R[X] :=\n  quadraticPolynomial (w.original.a : R)\n    ((packetOffset m w : R)-(m : R)^2*i) ((N : R)*(w.original.t : R))\n\n/-- N-normalized reciprocal coefficient form for the partner factor N/x. -/\nnoncomputable def reciprocalRecoveryPolynomial {R : Type*} [CommRing R]\n    (N m : ℕ) (w : FamilyPacket) (i : R) : R[X] :=\n  quadraticPolynomial (w.original.t : R)\n    ((packetOffset m w : R)-(m : R)^2*i) ((N : R)*(w.original.a : R))\n\n/-- The reciprocal coefficient form is the original polynomial at the\npartner coordinate, with only the exact known factors x² and N cleared. -/\ntheorem recovery_reciprocal_evaluation {R : Type*} [CommRing R]\n    (N m : ℕ) (w : FamilyPacket) (i x y : R) (hxy : x*y=(N : R)) :\n    x^2*(recoveryPolynomial N m w i).eval y=\n      (N : R)*(reciprocalRecoveryPolynomial N m w i).eval x := by\n  simp only [recoveryPolynomial,reciprocalRecoveryPolynomial,quadraticPolynomial,\n    eval_add,eval_mul,eval_C,eval_pow,eval_X]\n  linear_combination (w.original.a : R)*(x*y+(N : R))*hxy+\n    ((packetOffset m w : R)-(m : R)^2*i)*x*hxy\n\n/-- The retained factor sum gives the literal recovery equation at p. -/\ntheorem recovery_eval_of_factor_sum (p q m : ℕ) (w : FamilyPacket) (i : ℤ)\n    (hi : (m : ℤ)^2*i=factorSum m w p q) :\n    (recoveryPolynomial (p*q) m w i).eval (p : ℤ)=0 := by\n  simp only [recoveryPolynomial,quadraticPolynomial,eval_add,eval_mul,eval_C,\n    eval_pow,eval_X,Int.cast_id,Nat.cast_mul]\n  unfold factorSum at hi\n  linear_combination -(p : ℤ)*hi\n\n/-- Both original recovery equations have the true factor roots at their\ntransported integral indices. Their later reciprocal degeneracy does not\nerase these roots or prove that a correct index has been found publicly. -/\ntheorem publicPacket_factor_partner_recovery {p q m : ℕ} (hm : 0<m)\n    (hp : 0<p) (hq : 0<q) {u v : FamilyPacket}\n    (hu : u∈publicPackets (p*q) m) (hv : v∈publicPackets (p*q) m)\n    (hj : u.residue=p%m) (hk : v.residue=q%m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a) :\n    ∃ i : ℤ, (recoveryPolynomial (p*q) m u i).eval (p : ℤ)=0 ∧\n      (recoveryPolynomial (p*q) m v (s*i+partnerStep m u v s)).eval (q : ℤ)=0 := by\n  obtain ⟨i,k,hi,hkIndex,htransport⟩ :=\n    publicPacket_factor_indices_related hm hp hq hu hv hj hk s ha ht\n  refine ⟨i,recovery_eval_of_factor_sum p q m u i hi,?_⟩\n  have he := recovery_eval_of_factor_sum q p m v k hkIndex\n  simpa only [Nat.mul_comm q p,htransport] using he\n\n/-- The reciprocal partner equation is redundant for every possible index.\nThe ring may itself be a polynomial ring in a symbolic index. -/\ntheorem publicPacket_reciprocal_recovery_eq {R : Type*} [CommRing R]\n    {N m : ℕ} (hm : 0<m) {u v : FamilyPacket}\n    (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) (i : R) :\n    reciprocalRecoveryPolynomial N m v ((s : R)*i+(partnerStep m u v s : R))=\n      C (s : R)*recoveryPolynomial N m u i := by\n  have he := congrArg (fun z : ℤ => (z : R))\n    (publicPacket_partner_step_exact hm hu hv s ha ht hprod)\n  simp only [Int.cast_add,Int.cast_mul,Int.cast_pow,Int.cast_natCast] at he\n  simp only [reciprocalRecoveryPolynomial,recoveryPolynomial,quadraticPolynomial,\n    ha,ht,Int.cast_mul,he,map_add,map_sub,map_mul,map_pow]\n  ring\n\n/-- Genuine Sylvester elimination gives zero identically, not a factor test. -/\ntheorem publicPacket_partner_recovery_resultant_zero {R : Type*} [CommRing R]\n    {N m : ℕ} (hm : 0<m) {u v : FamilyPacket}\n    (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) (i : R) :\n    Polynomial.resultant (recoveryPolynomial N m u i)\n      (reciprocalRecoveryPolynomial N m v ((s : R)*i+(partnerStep m u v s : R)))\n      2 2=0 := by\n  have he := congrArg (fun z : ℤ => (z : R))\n    (publicPacket_partner_step_exact hm hu hv s ha ht hprod)\n  simp only [Int.cast_add,Int.cast_mul,Int.cast_pow,Int.cast_natCast] at he\n  unfold recoveryPolynomial reciprocalRecoveryPolynomial\n  rw [quadratic_resultant]\n  simp only [ha,ht,Int.cast_mul,he]\n  ring\n\n/-- Eliminating the factor coordinate still gives the zero polynomial when\nthe index itself is left symbolic. This is not merely a true-index zero. -/\ntheorem publicPacket_symbolic_partner_resultant_zero {N m : ℕ} (hm : 0<m)\n    {u v : FamilyPacket} (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) :\n    Polynomial.resultant (recoveryPolynomial N m u (X : ℤ[X]))\n      (reciprocalRecoveryPolynomial N m v\n        ((s : ℤ[X])*X+(partnerStep m u v s : ℤ[X]))) 2 2=0 :=\n  publicPacket_partner_recovery_resultant_zero hm hu hv s ha ht hprod X\n\n/-- Every integer index gives full saturation, so this test selects no index.\nSolving a recovery quadratic after its correct index is known is a separate step. -/\ntheorem publicPacket_partner_resultant_saturated {N m : ℕ} (hm : 0<m)\n    {u v : FamilyPacket} (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) (i : ℤ) :\n    N.gcd (Polynomial.resultant (recoveryPolynomial N m u i)\n      (reciprocalRecoveryPolynomial N m v (s*i+partnerStep m u v s)) 2 2).natAbs=N := by\n  have he : Polynomial.resultant (recoveryPolynomial N m u i)\n      (reciprocalRecoveryPolynomial N m v (s*i+partnerStep m u v s)) 2 2=0 := by\n    simpa only [Int.cast_id] using\n      publicPacket_partner_recovery_resultant_zero hm hu hv s ha ht hprod i\n  rw [he]\n  simp only [Int.natAbs_zero,Nat.gcd_zero_right]\n\n/-- The actual two factor residues satisfy the symbolic obstruction directly. -/\ntheorem publicPacket_factor_partner_symbolic_resultant_zero {p q m : ℕ} (hm : 0<m)\n    {u v : FamilyPacket} (hu : u∈publicPackets (p*q) m) (hv : v∈publicPackets (p*q) m)\n    (hj : u.residue=p%m) (hk : v.residue=q%m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a) :\n    Polynomial.resultant (recoveryPolynomial (p*q) m u (X : ℤ[X]))\n      (reciprocalRecoveryPolynomial (p*q) m v\n        ((s : ℤ[X])*X+(partnerStep m u v s : ℤ[X]))) 2 2=0 := by\n  have hprod : (m : ℤ)∣(p*q : ℕ)-(u.residue : ℤ)*v.residue := by\n    simpa only [hj,hk,Nat.cast_mul] using factor_residue_product_dvd p q m\n  exact publicPacket_symbolic_partner_resultant_zero hm hu hv s ha ht hprod\n\nend RiemannGaussian.SemiprimePartnerRecoveryObstruction\n","RiemannGaussian.SemiprimePublicAcquiredExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeAcquiredPrefixSearch\nimport RiemannGaussian.SemiprimeMacroFiniteEnumerations\nimport RiemannGaussian.SemiprimePublicConstructedCount\nimport RiemannGaussian.SemiprimeSubdividedEntry\n\n/-! # Executed acquired counter on the public integer factoring graph -/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimePublicAcquiredExecution\nopen scoped BigOperators\nopen SemiprimeMacroGraph SemiprimeMacroGraphSemantics SemiprimeMacroParameters\nopen SemiprimeMacroFiniteEnumerations SemiprimeMacroEntryBitPrimitives\nopen SemiprimeCountRecovery SemiprimeCounterSearch\n\n/-- Actual public half-edge type, without a polynomial layout parameter. -/\nabbrev PublicEdge (N : ℕ) := Edge (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N))\n/-- Actual public arithmetic and equality vertices. -/\nabbrev PublicVertex (N : ℕ) := SubdividedVertex (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N))\n/-- Explicit ascending-constructor enumeration of all public wires. -/\ndef edgeEnumeration (N : ℕ) := edges (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N))\n/-- Explicit constructor enumeration of all public vertices. -/\ndef vertexEnumeration (N : ℕ) := subdividedVertices (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N))\n/-- Runtime number of public wire bits. -/\ndef wireCount (N : ℕ) : ℕ := (edgeEnumeration N).values.length\n/-- Runtime number of actual public factors in the tensor network. -/\ndef factorCount (N : ℕ) : ℕ := (vertexEnumeration N).values.length\n/-- Public graph arity after its explicit finite indexing. -/\ndef indexedArity (N : ℕ) (e : Fin (factorCount N)) : ℕ := subdividedArity ((vertexEnumeration N).equivFin e)\n/-- Literal port-to-wire map in finite indices. -/\ndef indexedCoordinate (N : ℕ) (hN : 0<N) (e : Fin (factorCount N)) (i : Fin (indexedArity N e)) : Fin (wireCount N) :=\n  (edgeEnumeration N).equivFin.symm (SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN)\n    ((vertexEnumeration N).equivFin e) i)\n/-- Paid original arithmetic/equality local checker, not a supplied acceptance table. -/\ndef indexedEntry (N : ℕ) (hN : 0<N) (e : Fin (factorCount N)) (input : Fin (indexedArity N e) → Bool) : CheckRun :=\n  SemiprimeSubdividedEntry.publicSubdividedEntry N hN ((vertexEnumeration N).equivFin e) input\n\n/-- Exact port reindexing preserves all original incidences. -/\ndef portEquiv (N : ℕ) :\n    ((e : Fin (factorCount N)) × Fin (indexedArity N e)) ≃\n      ((v : PublicVertex N) × Fin (subdividedArity v)) :=\n  Equiv.sigmaCongr (vertexEnumeration N).equivFin (fun _ => Equiv.refl _)\n\n/-- Every indexed wire occurs in an actual public scope. -/\ntheorem indexed_coverage (N : ℕ) (hN : 0<N) (a : Fin (wireCount N)) :\n    ∃ e i, indexedCoordinate N hN e i=a := by\n  obtain ⟨v,i,hi⟩ := SemiprimePublicConstructedCount.public_coverage (bitLength_pos hN)\n    ((edgeEnumeration N).equivFin a)\n  let p := (portEquiv N).symm ⟨v,i⟩\n  have hp : portEquiv N p=⟨v,i⟩ := (portEquiv N).apply_symm_apply ⟨v,i⟩\n  refine ⟨p.1,p.2,?_⟩\n  apply (edgeEnumeration N).equivFin.injective\n  change (edgeEnumeration N).equivFin ((edgeEnumeration N).equivFin.symm\n    (SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN) (portEquiv N p).1 (portEquiv N p).2)) = _\n  rw [Equiv.apply_symm_apply,hp]\n  exact hi\n\n/-- Finite reindexing retains the actual occurrence-two source load B=2. -/\ntheorem indexed_occurrences (N : ℕ) (hN : 0<N) (a : Fin (wireCount N)) :\n    (Finset.univ.filter (fun i : (e : Fin (factorCount N)) × Fin (indexedArity N e) =>\n      indexedCoordinate N hN i.1 i.2=a)).card ≤ 2 := by\n  classical\n  let target := (edgeEnumeration N).equivFin a\n  let f : {p : (e : Fin (factorCount N)) × Fin (indexedArity N e) // indexedCoordinate N hN p.1 p.2=a} →\n      {p : (v : PublicVertex N) × Fin (subdividedArity v) //\n        SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN) p.1 p.2=target} :=\n    fun p => ⟨portEquiv N p.val, by\n      change SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN)\n        ((vertexEnumeration N).equivFin p.val.1) p.val.2=target\n      have h := congrArg (edgeEnumeration N).equivFin p.property\n      simpa only [indexedCoordinate, Equiv.apply_symm_apply] using h⟩\n  have hf : Function.Injective f := by\n    intro p q h\n    apply Subtype.ext\n    exact (portEquiv N).injective (congrArg Subtype.val h)\n  have hc := Fintype.card_le_of_injective f hf\n  have ho := SemiprimeScheduledCounter.public_occurrences (bitLength_pos hN) target\n  have hc' : (Finset.univ.filter (fun p : (e : Fin (factorCount N)) × Fin (indexedArity N e) =>\n      indexedCoordinate N hN p.1 p.2=a)).card ≤ (Finset.univ.filter (fun p : (v : PublicVertex N) × Fin (subdividedArity v) =>\n      SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN) p.1 p.2=target)).card := by\n    simpa only [Fintype.card_subtype] using hc\n  exact hc'.trans ho\n\n/-- The executed indexed checker is exactly the actual public tensor table. -/\ntheorem indexedEntry_correct (N : ℕ) (hN : 0<N) (e : Fin (factorCount N)) (input : Fin (indexedArity N e) → Bool) :\n    (indexedEntry N hN e input).accepted =\n      subdividedTable (SemiprimePublicFactorCount.publicConfig N hN) ((vertexEnumeration N).equivFin e) input :=\n  SemiprimeSubdividedEntry.publicSubdividedEntry_correct N hN _ input\n\n/-- Original public accepting predicate in the executed finite wire indices. -/\ndef indexedPredicate (N : ℕ) (hN : 0<N) : Finset (Fin (wireCount N)) → Bool :=\n  originalPredicate (indexedArity N) (fun e a => (indexedEntry N hN e a).accepted) (indexedCoordinate N hN)\n\n/-- Indexed acceptance gives the true public subdivided arithmetic graph. -/\ntheorem indexed_to_public (N : ℕ) (hN : 0<N) (x : Finset (Fin (wireCount N)))\n    (hx : indexedPredicate N hN x=true) :\n    SubdividedAccepted (SemiprimePublicFactorCount.publicConfig N hN)\n      (fun a => assignmentBit x ((edgeEnumeration N).equivFin.symm a)) := by\n  have hh : ∀ e, (indexedEntry N hN e (fun i => assignmentBit x (indexedCoordinate N hN e i))).accepted=true :=\n    by simpa only [indexedPredicate, originalPredicate, decide_eq_true_eq] using hx\n  intro v\n  obtain ⟨e,rfl⟩ := (vertexEnumeration N).equivFin.surjective v\n  exact (indexedEntry_correct N hN e _).symm.trans (hh e)\n\n/-- Actual natural prefix count of the public integer, using the source interpreter. -/\ndef prefixCount (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (fixed : List (Fin (wireCount N) × Bool)) : ℕ :=\n  SemiprimeAcquiredPrefixSearch.prefixCount (r := r) (Q := Q)\n    (indexedArity N) (indexedCoordinate N hN) eps R 2 J (indexedEntry N hN) fixed\n\n/-- Every requested prefix is counted by the same actual public network. -/\ntheorem prefixCount_correct (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (fixed : List (Fin (wireCount N) × Bool)) :\n    prefixCount N hN r Q eps R J fixed =\n      acceptedCount (restricted assignmentBit (indexedPredicate N hN) fixed) :=\n  SemiprimeAcquiredPrefixSearch.prefixCount_correct (indexedArity N) (indexedCoordinate N hN)\n    eps R 2 J (indexedEntry N hN) (indexed_occurrences N hN) (indexed_coverage N hN)\n    hQ hAQ hJ hprecision fixed\n\n/-- Literal zero-first search over the actual public half-edge list. -/\ndef search (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) :\n    SearchResult (Fin (wireCount N)) :=\n  SemiprimeCountRecovery.search (prefixCount N hN r Q eps R J) (List.finRange (wireCount N))\n\n/-- Explicit transport between indexed and original Boolean wire functions. -/\ndef assignmentEquiv (N : ℕ) : (Fin (wireCount N) → Bool) ≃ (PublicEdge N → Bool) where\n  toFun f a := f ((edgeEnumeration N).equivFin.symm a)\n  invFun f i := f ((edgeEnumeration N).equivFin i)\n  left_inv f := by funext i; exact congrArg f ((edgeEnumeration N).equivFin.symm_apply_apply i)\n  right_inv f := by funext i; simp\n\n/-- The indexed whole public predicate counts exactly ordinary ordered factor pairs. -/\ntheorem indexed_factor_count (N : ℕ) (hN : 0<N) :\n    acceptedCount (indexedPredicate N hN)=Fintype.card (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  classical\n  unfold indexedPredicate\n  rw [SemiprimePublicConstructedCount.accepted_eq_tensor]\n  have hs : (∑ a : Fin (wireCount N) → Bool, ∏ e : Fin (factorCount N),\n      if (indexedEntry N hN e (fun i => a (indexedCoordinate N hN e i))).accepted then (1 : ℕ) else 0) =\n      (∑ a : PublicEdge N → Bool, ∏ v : PublicVertex N,\n        if subdividedTable (SemiprimePublicFactorCount.publicConfig N hN) v\n          (fun i => a (SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN) v i)) then (1 : ℕ) else 0) := by\n    apply Fintype.sum_equiv (assignmentEquiv N)\n    intro a\n    simp only [indexedEntry_correct]\n    exact (vertexEnumeration N).equivFin.prod_comp\n      (fun v => if subdividedTable (SemiprimePublicFactorCount.publicConfig N hN) v\n        (fun i => a ((edgeEnumeration N).equivFin.symm\n          (SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN) v i))) then (1 : ℕ) else 0)\n  exact hs.trans (SemiprimePublicFactorCount.public_tensor_factor_count N hN)\n\n/-- The acquired empty-prefix count is the actual ordinary factor cardinal. -/\ntheorem factor_count (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J) :\n    prefixCount N hN r Q eps R J []=Fintype.card (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [prefixCount_correct N hN r Q eps R J hQ hAQ hJ hprecision]\n  have he : restricted assignmentBit (indexedPredicate N hN) []=indexedPredicate N hN := by\n    funext x\n    simp only [restricted,List.all_nil,Bool.and_true]\n  rw [he]\n  exact indexed_factor_count N hN\n\n/-- Decode physical input words by the literal little-endian bit algorithm.\nNo classical BitVec inverse or public normalizer is evaluated. -/\ndef decodeOperand (N : ℕ) (values : List (Fin (wireCount N) × Bool)) (side : Fin 2) : ℕ :=\n  let length := firstAxis (bitLength N)*secondAxis (bitLength N)\n  ∑ i ∈ Finset.range (digitCount (bitLength N)),\n    (if hi : i<length then SemiprimeMacroEntryExecution.binaryDecode\n      (fun bit : Fin (length+1) => SemiprimeAcquiredPrefixSearch.selectedBits values\n        ((edgeEnumeration N).equivFin.symm ((.inl (.input side ⟨i,hi⟩,bit)),false))) else 0) *\n      (2^radixBits (bitLength N))^i\n\n/-- The physical bit decoder is exactly the source operand used in the arithmetic proof. -/\ntheorem decodeOperand_eq (N : ℕ) (hN : 0<N) (values : List (Fin (wireCount N) × Bool)) (side : Fin 2) :\n    decodeOperand N values side = sourceOperand (SemiprimePublicFactorCount.publicConfig N hN)\n      (fun signal => SemiprimeAcquiredPrefixSearch.selectedBits values\n        ((edgeEnumeration N).equivFin.symm (signal,false))) side := by\n  unfold decodeOperand sourceOperand sourceFunction wordNat\n  simp only [SemiprimeMacroEntryExecution.readWord_eq_binaryDecode]\n  rfl\n\n/-- The actual executed prefix search returns a proper integer factor. -/\ndef factor (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) : Option ℕ :=\n  (search N hN r Q eps R J).values.map (fun values => decodeOperand N values 0)\n\n/-- Every executed search branch uses the same acquired counter and has a common original witness. -/\ntheorem search_sound (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (values : List (Fin (wireCount N) × Bool))\n    (h : (search N hN r Q eps R J).values=some values) :\n    values.map Prod.fst=List.finRange (wireCount N) ∧\n      ∃ x, indexedPredicate N hN x=true ∧ ∀ p ∈ values, assignmentBit x p.1=p.2 :=\n  SemiprimeCountRecovery.search_some_sound (prefixCount N hN r Q eps R J) assignmentBit\n    (indexedPredicate N hN) (prefixCount_correct N hN r Q eps R J hQ hAQ hJ hprecision)\n    (List.finRange (wireCount N)) values h\n\n/-- The reconstructed selected wires have genuine nontrivial product N. -/\ntheorem selected_factor_pair (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (values : List (Fin (wireCount N) × Bool))\n    (h : (search N hN r Q eps R J).values=some values) :\n    2≤decodeOperand N values 0 ∧ 2≤decodeOperand N values 1 ∧\n      decodeOperand N values 0*decodeOperand N values 1=N := by\n  obtain ⟨hindices,x,hx,hbits⟩ := search_sound N hN r Q eps R J hQ hAQ hJ hprecision values h\n  have hcover (i : Fin (wireCount N)) : ∃ p ∈ values, p.1=i := by\n    have hi : i ∈ values.map Prod.fst := by rw [hindices]; exact List.mem_finRange i\n    exact List.mem_map.mp hi\n  have heq : SemiprimeAcquiredPrefixSearch.selectedBits values=assignmentBit x := by\n    funext i\n    exact SemiprimeAcquiredPrefixSearch.selectedBits_eq values _ hcover hbits i\n  have hp := subdivided_factor_pair (SemiprimePublicFactorCount.publicConfig N hN) _\n    (indexed_to_public N hN x hx)\n  have hdec (side : Fin 2) : decodeOperand N values side =\n      sourceOperand (SemiprimePublicFactorCount.publicConfig N hN)\n        (fun signal => assignmentBit x ((edgeEnumeration N).equivFin.symm (signal,false))) side := by\n    rw [decodeOperand_eq N hN values side]\n    congr 1\n    funext signal\n    exact congrFun heq _\n  refine ⟨hp.1.trans_eq (hdec 0).symm,hp.2.1.trans_eq (hdec 1).symm,?_⟩\n  exact ((congrArg₂ (fun a b : ℕ => a*b) (hdec 0) (hdec 1)).trans hp.2.2).trans\n    (SemiprimePublicFactorCount.public_target_value N hN)\n\n/-- A returned value is an actual proper divisor, with no modular or ring-only decoder. -/\ntheorem factor_sound (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (p : ℕ) (h : factor N hN r Q eps R J=some p) : 2≤p ∧ p<N ∧ p∣N := by\n  unfold factor at h\n  obtain ⟨values,hvalues,hp⟩ := Option.map_eq_some_iff.mp h\n  obtain ⟨hle,hright,hprod⟩ := selected_factor_pair N hN r Q eps R J hQ hAQ hJ hprecision values hvalues\n  subst p\n  refine ⟨hle,?_,⟨decodeOperand N values 1,hprod.symm⟩⟩\n  nlinarith\n\n/-- Actual acquired search fails exactly when the integer has no ordinary proper factor pair. -/\ntheorem search_none_iff (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J) :\n    (search N hN r Q eps R J).values=none ↔\n      ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  classical\n  have hs := SemiprimeCountRecovery.search_none_iff (prefixCount N hN r Q eps R J) assignmentBit\n    (indexedPredicate N hN) (prefixCount_correct N hN r Q eps R J hQ hAQ hJ hprecision)\n    (List.finRange (wireCount N))\n  have he : (∃ x, indexedPredicate N hN x=true) ↔ Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n    rw [← acceptedCount_pos_iff, indexed_factor_count, Fintype.card_pos_iff]\n  exact hs.trans (not_congr he)\n\n/-- The returned integer algorithm is complete as well as sound, including squares. -/\ntheorem factor_none_iff (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J) :\n    factor N hN r Q eps R J=none ↔ ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [factor,Option.map_eq_none_iff]\n  exact search_none_iff N hN r Q eps R J hQ hAQ hJ hprecision\n\n/-- Recovery makes one initial and at most one actual conditional query per half-edge. -/\ntheorem search_queries (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) :\n    (search N hN r Q eps R J).queries ≤ wireCount N+1 := by\n  simpa only [search,List.length_finRange] using SemiprimeCountRecovery.search_queries_le\n    (prefixCount N hN r Q eps R J) (List.finRange (wireCount N))\n\n/-- Finite indexing preserves the actual public variable-count schedule exactly. -/\ntheorem wireCount_eq (N : ℕ) : wireCount N=variableCount (bitLength N) :=\n  (edgeEnumeration N).length_eq_card\n\n/-- The indexed runtime scopes retain the actual public arity bound. -/\ntheorem indexedArity_le (N : ℕ) (e : Fin (factorCount N)) :\n    indexedArity N e ≤ scopeBound (bitLength N) := actual_arity_le _\n\n/-- Every original public callback has its proved polynomial bit-checker cost. -/\ntheorem indexedEntry_clock (N : ℕ) (hN : 0<N) (e : Fin (factorCount N))\n    (input : Fin (indexedArity N e) → Bool) :\n    (indexedEntry N hN e input).clock≤1048576*(64*bitLength N+2)^10 :=\n  SemiprimeSubdividedEntry.publicSubdividedEntry_polynomial N hN _ input\n\n/-- Natural-input wrapper; zero is rejected by an actual decidable branch. -/\ndef factorNat (N r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) : Option ℕ :=\n  if hN : 0<N then factor N hN r Q eps R J else none\n\n/-- Every output of the natural-input wrapper is a proper divisor of its input. -/\ntheorem factorNat_sound (N r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (p : ℕ) (h : factorNat N r Q eps R J=some p) : 2≤p ∧ p<N ∧ p∣N := by\n  unfold factorNat at h\n  split_ifs at h with hN\n  · exact factor_sound N hN r Q eps R J hQ hAQ hJ hprecision p h\n\n/-- The actual finite port enumeration has exactly two ports per Boolean wire. -/\ntheorem indexed_incidence_count (N : ℕ) (hN : 0<N) :\n    (∑ e, indexedArity N e)=2*wireCount N := by\n  have h := Fintype.card_congr (portEquiv N)\n  have hc : Fintype.card ((e : Fin (factorCount N)) × Fin (indexedArity N e))=\n      ∑ e, indexedArity N e := by simp only [Fintype.card_sigma,Fintype.card_fin]\n  rw [hc] at h\n  exact h.trans ((SemiprimeScheduledCounter.public_incidence_card (bitLength_pos hN)).trans\n    (congrArg (fun a => 2*a) (wireCount_eq N).symm))\n\nend RiemannGaussian.SemiprimePublicAcquiredExecution\n","RiemannGaussian.SemiprimeRepresentativeExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeCounterCompose\nimport RiemannGaussian.SemiprimeLayoutCertificates\n\n/-!\n# Executed search for a shared-summary representative\n\nThe binary traversal keeps a single found Boolean word and charges every actual\nmeasurement callback. No table of all Boolean words or chosen representative\nis an input. Its interpretation in a node certificate is proved separately.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeRepresentativeExecution\nopen scoped BigOperators\n\n/-- A computed Boolean gate and its charged local work. -/\nstructure TestReport where\n  /-- The actual comparison result. -/\n  accepted : Bool\n  /-- Arithmetic, reads and control operations of this test. -/\n  work : ℕ\n\n/-- Search output with the work of every visited test and branch. -/\nstructure SearchReport (n : ℕ) where\n  /-- One successful assignment, or no successful assignment. -/\n  found : Option (Fin n → Bool)\n  /-- Callback work plus traversal control charges. -/\n  work : ℕ\n  /-- Number of actual leaf tests. -/\n  tests : ℕ\n\n/-- False-first depth-first search, stopping after its first successful leaf. -/\ndef findBits : (n : ℕ) → ((Fin n → Bool) → TestReport) → SearchReport n\n  | 0, test =>\n      let result := test Fin.elim0\n      ⟨if result.accepted then some Fin.elim0 else none, result.work+1, 1⟩\n  | n+1, test =>\n      let left := findBits n (fun x => test (Fin.cons false x))\n      match left.found with\n      | some x => ⟨some (Fin.cons false x),left.work+1,left.tests⟩\n      | none =>\n          let right := findBits n (fun x => test (Fin.cons true x))\n          ⟨right.found.map (Fin.cons true),left.work+right.work+1,left.tests+right.tests⟩\n\n/-- Every returned word actually passed its supplied computed test. -/\ntheorem findBits_sound (n : ℕ) (test : (Fin n → Bool) → TestReport)\n    (x : Fin n → Bool) (h : (findBits n test).found = some x) :\n    (test x).accepted = true := by\n  induction n with\n  | zero =>\n    have hx : x = Fin.elim0 := by funext i; exact Fin.elim0 i\n    subst x\n    cases ht : (test Fin.elim0).accepted <;> simp [findBits,ht] at h ⊢\n  | succ n ih =>\n    simp only [findBits] at h\n    split at h\n    · rename_i a ha\n      have hx := Option.some.inj h\n      subst x\n      exact ih _ a ha\n    · rename_i ha\n      obtain ⟨a, ha', hx⟩ := Option.map_eq_some_iff.mp h\n      subst x\n      exact ih _ a ha'\n\n/-- Failure is equivalent to failure of every Boolean assignment, not a search cap. -/\ntheorem findBits_none_iff (n : ℕ) (test : (Fin n → Bool) → TestReport) :\n    (findBits n test).found = none ↔ ∀ x, (test x).accepted = false := by\n  induction n with\n  | zero =>\n    have hx (x : Fin 0 → Bool) : x = Fin.elim0 := by funext i; exact Fin.elim0 i\n    simp [findBits, hx]\n  | succ n ih =>\n    have hcons (x : Fin (n+1) → Bool) : Fin.cons (x 0) (fun i => x i.succ) = x := by\n      funext i\n      exact Fin.cases rfl (fun _ => rfl) i\n    simp only [findBits]\n    split\n    · rename_i a ha\n      constructor\n      · intro h; cases h\n      · intro h\n        have ht := findBits_sound n (fun x => test (Fin.cons false x)) a ha\n        rw [h (Fin.cons false a)] at ht\n        cases ht\n    · rename_i ha\n      rw [Option.map_eq_none_iff, ih]\n      have hf := (ih (fun x => test (Fin.cons false x))).mp ha\n      constructor\n      · intro ht x\n        rw [← hcons x]\n        cases h : x 0\n        · exact hf _\n        · exact ht _\n      · intro h x\n        exact h _\n\n/-- Every tested word is paid; both branches together visit at most 2^n leaves. -/\ntheorem findBits_tests (n : ℕ) (test : (Fin n → Bool) → TestReport) :\n    (findBits n test).tests ≤ 2^n := by\n  induction n with\n  | zero => simp [findBits]\n  | succ n ih =>\n    simp only [findBits]\n    split\n    · have hl := ih (fun x => test (Fin.cons false x))\n      dsimp only\n      rw [pow_succ]\n      omega\n    · have hl := ih (fun x => test (Fin.cons false x))\n      have hr := ih (fun x => test (Fin.cons true x))\n      dsimp only\n      rw [pow_succ]\n      omega\n\n/-- The same actual search includes all supplied callback costs and tree control. -/\ntheorem findBits_work (n B : ℕ) (test : (Fin n → Bool) → TestReport)\n    (h : ∀ x, (test x).work ≤ B) :\n    (findBits n test).work + 1 ≤ 2^n * (B+2) := by\n  induction n with\n  | zero => simpa only [findBits, pow_zero, one_mul] using Nat.add_le_add_right (h Fin.elim0) 2\n  | succ n ih =>\n    have hl := ih (fun x => test (Fin.cons false x)) (fun x => h _)\n    have hr := ih (fun x => test (Fin.cons true x)) (fun x => h _)\n    simp only [findBits]\n    split\n    · rw [pow_succ]\n      have hp : 0 < 2^n * (B+2) := by positivity\n      nlinarith\n    · rw [pow_succ]\n      nlinarith\n\n/-- Actual representative word; an empty fibre receives the literal false word. -/\ndef representative (n : ℕ) (test : (Fin n → Bool) → TestReport) : Fin n → Bool :=\n  (findBits n test).found.getD (fun _ => false)\n\n/-- A nonempty fibre always receives a computed successful representative. -/\ntheorem representative_valid (n : ℕ) (test : (Fin n → Bool) → TestReport)\n    (h : ∃ x, (test x).accepted = true) :\n    (test (representative n test)).accepted = true := by\n  cases he : (findBits n test).found with\n  | none =>\n    obtain ⟨x,hx⟩ := h\n    have hf := (findBits_none_iff n test).mp he x\n    rw [hf] at hx\n    cases hx\n  | some x =>\n    simpa only [representative,he,Option.getD_some] using findBits_sound n test x he\n\n/-- Integer dot product of one measurement row with a Boolean word. -/\ndef dotBits : (n : ℕ) → (Fin n → ℤ) → (Fin n → Bool) → ℤ\n  | 0, _, _ => 0\n  | n+1, row, bits =>\n      (if bits 0 then row 0 else 0) + dotBits n (fun i => row i.succ) (fun i => bits i.succ)\n\ntheorem dotBits_value (n : ℕ) (row : Fin n → ℤ) (bits : Fin n → Bool) :\n    dotBits n row bits = ∑ i, if bits i then row i else 0 := by\n  induction n with\n  | zero => simp [dotBits]\n  | succ n ih => rw [dotBits, Fin.sum_univ_succ, ih]\n\n/-- The actual integer scalar and its charged reads, branch and addition. -/\nstructure DotReport where\n  /-- Computed integer dot product. -/\n  value : ℤ\n  /-- Selected integer arithmetic/read charges. -/\n  work : ℕ\n\n/-- A dot-product loop with charges attached to its sole recursive call. -/\ndef dotRun : (n : ℕ) → (Fin n → ℤ) → (Fin n → Bool) → DotReport\n  | 0, _, _ => ⟨0,1⟩\n  | n+1, row, bits =>\n      let tail := dotRun n (fun i => row i.succ) (fun i => bits i.succ)\n      ⟨(if bits 0 then row 0 else 0)+tail.value,tail.work+4⟩\n\ntheorem dotRun_value (n : ℕ) (row : Fin n → ℤ) (bits : Fin n → Bool) :\n    (dotRun n row bits).value = dotBits n row bits := by\n  induction n with\n  | zero => rfl\n  | succ n ih => simp only [dotRun,dotBits,ih]\n\ntheorem dotRun_work (n : ℕ) (row : Fin n → ℤ) (bits : Fin n → Bool) :\n    (dotRun n row bits).work = 4*n+1 := by\n  induction n with\n  | zero => rfl\n  | succ n ih => simp only [dotRun,ih]; omega\n\n/-- Every row test computes its actual integer dot product and target equality. -/\ndef measurementTest (n : ℕ) : (m : ℕ) → (Fin m → Fin n → ℤ) →\n    (Fin m → ℤ) → (Fin n → Bool) → TestReport\n  | 0, _, _, _ => ⟨true,1⟩\n  | m+1, rows, target, bits =>\n      let tail := measurementTest n m (fun i => rows i.succ) (fun i => target i.succ) bits\n      let dot := dotRun n (rows 0) bits\n      ⟨decide (dot.value = target 0) && tail.accepted,tail.work+dot.work+2⟩\n\n/-- Exact finite measurement equality; there is no supplied correct-test oracle. -/\ntheorem measurementTest_correct (n m : ℕ) (rows : Fin m → Fin n → ℤ)\n    (target : Fin m → ℤ) (bits : Fin n → Bool) :\n    (measurementTest n m rows target bits).accepted = true ↔\n      ∀ j, (∑ i, if bits i then rows j i else 0) = target j := by\n  induction m with\n  | zero => simp [measurementTest]\n  | succ m ih =>\n    simp only [measurementTest,Bool.and_eq_true,decide_eq_true_eq,dotRun_value,dotBits_value,ih]\n    constructor\n    · rintro ⟨h0,hs⟩ j\n      exact Fin.cases h0 hs j\n    · intro h\n      exact ⟨h 0,fun j => h j.succ⟩\n\n/-- Measurement arithmetic/reads/control is linear in the literal matrix size.\nInteger bit arithmetic and physical array lookup costs must still be supplied. -/\ntheorem measurementTest_work (n m : ℕ) (rows : Fin m → Fin n → ℤ)\n    (target : Fin m → ℤ) (bits : Fin n → Bool) :\n    (measurementTest n m rows target bits).work = m*(4*n+3)+1 := by\n  induction m with\n  | zero => simp [measurementTest]\n  | succ m ih => simp only [measurementTest,ih,dotRun_work]; ring\n\n/-- Concrete search over the actual integer measurement equations. -/\ndef measuredRepresentative (n m : ℕ) (rows : Fin m → Fin n → ℤ)\n    (target : Fin m → ℤ) : SearchReport n := findBits n (measurementTest n m rows target)\n\ntheorem measuredRepresentative_sound (n m : ℕ) (rows : Fin m → Fin n → ℤ)\n    (target : Fin m → ℤ) (bits : Fin n → Bool)\n    (h : (measuredRepresentative n m rows target).found = some bits) :\n    ∀ j, (∑ i, if bits i then rows j i else 0) = target j :=\n  (measurementTest_correct n m rows target bits).mp (findBits_sound n _ bits h)\n\ntheorem measuredRepresentative_work (n m : ℕ) (rows : Fin m → Fin n → ℤ)\n    (target : Fin m → ℤ) :\n    (measuredRepresentative n m rows target).work + 1 ≤ 2^n*(m*(4*n+3)+3) :=\n  findBits_work n (m*(4*n+3)+1) _ (fun x => (measurementTest_work n m rows target x).le)\n\n/-- Decode a signed summary box using public natural dimensions. -/\ndef summaryTarget (n m W : ℕ)\n    (y : SemiprimeLayoutCertificates.Summary (Fin n) (Fin m) W) : Fin m → ℤ :=\n  fun j => (y j).val - (n*W : ℕ)\n\n/-- Actual integer equality tests are exactly the existing node measurement. -/\ntheorem summaryTest_correct (n m W : ℕ) (rows : Fin m → Fin n → ℤ)\n    (hrows : ∀ j i, |rows j i| ≤ (W : ℤ))\n    (y : SemiprimeLayoutCertificates.Summary (Fin n) (Fin m) W) (bits : Fin n → Bool) :\n    (measurementTest n m rows (summaryTarget n m W y) bits).accepted = true ↔\n      SemiprimeLayoutCertificates.measurement rows W hrows bits = y := by\n  rw [measurementTest_correct]\n  have hs (j : Fin m) : SemiprimeLayoutCertificates.signature rows bits j =\n      ∑ i, if bits i then rows j i else 0 := by\n    simp only [SemiprimeLayoutCertificates.signature, mul_ite, mul_one, mul_zero]\n  have hv (j : Fin m) :\n      ((SemiprimeLayoutCertificates.measurement rows W hrows bits j).val : ℤ) =\n        (∑ i, if bits i then rows j i else 0) + (n*W : ℕ) := by\n    have hb := abs_le.mp (SemiprimeLayoutCertificates.signature_bound rows W hrows bits j)\n    simp only [Fintype.card_fin, hs] at hb\n    simp only [SemiprimeLayoutCertificates.measurement,Fintype.card_fin,hs]\n    omega\n  constructor\n  · intro h\n    funext j\n    apply Fin.ext\n    have hj := h j\n    have he := hv j\n    simp only [summaryTarget] at hj\n    omega\n  · intro h j\n    have he := hv j\n    rw [h] at he\n    simp only [summaryTarget]\n    omega\n\n/-- The data path for the representative of an actual bounded integer row system. -/\ndef summaryRepresentative (n m W : ℕ) (rows : Fin m → Fin n → ℤ)\n    (y : SemiprimeLayoutCertificates.Summary (Fin n) (Fin m) W) : Fin n → Bool :=\n  representative n (measurementTest n m rows (summaryTarget n m W y))\n\n/-- Native summary representatives are computed by finite scans, not chosen. -/\ntheorem summaryRepresentative_valid (n m W : ℕ) (rows : Fin m → Fin n → ℤ)\n    (hrows : ∀ j i, |rows j i| ≤ (W : ℤ))\n    (y : SemiprimeLayoutCertificates.Summary (Fin n) (Fin m) W)\n    (hy : ∃ bits, SemiprimeLayoutCertificates.measurement rows W hrows bits = y) :\n    SemiprimeLayoutCertificates.measurement rows W hrows\n      (summaryRepresentative n m W rows y) = y := by\n  apply (summaryTest_correct n m W rows hrows y _).mp\n  apply representative_valid\n  obtain ⟨bits,hbits⟩ := hy\n  exact ⟨bits,(summaryTest_correct n m W rows hrows y bits).mpr hbits⟩\n\n/-- Literal forced-bit conjunction on one local word. -/\ndef forcedTest : (n : ℕ) → (Fin n → Bool) → (Fin n → Bool) → TestReport\n  | 0, _, _ => ⟨true,1⟩\n  | n+1, forced, bits =>\n      let tail := forcedTest n (fun i => forced i.succ) (fun i => bits i.succ)\n      ⟨(!forced 0 || bits 0) && tail.accepted,tail.work+4⟩\n\ntheorem forcedTest_correct (n : ℕ) (forced bits : Fin n → Bool) :\n    (forcedTest n forced bits).accepted = true ↔\n      ∀ i, forced i = true → bits i = true := by\n  induction n with\n  | zero => simp [forcedTest]\n  | succ n ih =>\n    simp only [forcedTest,Bool.and_eq_true,ih]\n    have hh : (!forced 0 || bits 0) = true ↔ (forced 0 = true → bits 0 = true) := by\n      cases forced 0 <;> cases bits 0 <;> decide\n    rw [hh]\n    constructor\n    · rintro ⟨h0,hs⟩ i\n      exact Fin.cases h0 hs i\n    · intro h\n      exact ⟨h 0,fun i => h i.succ⟩\n\ntheorem forcedTest_work (n : ℕ) (forced bits : Fin n → Bool) :\n    (forcedTest n forced bits).work = 4*n+1 := by\n  induction n with\n  | zero => rfl\n  | succ n ih => simp only [forcedTest,ih]; omega\n\n/-- One retained computed Boolean representative per head group. -/\nstructure RepresentativeFamily {r : ℕ} (h : Fin r → ℕ) where\n  /-- Retained computed local words. -/\n  words : (g : Fin r) → Fin (h g) → Bool\n  /-- Total representative search and branch charges. -/\n  work : ℕ\n\n/-- Every group search is executed once and its resulting word is retained. -/\ndef acquireRepresentatives : (r : ℕ) → (h m W : Fin r → ℕ) →\n    ((g : Fin r) → Fin (m g) → Fin (h g) → ℤ) →\n    ((g : Fin r) → SemiprimeLayoutCertificates.Summary (Fin (h g)) (Fin (m g)) (W g)) →\n    RepresentativeFamily h\n  | 0, _, _, _, _, _ => ⟨fun g => Fin.elim0 g,0⟩\n  | r+1, h, m, W, rows, y =>\n      let head := measuredRepresentative (h 0) (m 0) (rows 0) (summaryTarget (h 0) (m 0) (W 0) (y 0))\n      let tail := acquireRepresentatives r (fun i => h i.succ) (fun i => m i.succ)\n        (fun i => W i.succ) (fun i => rows i.succ) (fun i => y i.succ)\n      ⟨Fin.cons (head.found.getD (fun _ => false)) tail.words,head.work+tail.work+1⟩\n\ntheorem acquireRepresentatives_words (r : ℕ) (h m W : Fin r → ℕ)\n    (rows : (g : Fin r) → Fin (m g) → Fin (h g) → ℤ)\n    (y : (g : Fin r) → SemiprimeLayoutCertificates.Summary (Fin (h g)) (Fin (m g)) (W g))\n    (g : Fin r) :\n    (acquireRepresentatives r h m W rows y).words g =\n      summaryRepresentative (h g) (m g) (W g) (rows g) (y g) := by\n  induction r with\n  | zero => exact Fin.elim0 g\n  | succ r ih =>\n    refine Fin.cases ?_ (fun i => ?_) g\n    · rfl\n    · exact ih _ _ _ _ _ i\n\ntheorem acquireRepresentatives_work (r : ℕ) (h m W : Fin r → ℕ)\n    (rows : (g : Fin r) → Fin (m g) → Fin (h g) → ℤ)\n    (y : (g : Fin r) → SemiprimeLayoutCertificates.Summary (Fin (h g)) (Fin (m g)) (W g)) :\n    (acquireRepresentatives r h m W rows y).work =\n      (∑ g, (measuredRepresentative (h g) (m g) (rows g)\n        (summaryTarget (h g) (m g) (W g) (y g))).work) + r := by\n  induction r with\n  | zero => simp [acquireRepresentatives]\n  | succ r ih => simp only [acquireRepresentatives,ih,Fin.sum_univ_succ]; omega\n\ntheorem acquireRepresentatives_work_le (r : ℕ) (h m W : Fin r → ℕ)\n    (rows : (g : Fin r) → Fin (m g) → Fin (h g) → ℤ)\n    (y : (g : Fin r) → SemiprimeLayoutCertificates.Summary (Fin (h g)) (Fin (m g)) (W g)) :\n    (acquireRepresentatives r h m W rows y).work ≤\n      ∑ g, 2^(h g)*((m g)*(4*(h g)+3)+3) := by\n  rw [acquireRepresentatives_work]\n  have he := Finset.sum_le_sum (s := Finset.univ) (fun (g : Fin r) _ =>\n    measuredRepresentative_work (h g) (m g) (rows g) (summaryTarget (h g) (m g) (W g) (y g)))\n  simpa only [Finset.sum_add_distrib,Finset.sum_const,Finset.card_univ,\n    Fintype.card_fin,smul_eq_mul,mul_one] using he\n\nend RiemannGaussian.SemiprimeRepresentativeExecution\n","RiemannGaussian.SemiprimeSameResidueAreas":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeRowAreaSpectrum\n\n/-!\n# Same-residue area obstruction with both centers retained\n\nThe original Euclidean stream has the stronger coefficient envelope\n|a|+t ≤ m. This bounds the mixed-center area direction by m³, before any\nresidue division. On balanced semiprimes the public center difference is\nat most p+2. Thus, beyond a small-factor prefix, every same-residue triple\nhas zero or unit area, even when its centers differ. Cross-residue areas\nand universal sixth-root factoring remain open.\n-/\n\nnamespace RiemannGaussian.SemiprimeSameResidueAreas\n\nopen SemiprimeQuotientRows SemiprimeQuotientCentering SemiprimeEuclidRowFamily\nopen SemiprimeWeightedRows SemiprimeCompanionRows SemiprimeCompanionCenterSpectrum\nopen SemiprimeAffineRowRoots SemiprimeCenteredOffsetExtractor SemiprimeAnchoredRowAreas\nopen SemiprimeRowAreaSpectrum\n\n/-- Keep the signed numerator and denominator together until their joint bound. -/\ntheorem euclidPairs_sum_le {m r₀ r₁ x y : ℕ} {negative : Bool}\n    (horder : r₁<r₀) (hy : 0<y) (hdet : r₀*y+r₁*x=m)\n    {z : ℤ×ℕ} (hz : z∈euclidPairs r₀ r₁ x y negative) : z.1.natAbs+z.2≤m := by\n  rw [euclidPairs] at hz\n  split_ifs at hz with hr\n  · simp only [List.not_mem_nil] at hz\n  · have hrpos : 0<r₁ := by omega\n    simp only [List.mem_cons,List.mem_append,List.mem_map] at hz\n    rcases hz with hcur|hmid|htail\n    · subst z\n      simp only [signed_natAbs]\n      have h₁ := Nat.mul_le_mul_right y (show r₁+1≤r₀ by omega)\n      have h₂ := Nat.mul_le_mul_left r₁ (show 1≤y by omega)\n      nlinarith only [h₁,h₂,hdet,Nat.zero_le (r₁*x)]\n    · obtain ⟨k,hk,rfl⟩ := hmid\n      simp only [signed_natAbs]\n      have hk' : k+1<r₀/r₁ := by have := List.mem_range.mp hk; omega\n      have hmul : (k+1)*r₁≤r₀ :=\n        (Nat.mul_le_mul_right r₁ hk'.le).trans (Nat.div_mul_le_self _ _)\n      have hs := congrArg (fun z => z*y) (Nat.sub_add_cancel hmul)\n      have hn : (r₀-(k+1)*r₁)*y+r₁*(x+(k+1)*y)=m := by\n        nlinarith only [hs,hdet]\n      have h₁ := Nat.mul_le_mul_left (r₀-(k+1)*r₁) (show 1≤y by omega)\n      have h₂ := Nat.le_mul_of_pos_left (x+(k+1)*y) hrpos\n      omega\n    · have hq : 0<r₀/r₁ := Nat.div_pos horder.le hrpos\n      have hn : r₁*(x+r₀/r₁*y)+(r₀%r₁)*y=m := by\n        rw [←euclid_determinant_step,hdet]\n      exact euclidPairs_sum_le (Nat.mod_lt _ hrpos) (by positivity) hn htail\ntermination_by r₁\ndecreasing_by exact Nat.mod_lt _ (by omega)\n\ntheorem publicPairs_sum_le {N m j : ℕ} (hm : 0<m) {z : ℤ×ℕ}\n    (hz : z∈publicPairs N m j) : z.1.natAbs+z.2≤m :=\n  euclidPairs_sum_le (Nat.mod_lt _ hm) (by decide) (by simp) hz\n\n/-- The original public constructor supplies a diamond, rather than only a box. -/\ntheorem publicPacket_coefficient_sum_le {N m : ℕ} (hm : 0<m) {w : FamilyPacket}\n    (hw : w∈publicPackets N m) : |w.original.a|+|w.original.t|≤(m : ℤ) := by\n  obtain ⟨j,_,hw⟩ := List.mem_flatMap.mp hw\n  split_ifs at hw\n  · obtain ⟨z,hz,hw⟩ := List.mem_flatMap.mp hw\n    have hb := publicPairs_sum_le hm hz\n    simp only [List.mem_cons,List.not_mem_nil,or_false] at hw\n    rcases hw with rfl|rfl\n    all_goals\n      change |z.1|+|(z.2 : ℤ)|≤(m : ℤ)\n      rw [Int.abs_eq_natAbs,abs_of_nonneg (Int.natCast_nonneg z.2)]\n      exact_mod_cast hb\n  · simp only [List.not_mem_nil] at hw\n\n/-- A signed coefficient minor respects the full joint envelope. -/\ntheorem publicPacket_minor_abs_le {N m : ℕ} (hm : 0<m) {u w : FamilyPacket}\n    (hu : u∈publicPackets N m) (hw : w∈publicPackets N m) :\n    |denominatorMinor u w|≤(m : ℤ)^2 := by\n  have hub := publicPacket_coefficient_sum_le hm hu\n  have hwb := publicPacket_coefficient_sum_le hm hw\n  have h := abs_sub_le (u.original.a*w.original.t) 0 (w.original.a*u.original.t)\n  simp only [sub_zero,zero_sub,abs_neg,abs_mul] at h\n  have hprod := mul_le_mul hub hwb\n    (add_nonneg (abs_nonneg _) (abs_nonneg _)) (Int.natCast_nonneg m)\n  have hdiag₁ := mul_nonneg (abs_nonneg u.original.a) (abs_nonneg w.original.a)\n  have hdiag₂ := mul_nonneg (abs_nonneg u.original.t) (abs_nonneg w.original.t)\n  unfold denominatorMinor\n  nlinarith only [h,hprod,hdiag₁,hdiag₂]\n\ntheorem centerFlag_difference_abs_le (us ws : Bool) : |centerFlag us-centerFlag ws|≤1 := by\n  cases us <;> cases ws <;> norm_num [centerFlag]\n\n/-- One differing center contributes a signed minor with its full source retained. -/\ntheorem mixedArea_middle_center (u w v : FamilyPacket) (us ws : Bool) :\n    mixedArea u w v us ws us=(centerFlag ws-centerFlag us)*\n      (w.original.a-w.original.t)*denominatorMinor u v := by\n  simp [mixedArea,denominatorMinor,Matrix.det_fin_three]\n  ring\n\ntheorem publicPacket_center_minor_abs_le {N m : ℕ} (hm : 0<m) {u w v : FamilyPacket}\n    (hu : u∈publicPackets N m) (hw : w∈publicPackets N m) (hv : v∈publicPackets N m)\n    (us ws : Bool) :\n    |(centerFlag us-centerFlag ws)*(u.original.a-u.original.t)*denominatorMinor w v|≤\n      (m : ℤ)^3 := by\n  have hdiff := abs_sub_le u.original.a 0 u.original.t\n  simp only [sub_zero,zero_sub,abs_neg] at hdiff\n  have hc := hdiff.trans (publicPacket_coefficient_sum_le hm hu)\n  have hf := centerFlag_difference_abs_le us ws\n  have hd := publicPacket_minor_abs_le hm hw hv\n  rw [abs_mul,abs_mul]\n  calc\n    _ ≤ (1*(m : ℤ))*(m : ℤ)^2 :=\n      mul_le_mul (mul_le_mul hf hc (abs_nonneg _) (by decide : (0 : ℤ)≤1)) hd\n        (abs_nonneg _) (by positivity)\n    _ = _ := by ring\n\n/-- Both public centers, in all eight orientations, satisfy the cubic envelope. -/\ntheorem publicPacket_mixedArea_abs_le {N m : ℕ} (hm : 0<m) {u w v : FamilyPacket}\n    (hu : u∈publicPackets N m) (hw : w∈publicPackets N m) (hv : v∈publicPackets N m)\n    (us ws vs : Bool) : |mixedArea u w v us ws vs|≤(m : ℤ)^3 := by\n  cases us <;> cases ws <;> cases vs\n  · rw [mixedArea_same_center,abs_zero]; positivity\n  · rw [mixedArea_last_center,neg_mul,neg_mul,abs_neg]\n    exact publicPacket_center_minor_abs_le hm hv hu hw true false\n  · rw [mixedArea_middle_center]\n    exact publicPacket_center_minor_abs_le hm hw hu hv true false\n  · rw [mixedArea_first_center,neg_mul,neg_mul,abs_neg]\n    exact publicPacket_center_minor_abs_le hm hu hw hv false true\n  · rw [mixedArea_first_center,neg_mul,neg_mul,abs_neg]\n    exact publicPacket_center_minor_abs_le hm hu hw hv true false\n  · rw [mixedArea_middle_center]\n    exact publicPacket_center_minor_abs_le hm hw hu hv false true\n  · rw [mixedArea_last_center,neg_mul,neg_mul,abs_neg]\n    exact publicPacket_center_minor_abs_le hm hv hu hw false true\n  · rw [mixedArea_same_center,abs_zero]; positivity\n\ntheorem centerDifference_nonneg (N : ℕ) : 0≤centerDifference N := by\n  have h := Nat.sqrt_le_sqrt ((Nat.div_le_self N 2).trans (show N≤2*N by omega))\n  have hz : ((N/2).sqrt : ℤ)≤(2*N).sqrt := by exact_mod_cast h\n  simp [centerDifference,centerA]\n  omega\n\n/-- Floor-square-root errors are retained in the public center bound. -/\ntheorem sqrt_center_difference_le (N : ℕ) : (2*N).sqrt≤2*(N/2).sqrt+2 := by\n  have hh := Nat.sqrt_le' (2*N)\n  have hl := Nat.lt_succ_sqrt' (N/2)\n  have hd := Nat.mod_add_div N 2\n  have hr := Nat.mod_lt N (by decide : 0<2)\n  nlinarith only [hh,hl,hd,hr]\n\ntheorem balanced_centerDifference_abs_le {p q : ℕ} (hq : q≤2*p) :\n    |centerDifference (p*q)|≤(p : ℤ)+2 := by\n  have hN : p*q≤2*p^2 := by nlinarith only [Nat.mul_le_mul_left p hq]\n  have hdiv : p*q/2≤p^2 := by have := Nat.div_mul_le_self (p*q) 2; omega\n  have hl : (p*q/2).sqrt≤p := by nlinarith only [Nat.sqrt_le' (p*q/2),hdiv]\n  have hc := sqrt_center_difference_le (p*q)\n  have hb : (2*(p*q)).sqrt≤(p*q/2).sqrt+p+2 := by omega\n  have hbz : ((2*(p*q)).sqrt : ℤ)≤((p*q/2).sqrt : ℤ)+p+2 := by exact_mod_cast hb\n  rw [abs_of_nonneg (centerDifference_nonneg (p*q))]\n  simp [centerDifference,centerA]\n  omega\n\n/-- The mixed-center channel is bounded before the common residue division. -/\ntheorem publicPacket_mixed_area_bound {N m : ℕ} (hm : 0<m) {u w v : FamilyPacket}\n    (hu : u∈publicPackets N m) (hw : w∈publicPackets N m) (hv : v∈publicPackets N m)\n    (us ws vs : Bool) (huc : CenterChoice N m u us) (hwc : CenterChoice N m w ws)\n    (hvc : CenterChoice N m v vs) :\n    2*|rowArea m u w v|≤6*(m : ℤ)^4+|centerDifference N| *(m : ℤ)^3 := by\n  have he := mixed_center_area u w v us ws vs huc hwc hvc\n  have hb := publicPacket_errorArea_abs_le hm hu hw hv us ws vs\n  have hmixed := publicPacket_mixedArea_abs_le hm hu hw hv us ws vs\n  have ht := abs_sub_le (-errorArea N m u w v us ws vs) 0\n    (centerDifference N*mixedArea u w v us ws vs)\n  simp only [sub_zero,zero_sub,abs_neg,abs_mul] at ht\n  have habs := congrArg abs he\n  rw [abs_mul] at habs\n  norm_num at habs\n  have hp := mul_le_mul_of_nonneg_left hmixed (abs_nonneg (centerDifference N))\n  nlinarith only [habs,ht,hb,hp]\n\n/-- Divide the combined signed area, rather than dividing its channels separately. -/\ntheorem publicPacket_same_residue_normalized_bound {N m : ℕ} (hm : 0<m)\n    (hcop : m.Coprime N) {u w v : FamilyPacket} (hu : u∈publicPackets N m)\n    (hw : w∈publicPackets N m) (hv : v∈publicPackets N m)\n    (hwu : w.residue=u.residue) (hvu : v.residue=u.residue) :\n    2*|residueArea m u w v|≤6*(m : ℤ)+|centerDifference N| := by\n  obtain ⟨us,huc⟩ := publicPacket_center_choice hu\n  obtain ⟨ws,hwc⟩ := publicPacket_center_choice hw\n  obtain ⟨vs,hvc⟩ := publicPacket_center_choice hv\n  have hb := publicPacket_mixed_area_bound hm hu hw hv us ws vs huc hwc hvc\n  rw [publicPacket_residueArea_exact hm hcop hu hw hv hwu hvu,abs_mul,\n    abs_of_pos (by positivity : (0 : ℤ)<(m : ℤ)^3)] at hb\n  apply (mul_le_mul_iff_right₀ (by positivity : (0 : ℤ)<(m : ℤ)^3)).mp\n  nlinarith only [hb]\n\n/-- A nonzero signed integer smaller than both primes is a unit, including squares. -/\ntheorem bounded_int_isUnit {p q : ℕ} (hp : p.Prime) (hq : q.Prime) {k : ℤ}\n    (hk : k≠0) (hkp : |k|<(p : ℤ)) (hkq : |k|<(q : ℤ)) :\n    IsUnit (k : ZMod (p*q)) := by\n  have hpos := Int.natAbs_pos.mpr hk\n  have hnp : k.natAbs<p := by rw [Int.abs_eq_natAbs] at hkp; exact_mod_cast hkp\n  have hnq : k.natAbs<q := by rw [Int.abs_eq_natAbs] at hkq; exact_mod_cast hkq\n  have hpc := (hp.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt hpos hnp)).symm\n  have hqc := (hq.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt hpos hnq)).symm\n  have hu := (ZMod.isUnit_iff_coprime k.natAbs (p*q)).mpr (hpc.mul_right hqc)\n  have habsu : IsUnit ((|k| : ℤ) : ZMod (p*q)) := by\n    simpa only [Int.abs_eq_natAbs,Int.cast_natCast] using hu\n  by_cases hnonneg : 0≤k\n  · simpa only [abs_of_nonneg hnonneg] using habsu\n  · rw [abs_of_neg (lt_of_not_ge hnonneg),Int.cast_neg] at habsu\n    simpa only [neg_neg] using habsu.neg\n\n/-- Every same-residue triple is zero or unit in the balanced hard branch.\nAll centers are supplied by actual public membership. -/\ntheorem balanced_publicPacket_same_residue_zero_or_unit {p q m : ℕ} (hm : 0<m)\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≤q) (hqp : q≤2*p)\n    (hcop : m.Coprime (p*q)) (hpm : 6*m+2<p) {u w v : FamilyPacket}\n    (hu : u∈publicPackets (p*q) m) (hw : w∈publicPackets (p*q) m)\n    (hv : v∈publicPackets (p*q) m) (hwu : w.residue=u.residue)\n    (hvu : v.residue=u.residue) :\n    rowArea m u w v=0 ∨ IsUnit (rowArea m u w v : ZMod (p*q)) := by\n  have he := publicPacket_residueArea_exact hm hcop hu hw hv hwu hvu\n  have hb := publicPacket_same_residue_normalized_bound hm hcop hu hw hv hwu hvu\n  have hc := balanced_centerDifference_abs_le hqp\n  have hpmz : 6*(m : ℤ)+2<p := by exact_mod_cast hpm\n  have hpqz : (p : ℤ)≤q := by exact_mod_cast hpq\n  have hkp : |residueArea m u w v|<(p : ℤ) := by nlinarith only [hb,hc,hpmz]\n  by_cases hk : residueArea m u w v=0\n  · exact Or.inl (by rw [he,hk,mul_zero])\n  · apply Or.inr\n    have hkunit := bounded_int_isUnit hp hq hk hkp (hkp.trans_le hpqz)\n    have hmunit := (ZMod.isUnit_iff_coprime m (p*q)).mpr hcop\n    rw [he]\n    push_cast\n    exact (hmunit.pow 3).mul hkunit\n\ntheorem balanced_publicPacket_same_residue_no_proper_gcd {p q m : ℕ} (hm : 0<m)\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≤q) (hqp : q≤2*p)\n    (hcop : m.Coprime (p*q)) (hpm : 6*m+2<p) {u w v : FamilyPacket}\n    (hu : u∈publicPackets (p*q) m) (hw : w∈publicPackets (p*q) m)\n    (hv : v∈publicPackets (p*q) m) (hwu : w.residue=u.residue)\n    (hvu : v.residue=u.residue) :\n    ¬SemiprimeGroupSelection.ProperDivisor (p*q)\n      ((p*q).gcd (rowArea m u w v : ZMod (p*q)).val) := by\n  let : NeZero (p*q) := ⟨(Nat.mul_pos hp.pos hq.pos).ne'⟩\n  rcases balanced_publicPacket_same_residue_zero_or_unit hm hp hq hpq hqp hcop hpm\n      hu hw hv hwu hvu with hz|hunit\n  · simp only [hz,Int.cast_zero,ZMod.val_zero,Nat.gcd_zero_right,\n      SemiprimeGroupSelection.ProperDivisor,lt_self_iff_false,and_false,false_and,not_false_eq_true]\n  · rw [(SemiprimeBulkNorm.gcd_one_iff_unit _).mpr hunit]\n    simp only [SemiprimeGroupSelection.ProperDivisor,lt_self_iff_false,false_and,not_false_eq_true]\n\nend RiemannGaussian.SemiprimeSameResidueAreas\n","RiemannGaussian.SemiprimeSeedLazyJets":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeIndexReader\nimport Mathlib.LinearAlgebra.Matrix.Notation\n\n/-!\n# Lazy marked-jet acquisition and a fixed geometric recurrence\n\nThe original detector and both derivative channels are retained in four\nscalar components. One auxiliary component carries the current index times\nthe product, giving polynomial coefficients of degree one in the current\nbase power. There is no divided product or supplied index in this data path.\nThe literal recurrence is linear in interval length; a fast matrix-product\nbackend, detector batch, full bit clocks and memory remain separate work.\n-/\n\nnamespace RiemannGaussian.SemiprimeSeedLazyJets\n\nopen Polynomial SemiprimeIntervalJet SemiprimeSharedIntervalJet\nopen SemiprimeSeedSumAcquisition SemiprimeGroupSelection\nopen scoped BigOperators Matrix\n\n/-- Rich original interval channels and one auxiliary marked-product state. -/\nstructure GeometricJetState (R : Type*) where\n  /-- Original interval product. -/\n  product : R\n  /-- Original derivative in the target variable. -/\n  target : R\n  /-- Original logarithmic derivative in the geometric base. -/\n  base : R\n  /-- Current interval length times its original product. -/\n  marked : R\n\n/-- Empty-interval detector, derivatives and auxiliary state. -/\ndef initialJet {R : Type*} [CommRing R] : GeometricJetState R := ⟨1,0,0,0⟩\n\n/-- One literal scalar step. The mark is advanced by an addition rather\nthan supplied as an index or a division by the possibly zero product. -/\ndef jetStep {R : Type*} [CommRing R] (x t : R) (state : GeometricJetState R) :\n    GeometricJetState R :=\n  let f := x-t\n  ⟨f*state.product,state.product+f*state.target,\n    f*state.base-t*state.marked,f*(state.marked+state.product)⟩\n\n/-- Actual scalar state, iterated base power and native iteration counter. -/\nstructure JetRunReport (R : Type*) where\n  /-- Every original channel and the retained auxiliary mark. -/\n  state : GeometricJetState R\n  /-- Base power for the next literal step. -/\n  power : R\n  /-- Actual executed scalar steps, separate from any bit clock. -/\n  steps : ℕ\n\n/-- Execute the four-component recurrence and update the base power once\nper step. No polynomial coefficients, cofactor list or pair matrix are built. -/\ndef geometricJetRun {R : Type*} [CommRing R] (alpha x : R) : ℕ → JetRunReport R\n  | 0 => ⟨initialJet,1,0⟩\n  | n+1 =>\n    let child := geometricJetRun alpha x n\n    ⟨jetStep x child.power child.state,child.power*alpha,child.steps+1⟩\n\n/-- Literal one-factor block values, retaining its absolute exponent mark. -/\ntheorem singleton_block_jet {R : Type*} [CommRing R] (alpha x : R) (n : ℕ) :\n    blockProduct alpha x n 1=x-alpha^n ∧\n      blockTargetDerivative alpha x n 1=1 ∧\n      blockBaseDerivative alpha x n 1= -(n : R)*alpha^n := by\n  simp only [blockProduct,blockFactor,blockTargetDerivative,blockBaseDerivative,\n    blockCofactor,Finset.range_one,Finset.prod_singleton,Finset.sum_singleton,\n    Finset.erase_singleton,Finset.prod_empty,add_zero,mul_one,neg_mul,and_self]\n\n/-- The recurrence preserves the exact original rich jet, including\nsaturated or repeated roots, over every commutative coefficient ring. -/\ntheorem geometricJetRun_exact {R : Type*} [CommRing R] (alpha x : R) (L : ℕ) :\n    (geometricJetRun alpha x L).state.product=intervalProduct alpha x L ∧\n      (geometricJetRun alpha x L).state.target=targetDerivative alpha x L ∧\n      (geometricJetRun alpha x L).state.base=baseDerivative alpha x L ∧\n      (geometricJetRun alpha x L).state.marked=(L : R)*intervalProduct alpha x L ∧\n      (geometricJetRun alpha x L).power=alpha^L ∧\n      (geometricJetRun alpha x L).steps=L := by\n  induction L with\n  | zero => simp only [geometricJetRun,initialJet,intervalProduct,targetDerivative,\n      baseDerivative,Finset.range_zero,Finset.prod_empty,Finset.sum_empty,\n      Nat.cast_zero,zero_mul,pow_zero,neg_zero,and_self]\n  | succ n ih =>\n    obtain ⟨hP,hD,hE,hmark,hpow,hsteps⟩ := ih\n    obtain ⟨hblock,hblockD,hblockE⟩ := singleton_block_jet alpha x n\n    have hPnext := intervalProduct_split alpha x n 1\n    have hDnext := targetDerivative_split alpha x n 1\n    have hEnext := baseDerivative_split alpha x n 1\n    rw [hblock] at hPnext hDnext hEnext\n    rw [hblockD] at hDnext\n    rw [hblockE] at hEnext\n    dsimp only [geometricJetRun,jetStep]\n    rw [hP,hD,hE,hmark,hpow,hsteps]\n    refine ⟨?_,?_,?_,?_,?_,rfl⟩\n    · rw [hPnext]\n      ring\n    · rw [hDnext]\n      ring\n    · rw [hEnext]\n      ring\n    · rw [hPnext,Nat.cast_add,Nat.cast_one]\n      ring\n    · exact (pow_succ alpha n).symm\n\n/-- The actual recurrence exposes the original detector/target/base triple. -/\ndef JetRunReport.jet {R : Type*} (report : JetRunReport R) : R×R×R :=\n  (report.state.product,report.state.target,report.state.base)\n\n/-- The scalar recurrence's triple is exactly the original interval triple. -/\ntheorem geometricJetRun_jet {R : Type*} [CommRing R] (alpha x : R) (L : ℕ) :\n    (geometricJetRun alpha x L).jet=\n      (intervalProduct alpha x L,targetDerivative alpha x L,baseDerivative alpha x L) := by\n  obtain ⟨hP,hD,hE,_,_,_⟩ := geometricJetRun_exact alpha x L\n  exact Prod.ext hP (Prod.ext hD hE)\n\n/-- The four source components, with no scalar compression or channel sum. -/\ndef jetVector {R : Type*} (state : GeometricJetState R) : Fin 4 → R :=\n  ![state.product,state.target,state.base,state.marked]\n\n/-- Proof-side fixed four-by-four recurrence matrix, with polynomial\ncoefficients in the current base power. The scalar executor uses jetStep. -/\nnoncomputable def jetMatrix {R : Type*} [CommRing R] (x : R) :\n    Matrix (Fin 4) (Fin 4) R[X] :=\n  !![C x-X,0,0,0;\n     1,C x-X,0,0;\n     0,0,C x-X,-X;\n     C x-X,0,0,C x-X]\n\n/-- Every entry of the actual transfer specification has degree at most\none; dimension and degree do not grow with the interval length. -/\ntheorem jetMatrix_degree {R : Type*} [CommRing R] (x : R) (i j : Fin 4) :\n    (jetMatrix x i j).natDegree≤1 := by\n  have hf : (C x-X : R[X]).natDegree≤1 := by\n    exact (natDegree_sub_le (C x) X).trans\n      (max_le (by simp only [natDegree_C]; omega) natDegree_X_le)\n  fin_cases i <;> fin_cases j <;> simp [jetMatrix,hf,natDegree_X_le]\n\n/-- Evaluating the fixed degree-one matrix reproduces the literal scalar\nstep with all four original components and no inverse. -/\ntheorem jetMatrix_step {R : Type*} [CommRing R] (x t : R) (state : GeometricJetState R) :\n    Matrix.mulVec (Matrix.of (fun i j => (jetMatrix x i j).eval t)) (jetVector state)=\n      jetVector (jetStep x t state) := by\n  ext i\n  fin_cases i <;> simp [Matrix.mulVec,dotProduct,Fin.sum_univ_succ,\n    jetMatrix,jetVector,jetStep] <;> ring\n\n/-- Native detector selection stops on a proper factor or on the first\nzero canonical residue, retaining the original seed label. -/\ninductive DetectorOutcome (S : Type*) where\n  /-- A proper GCD, checked before any marked jet is requested. -/\n  | factor (divisor : ℕ)\n  /-- The original label of the first saturated detector. -/\n  | saturated (seed : S)\n\n/-- Executed native detector selection and every visited labelled residue. -/\nstructure DetectorScanReport (S : Type*) where\n  /-- First stopping outcome, if any. -/\n  outcome : Option (DetectorOutcome S)\n  /-- Exactly the detector rows inspected before stopping. -/\n  visited : List (S×ℕ)\n  /-- Actual native GCD calls, including improper results. -/\n  gcdCalls : ℕ\n\n/-- Inspect already acquired canonical detector residues. Derivative\nacquisition is absent from this native selector and remains a later call. -/\ndef selectDetector {S : Type*} (N : ℕ) : List (S×ℕ) → DetectorScanReport S\n  | [] => ⟨none,[],0⟩\n  | row::tail =>\n    match checkedSignal N row.2 with\n    | some d => ⟨some (.factor d),[row],1⟩\n    | none =>\n      if row.2=0 then ⟨some (.saturated row.1),[row],1⟩\n      else\n        let child := selectDetector N tail\n        ⟨child.outcome,row::child.visited,child.gcdCalls+1⟩\n\n/-- Every selected factor is proper on arbitrary input detector words. -/\ntheorem selectDetector_factor_sound {S : Type*} {N d : ℕ} {rows : List (S×ℕ)}\n    (h : (selectDetector N rows).outcome=some (.factor d)) : ProperDivisor N d := by\n  induction rows with\n  | nil => cases h\n  | cons row tail ih =>\n    unfold selectDetector at h\n    split at h\n    · rename_i d' hd\n      dsimp only at h\n      cases h\n      exact checkedSignal_sound hd\n    · split at h\n      · cases h\n      · exact ih h\n\n/-- A saturated outcome retains an original label with an actually\ninspected zero residue; zero is not inferred from missing factor output. -/\ntheorem selectDetector_saturated_source {S : Type*} {N : ℕ} {rows : List (S×ℕ)} {s : S}\n    (h : (selectDetector N rows).outcome=some (.saturated s)) : (s,0)∈rows := by\n  induction rows with\n  | nil => cases h\n  | cons row tail ih =>\n    unfold selectDetector at h\n    split at h\n    · cases h\n    · split at h\n      · rename_i hz\n        dsimp only at h\n        have hs := DetectorOutcome.saturated.inj (Option.some.inj h)\n        have hr : row=(s,0) := Prod.ext hs hz\n        rw [hr]\n        exact List.mem_cons_self\n      · exact List.mem_cons_of_mem _ (ih h)\n\n/-- Native selector counters count the actual inspected prefix, with one\nGCD per visit and no hidden second detector traversal. -/\ntheorem selectDetector_counts {S : Type*} (N : ℕ) (rows : List (S×ℕ)) :\n    (selectDetector N rows).gcdCalls=(selectDetector N rows).visited.length ∧\n      (selectDetector N rows).gcdCalls≤rows.length ∧\n      (selectDetector N rows).visited=rows.take (selectDetector N rows).gcdCalls := by\n  induction rows with\n  | nil => simp only [selectDetector,List.length_nil,List.take_nil,le_refl,and_self]\n  | cons row tail ih =>\n    unfold selectDetector\n    split\n    · exact ⟨rfl,by dsimp only [List.length_cons]; omega,rfl⟩\n    · split\n      · exact ⟨rfl,by dsimp only [List.length_cons]; omega,rfl⟩\n      · dsimp only [List.length_cons]\n        rw [List.take_succ_cons,← ih.2.2]\n        exact ⟨by omega,by omega,rfl⟩\n\n/-- A successful detector member forces a stopping selection, preserving\nany earlier stopping outcome. This is a universal list theorem. -/\ntheorem selectDetector_of_member {S : Type*} {N : ℕ} {rows : List (S×ℕ)}\n    {row : S×ℕ} (hrow : row∈rows) (hsuccess : checkedSignal N row.2≠none ∨ row.2=0) :\n    (selectDetector N rows).outcome≠none := by\n  induction rows with\n  | nil => cases hrow\n  | cons head tail ih =>\n    unfold selectDetector\n    cases hh : checkedSignal N head.2 with\n    | some d => simp only [ne_eq,reduceCtorEq,not_false_eq_true]\n    | none =>\n      by_cases hz : head.2=0\n      · simp only [ite_eq_left hz,ne_eq,reduceCtorEq,not_false_eq_true]\n      · rw [ite_eq_right hz]\n        rcases List.mem_cons.mp hrow with he | ht\n        · subst head\n          rcases hsuccess with hs | hs\n          · exact False.elim (hs hh)\n          · exact False.elim (hz hs)\n        · exact ih ht\n\n/-- Original derivative pair acquired by the literal four-state executor.\nThe original product is recomputed as internal state, not divided away. -/\ndef acquireSeedMarked {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (s : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)) : ZMod N×ZMod N :=\n  let report := geometricJetRun ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n    (s.step : ZMod N) (seedLength m)\n  (report.state.target,report.state.base)\n\n/-- The actual singleton derivative acquisition is the original target\nderivative and original logarithmic base derivative, including saturation. -/\ntheorem acquireSeedMarked_exact {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (s : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)) :\n    acquireSeedMarked g m s=\n      (targetDerivative ((seedBase g m : (ZMod N)ˣ) : ZMod N) (s.step : ZMod N) (seedLength m),\n        baseDerivative ((seedBase g m : (ZMod N)ˣ) : ZMod N) (s.step : ZMod N) (seedLength m)) := by\n  have hh := geometricJetRun_exact ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n    (s.step : ZMod N) (seedLength m)\n  exact Prod.ext hh.2.1 hh.2.2.1\n\n/-- A selected detector and only its actually requested marked scalars.\nThe established tag reader is still a semantic, noncomputable controller. -/\nstructure LazySeedReport (N : ℕ) where\n  /-- Original native detector selection report. -/\n  selection : DetectorScanReport (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ))\n  /-- The original selected seed and its computed marked derivative pair. -/\n  requested : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)×(ZMod N×ZMod N))\n  /-- First recovered factor, including a checked common-index sum candidate. -/\n  factor : Option ℕ\n\n/-- Feed one selected saturated seed's acquired derivatives to the existing\nrich tagged reader. Proper detector factors bypass the acquisition callback.\nThis semantic adapter does not claim a complete physical controller clock. -/\nnoncomputable def lazySeedRecoveryWith {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (acquire : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ) → ZMod N×ZMod N)\n    (rows : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)×ℕ)) : LazySeedReport N :=\n  let selection := selectDetector N rows\n  match selection.outcome with\n  | none => ⟨selection,[],none⟩\n  | some (.factor d) => ⟨selection,[],some d⟩\n  | some (.saturated s) =>\n    let marked := acquire s\n    let factor := match readSeedJet g m s (0,marked.1,marked.2) with\n      | none => none\n      | some (Sum.inl d) => some d\n      | some (Sum.inr r) => recoverSeedSum N m s r\n    ⟨selection,[(s,marked)],factor⟩\n\n/-- Use the actual literal recurrence in the at-most-once marked callback. -/\nnoncomputable def lazySeedRecovery {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (rows : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)×ℕ)) : LazySeedReport N :=\n  lazySeedRecoveryWith g m (acquireSeedMarked g m) rows\n\n/-- At most one marked pair is requested for arbitrary rows and arbitrary\nacquisition implementations; the bound follows from the actual call site. -/\ntheorem lazySeedRecoveryWith_request_bound {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (acquire : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ) → ZMod N×ZMod N)\n    (rows : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)×ℕ)) :\n    (lazySeedRecoveryWith g m acquire rows).requested.length≤1 := by\n  unfold lazySeedRecoveryWith\n  dsimp only\n  split <;> simp only [List.length_nil,List.length_cons] <;> omega\n\n/-- The actual recurrence-backed adapter requests at most one original jet\npair. It does not eagerly construct the derivative batch for all seeds. -/\ntheorem lazySeedRecovery_request_bound {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (rows : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)×ℕ)) :\n    (lazySeedRecovery g m rows).requested.length≤1 :=\n  lazySeedRecoveryWith_request_bound g m _ rows\n\n/-- The literal original detector rows retain every seed label. Their\nacquisition is deliberately separate from the singleton marked callback. -/\ndef originalDetectorRows {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (xs : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ))) :\n    List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)×ℕ) :=\n  xs.map (fun s => (s,(intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n    (s.step : ZMod N) (seedLength m)).val))\n\n/-- The literal detector batch has exactly the original number of labels. -/\ntheorem originalDetectorRows_length {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (xs : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ))) :\n    (originalDetectorRows g m xs).length=xs.length := by\n  simp only [originalDetectorRows,List.length_map]\n\n/-- Proper detector checks return the same factor tag before either\noriginal derivative is inspected by the established seed reader. -/\ntheorem readSeed_of_detector_factor {N m d : ℕ} (g : (ZMod N)ˣ)\n    (s : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ))\n    (h : checkedSignal N (intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n      (s.step : ZMod N) (seedLength m)).val=some d) : readSeed g m s=some (Sum.inl d) := by\n  unfold checkedSignal at h\n  split at h\n  · rename_i hp\n    cases h\n    unfold readSeed SemiprimeWrapIndexRecovery.recoverTaggedInterval\n      SemiprimeWrapIndexRecovery.recoverTaggedJet\n    dsimp only\n    rw [ite_eq_left hp]\n  · cases h\n\n/-- A clear nonzero detector makes the established reader return none,\nindependently of any marked-derivative acquisition. -/\ntheorem readSeed_of_clear_nonzero {N m : ℕ} (g : (ZMod N)ˣ)\n    (s : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ))\n    (hclear : checkedSignal N (intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n      (s.step : ZMod N) (seedLength m)).val=none)\n    (hzero : intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n      (s.step : ZMod N) (seedLength m)≠0) : readSeed g m s=none := by\n  have hn : ¬(1<N.gcd (intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n      (s.step : ZMod N) (seedLength m)).val ∧\n      N.gcd (intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n        (s.step : ZMod N) (seedLength m)).val<N) := by\n    intro hp\n    rw [checkedSignal,ite_eq_left hp] at hclear\n    cases hclear\n  unfold readSeed SemiprimeWrapIndexRecovery.recoverTaggedInterval\n    SemiprimeWrapIndexRecovery.recoverTaggedJet\n  dsimp only\n  rw [ite_eq_right hn,ite_eq_right hzero]\n\n/-- Exact acquired original derivatives restore the original saturated\nseed reader. No divided half-product or unit ratio is used. -/\ntheorem readSeedJet_saturated_exact {N m : ℕ} (g : (ZMod N)ˣ)\n    (s : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ))\n    (marked : ZMod N×ZMod N)\n    (hmarked : marked=\n      (targetDerivative ((seedBase g m : (ZMod N)ˣ) : ZMod N) (s.step : ZMod N) (seedLength m),\n        baseDerivative ((seedBase g m : (ZMod N)ˣ) : ZMod N) (s.step : ZMod N) (seedLength m)))\n    (hzero : intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n      (s.step : ZMod N) (seedLength m)=0) :\n    readSeedJet g m s (0,marked.1,marked.2)=readSeed g m s := by\n  rw [hmarked,← hzero]\n  rfl\n\n/-- For exact original detector rows, exact marked derivatives and a\nsuccessful original saturated reader, the lazy adapter is exactly the\nestablished first-success seed scan. The saturation premise is discharged\nfrom original local period data in the long-route theorem below. -/\ntheorem lazySeedRecoveryWith_exact {N : ℕ} (hN : 0<N) (g : (ZMod N)ˣ) (m : ℕ)\n    (acquire : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ) → ZMod N×ZMod N)\n    (xs : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)))\n    (hmarked : ∀ s∈xs, acquire s=\n      (targetDerivative ((seedBase g m : (ZMod N)ˣ) : ZMod N) (s.step : ZMod N) (seedLength m),\n        baseDerivative ((seedBase g m : (ZMod N)ˣ) : ZMod N) (s.step : ZMod N) (seedLength m)))\n    (hsaturated : ∀ s∈xs, intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n      (s.step : ZMod N) (seedLength m)=0 → readSeed g m s≠none) :\n    (lazySeedRecoveryWith g m acquire (originalDetectorRows g m xs)).factor=scanSeedSums g m xs := by\n  let : NeZero N := ⟨hN.ne'⟩\n  induction xs with\n  | nil => rfl\n  | cons s tail ih =>\n    have ht := ih (fun t ht => hmarked t (List.mem_cons_of_mem _ ht))\n      (fun t ht => hsaturated t (List.mem_cons_of_mem _ ht))\n    have hPiff : (intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n        (s.step : ZMod N) (seedLength m)).val=0 ↔\n        intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n          (s.step : ZMod N) (seedLength m)=0 := ZMod.val_eq_zero _\n    cases hc : checkedSignal N (intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n      (s.step : ZMod N) (seedLength m)).val with\n    | some d =>\n      have hr := readSeed_of_detector_factor g s hc\n      simp only [lazySeedRecoveryWith,originalDetectorRows,List.map_cons,selectDetector,hc,\n        scanSeedSums,hr]\n    | none =>\n      by_cases hz : intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n        (s.step : ZMod N) (seedLength m)=0\n      · have hv := hPiff.mpr hz\n        have hr := readSeedJet_saturated_exact g s (acquire s) (hmarked s List.mem_cons_self) hz\n        have hread := hsaturated s List.mem_cons_self hz\n        cases ho : readSeed g m s with\n        | none => exact False.elim (hread ho)\n        | some outcome =>\n          cases outcome <;> simp only [lazySeedRecoveryWith,originalDetectorRows,List.map_cons,\n            selectDetector,hc,ite_eq_left hv,hr,ho,scanSeedSums]\n      · have hv : ¬(intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n          (s.step : ZMod N) (seedLength m)).val=0 := by\n          intro hh\n          exact hz (hPiff.mp hh)\n        have hr := readSeed_of_clear_nonzero g s hc hz\n        simp only [lazySeedRecoveryWith,originalDetectorRows,List.map_cons,selectDetector,hc,\n          ite_eq_right hv,scanSeedSums,hr] at ht ⊢\n        cases ho : (selectDetector N (tail.map (fun s =>\n          (s,(intervalProduct ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n            (s.step : ZMod N) (seedLength m)).val)))).outcome with\n        | none => simpa only [ho] using ht\n        | some outcome => cases outcome <;> simpa only [ho] using ht\n\n/-- On the original long route the exact literal marked callback preserves\nthe complete original scan, for every original supplied seed list. -/\ntheorem long_lazySeedRecovery_exact {p q m : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p<q) (hm : 4≤m)\n    (g : (ZMod (p*q))ˣ) (hlong : SemiprimeLocalOrderRouting.LongData g m)\n    (xs : List (SemiprimeDenseRowCarries.ProgressionSeed ((ZMod (p*q))ˣ))) :\n    (lazySeedRecovery (SemiprimeCentreFreeCover.projectedUnit g m) m\n      (originalDetectorRows (SemiprimeCentreFreeCover.projectedUnit g m) m xs)).factor=\n      scanSeedSums (SemiprimeCentreFreeCover.projectedUnit g m) m xs := by\n  apply lazySeedRecoveryWith_exact (Nat.mul_pos hp.pos hq.pos)\n  · intro s _\n    exact acquireSeedMarked_exact _ _ s\n  · intro s _ hz\n    exact SemiprimeBitInverse.long_readSeed_saturated hp hq hpq hm g hlong s hz\n\n/-- Ordered evaluated product of the fixed four-state transfer matrices.\nThis proof-side specification preserves multiplication order and is not\na claim that a fast polynomial backend has been implemented. -/\nnoncomputable def matrixJetRun {R : Type*} [CommRing R] (alpha x : R) :\n    ℕ → Matrix (Fin 4) (Fin 4) R\n  | 0 => 1\n  | n+1 => Matrix.of (fun i j => (jetMatrix x i j).eval (alpha^n))*matrixJetRun alpha x n\n\n/-- The complete ordered matrix product is exactly the actual scalar\nrecurrence on its rich initial state, without a determinant or channel loss. -/\ntheorem matrixJetRun_state {R : Type*} [CommRing R] (alpha x : R) (L : ℕ) :\n    (matrixJetRun alpha x L).mulVec (jetVector (initialJet : GeometricJetState R))=\n      jetVector (geometricJetRun alpha x L).state := by\n  induction L with\n  | zero => simp only [matrixJetRun,Matrix.one_mulVec,geometricJetRun]\n  | succ n ih =>\n    rw [matrixJetRun,← Matrix.mulVec_mulVec,ih,jetMatrix_step]\n    rw [geometricJetRun]\n    dsimp only\n    rw [(geometricJetRun_exact alpha x n).2.2.2.2.1]\n\n/-- Every original detector and derivative is an explicit component of\nthe fixed-degree transfer product, even at a saturated target. -/\ntheorem matrixJetRun_channels {R : Type*} [CommRing R] (alpha x : R) (L : ℕ) :\n    (matrixJetRun alpha x L).mulVec (jetVector (initialJet : GeometricJetState R))=\n      ![intervalProduct alpha x L,targetDerivative alpha x L,baseDerivative alpha x L,\n        (L : R)*intervalProduct alpha x L] := by\n  rw [matrixJetRun_state]\n  obtain ⟨hP,hD,hE,hmarked,_,_⟩ := geometricJetRun_exact alpha x L\n  simp only [jetVector,hP,hD,hE,hmarked]\n\n/-- The actual literal marked acquisition has quadratic interval length,\nnot the square-root cost of a still-unimplemented fast transfer backend. -/\ntheorem literal_seed_marked_steps {N m : ℕ} (g : (ZMod N)ˣ)\n    (s : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)) (hm : 4≤m) :\n    2*m^2+2≤(geometricJetRun ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n      (s.step : ZMod N) (seedLength m)).steps ∧\n      (geometricJetRun ((seedBase g m : (ZMod N)ˣ) : ZMod N)\n        (s.step : ZMod N) (seedLength m)).steps≤4*m^2 := by\n  rw [(geometricJetRun_exact _ _ _).2.2.2.2.2]\n  exact seedLength_bounds hm\n\n/-- At the actual matched public width the implemented literal marked\nrecurrence is quadratic in sixthWidth whenever its callback is requested.\nThe fixed-degree transfer structure is available for a faster backend. -/\ntheorem public_literal_seed_marked_steps {N : ℕ} (hN : 0<N)\n    (hB : 4≤SemiprimeLehmanCoverage.sixthWidth N) (g : (ZMod N)ˣ)\n    (s : SemiprimeDenseRowCarries.ProgressionSeed ((ZMod N)ˣ)) :\n    2*(SemiprimeLehmanCoverage.sixthWidth N)^2+2≤\n      (geometricJetRun\n        ((seedBase g (SemiprimeEuclidRowBudget.publicRowModulus N) : (ZMod N)ˣ) : ZMod N)\n        (s.step : ZMod N)\n        (seedLength (SemiprimeEuclidRowBudget.publicRowModulus N))).steps ∧\n      (geometricJetRun\n        ((seedBase g (SemiprimeEuclidRowBudget.publicRowModulus N) : (ZMod N)ˣ) : ZMod N)\n        (s.step : ZMod N)\n        (seedLength (SemiprimeEuclidRowBudget.publicRowModulus N))).steps≤\n          16*(SemiprimeLehmanCoverage.sixthWidth N)^2 := by\n  have hm := SemiprimeEuclidRowBudget.publicRowModulus_bounds hN\n  have hh := literal_seed_marked_steps g s (hB.trans hm.1)\n  have hlo := Nat.pow_le_pow_left hm.1 2\n  have hhi := Nat.pow_le_pow_left hm.2 2\n  constructor <;> nlinarith [hh.1,hh.2]\n\n/-- The lazy controller on the original long route succeeds on every\nremaining distinct-prime ratio, with at most one marked acquisition request.\nThe detector source and literal/faster marked costs remain separate. -/\ntheorem long_lazySeedRecovery_complete {p q m : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p<q) (hm : 4≤m) (hmprime : m.Prime)\n    (hprefix : m^2≤p) (hN : m.Coprime (p*q)) (hsize : p*q≤m^6)\n    (g : (ZMod (p*q))ˣ) (hlong : SemiprimeLocalOrderRouting.LongData g m) :\n    let h := SemiprimeCentreFreeCover.projectedUnit g m\n    let xs := SemiprimeDenseRowCarries.progressionSeeds h (p*q) m\n    let out := lazySeedRecovery h m (originalDetectorRows h m xs)\n    (∃ d, out.factor=some d ∧ ProperDivisor (p*q) d) ∧\n      out.requested.length≤1 ∧ out.selection.gcdCalls≤m-1 := by\n  dsimp only\n  obtain ⟨d,hd⟩ := scanSeedSums_complete hp hq hpq hm hmprime hprefix hN hsize g hlong\n  have he := long_lazySeedRecovery_exact hp hq hpq hm g hlong\n    (SemiprimeDenseRowCarries.progressionSeeds\n      (SemiprimeCentreFreeCover.projectedUnit g m) (p*q) m)\n  refine ⟨⟨d,he.trans hd,scanSeedSums_sound _ _ hd⟩,lazySeedRecovery_request_bound _ _ _,?_⟩\n  have hc := (selectDetector_counts (p*q) (originalDetectorRows\n    (SemiprimeCentreFreeCover.projectedUnit g m) m\n    (SemiprimeDenseRowCarries.progressionSeeds\n      (SemiprimeCentreFreeCover.projectedUnit g m) (p*q) m))).2.1\n  rw [originalDetectorRows_length,SemiprimeDenseRowCarries.progressionSeeds_length] at hc\n  unfold lazySeedRecovery lazySeedRecoveryWith\n  dsimp only\n  split <;> exact hc\n\n/-- The actual matched-width public long route after an unsuccessful\noriginal prefix has a successful lazy semantic adapter, at most one marked\nrequest and a linear number of actual native detector GCD calls. Neither\nthe original detector source nor the full recovery bit clock is priced here. -/\ntheorem actual_public_route_lazy_acquisition {p q a : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p<q)\n    (hB : 4≤SemiprimeLehmanCoverage.sixthWidth (p*q))\n    (hnone : SemiprimeStrassenPrefix.factorPrefix (p*q)\n      (SemiprimeEuclidRowBudget.publicRowModulus (p*q))=none)\n    (hroute : SemiprimeWrapIndexRecovery.routeAtRowModulus (p*q)=.longBase a) :\n    ∃ hc : a.Coprime (p*q),\n      let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n      let h := SemiprimeCentreFreeCover.projectedUnit (ZMod.unitOfCoprime a hc) m\n      let xs := SemiprimeDenseRowCarries.progressionSeeds h (p*q) m\n      let out := lazySeedRecovery h m (originalDetectorRows h m xs)\n      (∃ d, out.factor=some d ∧ ProperDivisor (p*q) d) ∧\n        out.requested.length≤1 ∧ out.selection.gcdCalls≤m-1 ∧\n          out.selection.gcdCalls≤2*SemiprimeLehmanCoverage.sixthWidth (p*q) := by\n  have hd := SemiprimeWrapIndexRecovery.routeAtRowModulus_semiprime hp hq hpq hB\n  rw [hroute] at hd\n  obtain ⟨hc,hlong⟩ := hd\n  let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n  let g := ZMod.unitOfCoprime a hc\n  have hN := Nat.mul_pos hp.pos hq.pos\n  have hmBounds := SemiprimeEuclidRowBudget.publicRowModulus_bounds hN\n  have hm : 4≤m := hB.trans hmBounds.1\n  have hbudget : p*q≤m^6 := (SemiprimeLehmanCoverage.sixthWidth_upper (p*q)).trans\n    (Nat.pow_le_pow_left hmBounds.1 6)\n  have hcover : m^2<p*q := SemiprimeWideWrapCoverage.public_modulus_prefix_below_input hN hB\n  have hprefix := SemiprimeStrassenPrefix.prefix_none_excludes_small_prime\n    hcover hp (dvd_mul_right p q) hnone\n  have hmprime : m.Prime := SemiprimeEuclidRowBudget.publicRowModulus_prime (p*q)\n  have hcop := SemiprimeStrassenPrefix.prefix_none_coprime_integer hcover hnone hmprime.pos\n    (by have hh := hmprime.two_le; nlinarith only [hh] : m≤m^2)\n  obtain ⟨hfactor,hrequest,hgcd⟩ := long_lazySeedRecovery_complete hp hq hpq hm hmprime\n    hprefix.le hcop.symm hbudget g hlong\n  refine ⟨hc,hfactor,hrequest,hgcd,hgcd.trans ?_⟩\n  exact (Nat.sub_le m 1).trans hmBounds.2\n\nend RiemannGaussian.SemiprimeSeedLazyJets\n","RiemannGaussian.SemiprimeSignedMomentAcquisitionObstruction":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSeedEnergyAcquisitionObstruction\nimport Mathlib.RingTheory.Polynomial.Cyclotomic.Basic\n\n\n/-!\n# Signed common-point filters retain the original arithmetic energy obstruction\n\nA nonzero polynomial filter in an injective common character can remove\nat most its degree many original grid poles. Exact signed label grouping\nretains each surviving positive multiplicity. The literal original carry\nenergy therefore bounds the denominator degree plus the filter degree.\n\nThe investigation journal combines this finite source theorem with the\npreserved actual infinite family. Its dense signed-carrier acquisition\nobstruction holds simultaneously for all widths and full-input adaptive\nfilters. Separate shared column masks can telescope to small endpoint\ncarriers; cyclotomic column factors add no new low-index moment gcd signal.\nArbitrary independent signed masks, smaller internal pivots, implicit\nrepresentations and the full factorization bit bound remain outside scope.\n-/\n\nnamespace RiemannGaussian.SemiprimeSignedMomentAcquisitionObstruction\n\nopen scoped BigOperators\nopen Polynomial RiemannGaussian.SemiprimeSeedMomentPoleRetention\n\n/-- A nonzero common-point filter deletes at most its degree many poles\nafter any injective change of the points used to evaluate the filter. -/\ntheorem injective_filter_denominator_degree {K : Type*} [Field K]\n    (S : Finset K) (mu phi : K → K) (hx : ∀ x ∈ S, x ≠ 0)\n    (hmu : ∀ x ∈ S, mu x ≠ 0) (hphi : Set.InjOn phi S)\n    (W U V : K[X]) (hW : W ≠ 0) (hU : U.coeff 0 = 1)\n    (hUV : (U : PowerSeries K) *\n      (∑ x ∈ S, PowerSeries.C (mu x * W.eval (phi x)) * positiveMoments x) =\n      (V : PowerSeries K)) :\n    S.card ≤ U.natDegree + W.natDegree := by\n  classical\n  let T := S.filter fun x => W.eval (phi x) ≠ 0\n  let Z := S.filter fun x => W.eval (phi x) = 0\n  have hsum : (∑ x ∈ T, PowerSeries.C (mu x * W.eval (phi x)) * positiveMoments x) =\n      (∑ x ∈ S, PowerSeries.C (mu x * W.eval (phi x)) * positiveMoments x) := by\n    apply Finset.sum_subset (Finset.filter_subset _ _)\n    intro x hxS hxT\n    have hz : W.eval (phi x) = 0 := by\n      by_contra hne\n      exact hxT (Finset.mem_filter.mpr ⟨hxS, hne⟩)\n    simp only [hz, mul_zero, map_zero, zero_mul]\n  have hT : T.card ≤ U.natDegree := by\n    apply weighted_denominator_degree T (fun x => mu x * W.eval (phi x))\n      (fun x hxT => hx x (Finset.mem_filter.mp hxT).1)\n      (fun x hxT => mul_ne_zero (hmu x (Finset.mem_filter.mp hxT).1)\n        (Finset.mem_filter.mp hxT).2) U V hU\n    rw [hsum]\n    exact hUV\n  have hinj : Set.InjOn phi Z := fun x hxZ y hyZ h =>\n    hphi (Finset.mem_filter.mp hxZ).1 (Finset.mem_filter.mp hyZ).1 h\n  have hZ : Z.card ≤ W.natDegree := by\n    rw [←Finset.card_image_of_injOn hinj]\n    apply Polynomial.card_le_degree_of_subset_roots\n    intro y hy\n    obtain ⟨x, hxZ, rfl⟩ := Finset.mem_image.mp hy\n    exact (Polynomial.mem_roots hW).mpr (Finset.mem_filter.mp hxZ).2\n  have hcard : S.card = T.card + Z.card := by\n    dsimp only [T, Z]\n    simpa only [not_not] using\n      (Finset.card_filter_add_card_filter_not (s := S)\n        (p := fun x => W.eval (phi x) ≠ 0)).symm\n  rw [hcard]\n  exact Nat.add_le_add hT hZ\n\n/-- Exact weights depending only on the point may be pulled through\nlabel grouping; all original positive multiplicities are preserved. -/\ntheorem weighted_labelled_moments_group {R ι : Type*} [CommRing R] [DecidableEq R]\n    (I : Finset ι) (x : ι → R) (weight : R → R) :\n    (∑ i ∈ I, PowerSeries.C (weight (x i)) * positiveMoments (x i)) =\n      ∑ y ∈ I.image x, PowerSeries.C\n        ((((I.filter fun i => x i = y).card : ℕ) : R) * weight y) * positiveMoments y := by\n  classical\n  rw [←Finset.sum_fiberwise_of_maps_to\n    (fun i hi => Finset.mem_image_of_mem x hi)\n    (fun i => PowerSeries.C (weight (x i)) * positiveMoments (x i))]\n  apply Finset.sum_congr rfl\n  intro y _\n  rw [Finset.sum_congr rfl (fun i hi =>\n    congrArg (fun a => PowerSeries.C (weight a) * positiveMoments a)\n      (Finset.mem_filter.mp hi).2)]\n  ext r\n  simp only [Finset.sum_const, nsmul_eq_mul, map_mul]\n  simp [mul_assoc]\n\n/-- Signed filtering of a labelled prime-field family retains all but\nthe filter degree of its distinct poles. Only individual positive fibres\nmust lie below the characteristic. -/\ntheorem labelled_injective_filter_denominator_degree {p : ℕ} {ι : Type*}\n    (hp : p.Prime) (I : Finset ι) (x : ι → ZMod p) (phi : ZMod p → ZMod p)\n    (hfiber : ∀ y ∈ I.image x, (I.filter fun i => x i = y).card < p)\n    (hx : ∀ i ∈ I, x i ≠ 0) (hphi : Set.InjOn phi (I.image x))\n    (W U V : (ZMod p)[X]) (hW : W ≠ 0) (hU : U.coeff 0 = 1)\n    (hUV : (U : PowerSeries (ZMod p)) *\n      (∑ i ∈ I, PowerSeries.C (W.eval (phi (x i))) * positiveMoments (x i)) =\n      (V : PowerSeries (ZMod p))) :\n    (I.image x).card ≤ U.natDegree + W.natDegree := by\n  classical\n  let : Fact p.Prime := ⟨hp⟩\n  rw [weighted_labelled_moments_group I x (fun y => W.eval (phi y))] at hUV\n  apply injective_filter_denominator_degree (I.image x)\n    (fun y => (((I.filter fun i => x i = y).card : ℕ) : ZMod p)) phi\n    (by\n      intro y hy\n      obtain ⟨i, hi, rfl⟩ := Finset.mem_image.mp hy\n      exact hx i hi)\n    (by\n      intro y hy\n      obtain ⟨i, hi, he⟩ := Finset.mem_image.mp hy\n      have hpos : 0 < (I.filter fun j => x j = y).card :=\n        Finset.card_pos.mpr ⟨i, Finset.mem_filter.mpr ⟨hi, he⟩⟩\n      exact fun hz => Nat.not_dvd_of_pos_of_lt hpos\n        (hfiber y (Finset.mem_image.mpr ⟨i, hi, he⟩))\n        ((ZMod.natCast_eq_zero_iff _ _).mp hz))\n    hphi W U V hW hU hUV\n\n/-- The original kind of geometric row grid needs only M<p, because\neach row contributes at most once to a local point. The filter may have\narbitrary signed coefficients. -/\ntheorem geometric_grid_filtered_denominator_degree {p M J : ℕ}\n    (hp : p.Prime) (x : Fin M → (ZMod p)ˣ) (beta : (ZMod p)ˣ)\n    (hJ : J ≤ orderOf beta) (hM : M < p) (phi : ZMod p → ZMod p)\n    (hphi : Set.InjOn phi\n      ((Finset.univ : Finset (Fin M × Fin J)).image\n        fun ik => (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p)))\n    (W U V : (ZMod p)[X]) (hW : W ≠ 0) (hU : U.coeff 0 = 1)\n    (hUV : (U : PowerSeries (ZMod p)) *\n      (∑ ik : Fin M × Fin J, PowerSeries.C\n        (W.eval (phi (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p))) *\n        positiveMoments ((((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p))) =\n      (V : PowerSeries (ZMod p))) :\n    ((Finset.univ : Finset (Fin M × Fin J)).image\n      fun ik => (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p)).card ≤\n        U.natDegree + W.natDegree := by\n  classical\n  let : Fact p.Prime := ⟨hp⟩\n  apply labelled_injective_filter_denominator_degree hp Finset.univ\n    (fun ik : Fin M × Fin J => (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p)) phi\n    (by\n      intro y _\n      have hcap := Finset.card_le_card_of_injOn\n        (s := ((Finset.univ : Finset (Fin M × Fin J)).filter\n          fun ik => (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p) = y))\n        (t := (Finset.univ : Finset (Fin M))) (fun ik => ik.1)\n        (fun _ _ => Finset.mem_univ _)\n        (by\n          intro a ha b hb he\n          have hpoint : x a.1 * beta ^ a.2.val = x b.1 * beta ^ b.2.val :=\n            Units.ext ((Finset.mem_filter.mp ha).2.trans (Finset.mem_filter.mp hb).2.symm)\n          have hpow : beta ^ a.2.val = beta ^ b.2.val := by\n            apply mul_left_cancel (a := x b.1)\n            simpa only [he] using hpoint\n          have hk : a.2 = b.2 := Fin.ext\n            (pow_injOn_Iio_orderOf (a.2.is_lt.trans_le hJ) (b.2.is_lt.trans_le hJ) hpow)\n          exact Prod.ext he hk)\n      have hc : ((Finset.univ : Finset (Fin M × Fin J)).filter\n          fun ik => (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p) = y).card ≤ M := by\n        simpa only [Finset.card_univ, Fintype.card_fin] using hcap\n      exact hc.trans_lt hM)\n    (fun ik _ => (x ik.1 * beta ^ ik.2.val).isUnit.ne_zero)\n    hphi W U V hW hU hUV\n\nopen scoped Pointwise Combinatorics.Additive\nopen RiemannGaussian.SemiprimeSeedEnergyAcquisitionObstruction\nopen RiemannGaussian.SemiprimeGlobalPhaseCancellation\nopen RiemannGaussian.SemiprimeDenseRowCarries\n\n/-- Coprime powering is injective on a family with a common finite period. -/\ntheorem power_injective_on_periodic_points {K : Type*} [CommMonoid K]\n    (S : Set K) {R e : ℕ} (hR : 0 < R) (hcop : e.Coprime R)\n    (hperiod : ∀ x ∈ S, x ^ R = 1) : Set.InjOn (fun x : K => x ^ e) S := by\n  by_cases hRone : R = 1\n  · intro x hx y hy _\n    simpa only [hRone, pow_one] using (hperiod x hx).trans (hperiod y hy).symm\n  have hRtwo : 1 < R := by omega\n  obtain ⟨k, _, hk⟩ := Nat.exists_mul_mod_eq_one_of_coprime hcop hRtwo\n  have hrecover : ∀ x ∈ S, (x ^ e) ^ k = x := by\n    intro x hx\n    rw [←pow_mul, ←Nat.mod_add_div (e * k) R, pow_add, pow_mul,\n      hperiod x hx, one_pow, mul_one, hk, pow_one]\n  intro x hx y hy hxy\n  have heq := congrArg (fun t : K => t ^ k) hxy\n  rw [hrecover x hx, hrecover y hy] at heq\n  exact heq\n\n/-- Evaluation of a polynomial divisor of a unit-valued polynomial is a unit.\nThis includes cyclotomic or binomial column masks once their gate is proved. -/\ntheorem polynomial_divisor_eval_isUnit {R : Type*} [CommRing R]\n    (P Q : R[X]) (v : R) (hdiv : P ∣ Q) (hQ : IsUnit (Q.eval v)) :\n    IsUnit (P.eval v) := by\n  obtain ⟨A, hA⟩ := hdiv\n  rw [hA, eval_mul] at hQ\n  exact isUnit_of_mul_isUnit_left hQ\n\n/-- A prime period cannot divide a product of two positive smaller indices. -/\ntheorem prime_order_binomial_ne_zero {K : Type*} [Field K]\n    (beta : Kˣ) (hR : (orderOf beta).Prime) {r d : ℕ}\n    (hr : 0 < r) (hrR : r < orderOf beta)\n    (hd : 0 < d) (hdR : d < orderOf beta) :\n    (((beta : K) ^ r) ^ d - 1) ≠ 0 := by\n  intro he\n  have hp : beta ^ (r * d) = 1 := by\n    apply Units.ext\n    simpa only [Units.val_pow_eq_pow_val, Units.val_one, pow_mul] using\n      (sub_eq_zero.mp he)\n  have hdiv := (orderOf_dvd_iff_pow_eq_one).mpr hp\n  rcases hR.dvd_mul.mp hdiv with h | h\n  · exact Nat.not_dvd_of_pos_of_lt hr hrR h\n  · exact Nat.not_dvd_of_pos_of_lt hd hdR h\n\n/-- A signed common-point filtered grid keeps the source-energy tradeoff,\nwith the exact denominator degree plus the filter's root budget. -/\ntheorem geometric_filtered_source_energy_tradeoff {p M J : ℕ}\n    (hp : p.Prime) (x : Fin M → (ZMod p)ˣ) (beta : (ZMod p)ˣ)\n    (hsource : ∀ y ∈ Finset.univ.image x,\n      ((Finset.univ : Finset (Fin M)).filter fun i => x i = y).card ≤ 2)\n    (hJ : J ≤ orderOf beta) (hJpos : 0 < J) (hM : M < p)\n    (w L : ℕ) (hcover : L ≤ w * J) (phi : ZMod p → ZMod p)\n    (hphi : Set.InjOn phi\n      ((Finset.univ : Finset (Fin M × Fin J)).image\n        fun ik => (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p)))\n    (W H K : (ZMod p)[X]) (hW : W ≠ 0) (hH : H.coeff 0 = 1)\n    (hHK : (H : PowerSeries (ZMod p)) *\n      (∑ ik : Fin M × Fin J, PowerSeries.C\n        (W.eval (phi (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p))) *\n        positiveMoments ((((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p))) =\n      (K : PowerSeries (ZMod p))) :\n    M ^ 4 * L ≤ 16 * w * (H.natDegree + W.natDegree) ^ 2 *\n      labelledEnergy Finset.univ x := by\n  classical\n  let : NeZero p := ⟨hp.ne_zero⟩\n  let A := Finset.univ.image x\n  let B := Finset.univ.image fun k : Fin J => beta ^ k.val\n  have hB : B.card = J := by\n    rw [Finset.card_image_of_injective]\n    · exact Fintype.card_fin J\n    · intro k l he\n      apply Fin.ext\n      exact pow_injOn_Iio_orderOf (k.is_lt.trans_le hJ) (l.is_lt.trans_le hJ) he\n  have hrows : M ≤ 2 * A.card := by\n    have h := card_le_fiber_bound_mul_image Finset.univ x 2 hsource\n    simpa only [Finset.card_univ, Fintype.card_fin] using h\n  have hdeg : (A * B).card ≤ H.natDegree + W.natDegree := by\n    rw [geometric_grid_support_card_eq]\n    exact geometric_grid_filtered_denominator_degree hp x beta hJ hM phi hphi\n      W H K hW hH hHK\n  have he := product_support_tradeoff A B (by rw [hB]; exact hJpos)\n    w L (H.natDegree + W.natDegree) (labelledEnergy Finset.univ x)\n    (by rw [hB]; exact hcover) hdeg (image_self_energy_le_labelled Finset.univ x)\n  calc\n    _ ≤ (2 * A.card) ^ 4 * L := Nat.mul_le_mul_right L (Nat.pow_le_pow_left hrows 4)\n    _ = 16 * (A.card ^ 4 * L) := by ring\n    _ ≤ 16 * (w * (H.natDegree + W.natDegree) ^ 2 * labelledEnergy Finset.univ x) :=\n      Nat.mul_le_mul_left _ he\n    _ = _ := by ring\n\n/-- Literal original row offsets retain the all-width energy obstruction\nthrough signed common-point filtering. Infinitude and bit cost are separate. -/\ntheorem literal_original_filtered_energy_tradeoff {p N m J : ℕ}\n    (hp : p.Prime) (hm : m.Prime) (hN : m.Coprime N)\n    (gamma beta : (ZMod p)ˣ) (horder : 8 * m ^ 2 < orderOf gamma)\n    (hJ : J ≤ orderOf beta) (hJpos : 0 < J) (hM : m - 1 < p)\n    (w L : ℕ) (hcover : L ≤ w * J) (phi : ZMod p → ZMod p)\n    (hphi : Set.InjOn phi\n      ((Finset.univ : Finset (Fin (m-1) × Fin J)).image fun ik =>\n        (((progressionSeed gamma N m (ik.1.val+1)).step *\n          beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p)))\n    (W H K : (ZMod p)[X]) (hW : W ≠ 0) (hH : H.coeff 0 = 1)\n    (hHK : (H : PowerSeries (ZMod p)) *\n      (∑ ik : Fin (m-1) × Fin J, PowerSeries.C\n        (W.eval (phi (((progressionSeed gamma N m (ik.1.val+1)).step *\n          beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p))) *\n        positiveMoments (((progressionSeed gamma N m (ik.1.val+1)).step *\n          beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p)) = (K : PowerSeries (ZMod p))) :\n    (m-1) ^ 4 * L ≤ 16 * w * (H.natDegree + W.natDegree) ^ 2 *\n      (nontrivialOffsetEnergy N m + 2 * (m-1) ^ 2) := by\n  classical\n  let x := fun i : Fin (m-1) => (progressionSeed gamma N m (i.val+1)).step\n  have hsource : ∀ y ∈ Finset.univ.image x,\n      ((Finset.univ : Finset (Fin (m-1))).filter fun i => x i = y).card ≤ 2 := by\n    intro y _\n    exact original_seed_fiber_card_le_two gamma hm hN horder y\n  have he := geometric_filtered_source_energy_tradeoff hp x beta hsource\n    hJ hJpos hM w L hcover phi hphi W H K hW hH hHK\n  rw [labelled_original_seed_energy_eq_offset gamma hm horder] at he\n  exact he.trans (Nat.mul_le_mul_left _ (offsetEnergy_le_nontrivial_add N m))\n\n/-- The weighted centered series has the literal signed power-sum coefficients. -/\ntheorem weighted_positive_moments_coeff {R ι : Type*} [CommRing R]\n    (I : Finset ι) (x weight : ι → R) {r : ℕ} (hr : 0 < r) :\n    PowerSeries.coeff r (∑ i ∈ I, PowerSeries.C (weight i) * positiveMoments (x i)) =\n      ∑ i ∈ I, weight i * (x i) ^ r := by\n  simp only [map_sum, PowerSeries.coeff_C_mul, positiveMoments, PowerSeries.coeff_mk,\n    ite_eq_right (Nat.ne_of_gt hr)]\n\n/-- Finite signed moment-index shifts are common-character point filters,\nwith every original label retained in the exact sum. -/\ntheorem signed_moment_shift_identity {R ι : Type*} [CommRing R]\n    (I : Finset ι) (x : ι → R) (W : R[X]) (r e : ℕ) :\n    (∑ a ∈ Finset.range (W.natDegree + 1), W.coeff a *\n      (∑ i ∈ I, (x i) ^ (r + e * a))) =\n      ∑ i ∈ I, W.eval ((x i) ^ e) * (x i) ^ r := by\n  simp_rw [Finset.mul_sum]\n  rw [Finset.sum_comm]\n  apply Finset.sum_congr rfl\n  intro i _\n  rw [Polynomial.eval_eq_sum_range, Finset.sum_mul]\n  apply Finset.sum_congr rfl\n  intro a _\n  rw [pow_add, pow_mul]\n  ring\n\n/-- Shared signed column masks separate from the genuine original seed moment. -/\ntheorem signed_column_moment_factor {R ι : Type*} [CommRing R]\n    (I : Finset ι) (B : Finset ℕ) (x : ι → R) (beta : R) (weight : ℕ → R) (r : ℕ) :\n    (∑ j ∈ I, ∑ h ∈ B, weight h * (x j * beta ^ h) ^ r) =\n      (∑ j ∈ I, (x j) ^ r) * (∑ h ∈ B, weight h * (beta ^ r) ^ h) := by\n  rw [Finset.sum_mul]\n  apply Finset.sum_congr rfl\n  intro j _\n  rw [Finset.mul_sum]\n  apply Finset.sum_congr rfl\n  intro h _\n  rw [mul_pow, pow_right_comm beta h r]\n  ring\n\n/-- Cyclotomic column factors are units below a local prime period; changing\nsuch a mask adds no zero to an already acquired original seed moment. -/\ntheorem prime_order_cyclotomic_eval_isUnit {K : Type*} [Field K] (beta : Kˣ)\n    (hR : (orderOf beta).Prime) {r d : ℕ}\n    (hr : 0 < r) (hrR : r < orderOf beta) (hd : 0 < d) (hdR : d < orderOf beta) :\n    IsUnit ((cyclotomic d K).eval ((beta : K) ^ r)) := by\n  apply polynomial_divisor_eval_isUnit (cyclotomic d K) (X ^ d - 1) ((beta : K) ^ r)\n    (cyclotomic.dvd_X_pow_sub_one d K)\n  simp only [eval_sub, eval_pow, eval_X, eval_one]\n  exact isUnit_iff_ne_zero.mpr (prime_order_binomial_ne_zero beta hR hr hrR hd hdR)\n\nend RiemannGaussian.SemiprimeSignedMomentAcquisitionObstruction\n","RiemannGaussian.SemiprimeSourceArrayGeneratedBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceArrayProgramBits\nimport RiemannGaussian.SemiprimeSourceArrayProgramGeneration\n\n/-! # One acquired source-code generator joined to physical execution and readout\nThe generator runs once, and its returned bank, cached code size and constant-size\noutput descriptor are used directly. The retained scalar ledger includes actual\nsyntax traversal, constant lookup, append copying, address generation and final\noutput-ID acquisition. Native scalar metadata remains distinct from primitive\nBoolean interpreter work.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1400000\nnamespace RiemannGaussian.SemiprimeSourceArrayGeneratedBits\nopen SemiprimeRationalBits SemiprimeSourceArrayProgramAcquisition\nopen SemiprimeSourceArrayProgramCompiler SemiprimeSourceArrayProgramLowering\nopen SemiprimeSourceArrayProgramGeneration\nopen OAI.Algorithms.SubexponentialSAT.SubexpRowInterpolation\n\n/-- The actual returned code is exactly the verified original compiler program. -/\ntheorem generated_code (J : ℕ) (p : PolynomialCode ℚ) :\n    (generate J p).result.compiled.code=(program J p).code :=\n  congrArg Block.code (generate_block J p)\n\n/-- Cached allocation size is the actual verified code length. -/\ntheorem generated_size (J : ℕ) (p : PolynomialCode ℚ) :\n    (generate J p).result.compiled.size=(program J p).code.length := by\n  rw [(generate J p).result.compiled.size_eq,generated_code]\n\n/-- Actual constant-size output descriptors have the original stable-register meaning. -/\ntheorem generated_output (J : ℕ) (p : PolynomialCode ℚ) (k : ℕ) :\n    (generate J p).result.shape.value k=(program J p).output k :=\n  congrArg (fun b : Block => b.output k) (generate_block J p)\n\n/-- Generate ONCE, encode its acquired bank, execute its code and read the actual output ID. -/\ndef coefficient (bits J : ℕ) (p : PolynomialCode ℚ) (k : ℕ) :\n    SemiprimeSourceArrayProgramBits.CoefficientRun :=\n  let generated := generate J p\n  let initial := generated.bank.length\n  let final := initial+generated.result.compiled.size\n  let B := final+1\n  let inputs := acquireBank bits generated.bank\n  let instructions := lower initial B initial generated.result.compiled.code\n  let result := SemiprimeSourceProgramBits.run (List.replicate (bits+1) false)\n    instructions.code inputs.words\n  let id := generated.result.shape.read k\n  let out := readout initial final B id.value result.memory\n  ⟨out.word,generated.work+inputs.scalarWork+instructions.work+id.work+out.scalarWork+\n    2*(bits+1)+initial+20,result.clock+out.bitWork+2⟩\n\n/-- Code-generation caching changes no physical output bit. -/\ntheorem coefficient_word (bits J : ℕ) (p : PolynomialCode ℚ) (k : ℕ) :\n    (coefficient bits J p k).word=(SemiprimeSourceArrayProgramBits.coefficient bits J p k).word := by\n  simp only [coefficient,generate_bank,generated_size,generated_code,Shape.read_value,generated_output,\n    SemiprimeSourceArrayProgramBits.coefficient,SemiprimeSourceArrayProgramBits.execute,\n    SemiprimeSourceArrayProgramBits.frontier]\n\n/-- The joined code generator retains precisely the same actual Boolean backend execution. -/\ntheorem coefficient_bitWork (bits J : ℕ) (p : PolynomialCode ℚ) (k : ℕ) :\n    (coefficient bits J p k).bitWork=(SemiprimeSourceArrayProgramBits.coefficient bits J p k).bitWork := by\n  simp only [coefficient,generate_bank,generated_size,generated_code,Shape.read_value,generated_output,\n    SemiprimeSourceArrayProgramBits.coefficient,SemiprimeSourceArrayProgramBits.execute,\n    SemiprimeSourceArrayProgramBits.frontier]\n\n/-- The scalar ledger pays generated code, output descriptor lookup and bank traversal as well. -/\ntheorem coefficient_acquisitionWork (bits J : ℕ) (p : PolynomialCode ℚ) (k : ℕ) :\n    (coefficient bits J p k).acquisitionWork ≤\n      (generate J p).work+(SemiprimeSourceArrayProgramBits.coefficient bits J p k).acquisitionWork+\n        (bank p).length+20 := by\n  have hid := (generate J p).result.shape.read_work k\n  simp only [coefficient,generate_bank,generated_size,generated_code,Shape.read_value,generated_output,\n    SemiprimeSourceArrayProgramBits.coefficient,SemiprimeSourceArrayProgramBits.execute,\n    SemiprimeSourceArrayProgramBits.frontier]\n  omega\n\n/-- Join generated-code acquisition with both retained coefficient backend ledgers. -/\ntheorem coefficient_totalWork (bits J : ℕ) (p : PolynomialCode ℚ) (k : ℕ) :\n    (coefficient bits J p k).acquisitionWork+(coefficient bits J p k).bitWork ≤\n      (generate J p).work+\n        ((SemiprimeSourceArrayProgramBits.coefficient bits J p k).acquisitionWork+\n          (SemiprimeSourceArrayProgramBits.coefficient bits J p k).bitWork)+(bank p).length+20 := by\n  have ha := coefficient_acquisitionWork bits J p k\n  rw [coefficient_bitWork]\n  omega\n\n/-- Original-data bank and instruction-fit proofs now apply to the generated runtime itself. -/\ntheorem coefficient_correct (bits J : ℕ) (p : PolynomialCode ℚ) (k : ℕ) (hk : k < J)\n    (hb : ∀ q∈bank p,q.num.natAbs ≤ 2^bits ∧ q.den ≤ 2^bits)\n    (hs : Safe (bits+1) (program J p).code (bank p).length (initialEnv p)) :\n    (coefficient bits J p k).word.value=\n      SemiprimeJetArray.coefficient (SemiprimeSourceCodeArrays.compile J p).coefficients k ∧\n      (coefficient bits J p k).word.Valid ∧ Width (coefficient bits J p k).word (bits+1) := by\n  rw [coefficient_word]\n  exact SemiprimeSourceArrayProgramBits.coefficient_correct bits J p k hk hb hs\n\nend RiemannGaussian.SemiprimeSourceArrayGeneratedBits\n","RiemannGaussian.SemiprimeSourceHeadCountBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceCountPowers\nimport RiemannGaussian.SemiprimeSourceHeadCountFormula\nimport RiemannGaussian.SemiprimeSourceWordIdPredicateBounds\n\n/-! # Closed-form physical padded head-collision counter\nOnly actual cached Boolean powers are copied. The one fixed/fixed test uses the\nactual acquired-bank predicate. Native descriptor equality and membership scans\nretain their explicit metadata-stage ledger, not a whole primitive-bit claim.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHeadCountBits\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\nopen SemiprimeMaterializedWords SemiprimeSourceOffsetInputsCore SemiprimeBitArithmetic\nopen SemiprimeSourceCountPowers (Powers)\nopen SemiprimeSourceWordBank (Bank)\nopen SemiprimeSourceWordIdEnvironment (Env Rel)\n\n/-- Execute the physical head-count shortcut with cached original power payloads.\nThe cache acquisition work belongs to the once-per-caller initializer. -/\ndef count (bank : Bank) (env : Env) (powers : Powers) {Q : ℕ} (q : Fin Q)\n    (a b : ℕ) (remaining : List ℕ) : NatRun :=\n  if a=b then\n    let out := SemiprimeSourceChoiceBits.copyID powers.fourth\n    ⟨out.value,out.work+3⟩\n  else\n    let ma := memberRun a remaining\n    let mb := memberRun b remaining\n    if ma.value || mb.value then\n      let out := SemiprimeSourceChoiceBits.copyID powers.head\n      ⟨out.value,ma.work+mb.work+out.work+5⟩\n    else\n      let truth := SemiprimeSourceWordIdPredicate.terminal bank env (.head q a b)\n      if truth.value then\n        let out := SemiprimeSourceChoiceBits.copyID powers.fourth\n        ⟨out.value,ma.work+mb.work+truth.work+out.work+7⟩\n      else ⟨[],ma.work+mb.work+truth.work+5⟩\n\n/-- Exact branch payloads; no numerical count is encoded or supplied. -/\ntheorem count_bits (bank : Bank) (env : Env) (powers : Powers) {Q : ℕ} (q : Fin Q)\n    (a b : ℕ) (remaining : List ℕ) :\n    (count bank env powers q a b remaining).bits=\n      if a=b then powers.fourth else if a∈remaining ∨ b∈remaining then powers.head\n      else if (SemiprimeSourceWordIdPredicate.terminal bank env (.head q a b)).value then powers.fourth else [] := by\n  by_cases hab : a=b\n  · simp [count,hab,SemiprimeSourceChoiceBits.copyID_value]\n  · by_cases ha : a∈remaining <;> by_cases hb : b∈remaining <;>\n      simp [count,hab,ha,hb,memberRun_value,SemiprimeSourceChoiceBits.copyID_value]\n    split_ifs <;> rfl\n\n/-- Structural output width covers every branch, independent of truth or count value. -/\ntheorem count_length (bank : Bank) (env : Env) (powers : Powers) {Q : ℕ} (q : Fin Q)\n    (a b : ℕ) (remaining : List ℕ) :\n    (count bank env powers q a b remaining).bits.length ≤\n      max powers.fourth.length powers.head.length := by\n  rw [count_bits]\n  split_ifs <;> simp\n\n/-- Actual original cache acquisition supplies all output widths internally. -/\ntheorem acquired_length (r Q : ℕ) (env : Env) (q : Fin Q) (a b : ℕ) (remaining : List ℕ) :\n    (count (SemiprimeSourceWordBank.acquire r Q) env (SemiprimeSourceCountPowers.acquire r Q)\n      q a b remaining).bits.length ≤ SemiprimeSourceCountPowers.width r Q := by\n  apply (count_length _ _ _ q a b remaining).trans\n  exact max_le (SemiprimeSourceCountPowers.acquire_length r Q).2.2.1\n    (SemiprimeSourceCountPowers.acquire_length r Q).2.2.2\n\n/-- The optimized physical count equals the ACTUAL original padded head counter.\nThe original bank and power cache are concretely acquired, with no count/Fits advice. -/\ntheorem count_original (r Q : ℕ) [NeZero r] (env : Env)\n    (original : SemiprimeMaterializedScoreEnvironment.Environment r Q)\n    (q : Fin Q) (a b : ℕ) (remaining : List ℕ) (hn : remaining.Nodup)\n    (he : Rel (SemiprimeSourceWordBank.acquire r Q).ids\n      (SemiprimeSourceWordBankSemantics.decode r Q) env original) :\n    bitValue (count (SemiprimeSourceWordBank.acquire r Q) env\n      (SemiprimeSourceCountPowers.acquire r Q) q a b remaining).bits=\n      (SemiprimeSourceScoreCountsPadding.paddedLocal (SemiprimeFiniteEnumerations.words r Q).values\n        (.head q a b) remaining original).value := by\n  have ht := SemiprimeSourceWordIdPredicate.terminal_rel r Q env original (.head q a b) he\n  change (SemiprimeSourceWordIdPredicate.terminal (SemiprimeSourceWordBank.acquire r Q) env\n    (.head q a b)).value=decide (SemiprimeMaterializedScoreEnvironment.denote original a q=\n      SemiprimeMaterializedScoreEnvironment.denote original b q) at ht\n  have hp := SemiprimeSourceCountPowers.acquire_value r Q\n  have hfourth : bitValue (SemiprimeSourceCountPowers.acquire r Q).fourth=(r^Q)^4 := by\n    rw [hp.2.2.1,←pow_mul]\n    congr 1\n    omega\n  rw [count_bits,SemiprimeSourceHeadCountFormula.head_padded_original r Q q a b remaining original hn]\n  by_cases hab : a=b\n  · simp only [hab,ite_true,hfourth]\n  · by_cases hactive : a∈remaining ∨ b∈remaining\n    · simp only [hab,ite_false,hactive,ite_true,hp.2.2.2]\n    · simp only [hab,ite_false,hactive,ht]\n      by_cases h : SemiprimeMaterializedScoreEnvironment.denote original a q=\n          SemiprimeMaterializedScoreEnvironment.denote original b q\n      · simp [h,hfourth]\n      · simp [h,bitValue]\n\nend RiemannGaussian.SemiprimeSourceHeadCountBits\n","RiemannGaussian.SemiprimeSourceHeadCountBitsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHeadCountBits\n\n/-! # Original-metadata work of the closed-form physical head counter\nThere is no completion enumeration or unary count padding. The fixed/fixed\nbranch pays its concrete original-bank head predicate; cached powers are copied.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHeadCountBitsBounds\nopen SemiprimeSourceHeadCountBits SemiprimeSourceOffsetInputsCore SemiprimeMaterializedWords\nopen SemiprimeSourceCountPowers (Powers)\nopen SemiprimeSourceWordBank (Bank)\nopen SemiprimeSourceWordIdEnvironment (Env ValidIds)\nopen SemiprimeSourceWordIdEnvironmentBounds (KeysBound)\nopen SemiprimeReportPolynomialGrowth\n\n/-- Every actual branch retains scans, payload copies and any physical truth report. -/\ntheorem count_clock (bank : Bank) (env : Env) (powers : Powers) {Q : ℕ} (q : Fin Q)\n    (a b : ℕ) (remaining : List ℕ) :\n    (count bank env powers q a b remaining).clock  ≤ \n      4*remaining.length+4*max powers.fourth.length powers.head.length+\n        (SemiprimeSourceWordIdPredicate.terminal bank env (.head q a b)).work+20 := by\n  have hm := memberRun_work a remaining\n  have hn := memberRun_work b remaining\n  have hf := SemiprimeSourceChoiceBits.copyID_work powers.fourth\n  have hh := SemiprimeSourceChoiceBits.copyID_work powers.head\n  have hfl := le_max_left powers.fourth.length powers.head.length\n  have hhl := le_max_right powers.fourth.length powers.head.length\n  unfold count\n  split\n  · dsimp only\n    omega\n  · dsimp only\n    split\n    · dsimp only\n      omega\n    · split <;> dsimp only <;> omega\n\n/-- Closed head-callback work from original bank/cache/finite metadata dimensions. -/\ndef budget (r Q L N s : ℕ) : ℕ :=\n  4*N+4*SemiprimeSourceCountPowers.width r Q+\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget r Q L N s+20\n\n/-- Original acquired powers and bank discharge all physical value/width/callback\nconditions. The remaining hypotheses are literal original finite metadata bounds. -/\ntheorem count_original_clock (r Q : ℕ) [NeZero r] (env : Env) (q : Fin Q)\n    (a b : ℕ) (remaining : List ℕ) (N s : ℕ)\n    (he : ValidIds (SemiprimeSourceWordBank.acquire r Q).ids env)\n    (hf : env.fixedIDs.length ≤ N) (ho : env.overrides.length ≤ s) (hk : KeysBound (N+1) env)\n    (hn : remaining.length ≤ N) (ha : a ≤ N) (hb : b ≤ N) :\n    (count (SemiprimeSourceWordBank.acquire r Q) env (SemiprimeSourceCountPowers.acquire r Q)\n      q a b remaining).clock ≤ budget r Q (r^Q) N s := by\n  have hc := count_clock (SemiprimeSourceWordBank.acquire r Q) env\n    (SemiprimeSourceCountPowers.acquire r Q) q a b remaining\n  have hl := SemiprimeSourceCountPowers.acquire_length r Q\n  have hm : max (SemiprimeSourceCountPowers.acquire r Q).fourth.length\n      (SemiprimeSourceCountPowers.acquire r Q).head.length ≤ SemiprimeSourceCountPowers.width r Q :=\n    max_le hl.2.2.1 hl.2.2.2\n  have ht := SemiprimeSourceWordIdPredicateBounds.terminal_work r Q env (.head q a b) N s\n    he hf ho hk (by\n      intro i hi\n      simp only [SemiprimeMaterializedScoreEnvironment.support,List.mem_cons,List.not_mem_nil,or_false] at hi\n      rcases hi with rfl|rfl <;> assumption)\n  unfold budget\n  omega\n\n/-- Componentwise resource monotonicity, isolated from all actual source expressions. -/\ntheorem budget_mono {r Q L N s r' Q' L' N' s' : ℕ}\n    (hr : r ≤ r') (hQ : Q ≤ Q') (hL : L ≤ L') (hN : N ≤ N') (hs : s ≤ s') :\n    budget r Q L N s ≤ budget r' Q' L' N' s' := by\n  unfold budget SemiprimeSourceCountPowers.width\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget\n    SemiprimeSourceWordIdPredicateBounds.programBudget\n    SemiprimeSourceWordIdPredicateBounds.terminalStepBudget\n    SemiprimeSourceWordIdPredicateBounds.bankReadBudget\n    SemiprimeSourceWordIdPredicateBounds.colourReadBudget\n    SemiprimeSourceWordIdEnvironmentBounds.readBudget\n    SemiprimeSourceWordIdEnvironmentBounds.scanStep\n    SemiprimeSourceWordIdEnvironmentBounds.keyBudget\n    SemiprimeSourceWordIdEnvironmentBounds.idCopyBudget\n    SemiprimeSourceWordIdEnvironmentBounds.eqBudget\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget\n    SemiprimeSourceScorePredicateBitsBounds.equalityBudget\n  gcongr\n\n/-- Fixed monomial growth counts materialized L explicitly, never a unary L^4 loop. -/\ntheorem budget_monomial : ∃ C k : ℕ,∀ S,budget S S S S S ≤ C*(S+1)^k := by\n  change Bound (fun S => budget S S S S S)\n  simp only [budget,SemiprimeSourceCountPowers.width,\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget,\n    SemiprimeSourceWordIdPredicateBounds.programBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalStepBudget,\n    SemiprimeSourceWordIdPredicateBounds.bankReadBudget,\n    SemiprimeSourceWordIdPredicateBounds.colourReadBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.readBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.scanStep,\n    SemiprimeSourceWordIdEnvironmentBounds.keyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.idCopyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.eqBudget,\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget,\n    SemiprimeSourceScorePredicateBitsBounds.equalityBudget]\n  boundArithmetic\n\nend RiemannGaussian.SemiprimeSourceHeadCountBitsBounds\n","RiemannGaussian.SemiprimeSourceHeadCountFormula":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHeadFibres\nimport RiemannGaussian.SemiprimeSourceScoreCountsPadding\nimport RiemannGaussian.SemiprimeFiniteEnumerations\n\n/-! # Exact original padded head counts for every environment and prefix\nThe final theorem simplifies the original ordered recursive evaluator, not an\nassumed uniform oracle. Arbitrary typed defaults/fixed words/overrides are allowed.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHeadCountFormula\nopen scoped BigOperators\nopen RiemannGaussian\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\nopen SemiprimeMaterializedWords SemiprimeMaterializedScoreEnvironment\nopen SemiprimeSourceScoreCounts\n\n/-- The actual canonical complete source-word menu, with its published order. -/\ndef alphabet (r Q : ℕ) := (SemiprimeFiniteEnumerations.words r Q).values\n\ntheorem alphabet_length (r Q : ℕ) : (alphabet r Q).length=r^Q := by\n  exact SemiprimeFiniteEnumerations.words_length r Q\n\ntheorem alphabet_sum (r Q : ℕ) (f : Word r Q → ℕ) :\n    ((alphabet r Q).map f).sum=∑w,f w := by\n  classical\n  have hu : (alphabet r Q).toFinset=Finset.univ := by\n    ext w\n    simp only [List.mem_toFinset, Finset.mem_univ, iff_true]\n    exact (SemiprimeFiniteEnumerations.words r Q).complete w\n  have hn : (alphabet r Q).Nodup := (SemiprimeFiniteEnumerations.words r Q).nodup\n  rw [← List.sum_toFinset f hn,hu]\n\ntheorem fibre_sum (r Q : ℕ) (q : Fin Q) (c : Fin r) :\n    ((alphabet r Q).map (fun w => if w q=c then 1 else 0)).sum=r^(Q-1) := by\n  classical\n  rw [alphabet_sum]\n  rw [Finset.sum_boole]\n  rw [← Fintype.card_subtype]\n  exact SemiprimeSourceHeadFibres.fibre_card r Q q c\n\ntheorem sum_constant (r Q c : ℕ) :\n    ((alphabet r Q).map (fun _ => c)).sum=r^Q*c := by\n  simp [alphabet_length, List.sum_replicate, List.map_const']\n\ntheorem sum_mul {r Q : ℕ} (xs : List (Word r Q)) (f : Word r Q→ℕ) (c : ℕ) :\n    (xs.map (fun w => f w*c)).sum=(xs.map f).sum*c := by\n  induction xs with\n  | nil => simp\n  | cons x xs ih => simp [ih,add_mul]\n\n\ntheorem empty_head (r Q : ℕ) (q : Fin Q) (a b : ℕ) (env : Environment r Q) :\n    (count (alphabet r Q) (.head q a b) [] env).value=\n      if denote env a q=denote env b q then 1 else 0 := by\n  simp only [count,hit,decide_eq_true_eq]\n  rfl\n\ntheorem singleton_left (r Q : ℕ) (q : Fin Q) (a b : ℕ) (hab : a≠b)\n    (env : Environment r Q) :\n    (count (alphabet r Q) (.head q a b) [a] env).value=r^(Q-1) := by\n  rw [count,sumCount_value]\n  simp only [empty_head]\n  change ((alphabet r Q).map (fun w =>\n    if denote (extend env a w) a q=denote (extend env a w) b q then 1 else 0)).sum=_\n  simp only [denote_extend,Function.update_same,Function.update_noteq (Ne.symm hab)]\n  exact fibre_sum r Q q (denote env b q)\n\ntheorem singleton_right (r Q : ℕ) (q : Fin Q) (a b : ℕ) (hab : a≠b)\n    (env : Environment r Q) :\n    (count (alphabet r Q) (.head q a b) [b] env).value=r^(Q-1) := by\n  rw [count,sumCount_value]\n  simp only [empty_head]\n  change ((alphabet r Q).map (fun w =>\n    if denote (extend env b w) a q=denote (extend env b w) b q then 1 else 0)).sum=_\n  simp only [denote_extend,Function.update_same,Function.update_noteq hab]\n  simpa only [eq_comm] using fibre_sum r Q q (denote env a q)\n\ntheorem pair_left (r Q : ℕ) (q : Fin Q) (a b : ℕ) (hab : a≠b)\n    (env : Environment r Q) :\n    (count (alphabet r Q) (.head q a b) [a,b] env).value=r^Q*r^(Q-1) := by\n  rw [count,sumCount_value]\n  change ((alphabet r Q).map (fun w =>\n    (count (alphabet r Q) (.head q a b) [b] (extend env a w)).value)).sum=_\n  simp_rw [singleton_right r Q q a b hab]\n  exact sum_constant r Q (r^(Q-1))\n\ntheorem pair_right (r Q : ℕ) (q : Fin Q) (a b : ℕ) (hab : a≠b)\n    (env : Environment r Q) :\n    (count (alphabet r Q) (.head q a b) [b,a] env).value=r^Q*r^(Q-1) := by\n  rw [count,sumCount_value]\n  change ((alphabet r Q).map (fun w =>\n    (count (alphabet r Q) (.head q a b) [a] (extend env b w)).value)).sum=_\n  simp_rw [singleton_left r Q q a b hab]\n  exact sum_constant r Q (r^(Q-1))\n\ntheorem self_count (r Q : ℕ) (q : Fin Q) (a : ℕ)\n    (xs : List ℕ) (env : Environment r Q) :\n    (count (alphabet r Q) (.head q a a) xs env).value=(r^Q)^xs.length := by\n  induction xs generalizing env with\n  | nil => simp [empty_head]\n  | cons i xs ih =>\n    rw [count,sumCount_value]\n    change ((alphabet r Q).map (fun w =>\n      (count (alphabet r Q) (.head q a a) xs (extend env i w)).value)).sum=_\n    simp_rw [ih]\n    rw [sum_constant]\n    simp [pow_succ,Nat.mul_comm]\n\n\ntheorem one_shape (b : ℕ) (xs : List ℕ) (hn : xs.Nodup)\n    (hm : ∀ x∈xs,x=b) : xs=[] ∨ xs=[b] := by\n  cases xs with\n  | nil => exact Or.inl rfl\n  | cons x xs =>\n    have hx:=hm x List.mem_cons_self\n    subst x\n    have hnil : xs=[] := by\n      apply List.eq_nil_iff_forall_not_mem.mpr\n      intro y hy\n      have he:=hm y (List.mem_cons_of_mem _ hy)\n      subst y\n      exact (List.nodup_cons.mp hn).1 hy\n    subst xs\n    exact Or.inr rfl\n\ntheorem two_shapes (a b : ℕ) (xs : List ℕ) (hn : xs.Nodup)\n    (hm : ∀ x∈xs,x=a ∨ x=b) :\n    xs=[] ∨ xs=[a] ∨ xs=[b] ∨ xs=[a,b] ∨ xs=[b,a] := by\n  cases xs with\n  | nil => exact Or.inl rfl\n  | cons x xs =>\n    have hx:=hm x List.mem_cons_self\n    rcases hx with rfl|rfl\n    · have ht : ∀ y∈xs,y=b := by\n        intro y hy\n        rcases hm y (List.mem_cons_of_mem _ hy) with he|he\n        · subst y; exact False.elim ((List.nodup_cons.mp hn).1 hy)\n        · exact he\n      rcases one_shape b xs (List.nodup_cons.mp hn).2 ht with rfl|rfl\n      · exact Or.inr (Or.inl rfl)\n      · exact Or.inr (Or.inr (Or.inr (Or.inl rfl)))\n    · have ht : ∀ y∈xs,y=a := by\n        intro y hy\n        rcases hm y (List.mem_cons_of_mem _ hy) with he|he\n        · exact he\n        · subst y; exact False.elim ((List.nodup_cons.mp hn).1 hy)\n      rcases one_shape a xs (List.nodup_cons.mp hn).2 ht with rfl|rfl\n      · exact Or.inr (Or.inr (Or.inl rfl))\n      · exact Or.inr (Or.inr (Or.inr (Or.inr rfl)))\n\n/-- The original paid active-support scan, observed at its returned list. -/\ndef activeHead {Q : ℕ} (q : Fin Q) (a b : ℕ) (remaining : List ℕ) :=\n  (activeRun (support (.head q a b)) remaining).value\n\ntheorem activeHead_mem {Q : ℕ} (q : Fin Q) (a b x : ℕ) (xs : List ℕ) :\n    x∈activeHead q a b xs ↔ x∈xs ∧ (x=a ∨ x=b) := by\n  simp [activeHead,activeRun_value,OAI.Algorithms.SubexponentialSAT.LocalExpectation.active,support]\n\ntheorem activeHead_nodup {Q : ℕ} (q : Fin Q) (a b : ℕ) (xs : List ℕ) (hn : xs.Nodup) :\n    (activeHead q a b xs).Nodup := by\n  unfold activeHead\n  rw [activeRun_value]\n  exact hn.filter _\n\n\ntheorem supported_padded (r Q : ℕ) (q : Fin Q) (a b : ℕ)\n    (xs : List ℕ) (env : Environment r Q) (hn : xs.Nodup)\n    (hm : ∀ x∈xs,x=a ∨ x=b) (hlen : xs.length≤4) :\n    (count (alphabet r Q) (.head q a b) xs env).value*(r^Q)^(4-xs.length)=\n      if a=b then (r^Q)^4 else if a∈xs ∨ b∈xs then r^(4*Q-1)\n      else if denote env a q=denote env b q then (r^Q)^4 else 0 := by\n  by_cases hab : a=b\n  · subst b\n    rw [self_count,←pow_add,Nat.add_sub_of_le hlen]\n    simp\n  · simp only [hab,ite_false]\n    rcases two_shapes a b xs hn hm with h|h|h|h|h\n    · subst xs\n      simp [empty_head]\n    · subst xs\n      simp\n      rw [singleton_left r Q q a b hab, ←pow_mul, ←pow_add]\n      congr 1\n      have := q.isLt\n      omega\n    · subst xs\n      simp\n      rw [singleton_right r Q q a b hab, ←pow_mul, ←pow_add]\n      congr 1\n      have := q.isLt\n      omega\n    · subst xs\n      simp\n      rw [pair_left r Q q a b hab, ←pow_add, ←pow_mul, ←pow_add]\n      congr 1\n      have := q.isLt\n      omega\n    · subst xs\n      simp\n      rw [pair_right r Q q a b hab, ←pow_add, ←pow_mul, ←pow_add]\n      congr 1\n      have := q.isLt\n      omega\n\ntheorem head_padded_original (r Q : ℕ) (q : Fin Q) (a b : ℕ)\n    (remaining : List ℕ) (env : Environment r Q) (hn : remaining.Nodup) :\n    (SemiprimeSourceScoreCountsPadding.paddedLocal (SemiprimeFiniteEnumerations.words r Q).values\n      (.head q a b) remaining env).value=\n      if a=b then (r^Q)^4 else if a∈remaining ∨ b∈remaining then r^(4*Q-1)\n      else if denote env a q=denote env b q then (r^Q)^4 else 0 := by\n  have hlen:=SemiprimeSourceScoreCountsPadding.active_length (.head q a b) remaining hn\n  have h:=supported_padded r Q q a b (activeHead q a b remaining) env\n    (activeHead_nodup q a b remaining hn)\n    (fun x hx => (activeHead_mem q a b x remaining).mp hx |>.2) hlen\n  have ha : a∈activeHead q a b remaining ↔ a∈remaining := by simp [activeHead_mem]\n  have hb : b∈activeHead q a b remaining ↔ b∈remaining := by simp [activeHead_mem]\n  simp only [ha,hb] at h\n  simpa only [SemiprimeSourceScoreCountsPadding.paddedLocal,\n    (SemiprimeSourceScoreCountsPadding.power_spec _ _).1,alphabet,activeHead,\n    SemiprimeFiniteEnumerations.words_length] using h\n\nend RiemannGaussian.SemiprimeSourceHeadCountFormula\n","RiemannGaussian.SemiprimeSourceHistogramOriginalSums":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramGrouping\nimport RiemannGaussian.SemiprimeSourceIncidenceNamespaces\nimport RiemannGaussian.SemiprimeSourceIncidenceHistogram\nimport RiemannGaussian.SemiprimeSourceScoreCountsObjective\n\n/-! # Original compiled score lanes as direct occurrence-pair sums\nThe quadratic original score list appears only in the specification being\nsimplified. The right sides use the original port, vertex and coordinate lists,\nwithout assuming an acquired term list, histogram answer or source-count oracle.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeSourceHistogramOriginalSums\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT\nopen LocalExpectation MulticolorTypes\nopen SemiprimeMaterializedScoreEnvironment SemiprimeSourceScoreCountsPadding\nopen SemiprimeSourceScoreCountsObjective SemiprimeSourceHistogramGrouping\n\n/-- Incidence contribution of an actual descriptor, including literal zero for heads. -/\ndef incidenceValue {r Q : ℕ} (alphabet : List (Word r Q))\n    (remaining : List ℕ) (env : Environment r Q) : ScoreProgram Q→ℕ\n  | .incidence a b c d => (paddedLocal alphabet (.incidence a b c d) remaining env).value\n  | .head _ _ _ => 0\n\n/-- Head contribution of an actual descriptor, including literal zero for incidences. -/\ndef headValue {r Q : ℕ} (alphabet : List (Word r Q))\n    (remaining : List ℕ) (env : Environment r Q) : ScoreProgram Q→ℕ\n  | .incidence _ _ _ _ => 0\n  | .head q a b => (paddedLocal alphabet (.head q a b) remaining env).value\n\n/-- The actual ordered recursive lane is its literal descriptor-list sum. -/\ntheorem evaluate_incidence {r Q : ℕ} (alphabet : List (Word r Q))\n    (programs : List (ScoreProgram Q)) (remaining : List ℕ) (env : Environment r Q) :\n    (evaluateCounts alphabet programs remaining env).value.incidence=\n      (programs.map (incidenceValue alphabet remaining env)).sum := by\n  induction programs with\n  | nil => rfl\n  | cons p ps ih => cases p <;> simp only [evaluateCounts,List.map_cons,List.sum_cons,\n      incidenceValue,ih,Nat.zero_add]\n\n/-- The actual ordered recursive head lane is its literal descriptor-list sum. -/\ntheorem evaluate_head {r Q : ℕ} (alphabet : List (Word r Q))\n    (programs : List (ScoreProgram Q)) (remaining : List ℕ) (env : Environment r Q) :\n    (evaluateCounts alphabet programs remaining env).value.head=\n      (programs.map (headValue alphabet remaining env)).sum := by\n  induction programs with\n  | nil => rfl\n  | cons p ps ih => cases p <;> simp only [evaluateCounts,List.map_cons,List.sum_cons,\n      headValue,ih,Nat.zero_add]\n\n/-- Ordered Cartesian-list aggregation retains duplicate occurrences in both inputs. -/\ntheorem sum_product {A B R : Type*} [AddCommMonoid R] (xs : List A) (ys : List B)\n    (f : A×B→R) :\n    ((xs.product ys).map f).sum=\n      (xs.map (fun a => (ys.map (fun b => f (a,b))).sum)).sum := by\n  simp only [List.product]\n  induction xs with\n  | nil => rfl\n  | cons a xs ih =>\n    simp only [List.flatMap_cons,List.map_append,List.sum_append,List.map_map,\n      Function.comp_def,List.map_cons,List.sum_cons,ih]\n\nvariable {I V E : Type} [DecidableEq V] [DecidableEq E] {r Q : ℕ}\n\n/-- Actual compiled original incidence lane, with no pairwise term-list premise. -/\ntheorem compiled_incidence_sum (owner : I→V) (factor : I→E) (indices : List (V⊕E))\n    (ports : List I) (vertices : List V) (coordinates : List (Fin Q))\n    (alphabet : List (Word r Q)) (remaining : List ℕ) (env : Environment r Q) :\n    (evaluateCounts alphabet\n      (SemiprimeMaterializedSourceWords.compileAll owner factor indices\n        (SemiprimePaidFiniteEnumerations.scores ports vertices coordinates).value).value\n      remaining env).value.incidence=\n    pairs ports (fun i j => (paddedLocal alphabet\n      (.incidence (indexCode indices (.inl (owner i))) (indexCode indices (.inr (factor i)))\n        (indexCode indices (.inl (owner j))) (indexCode indices (.inr (factor j)))) remaining env).value) := by\n  rw [evaluate_incidence,SemiprimeMaterializedSourceWords.compileAll_value,\n    SemiprimePaidFiniteEnumerations.scores_value]\n  simp only [List.map_append,List.sum_append,List.map_map,Function.comp_def,\n    SemiprimeMaterializedSourceWords.descriptor,incidenceValue]\n  simp only [List.map_const',List.sum_replicate,smul_zero,add_zero]\n  exact sum_product (R:=ℕ) ports ports _\n\n/-- Actual compiled original head lane, with the original coordinate/vertex order. -/\ntheorem compiled_head_sum (owner : I→V) (factor : I→E) (indices : List (V⊕E))\n    (ports : List I) (vertices : List V) (coordinates : List (Fin Q))\n    (alphabet : List (Word r Q)) (remaining : List ℕ) (env : Environment r Q) :\n    (evaluateCounts alphabet\n      (SemiprimeMaterializedSourceWords.compileAll owner factor indices\n        (SemiprimePaidFiniteEnumerations.scores ports vertices coordinates).value).value\n      remaining env).value.head=\n    (coordinates.map (fun q => pairs vertices (fun v w => (paddedLocal alphabet\n      (.head q (indexCode indices (.inl v)) (indexCode indices (.inl w))) remaining env).value))).sum := by\n  rw [evaluate_head,SemiprimeMaterializedSourceWords.compileAll_value,\n    SemiprimePaidFiniteEnumerations.scores_value]\n  simp only [List.map_append,List.sum_append,List.map_map,Function.comp_def,\n    SemiprimeMaterializedSourceWords.descriptor,headValue]\n  simp only [List.map_const',List.sum_replicate,smul_zero,zero_add]\n  rw [sum_product]\n  congr 1\n  apply List.map_congr_left\n  intro q _\n  exact sum_product (R:=ℕ) vertices vertices _\n\n\n/-- Casting an actual ordered integer pair sum preserves both list multiplicities. -/\ntheorem cast_pairs {A : Type*} (xs : List A) (f : A→A→ℕ) :\n    ((pairs xs f:ℕ):ℚ)=pairs xs (fun a b => (f a b:ℚ)) := by\n  simp only [pairs,Nat.cast_list_sum,List.map_map,Function.comp_def]\n\n/-- Derived sparse head formula: fixed-colour and free-variable-key buckets.\nEvery bucket is a literal sum over the original occurrence list. -/\ndef headHistogram {V : Type*} (vertices : List V) (key : V→ℕ)\n    (r Q : ℕ) (q : Fin Q) (remaining : List ℕ) (env : Environment r Q) : ℚ :=\n  let colour := fun k => denote env k q\n  let fixed : V→ℚ := fun v => if key v∈remaining then 0 else 1\n  let free : V→ℚ := fun v => if key v∈remaining then 1 else 0\n  let A : ℚ := ((r^Q)^4:ℕ)\n  let B : ℚ := (r^(4*Q-1):ℕ)\n  A*(∑ c∈(vertices.map (fun v => colour (key v))).toFinset,\n      (bucket (fun v => colour (key v)) vertices fixed c)^2)+\n    B*(((vertices.map (fun _ => (1:ℚ))).sum)^2-((vertices.map fixed).sum)^2)+\n    (A-B)*(∑ k∈(vertices.map key).toFinset,(bucket key vertices free k)^2)\n\n/-- All-prefix original padded head-pair sum, with no histogram input or answer. -/\ntheorem head_pairs_histogram {V : Type*} (vertices : List V) (key : V→ℕ)\n    (r Q : ℕ) (q : Fin Q) (remaining : List ℕ) (env : Environment r Q)\n    (hn : remaining.Nodup) :\n    ((pairs vertices (fun v w => (paddedLocal (SemiprimeFiniteEnumerations.words r Q).values\n      (.head q (key v) (key w)) remaining env).value):ℕ):ℚ)=\n      headHistogram vertices key r Q q remaining env := by\n  rw [cast_pairs]\n  have hpoint : (fun v w => ((paddedLocal (SemiprimeFiniteEnumerations.words r Q).values\n      (.head q (key v) (key w)) remaining env).value:ℚ))=\n      (fun v w => if key v=key w then (((r^Q)^4:ℕ):ℚ)\n        else if key v∈remaining ∨ key w∈remaining then ((r^(4*Q-1):ℕ):ℚ)\n        else if denote env (key v) q=denote env (key w) q then (((r^Q)^4:ℕ):ℚ) else 0) := by\n    funext v w\n    rw [SemiprimeSourceHeadCountFormula.head_padded_original r Q q (key v) (key w) remaining env hn]\n    split_ifs <;> rfl\n  rw [hpoint]\n  exact head_prefix_grouping vertices key (fun k => denote env k q)\n    (fun k => k∈remaining) (((r^Q)^4:ℕ):ℚ) ((r^(4*Q-1):ℕ):ℚ)\n\n/-- The actual complete compiled head lane is acquired from vertex/coordinate\nlists alone; no quadratic source-term list occurs on the histogram side. -/\ntheorem compiled_head_histogram (owner : I→V) (factor : I→E) (indices : List (V⊕E))\n    (ports : List I) (vertices : List V) (coordinates : List (Fin Q))\n    (remaining : List ℕ) (env : Environment r Q) (hn : remaining.Nodup) :\n    (((evaluateCounts (SemiprimeFiniteEnumerations.words r Q).values\n      (SemiprimeMaterializedSourceWords.compileAll owner factor indices\n        (SemiprimePaidFiniteEnumerations.scores ports vertices coordinates).value).value\n      remaining env).value.head:ℕ):ℚ)=\n    (coordinates.map (fun q => headHistogram vertices\n      (fun v => indexCode indices (.inl v)) r Q q remaining env)).sum := by\n  rw [compiled_head_sum]\n  simp only [Nat.cast_list_sum,List.map_map,Function.comp_def]\n  congr 1\n  apply List.map_congr_left\n  intro q _\n  exact head_pairs_histogram vertices (fun v => indexCode indices (.inl v)) r Q q remaining env hn\n\n\n/-- Complete original indices discharge every namespace condition; the actual\ncompiled incidence lane is exactly sixteen sparse occurrence histograms. -/\ntheorem compiled_incidence_histogram (owner : I→V) (factor : I→E)\n    (indices : List (V⊕E)) (hc : ∀ z,z∈indices)\n    (ports : List I) (vertices : List V) (coordinates : List (Fin Q))\n    (hr : 0<r) (remaining : List ℕ) (env : Environment r Q) (hn : remaining.Nodup) :\n    (((evaluateCounts (SemiprimeFiniteEnumerations.words r Q).values\n      (SemiprimeMaterializedSourceWords.compileAll owner factor indices\n        (SemiprimePaidFiniteEnumerations.scores ports vertices coordinates).value).value\n      remaining env).value.incidence:ℕ):ℚ)=\n    ((r^Q:ℕ):ℚ)^2*SemiprimeSourceIncidenceHistogram.histogramSum ((r^Q:ℕ):ℚ)\n      ports remaining (denote env)\n      (fun i => indexCode indices (.inl (owner i)))\n      (fun i => indexCode indices (.inr (factor i))) := by\n  rw [compiled_incidence_sum,cast_pairs]\n  exact SemiprimeSourceIncidenceHistogram.original_incidence_pairs ports\n    (fun i => indexCode indices (.inl (owner i)))\n    (fun i => indexCode indices (.inr (factor i))) r Q hr remaining env hn\n    (fun i _ j _ => SemiprimeSourceIncidenceNamespaces.indexCode_cross indices hc (owner i) (factor j))\n\nend RiemannGaussian.SemiprimeSourceHistogramOriginalSums\n","RiemannGaussian.SemiprimeSourceHistogramSquaresBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramSquares\nimport RiemannGaussian.SemiprimeSourceHistogramTrieBounds\n\n/-! # Original-key-list widths, inventory and complete streaming reports\nEvery numeric cap is derived from actual occurrence counts and loop invariants.\nThere is no supplied encoded counter, frequency, output fit or callback clock.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramSquaresBounds\nopen SemiprimeBitArithmetic SemiprimeSourceHistogramSquares\nopen SemiprimeSourceHistogramTrie (Trie)\nopen SemiprimeSourceCompactBits (Compact)\n\n/-- A literal list sum with bounded acquired entries has the actual length cap. -/\ntheorem list_sum_cap {A : Type*} (xs : List A) (f : A → ℕ) (M : ℕ)\n    (hf : ∀a∈xs,f a ≤ M) : (xs.map f).sum ≤ xs.length*M := by\n  induction xs with\n  | nil => simp\n  | cons a xs ih =>\n    have ha := hf a List.mem_cons_self\n    have ht := ih (fun b hb => hf b (List.mem_cons_of_mem a hb))\n    simp only [List.map_cons,List.sum_cons,List.length_cons]\n    nlinarith\n\n/-- The proof-view pair count is also the sum of its acquired occurrence frequencies. -/\ntheorem collisions_counts (keys : List (List Bool)) :\n    collisions keys=(keys.map (fun key => keys.count key)).sum := by\n  have hr (key : List Bool) :\n      (keys.map (fun a => if key=a then (1:ℕ) else 0)).sum=keys.count key := by\n    simpa only [eq_comm] using row_count keys key\n  unfold collisions SemiprimeSourceHistogramGrouping.pairs\n  simp_rw [hr]\n\n/-- Actual accumulated collision count never exceeds the original occurrence square. -/\ntheorem collisions_le (keys : List (List Bool)) : collisions keys ≤ keys.length^2 := by\n  rw [collisions_counts,pow_two]\n  exact list_sum_cap keys (fun key => keys.count key) keys.length (fun _ _ => List.count_le_length)\n\n/-- Every final dictionary counter has intrinsic logarithmic physical width. -/\ntheorem frequency_width (keys : List (List Bool)) (key : List Bool) :\n    (SemiprimeSourceHistogramTrie.stored (acquire keys).trie key).length ≤\n      Nat.clog 2 (keys.length+1) := by\n  apply SemiprimeSourceHistogramTrieBounds.stored_length _ key keys.length\n    (acquire_good keys).2.2.1\n  rw [(acquire_good keys).1 key]\n  exact List.count_le_length\n\n/-- The actual total output has logarithmic width in the original pair cap. -/\ntheorem square_width (keys : List (List Bool)) :\n    (acquire keys).bits.length ≤ Nat.clog 2 (keys.length^2+1) := by\n  apply SemiprimeSourceCompactBits.compact_length_of_lt _ (acquire_good keys).2.2.2\n  rw [acquire_value]\n  have hc := collisions_le keys\n  have hp := Nat.le_pow_clog (by decide : 1<(2:ℕ)) (keys.length^2+1)\n  omega\n\n/-- Common logarithmic arithmetic width including the doubled old counter. -/\ndef width (M : ℕ) : ℕ := Nat.clog 2 ((M+1)^2+1)+2\n\n/-- Its numerical envelope follows the original length, not an advised word. -/\ntheorem width_envelope (M : ℕ) : (M+1)^2+1 ≤ 2^(width M) := by\n  apply (Nat.le_pow_clog (by decide : 1<(2:ℕ)) ((M+1)^2+1)).trans\n  apply Nat.pow_le_pow_right (by decide : 0<(2:ℕ))\n  unfold width\n  omega\n\n/-- Every actual current stored frequency fits the internally selected common width. -/\ntheorem good_stored_width (processed : List (List Bool)) (state : State) (M : ℕ)\n    (hs : Good processed state) (hlen : processed.length ≤ M) (key : List Bool) :\n    (SemiprimeSourceHistogramTrie.stored state.trie key).length ≤ width M := by\n  apply SemiprimeSourceCompactBits.compact_length_of_lt _ (hs.2.2.1 key)\n  have hc : SemiprimeSourceHistogramTrie.value state.trie key ≤ M :=\n    (hs.1 key ▸ List.count_le_length).trans hlen\n  have hp := width_envelope M\n  change bitValue (SemiprimeSourceHistogramTrie.stored state.trie key) ≤ M at hc\n  nlinarith\n\n/-- Every actual accumulated prefix fits the same original-length envelope. -/\ntheorem good_total_width (processed : List (List Bool)) (state : State) (M : ℕ)\n    (hs : Good processed state) (hlen : processed.length ≤ M) : state.bits.length ≤ width M := by\n  apply SemiprimeSourceCompactBits.compact_length_of_lt _ hs.2.2.2\n  have hc : bitValue state.bits ≤ M^2 := by\n    rw [hs.2.1]\n    exact (collisions_le processed).trans (Nat.pow_le_pow_left hlen 2)\n  have hp := width_envelope M\n  nlinarith\n\n/-- Single-step budget is linear in actual key width and logarithmic tally width. -/\ndef stepBudget (B M : ℕ) : ℕ := 100*(B+width M+2)+100\n\n/-- Complete executed update work from the proven actual prefix invariant. -/\ntheorem step_clock (processed : List (List Bool)) (state : State) (key : List Bool) (B M : ℕ)\n    (hs : Good processed state) (hlen : processed.length ≤ M) (hk : key.length ≤ B) :\n    (step state key).clock ≤ state.clock+stepBudget B M := by\n  have hW : 1 ≤ width M := by unfold width;omega\n  have hold := good_stored_width processed state M hs hlen key\n  have htotal := good_total_width processed state M hs hlen\n  have hBump := SemiprimeSourceHistogramTrieBounds.bump_clock state.trie key (width M) hW hold\n  have hOld : (SemiprimeSourceHistogramTrie.bump state.trie key).old.length ≤ width M := by\n    rw [SemiprimeSourceHistogramTrie.bump_old]\n    exact hold\n  have hi := SemiprimeSourceCompactBits.increment_clock\n    (false::(SemiprimeSourceHistogramTrie.bump state.trie key).old) (width M+1)\n    (by omega) (by simp only [List.length_cons];omega)\n  have hterm : (SemiprimeSourceCompactBits.increment\n      (false::(SemiprimeSourceHistogramTrie.bump state.trie key).old)).bits.length ≤ width M := by\n    apply SemiprimeSourceCompactBits.compact_length_of_lt _\n      (SemiprimeSourceCompactBits.increment_compact _)\n    rw [SemiprimeSourceCompactBits.increment_value,SemiprimeSourceHistogramTrie.bump_old]\n    have hcount : SemiprimeSourceHistogramTrie.value state.trie key ≤ M := by\n      rw [hs.1 key]\n      exact List.count_le_length.trans hlen\n    have hp := width_envelope M\n    change bitValue (SemiprimeSourceHistogramTrie.stored state.trie key) ≤ M at hcount\n    simp only [bitValue,bitNat,Bool.false_eq_true,ite_false]\n    nlinarith\n  have ha := SemiprimeSourceCompactBits.add_clock state.bits\n    (SemiprimeSourceCompactBits.increment\n      (false::(SemiprimeSourceHistogramTrie.bump state.trie key).old)).bits (width M) htotal hterm\n  unfold step stepBudget\n  dsimp only\n  omega\n\n/-- Final bound retains every step and loop branch, with no final bin scan. -/\ndef budget (B M : ℕ) : ℕ := M*(stepBudget B M+3)+2\n\n/-- Actual remaining-key recursion preserves a fixed original-prefix cap. -/\ntheorem fold_clock (keys processed : List (List Bool)) (state : State) (B M : ℕ)\n    (hs : Good processed state) (hlen : processed.length+keys.length ≤ M)\n    (hk : ∀key∈keys,key.length ≤ B) :\n    (fold keys state).clock ≤ state.clock+keys.length*(stepBudget B M+3)+1 := by\n  induction keys generalizing processed state with\n  | nil => simp [fold]\n  | cons key keys ih =>\n    have hkey := hk key List.mem_cons_self\n    have hstep := step_clock processed state key B M hs (by simp only [List.length_cons] at hlen;omega) hkey\n    have hnext := step_good processed state key hs\n    have hlen' : (processed++[key]).length+keys.length ≤ M := by\n      simp only [List.length_append,List.length_cons,List.length_nil] at hlen ⊢\n      omega\n    have hr := ih (processed++[key]) (step state key) hnext hlen'\n      (fun k h => hk k (List.mem_cons_of_mem key h))\n    simp only [fold,List.length_cons]\n    nlinarith\n\n/-- Original input length and key widths discharge the entire acquisition clock. -/\ntheorem acquire_clock (keys : List (List Bool)) (B : ℕ)\n    (hk : ∀key∈keys,key.length ≤ B) : (acquire keys).clock ≤ budget B keys.length := by\n  have h := fold_clock keys [] initial B keys.length initial_good (by simp) hk\n  change (fold keys initial).clock ≤ keys.length*(stepBudget B keys.length+3)+2\n  change (fold keys initial).clock ≤ 1+keys.length*(stepBudget B keys.length+3)+1 at h\n  omega\n\n/-- Actual persistent trie nodes grow only on the visited original key path. -/\ntheorem fold_nodes (keys : List (List Bool)) (state : State) :\n    SemiprimeSourceHistogramTrie.nodes (fold keys state).trie ≤\n      SemiprimeSourceHistogramTrie.nodes state.trie+(keys.map (fun key => key.length+1)).sum := by\n  induction keys generalizing state with\n  | nil => simp [fold]\n  | cons key keys ih =>\n    have h := ih (step state key)\n    have hb := SemiprimeSourceHistogramTrie.bump_nodes state.trie key\n    simp only [fold,step,List.map_cons,List.sum_cons] at h ⊢\n    omega\n\n/-- Node inventory of the actual acquired trie is bounded by the original key cells. -/\ntheorem acquire_nodes (keys : List (List Bool)) (B : ℕ)\n    (hk : ∀key∈keys,key.length ≤ B) :\n    SemiprimeSourceHistogramTrie.nodes (acquire keys).trie ≤ keys.length*(B+1) := by\n  have h := fold_nodes keys initial\n  have hb := list_sum_cap keys (fun key => key.length+1) (B+1)\n    (fun key h => Nat.add_le_add_right (hk key h) 1)\n  simp only [initial,SemiprimeSourceHistogramTrie.nodes,Nat.zero_add] at h\n  exact h.trans hb\n\n/-- The internally derived common width is monotone in the original key count. -/\ntheorem width_mono {M M' : ℕ} (h : M ≤ M') : width M ≤ width M' := by\n  unfold width\n  apply Nat.add_le_add_right\n  apply Nat.clog_mono_right 2\n  gcongr\n\n/-- Original key-width/count caps may be enlarged without a resource oracle. -/\ntheorem budget_mono {B M B' M' : ℕ} (hB : B ≤ B') (hM : M ≤ M') :\n    budget B M ≤ budget B' M' := by\n  have hw := width_mono hM\n  unfold budget stepBudget\n  gcongr\n\nend RiemannGaussian.SemiprimeSourceHistogramSquaresBounds\n","RiemannGaussian.SemiprimeSourceInterpolationBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceInterpolationHeight\nimport RiemannGaussian.SemiprimeReportPolynomialGrowth\n\n/-! # Original polynomial binary heights of ALL source interpolation frames\nThe exponential magnitude envelopes remain proof-only. Their binary exponents\nare explicit fixed polynomials in original dimensions, not new resources.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2200000\nnamespace RiemannGaussian.SemiprimeSourceInterpolationBits\nopen scoped BigOperators\nopen SemiprimeReportPolynomialGrowth\nopen OAI.Algorithms.SubexponentialSAT\nopen MulticolorTypes SubexpRowInterpolation\nopen SemiprimeSourceInterpolationHeight SemiprimeSourceCodeArrayHeight\nopen SemiprimeJetArray SemiprimeJetArrayHeight SemiprimeSourceCodeArrays\n\n/-- Binary exponent of the original shared constant denominator. -/\ndef leafDenominatorBits (Q R : ℕ) : ℕ := R+Nat.clog 2 Q*Q\n/-- Binary exponent of all original source constants, including executed parity prescriptions. -/\ndef leafBits (A Q R : ℕ) : ℕ :=\n  leafDenominatorBits Q R+Q+SemiprimeSourceUniversalHeight.entryExponent A Q R+2\n/-- Tree size times original leaf height covers all recursively cached state. -/\ndef stateBits (A Q R : ℕ) : ℕ := (leafBits A Q R+R+7)*nodeCap Q\n/-- Explicit fixed polynomial majorant, with logarithms bounded by ORIGINAL dimensions. -/\ndef polynomial (A Q R : ℕ) : ℕ :=\n  (R+Q*Q+Q+(R*(A+(R+1)+1)+2*R+2*Q)+2+R+7)*(6*Q^2+8*Q+3)\n\n/-- The denominator bound uses Q!, not an unjustified common multiple from mere height. -/\ntheorem leaf_denominator_dyadic (Q R : ℕ) :\n    leafDenominator Q R ≤ 2^leafDenominatorBits Q R := by\n  calc\n    _ ≤ 2^R*2^(Nat.clog 2 Q*Q) := Nat.mul_le_mul\n      (Nat.pow_le_pow_right (by decide) (Nat.sub_le R 1)) (SemiprimeHermiteArrayHeight.factorial_dyadic Q)\n    _ = _ := by rw [← pow_add];rfl\n\n/-- Acquired prescription and integer sample bounds give the original leaf exponent. -/\ntheorem leaf_numerator_dyadic (A Q R : ℕ) : leafNumerator A Q R ≤ 2^leafBits A Q R := by\n  let E := SemiprimeSourceUniversalHeight.entryExponent A Q R\n  have hQ : Q ≤ 2^(Q+E) := (Nat.lt_two_pow_self (n:=Q)).le.trans\n    (Nat.pow_le_pow_right (by decide) (Nat.le_add_right _ _))\n  have hE : 2^E ≤ 2^(Q+E) := Nat.pow_le_pow_right (by decide) (Nat.le_add_left _ _)\n  have hone : 1 ≤ 2^(Q+E) := Nat.one_le_two_pow\n  have hs : Q+2^E+1 ≤ 2^(Q+E+2) := by\n    rw [show Q+E+2=(Q+E)+1+1 by omega,pow_succ,pow_succ]\n    omega\n  calc\n    leafNumerator A Q R ≤ 2^leafDenominatorBits Q R*2^(Q+E+2) :=\n      Nat.mul_le_mul (leaf_denominator_dyadic Q R) hs\n    _ = _ := by rw [← pow_add];congr 1;unfold leafBits;omega\n\n/-- A generic original-data compiler base has a linear binary exponent. -/\ntheorem base_dyadic (J d B b : ℕ) (hd : d ≤ 2^b) (hB : B ≤ 2^b) :\n    base J d B ≤ 2^(b+J+6) := by\n  have hJ : J+2 ≤ 2^(J+2) := (Nat.lt_two_pow_self (n:=J+2)).le\n  have hone : 1 ≤ 2^b := Nat.one_le_two_pow\n  have hs : 2*d+2*B+4 ≤ 2^(b+3) := by\n    rw [show b+3=b+1+1+1 by omega,pow_succ,pow_succ,pow_succ]\n    omega\n  calc\n    base J d B ≤ 2^(J+2)*2^(b+3) := Nat.mul_le_mul hJ hs\n    _ = 2^((J+2)+(b+3))  := by rw [← pow_add]\n    _ ≤ _ := Nat.pow_le_pow_right (by decide) (by omega)\n\n/-- Both shared full-tree magnitudes have an ORIGINAL polynomial-bit bound. -/\ntheorem common_caps_dyadic (A Q R : ℕ) :\n    denominator Q R ≤ 2^stateBits A Q R ∧ numerator A Q R ≤ 2^stateBits A Q R := by\n  have hd : leafDenominator Q R ≤ 2^leafBits A Q R :=\n    (leaf_denominator_dyadic Q R).trans (Nat.pow_le_pow_right (by decide) (by unfold leafBits;omega))\n  have hb := base_dyadic (R+1) (leafDenominator Q R) (leafNumerator A Q R)\n    (leafBits A Q R) hd (leaf_numerator_dyadic A Q R)\n  constructor\n  · calc\n      _ ≤ (2^leafBits A Q R)^nodeCap Q := Nat.pow_le_pow_left hd _\n      _ = 2^(leafBits A Q R*nodeCap Q) := by rw [pow_mul]\n      _ ≤ _ := Nat.pow_le_pow_right (by decide) (by unfold stateBits; nlinarith)\n  · calc\n      _ ≤ (2^(leafBits A Q R+(R+1)+6))^nodeCap Q := Nat.pow_le_pow_left hb _\n      _ = _ := by simp only [← pow_mul,stateBits,Nat.add_assoc]\n\n/-- Any already-proved actual source frame representation gives reduced binary bounds. -/\ntheorem representation_binary_bounds {q : ℚ} (A Q R : ℕ)\n    (hq : Representation q (denominator Q R) (numerator A Q R)) :\n    q.den ≤ 2^stateBits A Q R ∧ q.num.natAbs ≤ 2^stateBits A Q R := by\n  have hr := representation_reduced_bound (denominator_positive Q R) hq\n  have hc := common_caps_dyadic A Q R\n  exact ⟨hr.1.trans hc.1,hr.2.trans hc.2⟩\n\n/-- Binary lengths follow at every actual subtree, not just the completed row. -/\ntheorem subtree_binary_bounds {r Q : ℕ} (A R : ℕ) (a y : UniversalType r Q 1)\n    (p : PolynomialCode ℚ) (hp : Subcode p\n      (SemiprimeSourceInterpolationExecution.code (SemiprimeBinomialExecution.parity A R) a 0 y))\n    (i : ℕ) (hi : i<R+1) :\n    (coefficient (compile (R+1) p).coefficients i).den ≤ 2^stateBits A Q R ∧\n    (coefficient (compile (R+1) p).coefficients i).num.natAbs ≤ 2^stateBits A Q R :=\n  representation_binary_bounds A Q R (code_subtree_bound A R a y p hp i hi)\n\n/-- Every actual cached convolution dot-prefix has the original reduced binary cap. -/\ntheorem dotPrefix_binary_bounds {r Q : ℕ} (A R : ℕ) (a y : UniversalType r Q 1)\n    (p q : PolynomialCode ℚ) (hpq : Subcode (.mul p q)\n      (SemiprimeSourceInterpolationExecution.code (SemiprimeBinomialExecution.parity A R) a 0 y))\n    (n len : ℕ) (hn : n<R+1) (hlen : len ≤ n) :\n    (dotPrefix (compile (R+1) p).coefficients (compile (R+1) q).coefficients (n-1) len).value.den ≤ 2^stateBits A Q R ∧\n    (dotPrefix (compile (R+1) p).coefficients (compile (R+1) q).coefficients (n-1) len).value.num.natAbs ≤ 2^stateBits A Q R :=\n  representation_binary_bounds A Q R (code_dotPrefix_bound A R a y p q hpq n len hn hlen)\n\n/-- Requested binary lengths are bounded directly from the shared original representation. -/\ntheorem representation_bit_lengths {q : ℚ} (A Q R : ℕ)\n    (hq : Representation q (denominator Q R) (numerator A Q R)) :\n    Nat.clog 2 (q.den+1) ≤ stateBits A Q R+1 ∧\n    Nat.clog 2 (q.num.natAbs+1) ≤ stateBits A Q R+1 := by\n  have h := representation_binary_bounds A Q R hq\n  exact ⟨SemiprimeHermiteArrayHeight.clog_two_succ_of_dyadic h.1,\n    SemiprimeHermiteArrayHeight.clog_two_succ_of_dyadic h.2⟩\n\n/-- The explicit bit exponent is a fixed polynomial of original A,Q,R dimensions. -/\ntheorem stateBits_le_polynomial (A Q R : ℕ) : stateBits A Q R ≤ polynomial A Q R := by\n  have hQ := SemiprimeHermiteArrayHeight.clog_two_le_self Q\n  have hR := SemiprimeHermiteArrayHeight.clog_two_le_self (R+1)\n  unfold stateBits leafBits leafDenominatorBits nodeCap SemiprimeSourceUniversalHeight.entryExponent SemiprimeSourceUniversalHeight.coefficientExponent polynomial\n  gcongr\n\n/-- Original dimension bounds preserve the fixed polynomial majorant. -/\ntheorem polynomial_mono {A Q R A' Q' R' : ℕ} (hA : A ≤ A') (hQ : Q ≤ Q') (hR : R ≤ R') :\n    polynomial A Q R ≤ polynomial A' Q' R' := by unfold polynomial;gcongr\n\n/-- Input-independent monomial witnesses describe the original binary-height polynomial. -/\ntheorem polynomial_monomial : SemiprimeReportPolynomialGrowth.Bound (fun S => polynomial S S S) := by\n  unfold polynomial\n  boundArithmetic\n\nend RiemannGaussian.SemiprimeSourceInterpolationBits\n","RiemannGaussian.SemiprimeSourceWordIdControl":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceChoiceOrder\n\n/-! # Actual acquired-menu invariants for the existing Boolean-ID controller\nCorrectness and work contracts are required only for IDs in the acquired menu\nand prefixes made from that menu. This avoids assuming resource bounds on\narbitrary external bit strings. The executed controller is unchanged.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1400000\nnamespace RiemannGaussian.SemiprimeSourceWordIdControl\nopen SemiprimeRationalBits SemiprimeMaterializedWords SemiprimeSourceChoiceBits\n\n/-- Every ID of a stored physical prefix belongs to the actual acquired menu. -/\ndef InMenu (menu xs : List (List Bool)) : Prop := ∀ x∈xs,x∈menu\n\n/-- Extending a prefix by one acquired ID preserves its concrete menu invariant. -/\ntheorem inMenu_cons (menu xs : List (List Bool)) (x : List Bool)\n    (hx : x∈menu) (hxs : InMenu menu xs) : InMenu menu (x::xs) := by\n  intro y hy\n  rcases List.mem_cons.mp hy with rfl | hy\n  · exact hx\n  · exact hxs y hy\n\n/-- Physical choice returns an actual menu entry, regardless of score values. -/\ntheorem choose_inMenu (menu : List (List Bool)) (physical : List Bool → RationalReport)\n    (a : List Bool) (tail : List (List Bool)) (h : InMenu menu (a::tail)) :\n    (SemiprimeSourceChoiceBits.choose physical a tail).value∈menu :=\n  h _ (choose_mem physical a tail)\n\n/-- Every stored output ID is either originally fixed or physically selected from the menu. -/\ntheorem assign_inMenu (menu : List (List Bool)) (a : List Bool) (tail : List (List Bool))\n    (physical : List Bool → List (List Bool) → RationalReport)\n    (tokens : List Bool) (fixed : List (List Bool))\n    (hc : InMenu menu (a::tail)) (hf : InMenu menu fixed) :\n    InMenu menu (SemiprimeSourceChoiceBits.assign a tail physical tokens fixed).value := by\n  induction tokens generalizing fixed with\n  | nil => simpa only [SemiprimeSourceChoiceBits.assign,copyIDs_value] using hf\n  | cons t tokens ih =>\n    simp only [SemiprimeSourceChoiceBits.assign,copyIDs_value]\n    exact ih _ (inMenu_cons menu fixed _ (choose_inMenu menu _ a tail hc) hf)\n\n/-- Order refinement is needed only for actual acquired candidate IDs. -/\ntheorem choose_decode {A : Type} (menu : List (List Bool)) (decode : List Bool → A)\n    (physical : List Bool → RationalReport) (source : A → Run ℚ)\n    (hv : ∀ w∈menu,(physical w).word.Valid)\n    (ho : ∀ v∈menu,∀ w∈menu,(physical v).word.value ≤ (physical w).word.value ↔\n      (source (decode v)).value ≤ (source (decode w)).value)\n    (a : List Bool) (tail : List (List Bool)) (hc : InMenu menu (a::tail)) :\n    decode (SemiprimeSourceChoiceBits.choose physical a tail).value=\n      (SemiprimeMaterializedWords.choose source (decode a) (tail.map decode)).value := by\n  induction tail generalizing a with\n  | nil => simp only [SemiprimeSourceChoiceBits.choose,copyID_value,List.map_nil,\n      SemiprimeMaterializedWords.choose]\n  | cons b bs ih =>\n    have ht : InMenu menu (b::bs) := fun w hw => hc w (List.mem_cons_of_mem a hw)\n    have ha := hc a List.mem_cons_self\n    have hn := choose_inMenu menu physical b bs ht\n    have hh := ho a ha (SemiprimeSourceChoiceBits.choose physical b bs).value hn\n    simp only [SemiprimeSourceChoiceBits.choose,copyID_value,List.map_cons,\n      SemiprimeMaterializedWords.choose]\n    rw [SemiprimeSourceComparisonBits.compare_branch _ _ (hv a ha) (hv _ hn)]\n    simp only [apply_ite,hh,ih b ht]\n    split <;> simp_all\n\n/-- Exact original assignment from concrete valid-menu prefix score refinement. -/\ntheorem assign_decode {A : Type} (menu : List (List Bool)) (decode : List Bool → A)\n    (a : List Bool) (tail : List (List Bool))\n    (physical : List Bool → List (List Bool) → RationalReport)\n    (source : ℕ → List A → Run ℚ)\n    (hv : ∀ ts xs,InMenu menu xs → (physical ts xs).word.Valid)\n    (ho : ∀ ts xs,InMenu menu xs → ∀ v∈menu,∀ w∈menu,\n      (physical ts (v::xs)).word.value ≤ (physical ts (w::xs)).word.value ↔\n        (source ts.length (decode v::xs.map decode)).value ≤\n          (source ts.length (decode w::xs.map decode)).value)\n    (tokens : List Bool) (fixed : List (List Bool))\n    (hc : InMenu menu (a::tail)) (hf : InMenu menu fixed) :\n    (SemiprimeSourceChoiceBits.assign a tail physical tokens fixed).value.map decode=\n      (SemiprimeMaterializedWords.assign (decode a) (tail.map decode) source tokens.length\n        (fixed.map decode)).value := by\n  induction tokens generalizing fixed with\n  | nil => simp only [SemiprimeSourceChoiceBits.assign,copyIDs_value,List.length_nil,\n      SemiprimeMaterializedWords.assign]\n  | cons t tokens ih =>\n    have hnext := choose_inMenu menu (fun w => physical tokens (w::fixed)) a tail hc\n    have hc' := choose_decode menu decode (fun w => physical tokens (w::fixed))\n      (fun w => source tokens.length (w::fixed.map decode))\n      (fun w hw => hv tokens (w::fixed) (inMenu_cons menu fixed w hw hf))\n      (ho tokens fixed hf) a tail hc\n    have ht := ih _ (inMenu_cons menu fixed _ hnext hf)\n    simp only [SemiprimeSourceChoiceBits.assign,copyIDs_value,ht,List.map_cons,hc',\n      List.length_cons,SemiprimeMaterializedWords.assign]\n\n/-- The acquired unary-token wrapper preserves exact labels under reachable-menu contracts. -/\ntheorem run_decode {A : Type} (menu : List (List Bool)) (decode : List Bool → A)\n    (a : List Bool) (tail : List (List Bool))\n    (physical : List Bool → List (List Bool) → RationalReport)\n    (source : ℕ → List A → Run ℚ)\n    (hv : ∀ ts xs,InMenu menu xs → (physical ts xs).word.Valid)\n    (ho : ∀ ts xs,InMenu menu xs → ∀ v∈menu,∀ w∈menu,\n      (physical ts (v::xs)).word.value ≤ (physical ts (w::xs)).word.value ↔\n        (source ts.length (decode v::xs.map decode)).value ≤\n          (source ts.length (decode w::xs.map decode)).value)\n    (n : ℕ) (fixed : List (List Bool)) (hc : InMenu menu (a::tail)) (hf : InMenu menu fixed) :\n    (SemiprimeSourceChoiceBits.run a tail physical n fixed).value.map decode=\n      (SemiprimeMaterializedWords.assign (decode a) (tail.map decode) source n (fixed.map decode)).value := by\n  simpa only [SemiprimeSourceChoiceBits.run,acquireTokens_value,List.length_replicate] using\n    assign_decode menu decode a tail physical source hv ho (List.replicate n false) fixed hc hf\n\n/-- Actual prefix contracts suffice for the controller's full scan/copy/comparison report. -/\ntheorem assign_work (menu : List (List Bool)) (a : List Bool) (tail : List (List Bool))\n    (physical : List Bool → List (List Bool) → RationalReport)\n    (tokens : List Bool) (fixed : List (List Bool)) (F W B N : ℕ)\n    (hm : ∀ x∈menu,x.length ≤ B) (hc : InMenu menu (a::tail)) (hf : InMenu menu fixed)\n    (hs : ∀ ts xs,ts.length+xs.length ≤ N → InMenu menu xs →\n      (physical ts xs).clock ≤ F ∧ Width (physical ts xs).word W)\n    (hlen : tokens.length+fixed.length ≤ N) :\n    (SemiprimeSourceChoiceBits.assign a tail physical tokens fixed).work ≤\n      tokens.length*(tail.length*(2*F+200*(W+1)^2+4*B+5)+4*B+2+N*(4*B+4)+4)+\n        N*(4*B+4)+1 := by\n  induction tokens generalizing fixed with\n  | nil =>\n    have hh := copyIDs_work fixed B (fun x hx => hm x (hf x hx))\n    have hN : fixed.length ≤ N := by simpa using hlen\n    simpa only [SemiprimeSourceChoiceBits.assign,List.length_nil,Nat.zero_mul,Nat.zero_add] using\n      hh.trans (Nat.add_le_add_right (Nat.mul_le_mul_right (4*B+4) hN) 1)\n  | cons t tokens ih =>\n    have hn := choose_inMenu menu (fun w => physical tokens (w::fixed)) a tail hc\n    have hnew := inMenu_cons menu fixed _ hn hf\n    have hchoose := SemiprimeSourceChoiceBits.choose_work (fun w => physical tokens (w::fixed)) a tail F W B\n      (fun w hw => hs tokens (w::fixed)\n        (by simp only [List.length_cons] at hlen ⊢;omega)\n        (inMenu_cons menu fixed w (hc w hw) hf))\n      (fun w hw => hm w (hc w hw))\n    have hp := copyIDs_work ((SemiprimeSourceChoiceBits.choose (fun w => physical tokens (w::fixed)) a tail).value::fixed)\n      B (fun w hw => hm w (hnew w hw))\n    have ht := ih _ hnew (by simp only [List.length_cons] at hlen ⊢;omega)\n    have hfix : fixed.length+1 ≤ N := by simp only [List.length_cons] at hlen;omega\n    have hmul := Nat.mul_le_mul_right (4*B+4) hfix\n    simp only [SemiprimeSourceChoiceBits.assign,copyIDs_value,List.length_cons] at ⊢ hp\n    nlinarith\n\n/-- Token acquisition is included before executing the bounded actual-menu controller. -/\ntheorem run_work (menu : List (List Bool)) (a : List Bool) (tail : List (List Bool))\n    (physical : List Bool → List (List Bool) → RationalReport)\n    (n : ℕ) (fixed : List (List Bool)) (F W B N : ℕ)\n    (hm : ∀ x∈menu,x.length ≤ B) (hc : InMenu menu (a::tail)) (hf : InMenu menu fixed)\n    (hs : ∀ ts xs,ts.length+xs.length ≤ N → InMenu menu xs →\n      (physical ts xs).clock ≤ F ∧ Width (physical ts xs).word W)\n    (hlen : n+fixed.length ≤ N) :\n    (SemiprimeSourceChoiceBits.run a tail physical n fixed).work ≤\n      2*n+3+n*(tail.length*(2*F+200*(W+1)^2+4*B+5)+4*B+2+N*(4*B+4)+4)+\n        N*(4*B+4)+1 := by\n  have h := assign_work menu a tail physical (List.replicate n false) fixed F W B N hm hc hf hs\n    (by simpa only [List.length_replicate] using hlen)\n  simp only [SemiprimeSourceChoiceBits.run,acquireTokens_value,acquireTokens_work]\n  simp only [List.length_replicate] at h\n  omega\n\nend RiemannGaussian.SemiprimeSourceWordIdControl\n","RiemannGaussian.SemiprimeSourceWordMenuOrder":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePaidFiniteEnumerations\n\n/-! # Exact zero-first order of the original canonical word menu\nThis is an ordered-list identity. It permits the acquired head-major bank to\nbe consumed by the original zero-first/filter-tail caller without changing its\ndeterministic tie rule. All word functions in this module are specifications.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeSourceWordMenuOrder\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\n\n/-- The actual canonical head-major list starts with the literal all-zero word. -/\ntheorem words_head_zero (r Q : ℕ) [NeZero r] :\n    ∃ tail,(SemiprimeFiniteEnumerations.words r Q).values=(fun _ => 0)::tail := by\n  induction Q with\n  | zero =>\n    refine ⟨[],?_⟩\n    change [(fun i : Fin 0 => Fin.elim0 i)]=[fun _ => 0]\n    congr 1\n    funext i\n    exact Fin.elim0 i\n  | succ Q ih =>\n    obtain ⟨tail,ht⟩ := ih\n    obtain ⟨r',hr⟩ := Nat.exists_eq_succ_of_ne_zero (NeZero.ne r)\n    subst r\n    change ∃ rest,((List.finRange (r'+1)).product (SemiprimeFiniteEnumerations.words (r'+1) Q).values).map\n      (fun p => (Fin.cons p.1 p.2 : Word (r'+1) (Q+1)))=(fun _ => 0)::rest\n    rw [List.finRange_succ,ht]\n    let rest := ((tail.map (fun w => ((0:Fin (r'+1)),w)))++\n      ((List.finRange r').map Fin.succ).product ((fun _ => (0:Fin (r'+1)))::tail)).map\n        (fun p => (Fin.cons p.1 p.2 : Word (r'+1) (Q+1)))\n    refine ⟨rest,?_⟩\n    change (Fin.cons (0:Fin (r'+1)) (fun _ : Fin Q => 0) : Word (r'+1) (Q+1))::rest=\n      (fun _ => 0)::rest\n    congr 1\n    funext i\n    refine Fin.cases ?_ (fun j => ?_) i\n    · rfl\n    · rfl\n\n/-- Filtering a duplicate-free list's first value leaves its exact ordered tail. -/\ntheorem filter_head {A : Type} [DecidableEq A] (a : A) (tail : List A)\n    (hn : (a::tail).Nodup) :\n    (a::tail).filter (fun x => decide (x ≠ a))=tail := by\n  simp only [List.filter_cons,ne_eq,not_true_eq_false,decide_false,Bool.false_eq_true,ite_false]\n  apply List.filter_eq_self.mpr\n  intro x hx\n  simp only [decide_eq_true_eq]\n  intro heq\n  subst x\n  exact (List.nodup_cons.mp hn).1 hx\n\n/-- The original indexed caller's zero-first/filter-tail list is the full canonical list. -/\ntheorem words_zero_first (r Q : ℕ) [NeZero r] :\n    (SemiprimeFiniteEnumerations.words r Q).values=\n      (fun _ => 0)::(SemiprimeFiniteEnumerations.words r Q).values.filter\n        (fun w => decide (w ≠ fun _ => 0)) := by\n  obtain ⟨tail,ht⟩ := words_head_zero r Q\n  have hn := (SemiprimeFiniteEnumerations.words r Q).nodup\n  rw [ht] at hn ⊢\n  rw [filter_head _ tail hn]\n\n/-- The fully acquired indexed enumeration retains exactly that ordered word menu. -/\ntheorem indexed_menu (n F r Q : ℕ) [NeZero r] (arity : Fin F → ℕ) :\n    (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value.wordFirst::\n      (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value.wordTail=\n        (SemiprimeFiniteEnumerations.words r Q).values := by\n  rw [SemiprimePaidFiniteEnumerations.indexed_value]\n  exact (words_zero_first r Q).symm\n\nend RiemannGaussian.SemiprimeSourceWordMenuOrder\n","RiemannGaussian.SemiprimeWordPacketScheduledController":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeWordPacketPublicController\nimport RiemannGaussian.SemiprimeCachedSourceScheduledExecution\n\n/-!\n# N-only controller calling the word-valued native packet counter\n\nThe only runtime input is N. Actual cached-source queries, floor operations,\nzero-first recovery, and physical operand reconstruction retain their reports.\nThe literal schedule/guard and public enumeration construction still require\ntheir separate setup/physical-bit refinements; no complete bit clock is inferred\nfrom the selected scalar/list/branch ledger below.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeWordPacketScheduledController\nopen SemiprimeWordPacketPublicController SemiprimePublicAcquiredExecution\nopen SemiprimeScheduledFactorExecution\n\n/-- Additional actual branch/report control leaves the acquired result unchanged. -/\ndef bump (r : FactorRun) (n : ℕ) : FactorRun := ⟨r.value,r.queries,r.work+n⟩\n\n/-- Execute the actual finite trial interval, with every tested remainder retained. -/\ndef trialList (N : ℕ) : List ℕ → FactorRun\n  | [] => ⟨none,0,1⟩\n  | p::ps => if 2≤ p ∧ N%p=0 then ⟨some p,0,5⟩ else\n    let tail := trialList N ps\n    ⟨tail.value,0,tail.work+5⟩\n\n/-- Literal finite fallback has the same chosen first divisor as the old algorithm. -/\ntheorem trialList_value (N : ℕ) (xs : List ℕ) :\n    (trialList N xs).value=xs.find? (fun p => decide (2≤ p ∧ N%p=0)) := by\n  induction xs with\n  | nil => rfl\n  | cons p ps ih => by_cases h : 2≤ p ∧ N%p=0 <;> simp [trialList,h,ih]\n\n/-- Every actual finite trial step contributes to the selected-operation report. -/\ntheorem trialList_work (N : ℕ) (xs : List ℕ) : (trialList N xs).work≤5*xs.length+1 := by\n  induction xs with\n  | nil => simp [trialList]\n  | cons p ps ih => by_cases h : 2≤ p ∧ N%p=0 <;>\n      simp [trialList,h,List.length_cons] <;> omega\n\n/-- Explicit ascending finite interval construction, retaining list/loop work. -/\ndef rangeFrom : ℕ → ℕ → SemiprimePaidPrefixController.Run (List ℕ)\n  | 0, _ => ⟨[],1⟩\n  | n+1, start => let tail := rangeFrom n (start+1); ⟨start::tail.value,tail.work+3⟩\n\n/-- The acquired interval is the literal original ascending range. -/\ntheorem rangeFrom_value (n start : ℕ) : (rangeFrom n start).value=List.range' start n := by\n  induction n generalizing start with\n  | zero => rfl\n  | succ n ih => simp only [rangeFrom,ih,List.range'_succ,Nat.add_one]\n\n/-- Each interval cell, successor and recursive step is accounted for. -/\ntheorem rangeFrom_work (n start : ℕ) : (rangeFrom n start).work=3*n+1 := by\n  induction n generalizing start with\n  | zero => rfl\n  | succ n ih => simp only [rangeFrom,ih]; omega\n\n/-- Acquire the actual finite range and retain its full trial scan. -/\ndef trial (N : ℕ) : FactorRun :=\n  let candidates := rangeFrom N 0\n  let result := trialList N candidates.value\n  bump result (candidates.work+1)\n\n/-- Trial range allocation and each tested scalar remainder are included. -/\ntheorem trial_work (N : ℕ) : (trial N).work≤8*N+3 := by\n  have h := trialList_work N (List.range N)\n  simp only [List.length_range] at h\n  simp only [trial,bump,rangeFrom_work,rangeFrom_value,← List.range_eq_range']\n  omega\n\n/-- Exact old fallback output, without a divisor answer input. -/\ntheorem trial_value (N : ℕ) : (trial N).value=trialFactor N :=\n  by simpa only [trial,bump,rangeFrom_value,← List.range_eq_range',trialFactor] using trialList_value N (List.range N)\n\n/-- Entire deterministic factor algorithm. Counter values and all their reports\nare acquired internally, never supplied through a public count callback. -/\ndef run (N : ℕ) : FactorRun :=\n  if hN : 0< N then\n    if hr : 0< groups N then\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      if fastGuard N then\n        bump (SemiprimeWordPacketPublicController.factor N hN (groups N) (points N)\n          (epsilon N) (degree N) (precision N)) 3\n      else bump (trial N) 3\n    else bump (trial N) 2\n  else ⟨none,0,1⟩\n\n/-- EVERY-N exact value equivalence; work reports are NOT identified or discarded. -/\ntheorem run_value (N : ℕ) : (run N).value=SemiprimeCachedSourceScheduledExecution.run N := by\n  by_cases hN : 0< N\n  · by_cases hr : 0< groups N\n    · let _ : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      by_cases hg : fastGuard N\n      · have hQ : 1≤ points N := Nat.le_trans (by decide : 1≤2) hg.2.2.2.1\n        have hAQ := guard_interval N hg\n        have hp := precision_valid N hN (guard_points_pos N hg)\n        simpa only [run,SemiprimeCachedSourceScheduledExecution.run,dite_eq_left hN,\n          dite_eq_left hr,ite_eq_left hg,bump] using\n          SemiprimeWordPacketPublicController.factor_value N hN (groups N) (points N)\n            (epsilon N) (degree N) (precision N) hQ hAQ hp.1 hp.2\n      · simpa only [run,SemiprimeCachedSourceScheduledExecution.run,dite_eq_left hN,\n          dite_eq_left hr,ite_eq_right hg,bump] using trial_value N\n    · simpa only [run,SemiprimeCachedSourceScheduledExecution.run,dite_eq_left hN,dite_eq_right hr,bump] using trial_value N\n  · simp only [run,SemiprimeCachedSourceScheduledExecution.run,dite_eq_right hN]\n\n/-- Every actual returned value is a proper integer factor. -/\ntheorem run_sound (N p : ℕ) (h : (run N).value=some p) : 2≤ p ∧ p< N ∧ p∣N :=\n  SemiprimeCachedSourceScheduledExecution.run_sound N p ((run_value N).symm.trans h)\n\n/-- All-input completeness, including zero, one, primes and perfect squares. -/\ntheorem run_none_iff (N : ℕ) :\n    (run N).value=none ↔ ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [run_value]\n  exact SemiprimeCachedSourceScheduledExecution.run_none_iff N\n\nopen Filter in\n/-- The eventual fast branch actually invokes the word-packet controller. -/\ntheorem eventually_run_nativeBits : ∀ᶠ N : ℕ in atTop,\n    ∃ hN : 0< N, ∃ hg : fastGuard N,\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt (guard_groups_pos N hg)⟩\n      run N=bump (SemiprimeWordPacketPublicController.factor N hN (groups N) (points N)\n        (epsilon N) (degree N) (precision N)) 3 := by\n  filter_upwards [eventually_fastGuard,eventually_gt_atTop 0] with N hg hN\n  exact ⟨hN,hg,by simp only [run,dite_eq_left hN,dite_eq_left (guard_groups_pos N hg),ite_eq_left hg]⟩\n\n/-- Fast-branch aggregate bound: countBudget is a bound on the ACTUAL internal\ncounter report, while all additional prefix/recovery/decoder work is explicit. -/\ntheorem run_fast_work (N : ℕ) (hN : 0< N) (hg : fastGuard N) [NeZero (groups N)] (B : ℕ)\n    (hb : ∀ fixed, fixed.length≤ wireCount N →\n      (SemiprimeWordPacketPublicController.counter N hN (groups N) (points N)\n        (epsilon N) (degree N) (precision N) fixed).work≤ B) :\n    (run N).work≤(wireCount N+1)*\n      (B+wireCount N+3*(wireCount N+1)^2+SemiprimePaidFactorDecoder.budget N (wireCount N)+19) := by\n  have hf := SemiprimeWordPacketPublicController.factor_work N hN (groups N) (points N)\n    (epsilon N) (degree N) (precision N) B hb\n  simp only [run,dite_eq_left hN,dite_eq_left (guard_groups_pos N hg),ite_eq_left hg,bump]\n  nlinarith\n\nend RiemannGaussian.SemiprimeWordPacketScheduledController\n"};
